      Verse(
        verseNumber: 1,
        devanagariText: "\u0936\u094d\u0930\u0940\u0917\u0941\u0930\u0941 \u091a\u0930\u0928 \u0938\u0930\u094b\u091c \u0930\u091c \u0928\u093f\u091c \u092e\u0928\u0941 \u092e\u0941\u0915\u0941\u0930\u0941 \u0938\u0941\u0927\u093e\u0930\u093f \u0964\n\u092c\u0930\u0928\u0909\u0901 \u0930\u0918\u0941\u092c\u0930 \u092c\u093f\u092e\u0932 \u091c\u0938\u0941 \u091c\u094b \u0926\u093e\u092f\u0915\u0941 \u092b\u0932 \u091a\u093e\u0930\u093f \u0965",
        iastText: "\u015br\u012bguru carana sar\u014dja raja nija manu mukuru sudh\u0101ri \u0964\nbaranau\u1e41 raghubara bimala jasu j\u014d d\u0101yaku phala c\u0101ri \u0965",
        meter: "Doha (13-11)",
        transliterations: {"telugu": "\u0c36\u0c4d\u0c30\u0c40\u0c17\u0c41\u0c30\u0c41 \u0c1a\u0c30\u0c28 \u0c38\u0c30\u0c4b\u0c1c \u0c30\u0c1c \u0c28\u0c3f\u0c1c \u0c2e\u0c28\u0c41 \u0c2e\u0c41\u0c15\u0c41\u0c30\u0c41 \u0c38\u0c41\u0c27\u0c3e\u0c30\u0c3f \u0964\n\u0c2c\u0c30\u0c28\u0c09\u0c01 \u0c30\u0c18\u0c41\u0c2c\u0c30 \u0c2c\u0c3f\u0c2e\u0c32 \u0c1c\u0c38\u0c41 \u0c1c\u0c4b \u0c26\u0c3e\u0c2f\u0c15\u0c41 \u0c2b\u0c32 \u0c1a\u0c3e\u0c30\u0c3f \u0965", "tamil": "\u0bb6\u0bcd\u0bb0\u0bc0\u0b95\u0bc1\u0bb0\u0bc1 \u0b9a\u0bb0\u0ba8 \u0bb8\u0bb0\u0bcb\u0b9c \u0bb0\u0b9c \u0ba8\u0bbf\u0b9c \u0bae\u0ba8\u0bc1 \u0bae\u0bc1\u0b95\u0bc1\u0bb0\u0bc1 \u0bb8\u0bc1\u0ba4\u0bbe\u0bb0\u0bbf \u0964\n\u0baa\u0bb0\u0ba8\u0b89\u0901 \u0bb0\u0b95\u0bc1\u0baa\u0bb0 \u0baa\u0bbf\u0bae\u0bb2 \u0b9c\u0bb8\u0bc1 \u0b9c\u0bcb \u0ba4\u0bbe\u0baf\u0b95\u0bc1 \u0baa\u0bb2 \u0b9a\u0bbe\u0bb0\u0bbf \u0965", "kannada": "\u0cb6\u0ccd\u0cb0\u0cc0\u0c97\u0cc1\u0cb0\u0cc1 \u0c9a\u0cb0\u0ca8 \u0cb8\u0cb0\u0ccb\u0c9c \u0cb0\u0c9c \u0ca8\u0cbf\u0c9c \u0cae\u0ca8\u0cc1 \u0cae\u0cc1\u0c95\u0cc1\u0cb0\u0cc1 \u0cb8\u0cc1\u0ca7\u0cbe\u0cb0\u0cbf \u0964\n\u0cac\u0cb0\u0ca8\u0c89\u0c81 \u0cb0\u0c98\u0cc1\u0cac\u0cb0 \u0cac\u0cbf\u0cae\u0cb2 \u0c9c\u0cb8\u0cc1 \u0c9c\u0ccb \u0ca6\u0cbe\u0caf\u0c95\u0cc1 \u0cab\u0cb2 \u0c9a\u0cbe\u0cb0\u0cbf \u0965", "malayalam": "\u0d36\u0d4d\u0d30\u0d40\u0d17\u0d41\u0d30\u0d41 \u0d1a\u0d30\u0d28 \u0d38\u0d30\u0d4b\u0d1c \u0d30\u0d1c \u0d28\u0d3f\u0d1c \u0d2e\u0d28\u0d41 \u0d2e\u0d41\u0d15\u0d41\u0d30\u0d41 \u0d38\u0d41\u0d27\u0d3e\u0d30\u0d3f \u0964\n\u0d2c\u0d30\u0d28\u0d09\u0d01 \u0d30\u0d18\u0d41\u0d2c\u0d30 \u0d2c\u0d3f\u0d2e\u0d32 \u0d1c\u0d38\u0d41 \u0d1c\u0d4b \u0d26\u0d3e\u0d2f\u0d15\u0d41 \u0d2b\u0d32 \u0d1a\u0d3e\u0d30\u0d3f \u0965"},
        draftTranslation: "Having cleansed the mirror of my mind with the dust from the lotus feet of the revered Guru, I narrate the pure renown of Lord Raghubara, which bestows the four fruits of life.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 2,
        devanagariText: "\u092c\u0941\u0926\u094d\u0927\u093f\u0939\u0940\u0928 \u0924\u0928\u0941 \u091c\u093e\u0928\u093f\u0915\u0947 \u0938\u0941\u092e\u093f\u0930\u094c \u092a\u0935\u0928-\u0915\u0941\u092e\u093e\u0930 \u0964\n\u092c\u0932 \u092c\u0941\u0927\u093f \u092c\u093f\u0926\u094d\u092f\u093e \u0926\u0947\u0939\u0941 \u092e\u094b\u0939\u093f\u0902 \u0939\u0930\u0939\u0941 \u0915\u0932\u0947\u0938 \u092c\u093f\u0915\u093e\u0930 \u0965",
        iastText: "buddhih\u012bna tanu j\u0101nik\u0113 sumirau pavana-kum\u0101ra \u0964\nbala budhi bidy\u0101 d\u0113hu mohi\u1e41 harahu kal\u0113sa bik\u0101ra \u0965",
        meter: "Doha (13-11)",
        transliterations: {"telugu": "\u0c2c\u0c41\u0c26\u0c4d\u0c27\u0c3f\u0c39\u0c40\u0c28 \u0c24\u0c28\u0c41 \u0c1c\u0c3e\u0c28\u0c3f\u0c15\u0c47 \u0c38\u0c41\u0c2e\u0c3f\u0c30\u0c4c \u0c2a\u0c35\u0c28-\u0c15\u0c41\u0c2e\u0c3e\u0c30 \u0964\n\u0c2c\u0c32 \u0c2c\u0c41\u0c27\u0c3f \u0c2c\u0c3f\u0c26\u0c4d\u0c2f\u0c3e \u0c26\u0c47\u0c39\u0c41 \u0c2e\u0c4b\u0c39\u0c3f\u0c02 \u0c39\u0c30\u0c39\u0c41 \u0c15\u0c32\u0c47\u0c38 \u0c2c\u0c3f\u0c15\u0c3e\u0c30 \u0965", "tamil": "\u0baa\u0bc1\u0ba4\u0bcd\u0ba4\u0bbf\u0bb9\u0bc0\u0ba8 \u0ba4\u0ba8\u0bc1 \u0b9c\u0bbe\u0ba8\u0bbf\u0b95\u0bc7 \u0bb8\u0bc1\u0bae\u0bbf\u0bb0\u0bcc \u0baa\u0bb5\u0ba8-\u0b95\u0bc1\u0bae\u0bbe\u0bb0 \u0964\n\u0baa\u0bb2 \u0baa\u0bc1\u0ba4\u0bbf \u0baa\u0bbf\u0ba4\u0bcd\u0baf\u0bbe \u0ba4\u0bc7\u0bb9\u0bc1 \u0bae\u0bcb\u0bb9\u0bbf\u0bae\u0bcd \u0bb9\u0bb0\u0bb9\u0bc1 \u0b95\u0bb2\u0bc7\u0bb8 \u0baa\u0bbf\u0b95\u0bbe\u0bb0 \u0965", "kannada": "\u0cac\u0cc1\u0ca6\u0ccd\u0ca7\u0cbf\u0cb9\u0cc0\u0ca8 \u0ca4\u0ca8\u0cc1 \u0c9c\u0cbe\u0ca8\u0cbf\u0c95\u0cc7 \u0cb8\u0cc1\u0cae\u0cbf\u0cb0\u0ccc \u0caa\u0cb5\u0ca8-\u0c95\u0cc1\u0cae\u0cbe\u0cb0 \u0964\n\u0cac\u0cb2 \u0cac\u0cc1\u0ca7\u0cbf \u0cac\u0cbf\u0ca6\u0ccd\u0caf\u0cbe \u0ca6\u0cc7\u0cb9\u0cc1 \u0cae\u0ccb\u0cb9\u0cbf\u0c82 \u0cb9\u0cb0\u0cb9\u0cc1 \u0c95\u0cb2\u0cc7\u0cb8 \u0cac\u0cbf\u0c95\u0cbe\u0cb0 \u0965", "malayalam": "\u0d2c\u0d41\u0d26\u0d4d\u0d27\u0d3f\u0d39\u0d40\u0d28 \u0d24\u0d28\u0d41 \u0d1c\u0d3e\u0d28\u0d3f\u0d15\u0d47 \u0d38\u0d41\u0d2e\u0d3f\u0d30\u0d4c \u0d2a\u0d35\u0d28-\u0d15\u0d41\u0d2e\u0d3e\u0d30 \u0964\n\u0d2c\u0d32 \u0d2c\u0d41\u0d27\u0d3f \u0d2c\u0d3f\u0d26\u0d4d\u0d2f\u0d3e \u0d26\u0d47\u0d39\u0d41 \u0d2e\u0d4b\u0d39\u0d3f\u0d02 \u0d39\u0d30\u0d39\u0d41 \u0d15\u0d32\u0d47\u0d38 \u0d2c\u0d3f\u0d15\u0d3e\u0d30 \u0965"},
        draftTranslation: "Knowing myself to be devoid of wisdom, I contemplate You, O Son of the Wind! Bestow upon me strength, intellect, and spiritual knowledge, and dispel all my afflictions and inner blemishes.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 3,
        devanagariText: "\u091c\u092f \u0939\u0928\u0941\u092e\u093e\u0928 \u091c\u094d\u091e\u093e\u0928 \u0917\u0941\u0928 \u0938\u093e\u0917\u0930 \u0964 \u091c\u092f \u0915\u092a\u0940\u0938 \u0924\u093f\u0939\u0941\u0901 \u0932\u094b\u0915 \u0909\u091c\u093e\u0917\u0930 \u0965 \u0967 \u0965",
        iastText: "jaya hanum\u0101na j\u00f1\u0101na guna s\u0101gara \u0964 jaya kap\u012bsa tihu\u1e41 l\u014dka uj\u0101gara \u0965 1 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c1c\u0c2f \u0c39\u0c28\u0c41\u0c2e\u0c3e\u0c28 \u0c1c\u0c4d\u0c1e\u0c3e\u0c28 \u0c17\u0c41\u0c28 \u0c38\u0c3e\u0c17\u0c30 \u0964 \u0c1c\u0c2f \u0c15\u0c2a\u0c40\u0c38 \u0c24\u0c3f\u0c39\u0c41\u0c01 \u0c32\u0c4b\u0c15 \u0c09\u0c1c\u0c3e\u0c17\u0c30 \u0965 \u0c67 \u0965", "tamil": "\u0b9c\u0baf \u0bb9\u0ba8\u0bc1\u0bae\u0bbe\u0ba8 \u0b9c\u0bcd\u0b9e\u0bbe\u0ba8 \u0b95\u0bc1\u0ba8 \u0bb8\u0bbe\u0b95\u0bb0 \u0964 \u0b9c\u0baf \u0b95\u0baa\u0bc0\u0bb8 \u0ba4\u0bbf\u0bb9\u0bc1\u0901 \u0bb2\u0bcb\u0b95 \u0b89\u0b9c\u0bbe\u0b95\u0bb0 \u0965 \u0be7 \u0965", "kannada": "\u0c9c\u0caf \u0cb9\u0ca8\u0cc1\u0cae\u0cbe\u0ca8 \u0c9c\u0ccd\u0c9e\u0cbe\u0ca8 \u0c97\u0cc1\u0ca8 \u0cb8\u0cbe\u0c97\u0cb0 \u0964 \u0c9c\u0caf \u0c95\u0caa\u0cc0\u0cb8 \u0ca4\u0cbf\u0cb9\u0cc1\u0c81 \u0cb2\u0ccb\u0c95 \u0c89\u0c9c\u0cbe\u0c97\u0cb0 \u0965 \u0ce7 \u0965", "malayalam": "\u0d1c\u0d2f \u0d39\u0d28\u0d41\u0d2e\u0d3e\u0d28 \u0d1c\u0d4d\u0d1e\u0d3e\u0d28 \u0d17\u0d41\u0d28 \u0d38\u0d3e\u0d17\u0d30 \u0964 \u0d1c\u0d2f \u0d15\u0d2a\u0d40\u0d38 \u0d24\u0d3f\u0d39\u0d41\u0d01 \u0d32\u0d4b\u0d15 \u0d09\u0d1c\u0d3e\u0d17\u0d30 \u0965 \u0d67 \u0965"},
        draftTranslation: "Hail, Hanuman, ocean of wisdom and virtues! Hail, lord among monkeys, illuminator of the three worlds!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 4,
        devanagariText: "\u0930\u093e\u092e \u0926\u0942\u0924 \u0905\u0924\u0941\u0932\u093f\u0924 \u092c\u0932 \u0927\u093e\u092e\u093e \u0964 \u0905\u091e\u094d\u091c\u0928\u093f-\u092a\u0941\u0924\u094d\u0930 \u092a\u0935\u0928\u0938\u0941\u0924 \u0928\u093e\u092e\u093e \u0965 \u0968 \u0965",
        iastText: "r\u0101ma d\u016bta atulita bala dh\u0101m\u0101 \u0964 a\u00f1jani-putra pavanasuta n\u0101m\u0101 \u0965 2 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c30\u0c3e\u0c2e \u0c26\u0c42\u0c24 \u0c05\u0c24\u0c41\u0c32\u0c3f\u0c24 \u0c2c\u0c32 \u0c27\u0c3e\u0c2e\u0c3e \u0964 \u0c05\u0c1e\u0c4d\u0c1c\u0c28\u0c3f-\u0c2a\u0c41\u0c24\u0c4d\u0c30 \u0c2a\u0c35\u0c28\u0c38\u0c41\u0c24 \u0c28\u0c3e\u0c2e\u0c3e \u0965 \u0c68 \u0965", "tamil": "\u0bb0\u0bbe\u0bae \u0ba4\u0bc2\u0ba4 \u0b85\u0ba4\u0bc1\u0bb2\u0bbf\u0ba4 \u0baa\u0bb2 \u0ba4\u0bbe\u0bae\u0bbe \u0964 \u0b85\u0b9e\u0bcd\u0b9c\u0ba8\u0bbf-\u0baa\u0bc1\u0ba4\u0bcd\u0bb0 \u0baa\u0bb5\u0ba8\u0bb8\u0bc1\u0ba4 \u0ba8\u0bbe\u0bae\u0bbe \u0965 \u0be8 \u0965", "kannada": "\u0cb0\u0cbe\u0cae \u0ca6\u0cc2\u0ca4 \u0c85\u0ca4\u0cc1\u0cb2\u0cbf\u0ca4 \u0cac\u0cb2 \u0ca7\u0cbe\u0cae\u0cbe \u0964 \u0c85\u0c9e\u0ccd\u0c9c\u0ca8\u0cbf-\u0caa\u0cc1\u0ca4\u0ccd\u0cb0 \u0caa\u0cb5\u0ca8\u0cb8\u0cc1\u0ca4 \u0ca8\u0cbe\u0cae\u0cbe \u0965 \u0ce8 \u0965", "malayalam": "\u0d30\u0d3e\u0d2e \u0d26\u0d42\u0d24 \u0d05\u0d24\u0d41\u0d32\u0d3f\u0d24 \u0d2c\u0d32 \u0d27\u0d3e\u0d2e\u0d3e \u0964 \u0d05\u0d1e\u0d4d\u0d1c\u0d28\u0d3f-\u0d2a\u0d41\u0d24\u0d4d\u0d30 \u0d2a\u0d35\u0d28\u0d38\u0d41\u0d24 \u0d28\u0d3e\u0d2e\u0d3e \u0965 \u0d68 \u0965"},
        draftTranslation: "Messenger of Rama, abode of incomparable strength, son of Anjani, known as the Son of the Wind.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 5,
        devanagariText: "\u092e\u0939\u093e\u092c\u0940\u0930 \u092c\u093f\u0915\u094d\u0930\u092e \u092c\u091c\u0930\u0919\u094d\u0917\u0940 \u0964 \u0915\u0941\u092e\u0924\u093f \u0928\u093f\u0935\u093e\u0930 \u0938\u0941\u092e\u0924\u093f \u0915\u0947 \u0938\u0919\u094d\u0917\u0940 \u0965 \u0969 \u0965",
        iastText: "mah\u0101b\u012bra bikrama bajara\u1e45g\u012b \u0964 kumati niv\u0101ra sumati k\u0113 sa\u1e45g\u012b \u0965 3 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c2e\u0c39\u0c3e\u0c2c\u0c40\u0c30 \u0c2c\u0c3f\u0c15\u0c4d\u0c30\u0c2e \u0c2c\u0c1c\u0c30\u0c19\u0c4d\u0c17\u0c40 \u0964 \u0c15\u0c41\u0c2e\u0c24\u0c3f \u0c28\u0c3f\u0c35\u0c3e\u0c30 \u0c38\u0c41\u0c2e\u0c24\u0c3f \u0c15\u0c47 \u0c38\u0c19\u0c4d\u0c17\u0c40 \u0965 \u0c69 \u0965", "tamil": "\u0bae\u0bb9\u0bbe\u0baa\u0bc0\u0bb0 \u0baa\u0bbf\u0b95\u0bcd\u0bb0\u0bae \u0baa\u0b9c\u0bb0\u0b99\u0bcd\u0b95\u0bc0 \u0964 \u0b95\u0bc1\u0bae\u0ba4\u0bbf \u0ba8\u0bbf\u0bb5\u0bbe\u0bb0 \u0bb8\u0bc1\u0bae\u0ba4\u0bbf \u0b95\u0bc7 \u0bb8\u0b99\u0bcd\u0b95\u0bc0 \u0965 \u0be9 \u0965", "kannada": "\u0cae\u0cb9\u0cbe\u0cac\u0cc0\u0cb0 \u0cac\u0cbf\u0c95\u0ccd\u0cb0\u0cae \u0cac\u0c9c\u0cb0\u0c99\u0ccd\u0c97\u0cc0 \u0964 \u0c95\u0cc1\u0cae\u0ca4\u0cbf \u0ca8\u0cbf\u0cb5\u0cbe\u0cb0 \u0cb8\u0cc1\u0cae\u0ca4\u0cbf \u0c95\u0cc7 \u0cb8\u0c99\u0ccd\u0c97\u0cc0 \u0965 \u0ce9 \u0965", "malayalam": "\u0d2e\u0d39\u0d3e\u0d2c\u0d40\u0d30 \u0d2c\u0d3f\u0d15\u0d4d\u0d30\u0d2e \u0d2c\u0d1c\u0d30\u0d19\u0d4d\u0d17\u0d40 \u0964 \u0d15\u0d41\u0d2e\u0d24\u0d3f \u0d28\u0d3f\u0d35\u0d3e\u0d30 \u0d38\u0d41\u0d2e\u0d24\u0d3f \u0d15\u0d47 \u0d38\u0d19\u0d4d\u0d17\u0d40 \u0965 \u0d69 \u0965"},
        draftTranslation: "Valiant hero of thunderbolt limbs, dispeller of evil thoughts, companion of the wise.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 6,
        devanagariText: "\u0915\u091e\u094d\u091a\u0928 \u092c\u0930\u0928 \u092c\u093f\u0930\u093e\u091c \u0938\u0941\u092c\u0947\u0938\u093e \u0964 \u0915\u093e\u0928\u0928 \u0915\u0941\u0923\u094d\u0921\u0932 \u0915\u0941\u091e\u094d\u091a\u093f\u0924 \u0915\u0947\u0938\u093e \u0965 \u096a \u0965",
        iastText: "ka\u00f1cana barana bir\u0101ja sub\u0113s\u0101 \u0964 k\u0101nana ku\u1e47\u1e0dala ku\u00f1cita k\u0113s\u0101 \u0965 4 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c15\u0c1e\u0c4d\u0c1a\u0c28 \u0c2c\u0c30\u0c28 \u0c2c\u0c3f\u0c30\u0c3e\u0c1c \u0c38\u0c41\u0c2c\u0c47\u0c38\u0c3e \u0964 \u0c15\u0c3e\u0c28\u0c28 \u0c15\u0c41\u0c23\u0c4d\u0c21\u0c32 \u0c15\u0c41\u0c1e\u0c4d\u0c1a\u0c3f\u0c24 \u0c15\u0c47\u0c38\u0c3e \u0965 \u0c6a \u0965", "tamil": "\u0b95\u0b9e\u0bcd\u0b9a\u0ba8 \u0baa\u0bb0\u0ba8 \u0baa\u0bbf\u0bb0\u0bbe\u0b9c \u0bb8\u0bc1\u0baa\u0bc7\u0bb8\u0bbe \u0964 \u0b95\u0bbe\u0ba8\u0ba8 \u0b95\u0bc1\u0ba3\u0bcd\u0b9f\u0bb2 \u0b95\u0bc1\u0b9e\u0bcd\u0b9a\u0bbf\u0ba4 \u0b95\u0bc7\u0bb8\u0bbe \u0965 \u0bea \u0965", "kannada": "\u0c95\u0c9e\u0ccd\u0c9a\u0ca8 \u0cac\u0cb0\u0ca8 \u0cac\u0cbf\u0cb0\u0cbe\u0c9c \u0cb8\u0cc1\u0cac\u0cc7\u0cb8\u0cbe \u0964 \u0c95\u0cbe\u0ca8\u0ca8 \u0c95\u0cc1\u0ca3\u0ccd\u0ca1\u0cb2 \u0c95\u0cc1\u0c9e\u0ccd\u0c9a\u0cbf\u0ca4 \u0c95\u0cc7\u0cb8\u0cbe \u0965 \u0cea \u0965", "malayalam": "\u0d15\u0d1e\u0d4d\u0d1a\u0d28 \u0d2c\u0d30\u0d28 \u0d2c\u0d3f\u0d30\u0d3e\u0d1c \u0d38\u0d41\u0d2c\u0d47\u0d38\u0d3e \u0964 \u0d15\u0d3e\u0d28\u0d28 \u0d15\u0d41\u0d23\u0d4d\u0d21\u0d32 \u0d15\u0d41\u0d1e\u0d4d\u0d1a\u0d3f\u0d24 \u0d15\u0d47\u0d38\u0d3e \u0965 \u0d6a \u0965"},
        draftTranslation: "With golden complexion and splendid attire, with sparkling earrings and curly locks.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 7,
        devanagariText: "\u0939\u093e\u0925 \u092c\u091c\u094d\u0930 \u0914 \u0927\u094d\u0935\u091c\u093e \u092c\u093f\u0930\u093e\u091c\u0948 \u0964 \u0915\u093e\u0901\u0927\u0947 \u092e\u0942\u0901\u091c \u091c\u0928\u0947\u090a \u0938\u093e\u091c\u0948 \u0965 \u096b \u0965",
        iastText: "h\u0101tha bajra au dhvaj\u0101 bir\u0101jai \u0964 k\u0101m\u0310dh\u0113 m\u016bn\u0310ja jan\u0113\u016b s\u0101jai \u0965 5 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c39\u0c3e\u0c25 \u0c2c\u0c1c\u0c4d\u0c30 \u0c14 \u0c27\u0c4d\u0c35\u0c1c\u0c3e \u0c2c\u0c3f\u0c30\u0c3e\u0c1c\u0c48 \u0964 \u0c15\u0c3e\u0c01\u0c27\u0c47 \u0c2e\u0c42\u0c01\u0c1c \u0c1c\u0c28\u0c47\u0c0a \u0c38\u0c3e\u0c1c\u0c48 \u0965 \u0c6b \u0965", "tamil": "\u0bb9\u0bbe\u0ba4 \u0baa\u0b9c\u0bcd\u0bb0 \u0b94 \u0ba4\u0bcd\u0bb5\u0b9c\u0bbe \u0baa\u0bbf\u0bb0\u0bbe\u0b9c\u0bc8 \u0964 \u0b95\u0bbe\u0901\u0ba4\u0bc7 \u0bae\u0bc2\u0901\u0b9c \u0b9c\u0ba8\u0bc7\u0b8a \u0bb8\u0bbe\u0b9c\u0bc8 \u0965 \u0beb \u0965", "kannada": "\u0cb9\u0cbe\u0ca5 \u0cac\u0c9c\u0ccd\u0cb0 \u0c94 \u0ca7\u0ccd\u0cb5\u0c9c\u0cbe \u0cac\u0cbf\u0cb0\u0cbe\u0c9c\u0cc8 \u0964 \u0c95\u0cbe\u0c81\u0ca7\u0cc7 \u0cae\u0cc2\u0c81\u0c9c \u0c9c\u0ca8\u0cc7\u0c8a \u0cb8\u0cbe\u0c9c\u0cc8 \u0965 \u0ceb \u0965", "malayalam": "\u0d39\u0d3e\u0d25 \u0d2c\u0d1c\u0d4d\u0d30 \u0d14 \u0d27\u0d4d\u0d35\u0d1c\u0d3e \u0d2c\u0d3f\u0d30\u0d3e\u0d1c\u0d48 \u0964 \u0d15\u0d3e\u0d01\u0d27\u0d47 \u0d2e\u0d42\u0d01\u0d1c \u0d1c\u0d28\u0d47\u0d0a \u0d38\u0d3e\u0d1c\u0d48 \u0965 \u0d6b \u0965"},
        draftTranslation: "In Your hands gleam the thunderbolt and flag, upon Your shoulder rests the sacred munja grass thread.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 8,
        devanagariText: "\u0938\u0919\u094d\u0915\u0930 \u0938\u0941\u0935\u0928 \u0915\u0947\u0938\u0930\u0940\u0928\u0928\u094d\u0926\u0928 \u0964 \u0924\u0947\u091c \u092a\u094d\u0930\u0924\u093e\u092a \u092e\u0939\u093e \u091c\u0917 \u092c\u0928\u094d\u0926\u0928 \u0965 \u096c \u0965",
        iastText: "sa\u1e45kara suvana k\u0113sar\u012bnandana \u0964 t\u0113ja prat\u0101pa mah\u0101 jaga bandana \u0965 6 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c38\u0c19\u0c4d\u0c15\u0c30 \u0c38\u0c41\u0c35\u0c28 \u0c15\u0c47\u0c38\u0c30\u0c40\u0c28\u0c28\u0c4d\u0c26\u0c28 \u0964 \u0c24\u0c47\u0c1c \u0c2a\u0c4d\u0c30\u0c24\u0c3e\u0c2a \u0c2e\u0c39\u0c3e \u0c1c\u0c17 \u0c2c\u0c28\u0c4d\u0c26\u0c28 \u0965 \u0c6c \u0965", "tamil": "\u0bb8\u0b99\u0bcd\u0b95\u0bb0 \u0bb8\u0bc1\u0bb5\u0ba8 \u0b95\u0bc7\u0bb8\u0bb0\u0bc0\u0ba8\u0ba8\u0bcd\u0ba4\u0ba8 \u0964 \u0ba4\u0bc7\u0b9c \u0baa\u0bcd\u0bb0\u0ba4\u0bbe\u0baa \u0bae\u0bb9\u0bbe \u0b9c\u0b95 \u0baa\u0ba8\u0bcd\u0ba4\u0ba8 \u0965 \u0bec \u0965", "kannada": "\u0cb8\u0c99\u0ccd\u0c95\u0cb0 \u0cb8\u0cc1\u0cb5\u0ca8 \u0c95\u0cc7\u0cb8\u0cb0\u0cc0\u0ca8\u0ca8\u0ccd\u0ca6\u0ca8 \u0964 \u0ca4\u0cc7\u0c9c \u0caa\u0ccd\u0cb0\u0ca4\u0cbe\u0caa \u0cae\u0cb9\u0cbe \u0c9c\u0c97 \u0cac\u0ca8\u0ccd\u0ca6\u0ca8 \u0965 \u0cec \u0965", "malayalam": "\u0d38\u0d19\u0d4d\u0d15\u0d30 \u0d38\u0d41\u0d35\u0d28 \u0d15\u0d47\u0d38\u0d30\u0d40\u0d28\u0d28\u0d4d\u0d26\u0d28 \u0964 \u0d24\u0d47\u0d1c \u0d2a\u0d4d\u0d30\u0d24\u0d3e\u0d2a \u0d2e\u0d39\u0d3e \u0d1c\u0d17 \u0d2c\u0d28\u0d4d\u0d26\u0d28 \u0965 \u0d6c \u0965"},
        draftTranslation: "Incarnation of Shiva, son of Kesari, Your blazing glory is revered throughout the universe.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 9,
        devanagariText: "\u092c\u093f\u0926\u094d\u092f\u093e\u0935\u093e\u0928 \u0917\u0941\u0928\u0940 \u0905\u0924\u093f \u091a\u093e\u0924\u0941\u0930 \u0964 \u0930\u093e\u092e \u0915\u093e\u091c \u0915\u0930\u093f\u092c\u0947 \u0915\u094b \u0906\u0924\u0941\u0930 \u0965 \u096d \u0965",
        iastText: "bidy\u0101v\u0101na gun\u012b ati c\u0101tura \u0964 r\u0101ma k\u0101ja karib\u0113 k\u014d \u0101tura \u0965 7 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c2c\u0c3f\u0c26\u0c4d\u0c2f\u0c3e\u0c35\u0c3e\u0c28 \u0c17\u0c41\u0c28\u0c40 \u0c05\u0c24\u0c3f \u0c1a\u0c3e\u0c24\u0c41\u0c30 \u0964 \u0c30\u0c3e\u0c2e \u0c15\u0c3e\u0c1c \u0c15\u0c30\u0c3f\u0c2c\u0c47 \u0c15\u0c4b \u0c06\u0c24\u0c41\u0c30 \u0965 \u0c6d \u0965", "tamil": "\u0baa\u0bbf\u0ba4\u0bcd\u0baf\u0bbe\u0bb5\u0bbe\u0ba8 \u0b95\u0bc1\u0ba8\u0bc0 \u0b85\u0ba4\u0bbf \u0b9a\u0bbe\u0ba4\u0bc1\u0bb0 \u0964 \u0bb0\u0bbe\u0bae \u0b95\u0bbe\u0b9c \u0b95\u0bb0\u0bbf\u0baa\u0bc7 \u0b95\u0bcb \u0b86\u0ba4\u0bc1\u0bb0 \u0965 \u0bed \u0965", "kannada": "\u0cac\u0cbf\u0ca6\u0ccd\u0caf\u0cbe\u0cb5\u0cbe\u0ca8 \u0c97\u0cc1\u0ca8\u0cc0 \u0c85\u0ca4\u0cbf \u0c9a\u0cbe\u0ca4\u0cc1\u0cb0 \u0964 \u0cb0\u0cbe\u0cae \u0c95\u0cbe\u0c9c \u0c95\u0cb0\u0cbf\u0cac\u0cc7 \u0c95\u0ccb \u0c86\u0ca4\u0cc1\u0cb0 \u0965 \u0ced \u0965", "malayalam": "\u0d2c\u0d3f\u0d26\u0d4d\u0d2f\u0d3e\u0d35\u0d3e\u0d28 \u0d17\u0d41\u0d28\u0d40 \u0d05\u0d24\u0d3f \u0d1a\u0d3e\u0d24\u0d41\u0d30 \u0964 \u0d30\u0d3e\u0d2e \u0d15\u0d3e\u0d1c \u0d15\u0d30\u0d3f\u0d2c\u0d47 \u0d15\u0d4b \u0d06\u0d24\u0d41\u0d30 \u0965 \u0d6d \u0965"},
        draftTranslation: "Learned, virtuous, profoundly wise, always eager to accomplish Sri Rama's work.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 10,
        devanagariText: "\u092a\u094d\u0930\u092d\u0941 \u091a\u0930\u093f\u0924\u094d\u0930 \u0938\u0941\u0928\u093f\u092c\u0947 \u0915\u094b \u0930\u0938\u093f\u092f\u093e \u0964 \u0930\u093e\u092e \u0932\u0916\u0928 \u0938\u0940\u0924\u093e \u092e\u0928 \u092c\u0938\u093f\u092f\u093e \u0965 \u096e \u0965",
        iastText: "prabhu caritra sunib\u0113 k\u014d rasiy\u0101 \u0964 r\u0101ma lakhana s\u012bt\u0101 mana basiy\u0101 \u0965 8 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c2a\u0c4d\u0c30\u0c2d\u0c41 \u0c1a\u0c30\u0c3f\u0c24\u0c4d\u0c30 \u0c38\u0c41\u0c28\u0c3f\u0c2c\u0c47 \u0c15\u0c4b \u0c30\u0c38\u0c3f\u0c2f\u0c3e \u0964 \u0c30\u0c3e\u0c2e \u0c32\u0c16\u0c28 \u0c38\u0c40\u0c24\u0c3e \u0c2e\u0c28 \u0c2c\u0c38\u0c3f\u0c2f\u0c3e \u0965 \u0c6e \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0baa\u0bc1 \u0b9a\u0bb0\u0bbf\u0ba4\u0bcd\u0bb0 \u0bb8\u0bc1\u0ba8\u0bbf\u0baa\u0bc7 \u0b95\u0bcb \u0bb0\u0bb8\u0bbf\u0baf\u0bbe \u0964 \u0bb0\u0bbe\u0bae \u0bb2\u0b95\u0ba8 \u0bb8\u0bc0\u0ba4\u0bbe \u0bae\u0ba8 \u0baa\u0bb8\u0bbf\u0baf\u0bbe \u0965 \u0bee \u0965", "kannada": "\u0caa\u0ccd\u0cb0\u0cad\u0cc1 \u0c9a\u0cb0\u0cbf\u0ca4\u0ccd\u0cb0 \u0cb8\u0cc1\u0ca8\u0cbf\u0cac\u0cc7 \u0c95\u0ccb \u0cb0\u0cb8\u0cbf\u0caf\u0cbe \u0964 \u0cb0\u0cbe\u0cae \u0cb2\u0c96\u0ca8 \u0cb8\u0cc0\u0ca4\u0cbe \u0cae\u0ca8 \u0cac\u0cb8\u0cbf\u0caf\u0cbe \u0965 \u0cee \u0965", "malayalam": "\u0d2a\u0d4d\u0d30\u0d2d\u0d41 \u0d1a\u0d30\u0d3f\u0d24\u0d4d\u0d30 \u0d38\u0d41\u0d28\u0d3f\u0d2c\u0d47 \u0d15\u0d4b \u0d30\u0d38\u0d3f\u0d2f\u0d3e \u0964 \u0d30\u0d3e\u0d2e \u0d32\u0d16\u0d28 \u0d38\u0d40\u0d24\u0d3e \u0d2e\u0d28 \u0d2c\u0d38\u0d3f\u0d2f\u0d3e \u0965 \u0d6e \u0965"},
        draftTranslation: "Relishing the narration of the Lord's deeds, in Your heart ever dwell Rama, Lakshmana, and Sita.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 11,
        devanagariText: "\u0938\u0942\u0915\u094d\u0937\u094d\u092e \u0930\u0942\u092a \u0927\u0930\u093f \u0938\u093f\u092f\u0939\u093f\u0902 \u0926\u093f\u0916\u093e\u0935\u093e \u0964 \u092c\u093f\u0915\u091f \u0930\u0942\u092a \u0927\u0930\u093f \u0932\u0919\u094d\u0915 \u091c\u0930\u093e\u0935\u093e \u0965 \u096f \u0965",
        iastText: "s\u016bk\u1e63ma r\u016bpa dhari siyahi\u1e41 dikh\u0101v\u0101 \u0964 bika\u1e6da r\u016bpa dhari la\u1e45ka jar\u0101v\u0101 \u0965 9 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c38\u0c42\u0c15\u0c4d\u0c37\u0c4d\u0c2e \u0c30\u0c42\u0c2a \u0c27\u0c30\u0c3f \u0c38\u0c3f\u0c2f\u0c39\u0c3f\u0c02 \u0c26\u0c3f\u0c16\u0c3e\u0c35\u0c3e \u0964 \u0c2c\u0c3f\u0c15\u0c1f \u0c30\u0c42\u0c2a \u0c27\u0c30\u0c3f \u0c32\u0c19\u0c4d\u0c15 \u0c1c\u0c30\u0c3e\u0c35\u0c3e \u0965 \u0c6f \u0965", "tamil": "\u0bb8\u0bc2\u0b95\u0bcd\u0bb7\u0bcd\u0bae \u0bb0\u0bc2\u0baa \u0ba4\u0bb0\u0bbf \u0bb8\u0bbf\u0baf\u0bb9\u0bbf\u0bae\u0bcd \u0ba4\u0bbf\u0b95\u0bbe\u0bb5\u0bbe \u0964 \u0baa\u0bbf\u0b95\u0b9f \u0bb0\u0bc2\u0baa \u0ba4\u0bb0\u0bbf \u0bb2\u0b99\u0bcd\u0b95 \u0b9c\u0bb0\u0bbe\u0bb5\u0bbe \u0965 \u0bef \u0965", "kannada": "\u0cb8\u0cc2\u0c95\u0ccd\u0cb7\u0ccd\u0cae \u0cb0\u0cc2\u0caa \u0ca7\u0cb0\u0cbf \u0cb8\u0cbf\u0caf\u0cb9\u0cbf\u0c82 \u0ca6\u0cbf\u0c96\u0cbe\u0cb5\u0cbe \u0964 \u0cac\u0cbf\u0c95\u0c9f \u0cb0\u0cc2\u0caa \u0ca7\u0cb0\u0cbf \u0cb2\u0c99\u0ccd\u0c95 \u0c9c\u0cb0\u0cbe\u0cb5\u0cbe \u0965 \u0cef \u0965", "malayalam": "\u0d38\u0d42\u0d15\u0d4d\u0d37\u0d4d\u0d2e \u0d30\u0d42\u0d2a \u0d27\u0d30\u0d3f \u0d38\u0d3f\u0d2f\u0d39\u0d3f\u0d02 \u0d26\u0d3f\u0d16\u0d3e\u0d35\u0d3e \u0964 \u0d2c\u0d3f\u0d15\u0d1f \u0d30\u0d42\u0d2a \u0d27\u0d30\u0d3f \u0d32\u0d19\u0d4d\u0d15 \u0d1c\u0d30\u0d3e\u0d35\u0d3e \u0965 \u0d6f \u0965"},
        draftTranslation: "Assuming a minute form You appeared before Mother Sita, assuming a colossal form You burnt Lanka.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 12,
        devanagariText: "\u092d\u0940\u092e \u0930\u0942\u092a \u0927\u0930\u093f \u0905\u0938\u0941\u0930 \u0938\u0901\u0939\u093e\u0930\u0947 \u0964 \u0930\u093e\u092e\u091a\u0928\u094d\u0926\u094d\u0930 \u0915\u0947 \u0915\u093e\u091c \u0938\u0901\u0935\u093e\u0930\u0947 \u0965 \u0967\u0966 \u0965",
        iastText: "bh\u012bma r\u016bpa dhari asura sam\u0310h\u0101r\u0113 \u0964 r\u0101macandra k\u0113 k\u0101ja sam\u0310v\u0101r\u0113 \u0965 10 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c2d\u0c40\u0c2e \u0c30\u0c42\u0c2a \u0c27\u0c30\u0c3f \u0c05\u0c38\u0c41\u0c30 \u0c38\u0c01\u0c39\u0c3e\u0c30\u0c47 \u0964 \u0c30\u0c3e\u0c2e\u0c1a\u0c28\u0c4d\u0c26\u0c4d\u0c30 \u0c15\u0c47 \u0c15\u0c3e\u0c1c \u0c38\u0c01\u0c35\u0c3e\u0c30\u0c47 \u0965 \u0c67\u0c66 \u0965", "tamil": "\u0baa\u0bc0\u0bae \u0bb0\u0bc2\u0baa \u0ba4\u0bb0\u0bbf \u0b85\u0bb8\u0bc1\u0bb0 \u0bb8\u0901\u0bb9\u0bbe\u0bb0\u0bc7 \u0964 \u0bb0\u0bbe\u0bae\u0b9a\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0 \u0b95\u0bc7 \u0b95\u0bbe\u0b9c \u0bb8\u0901\u0bb5\u0bbe\u0bb0\u0bc7 \u0965 \u0be7\u0be6 \u0965", "kannada": "\u0cad\u0cc0\u0cae \u0cb0\u0cc2\u0caa \u0ca7\u0cb0\u0cbf \u0c85\u0cb8\u0cc1\u0cb0 \u0cb8\u0c81\u0cb9\u0cbe\u0cb0\u0cc7 \u0964 \u0cb0\u0cbe\u0cae\u0c9a\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0 \u0c95\u0cc7 \u0c95\u0cbe\u0c9c \u0cb8\u0c81\u0cb5\u0cbe\u0cb0\u0cc7 \u0965 \u0ce7\u0ce6 \u0965", "malayalam": "\u0d2d\u0d40\u0d2e \u0d30\u0d42\u0d2a \u0d27\u0d30\u0d3f \u0d05\u0d38\u0d41\u0d30 \u0d38\u0d01\u0d39\u0d3e\u0d30\u0d47 \u0964 \u0d30\u0d3e\u0d2e\u0d1a\u0d28\u0d4d\u0d26\u0d4d\u0d30 \u0d15\u0d47 \u0d15\u0d3e\u0d1c \u0d38\u0d01\u0d35\u0d3e\u0d30\u0d47 \u0965 \u0d67\u0d66 \u0965"},
        draftTranslation: "Assuming a formidable form You destroyed demons, successfully carrying out all the missions of Sri Ramachandra.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 13,
        devanagariText: "\u0932\u093e\u092f \u0938\u091c\u0940\u0935\u0928 \u0932\u0916\u0928 \u091c\u093f\u092f\u093e\u092f\u0947 \u0964 \u0936\u094d\u0930\u0940\u0930\u0918\u0941\u092c\u0940\u0930 \u0939\u0930\u0937\u093f \u0909\u0930 \u0932\u093e\u092f\u0947 \u0965 \u0967\u0967 \u0965",
        iastText: "l\u0101ya saj\u012bvana lakhana jiy\u0101y\u0113 \u0964 \u015br\u012braghub\u012bra hara\u1e63i ura l\u0101y\u0113 \u0965 11 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c32\u0c3e\u0c2f \u0c38\u0c1c\u0c40\u0c35\u0c28 \u0c32\u0c16\u0c28 \u0c1c\u0c3f\u0c2f\u0c3e\u0c2f\u0c47 \u0964 \u0c36\u0c4d\u0c30\u0c40\u0c30\u0c18\u0c41\u0c2c\u0c40\u0c30 \u0c39\u0c30\u0c37\u0c3f \u0c09\u0c30 \u0c32\u0c3e\u0c2f\u0c47 \u0965 \u0c67\u0c67 \u0965", "tamil": "\u0bb2\u0bbe\u0baf \u0bb8\u0b9c\u0bc0\u0bb5\u0ba8 \u0bb2\u0b95\u0ba8 \u0b9c\u0bbf\u0baf\u0bbe\u0baf\u0bc7 \u0964 \u0bb6\u0bcd\u0bb0\u0bc0\u0bb0\u0b95\u0bc1\u0baa\u0bc0\u0bb0 \u0bb9\u0bb0\u0bb7\u0bbf \u0b89\u0bb0 \u0bb2\u0bbe\u0baf\u0bc7 \u0965 \u0be7\u0be7 \u0965", "kannada": "\u0cb2\u0cbe\u0caf \u0cb8\u0c9c\u0cc0\u0cb5\u0ca8 \u0cb2\u0c96\u0ca8 \u0c9c\u0cbf\u0caf\u0cbe\u0caf\u0cc7 \u0964 \u0cb6\u0ccd\u0cb0\u0cc0\u0cb0\u0c98\u0cc1\u0cac\u0cc0\u0cb0 \u0cb9\u0cb0\u0cb7\u0cbf \u0c89\u0cb0 \u0cb2\u0cbe\u0caf\u0cc7 \u0965 \u0ce7\u0ce7 \u0965", "malayalam": "\u0d32\u0d3e\u0d2f \u0d38\u0d1c\u0d40\u0d35\u0d28 \u0d32\u0d16\u0d28 \u0d1c\u0d3f\u0d2f\u0d3e\u0d2f\u0d47 \u0964 \u0d36\u0d4d\u0d30\u0d40\u0d30\u0d18\u0d41\u0d2c\u0d40\u0d30 \u0d39\u0d30\u0d37\u0d3f \u0d09\u0d30 \u0d32\u0d3e\u0d2f\u0d47 \u0965 \u0d67\u0d67 \u0965"},
        draftTranslation: "Bringing the Sanjivani herb You revived Lakshmana, whereupon Sri Rama joyfully embraced You.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 14,
        devanagariText: "\u0930\u0918\u0941\u092a\u0924\u093f \u0915\u0940\u0928\u094d\u0939\u0940 \u092c\u0939\u0941\u0924 \u092c\u0921\u093c\u093e\u0908 \u0964 \u0924\u0941\u092e \u092e\u092e \u092a\u094d\u0930\u093f\u092f \u092d\u0930\u0924\u0939\u093f \u0938\u092e \u092d\u093e\u0908 \u0965 \u0967\u0968 \u0965",
        iastText: "raghupati k\u012bnh\u012b bahuta ba\u1e5b\u0101\u012b \u0964 tuma mama priya bharatahi sama bh\u0101\u012b \u0965 12 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c30\u0c18\u0c41\u0c2a\u0c24\u0c3f \u0c15\u0c40\u0c28\u0c4d\u0c39\u0c40 \u0c2c\u0c39\u0c41\u0c24 \u0c2c\u0921\u093c\u0c3e\u0c08 \u0964 \u0c24\u0c41\u0c2e \u0c2e\u0c2e \u0c2a\u0c4d\u0c30\u0c3f\u0c2f \u0c2d\u0c30\u0c24\u0c39\u0c3f \u0c38\u0c2e \u0c2d\u0c3e\u0c08 \u0965 \u0c67\u0c68 \u0965", "tamil": "\u0bb0\u0b95\u0bc1\u0baa\u0ba4\u0bbf \u0b95\u0bc0\u0ba8\u0bcd\u0bb9\u0bc0 \u0baa\u0bb9\u0bc1\u0ba4 \u0baa\u0b83\u0b9f\u00b2\u0bbe\u0b88 \u0964 \u0ba4\u0bc1\u0bae \u0bae\u0bae \u0baa\u0bcd\u0bb0\u0bbf\u0baf \u0baa\u0bb0\u0ba4\u0bb9\u0bbf \u0bb8\u0bae \u0baa\u0bbe\u0b88 \u0965 \u0be7\u0be8 \u0965", "kannada": "\u0cb0\u0c98\u0cc1\u0caa\u0ca4\u0cbf \u0c95\u0cc0\u0ca8\u0ccd\u0cb9\u0cc0 \u0cac\u0cb9\u0cc1\u0ca4 \u0cac\u0ca1\u0cbc\u0cbe\u0c88 \u0964 \u0ca4\u0cc1\u0cae \u0cae\u0cae \u0caa\u0ccd\u0cb0\u0cbf\u0caf \u0cad\u0cb0\u0ca4\u0cb9\u0cbf \u0cb8\u0cae \u0cad\u0cbe\u0c88 \u0965 \u0ce7\u0ce8 \u0965", "malayalam": "\u0d30\u0d18\u0d41\u0d2a\u0d24\u0d3f \u0d15\u0d40\u0d28\u0d4d\u0d39\u0d40 \u0d2c\u0d39\u0d41\u0d24 \u0d2c\u0921\u093c\u0d3e\u0d08 \u0964 \u0d24\u0d41\u0d2e \u0d2e\u0d2e \u0d2a\u0d4d\u0d30\u0d3f\u0d2f \u0d2d\u0d30\u0d24\u0d39\u0d3f \u0d38\u0d2e \u0d2d\u0d3e\u0d08 \u0965 \u0d67\u0d68 \u0965"},
        draftTranslation: "Raghupati praised You lavishly, saying: 'You are as dear to Me as My brother Bharata!'",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 15,
        devanagariText: "\u0938\u0939\u0938 \u092c\u0926\u0928 \u0924\u0941\u092e\u094d\u0939\u0930\u094b \u091c\u0938 \u0917\u093e\u0935\u0948\u0902 \u0964 \u0905\u0938 \u0915\u0939\u093f \u0936\u094d\u0930\u0940\u092a\u0924\u093f \u0915\u0923\u094d\u0920 \u0932\u0917\u093e\u0935\u0948\u0902 \u0965 \u0967\u0969 \u0965",
        iastText: "sahasa badana tumhar\u014d jasa g\u0101vai\u1e41 \u0964 asa kahi \u015br\u012bpati ka\u1e47\u1e6dha lag\u0101vai\u1e41 \u0965 13 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c38\u0c39\u0c38 \u0c2c\u0c26\u0c28 \u0c24\u0c41\u0c2e\u0c4d\u0c39\u0c30\u0c4b \u0c1c\u0c38 \u0c17\u0c3e\u0c35\u0c48\u0c02 \u0964 \u0c05\u0c38 \u0c15\u0c39\u0c3f \u0c36\u0c4d\u0c30\u0c40\u0c2a\u0c24\u0c3f \u0c15\u0c23\u0c4d\u0c20 \u0c32\u0c17\u0c3e\u0c35\u0c48\u0c02 \u0965 \u0c67\u0c69 \u0965", "tamil": "\u0bb8\u0bb9\u0bb8 \u0baa\u0ba4\u0ba8 \u0ba4\u0bc1\u0bae\u0bcd\u0bb9\u0bb0\u0bcb \u0b9c\u0bb8 \u0b95\u0bbe\u0bb5\u0bc8\u0bae\u0bcd \u0964 \u0b85\u0bb8 \u0b95\u0bb9\u0bbf \u0bb6\u0bcd\u0bb0\u0bc0\u0baa\u0ba4\u0bbf \u0b95\u0ba3\u0bcd\u0b9f \u0bb2\u0b95\u0bbe\u0bb5\u0bc8\u0bae\u0bcd \u0965 \u0be7\u0be9 \u0965", "kannada": "\u0cb8\u0cb9\u0cb8 \u0cac\u0ca6\u0ca8 \u0ca4\u0cc1\u0cae\u0ccd\u0cb9\u0cb0\u0ccb \u0c9c\u0cb8 \u0c97\u0cbe\u0cb5\u0cc8\u0c82 \u0964 \u0c85\u0cb8 \u0c95\u0cb9\u0cbf \u0cb6\u0ccd\u0cb0\u0cc0\u0caa\u0ca4\u0cbf \u0c95\u0ca3\u0ccd\u0ca0 \u0cb2\u0c97\u0cbe\u0cb5\u0cc8\u0c82 \u0965 \u0ce7\u0ce9 \u0965", "malayalam": "\u0d38\u0d39\u0d38 \u0d2c\u0d26\u0d28 \u0d24\u0d41\u0d2e\u0d4d\u0d39\u0d30\u0d4b \u0d1c\u0d38 \u0d17\u0d3e\u0d35\u0d48\u0d02 \u0964 \u0d05\u0d38 \u0d15\u0d39\u0d3f \u0d36\u0d4d\u0d30\u0d40\u0d2a\u0d24\u0d3f \u0d15\u0d23\u0d4d\u0d20 \u0d32\u0d17\u0d3e\u0d35\u0d48\u0d02 \u0965 \u0d67\u0d69 \u0965"},
        draftTranslation: "'May the thousand-mouthed Shesha sing Your renown!' Saying this, the Lord of Sri embraced You.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 16,
        devanagariText: "\u0938\u0928\u0915\u093e\u0926\u093f\u0915 \u092c\u094d\u0930\u0939\u094d\u092e\u093e\u0926\u093f \u092e\u0941\u0928\u0940\u0938\u093e \u0964 \u0928\u093e\u0930\u0926 \u0938\u093e\u0930\u0926 \u0938\u0939\u093f\u0924 \u0905\u0939\u0940\u0938\u093e \u0965 \u0967\u096a \u0965",
        iastText: "sanak\u0101dika brahm\u0101di mun\u012bs\u0101 \u0964 n\u0101rada s\u0101rada sahita ah\u012bs\u0101 \u0965 14 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c38\u0c28\u0c15\u0c3e\u0c26\u0c3f\u0c15 \u0c2c\u0c4d\u0c30\u0c39\u0c4d\u0c2e\u0c3e\u0c26\u0c3f \u0c2e\u0c41\u0c28\u0c40\u0c38\u0c3e \u0964 \u0c28\u0c3e\u0c30\u0c26 \u0c38\u0c3e\u0c30\u0c26 \u0c38\u0c39\u0c3f\u0c24 \u0c05\u0c39\u0c40\u0c38\u0c3e \u0965 \u0c67\u0c6a \u0965", "tamil": "\u0bb8\u0ba8\u0b95\u0bbe\u0ba4\u0bbf\u0b95 \u0baa\u0bcd\u0bb0\u0bb9\u0bcd\u0bae\u0bbe\u0ba4\u0bbf \u0bae\u0bc1\u0ba8\u0bc0\u0bb8\u0bbe \u0964 \u0ba8\u0bbe\u0bb0\u0ba4 \u0bb8\u0bbe\u0bb0\u0ba4 \u0bb8\u0bb9\u0bbf\u0ba4 \u0b85\u0bb9\u0bc0\u0bb8\u0bbe \u0965 \u0be7\u0bea \u0965", "kannada": "\u0cb8\u0ca8\u0c95\u0cbe\u0ca6\u0cbf\u0c95 \u0cac\u0ccd\u0cb0\u0cb9\u0ccd\u0cae\u0cbe\u0ca6\u0cbf \u0cae\u0cc1\u0ca8\u0cc0\u0cb8\u0cbe \u0964 \u0ca8\u0cbe\u0cb0\u0ca6 \u0cb8\u0cbe\u0cb0\u0ca6 \u0cb8\u0cb9\u0cbf\u0ca4 \u0c85\u0cb9\u0cc0\u0cb8\u0cbe \u0965 \u0ce7\u0cea \u0965", "malayalam": "\u0d38\u0d28\u0d15\u0d3e\u0d26\u0d3f\u0d15 \u0d2c\u0d4d\u0d30\u0d39\u0d4d\u0d2e\u0d3e\u0d26\u0d3f \u0d2e\u0d41\u0d28\u0d40\u0d38\u0d3e \u0964 \u0d28\u0d3e\u0d30\u0d26 \u0d38\u0d3e\u0d30\u0d26 \u0d38\u0d39\u0d3f\u0d24 \u0d05\u0d39\u0d40\u0d38\u0d3e \u0965 \u0d67\u0d6a \u0965"},
        draftTranslation: "Sages like Sanaka, Brahma, Narada, Saraswati, and the serpent king sing Your praises.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 17,
        devanagariText: "\u091c\u092e \u0915\u0941\u092c\u0947\u0930 \u0926\u093f\u0917\u092a\u093e\u0932 \u091c\u0939\u093e\u0901 \u0924\u0947 \u0964 \u0915\u092c\u093f \u0915\u094b\u092c\u093f\u0926 \u0915\u0939\u093f \u0938\u0915\u0948\u0902 \u0915\u0939\u093e\u0901 \u0924\u0947 \u0965 \u0967\u096b \u0965",
        iastText: "jama kub\u0113ra digap\u0101la jah\u0101m\u0310 t\u0113 \u0964 kabi k\u014dbida kahi sakai\u1e41 kah\u0101m\u0310 t\u0113 \u0965 15 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c1c\u0c2e \u0c15\u0c41\u0c2c\u0c47\u0c30 \u0c26\u0c3f\u0c17\u0c2a\u0c3e\u0c32 \u0c1c\u0c39\u0c3e\u0c01 \u0c24\u0c47 \u0964 \u0c15\u0c2c\u0c3f \u0c15\u0c4b\u0c2c\u0c3f\u0c26 \u0c15\u0c39\u0c3f \u0c38\u0c15\u0c48\u0c02 \u0c15\u0c39\u0c3e\u0c01 \u0c24\u0c47 \u0965 \u0c67\u0c6b \u0965", "tamil": "\u0b9c\u0bae \u0b95\u0bc1\u0baa\u0bc7\u0bb0 \u0ba4\u0bbf\u0b95\u0baa\u0bbe\u0bb2 \u0b9c\u0bb9\u0bbe\u0901 \u0ba4\u0bc7 \u0964 \u0b95\u0baa\u0bbf \u0b95\u0bcb\u0baa\u0bbf\u0ba4 \u0b95\u0bb9\u0bbf \u0bb8\u0b95\u0bc8\u0bae\u0bcd \u0b95\u0bb9\u0bbe\u0901 \u0ba4\u0bc7 \u0965 \u0be7\u0beb \u0965", "kannada": "\u0c9c\u0cae \u0c95\u0cc1\u0cac\u0cc7\u0cb0 \u0ca6\u0cbf\u0c97\u0caa\u0cbe\u0cb2 \u0c9c\u0cb9\u0cbe\u0c81 \u0ca4\u0cc7 \u0964 \u0c95\u0cac\u0cbf \u0c95\u0ccb\u0cac\u0cbf\u0ca6 \u0c95\u0cb9\u0cbf \u0cb8\u0c95\u0cc8\u0c82 \u0c95\u0cb9\u0cbe\u0c81 \u0ca4\u0cc7 \u0965 \u0ce7\u0ceb \u0965", "malayalam": "\u0d1c\u0d2e \u0d15\u0d41\u0d2c\u0d47\u0d30 \u0d26\u0d3f\u0d17\u0d2a\u0d3e\u0d32 \u0d1c\u0d39\u0d3e\u0d01 \u0d24\u0d47 \u0964 \u0d15\u0d2c\u0d3f \u0d15\u0d4b\u0d2c\u0d3f\u0d26 \u0d15\u0d39\u0d3f \u0d38\u0d15\u0d48\u0d02 \u0d15\u0d39\u0d3e\u0d01 \u0d24\u0d47 \u0965 \u0d67\u0d6b \u0965"},
        draftTranslation: "Yama, Kubera, and the guardians of directions\u2014how can worldly poets and scholars describe Your full glory?",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 18,
        devanagariText: "\u0924\u0941\u092e \u0909\u092a\u0915\u093e\u0930 \u0938\u0941\u0917\u094d\u0930\u0940\u0935\u0939\u093f\u0902 \u0915\u0940\u0928\u094d\u0939\u093e \u0964 \u0930\u093e\u092e \u092e\u093f\u0932\u093e\u092f \u0930\u093e\u091c\u092a\u0926 \u0926\u0940\u0928\u094d\u0939\u093e \u0965 \u0967\u096c \u0965",
        iastText: "tuma upak\u0101ra sugr\u012bvahi\u1e41 k\u012bnh\u0101 \u0964 r\u0101ma mil\u0101ya r\u0101japada d\u012bnh\u0101 \u0965 16 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c24\u0c41\u0c2e \u0c09\u0c2a\u0c15\u0c3e\u0c30 \u0c38\u0c41\u0c17\u0c4d\u0c30\u0c40\u0c35\u0c39\u0c3f\u0c02 \u0c15\u0c40\u0c28\u0c4d\u0c39\u0c3e \u0964 \u0c30\u0c3e\u0c2e \u0c2e\u0c3f\u0c32\u0c3e\u0c2f \u0c30\u0c3e\u0c1c\u0c2a\u0c26 \u0c26\u0c40\u0c28\u0c4d\u0c39\u0c3e \u0965 \u0c67\u0c6c \u0965", "tamil": "\u0ba4\u0bc1\u0bae \u0b89\u0baa\u0b95\u0bbe\u0bb0 \u0bb8\u0bc1\u0b95\u0bcd\u0bb0\u0bc0\u0bb5\u0bb9\u0bbf\u0bae\u0bcd \u0b95\u0bc0\u0ba8\u0bcd\u0bb9\u0bbe \u0964 \u0bb0\u0bbe\u0bae \u0bae\u0bbf\u0bb2\u0bbe\u0baf \u0bb0\u0bbe\u0b9c\u0baa\u0ba4 \u0ba4\u0bc0\u0ba8\u0bcd\u0bb9\u0bbe \u0965 \u0be7\u0bec \u0965", "kannada": "\u0ca4\u0cc1\u0cae \u0c89\u0caa\u0c95\u0cbe\u0cb0 \u0cb8\u0cc1\u0c97\u0ccd\u0cb0\u0cc0\u0cb5\u0cb9\u0cbf\u0c82 \u0c95\u0cc0\u0ca8\u0ccd\u0cb9\u0cbe \u0964 \u0cb0\u0cbe\u0cae \u0cae\u0cbf\u0cb2\u0cbe\u0caf \u0cb0\u0cbe\u0c9c\u0caa\u0ca6 \u0ca6\u0cc0\u0ca8\u0ccd\u0cb9\u0cbe \u0965 \u0ce7\u0cec \u0965", "malayalam": "\u0d24\u0d41\u0d2e \u0d09\u0d2a\u0d15\u0d3e\u0d30 \u0d38\u0d41\u0d17\u0d4d\u0d30\u0d40\u0d35\u0d39\u0d3f\u0d02 \u0d15\u0d40\u0d28\u0d4d\u0d39\u0d3e \u0964 \u0d30\u0d3e\u0d2e \u0d2e\u0d3f\u0d32\u0d3e\u0d2f \u0d30\u0d3e\u0d1c\u0d2a\u0d26 \u0d26\u0d40\u0d28\u0d4d\u0d39\u0d3e \u0965 \u0d67\u0d6c \u0965"},
        draftTranslation: "You rendered great service to Sugriva: introducing him to Sri Rama and restoring his royal throne.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 19,
        devanagariText: "\u0924\u0941\u092e\u094d\u0939\u0930\u094b \u092e\u0928\u094d\u0924\u094d\u0930 \u092c\u093f\u092d\u0940\u0937\u0928 \u092e\u093e\u0928\u093e \u0964 \u0932\u0919\u094d\u0915\u0947\u0938\u094d\u0935\u0930 \u092d\u090f \u0938\u092c \u091c\u0917 \u091c\u093e\u0928\u093e \u0965 \u0967\u096d \u0965",
        iastText: "tumhar\u014d mantra bibh\u012b\u1e63ana m\u0101n\u0101 \u0964 la\u1e45k\u0113svara bha\u0113 saba jaga j\u0101n\u0101 \u0965 17 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c24\u0c41\u0c2e\u0c4d\u0c39\u0c30\u0c4b \u0c2e\u0c28\u0c4d\u0c24\u0c4d\u0c30 \u0c2c\u0c3f\u0c2d\u0c40\u0c37\u0c28 \u0c2e\u0c3e\u0c28\u0c3e \u0964 \u0c32\u0c19\u0c4d\u0c15\u0c47\u0c38\u0c4d\u0c35\u0c30 \u0c2d\u0c0f \u0c38\u0c2c \u0c1c\u0c17 \u0c1c\u0c3e\u0c28\u0c3e \u0965 \u0c67\u0c6d \u0965", "tamil": "\u0ba4\u0bc1\u0bae\u0bcd\u0bb9\u0bb0\u0bcb \u0bae\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0 \u0baa\u0bbf\u0baa\u0bc0\u0bb7\u0ba8 \u0bae\u0bbe\u0ba8\u0bbe \u0964 \u0bb2\u0b99\u0bcd\u0b95\u0bc7\u0bb8\u0bcd\u0bb5\u0bb0 \u0baa\u0b8f \u0bb8\u0baa \u0b9c\u0b95 \u0b9c\u0bbe\u0ba8\u0bbe \u0965 \u0be7\u0bed \u0965", "kannada": "\u0ca4\u0cc1\u0cae\u0ccd\u0cb9\u0cb0\u0ccb \u0cae\u0ca8\u0ccd\u0ca4\u0ccd\u0cb0 \u0cac\u0cbf\u0cad\u0cc0\u0cb7\u0ca8 \u0cae\u0cbe\u0ca8\u0cbe \u0964 \u0cb2\u0c99\u0ccd\u0c95\u0cc7\u0cb8\u0ccd\u0cb5\u0cb0 \u0cad\u0c8f \u0cb8\u0cac \u0c9c\u0c97 \u0c9c\u0cbe\u0ca8\u0cbe \u0965 \u0ce7\u0ced \u0965", "malayalam": "\u0d24\u0d41\u0d2e\u0d4d\u0d39\u0d30\u0d4b \u0d2e\u0d28\u0d4d\u0d24\u0d4d\u0d30 \u0d2c\u0d3f\u0d2d\u0d40\u0d37\u0d28 \u0d2e\u0d3e\u0d28\u0d3e \u0964 \u0d32\u0d19\u0d4d\u0d15\u0d47\u0d38\u0d4d\u0d35\u0d30 \u0d2d\u0d0f \u0d38\u0d2c \u0d1c\u0d17 \u0d1c\u0d3e\u0d28\u0d3e \u0965 \u0d67\u0d6d \u0965"},
        draftTranslation: "Vibhishana heeded Your counsel, becoming the Lord of Lanka, as known to the whole world.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 20,
        devanagariText: "\u091c\u0941\u0917 \u0938\u0939\u0938\u094d\u0930 \u091c\u094b\u091c\u0928 \u092a\u0930 \u092d\u093e\u0928\u0942 \u0964 \u0932\u0940\u0932\u094d\u092f\u094b \u0924\u093e\u0939\u093f \u092e\u0927\u0941\u0930 \u092b\u0932 \u091c\u093e\u0928\u0942 \u0965 \u0967\u096e \u0965",
        iastText: "juga sahasra j\u014djana para bh\u0101n\u016b \u0964 l\u012bly\u014d t\u0101hi madhura phala j\u0101n\u016b \u0965 18 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c1c\u0c41\u0c17 \u0c38\u0c39\u0c38\u0c4d\u0c30 \u0c1c\u0c4b\u0c1c\u0c28 \u0c2a\u0c30 \u0c2d\u0c3e\u0c28\u0c42 \u0964 \u0c32\u0c40\u0c32\u0c4d\u0c2f\u0c4b \u0c24\u0c3e\u0c39\u0c3f \u0c2e\u0c27\u0c41\u0c30 \u0c2b\u0c32 \u0c1c\u0c3e\u0c28\u0c42 \u0965 \u0c67\u0c6e \u0965", "tamil": "\u0b9c\u0bc1\u0b95 \u0bb8\u0bb9\u0bb8\u0bcd\u0bb0 \u0b9c\u0bcb\u0b9c\u0ba8 \u0baa\u0bb0 \u0baa\u0bbe\u0ba8\u0bc2 \u0964 \u0bb2\u0bc0\u0bb2\u0bcd\u0baf\u0bcb \u0ba4\u0bbe\u0bb9\u0bbf \u0bae\u0ba4\u0bc1\u0bb0 \u0baa\u0bb2 \u0b9c\u0bbe\u0ba8\u0bc2 \u0965 \u0be7\u0bee \u0965", "kannada": "\u0c9c\u0cc1\u0c97 \u0cb8\u0cb9\u0cb8\u0ccd\u0cb0 \u0c9c\u0ccb\u0c9c\u0ca8 \u0caa\u0cb0 \u0cad\u0cbe\u0ca8\u0cc2 \u0964 \u0cb2\u0cc0\u0cb2\u0ccd\u0caf\u0ccb \u0ca4\u0cbe\u0cb9\u0cbf \u0cae\u0ca7\u0cc1\u0cb0 \u0cab\u0cb2 \u0c9c\u0cbe\u0ca8\u0cc2 \u0965 \u0ce7\u0cee \u0965", "malayalam": "\u0d1c\u0d41\u0d17 \u0d38\u0d39\u0d38\u0d4d\u0d30 \u0d1c\u0d4b\u0d1c\u0d28 \u0d2a\u0d30 \u0d2d\u0d3e\u0d28\u0d42 \u0964 \u0d32\u0d40\u0d32\u0d4d\u0d2f\u0d4b \u0d24\u0d3e\u0d39\u0d3f \u0d2e\u0d27\u0d41\u0d30 \u0d2b\u0d32 \u0d1c\u0d3e\u0d28\u0d42 \u0965 \u0d67\u0d6e \u0965"},
        draftTranslation: "The sun situated thousands of leagues away\u2014You swallowed it, mistaking it for a sweet fruit!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 21,
        devanagariText: "\u092a\u094d\u0930\u092d\u0941 \u092e\u0941\u0926\u094d\u0930\u093f\u0915\u093e \u092e\u0947\u0932\u093f \u092e\u0941\u0916 \u092e\u093e\u0939\u0940\u0902 \u0964 \u091c\u0932\u0927\u093f \u0932\u093e\u0901\u0918\u093f \u0917\u092f\u0947 \u0905\u091a\u0930\u091c \u0928\u093e\u0939\u0940\u0902 \u0965 \u0967\u096f \u0965",
        iastText: "prabhu mudrik\u0101 m\u0113li mukha m\u0101h\u012b\u1e41 \u0964 jaladhi l\u0101m\u0310ghi gay\u0113 acaraja n\u0101h\u012b\u1e41 \u0965 19 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c2a\u0c4d\u0c30\u0c2d\u0c41 \u0c2e\u0c41\u0c26\u0c4d\u0c30\u0c3f\u0c15\u0c3e \u0c2e\u0c47\u0c32\u0c3f \u0c2e\u0c41\u0c16 \u0c2e\u0c3e\u0c39\u0c40\u0c02 \u0964 \u0c1c\u0c32\u0c27\u0c3f \u0c32\u0c3e\u0c01\u0c18\u0c3f \u0c17\u0c2f\u0c47 \u0c05\u0c1a\u0c30\u0c1c \u0c28\u0c3e\u0c39\u0c40\u0c02 \u0965 \u0c67\u0c6f \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0baa\u0bc1 \u0bae\u0bc1\u0ba4\u0bcd\u0bb0\u0bbf\u0b95\u0bbe \u0bae\u0bc7\u0bb2\u0bbf \u0bae\u0bc1\u0b95 \u0bae\u0bbe\u0bb9\u0bc0\u0bae\u0bcd \u0964 \u0b9c\u0bb2\u0ba4\u0bbf \u0bb2\u0bbe\u0901\u0b95\u0bbf \u0b95\u0baf\u0bc7 \u0b85\u0b9a\u0bb0\u0b9c \u0ba8\u0bbe\u0bb9\u0bc0\u0bae\u0bcd \u0965 \u0be7\u0bef \u0965", "kannada": "\u0caa\u0ccd\u0cb0\u0cad\u0cc1 \u0cae\u0cc1\u0ca6\u0ccd\u0cb0\u0cbf\u0c95\u0cbe \u0cae\u0cc7\u0cb2\u0cbf \u0cae\u0cc1\u0c96 \u0cae\u0cbe\u0cb9\u0cc0\u0c82 \u0964 \u0c9c\u0cb2\u0ca7\u0cbf \u0cb2\u0cbe\u0c81\u0c98\u0cbf \u0c97\u0caf\u0cc7 \u0c85\u0c9a\u0cb0\u0c9c \u0ca8\u0cbe\u0cb9\u0cc0\u0c82 \u0965 \u0ce7\u0cef \u0965", "malayalam": "\u0d2a\u0d4d\u0d30\u0d2d\u0d41 \u0d2e\u0d41\u0d26\u0d4d\u0d30\u0d3f\u0d15\u0d3e \u0d2e\u0d47\u0d32\u0d3f \u0d2e\u0d41\u0d16 \u0d2e\u0d3e\u0d39\u0d40\u0d02 \u0964 \u0d1c\u0d32\u0d27\u0d3f \u0d32\u0d3e\u0d01\u0d18\u0d3f \u0d17\u0d2f\u0d47 \u0d05\u0d1a\u0d30\u0d1c \u0d28\u0d3e\u0d39\u0d40\u0d02 \u0965 \u0d67\u0d6f \u0965"},
        draftTranslation: "Holding the Lord's signet ring in Your mouth, You leaped across the mighty ocean\u2014no wonder at all!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 22,
        devanagariText: "\u0926\u0941\u0930\u094d\u0917\u092e \u0915\u093e\u091c \u091c\u0917\u0924 \u0915\u0947 \u091c\u0947\u0924\u0947 \u0964 \u0938\u0941\u0917\u092e \u0905\u0928\u0941\u0917\u094d\u0930\u0939 \u0924\u0941\u092e\u094d\u0939\u0930\u0947 \u0924\u0947\u0924\u0947 \u0965 \u0968\u0966 \u0965",
        iastText: "durgama k\u0101ja jagata k\u0113 j\u0113t\u0113 \u0964 sugama anugraha tumhar\u0113 t\u0113t\u0113 \u0965 20 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c26\u0c41\u0c30\u0c4d\u0c17\u0c2e \u0c15\u0c3e\u0c1c \u0c1c\u0c17\u0c24 \u0c15\u0c47 \u0c1c\u0c47\u0c24\u0c47 \u0964 \u0c38\u0c41\u0c17\u0c2e \u0c05\u0c28\u0c41\u0c17\u0c4d\u0c30\u0c39 \u0c24\u0c41\u0c2e\u0c4d\u0c39\u0c30\u0c47 \u0c24\u0c47\u0c24\u0c47 \u0965 \u0c68\u0c66 \u0965", "tamil": "\u0ba4\u0bc1\u0bb0\u0bcd\u0b95\u0bae \u0b95\u0bbe\u0b9c \u0b9c\u0b95\u0ba4 \u0b95\u0bc7 \u0b9c\u0bc7\u0ba4\u0bc7 \u0964 \u0bb8\u0bc1\u0b95\u0bae \u0b85\u0ba8\u0bc1\u0b95\u0bcd\u0bb0\u0bb9 \u0ba4\u0bc1\u0bae\u0bcd\u0bb9\u0bb0\u0bc7 \u0ba4\u0bc7\u0ba4\u0bc7 \u0965 \u0be8\u0be6 \u0965", "kannada": "\u0ca6\u0cc1\u0cb0\u0ccd\u0c97\u0cae \u0c95\u0cbe\u0c9c \u0c9c\u0c97\u0ca4 \u0c95\u0cc7 \u0c9c\u0cc7\u0ca4\u0cc7 \u0964 \u0cb8\u0cc1\u0c97\u0cae \u0c85\u0ca8\u0cc1\u0c97\u0ccd\u0cb0\u0cb9 \u0ca4\u0cc1\u0cae\u0ccd\u0cb9\u0cb0\u0cc7 \u0ca4\u0cc7\u0ca4\u0cc7 \u0965 \u0ce8\u0ce6 \u0965", "malayalam": "\u0d26\u0d41\u0d30\u0d4d\u0d17\u0d2e \u0d15\u0d3e\u0d1c \u0d1c\u0d17\u0d24 \u0d15\u0d47 \u0d1c\u0d47\u0d24\u0d47 \u0964 \u0d38\u0d41\u0d17\u0d2e \u0d05\u0d28\u0d41\u0d17\u0d4d\u0d30\u0d39 \u0d24\u0d41\u0d2e\u0d4d\u0d39\u0d30\u0d47 \u0d24\u0d47\u0d24\u0d47 \u0965 \u0d68\u0d66 \u0965"},
        draftTranslation: "All arduous tasks in this world become effortlessly accomplished by Your divine grace.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 23,
        devanagariText: "\u0930\u093e\u092e \u0926\u0941\u0906\u0930\u0947 \u0924\u0941\u092e \u0930\u0916\u0935\u093e\u0930\u0947 \u0964 \u0939\u094b\u0924 \u0928 \u0906\u091c\u094d\u091e\u093e \u092c\u093f\u0928\u0941 \u092a\u0948\u0938\u093e\u0930\u0947 \u0965 \u0968\u0967 \u0965",
        iastText: "r\u0101ma du\u0101r\u0113 tuma rakhav\u0101r\u0113 \u0964 h\u014dta na \u0101j\u00f1\u0101 binu pais\u0101r\u0113 \u0965 21 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c30\u0c3e\u0c2e \u0c26\u0c41\u0c06\u0c30\u0c47 \u0c24\u0c41\u0c2e \u0c30\u0c16\u0c35\u0c3e\u0c30\u0c47 \u0964 \u0c39\u0c4b\u0c24 \u0c28 \u0c06\u0c1c\u0c4d\u0c1e\u0c3e \u0c2c\u0c3f\u0c28\u0c41 \u0c2a\u0c48\u0c38\u0c3e\u0c30\u0c47 \u0965 \u0c68\u0c67 \u0965", "tamil": "\u0bb0\u0bbe\u0bae \u0ba4\u0bc1\u0b86\u0bb0\u0bc7 \u0ba4\u0bc1\u0bae \u0bb0\u0b95\u0bb5\u0bbe\u0bb0\u0bc7 \u0964 \u0bb9\u0bcb\u0ba4 \u0ba8 \u0b86\u0b9c\u0bcd\u0b9e\u0bbe \u0baa\u0bbf\u0ba8\u0bc1 \u0baa\u0bc8\u0bb8\u0bbe\u0bb0\u0bc7 \u0965 \u0be8\u0be7 \u0965", "kannada": "\u0cb0\u0cbe\u0cae \u0ca6\u0cc1\u0c86\u0cb0\u0cc7 \u0ca4\u0cc1\u0cae \u0cb0\u0c96\u0cb5\u0cbe\u0cb0\u0cc7 \u0964 \u0cb9\u0ccb\u0ca4 \u0ca8 \u0c86\u0c9c\u0ccd\u0c9e\u0cbe \u0cac\u0cbf\u0ca8\u0cc1 \u0caa\u0cc8\u0cb8\u0cbe\u0cb0\u0cc7 \u0965 \u0ce8\u0ce7 \u0965", "malayalam": "\u0d30\u0d3e\u0d2e \u0d26\u0d41\u0d06\u0d30\u0d47 \u0d24\u0d41\u0d2e \u0d30\u0d16\u0d35\u0d3e\u0d30\u0d47 \u0964 \u0d39\u0d4b\u0d24 \u0d28 \u0d06\u0d1c\u0d4d\u0d1e\u0d3e \u0d2c\u0d3f\u0d28\u0d41 \u0d2a\u0d48\u0d38\u0d3e\u0d30\u0d47 \u0965 \u0d68\u0d67 \u0965"},
        draftTranslation: "You are the gatekeeper at Rama's portal; no one can enter without Your sanction.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 24,
        devanagariText: "\u0938\u092c \u0938\u0941\u0916 \u0932\u0939\u0948 \u0924\u0941\u092e\u094d\u0939\u093e\u0930\u0940 \u0938\u0930\u0928\u093e \u0964 \u0924\u0941\u092e \u0930\u0915\u094d\u0937\u0915 \u0915\u093e\u0939\u0942 \u0915\u094b \u0921\u0930 \u0928\u093e \u0965 \u0968\u0968 \u0965",
        iastText: "saba sukha lahai tumh\u0101r\u012b saran\u0101 \u0964 tuma rak\u1e63aka k\u0101h\u016b k\u014d \u1e0dara n\u0101 \u0965 22 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c38\u0c2c \u0c38\u0c41\u0c16 \u0c32\u0c39\u0c48 \u0c24\u0c41\u0c2e\u0c4d\u0c39\u0c3e\u0c30\u0c40 \u0c38\u0c30\u0c28\u0c3e \u0964 \u0c24\u0c41\u0c2e \u0c30\u0c15\u0c4d\u0c37\u0c15 \u0c15\u0c3e\u0c39\u0c42 \u0c15\u0c4b \u0c21\u0c30 \u0c28\u0c3e \u0965 \u0c68\u0c68 \u0965", "tamil": "\u0bb8\u0baa \u0bb8\u0bc1\u0b95 \u0bb2\u0bb9\u0bc8 \u0ba4\u0bc1\u0bae\u0bcd\u0bb9\u0bbe\u0bb0\u0bc0 \u0bb8\u0bb0\u0ba8\u0bbe \u0964 \u0ba4\u0bc1\u0bae \u0bb0\u0b95\u0bcd\u0bb7\u0b95 \u0b95\u0bbe\u0bb9\u0bc2 \u0b95\u0bcb \u0b9f\u0bb0 \u0ba8\u0bbe \u0965 \u0be8\u0be8 \u0965", "kannada": "\u0cb8\u0cac \u0cb8\u0cc1\u0c96 \u0cb2\u0cb9\u0cc8 \u0ca4\u0cc1\u0cae\u0ccd\u0cb9\u0cbe\u0cb0\u0cc0 \u0cb8\u0cb0\u0ca8\u0cbe \u0964 \u0ca4\u0cc1\u0cae \u0cb0\u0c95\u0ccd\u0cb7\u0c95 \u0c95\u0cbe\u0cb9\u0cc2 \u0c95\u0ccb \u0ca1\u0cb0 \u0ca8\u0cbe \u0965 \u0ce8\u0ce8 \u0965", "malayalam": "\u0d38\u0d2c \u0d38\u0d41\u0d16 \u0d32\u0d39\u0d48 \u0d24\u0d41\u0d2e\u0d4d\u0d39\u0d3e\u0d30\u0d40 \u0d38\u0d30\u0d28\u0d3e \u0964 \u0d24\u0d41\u0d2e \u0d30\u0d15\u0d4d\u0d37\u0d15 \u0d15\u0d3e\u0d39\u0d42 \u0d15\u0d4b \u0d21\u0d30 \u0d28\u0d3e \u0965 \u0d68\u0d68 \u0965"},
        draftTranslation: "All joy is attained under Your shelter; when You are the protector, who can fear anything?",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 25,
        devanagariText: "\u0906\u092a\u0928 \u0924\u0947\u091c \u0938\u092e\u094d\u0939\u093e\u0930\u094b \u0906\u092a\u0948 \u0964 \u0924\u0940\u0928\u094b\u0902 \u0932\u094b\u0915 \u0939\u093e\u0901\u0915 \u0924\u0947\u0902 \u0915\u093e\u0901\u092a\u0948 \u0965 \u0968\u0969 \u0965",
        iastText: "\u0101pana t\u0113ja samh\u0101r\u014d \u0101pai \u0964 t\u012bn\u014d\u1e41 l\u014dka h\u0101m\u0310ka t\u0113\u1e41 k\u0101m\u0310pai \u0965 23 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c06\u0c2a\u0c28 \u0c24\u0c47\u0c1c \u0c38\u0c2e\u0c4d\u0c39\u0c3e\u0c30\u0c4b \u0c06\u0c2a\u0c48 \u0964 \u0c24\u0c40\u0c28\u0c4b\u0c02 \u0c32\u0c4b\u0c15 \u0c39\u0c3e\u0c01\u0c15 \u0c24\u0c47\u0c02 \u0c15\u0c3e\u0c01\u0c2a\u0c48 \u0965 \u0c68\u0c69 \u0965", "tamil": "\u0b86\u0baa\u0ba8 \u0ba4\u0bc7\u0b9c \u0bb8\u0bae\u0bcd\u0bb9\u0bbe\u0bb0\u0bcb \u0b86\u0baa\u0bc8 \u0964 \u0ba4\u0bc0\u0ba8\u0bcb\u0bae\u0bcd \u0bb2\u0bcb\u0b95 \u0bb9\u0bbe\u0901\u0b95 \u0ba4\u0bc7\u0bae\u0bcd \u0b95\u0bbe\u0901\u0baa\u0bc8 \u0965 \u0be8\u0be9 \u0965", "kannada": "\u0c86\u0caa\u0ca8 \u0ca4\u0cc7\u0c9c \u0cb8\u0cae\u0ccd\u0cb9\u0cbe\u0cb0\u0ccb \u0c86\u0caa\u0cc8 \u0964 \u0ca4\u0cc0\u0ca8\u0ccb\u0c82 \u0cb2\u0ccb\u0c95 \u0cb9\u0cbe\u0c81\u0c95 \u0ca4\u0cc7\u0c82 \u0c95\u0cbe\u0c81\u0caa\u0cc8 \u0965 \u0ce8\u0ce9 \u0965", "malayalam": "\u0d06\u0d2a\u0d28 \u0d24\u0d47\u0d1c \u0d38\u0d2e\u0d4d\u0d39\u0d3e\u0d30\u0d4b \u0d06\u0d2a\u0d48 \u0964 \u0d24\u0d40\u0d28\u0d4b\u0d02 \u0d32\u0d4b\u0d15 \u0d39\u0d3e\u0d01\u0d15 \u0d24\u0d47\u0d02 \u0d15\u0d3e\u0d01\u0d2a\u0d48 \u0965 \u0d68\u0d69 \u0965"},
        draftTranslation: "You alone can withstand Your immense radiance; all three worlds tremble when You roar!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 26,
        devanagariText: "\u092d\u0942\u0924 \u092a\u093f\u0938\u093e\u091a \u0928\u093f\u0915\u091f \u0928\u0939\u093f\u0902 \u0906\u0935\u0948 \u0964 \u092e\u0939\u093e\u092c\u0940\u0930 \u091c\u092c \u0928\u093e\u092e \u0938\u0941\u0928\u093e\u0935\u0948 \u0965 \u0968\u096a \u0965",
        iastText: "bh\u016bta pis\u0101ca nika\u1e6da nahi\u1e41 \u0101vai \u0964 mah\u0101b\u012bra jaba n\u0101ma sun\u0101vai \u0965 24 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c2d\u0c42\u0c24 \u0c2a\u0c3f\u0c38\u0c3e\u0c1a \u0c28\u0c3f\u0c15\u0c1f \u0c28\u0c39\u0c3f\u0c02 \u0c06\u0c35\u0c48 \u0964 \u0c2e\u0c39\u0c3e\u0c2c\u0c40\u0c30 \u0c1c\u0c2c \u0c28\u0c3e\u0c2e \u0c38\u0c41\u0c28\u0c3e\u0c35\u0c48 \u0965 \u0c68\u0c6a \u0965", "tamil": "\u0baa\u0bc2\u0ba4 \u0baa\u0bbf\u0bb8\u0bbe\u0b9a \u0ba8\u0bbf\u0b95\u0b9f \u0ba8\u0bb9\u0bbf\u0bae\u0bcd \u0b86\u0bb5\u0bc8 \u0964 \u0bae\u0bb9\u0bbe\u0baa\u0bc0\u0bb0 \u0b9c\u0baa \u0ba8\u0bbe\u0bae \u0bb8\u0bc1\u0ba8\u0bbe\u0bb5\u0bc8 \u0965 \u0be8\u0bea \u0965", "kannada": "\u0cad\u0cc2\u0ca4 \u0caa\u0cbf\u0cb8\u0cbe\u0c9a \u0ca8\u0cbf\u0c95\u0c9f \u0ca8\u0cb9\u0cbf\u0c82 \u0c86\u0cb5\u0cc8 \u0964 \u0cae\u0cb9\u0cbe\u0cac\u0cc0\u0cb0 \u0c9c\u0cac \u0ca8\u0cbe\u0cae \u0cb8\u0cc1\u0ca8\u0cbe\u0cb5\u0cc8 \u0965 \u0ce8\u0cea \u0965", "malayalam": "\u0d2d\u0d42\u0d24 \u0d2a\u0d3f\u0d38\u0d3e\u0d1a \u0d28\u0d3f\u0d15\u0d1f \u0d28\u0d39\u0d3f\u0d02 \u0d06\u0d35\u0d48 \u0964 \u0d2e\u0d39\u0d3e\u0d2c\u0d40\u0d30 \u0d1c\u0d2c \u0d28\u0d3e\u0d2e \u0d38\u0d41\u0d28\u0d3e\u0d35\u0d48 \u0965 \u0d68\u0d6a \u0965"},
        draftTranslation: "Ghosts and evil spirits dare not approach when the name of Mahavira is uttered.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 27,
        devanagariText: "\u0928\u093e\u0938\u0948 \u0930\u094b\u0917 \u0939\u0930\u0948 \u0938\u092c \u092a\u0940\u0930\u093e \u0964 \u091c\u092a\u0924 \u0928\u093f\u0930\u0928\u094d\u0924\u0930 \u0939\u0928\u0941\u092e\u0924 \u092c\u0940\u0930\u093e \u0965 \u0968\u096b \u0965",
        iastText: "n\u0101sai r\u014dga harai saba p\u012br\u0101 \u0964 japata nirantara hanumata b\u012br\u0101 \u0965 25 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c28\u0c3e\u0c38\u0c48 \u0c30\u0c4b\u0c17 \u0c39\u0c30\u0c48 \u0c38\u0c2c \u0c2a\u0c40\u0c30\u0c3e \u0964 \u0c1c\u0c2a\u0c24 \u0c28\u0c3f\u0c30\u0c28\u0c4d\u0c24\u0c30 \u0c39\u0c28\u0c41\u0c2e\u0c24 \u0c2c\u0c40\u0c30\u0c3e \u0965 \u0c68\u0c6b \u0965", "tamil": "\u0ba8\u0bbe\u0bb8\u0bc8 \u0bb0\u0bcb\u0b95 \u0bb9\u0bb0\u0bc8 \u0bb8\u0baa \u0baa\u0bc0\u0bb0\u0bbe \u0964 \u0b9c\u0baa\u0ba4 \u0ba8\u0bbf\u0bb0\u0ba8\u0bcd\u0ba4\u0bb0 \u0bb9\u0ba8\u0bc1\u0bae\u0ba4 \u0baa\u0bc0\u0bb0\u0bbe \u0965 \u0be8\u0beb \u0965", "kannada": "\u0ca8\u0cbe\u0cb8\u0cc8 \u0cb0\u0ccb\u0c97 \u0cb9\u0cb0\u0cc8 \u0cb8\u0cac \u0caa\u0cc0\u0cb0\u0cbe \u0964 \u0c9c\u0caa\u0ca4 \u0ca8\u0cbf\u0cb0\u0ca8\u0ccd\u0ca4\u0cb0 \u0cb9\u0ca8\u0cc1\u0cae\u0ca4 \u0cac\u0cc0\u0cb0\u0cbe \u0965 \u0ce8\u0ceb \u0965", "malayalam": "\u0d28\u0d3e\u0d38\u0d48 \u0d30\u0d4b\u0d17 \u0d39\u0d30\u0d48 \u0d38\u0d2c \u0d2a\u0d40\u0d30\u0d3e \u0964 \u0d1c\u0d2a\u0d24 \u0d28\u0d3f\u0d30\u0d28\u0d4d\u0d24\u0d30 \u0d39\u0d28\u0d41\u0d2e\u0d24 \u0d2c\u0d40\u0d30\u0d3e \u0965 \u0d68\u0d6b \u0965"},
        draftTranslation: "All diseases perish and all grief vanishes when one constantly chants the name of courageous Hanuman.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 28,
        devanagariText: "\u0938\u0919\u094d\u0915\u091f \u0924\u0947\u0902 \u0939\u0928\u0941\u092e\u093e\u0928 \u091b\u0941\u0921\u093c\u093e\u0935\u0948 \u0964 \u092e\u0928 \u0915\u094d\u0930\u092e \u092c\u091a\u0928 \u0927\u094d\u092f\u093e\u0928 \u091c\u094b \u0932\u093e\u0935\u0948 \u0965 \u0968\u096c \u0965",
        iastText: "sa\u1e45ka\u1e6da t\u0113\u1e41 hanum\u0101na chu\u1e5b\u0101vai \u0964 mana krama bacana dhy\u0101na j\u014d l\u0101vai \u0965 26 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c38\u0c19\u0c4d\u0c15\u0c1f \u0c24\u0c47\u0c02 \u0c39\u0c28\u0c41\u0c2e\u0c3e\u0c28 \u0c1b\u0c41\u0921\u093c\u0c3e\u0c35\u0c48 \u0964 \u0c2e\u0c28 \u0c15\u0c4d\u0c30\u0c2e \u0c2c\u0c1a\u0c28 \u0c27\u0c4d\u0c2f\u0c3e\u0c28 \u0c1c\u0c4b \u0c32\u0c3e\u0c35\u0c48 \u0965 \u0c68\u0c6c \u0965", "tamil": "\u0bb8\u0b99\u0bcd\u0b95\u0b9f \u0ba4\u0bc7\u0bae\u0bcd \u0bb9\u0ba8\u0bc1\u0bae\u0bbe\u0ba8 \u0b9a\u0bc1\u0b83\u0b9f\u00b2\u0bbe\u0bb5\u0bc8 \u0964 \u0bae\u0ba8 \u0b95\u0bcd\u0bb0\u0bae \u0baa\u0b9a\u0ba8 \u0ba4\u0bcd\u0baf\u0bbe\u0ba8 \u0b9c\u0bcb \u0bb2\u0bbe\u0bb5\u0bc8 \u0965 \u0be8\u0bec \u0965", "kannada": "\u0cb8\u0c99\u0ccd\u0c95\u0c9f \u0ca4\u0cc7\u0c82 \u0cb9\u0ca8\u0cc1\u0cae\u0cbe\u0ca8 \u0c9b\u0cc1\u0ca1\u0cbc\u0cbe\u0cb5\u0cc8 \u0964 \u0cae\u0ca8 \u0c95\u0ccd\u0cb0\u0cae \u0cac\u0c9a\u0ca8 \u0ca7\u0ccd\u0caf\u0cbe\u0ca8 \u0c9c\u0ccb \u0cb2\u0cbe\u0cb5\u0cc8 \u0965 \u0ce8\u0cec \u0965", "malayalam": "\u0d38\u0d19\u0d4d\u0d15\u0d1f \u0d24\u0d47\u0d02 \u0d39\u0d28\u0d41\u0d2e\u0d3e\u0d28 \u0d1b\u0d41\u0921\u093c\u0d3e\u0d35\u0d48 \u0964 \u0d2e\u0d28 \u0d15\u0d4d\u0d30\u0d2e \u0d2c\u0d1a\u0d28 \u0d27\u0d4d\u0d2f\u0d3e\u0d28 \u0d1c\u0d4b \u0d32\u0d3e\u0d35\u0d48 \u0965 \u0d68\u0d6c \u0965"},
        draftTranslation: "Hanuman liberates from all distress those who meditate on Him in thought, deed, and word.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 29,
        devanagariText: "\u0938\u092c \u092a\u0930 \u0930\u093e\u092e \u0924\u092a\u0938\u094d\u0935\u0940 \u0930\u093e\u091c\u093e \u0964 \u0924\u093f\u0928 \u0915\u0947 \u0915\u093e\u091c \u0938\u0915\u0932 \u0924\u0941\u092e \u0938\u093e\u091c\u093e \u0965 \u0968\u096d \u0965",
        iastText: "saba para r\u0101ma tapasv\u012b r\u0101j\u0101 \u0964 tina k\u0113 k\u0101ja sakala tuma s\u0101j\u0101 \u0965 27 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c38\u0c2c \u0c2a\u0c30 \u0c30\u0c3e\u0c2e \u0c24\u0c2a\u0c38\u0c4d\u0c35\u0c40 \u0c30\u0c3e\u0c1c\u0c3e \u0964 \u0c24\u0c3f\u0c28 \u0c15\u0c47 \u0c15\u0c3e\u0c1c \u0c38\u0c15\u0c32 \u0c24\u0c41\u0c2e \u0c38\u0c3e\u0c1c\u0c3e \u0965 \u0c68\u0c6d \u0965", "tamil": "\u0bb8\u0baa \u0baa\u0bb0 \u0bb0\u0bbe\u0bae \u0ba4\u0baa\u0bb8\u0bcd\u0bb5\u0bc0 \u0bb0\u0bbe\u0b9c\u0bbe \u0964 \u0ba4\u0bbf\u0ba8 \u0b95\u0bc7 \u0b95\u0bbe\u0b9c \u0bb8\u0b95\u0bb2 \u0ba4\u0bc1\u0bae \u0bb8\u0bbe\u0b9c\u0bbe \u0965 \u0be8\u0bed \u0965", "kannada": "\u0cb8\u0cac \u0caa\u0cb0 \u0cb0\u0cbe\u0cae \u0ca4\u0caa\u0cb8\u0ccd\u0cb5\u0cc0 \u0cb0\u0cbe\u0c9c\u0cbe \u0964 \u0ca4\u0cbf\u0ca8 \u0c95\u0cc7 \u0c95\u0cbe\u0c9c \u0cb8\u0c95\u0cb2 \u0ca4\u0cc1\u0cae \u0cb8\u0cbe\u0c9c\u0cbe \u0965 \u0ce8\u0ced \u0965", "malayalam": "\u0d38\u0d2c \u0d2a\u0d30 \u0d30\u0d3e\u0d2e \u0d24\u0d2a\u0d38\u0d4d\u0d35\u0d40 \u0d30\u0d3e\u0d1c\u0d3e \u0964 \u0d24\u0d3f\u0d28 \u0d15\u0d47 \u0d15\u0d3e\u0d1c \u0d38\u0d15\u0d32 \u0d24\u0d41\u0d2e \u0d38\u0d3e\u0d1c\u0d3e \u0965 \u0d68\u0d6d \u0965"},
        draftTranslation: "Supreme over all is Rama, the ascetic Sovereign; You accomplished every task on His behalf.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 30,
        devanagariText: "\u0914\u0930 \u092e\u0928\u094b\u0930\u0925 \u091c\u094b \u0915\u094b\u0908 \u0932\u093e\u0935\u0948 \u0964 \u0938\u094b\u0907 \u0905\u092e\u093f\u0924 \u091c\u0940\u0935\u0928 \u092b\u0932 \u092a\u093e\u0935\u0948 \u0965 \u0968\u096e \u0965",
        iastText: "aura man\u014dratha j\u014d k\u014d\u012b l\u0101vai \u0964 s\u014di amita j\u012bvana phala p\u0101vai \u0965 28 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c14\u0c30 \u0c2e\u0c28\u0c4b\u0c30\u0c25 \u0c1c\u0c4b \u0c15\u0c4b\u0c08 \u0c32\u0c3e\u0c35\u0c48 \u0964 \u0c38\u0c4b\u0c07 \u0c05\u0c2e\u0c3f\u0c24 \u0c1c\u0c40\u0c35\u0c28 \u0c2b\u0c32 \u0c2a\u0c3e\u0c35\u0c48 \u0965 \u0c68\u0c6e \u0965", "tamil": "\u0b94\u0bb0 \u0bae\u0ba8\u0bcb\u0bb0\u0ba4 \u0b9c\u0bcb \u0b95\u0bcb\u0b88 \u0bb2\u0bbe\u0bb5\u0bc8 \u0964 \u0bb8\u0bcb\u0b87 \u0b85\u0bae\u0bbf\u0ba4 \u0b9c\u0bc0\u0bb5\u0ba8 \u0baa\u0bb2 \u0baa\u0bbe\u0bb5\u0bc8 \u0965 \u0be8\u0bee \u0965", "kannada": "\u0c94\u0cb0 \u0cae\u0ca8\u0ccb\u0cb0\u0ca5 \u0c9c\u0ccb \u0c95\u0ccb\u0c88 \u0cb2\u0cbe\u0cb5\u0cc8 \u0964 \u0cb8\u0ccb\u0c87 \u0c85\u0cae\u0cbf\u0ca4 \u0c9c\u0cc0\u0cb5\u0ca8 \u0cab\u0cb2 \u0caa\u0cbe\u0cb5\u0cc8 \u0965 \u0ce8\u0cee \u0965", "malayalam": "\u0d14\u0d30 \u0d2e\u0d28\u0d4b\u0d30\u0d25 \u0d1c\u0d4b \u0d15\u0d4b\u0d08 \u0d32\u0d3e\u0d35\u0d48 \u0964 \u0d38\u0d4b\u0d07 \u0d05\u0d2e\u0d3f\u0d24 \u0d1c\u0d40\u0d35\u0d28 \u0d2b\u0d32 \u0d2a\u0d3e\u0d35\u0d48 \u0965 \u0d68\u0d6e \u0965"},
        draftTranslation: "Whatever wish anyone brings before You, he secures the inexhaustible fruit of life.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 31,
        devanagariText: "\u091a\u093e\u0930\u094b\u0902 \u091c\u0941\u0917 \u092a\u0930\u0924\u093e\u092a \u0924\u0941\u092e\u094d\u0939\u093e\u0930\u093e \u0964 \u0939\u0948 \u092a\u0930\u0938\u093f\u0926\u094d\u0927 \u091c\u0917\u0924 \u0909\u091c\u093f\u092f\u093e\u0930\u093e \u0965 \u0968\u096f \u0965",
        iastText: "c\u0101r\u014d\u1e41 juga parat\u0101pa tumh\u0101r\u0101 \u0964 hai parasiddha jagata ujiy\u0101r\u0101 \u0965 29 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c1a\u0c3e\u0c30\u0c4b\u0c02 \u0c1c\u0c41\u0c17 \u0c2a\u0c30\u0c24\u0c3e\u0c2a \u0c24\u0c41\u0c2e\u0c4d\u0c39\u0c3e\u0c30\u0c3e \u0964 \u0c39\u0c48 \u0c2a\u0c30\u0c38\u0c3f\u0c26\u0c4d\u0c27 \u0c1c\u0c17\u0c24 \u0c09\u0c1c\u0c3f\u0c2f\u0c3e\u0c30\u0c3e \u0965 \u0c68\u0c6f \u0965", "tamil": "\u0b9a\u0bbe\u0bb0\u0bcb\u0bae\u0bcd \u0b9c\u0bc1\u0b95 \u0baa\u0bb0\u0ba4\u0bbe\u0baa \u0ba4\u0bc1\u0bae\u0bcd\u0bb9\u0bbe\u0bb0\u0bbe \u0964 \u0bb9\u0bc8 \u0baa\u0bb0\u0bb8\u0bbf\u0ba4\u0bcd\u0ba4 \u0b9c\u0b95\u0ba4 \u0b89\u0b9c\u0bbf\u0baf\u0bbe\u0bb0\u0bbe \u0965 \u0be8\u0bef \u0965", "kannada": "\u0c9a\u0cbe\u0cb0\u0ccb\u0c82 \u0c9c\u0cc1\u0c97 \u0caa\u0cb0\u0ca4\u0cbe\u0caa \u0ca4\u0cc1\u0cae\u0ccd\u0cb9\u0cbe\u0cb0\u0cbe \u0964 \u0cb9\u0cc8 \u0caa\u0cb0\u0cb8\u0cbf\u0ca6\u0ccd\u0ca7 \u0c9c\u0c97\u0ca4 \u0c89\u0c9c\u0cbf\u0caf\u0cbe\u0cb0\u0cbe \u0965 \u0ce8\u0cef \u0965", "malayalam": "\u0d1a\u0d3e\u0d30\u0d4b\u0d02 \u0d1c\u0d41\u0d17 \u0d2a\u0d30\u0d24\u0d3e\u0d2a \u0d24\u0d41\u0d2e\u0d4d\u0d39\u0d3e\u0d30\u0d3e \u0964 \u0d39\u0d48 \u0d2a\u0d30\u0d38\u0d3f\u0d26\u0d4d\u0d27 \u0d1c\u0d17\u0d24 \u0d09\u0d1c\u0d3f\u0d2f\u0d3e\u0d30\u0d3e \u0965 \u0d68\u0d6f \u0965"},
        draftTranslation: "Your glory shines across all four Yugas; Your renown is celebrated as illumination for the world.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 32,
        devanagariText: "\u0938\u093e\u0927\u0941 \u0938\u0928\u094d\u0924 \u0915\u0947 \u0924\u0941\u092e \u0930\u0916\u0935\u093e\u0930\u0947 \u0964 \u0905\u0938\u0941\u0930 \u0928\u093f\u0915\u0928\u094d\u0926\u0928 \u0930\u093e\u092e \u0926\u0941\u0932\u093e\u0930\u0947 \u0965 \u0969\u0966 \u0965",
        iastText: "s\u0101dhu santa k\u0113 tuma rakhav\u0101r\u0113 \u0964 asura nikandana r\u0101ma dul\u0101r\u0113 \u0965 30 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c38\u0c3e\u0c27\u0c41 \u0c38\u0c28\u0c4d\u0c24 \u0c15\u0c47 \u0c24\u0c41\u0c2e \u0c30\u0c16\u0c35\u0c3e\u0c30\u0c47 \u0964 \u0c05\u0c38\u0c41\u0c30 \u0c28\u0c3f\u0c15\u0c28\u0c4d\u0c26\u0c28 \u0c30\u0c3e\u0c2e \u0c26\u0c41\u0c32\u0c3e\u0c30\u0c47 \u0965 \u0c69\u0c66 \u0965", "tamil": "\u0bb8\u0bbe\u0ba4\u0bc1 \u0bb8\u0ba8\u0bcd\u0ba4 \u0b95\u0bc7 \u0ba4\u0bc1\u0bae \u0bb0\u0b95\u0bb5\u0bbe\u0bb0\u0bc7 \u0964 \u0b85\u0bb8\u0bc1\u0bb0 \u0ba8\u0bbf\u0b95\u0ba8\u0bcd\u0ba4\u0ba8 \u0bb0\u0bbe\u0bae \u0ba4\u0bc1\u0bb2\u0bbe\u0bb0\u0bc7 \u0965 \u0be9\u0be6 \u0965", "kannada": "\u0cb8\u0cbe\u0ca7\u0cc1 \u0cb8\u0ca8\u0ccd\u0ca4 \u0c95\u0cc7 \u0ca4\u0cc1\u0cae \u0cb0\u0c96\u0cb5\u0cbe\u0cb0\u0cc7 \u0964 \u0c85\u0cb8\u0cc1\u0cb0 \u0ca8\u0cbf\u0c95\u0ca8\u0ccd\u0ca6\u0ca8 \u0cb0\u0cbe\u0cae \u0ca6\u0cc1\u0cb2\u0cbe\u0cb0\u0cc7 \u0965 \u0ce9\u0ce6 \u0965", "malayalam": "\u0d38\u0d3e\u0d27\u0d41 \u0d38\u0d28\u0d4d\u0d24 \u0d15\u0d47 \u0d24\u0d41\u0d2e \u0d30\u0d16\u0d35\u0d3e\u0d30\u0d47 \u0964 \u0d05\u0d38\u0d41\u0d30 \u0d28\u0d3f\u0d15\u0d28\u0d4d\u0d26\u0d28 \u0d30\u0d3e\u0d2e \u0d26\u0d41\u0d32\u0d3e\u0d30\u0d47 \u0965 \u0d69\u0d66 \u0965"},
        draftTranslation: "You are the guardian of saints and ascetics, slayer of demons, darling of Sri Rama.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 33,
        devanagariText: "\u0905\u0937\u094d\u091f \u0938\u093f\u0926\u094d\u0927\u093f \u0928\u094c \u0928\u093f\u0927\u093f \u0915\u0947 \u0926\u093e\u0924\u093e \u0964 \u0905\u0938 \u092c\u0930 \u0926\u0940\u0928 \u091c\u093e\u0928\u0915\u0940 \u092e\u093e\u0924\u093e \u0965 \u0969\u0967 \u0965",
        iastText: "a\u1e63\u1e6da siddhi nau nidhi k\u0113 d\u0101t\u0101 \u0964 asa bara d\u012bna j\u0101nak\u012b m\u0101t\u0101 \u0965 31 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c05\u0c37\u0c4d\u0c1f \u0c38\u0c3f\u0c26\u0c4d\u0c27\u0c3f \u0c28\u0c4c \u0c28\u0c3f\u0c27\u0c3f \u0c15\u0c47 \u0c26\u0c3e\u0c24\u0c3e \u0964 \u0c05\u0c38 \u0c2c\u0c30 \u0c26\u0c40\u0c28 \u0c1c\u0c3e\u0c28\u0c15\u0c40 \u0c2e\u0c3e\u0c24\u0c3e \u0965 \u0c69\u0c67 \u0965", "tamil": "\u0b85\u0bb7\u0bcd\u0b9f \u0bb8\u0bbf\u0ba4\u0bcd\u0ba4\u0bbf \u0ba8\u0bcc \u0ba8\u0bbf\u0ba4\u0bbf \u0b95\u0bc7 \u0ba4\u0bbe\u0ba4\u0bbe \u0964 \u0b85\u0bb8 \u0baa\u0bb0 \u0ba4\u0bc0\u0ba8 \u0b9c\u0bbe\u0ba8\u0b95\u0bc0 \u0bae\u0bbe\u0ba4\u0bbe \u0965 \u0be9\u0be7 \u0965", "kannada": "\u0c85\u0cb7\u0ccd\u0c9f \u0cb8\u0cbf\u0ca6\u0ccd\u0ca7\u0cbf \u0ca8\u0ccc \u0ca8\u0cbf\u0ca7\u0cbf \u0c95\u0cc7 \u0ca6\u0cbe\u0ca4\u0cbe \u0964 \u0c85\u0cb8 \u0cac\u0cb0 \u0ca6\u0cc0\u0ca8 \u0c9c\u0cbe\u0ca8\u0c95\u0cc0 \u0cae\u0cbe\u0ca4\u0cbe \u0965 \u0ce9\u0ce7 \u0965", "malayalam": "\u0d05\u0d37\u0d4d\u0d1f \u0d38\u0d3f\u0d26\u0d4d\u0d27\u0d3f \u0d28\u0d4c \u0d28\u0d3f\u0d27\u0d3f \u0d15\u0d47 \u0d26\u0d3e\u0d24\u0d3e \u0964 \u0d05\u0d38 \u0d2c\u0d30 \u0d26\u0d40\u0d28 \u0d1c\u0d3e\u0d28\u0d15\u0d40 \u0d2e\u0d3e\u0d24\u0d3e \u0965 \u0d69\u0d67 \u0965"},
        draftTranslation: "Bestower of the eight spiritual siddhis and nine divine treasures, as blessed by Mother Janaki.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 34,
        devanagariText: "\u0930\u093e\u092e \u0930\u0938\u093e\u092f\u0928 \u0924\u0941\u092e\u094d\u0939\u0930\u0947 \u092a\u093e\u0938\u093e \u0964 \u0938\u0926\u093e \u0930\u0939\u094b \u0930\u0918\u0941\u092a\u0924\u093f \u0915\u0947 \u0926\u093e\u0938\u093e \u0965 \u0969\u0968 \u0965",
        iastText: "r\u0101ma ras\u0101yana tumhar\u0113 p\u0101s\u0101 \u0964 sad\u0101 rah\u014d raghupati k\u0113 d\u0101s\u0101 \u0965 32 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c30\u0c3e\u0c2e \u0c30\u0c38\u0c3e\u0c2f\u0c28 \u0c24\u0c41\u0c2e\u0c4d\u0c39\u0c30\u0c47 \u0c2a\u0c3e\u0c38\u0c3e \u0964 \u0c38\u0c26\u0c3e \u0c30\u0c39\u0c4b \u0c30\u0c18\u0c41\u0c2a\u0c24\u0c3f \u0c15\u0c47 \u0c26\u0c3e\u0c38\u0c3e \u0965 \u0c69\u0c68 \u0965", "tamil": "\u0bb0\u0bbe\u0bae \u0bb0\u0bb8\u0bbe\u0baf\u0ba8 \u0ba4\u0bc1\u0bae\u0bcd\u0bb9\u0bb0\u0bc7 \u0baa\u0bbe\u0bb8\u0bbe \u0964 \u0bb8\u0ba4\u0bbe \u0bb0\u0bb9\u0bcb \u0bb0\u0b95\u0bc1\u0baa\u0ba4\u0bbf \u0b95\u0bc7 \u0ba4\u0bbe\u0bb8\u0bbe \u0965 \u0be9\u0be8 \u0965", "kannada": "\u0cb0\u0cbe\u0cae \u0cb0\u0cb8\u0cbe\u0caf\u0ca8 \u0ca4\u0cc1\u0cae\u0ccd\u0cb9\u0cb0\u0cc7 \u0caa\u0cbe\u0cb8\u0cbe \u0964 \u0cb8\u0ca6\u0cbe \u0cb0\u0cb9\u0ccb \u0cb0\u0c98\u0cc1\u0caa\u0ca4\u0cbf \u0c95\u0cc7 \u0ca6\u0cbe\u0cb8\u0cbe \u0965 \u0ce9\u0ce8 \u0965", "malayalam": "\u0d30\u0d3e\u0d2e \u0d30\u0d38\u0d3e\u0d2f\u0d28 \u0d24\u0d41\u0d2e\u0d4d\u0d39\u0d30\u0d47 \u0d2a\u0d3e\u0d38\u0d3e \u0964 \u0d38\u0d26\u0d3e \u0d30\u0d39\u0d4b \u0d30\u0d18\u0d41\u0d2a\u0d24\u0d3f \u0d15\u0d47 \u0d26\u0d3e\u0d38\u0d3e \u0965 \u0d69\u0d68 \u0965"},
        draftTranslation: "You hold the elixir of Rama's name; You are forever the devoted servant of Raghupati.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 35,
        devanagariText: "\u0924\u0941\u092e\u094d\u0939\u0930\u0947 \u092d\u091c\u0928 \u0930\u093e\u092e \u0915\u094b \u092a\u093e\u0935\u0948 \u0964 \u091c\u0928\u092e \u091c\u0928\u092e \u0915\u0947 \u0926\u0941\u0916 \u092c\u093f\u0938\u0930\u093e\u0935\u0948 \u0965 \u0969\u0969 \u0965",
        iastText: "tumhar\u0113 bhajana r\u0101ma k\u014d p\u0101vai \u0964 janama janama k\u0113 dukha bisar\u0101vai \u0965 33 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c24\u0c41\u0c2e\u0c4d\u0c39\u0c30\u0c47 \u0c2d\u0c1c\u0c28 \u0c30\u0c3e\u0c2e \u0c15\u0c4b \u0c2a\u0c3e\u0c35\u0c48 \u0964 \u0c1c\u0c28\u0c2e \u0c1c\u0c28\u0c2e \u0c15\u0c47 \u0c26\u0c41\u0c16 \u0c2c\u0c3f\u0c38\u0c30\u0c3e\u0c35\u0c48 \u0965 \u0c69\u0c69 \u0965", "tamil": "\u0ba4\u0bc1\u0bae\u0bcd\u0bb9\u0bb0\u0bc7 \u0baa\u0b9c\u0ba8 \u0bb0\u0bbe\u0bae \u0b95\u0bcb \u0baa\u0bbe\u0bb5\u0bc8 \u0964 \u0b9c\u0ba8\u0bae \u0b9c\u0ba8\u0bae \u0b95\u0bc7 \u0ba4\u0bc1\u0b95 \u0baa\u0bbf\u0bb8\u0bb0\u0bbe\u0bb5\u0bc8 \u0965 \u0be9\u0be9 \u0965", "kannada": "\u0ca4\u0cc1\u0cae\u0ccd\u0cb9\u0cb0\u0cc7 \u0cad\u0c9c\u0ca8 \u0cb0\u0cbe\u0cae \u0c95\u0ccb \u0caa\u0cbe\u0cb5\u0cc8 \u0964 \u0c9c\u0ca8\u0cae \u0c9c\u0ca8\u0cae \u0c95\u0cc7 \u0ca6\u0cc1\u0c96 \u0cac\u0cbf\u0cb8\u0cb0\u0cbe\u0cb5\u0cc8 \u0965 \u0ce9\u0ce9 \u0965", "malayalam": "\u0d24\u0d41\u0d2e\u0d4d\u0d39\u0d30\u0d47 \u0d2d\u0d1c\u0d28 \u0d30\u0d3e\u0d2e \u0d15\u0d4b \u0d2a\u0d3e\u0d35\u0d48 \u0964 \u0d1c\u0d28\u0d2e \u0d1c\u0d28\u0d2e \u0d15\u0d47 \u0d26\u0d41\u0d16 \u0d2c\u0d3f\u0d38\u0d30\u0d3e\u0d35\u0d48 \u0965 \u0d69\u0d69 \u0965"},
        draftTranslation: "Through devotion to You, one reaches Sri Rama and sheds the sorrows of countless lifetimes.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 36,
        devanagariText: "\u0905\u0928\u094d\u0924 \u0915\u093e\u0932 \u0930\u0918\u0941\u092c\u0930 \u092a\u0941\u0930 \u091c\u093e\u0908 \u0964 \u091c\u0939\u093e\u0901 \u091c\u0928\u094d\u092e \u0939\u0930\u093f-\u092d\u0915\u094d\u0924 \u0915\u0939\u093e\u0908 \u0965 \u0969\u096a \u0965",
        iastText: "anta k\u0101la raghubara pura j\u0101\u012b \u0964 jah\u0101m\u0310 janma hari-bhakta kah\u0101\u012b \u0965 34 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c05\u0c28\u0c4d\u0c24 \u0c15\u0c3e\u0c32 \u0c30\u0c18\u0c41\u0c2c\u0c30 \u0c2a\u0c41\u0c30 \u0c1c\u0c3e\u0c08 \u0964 \u0c1c\u0c39\u0c3e\u0c01 \u0c1c\u0c28\u0c4d\u0c2e \u0c39\u0c30\u0c3f-\u0c2d\u0c15\u0c4d\u0c24 \u0c15\u0c39\u0c3e\u0c08 \u0965 \u0c69\u0c6a \u0965", "tamil": "\u0b85\u0ba8\u0bcd\u0ba4 \u0b95\u0bbe\u0bb2 \u0bb0\u0b95\u0bc1\u0baa\u0bb0 \u0baa\u0bc1\u0bb0 \u0b9c\u0bbe\u0b88 \u0964 \u0b9c\u0bb9\u0bbe\u0901 \u0b9c\u0ba8\u0bcd\u0bae \u0bb9\u0bb0\u0bbf-\u0baa\u0b95\u0bcd\u0ba4 \u0b95\u0bb9\u0bbe\u0b88 \u0965 \u0be9\u0bea \u0965", "kannada": "\u0c85\u0ca8\u0ccd\u0ca4 \u0c95\u0cbe\u0cb2 \u0cb0\u0c98\u0cc1\u0cac\u0cb0 \u0caa\u0cc1\u0cb0 \u0c9c\u0cbe\u0c88 \u0964 \u0c9c\u0cb9\u0cbe\u0c81 \u0c9c\u0ca8\u0ccd\u0cae \u0cb9\u0cb0\u0cbf-\u0cad\u0c95\u0ccd\u0ca4 \u0c95\u0cb9\u0cbe\u0c88 \u0965 \u0ce9\u0cea \u0965", "malayalam": "\u0d05\u0d28\u0d4d\u0d24 \u0d15\u0d3e\u0d32 \u0d30\u0d18\u0d41\u0d2c\u0d30 \u0d2a\u0d41\u0d30 \u0d1c\u0d3e\u0d08 \u0964 \u0d1c\u0d39\u0d3e\u0d01 \u0d1c\u0d28\u0d4d\u0d2e \u0d39\u0d30\u0d3f-\u0d2d\u0d15\u0d4d\u0d24 \u0d15\u0d39\u0d3e\u0d08 \u0965 \u0d69\u0d6a \u0965"},
        draftTranslation: "At the final hour he departs to Raghuvira's supreme abode, remembered forever as Hari's devotee.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 37,
        devanagariText: "\u0914\u0930 \u0926\u0947\u0935\u0924\u093e \u091a\u093f\u0924\u094d\u0924 \u0928 \u0927\u0930\u0908 \u0964 \u0939\u0928\u0941\u092e\u0924 \u0938\u0947\u0907 \u0938\u0930\u094d\u092c \u0938\u0941\u0916 \u0915\u0930\u0908 \u0965 \u0969\u096b \u0965",
        iastText: "aura d\u0113vat\u0101 citta na dhara\u012b \u0964 hanumata s\u0113i sarba sukha kara\u012b \u0965 35 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c14\u0c30 \u0c26\u0c47\u0c35\u0c24\u0c3e \u0c1a\u0c3f\u0c24\u0c4d\u0c24 \u0c28 \u0c27\u0c30\u0c08 \u0964 \u0c39\u0c28\u0c41\u0c2e\u0c24 \u0c38\u0c47\u0c07 \u0c38\u0c30\u0c4d\u0c2c \u0c38\u0c41\u0c16 \u0c15\u0c30\u0c08 \u0965 \u0c69\u0c6b \u0965", "tamil": "\u0b94\u0bb0 \u0ba4\u0bc7\u0bb5\u0ba4\u0bbe \u0b9a\u0bbf\u0ba4\u0bcd\u0ba4 \u0ba8 \u0ba4\u0bb0\u0b88 \u0964 \u0bb9\u0ba8\u0bc1\u0bae\u0ba4 \u0bb8\u0bc7\u0b87 \u0bb8\u0bb0\u0bcd\u0baa \u0bb8\u0bc1\u0b95 \u0b95\u0bb0\u0b88 \u0965 \u0be9\u0beb \u0965", "kannada": "\u0c94\u0cb0 \u0ca6\u0cc7\u0cb5\u0ca4\u0cbe \u0c9a\u0cbf\u0ca4\u0ccd\u0ca4 \u0ca8 \u0ca7\u0cb0\u0c88 \u0964 \u0cb9\u0ca8\u0cc1\u0cae\u0ca4 \u0cb8\u0cc7\u0c87 \u0cb8\u0cb0\u0ccd\u0cac \u0cb8\u0cc1\u0c96 \u0c95\u0cb0\u0c88 \u0965 \u0ce9\u0ceb \u0965", "malayalam": "\u0d14\u0d30 \u0d26\u0d47\u0d35\u0d24\u0d3e \u0d1a\u0d3f\u0d24\u0d4d\u0d24 \u0d28 \u0d27\u0d30\u0d08 \u0964 \u0d39\u0d28\u0d41\u0d2e\u0d24 \u0d38\u0d47\u0d07 \u0d38\u0d30\u0d4d\u0d2c \u0d38\u0d41\u0d16 \u0d15\u0d30\u0d08 \u0965 \u0d69\u0d6b \u0965"},
        draftTranslation: "Even without contemplating any other deity, serving Hanuman alone yields all supreme bliss.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 38,
        devanagariText: "\u0938\u0919\u094d\u0915\u091f \u0915\u091f\u0948 \u092e\u093f\u091f\u0948 \u0938\u092c \u092a\u0940\u0930\u093e \u0964 \u091c\u094b \u0938\u0941\u092e\u093f\u0930\u0948 \u0939\u0928\u0941\u092e\u0924 \u092c\u0932\u092c\u0940\u0930\u093e \u0965 \u0969\u096c \u0965",
        iastText: "sa\u1e45ka\u1e6da ka\u1e6dai mi\u1e6dai saba p\u012br\u0101 \u0964 j\u014d sumirai hanumata balab\u012br\u0101 \u0965 36 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c38\u0c19\u0c4d\u0c15\u0c1f \u0c15\u0c1f\u0c48 \u0c2e\u0c3f\u0c1f\u0c48 \u0c38\u0c2c \u0c2a\u0c40\u0c30\u0c3e \u0964 \u0c1c\u0c4b \u0c38\u0c41\u0c2e\u0c3f\u0c30\u0c48 \u0c39\u0c28\u0c41\u0c2e\u0c24 \u0c2c\u0c32\u0c2c\u0c40\u0c30\u0c3e \u0965 \u0c69\u0c6c \u0965", "tamil": "\u0bb8\u0b99\u0bcd\u0b95\u0b9f \u0b95\u0b9f\u0bc8 \u0bae\u0bbf\u0b9f\u0bc8 \u0bb8\u0baa \u0baa\u0bc0\u0bb0\u0bbe \u0964 \u0b9c\u0bcb \u0bb8\u0bc1\u0bae\u0bbf\u0bb0\u0bc8 \u0bb9\u0ba8\u0bc1\u0bae\u0ba4 \u0baa\u0bb2\u0baa\u0bc0\u0bb0\u0bbe \u0965 \u0be9\u0bec \u0965", "kannada": "\u0cb8\u0c99\u0ccd\u0c95\u0c9f \u0c95\u0c9f\u0cc8 \u0cae\u0cbf\u0c9f\u0cc8 \u0cb8\u0cac \u0caa\u0cc0\u0cb0\u0cbe \u0964 \u0c9c\u0ccb \u0cb8\u0cc1\u0cae\u0cbf\u0cb0\u0cc8 \u0cb9\u0ca8\u0cc1\u0cae\u0ca4 \u0cac\u0cb2\u0cac\u0cc0\u0cb0\u0cbe \u0965 \u0ce9\u0cec \u0965", "malayalam": "\u0d38\u0d19\u0d4d\u0d15\u0d1f \u0d15\u0d1f\u0d48 \u0d2e\u0d3f\u0d1f\u0d48 \u0d38\u0d2c \u0d2a\u0d40\u0d30\u0d3e \u0964 \u0d1c\u0d4b \u0d38\u0d41\u0d2e\u0d3f\u0d30\u0d48 \u0d39\u0d28\u0d41\u0d2e\u0d24 \u0d2c\u0d32\u0d2c\u0d40\u0d30\u0d3e \u0965 \u0d69\u0d6c \u0965"},
        draftTranslation: "All crises are severed and all pain erased for him who remembers the mighty hero Hanuman.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 39,
        devanagariText: "\u091c\u092f \u091c\u092f \u091c\u092f \u0939\u0928\u0941\u092e\u093e\u0928 \u0917\u094b\u0938\u093e\u0908\u0902 \u0964 \u0915\u0943\u092a\u093e \u0915\u0930\u0939\u0941 \u0917\u0941\u0930\u0941\u0926\u0947\u0935 \u0915\u0940 \u0928\u093e\u0908\u0902 \u0965 \u0969\u096d \u0965",
        iastText: "jaya jaya jaya hanum\u0101na g\u014ds\u0101\u012b\u1e41 \u0964 k\u1e5bp\u0101 karahu gurud\u0113va k\u012b n\u0101\u012b\u1e41 \u0965 37 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c1c\u0c2f \u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c28\u0c41\u0c2e\u0c3e\u0c28 \u0c17\u0c4b\u0c38\u0c3e\u0c08\u0c02 \u0964 \u0c15\u0c43\u0c2a\u0c3e \u0c15\u0c30\u0c39\u0c41 \u0c17\u0c41\u0c30\u0c41\u0c26\u0c47\u0c35 \u0c15\u0c40 \u0c28\u0c3e\u0c08\u0c02 \u0965 \u0c69\u0c6d \u0965", "tamil": "\u0b9c\u0baf \u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0ba8\u0bc1\u0bae\u0bbe\u0ba8 \u0b95\u0bcb\u0bb8\u0bbe\u0b88\u0bae\u0bcd \u0964 \u0b95\u0bcd\u0bb0\u0bc1'\u0baa\u0bbe \u0b95\u0bb0\u0bb9\u0bc1 \u0b95\u0bc1\u0bb0\u0bc1\u0ba4\u0bc7\u0bb5 \u0b95\u0bc0 \u0ba8\u0bbe\u0b88\u0bae\u0bcd \u0965 \u0be9\u0bed \u0965", "kannada": "\u0c9c\u0caf \u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0ca8\u0cc1\u0cae\u0cbe\u0ca8 \u0c97\u0ccb\u0cb8\u0cbe\u0c88\u0c82 \u0964 \u0c95\u0cc3\u0caa\u0cbe \u0c95\u0cb0\u0cb9\u0cc1 \u0c97\u0cc1\u0cb0\u0cc1\u0ca6\u0cc7\u0cb5 \u0c95\u0cc0 \u0ca8\u0cbe\u0c88\u0c82 \u0965 \u0ce9\u0ced \u0965", "malayalam": "\u0d1c\u0d2f \u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d28\u0d41\u0d2e\u0d3e\u0d28 \u0d17\u0d4b\u0d38\u0d3e\u0d08\u0d02 \u0964 \u0d15\u0d43\u0d2a\u0d3e \u0d15\u0d30\u0d39\u0d41 \u0d17\u0d41\u0d30\u0d41\u0d26\u0d47\u0d35 \u0d15\u0d40 \u0d28\u0d3e\u0d08\u0d02 \u0965 \u0d69\u0d6d \u0965"},
        draftTranslation: "Hail, hail, hail to Lord Hanuman! Shower Your grace upon me like a divine spiritual Guru!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 40,
        devanagariText: "\u091c\u094b \u0938\u0924 \u092c\u093e\u0930 \u092a\u093e\u0920 \u0915\u0930 \u0915\u094b\u0908 \u0964 \u091b\u0942\u091f\u0939\u093f \u092c\u0928\u094d\u0926\u093f \u092e\u0939\u093e \u0938\u0941\u0916 \u0939\u094b\u0908 \u0965 \u0969\u096e \u0965",
        iastText: "j\u014d sata b\u0101ra p\u0101\u1e6dha kara k\u014d\u012b \u0964 ch\u016b\u1e6dahi bandi mah\u0101 sukha h\u014d\u012b \u0965 38 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c1c\u0c4b \u0c38\u0c24 \u0c2c\u0c3e\u0c30 \u0c2a\u0c3e\u0c20 \u0c15\u0c30 \u0c15\u0c4b\u0c08 \u0964 \u0c1b\u0c42\u0c1f\u0c39\u0c3f \u0c2c\u0c28\u0c4d\u0c26\u0c3f \u0c2e\u0c39\u0c3e \u0c38\u0c41\u0c16 \u0c39\u0c4b\u0c08 \u0965 \u0c69\u0c6e \u0965", "tamil": "\u0b9c\u0bcb \u0bb8\u0ba4 \u0baa\u0bbe\u0bb0 \u0baa\u0bbe\u0b9f \u0b95\u0bb0 \u0b95\u0bcb\u0b88 \u0964 \u0b9a\u0bc2\u0b9f\u0bb9\u0bbf \u0baa\u0ba8\u0bcd\u0ba4\u0bbf \u0bae\u0bb9\u0bbe \u0bb8\u0bc1\u0b95 \u0bb9\u0bcb\u0b88 \u0965 \u0be9\u0bee \u0965", "kannada": "\u0c9c\u0ccb \u0cb8\u0ca4 \u0cac\u0cbe\u0cb0 \u0caa\u0cbe\u0ca0 \u0c95\u0cb0 \u0c95\u0ccb\u0c88 \u0964 \u0c9b\u0cc2\u0c9f\u0cb9\u0cbf \u0cac\u0ca8\u0ccd\u0ca6\u0cbf \u0cae\u0cb9\u0cbe \u0cb8\u0cc1\u0c96 \u0cb9\u0ccb\u0c88 \u0965 \u0ce9\u0cee \u0965", "malayalam": "\u0d1c\u0d4b \u0d38\u0d24 \u0d2c\u0d3e\u0d30 \u0d2a\u0d3e\u0d20 \u0d15\u0d30 \u0d15\u0d4b\u0d08 \u0964 \u0d1b\u0d42\u0d1f\u0d39\u0d3f \u0d2c\u0d28\u0d4d\u0d26\u0d3f \u0d2e\u0d39\u0d3e \u0d38\u0d41\u0d16 \u0d39\u0d4b\u0d08 \u0965 \u0d69\u0d6e \u0965"},
        draftTranslation: "Whoever recites this one hundred times is freed from all bondage and attains supreme happiness.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 41,
        devanagariText: "\u091c\u094b \u092f\u0939 \u092a\u0922\u093c\u0948 \u0939\u0928\u0941\u092e\u093e\u0928 \u091a\u093e\u0932\u0940\u0938\u093e \u0964 \u0939\u094b\u092f \u0938\u093f\u0926\u094d\u0927\u093f \u0938\u093e\u0916\u0940 \u0917\u094c\u0930\u0940\u0938\u093e \u0965 \u0969\u096f \u0965",
        iastText: "j\u014d yaha pa\u1e5bhai hanum\u0101na c\u0101l\u012bs\u0101 \u0964 h\u014dya siddhi s\u0101kh\u012b gaur\u012bs\u0101 \u0965 39 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c1c\u0c4b \u0c2f\u0c39 \u0c2a\u0922\u093c\u0c48 \u0c39\u0c28\u0c41\u0c2e\u0c3e\u0c28 \u0c1a\u0c3e\u0c32\u0c40\u0c38\u0c3e \u0964 \u0c39\u0c4b\u0c2f \u0c38\u0c3f\u0c26\u0c4d\u0c27\u0c3f \u0c38\u0c3e\u0c16\u0c40 \u0c17\u0c4c\u0c30\u0c40\u0c38\u0c3e \u0965 \u0c69\u0c6f \u0965", "tamil": "\u0b9c\u0bcb \u0baf\u0bb9 \u0baa\u0b83\u0b9f\u00b3\u0bc8 \u0bb9\u0ba8\u0bc1\u0bae\u0bbe\u0ba8 \u0b9a\u0bbe\u0bb2\u0bc0\u0bb8\u0bbe \u0964 \u0bb9\u0bcb\u0baf \u0bb8\u0bbf\u0ba4\u0bcd\u0ba4\u0bbf \u0bb8\u0bbe\u0b95\u0bc0 \u0b95\u0bcc\u0bb0\u0bc0\u0bb8\u0bbe \u0965 \u0be9\u0bef \u0965", "kannada": "\u0c9c\u0ccb \u0caf\u0cb9 \u0caa\u0ca2\u0cbc\u0cc8 \u0cb9\u0ca8\u0cc1\u0cae\u0cbe\u0ca8 \u0c9a\u0cbe\u0cb2\u0cc0\u0cb8\u0cbe \u0964 \u0cb9\u0ccb\u0caf \u0cb8\u0cbf\u0ca6\u0ccd\u0ca7\u0cbf \u0cb8\u0cbe\u0c96\u0cc0 \u0c97\u0ccc\u0cb0\u0cc0\u0cb8\u0cbe \u0965 \u0ce9\u0cef \u0965", "malayalam": "\u0d1c\u0d4b \u0d2f\u0d39 \u0d2a\u0922\u093c\u0d48 \u0d39\u0d28\u0d41\u0d2e\u0d3e\u0d28 \u0d1a\u0d3e\u0d32\u0d40\u0d38\u0d3e \u0964 \u0d39\u0d4b\u0d2f \u0d38\u0d3f\u0d26\u0d4d\u0d27\u0d3f \u0d38\u0d3e\u0d16\u0d40 \u0d17\u0d4c\u0d30\u0d40\u0d38\u0d3e \u0965 \u0d69\u0d6f \u0965"},
        draftTranslation: "Whoever recites this Hanuman Chalisa attains all perfection, as witnessed by Lord Shiva Himself.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 42,
        devanagariText: "\u0924\u0941\u0932\u0938\u0940\u0926\u093e\u0938 \u0938\u0926\u093e \u0939\u0930\u093f \u091a\u0947\u0930\u093e \u0964 \u0915\u0940\u091c\u0948 \u0928\u093e\u0925 \u0939\u0943\u0926\u092f \u092e\u0901\u0939 \u0921\u0947\u0930\u093e \u0965 \u096a\u0966 \u0965",
        iastText: "tulas\u012bd\u0101sa sad\u0101 hari c\u0113r\u0101 \u0964 k\u012bjai n\u0101tha h\u1e5bdaya mam\u0310ha \u1e0d\u0113r\u0101 \u0965 40 \u0965",
        meter: "Chaupai (16)",
        transliterations: {"telugu": "\u0c24\u0c41\u0c32\u0c38\u0c40\u0c26\u0c3e\u0c38 \u0c38\u0c26\u0c3e \u0c39\u0c30\u0c3f \u0c1a\u0c47\u0c30\u0c3e \u0964 \u0c15\u0c40\u0c1c\u0c48 \u0c28\u0c3e\u0c25 \u0c39\u0c43\u0c26\u0c2f \u0c2e\u0c01\u0c39 \u0c21\u0c47\u0c30\u0c3e \u0965 \u0c6a\u0c66 \u0965", "tamil": "\u0ba4\u0bc1\u0bb2\u0bb8\u0bc0\u0ba4\u0bbe\u0bb8 \u0bb8\u0ba4\u0bbe \u0bb9\u0bb0\u0bbf \u0b9a\u0bc7\u0bb0\u0bbe \u0964 \u0b95\u0bc0\u0b9c\u0bc8 \u0ba8\u0bbe\u0ba4 \u0bb9\u0bcd\u0bb0\u0bc1'\u0ba4\u0baf \u0bae\u0901\u0bb9 \u0b9f\u0bc7\u0bb0\u0bbe \u0965 \u0bea\u0be6 \u0965", "kannada": "\u0ca4\u0cc1\u0cb2\u0cb8\u0cc0\u0ca6\u0cbe\u0cb8 \u0cb8\u0ca6\u0cbe \u0cb9\u0cb0\u0cbf \u0c9a\u0cc7\u0cb0\u0cbe \u0964 \u0c95\u0cc0\u0c9c\u0cc8 \u0ca8\u0cbe\u0ca5 \u0cb9\u0cc3\u0ca6\u0caf \u0cae\u0c81\u0cb9 \u0ca1\u0cc7\u0cb0\u0cbe \u0965 \u0cea\u0ce6 \u0965", "malayalam": "\u0d24\u0d41\u0d32\u0d38\u0d40\u0d26\u0d3e\u0d38 \u0d38\u0d26\u0d3e \u0d39\u0d30\u0d3f \u0d1a\u0d47\u0d30\u0d3e \u0964 \u0d15\u0d40\u0d1c\u0d48 \u0d28\u0d3e\u0d25 \u0d39\u0d43\u0d26\u0d2f \u0d2e\u0d01\u0d39 \u0d21\u0d47\u0d30\u0d3e \u0965 \u0d6a\u0d66 \u0965"},
        draftTranslation: "Tulsidas is ever the servant of the Lord; O Master, make Your permanent abode in my heart!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 43,
        devanagariText: "\u092a\u0935\u0928\u0924\u0928\u092f \u0938\u0902\u0915\u091f \u0939\u0930\u0928 \u092e\u0902\u0917\u0932 \u092e\u0942\u0930\u0924\u093f \u0930\u0942\u092a \u0964\n\u0930\u093e\u092e \u0932\u0916\u0928 \u0938\u0940\u0924\u093e \u0938\u0939\u093f\u0924 \u0939\u0943\u0926\u092f \u092c\u0938\u0939\u0941 \u0938\u0941\u0930 \u092d\u0942\u092a \u0965",
        iastText: "pavanatanaya sa\u1e45ka\u1e6da harana ma\u1e45gala m\u016brati r\u016bpa \u0964\nr\u0101ma lakhana s\u012bt\u0101 sahita h\u1e5bdaya basahu sura bh\u016bpa \u0965",
        meter: "Doha (13-11)",
        transliterations: {"telugu": "\u0c2a\u0c35\u0c28\u0c24\u0c28\u0c2f \u0c38\u0c02\u0c15\u0c1f \u0c39\u0c30\u0c28 \u0c2e\u0c02\u0c17\u0c32 \u0c2e\u0c42\u0c30\u0c24\u0c3f \u0c30\u0c42\u0c2a \u0964\n\u0c30\u0c3e\u0c2e \u0c32\u0c16\u0c28 \u0c38\u0c40\u0c24\u0c3e \u0c38\u0c39\u0c3f\u0c24 \u0c39\u0c43\u0c26\u0c2f \u0c2c\u0c38\u0c39\u0c41 \u0c38\u0c41\u0c30 \u0c2d\u0c42\u0c2a \u0965", "tamil": "\u0baa\u0bb5\u0ba8\u0ba4\u0ba8\u0baf \u0bb8\u0bae\u0bcd\u0b95\u0b9f \u0bb9\u0bb0\u0ba8 \u0bae\u0bae\u0bcd\u0b95\u0bb2 \u0bae\u0bc2\u0bb0\u0ba4\u0bbf \u0bb0\u0bc2\u0baa \u0964\n\u0bb0\u0bbe\u0bae \u0bb2\u0b95\u0ba8 \u0bb8\u0bc0\u0ba4\u0bbe \u0bb8\u0bb9\u0bbf\u0ba4 \u0bb9\u0bcd\u0bb0\u0bc1'\u0ba4\u0baf \u0baa\u0bb8\u0bb9\u0bc1 \u0bb8\u0bc1\u0bb0 \u0baa\u0bc2\u0baa \u0965", "kannada": "\u0caa\u0cb5\u0ca8\u0ca4\u0ca8\u0caf \u0cb8\u0c82\u0c95\u0c9f \u0cb9\u0cb0\u0ca8 \u0cae\u0c82\u0c97\u0cb2 \u0cae\u0cc2\u0cb0\u0ca4\u0cbf \u0cb0\u0cc2\u0caa \u0964\n\u0cb0\u0cbe\u0cae \u0cb2\u0c96\u0ca8 \u0cb8\u0cc0\u0ca4\u0cbe \u0cb8\u0cb9\u0cbf\u0ca4 \u0cb9\u0cc3\u0ca6\u0caf \u0cac\u0cb8\u0cb9\u0cc1 \u0cb8\u0cc1\u0cb0 \u0cad\u0cc2\u0caa \u0965", "malayalam": "\u0d2a\u0d35\u0d28\u0d24\u0d28\u0d2f \u0d38\u0d02\u0d15\u0d1f \u0d39\u0d30\u0d28 \u0d2e\u0d02\u0d17\u0d32 \u0d2e\u0d42\u0d30\u0d24\u0d3f \u0d30\u0d42\u0d2a \u0964\n\u0d30\u0d3e\u0d2e \u0d32\u0d16\u0d28 \u0d38\u0d40\u0d24\u0d3e \u0d38\u0d39\u0d3f\u0d24 \u0d39\u0d43\u0d26\u0d2f \u0d2c\u0d38\u0d39\u0d41 \u0d38\u0d41\u0d30 \u0d2d\u0d42\u0d2a \u0965"},
        draftTranslation: "O Son of the Wind, dispeller of calamities, embodiment of auspiciousness! Abide in my heart forever along with Rama, Lakshmana, and Sita, O King of Gods!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
    ],
  ),
