  Scripture(
    id: 10,
    contentId: "VEDA-TXT-00010",
    canonicalTitle: "Mahalakshmi Ashtakam",
    devanagariTitle: "\u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u094d\u092f\u0937\u094d\u091f\u0915\u092e\u094d",
    category: "Stotra",
    deity: "Goddess Lakshmi / Devi",
    composer: "Deva Indra (Padma Purana)",
    rishi: "Traditional Vedic Sage",
    chandas: "Anushtubh",
    devata: "Goddess Lakshmi / Devi",
    sourceScripture: "Padma Purana, Uttara Khanda",
    traditionalUsage: "Lakshmi Upasana, Prosperity, Auspiciousness",
    verseCount: 10,
    verses: [
      Verse(
        verseNumber: 1,
        devanagariText: "\u0928\u092e\u0938\u094d\u0924\u0947\u093d\u0938\u094d\u0924\u0941 \u092e\u0939\u093e\u092e\u093e\u092f\u0947 \u0936\u094d\u0930\u0940\u092a\u0940\u0920\u0947 \u0938\u0941\u0930\u092a\u0942\u091c\u093f\u0924\u0947 \u0964\n\u0936\u0919\u094d\u0916\u091a\u0915\u094d\u0930\u0917\u0926\u093e\u0939\u0938\u094d\u0924\u0947 \u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u093f \u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0924\u0947 \u0965 \u0967 \u0965",
        iastText: "namast\u0113'stu mah\u0101m\u0101y\u0113 \u015br\u012bp\u012b\u1e6dh\u0113 surap\u016bjit\u0113 \u0964\n\u015ba\u1e45khacakragad\u0101hast\u0113 mah\u0101lak\u1e63mi nam\u014d'stu t\u0113 \u0965 1 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c28\u0c2e\u0c38\u0c4d\u0c24\u0c47\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c2e\u0c39\u0c3e\u0c2e\u0c3e\u0c2f\u0c47 \u0c36\u0c4d\u0c30\u0c40\u0c2a\u0c40\u0c20\u0c47 \u0c38\u0c41\u0c30\u0c2a\u0c42\u0c1c\u0c3f\u0c24\u0c47 \u0964\n\u0c36\u0c19\u0c4d\u0c16\u0c1a\u0c15\u0c4d\u0c30\u0c17\u0c26\u0c3e\u0c39\u0c38\u0c4d\u0c24\u0c47 \u0c2e\u0c39\u0c3e\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c3f \u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c24\u0c47 \u0965 \u0c67 \u0965", "tamil": "\u0ba8\u0bae\u0bb8\u0bcd\u0ba4\u0bc7\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0bae\u0bb9\u0bbe\u0bae\u0bbe\u0baf\u0bc7 \u0bb6\u0bcd\u0bb0\u0bc0\u0baa\u0bc0\u0b9f\u0bc7 \u0bb8\u0bc1\u0bb0\u0baa\u0bc2\u0b9c\u0bbf\u0ba4\u0bc7 \u0964\n\u0bb6\u0b99\u0bcd\u0b95\u0b9a\u0b95\u0bcd\u0bb0\u0b95\u0ba4\u0bbe\u0bb9\u0bb8\u0bcd\u0ba4\u0bc7 \u0bae\u0bb9\u0bbe\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bbf \u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bc7 \u0965 \u0be7 \u0965", "kannada": "\u0ca8\u0cae\u0cb8\u0ccd\u0ca4\u0cc7\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0cae\u0cb9\u0cbe\u0cae\u0cbe\u0caf\u0cc7 \u0cb6\u0ccd\u0cb0\u0cc0\u0caa\u0cc0\u0ca0\u0cc7 \u0cb8\u0cc1\u0cb0\u0caa\u0cc2\u0c9c\u0cbf\u0ca4\u0cc7 \u0964\n\u0cb6\u0c99\u0ccd\u0c96\u0c9a\u0c95\u0ccd\u0cb0\u0c97\u0ca6\u0cbe\u0cb9\u0cb8\u0ccd\u0ca4\u0cc7 \u0cae\u0cb9\u0cbe\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cbf \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca4\u0cc7 \u0965 \u0ce7 \u0965", "malayalam": "\u0d28\u0d2e\u0d38\u0d4d\u0d24\u0d47\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d2e\u0d39\u0d3e\u0d2e\u0d3e\u0d2f\u0d47 \u0d36\u0d4d\u0d30\u0d40\u0d2a\u0d40\u0d20\u0d47 \u0d38\u0d41\u0d30\u0d2a\u0d42\u0d1c\u0d3f\u0d24\u0d47 \u0964\n\u0d36\u0d19\u0d4d\u0d16\u0d1a\u0d15\u0d4d\u0d30\u0d17\u0d26\u0d3e\u0d39\u0d38\u0d4d\u0d24\u0d47 \u0d2e\u0d39\u0d3e\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d3f \u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d24\u0d47 \u0965 \u0d67 \u0965", "iast": "namaste'stu mah\u0101m\u0101ye \u015br\u012bp\u012b\u1e6dhe surap\u016bjite |\n\u015ba\u1e45khacakragad\u0101haste mah\u0101lak\u1e63mi namo'stu te || 1 ||"},
        draftTranslation: "Salutations unto You, O Mahamaya, who abide upon the holy Sri Peetha, adored by all gods! Holding the conch, discus, and mace in Your hands, O Mahalakshmi, salutations unto You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 2,
        devanagariText: "\u0928\u092e\u0938\u094d\u0924\u0947 \u0917\u0930\u0941\u0921\u093e\u0930\u0942\u0922\u0947 \u0915\u094b\u0932\u093e\u0938\u0941\u0930\u092d\u092f\u0919\u094d\u0915\u0930\u093f \u0964\n\u0938\u0930\u094d\u0935\u092a\u093e\u092a\u0939\u0930\u0947 \u0926\u0947\u0935\u093f \u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u093f \u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0924\u0947 \u0965 \u0968 \u0965",
        iastText: "namast\u0113 garu\u1e0d\u0101r\u016b\u1e0dh\u0113 k\u014dl\u0101surabhaya\u1e45kari \u0964\nsarvap\u0101pahar\u0113 d\u0113vi mah\u0101lak\u1e63mi nam\u014d'stu t\u0113 \u0965 2 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c28\u0c2e\u0c38\u0c4d\u0c24\u0c47 \u0c17\u0c30\u0c41\u0c21\u0c3e\u0c30\u0c42\u0c22\u0c47 \u0c15\u0c4b\u0c32\u0c3e\u0c38\u0c41\u0c30\u0c2d\u0c2f\u0c19\u0c4d\u0c15\u0c30\u0c3f \u0964\n\u0c38\u0c30\u0c4d\u0c35\u0c2a\u0c3e\u0c2a\u0c39\u0c30\u0c47 \u0c26\u0c47\u0c35\u0c3f \u0c2e\u0c39\u0c3e\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c3f \u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c24\u0c47 \u0965 \u0c68 \u0965", "tamil": "\u0ba8\u0bae\u0bb8\u0bcd\u0ba4\u0bc7 \u0b95\u0bb0\u0bc1\u0b9f\u0bbe\u0bb0\u0bc2\u0b9f\u0bc7 \u0b95\u0bcb\u0bb2\u0bbe\u0bb8\u0bc1\u0bb0\u0baa\u0baf\u0b99\u0bcd\u0b95\u0bb0\u0bbf \u0964\n\u0bb8\u0bb0\u0bcd\u0bb5\u0baa\u0bbe\u0baa\u0bb9\u0bb0\u0bc7 \u0ba4\u0bc7\u0bb5\u0bbf \u0bae\u0bb9\u0bbe\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bbf \u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bc7 \u0965 \u0be8 \u0965", "kannada": "\u0ca8\u0cae\u0cb8\u0ccd\u0ca4\u0cc7 \u0c97\u0cb0\u0cc1\u0ca1\u0cbe\u0cb0\u0cc2\u0ca2\u0cc7 \u0c95\u0ccb\u0cb2\u0cbe\u0cb8\u0cc1\u0cb0\u0cad\u0caf\u0c99\u0ccd\u0c95\u0cb0\u0cbf \u0964\n\u0cb8\u0cb0\u0ccd\u0cb5\u0caa\u0cbe\u0caa\u0cb9\u0cb0\u0cc7 \u0ca6\u0cc7\u0cb5\u0cbf \u0cae\u0cb9\u0cbe\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cbf \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca4\u0cc7 \u0965 \u0ce8 \u0965", "malayalam": "\u0d28\u0d2e\u0d38\u0d4d\u0d24\u0d47 \u0d17\u0d30\u0d41\u0d21\u0d3e\u0d30\u0d42\u0d22\u0d47 \u0d15\u0d4b\u0d32\u0d3e\u0d38\u0d41\u0d30\u0d2d\u0d2f\u0d19\u0d4d\u0d15\u0d30\u0d3f \u0964\n\u0d38\u0d30\u0d4d\u0d35\u0d2a\u0d3e\u0d2a\u0d39\u0d30\u0d47 \u0d26\u0d47\u0d35\u0d3f \u0d2e\u0d39\u0d3e\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d3f \u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d24\u0d47 \u0965 \u0d68 \u0965", "iast": "namaste garu\u1e0d\u0101r\u016b\u1e0dhe kol\u0101surabhaya\u1e45kari |\nsarvap\u0101pahare devi mah\u0101lak\u1e63mi namo'stu te || 2 ||"},
        draftTranslation: "Salutations unto You who ride upon Garuda, who brought dread to the demon Kolasura, dispeller of all sins, O Goddess Mahalakshmi, salutations unto You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 3,
        devanagariText: "\u0938\u0930\u094d\u0935\u091c\u094d\u091e\u0947 \u0938\u0930\u094d\u0935\u0935\u0930\u0926\u0947 \u0938\u0930\u094d\u0935\u0926\u0941\u0937\u094d\u091f\u092d\u092f\u0919\u094d\u0915\u0930\u093f \u0964\n\u0938\u0930\u094d\u0935\u0926\u0941\u0903\u0916\u0939\u0930\u0947 \u0926\u0947\u0935\u093f \u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u093f \u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0924\u0947 \u0965 \u0969 \u0965",
        iastText: "sarvaj\u00f1\u0113 sarvavarad\u0113 sarvadu\u1e63\u1e6dabhaya\u1e45kari \u0964\nsarvadu\u1e25khahar\u0113 d\u0113vi mah\u0101lak\u1e63mi nam\u014d'stu t\u0113 \u0965 3 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0c30\u0c4d\u0c35\u0c1c\u0c4d\u0c1e\u0c47 \u0c38\u0c30\u0c4d\u0c35\u0c35\u0c30\u0c26\u0c47 \u0c38\u0c30\u0c4d\u0c35\u0c26\u0c41\u0c37\u0c4d\u0c1f\u0c2d\u0c2f\u0c19\u0c4d\u0c15\u0c30\u0c3f \u0964\n\u0c38\u0c30\u0c4d\u0c35\u0c26\u0c41\u0c03\u0c16\u0c39\u0c30\u0c47 \u0c26\u0c47\u0c35\u0c3f \u0c2e\u0c39\u0c3e\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c3f \u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c24\u0c47 \u0965 \u0c69 \u0965", "tamil": "\u0bb8\u0bb0\u0bcd\u0bb5\u0b9c\u0bcd\u0b9e\u0bc7 \u0bb8\u0bb0\u0bcd\u0bb5\u0bb5\u0bb0\u0ba4\u0bc7 \u0bb8\u0bb0\u0bcd\u0bb5\u0ba4\u0bc1\u0bb7\u0bcd\u0b9f\u0baa\u0baf\u0b99\u0bcd\u0b95\u0bb0\u0bbf \u0964\n\u0bb8\u0bb0\u0bcd\u0bb5\u0ba4\u0bc1\u0b83\u0b95\u0bb9\u0bb0\u0bc7 \u0ba4\u0bc7\u0bb5\u0bbf \u0bae\u0bb9\u0bbe\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bbf \u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bc7 \u0965 \u0be9 \u0965", "kannada": "\u0cb8\u0cb0\u0ccd\u0cb5\u0c9c\u0ccd\u0c9e\u0cc7 \u0cb8\u0cb0\u0ccd\u0cb5\u0cb5\u0cb0\u0ca6\u0cc7 \u0cb8\u0cb0\u0ccd\u0cb5\u0ca6\u0cc1\u0cb7\u0ccd\u0c9f\u0cad\u0caf\u0c99\u0ccd\u0c95\u0cb0\u0cbf \u0964\n\u0cb8\u0cb0\u0ccd\u0cb5\u0ca6\u0cc1\u0c83\u0c96\u0cb9\u0cb0\u0cc7 \u0ca6\u0cc7\u0cb5\u0cbf \u0cae\u0cb9\u0cbe\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cbf \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca4\u0cc7 \u0965 \u0ce9 \u0965", "malayalam": "\u0d38\u0d30\u0d4d\u0d35\u0d1c\u0d4d\u0d1e\u0d47 \u0d38\u0d30\u0d4d\u0d35\u0d35\u0d30\u0d26\u0d47 \u0d38\u0d30\u0d4d\u0d35\u0d26\u0d41\u0d37\u0d4d\u0d1f\u0d2d\u0d2f\u0d19\u0d4d\u0d15\u0d30\u0d3f \u0964\n\u0d38\u0d30\u0d4d\u0d35\u0d26\u0d41\u0d03\u0d16\u0d39\u0d30\u0d47 \u0d26\u0d47\u0d35\u0d3f \u0d2e\u0d39\u0d3e\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d3f \u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d24\u0d47 \u0965 \u0d69 \u0965", "iast": "sarvaj\u00f1e sarvavarade sarvadu\u1e63\u1e6dabhaya\u1e45kari |\nsarvadu\u1e25khahare devi mah\u0101lak\u1e63mi namo'stu te || 3 ||"},
        draftTranslation: "Omniscient One, bestower of all boons, terror to all wicked beings, allayer of all distress, O Goddess Mahalakshmi, salutations unto You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 4,
        devanagariText: "\u0938\u093f\u0926\u094d\u0927\u093f\u092c\u0941\u0926\u094d\u0927\u093f\u092a\u094d\u0930\u0926\u0947 \u0926\u0947\u0935\u093f \u092d\u0941\u0915\u094d\u0924\u093f\u092e\u0941\u0915\u094d\u0924\u093f\u092a\u094d\u0930\u0926\u093e\u092f\u093f\u0928\u093f \u0964\n\u092e\u0928\u094d\u0924\u094d\u0930\u092e\u0942\u0930\u094d\u0924\u0947 \u0938\u0926\u093e \u0926\u0947\u0935\u093f \u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u093f \u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0924\u0947 \u0965 \u096a \u0965",
        iastText: "siddhibuddhiprad\u0113 d\u0113vi bhuktimuktiprad\u0101yini \u0964\nmantram\u016brt\u0113 sad\u0101 d\u0113vi mah\u0101lak\u1e63mi nam\u014d'stu t\u0113 \u0965 4 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0c3f\u0c26\u0c4d\u0c27\u0c3f\u0c2c\u0c41\u0c26\u0c4d\u0c27\u0c3f\u0c2a\u0c4d\u0c30\u0c26\u0c47 \u0c26\u0c47\u0c35\u0c3f \u0c2d\u0c41\u0c15\u0c4d\u0c24\u0c3f\u0c2e\u0c41\u0c15\u0c4d\u0c24\u0c3f\u0c2a\u0c4d\u0c30\u0c26\u0c3e\u0c2f\u0c3f\u0c28\u0c3f \u0964\n\u0c2e\u0c28\u0c4d\u0c24\u0c4d\u0c30\u0c2e\u0c42\u0c30\u0c4d\u0c24\u0c47 \u0c38\u0c26\u0c3e \u0c26\u0c47\u0c35\u0c3f \u0c2e\u0c39\u0c3e\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c3f \u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c24\u0c47 \u0965 \u0c6a \u0965", "tamil": "\u0bb8\u0bbf\u0ba4\u0bcd\u0ba4\u0bbf\u0baa\u0bc1\u0ba4\u0bcd\u0ba4\u0bbf\u0baa\u0bcd\u0bb0\u0ba4\u0bc7 \u0ba4\u0bc7\u0bb5\u0bbf \u0baa\u0bc1\u0b95\u0bcd\u0ba4\u0bbf\u0bae\u0bc1\u0b95\u0bcd\u0ba4\u0bbf\u0baa\u0bcd\u0bb0\u0ba4\u0bbe\u0baf\u0bbf\u0ba8\u0bbf \u0964\n\u0bae\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bae\u0bc2\u0bb0\u0bcd\u0ba4\u0bc7 \u0bb8\u0ba4\u0bbe \u0ba4\u0bc7\u0bb5\u0bbf \u0bae\u0bb9\u0bbe\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bbf \u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bc7 \u0965 \u0bea \u0965", "kannada": "\u0cb8\u0cbf\u0ca6\u0ccd\u0ca7\u0cbf\u0cac\u0cc1\u0ca6\u0ccd\u0ca7\u0cbf\u0caa\u0ccd\u0cb0\u0ca6\u0cc7 \u0ca6\u0cc7\u0cb5\u0cbf \u0cad\u0cc1\u0c95\u0ccd\u0ca4\u0cbf\u0cae\u0cc1\u0c95\u0ccd\u0ca4\u0cbf\u0caa\u0ccd\u0cb0\u0ca6\u0cbe\u0caf\u0cbf\u0ca8\u0cbf \u0964\n\u0cae\u0ca8\u0ccd\u0ca4\u0ccd\u0cb0\u0cae\u0cc2\u0cb0\u0ccd\u0ca4\u0cc7 \u0cb8\u0ca6\u0cbe \u0ca6\u0cc7\u0cb5\u0cbf \u0cae\u0cb9\u0cbe\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cbf \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca4\u0cc7 \u0965 \u0cea \u0965", "malayalam": "\u0d38\u0d3f\u0d26\u0d4d\u0d27\u0d3f\u0d2c\u0d41\u0d26\u0d4d\u0d27\u0d3f\u0d2a\u0d4d\u0d30\u0d26\u0d47 \u0d26\u0d47\u0d35\u0d3f \u0d2d\u0d41\u0d15\u0d4d\u0d24\u0d3f\u0d2e\u0d41\u0d15\u0d4d\u0d24\u0d3f\u0d2a\u0d4d\u0d30\u0d26\u0d3e\u0d2f\u0d3f\u0d28\u0d3f \u0964\n\u0d2e\u0d28\u0d4d\u0d24\u0d4d\u0d30\u0d2e\u0d42\u0d30\u0d4d\u0d24\u0d47 \u0d38\u0d26\u0d3e \u0d26\u0d47\u0d35\u0d3f \u0d2e\u0d39\u0d3e\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d3f \u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d24\u0d47 \u0965 \u0d6a \u0965", "iast": "siddhibuddhiprade devi bhuktimuktiprad\u0101yini |\nmantram\u016brte sad\u0101 devi mah\u0101lak\u1e63mi namo'stu te || 4 ||"},
        draftTranslation: "Bestower of spiritual success and pure intellect, granter of worldly enjoyment and supreme liberation, eternal embodiment of sacred mantras, O Goddess Mahalakshmi, salutations unto You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 5,
        devanagariText: "\u0906\u0926\u094d\u092f\u0928\u094d\u0924\u0930\u0939\u093f\u0924\u0947 \u0926\u0947\u0935\u093f \u0906\u0926\u094d\u092f\u0936\u0915\u094d\u0924\u093f\u092e\u0939\u0947\u0936\u094d\u0935\u0930\u093f \u0964\n\u092f\u094b\u0917\u091c\u0947 \u092f\u094b\u0917\u0938\u092e\u094d\u092d\u0942\u0924\u0947 \u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u093f \u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0924\u0947 \u0965 \u096b \u0965",
        iastText: "\u0101dyantarahit\u0113 d\u0113vi \u0101dya\u015baktimah\u0113\u015bvari \u0964\ny\u014dgaj\u0113 y\u014dgasambh\u016bt\u0113 mah\u0101lak\u1e63mi nam\u014d'stu t\u0113 \u0965 5 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c06\u0c26\u0c4d\u0c2f\u0c28\u0c4d\u0c24\u0c30\u0c39\u0c3f\u0c24\u0c47 \u0c26\u0c47\u0c35\u0c3f \u0c06\u0c26\u0c4d\u0c2f\u0c36\u0c15\u0c4d\u0c24\u0c3f\u0c2e\u0c39\u0c47\u0c36\u0c4d\u0c35\u0c30\u0c3f \u0964\n\u0c2f\u0c4b\u0c17\u0c1c\u0c47 \u0c2f\u0c4b\u0c17\u0c38\u0c2e\u0c4d\u0c2d\u0c42\u0c24\u0c47 \u0c2e\u0c39\u0c3e\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c3f \u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c24\u0c47 \u0965 \u0c6b \u0965", "tamil": "\u0b86\u0ba4\u0bcd\u0baf\u0ba8\u0bcd\u0ba4\u0bb0\u0bb9\u0bbf\u0ba4\u0bc7 \u0ba4\u0bc7\u0bb5\u0bbf \u0b86\u0ba4\u0bcd\u0baf\u0bb6\u0b95\u0bcd\u0ba4\u0bbf\u0bae\u0bb9\u0bc7\u0bb6\u0bcd\u0bb5\u0bb0\u0bbf \u0964\n\u0baf\u0bcb\u0b95\u0b9c\u0bc7 \u0baf\u0bcb\u0b95\u0bb8\u0bae\u0bcd\u0baa\u0bc2\u0ba4\u0bc7 \u0bae\u0bb9\u0bbe\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bbf \u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bc7 \u0965 \u0beb \u0965", "kannada": "\u0c86\u0ca6\u0ccd\u0caf\u0ca8\u0ccd\u0ca4\u0cb0\u0cb9\u0cbf\u0ca4\u0cc7 \u0ca6\u0cc7\u0cb5\u0cbf \u0c86\u0ca6\u0ccd\u0caf\u0cb6\u0c95\u0ccd\u0ca4\u0cbf\u0cae\u0cb9\u0cc7\u0cb6\u0ccd\u0cb5\u0cb0\u0cbf \u0964\n\u0caf\u0ccb\u0c97\u0c9c\u0cc7 \u0caf\u0ccb\u0c97\u0cb8\u0cae\u0ccd\u0cad\u0cc2\u0ca4\u0cc7 \u0cae\u0cb9\u0cbe\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cbf \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca4\u0cc7 \u0965 \u0ceb \u0965", "malayalam": "\u0d06\u0d26\u0d4d\u0d2f\u0d28\u0d4d\u0d24\u0d30\u0d39\u0d3f\u0d24\u0d47 \u0d26\u0d47\u0d35\u0d3f \u0d06\u0d26\u0d4d\u0d2f\u0d36\u0d15\u0d4d\u0d24\u0d3f\u0d2e\u0d39\u0d47\u0d36\u0d4d\u0d35\u0d30\u0d3f \u0964\n\u0d2f\u0d4b\u0d17\u0d1c\u0d47 \u0d2f\u0d4b\u0d17\u0d38\u0d2e\u0d4d\u0d2d\u0d42\u0d24\u0d47 \u0d2e\u0d39\u0d3e\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d3f \u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d24\u0d47 \u0965 \u0d6b \u0965", "iast": "\u0101dyantarahite devi \u0101dya\u015baktimahe\u015bvari |\nyogaje yogasambh\u016bte mah\u0101lak\u1e63mi namo'stu te || 5 ||"},
        draftTranslation: "O Goddess devoid of beginning or end, primordial cosmic energy, supreme Sovereign! Born of yoga and manifest through meditation, O Goddess Mahalakshmi, salutations unto You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 6,
        devanagariText: "\u0938\u094d\u0925\u0942\u0932\u0938\u0942\u0915\u094d\u0937\u094d\u092e\u092e\u0939\u093e\u0930\u094c\u0926\u094d\u0930\u0947 \u092e\u0939\u093e\u0936\u0915\u094d\u0924\u093f\u092e\u0939\u094b\u0926\u0930\u0947 \u0964\n\u092e\u0939\u093e\u092a\u093e\u092a\u0939\u0930\u0947 \u0926\u0947\u0935\u093f \u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u093f \u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0924\u0947 \u0965 \u096c \u0965",
        iastText: "sth\u016blas\u016bk\u1e63mamah\u0101raudr\u0113 mah\u0101\u015baktimah\u014ddar\u0113 \u0964\nmah\u0101p\u0101pahar\u0113 d\u0113vi mah\u0101lak\u1e63mi nam\u014d'stu t\u0113 \u0965 6 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0c4d\u0c25\u0c42\u0c32\u0c38\u0c42\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c2e\u0c39\u0c3e\u0c30\u0c4c\u0c26\u0c4d\u0c30\u0c47 \u0c2e\u0c39\u0c3e\u0c36\u0c15\u0c4d\u0c24\u0c3f\u0c2e\u0c39\u0c4b\u0c26\u0c30\u0c47 \u0964\n\u0c2e\u0c39\u0c3e\u0c2a\u0c3e\u0c2a\u0c39\u0c30\u0c47 \u0c26\u0c47\u0c35\u0c3f \u0c2e\u0c39\u0c3e\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c3f \u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c24\u0c47 \u0965 \u0c6c \u0965", "tamil": "\u0bb8\u0bcd\u0ba4\u0bc2\u0bb2\u0bb8\u0bc2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bae\u0bb9\u0bbe\u0bb0\u0bcc\u0ba4\u0bcd\u0bb0\u0bc7 \u0bae\u0bb9\u0bbe\u0bb6\u0b95\u0bcd\u0ba4\u0bbf\u0bae\u0bb9\u0bcb\u0ba4\u0bb0\u0bc7 \u0964\n\u0bae\u0bb9\u0bbe\u0baa\u0bbe\u0baa\u0bb9\u0bb0\u0bc7 \u0ba4\u0bc7\u0bb5\u0bbf \u0bae\u0bb9\u0bbe\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bbf \u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bc7 \u0965 \u0bec \u0965", "kannada": "\u0cb8\u0ccd\u0ca5\u0cc2\u0cb2\u0cb8\u0cc2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cae\u0cb9\u0cbe\u0cb0\u0ccc\u0ca6\u0ccd\u0cb0\u0cc7 \u0cae\u0cb9\u0cbe\u0cb6\u0c95\u0ccd\u0ca4\u0cbf\u0cae\u0cb9\u0ccb\u0ca6\u0cb0\u0cc7 \u0964\n\u0cae\u0cb9\u0cbe\u0caa\u0cbe\u0caa\u0cb9\u0cb0\u0cc7 \u0ca6\u0cc7\u0cb5\u0cbf \u0cae\u0cb9\u0cbe\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cbf \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca4\u0cc7 \u0965 \u0cec \u0965", "malayalam": "\u0d38\u0d4d\u0d25\u0d42\u0d32\u0d38\u0d42\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d2e\u0d39\u0d3e\u0d30\u0d4c\u0d26\u0d4d\u0d30\u0d47 \u0d2e\u0d39\u0d3e\u0d36\u0d15\u0d4d\u0d24\u0d3f\u0d2e\u0d39\u0d4b\u0d26\u0d30\u0d47 \u0964\n\u0d2e\u0d39\u0d3e\u0d2a\u0d3e\u0d2a\u0d39\u0d30\u0d47 \u0d26\u0d47\u0d35\u0d3f \u0d2e\u0d39\u0d3e\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d3f \u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d24\u0d47 \u0965 \u0d6c \u0965", "iast": "sth\u016blas\u016bk\u1e63mamah\u0101raudre mah\u0101\u015baktimahodare |\nmah\u0101p\u0101pahare devi mah\u0101lak\u1e63mi namo'stu te || 6 ||"},
        draftTranslation: "Embodying both the gross and the subtle, fiercely majestic, of boundless power and containing all worlds within Your womb, destroyer of heinous sins, O Mahalakshmi, salutations unto You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 7,
        devanagariText: "\u092a\u0926\u094d\u092e\u093e\u0938\u0928\u0938\u094d\u0925\u093f\u0924\u0947 \u0926\u0947\u0935\u093f \u092a\u0930\u092c\u094d\u0930\u0939\u094d\u092e\u0938\u094d\u0935\u0930\u0942\u092a\u093f\u0923\u093f \u0964\n\u092a\u0930\u092e\u0947\u0936\u093f \u091c\u0917\u0928\u094d\u092e\u093e\u0924\u0930\u094d\u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u093f \u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0924\u0947 \u0965 \u096d \u0965",
        iastText: "padm\u0101sanasthit\u0113 d\u0113vi parabrahmasvar\u016bpi\u1e47i \u0964\nparam\u0113\u015bi jaganm\u0101tarmah\u0101lak\u1e63mi nam\u014d'stu t\u0113 \u0965 7 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2a\u0c26\u0c4d\u0c2e\u0c3e\u0c38\u0c28\u0c38\u0c4d\u0c25\u0c3f\u0c24\u0c47 \u0c26\u0c47\u0c35\u0c3f \u0c2a\u0c30\u0c2c\u0c4d\u0c30\u0c39\u0c4d\u0c2e\u0c38\u0c4d\u0c35\u0c30\u0c42\u0c2a\u0c3f\u0c23\u0c3f \u0964\n\u0c2a\u0c30\u0c2e\u0c47\u0c36\u0c3f \u0c1c\u0c17\u0c28\u0c4d\u0c2e\u0c3e\u0c24\u0c30\u0c4d\u0c2e\u0c39\u0c3e\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c3f \u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c24\u0c47 \u0965 \u0c6d \u0965", "tamil": "\u0baa\u0ba4\u0bcd\u0bae\u0bbe\u0bb8\u0ba8\u0bb8\u0bcd\u0ba4\u0bbf\u0ba4\u0bc7 \u0ba4\u0bc7\u0bb5\u0bbf \u0baa\u0bb0\u0baa\u0bcd\u0bb0\u0bb9\u0bcd\u0bae\u0bb8\u0bcd\u0bb5\u0bb0\u0bc2\u0baa\u0bbf\u0ba3\u0bbf \u0964\n\u0baa\u0bb0\u0bae\u0bc7\u0bb6\u0bbf \u0b9c\u0b95\u0ba8\u0bcd\u0bae\u0bbe\u0ba4\u0bb0\u0bcd\u0bae\u0bb9\u0bbe\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bbf \u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bc7 \u0965 \u0bed \u0965", "kannada": "\u0caa\u0ca6\u0ccd\u0cae\u0cbe\u0cb8\u0ca8\u0cb8\u0ccd\u0ca5\u0cbf\u0ca4\u0cc7 \u0ca6\u0cc7\u0cb5\u0cbf \u0caa\u0cb0\u0cac\u0ccd\u0cb0\u0cb9\u0ccd\u0cae\u0cb8\u0ccd\u0cb5\u0cb0\u0cc2\u0caa\u0cbf\u0ca3\u0cbf \u0964\n\u0caa\u0cb0\u0cae\u0cc7\u0cb6\u0cbf \u0c9c\u0c97\u0ca8\u0ccd\u0cae\u0cbe\u0ca4\u0cb0\u0ccd\u0cae\u0cb9\u0cbe\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cbf \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca4\u0cc7 \u0965 \u0ced \u0965", "malayalam": "\u0d2a\u0d26\u0d4d\u0d2e\u0d3e\u0d38\u0d28\u0d38\u0d4d\u0d25\u0d3f\u0d24\u0d47 \u0d26\u0d47\u0d35\u0d3f \u0d2a\u0d30\u0d2c\u0d4d\u0d30\u0d39\u0d4d\u0d2e\u0d38\u0d4d\u0d35\u0d30\u0d42\u0d2a\u0d3f\u0d23\u0d3f \u0964\n\u0d2a\u0d30\u0d2e\u0d47\u0d36\u0d3f \u0d1c\u0d17\u0d28\u0d4d\u0d2e\u0d3e\u0d24\u0d30\u0d4d\u0d2e\u0d39\u0d3e\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d3f \u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d24\u0d47 \u0965 \u0d6d \u0965", "iast": "padm\u0101sanasthite devi parabrahmasvar\u016bpi\u1e47i |\nparame\u015bi jaganm\u0101tarmah\u0101lak\u1e63mi namo'stu te || 7 ||"},
        draftTranslation: "Seated upon the divine lotus, the very embodiment of the Supreme Absolute Reality (Parabrahman), supreme Ruler, Mother of the universe, O Mahalakshmi, salutations unto You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 8,
        devanagariText: "\u0936\u094d\u0935\u0947\u0924\u093e\u092e\u094d\u092c\u0930\u0927\u0930\u0947 \u0926\u0947\u0935\u093f \u0928\u093e\u0928\u093e\u0932\u0919\u094d\u0915\u093e\u0930\u092d\u0942\u0937\u093f\u0924\u0947 \u0964\n\u091c\u0917\u0924\u094d\u0938\u094d\u0925\u093f\u0924\u0947 \u091c\u0917\u0928\u094d\u092e\u093e\u0924\u0930\u094d\u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u093f \u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0924\u0947 \u0965 \u096e \u0965",
        iastText: "\u015bv\u0113t\u0101mbaradhar\u0113 d\u0113vi n\u0101n\u0101la\u1e45k\u0101rabh\u016b\u1e63it\u0113 \u0964\njagatsthit\u0113 jaganm\u0101tarmah\u0101lak\u1e63mi nam\u014d'stu t\u0113 \u0965 8 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c36\u0c4d\u0c35\u0c47\u0c24\u0c3e\u0c2e\u0c4d\u0c2c\u0c30\u0c27\u0c30\u0c47 \u0c26\u0c47\u0c35\u0c3f \u0c28\u0c3e\u0c28\u0c3e\u0c32\u0c19\u0c4d\u0c15\u0c3e\u0c30\u0c2d\u0c42\u0c37\u0c3f\u0c24\u0c47 \u0964\n\u0c1c\u0c17\u0c24\u0c4d\u0c38\u0c4d\u0c25\u0c3f\u0c24\u0c47 \u0c1c\u0c17\u0c28\u0c4d\u0c2e\u0c3e\u0c24\u0c30\u0c4d\u0c2e\u0c39\u0c3e\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c3f \u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c24\u0c47 \u0965 \u0c6e \u0965", "tamil": "\u0bb6\u0bcd\u0bb5\u0bc7\u0ba4\u0bbe\u0bae\u0bcd\u0baa\u0bb0\u0ba4\u0bb0\u0bc7 \u0ba4\u0bc7\u0bb5\u0bbf \u0ba8\u0bbe\u0ba8\u0bbe\u0bb2\u0b99\u0bcd\u0b95\u0bbe\u0bb0\u0baa\u0bc2\u0bb7\u0bbf\u0ba4\u0bc7 \u0964\n\u0b9c\u0b95\u0ba4\u0bcd\u0bb8\u0bcd\u0ba4\u0bbf\u0ba4\u0bc7 \u0b9c\u0b95\u0ba8\u0bcd\u0bae\u0bbe\u0ba4\u0bb0\u0bcd\u0bae\u0bb9\u0bbe\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bbf \u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bc7 \u0965 \u0bee \u0965", "kannada": "\u0cb6\u0ccd\u0cb5\u0cc7\u0ca4\u0cbe\u0cae\u0ccd\u0cac\u0cb0\u0ca7\u0cb0\u0cc7 \u0ca6\u0cc7\u0cb5\u0cbf \u0ca8\u0cbe\u0ca8\u0cbe\u0cb2\u0c99\u0ccd\u0c95\u0cbe\u0cb0\u0cad\u0cc2\u0cb7\u0cbf\u0ca4\u0cc7 \u0964\n\u0c9c\u0c97\u0ca4\u0ccd\u0cb8\u0ccd\u0ca5\u0cbf\u0ca4\u0cc7 \u0c9c\u0c97\u0ca8\u0ccd\u0cae\u0cbe\u0ca4\u0cb0\u0ccd\u0cae\u0cb9\u0cbe\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cbf \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca4\u0cc7 \u0965 \u0cee \u0965", "malayalam": "\u0d36\u0d4d\u0d35\u0d47\u0d24\u0d3e\u0d2e\u0d4d\u0d2c\u0d30\u0d27\u0d30\u0d47 \u0d26\u0d47\u0d35\u0d3f \u0d28\u0d3e\u0d28\u0d3e\u0d32\u0d19\u0d4d\u0d15\u0d3e\u0d30\u0d2d\u0d42\u0d37\u0d3f\u0d24\u0d47 \u0964\n\u0d1c\u0d17\u0d24\u0d4d\u0d38\u0d4d\u0d25\u0d3f\u0d24\u0d47 \u0d1c\u0d17\u0d28\u0d4d\u0d2e\u0d3e\u0d24\u0d30\u0d4d\u0d2e\u0d39\u0d3e\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d3f \u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d24\u0d47 \u0965 \u0d6e \u0965", "iast": "\u015bvet\u0101mbaradhare devi n\u0101n\u0101la\u1e45k\u0101rabh\u016b\u1e63ite |\njagatsthite jaganm\u0101tarmah\u0101lak\u1e63mi namo'stu te || 8 ||"},
        draftTranslation: "Adorned in pure white raiment, decorated with diverse celestial ornaments, abiding throughout creation, Mother of all worlds, O Mahalakshmi, salutations unto You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 9,
        devanagariText: "\u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u094d\u092f\u0937\u094d\u091f\u0915\u0902 \u0938\u094d\u0924\u094b\u0924\u094d\u0930\u0902 \u092f\u0903 \u092a\u0920\u0947\u0926\u094d\u092d\u0915\u094d\u0924\u093f\u092e\u093e\u0928\u094d\u0928\u0930\u0903 \u0964\n\u0938\u0930\u094d\u0935\u0938\u093f\u0926\u094d\u0927\u093f\u092e\u0935\u093e\u092a\u094d\u0928\u094b\u0924\u093f \u0930\u093e\u091c\u094d\u092f\u0902 \u092a\u094d\u0930\u093e\u092a\u094d\u0928\u094b\u0924\u093f \u0938\u0930\u094d\u0935\u0926\u093e \u0965 \u096f \u0965",
        iastText: "mah\u0101lak\u1e63mya\u1e63\u1e6daka\u1e41 st\u014dtra\u1e41 ya\u1e25 pa\u1e6dh\u0113dbhaktim\u0101nnara\u1e25 \u0964\nsarvasiddhimav\u0101pn\u014dti r\u0101jya\u1e41 pr\u0101pn\u014dti sarvad\u0101 \u0965 9 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2e\u0c39\u0c3e\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c4d\u0c2f\u0c37\u0c4d\u0c1f\u0c15\u0c02 \u0c38\u0c4d\u0c24\u0c4b\u0c24\u0c4d\u0c30\u0c02 \u0c2f\u0c03 \u0c2a\u0c20\u0c47\u0c26\u0c4d\u0c2d\u0c15\u0c4d\u0c24\u0c3f\u0c2e\u0c3e\u0c28\u0c4d\u0c28\u0c30\u0c03 \u0964\n\u0c38\u0c30\u0c4d\u0c35\u0c38\u0c3f\u0c26\u0c4d\u0c27\u0c3f\u0c2e\u0c35\u0c3e\u0c2a\u0c4d\u0c28\u0c4b\u0c24\u0c3f \u0c30\u0c3e\u0c1c\u0c4d\u0c2f\u0c02 \u0c2a\u0c4d\u0c30\u0c3e\u0c2a\u0c4d\u0c28\u0c4b\u0c24\u0c3f \u0c38\u0c30\u0c4d\u0c35\u0c26\u0c3e \u0965 \u0c6f \u0965", "tamil": "\u0bae\u0bb9\u0bbe\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bcd\u0baf\u0bb7\u0bcd\u0b9f\u0b95\u0bae\u0bcd \u0bb8\u0bcd\u0ba4\u0bcb\u0ba4\u0bcd\u0bb0\u0bae\u0bcd \u0baf\u0b83 \u0baa\u0b9f\u0bc7\u0ba4\u0bcd\u0baa\u0b95\u0bcd\u0ba4\u0bbf\u0bae\u0bbe\u0ba8\u0bcd\u0ba8\u0bb0\u0b83 \u0964\n\u0bb8\u0bb0\u0bcd\u0bb5\u0bb8\u0bbf\u0ba4\u0bcd\u0ba4\u0bbf\u0bae\u0bb5\u0bbe\u0baa\u0bcd\u0ba8\u0bcb\u0ba4\u0bbf \u0bb0\u0bbe\u0b9c\u0bcd\u0baf\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0bbe\u0baa\u0bcd\u0ba8\u0bcb\u0ba4\u0bbf \u0bb8\u0bb0\u0bcd\u0bb5\u0ba4\u0bbe \u0965 \u0bef \u0965", "kannada": "\u0cae\u0cb9\u0cbe\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0ccd\u0caf\u0cb7\u0ccd\u0c9f\u0c95\u0c82 \u0cb8\u0ccd\u0ca4\u0ccb\u0ca4\u0ccd\u0cb0\u0c82 \u0caf\u0c83 \u0caa\u0ca0\u0cc7\u0ca6\u0ccd\u0cad\u0c95\u0ccd\u0ca4\u0cbf\u0cae\u0cbe\u0ca8\u0ccd\u0ca8\u0cb0\u0c83 \u0964\n\u0cb8\u0cb0\u0ccd\u0cb5\u0cb8\u0cbf\u0ca6\u0ccd\u0ca7\u0cbf\u0cae\u0cb5\u0cbe\u0caa\u0ccd\u0ca8\u0ccb\u0ca4\u0cbf \u0cb0\u0cbe\u0c9c\u0ccd\u0caf\u0c82 \u0caa\u0ccd\u0cb0\u0cbe\u0caa\u0ccd\u0ca8\u0ccb\u0ca4\u0cbf \u0cb8\u0cb0\u0ccd\u0cb5\u0ca6\u0cbe \u0965 \u0cef \u0965", "malayalam": "\u0d2e\u0d39\u0d3e\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d4d\u0d2f\u0d37\u0d4d\u0d1f\u0d15\u0d02 \u0d38\u0d4d\u0d24\u0d4b\u0d24\u0d4d\u0d30\u0d02 \u0d2f\u0d03 \u0d2a\u0d20\u0d47\u0d26\u0d4d\u0d2d\u0d15\u0d4d\u0d24\u0d3f\u0d2e\u0d3e\u0d28\u0d4d\u0d28\u0d30\u0d03 \u0964\n\u0d38\u0d30\u0d4d\u0d35\u0d38\u0d3f\u0d26\u0d4d\u0d27\u0d3f\u0d2e\u0d35\u0d3e\u0d2a\u0d4d\u0d28\u0d4b\u0d24\u0d3f \u0d30\u0d3e\u0d1c\u0d4d\u0d2f\u0d02 \u0d2a\u0d4d\u0d30\u0d3e\u0d2a\u0d4d\u0d28\u0d4b\u0d24\u0d3f \u0d38\u0d30\u0d4d\u0d35\u0d26\u0d3e \u0965 \u0d6f \u0965", "iast": "mah\u0101lak\u1e63mya\u1e63\u1e6daka\u1e43 stotra\u1e43 ya\u1e25 pa\u1e6dhedbhaktim\u0101nnara\u1e25 |\nsarvasiddhimav\u0101pnoti r\u0101jya\u1e43 pr\u0101pnoti sarvad\u0101 || 9 ||"},
        draftTranslation: "Whoever devoutly recites this Mahalakshmi Ashtakam hymn attains all perfections and secures sovereignty and spiritual triumph for all time.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 10,
        devanagariText: "\u090f\u0915\u0915\u093e\u0932\u0947 \u092a\u0920\u0947\u0928\u094d\u0928\u093f\u0924\u094d\u092f\u0902 \u092e\u0939\u093e\u092a\u093e\u092a\u0935\u093f\u0928\u093e\u0936\u0928\u092e\u094d \u0964\n\u0926\u094d\u0935\u093f\u0915\u093e\u0932\u0902 \u092f\u0903 \u092a\u0920\u0947\u0928\u094d\u0928\u093f\u0924\u094d\u092f\u0902 \u0927\u0928\u0927\u093e\u0928\u094d\u092f\u0938\u092e\u0928\u094d\u0935\u093f\u0924\u0903 \u0964\n\u0924\u094d\u0930\u093f\u0915\u093e\u0932\u0902 \u092f\u0903 \u092a\u0920\u0947\u0928\u094d\u0928\u093f\u0924\u094d\u092f\u0902 \u092e\u0939\u093e\u0936\u0924\u094d\u0930\u0941\u0935\u093f\u0928\u093e\u0936\u0928\u092e\u094d \u0964\n\u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u0930\u094d\u092d\u0935\u0947\u0928\u094d\u0928\u093f\u0924\u094d\u092f\u0902 \u092a\u094d\u0930\u0938\u0928\u094d\u0928\u093e \u0935\u0930\u0926\u093e \u0936\u0941\u092d\u093e \u0965 \u0967\u0966 \u0965",
        iastText: "\u0113kak\u0101l\u0113 pa\u1e6dh\u0113nnitya\u1e41 mah\u0101p\u0101pavin\u0101\u015banam \u0964\ndvik\u0101la\u1e41 ya\u1e25 pa\u1e6dh\u0113nnitya\u1e41 dhanadh\u0101nyasamanvita\u1e25 \u0964\ntrik\u0101la\u1e41 ya\u1e25 pa\u1e6dh\u0113nnitya\u1e41 mah\u0101\u015batruvin\u0101\u015banam \u0964\nmah\u0101lak\u1e63m\u012brbhav\u0113nnitya\u1e41 prasann\u0101 varad\u0101 \u015bubh\u0101 \u0965 10 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c0f\u0c15\u0c15\u0c3e\u0c32\u0c47 \u0c2a\u0c20\u0c47\u0c28\u0c4d\u0c28\u0c3f\u0c24\u0c4d\u0c2f\u0c02 \u0c2e\u0c39\u0c3e\u0c2a\u0c3e\u0c2a\u0c35\u0c3f\u0c28\u0c3e\u0c36\u0c28\u0c2e\u0c4d \u0964\n\u0c26\u0c4d\u0c35\u0c3f\u0c15\u0c3e\u0c32\u0c02 \u0c2f\u0c03 \u0c2a\u0c20\u0c47\u0c28\u0c4d\u0c28\u0c3f\u0c24\u0c4d\u0c2f\u0c02 \u0c27\u0c28\u0c27\u0c3e\u0c28\u0c4d\u0c2f\u0c38\u0c2e\u0c28\u0c4d\u0c35\u0c3f\u0c24\u0c03 \u0964\n\u0c24\u0c4d\u0c30\u0c3f\u0c15\u0c3e\u0c32\u0c02 \u0c2f\u0c03 \u0c2a\u0c20\u0c47\u0c28\u0c4d\u0c28\u0c3f\u0c24\u0c4d\u0c2f\u0c02 \u0c2e\u0c39\u0c3e\u0c36\u0c24\u0c4d\u0c30\u0c41\u0c35\u0c3f\u0c28\u0c3e\u0c36\u0c28\u0c2e\u0c4d \u0964\n\u0c2e\u0c39\u0c3e\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c40\u0c30\u0c4d\u0c2d\u0c35\u0c47\u0c28\u0c4d\u0c28\u0c3f\u0c24\u0c4d\u0c2f\u0c02 \u0c2a\u0c4d\u0c30\u0c38\u0c28\u0c4d\u0c28\u0c3e \u0c35\u0c30\u0c26\u0c3e \u0c36\u0c41\u0c2d\u0c3e \u0965 \u0c67\u0c66 \u0965", "tamil": "\u0b8f\u0b95\u0b95\u0bbe\u0bb2\u0bc7 \u0baa\u0b9f\u0bc7\u0ba8\u0bcd\u0ba8\u0bbf\u0ba4\u0bcd\u0baf\u0bae\u0bcd \u0bae\u0bb9\u0bbe\u0baa\u0bbe\u0baa\u0bb5\u0bbf\u0ba8\u0bbe\u0bb6\u0ba8\u0bae\u0bcd \u0964\n\u0ba4\u0bcd\u0bb5\u0bbf\u0b95\u0bbe\u0bb2\u0bae\u0bcd \u0baf\u0b83 \u0baa\u0b9f\u0bc7\u0ba8\u0bcd\u0ba8\u0bbf\u0ba4\u0bcd\u0baf\u0bae\u0bcd \u0ba4\u0ba8\u0ba4\u0bbe\u0ba8\u0bcd\u0baf\u0bb8\u0bae\u0ba8\u0bcd\u0bb5\u0bbf\u0ba4\u0b83 \u0964\n\u0ba4\u0bcd\u0bb0\u0bbf\u0b95\u0bbe\u0bb2\u0bae\u0bcd \u0baf\u0b83 \u0baa\u0b9f\u0bc7\u0ba8\u0bcd\u0ba8\u0bbf\u0ba4\u0bcd\u0baf\u0bae\u0bcd \u0bae\u0bb9\u0bbe\u0bb6\u0ba4\u0bcd\u0bb0\u0bc1\u0bb5\u0bbf\u0ba8\u0bbe\u0bb6\u0ba8\u0bae\u0bcd \u0964\n\u0bae\u0bb9\u0bbe\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bc0\u0bb0\u0bcd\u0baa\u0bb5\u0bc7\u0ba8\u0bcd\u0ba8\u0bbf\u0ba4\u0bcd\u0baf\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0bb8\u0ba8\u0bcd\u0ba8\u0bbe \u0bb5\u0bb0\u0ba4\u0bbe \u0bb6\u0bc1\u0baa\u0bbe \u0965 \u0be7\u0be6 \u0965", "kannada": "\u0c8f\u0c95\u0c95\u0cbe\u0cb2\u0cc7 \u0caa\u0ca0\u0cc7\u0ca8\u0ccd\u0ca8\u0cbf\u0ca4\u0ccd\u0caf\u0c82 \u0cae\u0cb9\u0cbe\u0caa\u0cbe\u0caa\u0cb5\u0cbf\u0ca8\u0cbe\u0cb6\u0ca8\u0cae\u0ccd \u0964\n\u0ca6\u0ccd\u0cb5\u0cbf\u0c95\u0cbe\u0cb2\u0c82 \u0caf\u0c83 \u0caa\u0ca0\u0cc7\u0ca8\u0ccd\u0ca8\u0cbf\u0ca4\u0ccd\u0caf\u0c82 \u0ca7\u0ca8\u0ca7\u0cbe\u0ca8\u0ccd\u0caf\u0cb8\u0cae\u0ca8\u0ccd\u0cb5\u0cbf\u0ca4\u0c83 \u0964\n\u0ca4\u0ccd\u0cb0\u0cbf\u0c95\u0cbe\u0cb2\u0c82 \u0caf\u0c83 \u0caa\u0ca0\u0cc7\u0ca8\u0ccd\u0ca8\u0cbf\u0ca4\u0ccd\u0caf\u0c82 \u0cae\u0cb9\u0cbe\u0cb6\u0ca4\u0ccd\u0cb0\u0cc1\u0cb5\u0cbf\u0ca8\u0cbe\u0cb6\u0ca8\u0cae\u0ccd \u0964\n\u0cae\u0cb9\u0cbe\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cc0\u0cb0\u0ccd\u0cad\u0cb5\u0cc7\u0ca8\u0ccd\u0ca8\u0cbf\u0ca4\u0ccd\u0caf\u0c82 \u0caa\u0ccd\u0cb0\u0cb8\u0ca8\u0ccd\u0ca8\u0cbe \u0cb5\u0cb0\u0ca6\u0cbe \u0cb6\u0cc1\u0cad\u0cbe \u0965 \u0ce7\u0ce6 \u0965", "malayalam": "\u0d0f\u0d15\u0d15\u0d3e\u0d32\u0d47 \u0d2a\u0d20\u0d47\u0d28\u0d4d\u0d28\u0d3f\u0d24\u0d4d\u0d2f\u0d02 \u0d2e\u0d39\u0d3e\u0d2a\u0d3e\u0d2a\u0d35\u0d3f\u0d28\u0d3e\u0d36\u0d28\u0d2e\u0d4d \u0964\n\u0d26\u0d4d\u0d35\u0d3f\u0d15\u0d3e\u0d32\u0d02 \u0d2f\u0d03 \u0d2a\u0d20\u0d47\u0d28\u0d4d\u0d28\u0d3f\u0d24\u0d4d\u0d2f\u0d02 \u0d27\u0d28\u0d27\u0d3e\u0d28\u0d4d\u0d2f\u0d38\u0d2e\u0d28\u0d4d\u0d35\u0d3f\u0d24\u0d03 \u0964\n\u0d24\u0d4d\u0d30\u0d3f\u0d15\u0d3e\u0d32\u0d02 \u0d2f\u0d03 \u0d2a\u0d20\u0d47\u0d28\u0d4d\u0d28\u0d3f\u0d24\u0d4d\u0d2f\u0d02 \u0d2e\u0d39\u0d3e\u0d36\u0d24\u0d4d\u0d30\u0d41\u0d35\u0d3f\u0d28\u0d3e\u0d36\u0d28\u0d2e\u0d4d \u0964\n\u0d2e\u0d39\u0d3e\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d40\u0d30\u0d4d\u0d2d\u0d35\u0d47\u0d28\u0d4d\u0d28\u0d3f\u0d24\u0d4d\u0d2f\u0d02 \u0d2a\u0d4d\u0d30\u0d38\u0d28\u0d4d\u0d28\u0d3e \u0d35\u0d30\u0d26\u0d3e \u0d36\u0d41\u0d2d\u0d3e \u0965 \u0d67\u0d66 \u0965", "iast": "ekak\u0101le pa\u1e6dhennitya\u1e43 mah\u0101p\u0101pavin\u0101\u015banam |\ndvik\u0101la\u1e43 ya\u1e25 pa\u1e6dhennitya\u1e43 dhanadh\u0101nyasamanvita\u1e25 |\ntrik\u0101la\u1e43 ya\u1e25 pa\u1e6dhennitya\u1e43 mah\u0101\u015batruvin\u0101\u015banam |\nmah\u0101lak\u1e63m\u012brbhavennitya\u1e43 prasann\u0101 varad\u0101 \u015bubh\u0101 || 10 ||"},
        draftTranslation: "Reciting once daily dispels monumental sins; reciting twice daily blesses one with abundant wealth and sustenance; reciting thrice daily vanquishes formidable adversaries; and Goddess Mahalakshmi remains ever pleased, auspicious, and ready to bestow boons.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
    ],
  ),
  Scripture(
    id: 11,
    contentId: "VEDA-TXT-00011",
    canonicalTitle: "Lingashtakam",
    devanagariTitle: "\u0932\u093f\u0919\u094d\u0917\u093e\u0937\u094d\u091f\u0915\u092e\u094d",
    category: "Stotra",
    deity: "Lord Shiva",
    composer: "Traditional (Shaiva Agama / Sage Agastya)",
    rishi: "Traditional Vedic Sage",
    chandas: "Anushtubh",
    devata: "Lord Shiva",
    sourceScripture: "Shaiva Agama / Linga Purana Tradition",
    traditionalUsage: "Shiva Linga Abhishekam, Daily Chanting, Mukti",
    verseCount: 9,
    verses: [
      Verse(
        verseNumber: 1,
        devanagariText: "\u092c\u094d\u0930\u0939\u094d\u092e\u092e\u0941\u0930\u093e\u0930\u093f\u0938\u0941\u0930\u093e\u0930\u094d\u091a\u093f\u0924\u0932\u093f\u0919\u094d\u0917\u0902 \u0928\u093f\u0930\u094d\u092e\u0932\u092d\u093e\u0938\u093f\u0924\u0936\u094b\u092d\u093f\u0924\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0964\n\u091c\u0928\u094d\u092e\u091c\u0926\u0941\u0903\u0916\u0935\u093f\u0928\u093e\u0936\u0915\u0932\u093f\u0919\u094d\u0917\u0902 \u0924\u0924\u094d \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u093f \u0938\u0926\u093e\u0936\u093f\u0935\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0965 \u0967 \u0965",
        iastText: "brahmamur\u0101risur\u0101rcitali\u1e45ga\u1e41 nirmalabh\u0101sita\u015b\u014dbhitali\u1e45gam \u0964\njanmajadukhavin\u0101\u015bakali\u1e45ga\u1e41 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam \u0965 1 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2c\u0c4d\u0c30\u0c39\u0c4d\u0c2e\u0c2e\u0c41\u0c30\u0c3e\u0c30\u0c3f\u0c38\u0c41\u0c30\u0c3e\u0c30\u0c4d\u0c1a\u0c3f\u0c24\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c28\u0c3f\u0c30\u0c4d\u0c2e\u0c32\u0c2d\u0c3e\u0c38\u0c3f\u0c24\u0c36\u0c4b\u0c2d\u0c3f\u0c24\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0964\n\u0c1c\u0c28\u0c4d\u0c2e\u0c1c\u0c26\u0c41\u0c03\u0c16\u0c35\u0c3f\u0c28\u0c3e\u0c36\u0c15\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c24\u0c24\u0c4d \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c3f \u0c38\u0c26\u0c3e\u0c36\u0c3f\u0c35\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0965 \u0c67 \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0bb9\u0bcd\u0bae\u0bae\u0bc1\u0bb0\u0bbe\u0bb0\u0bbf\u0bb8\u0bc1\u0bb0\u0bbe\u0bb0\u0bcd\u0b9a\u0bbf\u0ba4\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0ba8\u0bbf\u0bb0\u0bcd\u0bae\u0bb2\u0baa\u0bbe\u0bb8\u0bbf\u0ba4\u0bb6\u0bcb\u0baa\u0bbf\u0ba4\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0964\n\u0b9c\u0ba8\u0bcd\u0bae\u0b9c\u0ba4\u0bc1\u0b83\u0b95\u0bb5\u0bbf\u0ba8\u0bbe\u0bb6\u0b95\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0ba4\u0ba4\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bbf \u0bb8\u0ba4\u0bbe\u0bb6\u0bbf\u0bb5\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0965 \u0be7 \u0965", "kannada": "\u0cac\u0ccd\u0cb0\u0cb9\u0ccd\u0cae\u0cae\u0cc1\u0cb0\u0cbe\u0cb0\u0cbf\u0cb8\u0cc1\u0cb0\u0cbe\u0cb0\u0ccd\u0c9a\u0cbf\u0ca4\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0ca8\u0cbf\u0cb0\u0ccd\u0cae\u0cb2\u0cad\u0cbe\u0cb8\u0cbf\u0ca4\u0cb6\u0ccb\u0cad\u0cbf\u0ca4\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0964\n\u0c9c\u0ca8\u0ccd\u0cae\u0c9c\u0ca6\u0cc1\u0c83\u0c96\u0cb5\u0cbf\u0ca8\u0cbe\u0cb6\u0c95\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0ca4\u0ca4\u0ccd \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0cbf \u0cb8\u0ca6\u0cbe\u0cb6\u0cbf\u0cb5\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0965 \u0ce7 \u0965", "malayalam": "\u0d2c\u0d4d\u0d30\u0d39\u0d4d\u0d2e\u0d2e\u0d41\u0d30\u0d3e\u0d30\u0d3f\u0d38\u0d41\u0d30\u0d3e\u0d30\u0d4d\u0d1a\u0d3f\u0d24\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d28\u0d3f\u0d30\u0d4d\u0d2e\u0d32\u0d2d\u0d3e\u0d38\u0d3f\u0d24\u0d36\u0d4b\u0d2d\u0d3f\u0d24\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0964\n\u0d1c\u0d28\u0d4d\u0d2e\u0d1c\u0d26\u0d41\u0d03\u0d16\u0d35\u0d3f\u0d28\u0d3e\u0d36\u0d15\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d24\u0d24\u0d4d \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d3f \u0d38\u0d26\u0d3e\u0d36\u0d3f\u0d35\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0965 \u0d67 \u0965", "iast": "brahmamur\u0101risur\u0101rcitali\u1e45ga\u1e43 nirmalabh\u0101sita\u015bobhitali\u1e45gam |\njanmajadu\u1e25khavin\u0101\u015bakali\u1e45ga\u1e43 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam || 1 ||"},
        draftTranslation: "I bow before that eternal Sadashiva Lingam, which is worshipped by Brahma, Vishnu, and all the gods, effulgent with spotless pure radiance, and the destroyer of grief originating from cyclical birth.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 2,
        devanagariText: "\u0926\u0947\u0935\u092e\u0941\u0928\u093f\u092a\u094d\u0930\u0935\u0930\u093e\u0930\u094d\u091a\u093f\u0924\u0932\u093f\u0919\u094d\u0917\u0902 \u0915\u093e\u092e\u0926\u0939\u0902 \u0915\u0930\u0941\u0923\u093e\u0915\u0930\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0964\n\u0930\u093e\u0935\u0923\u0926\u0930\u094d\u092a\u0935\u093f\u0928\u093e\u0936\u0928\u0932\u093f\u0919\u094d\u0917\u0902 \u0924\u0924\u094d \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u093f \u0938\u0926\u093e\u0936\u093f\u0935\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0965 \u0968 \u0965",
        iastText: "d\u0113vamunipravar\u0101rcitali\u1e45ga\u1e41 k\u0101madaha\u1e41 karu\u1e47\u0101karali\u1e45gam \u0964\nr\u0101va\u1e47adarpavin\u0101\u015banali\u1e45ga\u1e41 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam \u0965 2 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c26\u0c47\u0c35\u0c2e\u0c41\u0c28\u0c3f\u0c2a\u0c4d\u0c30\u0c35\u0c30\u0c3e\u0c30\u0c4d\u0c1a\u0c3f\u0c24\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c15\u0c3e\u0c2e\u0c26\u0c39\u0c02 \u0c15\u0c30\u0c41\u0c23\u0c3e\u0c15\u0c30\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0964\n\u0c30\u0c3e\u0c35\u0c23\u0c26\u0c30\u0c4d\u0c2a\u0c35\u0c3f\u0c28\u0c3e\u0c36\u0c28\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c24\u0c24\u0c4d \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c3f \u0c38\u0c26\u0c3e\u0c36\u0c3f\u0c35\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0965 \u0c68 \u0965", "tamil": "\u0ba4\u0bc7\u0bb5\u0bae\u0bc1\u0ba8\u0bbf\u0baa\u0bcd\u0bb0\u0bb5\u0bb0\u0bbe\u0bb0\u0bcd\u0b9a\u0bbf\u0ba4\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0b95\u0bbe\u0bae\u0ba4\u0bb9\u0bae\u0bcd \u0b95\u0bb0\u0bc1\u0ba3\u0bbe\u0b95\u0bb0\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0964\n\u0bb0\u0bbe\u0bb5\u0ba3\u0ba4\u0bb0\u0bcd\u0baa\u0bb5\u0bbf\u0ba8\u0bbe\u0bb6\u0ba8\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0ba4\u0ba4\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bbf \u0bb8\u0ba4\u0bbe\u0bb6\u0bbf\u0bb5\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0965 \u0be8 \u0965", "kannada": "\u0ca6\u0cc7\u0cb5\u0cae\u0cc1\u0ca8\u0cbf\u0caa\u0ccd\u0cb0\u0cb5\u0cb0\u0cbe\u0cb0\u0ccd\u0c9a\u0cbf\u0ca4\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0c95\u0cbe\u0cae\u0ca6\u0cb9\u0c82 \u0c95\u0cb0\u0cc1\u0ca3\u0cbe\u0c95\u0cb0\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0964\n\u0cb0\u0cbe\u0cb5\u0ca3\u0ca6\u0cb0\u0ccd\u0caa\u0cb5\u0cbf\u0ca8\u0cbe\u0cb6\u0ca8\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0ca4\u0ca4\u0ccd \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0cbf \u0cb8\u0ca6\u0cbe\u0cb6\u0cbf\u0cb5\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0965 \u0ce8 \u0965", "malayalam": "\u0d26\u0d47\u0d35\u0d2e\u0d41\u0d28\u0d3f\u0d2a\u0d4d\u0d30\u0d35\u0d30\u0d3e\u0d30\u0d4d\u0d1a\u0d3f\u0d24\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d15\u0d3e\u0d2e\u0d26\u0d39\u0d02 \u0d15\u0d30\u0d41\u0d23\u0d3e\u0d15\u0d30\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0964\n\u0d30\u0d3e\u0d35\u0d23\u0d26\u0d30\u0d4d\u0d2a\u0d35\u0d3f\u0d28\u0d3e\u0d36\u0d28\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d24\u0d24\u0d4d \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d3f \u0d38\u0d26\u0d3e\u0d36\u0d3f\u0d35\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0965 \u0d68 \u0965", "iast": "devamunipravar\u0101rcitali\u1e45ga\u1e43 k\u0101madaha\u1e43 karu\u1e47\u0101karali\u1e45gam |\nr\u0101va\u1e47adarpavin\u0101\u015banali\u1e45ga\u1e43 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam || 2 ||"},
        draftTranslation: "I bow before that eternal Sadashiva Lingam, revered by the foremost of gods and sages, consumer of lust (Kamadeva), treasury of compassion, and destroyer of the pride of Ravana.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 3,
        devanagariText: "\u0938\u0930\u094d\u0935\u0938\u0941\u0917\u0928\u094d\u0927\u093f\u0938\u0941\u0932\u0947\u092a\u093f\u0924\u0932\u093f\u0919\u094d\u0917\u0902 \u092c\u0941\u0926\u094d\u0927\u093f\u0935\u093f\u0935\u0930\u094d\u0927\u0928\u0915\u093e\u0930\u0923\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0964\n\u0938\u093f\u0926\u094d\u0927\u0938\u0941\u0930\u093e\u0938\u0941\u0930\u0935\u0928\u094d\u0926\u093f\u0924\u0932\u093f\u0919\u094d\u0917\u0902 \u0924\u0924\u094d \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u093f \u0938\u0926\u093e\u0936\u093f\u0935\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0965 \u0969 \u0965",
        iastText: "sarvasugandhisul\u0113pitali\u1e45ga\u1e41 buddhivivardhanak\u0101ra\u1e47ali\u1e45gam \u0964\nsiddhasur\u0101suravanditali\u1e45ga\u1e41 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam \u0965 3 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0c30\u0c4d\u0c35\u0c38\u0c41\u0c17\u0c28\u0c4d\u0c27\u0c3f\u0c38\u0c41\u0c32\u0c47\u0c2a\u0c3f\u0c24\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c2c\u0c41\u0c26\u0c4d\u0c27\u0c3f\u0c35\u0c3f\u0c35\u0c30\u0c4d\u0c27\u0c28\u0c15\u0c3e\u0c30\u0c23\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0964\n\u0c38\u0c3f\u0c26\u0c4d\u0c27\u0c38\u0c41\u0c30\u0c3e\u0c38\u0c41\u0c30\u0c35\u0c28\u0c4d\u0c26\u0c3f\u0c24\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c24\u0c24\u0c4d \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c3f \u0c38\u0c26\u0c3e\u0c36\u0c3f\u0c35\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0965 \u0c69 \u0965", "tamil": "\u0bb8\u0bb0\u0bcd\u0bb5\u0bb8\u0bc1\u0b95\u0ba8\u0bcd\u0ba4\u0bbf\u0bb8\u0bc1\u0bb2\u0bc7\u0baa\u0bbf\u0ba4\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0baa\u0bc1\u0ba4\u0bcd\u0ba4\u0bbf\u0bb5\u0bbf\u0bb5\u0bb0\u0bcd\u0ba4\u0ba8\u0b95\u0bbe\u0bb0\u0ba3\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0964\n\u0bb8\u0bbf\u0ba4\u0bcd\u0ba4\u0bb8\u0bc1\u0bb0\u0bbe\u0bb8\u0bc1\u0bb0\u0bb5\u0ba8\u0bcd\u0ba4\u0bbf\u0ba4\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0ba4\u0ba4\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bbf \u0bb8\u0ba4\u0bbe\u0bb6\u0bbf\u0bb5\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0965 \u0be9 \u0965", "kannada": "\u0cb8\u0cb0\u0ccd\u0cb5\u0cb8\u0cc1\u0c97\u0ca8\u0ccd\u0ca7\u0cbf\u0cb8\u0cc1\u0cb2\u0cc7\u0caa\u0cbf\u0ca4\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0cac\u0cc1\u0ca6\u0ccd\u0ca7\u0cbf\u0cb5\u0cbf\u0cb5\u0cb0\u0ccd\u0ca7\u0ca8\u0c95\u0cbe\u0cb0\u0ca3\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0964\n\u0cb8\u0cbf\u0ca6\u0ccd\u0ca7\u0cb8\u0cc1\u0cb0\u0cbe\u0cb8\u0cc1\u0cb0\u0cb5\u0ca8\u0ccd\u0ca6\u0cbf\u0ca4\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0ca4\u0ca4\u0ccd \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0cbf \u0cb8\u0ca6\u0cbe\u0cb6\u0cbf\u0cb5\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0965 \u0ce9 \u0965", "malayalam": "\u0d38\u0d30\u0d4d\u0d35\u0d38\u0d41\u0d17\u0d28\u0d4d\u0d27\u0d3f\u0d38\u0d41\u0d32\u0d47\u0d2a\u0d3f\u0d24\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d2c\u0d41\u0d26\u0d4d\u0d27\u0d3f\u0d35\u0d3f\u0d35\u0d30\u0d4d\u0d27\u0d28\u0d15\u0d3e\u0d30\u0d23\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0964\n\u0d38\u0d3f\u0d26\u0d4d\u0d27\u0d38\u0d41\u0d30\u0d3e\u0d38\u0d41\u0d30\u0d35\u0d28\u0d4d\u0d26\u0d3f\u0d24\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d24\u0d24\u0d4d \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d3f \u0d38\u0d26\u0d3e\u0d36\u0d3f\u0d35\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0965 \u0d69 \u0965", "iast": "sarvasugandhisulepitali\u1e45ga\u1e43 buddhivivardhanak\u0101ra\u1e47ali\u1e45gam |\nsiddhasur\u0101suravanditali\u1e45ga\u1e43 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam || 3 ||"},
        draftTranslation: "I bow before that eternal Sadashiva Lingam, anointed with fragrant perfumes, the sovereign cause of intellectual elevation, adored by Siddhas, gods, and demons alike.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 4,
        devanagariText: "\u0915\u0928\u0915\u092e\u0939\u093e\u092e\u0923\u093f\u092d\u0942\u0937\u093f\u0924\u0932\u093f\u0919\u094d\u0917\u0902 \u092b\u0923\u093f\u092a\u0924\u093f\u0935\u0947\u0937\u094d\u091f\u093f\u0924\u0936\u094b\u092d\u093f\u0924\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0964\n\u0926\u0915\u094d\u0937\u0938\u0941\u092f\u091c\u094d\u091e\u0935\u093f\u0928\u093e\u0936\u0928\u0932\u093f\u0919\u094d\u0917\u0902 \u0924\u0924\u094d \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u093f \u0938\u0926\u093e\u0936\u093f\u0935\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0965 \u096a \u0965",
        iastText: "kanakamah\u0101ma\u1e47ibh\u016b\u1e63itali\u1e45ga\u1e41 pha\u1e47ipativ\u0113\u1e63\u1e6dita\u015b\u014dbhitali\u1e45gam \u0964\ndak\u1e63asuyaj\u00f1avin\u0101\u015banali\u1e45ga\u1e41 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam \u0965 4 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c15\u0c28\u0c15\u0c2e\u0c39\u0c3e\u0c2e\u0c23\u0c3f\u0c2d\u0c42\u0c37\u0c3f\u0c24\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c2b\u0c23\u0c3f\u0c2a\u0c24\u0c3f\u0c35\u0c47\u0c37\u0c4d\u0c1f\u0c3f\u0c24\u0c36\u0c4b\u0c2d\u0c3f\u0c24\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0964\n\u0c26\u0c15\u0c4d\u0c37\u0c38\u0c41\u0c2f\u0c1c\u0c4d\u0c1e\u0c35\u0c3f\u0c28\u0c3e\u0c36\u0c28\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c24\u0c24\u0c4d \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c3f \u0c38\u0c26\u0c3e\u0c36\u0c3f\u0c35\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0965 \u0c6a \u0965", "tamil": "\u0b95\u0ba8\u0b95\u0bae\u0bb9\u0bbe\u0bae\u0ba3\u0bbf\u0baa\u0bc2\u0bb7\u0bbf\u0ba4\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0baa\u0ba3\u0bbf\u0baa\u0ba4\u0bbf\u0bb5\u0bc7\u0bb7\u0bcd\u0b9f\u0bbf\u0ba4\u0bb6\u0bcb\u0baa\u0bbf\u0ba4\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0964\n\u0ba4\u0b95\u0bcd\u0bb7\u0bb8\u0bc1\u0baf\u0b9c\u0bcd\u0b9e\u0bb5\u0bbf\u0ba8\u0bbe\u0bb6\u0ba8\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0ba4\u0ba4\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bbf \u0bb8\u0ba4\u0bbe\u0bb6\u0bbf\u0bb5\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0965 \u0bea \u0965", "kannada": "\u0c95\u0ca8\u0c95\u0cae\u0cb9\u0cbe\u0cae\u0ca3\u0cbf\u0cad\u0cc2\u0cb7\u0cbf\u0ca4\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0cab\u0ca3\u0cbf\u0caa\u0ca4\u0cbf\u0cb5\u0cc7\u0cb7\u0ccd\u0c9f\u0cbf\u0ca4\u0cb6\u0ccb\u0cad\u0cbf\u0ca4\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0964\n\u0ca6\u0c95\u0ccd\u0cb7\u0cb8\u0cc1\u0caf\u0c9c\u0ccd\u0c9e\u0cb5\u0cbf\u0ca8\u0cbe\u0cb6\u0ca8\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0ca4\u0ca4\u0ccd \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0cbf \u0cb8\u0ca6\u0cbe\u0cb6\u0cbf\u0cb5\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0965 \u0cea \u0965", "malayalam": "\u0d15\u0d28\u0d15\u0d2e\u0d39\u0d3e\u0d2e\u0d23\u0d3f\u0d2d\u0d42\u0d37\u0d3f\u0d24\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d2b\u0d23\u0d3f\u0d2a\u0d24\u0d3f\u0d35\u0d47\u0d37\u0d4d\u0d1f\u0d3f\u0d24\u0d36\u0d4b\u0d2d\u0d3f\u0d24\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0964\n\u0d26\u0d15\u0d4d\u0d37\u0d38\u0d41\u0d2f\u0d1c\u0d4d\u0d1e\u0d35\u0d3f\u0d28\u0d3e\u0d36\u0d28\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d24\u0d24\u0d4d \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d3f \u0d38\u0d26\u0d3e\u0d36\u0d3f\u0d35\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0965 \u0d6a \u0965", "iast": "kanakamah\u0101ma\u1e47ibh\u016b\u1e63itali\u1e45ga\u1e43 pha\u1e47ipative\u1e63\u1e6dita\u015bobhitali\u1e45gam |\ndak\u1e63asuyaj\u00f1avin\u0101\u015banali\u1e45ga\u1e43 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam || 4 ||"},
        draftTranslation: "I bow before that eternal Sadashiva Lingam, embellished with gold and lustrous gems, adorned by the serpent king coiled around it, the vanquisher of the proud sacrifice of Daksha.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 5,
        devanagariText: "\u0915\u0941\u0919\u094d\u0915\u0941\u092e\u091a\u0928\u094d\u0926\u0928\u0932\u0947\u092a\u093f\u0924\u0932\u093f\u0919\u094d\u0917\u0902 \u092a\u0919\u094d\u0915\u091c\u0939\u093e\u0930\u0938\u0941\u0936\u094b\u092d\u093f\u0924\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0964\n\u0938\u091e\u094d\u091a\u093f\u0924\u092a\u093e\u092a\u0935\u093f\u0928\u093e\u0936\u0928\u0932\u093f\u0919\u094d\u0917\u0902 \u0924\u0924\u094d \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u093f \u0938\u0926\u093e\u0936\u093f\u0935\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0965 \u096b \u0965",
        iastText: "ku\u1e45kumacandanal\u0113pitali\u1e45ga\u1e41 pa\u1e45kajah\u0101rasu\u015b\u014dbhitali\u1e45gam \u0964\nsa\u00f1citap\u0101pavin\u0101\u015banali\u1e45ga\u1e41 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam \u0965 5 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c15\u0c41\u0c19\u0c4d\u0c15\u0c41\u0c2e\u0c1a\u0c28\u0c4d\u0c26\u0c28\u0c32\u0c47\u0c2a\u0c3f\u0c24\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c2a\u0c19\u0c4d\u0c15\u0c1c\u0c39\u0c3e\u0c30\u0c38\u0c41\u0c36\u0c4b\u0c2d\u0c3f\u0c24\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0964\n\u0c38\u0c1e\u0c4d\u0c1a\u0c3f\u0c24\u0c2a\u0c3e\u0c2a\u0c35\u0c3f\u0c28\u0c3e\u0c36\u0c28\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c24\u0c24\u0c4d \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c3f \u0c38\u0c26\u0c3e\u0c36\u0c3f\u0c35\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0965 \u0c6b \u0965", "tamil": "\u0b95\u0bc1\u0b99\u0bcd\u0b95\u0bc1\u0bae\u0b9a\u0ba8\u0bcd\u0ba4\u0ba8\u0bb2\u0bc7\u0baa\u0bbf\u0ba4\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0baa\u0b99\u0bcd\u0b95\u0b9c\u0bb9\u0bbe\u0bb0\u0bb8\u0bc1\u0bb6\u0bcb\u0baa\u0bbf\u0ba4\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0964\n\u0bb8\u0b9e\u0bcd\u0b9a\u0bbf\u0ba4\u0baa\u0bbe\u0baa\u0bb5\u0bbf\u0ba8\u0bbe\u0bb6\u0ba8\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0ba4\u0ba4\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bbf \u0bb8\u0ba4\u0bbe\u0bb6\u0bbf\u0bb5\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0965 \u0beb \u0965", "kannada": "\u0c95\u0cc1\u0c99\u0ccd\u0c95\u0cc1\u0cae\u0c9a\u0ca8\u0ccd\u0ca6\u0ca8\u0cb2\u0cc7\u0caa\u0cbf\u0ca4\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0caa\u0c99\u0ccd\u0c95\u0c9c\u0cb9\u0cbe\u0cb0\u0cb8\u0cc1\u0cb6\u0ccb\u0cad\u0cbf\u0ca4\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0964\n\u0cb8\u0c9e\u0ccd\u0c9a\u0cbf\u0ca4\u0caa\u0cbe\u0caa\u0cb5\u0cbf\u0ca8\u0cbe\u0cb6\u0ca8\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0ca4\u0ca4\u0ccd \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0cbf \u0cb8\u0ca6\u0cbe\u0cb6\u0cbf\u0cb5\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0965 \u0ceb \u0965", "malayalam": "\u0d15\u0d41\u0d19\u0d4d\u0d15\u0d41\u0d2e\u0d1a\u0d28\u0d4d\u0d26\u0d28\u0d32\u0d47\u0d2a\u0d3f\u0d24\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d2a\u0d19\u0d4d\u0d15\u0d1c\u0d39\u0d3e\u0d30\u0d38\u0d41\u0d36\u0d4b\u0d2d\u0d3f\u0d24\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0964\n\u0d38\u0d1e\u0d4d\u0d1a\u0d3f\u0d24\u0d2a\u0d3e\u0d2a\u0d35\u0d3f\u0d28\u0d3e\u0d36\u0d28\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d24\u0d24\u0d4d \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d3f \u0d38\u0d26\u0d3e\u0d36\u0d3f\u0d35\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0965 \u0d6b \u0965", "iast": "ku\u1e45kumacandanalepitali\u1e45ga\u1e43 pa\u1e45kajah\u0101rasu\u015bobhitali\u1e45gam |\nsa\u00f1citap\u0101pavin\u0101\u015banali\u1e45ga\u1e43 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam || 5 ||"},
        draftTranslation: "I bow before that eternal Sadashiva Lingam, anointed with kumkuma and sandal paste, adorned with garlands of lotuses, the absolver of all accumulated sins.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 6,
        devanagariText: "\u0926\u0947\u0935\u0917\u0923\u093e\u0930\u094d\u091a\u093f\u0924\u0938\u0947\u0935\u093f\u0924\u0932\u093f\u0919\u094d\u0917\u0902 \u092d\u093e\u0935\u0948\u0930\u094d\u092d\u0915\u094d\u0924\u093f\u092d\u093f\u0930\u0947\u0935 \u091a \u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0964\n\u0926\u093f\u0928\u0915\u0930\u0915\u094b\u091f\u093f\u092a\u094d\u0930\u092d\u093e\u0915\u0930\u0932\u093f\u0919\u094d\u0917\u0902 \u0924\u0924\u094d \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u093f \u0938\u0926\u093e\u0936\u093f\u0935\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0965 \u096c \u0965",
        iastText: "d\u0113vaga\u1e47\u0101rcitas\u0113vitali\u1e45ga\u1e41 bh\u0101vairbhaktibhir\u0113va ca li\u1e45gam \u0964\ndinakarak\u014d\u1e6diprabh\u0101karali\u1e45ga\u1e41 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam \u0965 6 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c26\u0c47\u0c35\u0c17\u0c23\u0c3e\u0c30\u0c4d\u0c1a\u0c3f\u0c24\u0c38\u0c47\u0c35\u0c3f\u0c24\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c2d\u0c3e\u0c35\u0c48\u0c30\u0c4d\u0c2d\u0c15\u0c4d\u0c24\u0c3f\u0c2d\u0c3f\u0c30\u0c47\u0c35 \u0c1a \u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0964\n\u0c26\u0c3f\u0c28\u0c15\u0c30\u0c15\u0c4b\u0c1f\u0c3f\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c15\u0c30\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c24\u0c24\u0c4d \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c3f \u0c38\u0c26\u0c3e\u0c36\u0c3f\u0c35\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0965 \u0c6c \u0965", "tamil": "\u0ba4\u0bc7\u0bb5\u0b95\u0ba3\u0bbe\u0bb0\u0bcd\u0b9a\u0bbf\u0ba4\u0bb8\u0bc7\u0bb5\u0bbf\u0ba4\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0baa\u0bbe\u0bb5\u0bc8\u0bb0\u0bcd\u0baa\u0b95\u0bcd\u0ba4\u0bbf\u0baa\u0bbf\u0bb0\u0bc7\u0bb5 \u0b9a \u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0964\n\u0ba4\u0bbf\u0ba8\u0b95\u0bb0\u0b95\u0bcb\u0b9f\u0bbf\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0b95\u0bb0\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0ba4\u0ba4\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bbf \u0bb8\u0ba4\u0bbe\u0bb6\u0bbf\u0bb5\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0965 \u0bec \u0965", "kannada": "\u0ca6\u0cc7\u0cb5\u0c97\u0ca3\u0cbe\u0cb0\u0ccd\u0c9a\u0cbf\u0ca4\u0cb8\u0cc7\u0cb5\u0cbf\u0ca4\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0cad\u0cbe\u0cb5\u0cc8\u0cb0\u0ccd\u0cad\u0c95\u0ccd\u0ca4\u0cbf\u0cad\u0cbf\u0cb0\u0cc7\u0cb5 \u0c9a \u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0964\n\u0ca6\u0cbf\u0ca8\u0c95\u0cb0\u0c95\u0ccb\u0c9f\u0cbf\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0c95\u0cb0\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0ca4\u0ca4\u0ccd \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0cbf \u0cb8\u0ca6\u0cbe\u0cb6\u0cbf\u0cb5\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0965 \u0cec \u0965", "malayalam": "\u0d26\u0d47\u0d35\u0d17\u0d23\u0d3e\u0d30\u0d4d\u0d1a\u0d3f\u0d24\u0d38\u0d47\u0d35\u0d3f\u0d24\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d2d\u0d3e\u0d35\u0d48\u0d30\u0d4d\u0d2d\u0d15\u0d4d\u0d24\u0d3f\u0d2d\u0d3f\u0d30\u0d47\u0d35 \u0d1a \u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0964\n\u0d26\u0d3f\u0d28\u0d15\u0d30\u0d15\u0d4b\u0d1f\u0d3f\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d15\u0d30\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d24\u0d24\u0d4d \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d3f \u0d38\u0d26\u0d3e\u0d36\u0d3f\u0d35\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0965 \u0d6c \u0965", "iast": "devaga\u1e47\u0101rcitasevitali\u1e45ga\u1e43 bh\u0101vairbhaktibhireva ca li\u1e45gam |\ndinakarako\u1e6diprabh\u0101karali\u1e45ga\u1e43 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam || 6 ||"},
        draftTranslation: "I bow before that eternal Sadashiva Lingam, served and worshipped by assemblies of gods with profound devotional sentiment, blazing with the effulgence of ten million suns.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 7,
        devanagariText: "\u0905\u0937\u094d\u091f\u0926\u0932\u094b\u092a\u0930\u093f\u0935\u0947\u0937\u094d\u091f\u093f\u0924\u0932\u093f\u0919\u094d\u0917\u0902 \u0938\u0930\u094d\u0935\u0938\u092e\u0941\u0926\u094d\u092d\u0935\u0915\u093e\u0930\u0923\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0964\n\u0905\u0937\u094d\u091f\u0926\u0930\u093f\u0926\u094d\u0930\u0935\u093f\u0928\u093e\u0936\u0928\u0932\u093f\u0919\u094d\u0917\u0902 \u0924\u0924\u094d \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u093f \u0938\u0926\u093e\u0936\u093f\u0935\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0965 \u096d \u0965",
        iastText: "a\u1e63\u1e6dadal\u014dpariv\u0113\u1e63\u1e6ditali\u1e45ga\u1e41 sarvasamudbhavak\u0101ra\u1e47ali\u1e45gam \u0964\na\u1e63\u1e6dadaridravin\u0101\u015banali\u1e45ga\u1e41 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam \u0965 7 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c05\u0c37\u0c4d\u0c1f\u0c26\u0c32\u0c4b\u0c2a\u0c30\u0c3f\u0c35\u0c47\u0c37\u0c4d\u0c1f\u0c3f\u0c24\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c38\u0c30\u0c4d\u0c35\u0c38\u0c2e\u0c41\u0c26\u0c4d\u0c2d\u0c35\u0c15\u0c3e\u0c30\u0c23\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0964\n\u0c05\u0c37\u0c4d\u0c1f\u0c26\u0c30\u0c3f\u0c26\u0c4d\u0c30\u0c35\u0c3f\u0c28\u0c3e\u0c36\u0c28\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c24\u0c24\u0c4d \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c3f \u0c38\u0c26\u0c3e\u0c36\u0c3f\u0c35\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0965 \u0c6d \u0965", "tamil": "\u0b85\u0bb7\u0bcd\u0b9f\u0ba4\u0bb2\u0bcb\u0baa\u0bb0\u0bbf\u0bb5\u0bc7\u0bb7\u0bcd\u0b9f\u0bbf\u0ba4\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0bb8\u0bb0\u0bcd\u0bb5\u0bb8\u0bae\u0bc1\u0ba4\u0bcd\u0baa\u0bb5\u0b95\u0bbe\u0bb0\u0ba3\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0964\n\u0b85\u0bb7\u0bcd\u0b9f\u0ba4\u0bb0\u0bbf\u0ba4\u0bcd\u0bb0\u0bb5\u0bbf\u0ba8\u0bbe\u0bb6\u0ba8\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0ba4\u0ba4\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bbf \u0bb8\u0ba4\u0bbe\u0bb6\u0bbf\u0bb5\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0965 \u0bed \u0965", "kannada": "\u0c85\u0cb7\u0ccd\u0c9f\u0ca6\u0cb2\u0ccb\u0caa\u0cb0\u0cbf\u0cb5\u0cc7\u0cb7\u0ccd\u0c9f\u0cbf\u0ca4\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0cb8\u0cb0\u0ccd\u0cb5\u0cb8\u0cae\u0cc1\u0ca6\u0ccd\u0cad\u0cb5\u0c95\u0cbe\u0cb0\u0ca3\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0964\n\u0c85\u0cb7\u0ccd\u0c9f\u0ca6\u0cb0\u0cbf\u0ca6\u0ccd\u0cb0\u0cb5\u0cbf\u0ca8\u0cbe\u0cb6\u0ca8\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0ca4\u0ca4\u0ccd \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0cbf \u0cb8\u0ca6\u0cbe\u0cb6\u0cbf\u0cb5\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0965 \u0ced \u0965", "malayalam": "\u0d05\u0d37\u0d4d\u0d1f\u0d26\u0d32\u0d4b\u0d2a\u0d30\u0d3f\u0d35\u0d47\u0d37\u0d4d\u0d1f\u0d3f\u0d24\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d38\u0d30\u0d4d\u0d35\u0d38\u0d2e\u0d41\u0d26\u0d4d\u0d2d\u0d35\u0d15\u0d3e\u0d30\u0d23\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0964\n\u0d05\u0d37\u0d4d\u0d1f\u0d26\u0d30\u0d3f\u0d26\u0d4d\u0d30\u0d35\u0d3f\u0d28\u0d3e\u0d36\u0d28\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d24\u0d24\u0d4d \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d3f \u0d38\u0d26\u0d3e\u0d36\u0d3f\u0d35\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0965 \u0d6d \u0965", "iast": "a\u1e63\u1e6dadaloparive\u1e63\u1e6ditali\u1e45ga\u1e43 sarvasamudbhavak\u0101ra\u1e47ali\u1e45gam |\na\u1e63\u1e6dadaridravin\u0101\u015banali\u1e45ga\u1e43 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam || 7 ||"},
        draftTranslation: "I bow before that eternal Sadashiva Lingam, surrounded upon an eight-petaled lotus pedestal, the prime cause of universal creation, and the dispeller of eightfold poverty.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 8,
        devanagariText: "\u0938\u0941\u0930\u0917\u0941\u0930\u0941\u0938\u0941\u0930\u0935\u0930\u092a\u0942\u091c\u093f\u0924\u0932\u093f\u0919\u094d\u0917\u0902 \u0938\u0941\u0930\u0935\u0928\u092a\u0941\u0937\u094d\u092a\u0938\u0926\u093e\u0930\u094d\u091a\u093f\u0924\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0964\n\u092a\u0930\u093e\u0924\u094d\u092a\u0930\u0902 \u092a\u0930\u092e\u093e\u0924\u094d\u092e\u0915\u0932\u093f\u0919\u094d\u0917\u0902 \u0924\u0924\u094d \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u093f \u0938\u0926\u093e\u0936\u093f\u0935\u0932\u093f\u0919\u094d\u0917\u092e\u094d \u0965 \u096e \u0965",
        iastText: "suragurusuravarap\u016bjitali\u1e45ga\u1e41 suravanapu\u1e63pasad\u0101rcitali\u1e45gam \u0964\npar\u0101tpara\u1e41 param\u0101tmakali\u1e45ga\u1e41 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam \u0965 8 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0c41\u0c30\u0c17\u0c41\u0c30\u0c41\u0c38\u0c41\u0c30\u0c35\u0c30\u0c2a\u0c42\u0c1c\u0c3f\u0c24\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c38\u0c41\u0c30\u0c35\u0c28\u0c2a\u0c41\u0c37\u0c4d\u0c2a\u0c38\u0c26\u0c3e\u0c30\u0c4d\u0c1a\u0c3f\u0c24\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0964\n\u0c2a\u0c30\u0c3e\u0c24\u0c4d\u0c2a\u0c30\u0c02 \u0c2a\u0c30\u0c2e\u0c3e\u0c24\u0c4d\u0c2e\u0c15\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c02 \u0c24\u0c24\u0c4d \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c3f \u0c38\u0c26\u0c3e\u0c36\u0c3f\u0c35\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c2e\u0c4d \u0965 \u0c6e \u0965", "tamil": "\u0bb8\u0bc1\u0bb0\u0b95\u0bc1\u0bb0\u0bc1\u0bb8\u0bc1\u0bb0\u0bb5\u0bb0\u0baa\u0bc2\u0b9c\u0bbf\u0ba4\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0bb8\u0bc1\u0bb0\u0bb5\u0ba8\u0baa\u0bc1\u0bb7\u0bcd\u0baa\u0bb8\u0ba4\u0bbe\u0bb0\u0bcd\u0b9a\u0bbf\u0ba4\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0964\n\u0baa\u0bb0\u0bbe\u0ba4\u0bcd\u0baa\u0bb0\u0bae\u0bcd \u0baa\u0bb0\u0bae\u0bbe\u0ba4\u0bcd\u0bae\u0b95\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0ba4\u0ba4\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bbf \u0bb8\u0ba4\u0bbe\u0bb6\u0bbf\u0bb5\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0965 \u0bee \u0965", "kannada": "\u0cb8\u0cc1\u0cb0\u0c97\u0cc1\u0cb0\u0cc1\u0cb8\u0cc1\u0cb0\u0cb5\u0cb0\u0caa\u0cc2\u0c9c\u0cbf\u0ca4\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0cb8\u0cc1\u0cb0\u0cb5\u0ca8\u0caa\u0cc1\u0cb7\u0ccd\u0caa\u0cb8\u0ca6\u0cbe\u0cb0\u0ccd\u0c9a\u0cbf\u0ca4\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0964\n\u0caa\u0cb0\u0cbe\u0ca4\u0ccd\u0caa\u0cb0\u0c82 \u0caa\u0cb0\u0cae\u0cbe\u0ca4\u0ccd\u0cae\u0c95\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0c82 \u0ca4\u0ca4\u0ccd \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0cbf \u0cb8\u0ca6\u0cbe\u0cb6\u0cbf\u0cb5\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cae\u0ccd \u0965 \u0cee \u0965", "malayalam": "\u0d38\u0d41\u0d30\u0d17\u0d41\u0d30\u0d41\u0d38\u0d41\u0d30\u0d35\u0d30\u0d2a\u0d42\u0d1c\u0d3f\u0d24\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d38\u0d41\u0d30\u0d35\u0d28\u0d2a\u0d41\u0d37\u0d4d\u0d2a\u0d38\u0d26\u0d3e\u0d30\u0d4d\u0d1a\u0d3f\u0d24\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0964\n\u0d2a\u0d30\u0d3e\u0d24\u0d4d\u0d2a\u0d30\u0d02 \u0d2a\u0d30\u0d2e\u0d3e\u0d24\u0d4d\u0d2e\u0d15\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d02 \u0d24\u0d24\u0d4d \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d3f \u0d38\u0d26\u0d3e\u0d36\u0d3f\u0d35\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d2e\u0d4d \u0965 \u0d6e \u0965", "iast": "suragurusuravarap\u016bjitali\u1e45ga\u1e43 suravanapu\u1e63pasad\u0101rcitali\u1e45gam |\npar\u0101tpara\u1e43 param\u0101tmakali\u1e45ga\u1e43 tat pra\u1e47am\u0101mi sad\u0101\u015bivali\u1e45gam || 8 ||"},
        draftTranslation: "I bow before that eternal Sadashiva Lingam, worshipped by Brihaspati and the highest celestial beings, ever adored with blossoms from divine celestial gardens, transcendent beyond the highest, the supreme Self.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 9,
        devanagariText: "\u0932\u093f\u0919\u094d\u0917\u093e\u0937\u094d\u091f\u0915\u092e\u093f\u0926\u0902 \u092a\u0941\u0923\u094d\u092f\u0902 \u092f\u0903 \u092a\u0920\u0947\u0924\u094d \u0936\u093f\u0935\u0938\u0928\u094d\u0928\u093f\u0927\u094c \u0964\n\u0936\u093f\u0935\u0932\u094b\u0915\u092e\u0935\u093e\u092a\u094d\u0928\u094b\u0924\u093f \u0936\u093f\u0935\u0947\u0928 \u0938\u0939 \u092e\u094b\u0926\u0924\u0947 \u0965 \u096f \u0965",
        iastText: "li\u1e45g\u0101\u1e63\u1e6dakamida\u1e41 pu\u1e47ya\u1e41 ya\u1e25 pa\u1e6dh\u0113t \u015bivasannidhau \u0964\n\u015bival\u014dkamav\u0101pn\u014dti \u015biv\u0113na saha m\u014ddat\u0113 \u0965 9 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c32\u0c3f\u0c19\u0c4d\u0c17\u0c3e\u0c37\u0c4d\u0c1f\u0c15\u0c2e\u0c3f\u0c26\u0c02 \u0c2a\u0c41\u0c23\u0c4d\u0c2f\u0c02 \u0c2f\u0c03 \u0c2a\u0c20\u0c47\u0c24\u0c4d \u0c36\u0c3f\u0c35\u0c38\u0c28\u0c4d\u0c28\u0c3f\u0c27\u0c4c \u0964\n\u0c36\u0c3f\u0c35\u0c32\u0c4b\u0c15\u0c2e\u0c35\u0c3e\u0c2a\u0c4d\u0c28\u0c4b\u0c24\u0c3f \u0c36\u0c3f\u0c35\u0c47\u0c28 \u0c38\u0c39 \u0c2e\u0c4b\u0c26\u0c24\u0c47 \u0965 \u0c6f \u0965", "tamil": "\u0bb2\u0bbf\u0b99\u0bcd\u0b95\u0bbe\u0bb7\u0bcd\u0b9f\u0b95\u0bae\u0bbf\u0ba4\u0bae\u0bcd \u0baa\u0bc1\u0ba3\u0bcd\u0baf\u0bae\u0bcd \u0baf\u0b83 \u0baa\u0b9f\u0bc7\u0ba4\u0bcd \u0bb6\u0bbf\u0bb5\u0bb8\u0ba8\u0bcd\u0ba8\u0bbf\u0ba4\u0bcc \u0964\n\u0bb6\u0bbf\u0bb5\u0bb2\u0bcb\u0b95\u0bae\u0bb5\u0bbe\u0baa\u0bcd\u0ba8\u0bcb\u0ba4\u0bbf \u0bb6\u0bbf\u0bb5\u0bc7\u0ba8 \u0bb8\u0bb9 \u0bae\u0bcb\u0ba4\u0ba4\u0bc7 \u0965 \u0bef \u0965", "kannada": "\u0cb2\u0cbf\u0c99\u0ccd\u0c97\u0cbe\u0cb7\u0ccd\u0c9f\u0c95\u0cae\u0cbf\u0ca6\u0c82 \u0caa\u0cc1\u0ca3\u0ccd\u0caf\u0c82 \u0caf\u0c83 \u0caa\u0ca0\u0cc7\u0ca4\u0ccd \u0cb6\u0cbf\u0cb5\u0cb8\u0ca8\u0ccd\u0ca8\u0cbf\u0ca7\u0ccc \u0964\n\u0cb6\u0cbf\u0cb5\u0cb2\u0ccb\u0c95\u0cae\u0cb5\u0cbe\u0caa\u0ccd\u0ca8\u0ccb\u0ca4\u0cbf \u0cb6\u0cbf\u0cb5\u0cc7\u0ca8 \u0cb8\u0cb9 \u0cae\u0ccb\u0ca6\u0ca4\u0cc7 \u0965 \u0cef \u0965", "malayalam": "\u0d32\u0d3f\u0d19\u0d4d\u0d17\u0d3e\u0d37\u0d4d\u0d1f\u0d15\u0d2e\u0d3f\u0d26\u0d02 \u0d2a\u0d41\u0d23\u0d4d\u0d2f\u0d02 \u0d2f\u0d03 \u0d2a\u0d20\u0d47\u0d24\u0d4d \u0d36\u0d3f\u0d35\u0d38\u0d28\u0d4d\u0d28\u0d3f\u0d27\u0d4c \u0964\n\u0d36\u0d3f\u0d35\u0d32\u0d4b\u0d15\u0d2e\u0d35\u0d3e\u0d2a\u0d4d\u0d28\u0d4b\u0d24\u0d3f \u0d36\u0d3f\u0d35\u0d47\u0d28 \u0d38\u0d39 \u0d2e\u0d4b\u0d26\u0d24\u0d47 \u0965 \u0d6f \u0965", "iast": "li\u1e45g\u0101\u1e63\u1e6dakamida\u1e43 pu\u1e47ya\u1e43 ya\u1e25 pa\u1e6dhet \u015bivasannidhau |\n\u015bivalokamav\u0101pnoti \u015bivena saha modate || 9 ||"},
        draftTranslation: "Whoever recites this sacred Lingashtakam in the holy presence of Lord Shiva attains the supreme realm of Shiva (Shivaloka) and rejoices with Shiva in eternal beatitude.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
    ],
  ),
  Scripture(
    id: 13,
    contentId: "VEDA-TXT-00012",
    canonicalTitle: "Sankata Nashana Ganesha Stotram",
    devanagariTitle: "\u0938\u0919\u094d\u0915\u091f\u0928\u093e\u0936\u0928\u0917\u0923\u0947\u0936\u0938\u094d\u0924\u094b\u0924\u094d\u0930\u092e\u094d",
    category: "Stotra",
    deity: "Lord Ganesha",
    composer: "Devarshi Narada (Narada Purana)",
    rishi: "Traditional Vedic Sage",
    chandas: "Anushtubh",
    devata: "Lord Ganesha",
    sourceScripture: "Narada Purana, Uttara Khanda",
    traditionalUsage: "Vighna Nivarana, Sankata Harana, Daily Morning Chanting",
    verseCount: 8,
    verses: [
      Verse(
        verseNumber: 1,
        devanagariText: "\u092a\u094d\u0930\u0923\u092e\u094d\u092f \u0936\u093f\u0930\u0938\u093e \u0926\u0947\u0935\u0902 \u0917\u094c\u0930\u0940\u092a\u0941\u0924\u094d\u0930\u0902 \u0935\u093f\u0928\u093e\u092f\u0915\u092e\u094d \u0964\n\u092d\u0915\u094d\u0924\u093e\u0935\u093e\u0938\u0902 \u0938\u094d\u092e\u0930\u0947\u0928\u094d\u0928\u093f\u0924\u094d\u092f\u092e\u093e\u092f\u0941\u0903\u0915\u093e\u092e\u093e\u0930\u094d\u0925\u0938\u093f\u0926\u094d\u0927\u092f\u0947 \u0965 \u0967 \u0965",
        iastText: "pra\u1e47amya \u015biras\u0101 d\u0113va\u1e41 gaur\u012bputra\u1e41 vin\u0101yakam \u0964\nbhakt\u0101v\u0101sa\u1e41 smar\u0113nnityam\u0101yu\u1e25k\u0101m\u0101rthasiddhay\u0113 \u0965 1 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c4d\u0c2f \u0c36\u0c3f\u0c30\u0c38\u0c3e \u0c26\u0c47\u0c35\u0c02 \u0c17\u0c4c\u0c30\u0c40\u0c2a\u0c41\u0c24\u0c4d\u0c30\u0c02 \u0c35\u0c3f\u0c28\u0c3e\u0c2f\u0c15\u0c2e\u0c4d \u0964\n\u0c2d\u0c15\u0c4d\u0c24\u0c3e\u0c35\u0c3e\u0c38\u0c02 \u0c38\u0c4d\u0c2e\u0c30\u0c47\u0c28\u0c4d\u0c28\u0c3f\u0c24\u0c4d\u0c2f\u0c2e\u0c3e\u0c2f\u0c41\u0c03\u0c15\u0c3e\u0c2e\u0c3e\u0c30\u0c4d\u0c25\u0c38\u0c3f\u0c26\u0c4d\u0c27\u0c2f\u0c47 \u0965 \u0c67 \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bcd\u0baf \u0bb6\u0bbf\u0bb0\u0bb8\u0bbe \u0ba4\u0bc7\u0bb5\u0bae\u0bcd \u0b95\u0bcc\u0bb0\u0bc0\u0baa\u0bc1\u0ba4\u0bcd\u0bb0\u0bae\u0bcd \u0bb5\u0bbf\u0ba8\u0bbe\u0baf\u0b95\u0bae\u0bcd \u0964\n\u0baa\u0b95\u0bcd\u0ba4\u0bbe\u0bb5\u0bbe\u0bb8\u0bae\u0bcd \u0bb8\u0bcd\u0bae\u0bb0\u0bc7\u0ba8\u0bcd\u0ba8\u0bbf\u0ba4\u0bcd\u0baf\u0bae\u0bbe\u0baf\u0bc1\u0b83\u0b95\u0bbe\u0bae\u0bbe\u0bb0\u0bcd\u0ba4\u0bb8\u0bbf\u0ba4\u0bcd\u0ba4\u0baf\u0bc7 \u0965 \u0be7 \u0965", "kannada": "\u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0ccd\u0caf \u0cb6\u0cbf\u0cb0\u0cb8\u0cbe \u0ca6\u0cc7\u0cb5\u0c82 \u0c97\u0ccc\u0cb0\u0cc0\u0caa\u0cc1\u0ca4\u0ccd\u0cb0\u0c82 \u0cb5\u0cbf\u0ca8\u0cbe\u0caf\u0c95\u0cae\u0ccd \u0964\n\u0cad\u0c95\u0ccd\u0ca4\u0cbe\u0cb5\u0cbe\u0cb8\u0c82 \u0cb8\u0ccd\u0cae\u0cb0\u0cc7\u0ca8\u0ccd\u0ca8\u0cbf\u0ca4\u0ccd\u0caf\u0cae\u0cbe\u0caf\u0cc1\u0c83\u0c95\u0cbe\u0cae\u0cbe\u0cb0\u0ccd\u0ca5\u0cb8\u0cbf\u0ca6\u0ccd\u0ca7\u0caf\u0cc7 \u0965 \u0ce7 \u0965", "malayalam": "\u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d4d\u0d2f \u0d36\u0d3f\u0d30\u0d38\u0d3e \u0d26\u0d47\u0d35\u0d02 \u0d17\u0d4c\u0d30\u0d40\u0d2a\u0d41\u0d24\u0d4d\u0d30\u0d02 \u0d35\u0d3f\u0d28\u0d3e\u0d2f\u0d15\u0d2e\u0d4d \u0964\n\u0d2d\u0d15\u0d4d\u0d24\u0d3e\u0d35\u0d3e\u0d38\u0d02 \u0d38\u0d4d\u0d2e\u0d30\u0d47\u0d28\u0d4d\u0d28\u0d3f\u0d24\u0d4d\u0d2f\u0d2e\u0d3e\u0d2f\u0d41\u0d03\u0d15\u0d3e\u0d2e\u0d3e\u0d30\u0d4d\u0d25\u0d38\u0d3f\u0d26\u0d4d\u0d27\u0d2f\u0d47 \u0965 \u0d67 \u0965", "iast": "pra\u1e47amya \u015biras\u0101 deva\u1e43 gaur\u012bputra\u1e43 vin\u0101yakam |\nbhakt\u0101v\u0101sa\u1e43 smarennityam\u0101yu\u1e25k\u0101m\u0101rthasiddhaye || 1 ||"},
        draftTranslation: "Bowing down with one's head before the divine Lord Vinayaka, the beloved son of Gauri, residing ever in the hearts of devotees, one should constantly meditate on Him for longevity, fulfillment of desires, and prosperity.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 2,
        devanagariText: "\u092a\u094d\u0930\u0925\u092e\u0902 \u0935\u0915\u094d\u0930\u0924\u0941\u0923\u094d\u0921\u0902 \u091a \u090f\u0915\u0926\u0928\u094d\u0924\u0902 \u0926\u094d\u0935\u093f\u0924\u0940\u092f\u0915\u092e\u094d \u0964\n\u0924\u0943\u0924\u0940\u092f\u0902 \u0915\u0943\u0937\u094d\u0923\u092a\u093f\u0919\u094d\u0917\u093e\u0915\u094d\u0937\u0902 \u0917\u091c\u0935\u0915\u094d\u0924\u094d\u0930\u0902 \u091a\u0924\u0941\u0930\u094d\u0925\u0915\u092e\u094d \u0965 \u0968 \u0965",
        iastText: "prathama\u1e41 vakratu\u1e47\u1e0da\u1e41 ca \u0113kadanta\u1e41 dvit\u012byakam \u0964\ntr\u0325t\u012bya\u1e41 kr\u0325\u1e63\u1e47api\u1e45g\u0101k\u1e63a\u1e41 gajavaktra\u1e41 caturthakam \u0965 2 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2a\u0c4d\u0c30\u0c25\u0c2e\u0c02 \u0c35\u0c15\u0c4d\u0c30\u0c24\u0c41\u0c23\u0c4d\u0c21\u0c02 \u0c1a \u0c0f\u0c15\u0c26\u0c28\u0c4d\u0c24\u0c02 \u0c26\u0c4d\u0c35\u0c3f\u0c24\u0c40\u0c2f\u0c15\u0c2e\u0c4d \u0964\n\u0c24\u0c43\u0c24\u0c40\u0c2f\u0c02 \u0c15\u0c43\u0c37\u0c4d\u0c23\u0c2a\u0c3f\u0c19\u0c4d\u0c17\u0c3e\u0c15\u0c4d\u0c37\u0c02 \u0c17\u0c1c\u0c35\u0c15\u0c4d\u0c24\u0c4d\u0c30\u0c02 \u0c1a\u0c24\u0c41\u0c30\u0c4d\u0c25\u0c15\u0c2e\u0c4d \u0965 \u0c68 \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0ba4\u0bae\u0bae\u0bcd \u0bb5\u0b95\u0bcd\u0bb0\u0ba4\u0bc1\u0ba3\u0bcd\u0b9f\u0bae\u0bcd \u0b9a \u0b8f\u0b95\u0ba4\u0ba8\u0bcd\u0ba4\u0bae\u0bcd \u0ba4\u0bcd\u0bb5\u0bbf\u0ba4\u0bc0\u0baf\u0b95\u0bae\u0bcd \u0964\n\u0ba4\u0bcd\u0bb0\u0bc1'\u0ba4\u0bc0\u0baf\u0bae\u0bcd \u0b95\u0bcd\u0bb0\u0bc1'\u0bb7\u0bcd\u0ba3\u0baa\u0bbf\u0b99\u0bcd\u0b95\u0bbe\u0b95\u0bcd\u0bb7\u0bae\u0bcd \u0b95\u0b9c\u0bb5\u0b95\u0bcd\u0ba4\u0bcd\u0bb0\u0bae\u0bcd \u0b9a\u0ba4\u0bc1\u0bb0\u0bcd\u0ba4\u0b95\u0bae\u0bcd \u0965 \u0be8 \u0965", "kannada": "\u0caa\u0ccd\u0cb0\u0ca5\u0cae\u0c82 \u0cb5\u0c95\u0ccd\u0cb0\u0ca4\u0cc1\u0ca3\u0ccd\u0ca1\u0c82 \u0c9a \u0c8f\u0c95\u0ca6\u0ca8\u0ccd\u0ca4\u0c82 \u0ca6\u0ccd\u0cb5\u0cbf\u0ca4\u0cc0\u0caf\u0c95\u0cae\u0ccd \u0964\n\u0ca4\u0cc3\u0ca4\u0cc0\u0caf\u0c82 \u0c95\u0cc3\u0cb7\u0ccd\u0ca3\u0caa\u0cbf\u0c99\u0ccd\u0c97\u0cbe\u0c95\u0ccd\u0cb7\u0c82 \u0c97\u0c9c\u0cb5\u0c95\u0ccd\u0ca4\u0ccd\u0cb0\u0c82 \u0c9a\u0ca4\u0cc1\u0cb0\u0ccd\u0ca5\u0c95\u0cae\u0ccd \u0965 \u0ce8 \u0965", "malayalam": "\u0d2a\u0d4d\u0d30\u0d25\u0d2e\u0d02 \u0d35\u0d15\u0d4d\u0d30\u0d24\u0d41\u0d23\u0d4d\u0d21\u0d02 \u0d1a \u0d0f\u0d15\u0d26\u0d28\u0d4d\u0d24\u0d02 \u0d26\u0d4d\u0d35\u0d3f\u0d24\u0d40\u0d2f\u0d15\u0d2e\u0d4d \u0964\n\u0d24\u0d43\u0d24\u0d40\u0d2f\u0d02 \u0d15\u0d43\u0d37\u0d4d\u0d23\u0d2a\u0d3f\u0d19\u0d4d\u0d17\u0d3e\u0d15\u0d4d\u0d37\u0d02 \u0d17\u0d1c\u0d35\u0d15\u0d4d\u0d24\u0d4d\u0d30\u0d02 \u0d1a\u0d24\u0d41\u0d30\u0d4d\u0d25\u0d15\u0d2e\u0d4d \u0965 \u0d68 \u0965", "iast": "prathama\u1e43 vakratu\u1e47\u1e0da\u1e43 ca ekadanta\u1e43 dvit\u012byakam |\nt\u1e5bt\u012bya\u1e43 k\u1e5b\u1e63\u1e47api\u1e45g\u0101k\u1e63a\u1e43 gajavaktra\u1e43 caturthakam || 2 ||"},
        draftTranslation: "First, He with the curved trunk (Vakratunda); second, the single-tusked Lord (Ekadanta); third, He with dark reddish-brown eyes (Krishna-pingaksha); fourth, He with the noble elephant face (Gajavaktra).",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 3,
        devanagariText: "\u0932\u092e\u094d\u092c\u094b\u0926\u0930\u0902 \u092a\u091e\u094d\u091a\u092e\u0902 \u091a \u0937\u0937\u094d\u0920\u0902 \u0935\u093f\u0915\u091f\u092e\u0947\u0935 \u091a \u0964\n\u0938\u092a\u094d\u0924\u092e\u0902 \u0935\u093f\u0918\u094d\u0928\u0930\u093e\u091c\u0947\u0928\u094d\u0926\u094d\u0930\u0902 \u0927\u0942\u092e\u094d\u0930\u0935\u0930\u094d\u0923\u0902 \u0924\u0925\u093e\u0937\u094d\u091f\u092e\u092e\u094d \u0965 \u0969 \u0965",
        iastText: "lamb\u014ddara\u1e41 pa\u00f1cama\u1e41 ca \u1e63a\u1e63\u1e6dha\u1e41 vika\u1e6dam\u0113va ca \u0964\nsaptama\u1e41 vighnar\u0101j\u0113ndra\u1e41 dh\u016bmravar\u1e47a\u1e41 tath\u0101\u1e63\u1e6damam \u0965 3 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c32\u0c2e\u0c4d\u0c2c\u0c4b\u0c26\u0c30\u0c02 \u0c2a\u0c1e\u0c4d\u0c1a\u0c2e\u0c02 \u0c1a \u0c37\u0c37\u0c4d\u0c20\u0c02 \u0c35\u0c3f\u0c15\u0c1f\u0c2e\u0c47\u0c35 \u0c1a \u0964\n\u0c38\u0c2a\u0c4d\u0c24\u0c2e\u0c02 \u0c35\u0c3f\u0c18\u0c4d\u0c28\u0c30\u0c3e\u0c1c\u0c47\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c02 \u0c27\u0c42\u0c2e\u0c4d\u0c30\u0c35\u0c30\u0c4d\u0c23\u0c02 \u0c24\u0c25\u0c3e\u0c37\u0c4d\u0c1f\u0c2e\u0c2e\u0c4d \u0965 \u0c69 \u0965", "tamil": "\u0bb2\u0bae\u0bcd\u0baa\u0bcb\u0ba4\u0bb0\u0bae\u0bcd \u0baa\u0b9e\u0bcd\u0b9a\u0bae\u0bae\u0bcd \u0b9a \u0bb7\u0bb7\u0bcd\u0b9f\u0bae\u0bcd \u0bb5\u0bbf\u0b95\u0b9f\u0bae\u0bc7\u0bb5 \u0b9a \u0964\n\u0bb8\u0baa\u0bcd\u0ba4\u0bae\u0bae\u0bcd \u0bb5\u0bbf\u0b95\u0bcd\u0ba8\u0bb0\u0bbe\u0b9c\u0bc7\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bae\u0bcd \u0ba4\u0bc2\u0bae\u0bcd\u0bb0\u0bb5\u0bb0\u0bcd\u0ba3\u0bae\u0bcd \u0ba4\u0ba4\u0bbe\u0bb7\u0bcd\u0b9f\u0bae\u0bae\u0bcd \u0965 \u0be9 \u0965", "kannada": "\u0cb2\u0cae\u0ccd\u0cac\u0ccb\u0ca6\u0cb0\u0c82 \u0caa\u0c9e\u0ccd\u0c9a\u0cae\u0c82 \u0c9a \u0cb7\u0cb7\u0ccd\u0ca0\u0c82 \u0cb5\u0cbf\u0c95\u0c9f\u0cae\u0cc7\u0cb5 \u0c9a \u0964\n\u0cb8\u0caa\u0ccd\u0ca4\u0cae\u0c82 \u0cb5\u0cbf\u0c98\u0ccd\u0ca8\u0cb0\u0cbe\u0c9c\u0cc7\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0c82 \u0ca7\u0cc2\u0cae\u0ccd\u0cb0\u0cb5\u0cb0\u0ccd\u0ca3\u0c82 \u0ca4\u0ca5\u0cbe\u0cb7\u0ccd\u0c9f\u0cae\u0cae\u0ccd \u0965 \u0ce9 \u0965", "malayalam": "\u0d32\u0d2e\u0d4d\u0d2c\u0d4b\u0d26\u0d30\u0d02 \u0d2a\u0d1e\u0d4d\u0d1a\u0d2e\u0d02 \u0d1a \u0d37\u0d37\u0d4d\u0d20\u0d02 \u0d35\u0d3f\u0d15\u0d1f\u0d2e\u0d47\u0d35 \u0d1a \u0964\n\u0d38\u0d2a\u0d4d\u0d24\u0d2e\u0d02 \u0d35\u0d3f\u0d18\u0d4d\u0d28\u0d30\u0d3e\u0d1c\u0d47\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d02 \u0d27\u0d42\u0d2e\u0d4d\u0d30\u0d35\u0d30\u0d4d\u0d23\u0d02 \u0d24\u0d25\u0d3e\u0d37\u0d4d\u0d1f\u0d2e\u0d2e\u0d4d \u0965 \u0d69 \u0965", "iast": "lambodara\u1e43 pa\u00f1cama\u1e43 ca \u1e63a\u1e63\u1e6dha\u1e43 vika\u1e6dameva ca |\nsaptama\u1e43 vighnar\u0101jendra\u1e43 dh\u016bmravar\u1e47a\u1e43 tath\u0101\u1e63\u1e6damam || 3 ||"},
        draftTranslation: "Fifth, the large-bellied Lord (Lambodara); sixth, the formidable and colossal One (Vikata); seventh, the King who rules over all obstacles (Vighnarajendra); eighth, He of smoky hue (Dhumravarna).",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 4,
        devanagariText: "\u0928\u0935\u092e\u0902 \u092d\u093e\u0932\u091a\u0928\u094d\u0926\u094d\u0930\u0902 \u091a \u0926\u0936\u092e\u0902 \u0924\u0941 \u0935\u093f\u0928\u093e\u092f\u0915\u092e\u094d \u0964\n\u090f\u0915\u093e\u0926\u0936\u0902 \u0917\u0923\u092a\u0924\u093f\u0902 \u0926\u094d\u0935\u093e\u0926\u0936\u0902 \u0924\u0941 \u0917\u091c\u093e\u0928\u0928\u092e\u094d \u0965 \u096a \u0965",
        iastText: "navama\u1e41 bh\u0101lacandra\u1e41 ca da\u015bama\u1e41 tu vin\u0101yakam \u0964\n\u0113k\u0101da\u015ba\u1e41 ga\u1e47apati\u1e41 dv\u0101da\u015ba\u1e41 tu gaj\u0101nanam \u0965 4 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c28\u0c35\u0c2e\u0c02 \u0c2d\u0c3e\u0c32\u0c1a\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c02 \u0c1a \u0c26\u0c36\u0c2e\u0c02 \u0c24\u0c41 \u0c35\u0c3f\u0c28\u0c3e\u0c2f\u0c15\u0c2e\u0c4d \u0964\n\u0c0f\u0c15\u0c3e\u0c26\u0c36\u0c02 \u0c17\u0c23\u0c2a\u0c24\u0c3f\u0c02 \u0c26\u0c4d\u0c35\u0c3e\u0c26\u0c36\u0c02 \u0c24\u0c41 \u0c17\u0c1c\u0c3e\u0c28\u0c28\u0c2e\u0c4d \u0965 \u0c6a \u0965", "tamil": "\u0ba8\u0bb5\u0bae\u0bae\u0bcd \u0baa\u0bbe\u0bb2\u0b9a\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bae\u0bcd \u0b9a \u0ba4\u0bb6\u0bae\u0bae\u0bcd \u0ba4\u0bc1 \u0bb5\u0bbf\u0ba8\u0bbe\u0baf\u0b95\u0bae\u0bcd \u0964\n\u0b8f\u0b95\u0bbe\u0ba4\u0bb6\u0bae\u0bcd \u0b95\u0ba3\u0baa\u0ba4\u0bbf\u0bae\u0bcd \u0ba4\u0bcd\u0bb5\u0bbe\u0ba4\u0bb6\u0bae\u0bcd \u0ba4\u0bc1 \u0b95\u0b9c\u0bbe\u0ba8\u0ba8\u0bae\u0bcd \u0965 \u0bea \u0965", "kannada": "\u0ca8\u0cb5\u0cae\u0c82 \u0cad\u0cbe\u0cb2\u0c9a\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0c82 \u0c9a \u0ca6\u0cb6\u0cae\u0c82 \u0ca4\u0cc1 \u0cb5\u0cbf\u0ca8\u0cbe\u0caf\u0c95\u0cae\u0ccd \u0964\n\u0c8f\u0c95\u0cbe\u0ca6\u0cb6\u0c82 \u0c97\u0ca3\u0caa\u0ca4\u0cbf\u0c82 \u0ca6\u0ccd\u0cb5\u0cbe\u0ca6\u0cb6\u0c82 \u0ca4\u0cc1 \u0c97\u0c9c\u0cbe\u0ca8\u0ca8\u0cae\u0ccd \u0965 \u0cea \u0965", "malayalam": "\u0d28\u0d35\u0d2e\u0d02 \u0d2d\u0d3e\u0d32\u0d1a\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d02 \u0d1a \u0d26\u0d36\u0d2e\u0d02 \u0d24\u0d41 \u0d35\u0d3f\u0d28\u0d3e\u0d2f\u0d15\u0d2e\u0d4d \u0964\n\u0d0f\u0d15\u0d3e\u0d26\u0d36\u0d02 \u0d17\u0d23\u0d2a\u0d24\u0d3f\u0d02 \u0d26\u0d4d\u0d35\u0d3e\u0d26\u0d36\u0d02 \u0d24\u0d41 \u0d17\u0d1c\u0d3e\u0d28\u0d28\u0d2e\u0d4d \u0965 \u0d6a \u0965", "iast": "navama\u1e43 bh\u0101lacandra\u1e43 ca da\u015bama\u1e43 tu vin\u0101yakam |\nek\u0101da\u015ba\u1e43 ga\u1e47apati\u1e43 dv\u0101da\u015ba\u1e43 tu gaj\u0101nanam || 4 ||"},
        draftTranslation: "Ninth, He who bears the crescent moon on His forehead (Bhalachandra); tenth, the supreme remover of obstacles (Vinayaka); eleventh, the Lord of all Ganas (Ganapati); and twelfth, the elephant-faced Sovereign (Gajanana).",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 5,
        devanagariText: "\u0926\u094d\u0935\u093e\u0926\u0936\u0948\u0924\u093e\u0928\u093f \u0928\u093e\u092e\u093e\u0928\u093f \u0924\u094d\u0930\u093f\u0938\u0928\u094d\u0927\u094d\u092f\u0902 \u092f\u0903 \u092a\u0920\u0947\u0928\u094d\u0928\u0930\u0903 \u0964\n\u0928 \u091a \u0935\u093f\u0918\u094d\u0928\u092d\u092f\u0902 \u0924\u0938\u094d\u092f \u0938\u0930\u094d\u0935\u0938\u093f\u0926\u094d\u0927\u093f\u0915\u0930\u0902 \u092a\u094d\u0930\u092d\u094b \u0965 \u096b \u0965",
        iastText: "dv\u0101da\u015bait\u0101ni n\u0101m\u0101ni trisandhya\u1e41 ya\u1e25 pa\u1e6dh\u0113nnara\u1e25 \u0964\nna ca vighnabhaya\u1e41 tasya sarvasiddhikara\u1e41 prabh\u014d \u0965 5 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c26\u0c4d\u0c35\u0c3e\u0c26\u0c36\u0c48\u0c24\u0c3e\u0c28\u0c3f \u0c28\u0c3e\u0c2e\u0c3e\u0c28\u0c3f \u0c24\u0c4d\u0c30\u0c3f\u0c38\u0c28\u0c4d\u0c27\u0c4d\u0c2f\u0c02 \u0c2f\u0c03 \u0c2a\u0c20\u0c47\u0c28\u0c4d\u0c28\u0c30\u0c03 \u0964\n\u0c28 \u0c1a \u0c35\u0c3f\u0c18\u0c4d\u0c28\u0c2d\u0c2f\u0c02 \u0c24\u0c38\u0c4d\u0c2f \u0c38\u0c30\u0c4d\u0c35\u0c38\u0c3f\u0c26\u0c4d\u0c27\u0c3f\u0c15\u0c30\u0c02 \u0c2a\u0c4d\u0c30\u0c2d\u0c4b \u0965 \u0c6b \u0965", "tamil": "\u0ba4\u0bcd\u0bb5\u0bbe\u0ba4\u0bb6\u0bc8\u0ba4\u0bbe\u0ba8\u0bbf \u0ba8\u0bbe\u0bae\u0bbe\u0ba8\u0bbf \u0ba4\u0bcd\u0bb0\u0bbf\u0bb8\u0ba8\u0bcd\u0ba4\u0bcd\u0baf\u0bae\u0bcd \u0baf\u0b83 \u0baa\u0b9f\u0bc7\u0ba8\u0bcd\u0ba8\u0bb0\u0b83 \u0964\n\u0ba8 \u0b9a \u0bb5\u0bbf\u0b95\u0bcd\u0ba8\u0baa\u0baf\u0bae\u0bcd \u0ba4\u0bb8\u0bcd\u0baf \u0bb8\u0bb0\u0bcd\u0bb5\u0bb8\u0bbf\u0ba4\u0bcd\u0ba4\u0bbf\u0b95\u0bb0\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0bcb \u0965 \u0beb \u0965", "kannada": "\u0ca6\u0ccd\u0cb5\u0cbe\u0ca6\u0cb6\u0cc8\u0ca4\u0cbe\u0ca8\u0cbf \u0ca8\u0cbe\u0cae\u0cbe\u0ca8\u0cbf \u0ca4\u0ccd\u0cb0\u0cbf\u0cb8\u0ca8\u0ccd\u0ca7\u0ccd\u0caf\u0c82 \u0caf\u0c83 \u0caa\u0ca0\u0cc7\u0ca8\u0ccd\u0ca8\u0cb0\u0c83 \u0964\n\u0ca8 \u0c9a \u0cb5\u0cbf\u0c98\u0ccd\u0ca8\u0cad\u0caf\u0c82 \u0ca4\u0cb8\u0ccd\u0caf \u0cb8\u0cb0\u0ccd\u0cb5\u0cb8\u0cbf\u0ca6\u0ccd\u0ca7\u0cbf\u0c95\u0cb0\u0c82 \u0caa\u0ccd\u0cb0\u0cad\u0ccb \u0965 \u0ceb \u0965", "malayalam": "\u0d26\u0d4d\u0d35\u0d3e\u0d26\u0d36\u0d48\u0d24\u0d3e\u0d28\u0d3f \u0d28\u0d3e\u0d2e\u0d3e\u0d28\u0d3f \u0d24\u0d4d\u0d30\u0d3f\u0d38\u0d28\u0d4d\u0d27\u0d4d\u0d2f\u0d02 \u0d2f\u0d03 \u0d2a\u0d20\u0d47\u0d28\u0d4d\u0d28\u0d30\u0d03 \u0964\n\u0d28 \u0d1a \u0d35\u0d3f\u0d18\u0d4d\u0d28\u0d2d\u0d2f\u0d02 \u0d24\u0d38\u0d4d\u0d2f \u0d38\u0d30\u0d4d\u0d35\u0d38\u0d3f\u0d26\u0d4d\u0d27\u0d3f\u0d15\u0d30\u0d02 \u0d2a\u0d4d\u0d30\u0d2d\u0d4b \u0965 \u0d6b \u0965", "iast": "dv\u0101da\u015bait\u0101ni n\u0101m\u0101ni trisandhya\u1e43 ya\u1e25 pa\u1e6dhennara\u1e25 |\nna ca vighnabhaya\u1e43 tasya sarvasiddhikara\u1e43 prabho || 5 ||"},
        draftTranslation: "A person who recites these twelve sacred names at the three junctions of the day (dawn, noon, dusk) has no fear of any impediment; this hymn bestows all accomplishments, O Lord!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 6,
        devanagariText: "\u0935\u093f\u0926\u094d\u092f\u093e\u0930\u094d\u0925\u0940 \u0932\u092d\u0924\u0947 \u0935\u093f\u0926\u094d\u092f\u093e\u0902 \u0927\u0928\u093e\u0930\u094d\u0925\u0940 \u0932\u092d\u0924\u0947 \u0927\u0928\u092e\u094d \u0964\n\u092a\u0941\u0924\u094d\u0930\u093e\u0930\u094d\u0925\u0940 \u0932\u092d\u0924\u0947 \u092a\u0941\u0924\u094d\u0930\u093e\u0928\u094d \u092e\u094b\u0915\u094d\u0937\u093e\u0930\u094d\u0925\u0940 \u0932\u092d\u0924\u0947 \u0917\u0924\u093f\u092e\u094d \u0965 \u096c \u0965",
        iastText: "vidy\u0101rth\u012b labhat\u0113 vidy\u0101\u1e41 dhan\u0101rth\u012b labhat\u0113 dhanam \u0964\nputr\u0101rth\u012b labhat\u0113 putr\u0101n m\u014dk\u1e63\u0101rth\u012b labhat\u0113 gatim \u0965 6 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c35\u0c3f\u0c26\u0c4d\u0c2f\u0c3e\u0c30\u0c4d\u0c25\u0c40 \u0c32\u0c2d\u0c24\u0c47 \u0c35\u0c3f\u0c26\u0c4d\u0c2f\u0c3e\u0c02 \u0c27\u0c28\u0c3e\u0c30\u0c4d\u0c25\u0c40 \u0c32\u0c2d\u0c24\u0c47 \u0c27\u0c28\u0c2e\u0c4d \u0964\n\u0c2a\u0c41\u0c24\u0c4d\u0c30\u0c3e\u0c30\u0c4d\u0c25\u0c40 \u0c32\u0c2d\u0c24\u0c47 \u0c2a\u0c41\u0c24\u0c4d\u0c30\u0c3e\u0c28\u0c4d \u0c2e\u0c4b\u0c15\u0c4d\u0c37\u0c3e\u0c30\u0c4d\u0c25\u0c40 \u0c32\u0c2d\u0c24\u0c47 \u0c17\u0c24\u0c3f\u0c2e\u0c4d \u0965 \u0c6c \u0965", "tamil": "\u0bb5\u0bbf\u0ba4\u0bcd\u0baf\u0bbe\u0bb0\u0bcd\u0ba4\u0bc0 \u0bb2\u0baa\u0ba4\u0bc7 \u0bb5\u0bbf\u0ba4\u0bcd\u0baf\u0bbe\u0bae\u0bcd \u0ba4\u0ba8\u0bbe\u0bb0\u0bcd\u0ba4\u0bc0 \u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0ba8\u0bae\u0bcd \u0964\n\u0baa\u0bc1\u0ba4\u0bcd\u0bb0\u0bbe\u0bb0\u0bcd\u0ba4\u0bc0 \u0bb2\u0baa\u0ba4\u0bc7 \u0baa\u0bc1\u0ba4\u0bcd\u0bb0\u0bbe\u0ba8\u0bcd \u0bae\u0bcb\u0b95\u0bcd\u0bb7\u0bbe\u0bb0\u0bcd\u0ba4\u0bc0 \u0bb2\u0baa\u0ba4\u0bc7 \u0b95\u0ba4\u0bbf\u0bae\u0bcd \u0965 \u0bec \u0965", "kannada": "\u0cb5\u0cbf\u0ca6\u0ccd\u0caf\u0cbe\u0cb0\u0ccd\u0ca5\u0cc0 \u0cb2\u0cad\u0ca4\u0cc7 \u0cb5\u0cbf\u0ca6\u0ccd\u0caf\u0cbe\u0c82 \u0ca7\u0ca8\u0cbe\u0cb0\u0ccd\u0ca5\u0cc0 \u0cb2\u0cad\u0ca4\u0cc7 \u0ca7\u0ca8\u0cae\u0ccd \u0964\n\u0caa\u0cc1\u0ca4\u0ccd\u0cb0\u0cbe\u0cb0\u0ccd\u0ca5\u0cc0 \u0cb2\u0cad\u0ca4\u0cc7 \u0caa\u0cc1\u0ca4\u0ccd\u0cb0\u0cbe\u0ca8\u0ccd \u0cae\u0ccb\u0c95\u0ccd\u0cb7\u0cbe\u0cb0\u0ccd\u0ca5\u0cc0 \u0cb2\u0cad\u0ca4\u0cc7 \u0c97\u0ca4\u0cbf\u0cae\u0ccd \u0965 \u0cec \u0965", "malayalam": "\u0d35\u0d3f\u0d26\u0d4d\u0d2f\u0d3e\u0d30\u0d4d\u0d25\u0d40 \u0d32\u0d2d\u0d24\u0d47 \u0d35\u0d3f\u0d26\u0d4d\u0d2f\u0d3e\u0d02 \u0d27\u0d28\u0d3e\u0d30\u0d4d\u0d25\u0d40 \u0d32\u0d2d\u0d24\u0d47 \u0d27\u0d28\u0d2e\u0d4d \u0964\n\u0d2a\u0d41\u0d24\u0d4d\u0d30\u0d3e\u0d30\u0d4d\u0d25\u0d40 \u0d32\u0d2d\u0d24\u0d47 \u0d2a\u0d41\u0d24\u0d4d\u0d30\u0d3e\u0d28\u0d4d \u0d2e\u0d4b\u0d15\u0d4d\u0d37\u0d3e\u0d30\u0d4d\u0d25\u0d40 \u0d32\u0d2d\u0d24\u0d47 \u0d17\u0d24\u0d3f\u0d2e\u0d4d \u0965 \u0d6c \u0965", "iast": "vidy\u0101rth\u012b labhate vidy\u0101\u1e43 dhan\u0101rth\u012b labhate dhanam |\nputr\u0101rth\u012b labhate putr\u0101n mok\u1e63\u0101rth\u012b labhate gatim || 6 ||"},
        draftTranslation: "The seeker of knowledge attains wisdom; the seeker of wealth secures abundance; the seeker of offspring is blessed with noble children; and the seeker of liberation attains the supreme spiritual goal.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 7,
        devanagariText: "\u091c\u092a\u0947\u0926\u094d\u0917\u0923\u092a\u0924\u093f\u0938\u094d\u0924\u094b\u0924\u094d\u0930\u0902 \u0937\u0921\u094d\u092d\u093f\u0930\u094d\u092e\u093e\u0938\u0948\u0903 \u092b\u0932\u0902 \u0932\u092d\u0947\u0924\u094d \u0964\n\u0938\u0902\u0935\u0924\u094d\u0938\u0930\u0947\u0923 \u0938\u093f\u0926\u094d\u0927\u093f\u0902 \u091a \u0932\u092d\u0924\u0947 \u0928\u093e\u0924\u094d\u0930 \u0938\u0902\u0936\u092f\u0903 \u0965 \u096d \u0965",
        iastText: "jap\u0113dga\u1e47apatist\u014dtra\u1e41 \u1e63a\u1e0dbhirm\u0101sai\u1e25 phala\u1e41 labh\u0113t \u0964\nsa\u1e41vatsar\u0113\u1e47a siddhi\u1e41 ca labhat\u0113 n\u0101tra sa\u1e41\u015baya\u1e25 \u0965 7 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c1c\u0c2a\u0c47\u0c26\u0c4d\u0c17\u0c23\u0c2a\u0c24\u0c3f\u0c38\u0c4d\u0c24\u0c4b\u0c24\u0c4d\u0c30\u0c02 \u0c37\u0c21\u0c4d\u0c2d\u0c3f\u0c30\u0c4d\u0c2e\u0c3e\u0c38\u0c48\u0c03 \u0c2b\u0c32\u0c02 \u0c32\u0c2d\u0c47\u0c24\u0c4d \u0964\n\u0c38\u0c02\u0c35\u0c24\u0c4d\u0c38\u0c30\u0c47\u0c23 \u0c38\u0c3f\u0c26\u0c4d\u0c27\u0c3f\u0c02 \u0c1a \u0c32\u0c2d\u0c24\u0c47 \u0c28\u0c3e\u0c24\u0c4d\u0c30 \u0c38\u0c02\u0c36\u0c2f\u0c03 \u0965 \u0c6d \u0965", "tamil": "\u0b9c\u0baa\u0bc7\u0ba4\u0bcd\u0b95\u0ba3\u0baa\u0ba4\u0bbf\u0bb8\u0bcd\u0ba4\u0bcb\u0ba4\u0bcd\u0bb0\u0bae\u0bcd \u0bb7\u0b9f\u0bcd\u0baa\u0bbf\u0bb0\u0bcd\u0bae\u0bbe\u0bb8\u0bc8\u0b83 \u0baa\u0bb2\u0bae\u0bcd \u0bb2\u0baa\u0bc7\u0ba4\u0bcd \u0964\n\u0bb8\u0bae\u0bcd\u0bb5\u0ba4\u0bcd\u0bb8\u0bb0\u0bc7\u0ba3 \u0bb8\u0bbf\u0ba4\u0bcd\u0ba4\u0bbf\u0bae\u0bcd \u0b9a \u0bb2\u0baa\u0ba4\u0bc7 \u0ba8\u0bbe\u0ba4\u0bcd\u0bb0 \u0bb8\u0bae\u0bcd\u0bb6\u0baf\u0b83 \u0965 \u0bed \u0965", "kannada": "\u0c9c\u0caa\u0cc7\u0ca6\u0ccd\u0c97\u0ca3\u0caa\u0ca4\u0cbf\u0cb8\u0ccd\u0ca4\u0ccb\u0ca4\u0ccd\u0cb0\u0c82 \u0cb7\u0ca1\u0ccd\u0cad\u0cbf\u0cb0\u0ccd\u0cae\u0cbe\u0cb8\u0cc8\u0c83 \u0cab\u0cb2\u0c82 \u0cb2\u0cad\u0cc7\u0ca4\u0ccd \u0964\n\u0cb8\u0c82\u0cb5\u0ca4\u0ccd\u0cb8\u0cb0\u0cc7\u0ca3 \u0cb8\u0cbf\u0ca6\u0ccd\u0ca7\u0cbf\u0c82 \u0c9a \u0cb2\u0cad\u0ca4\u0cc7 \u0ca8\u0cbe\u0ca4\u0ccd\u0cb0 \u0cb8\u0c82\u0cb6\u0caf\u0c83 \u0965 \u0ced \u0965", "malayalam": "\u0d1c\u0d2a\u0d47\u0d26\u0d4d\u0d17\u0d23\u0d2a\u0d24\u0d3f\u0d38\u0d4d\u0d24\u0d4b\u0d24\u0d4d\u0d30\u0d02 \u0d37\u0d21\u0d4d\u0d2d\u0d3f\u0d30\u0d4d\u0d2e\u0d3e\u0d38\u0d48\u0d03 \u0d2b\u0d32\u0d02 \u0d32\u0d2d\u0d47\u0d24\u0d4d \u0964\n\u0d38\u0d02\u0d35\u0d24\u0d4d\u0d38\u0d30\u0d47\u0d23 \u0d38\u0d3f\u0d26\u0d4d\u0d27\u0d3f\u0d02 \u0d1a \u0d32\u0d2d\u0d24\u0d47 \u0d28\u0d3e\u0d24\u0d4d\u0d30 \u0d38\u0d02\u0d36\u0d2f\u0d03 \u0965 \u0d6d \u0965", "iast": "japedga\u1e47apatistotra\u1e43 \u1e63a\u1e0dbhirm\u0101sai\u1e25 phala\u1e43 labhet |\nsa\u1e43vatsare\u1e47a siddhi\u1e43 ca labhate n\u0101tra sa\u1e43\u015baya\u1e25 || 7 ||"},
        draftTranslation: "By chanting this Ganapati Stotram, one reaps the fruit within six months, and within one year one attains total spiritual and material success\u2014of this there is no doubt.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 8,
        devanagariText: "\u0905\u0937\u094d\u091f\u092d\u094d\u092f\u094b \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u0947\u092d\u094d\u092f\u0936\u094d\u091a \u0932\u093f\u0916\u093f\u0924\u094d\u0935\u093e \u092f\u0903 \u0938\u092e\u0930\u094d\u092a\u092f\u0947\u0924\u094d \u0964\n\u0924\u0938\u094d\u092f \u0935\u093f\u0926\u094d\u092f\u093e \u092d\u0935\u0947\u0924\u094d\u0938\u0930\u094d\u0935\u093e \u0917\u0923\u0947\u0936\u0938\u094d\u092f \u092a\u094d\u0930\u0938\u093e\u0926\u0924\u0903 \u0965 \u096e \u0965",
        iastText: "a\u1e63\u1e6dabhy\u014d br\u0101hma\u1e47\u0113bhya\u015bca likhitv\u0101 ya\u1e25 samarpay\u0113t \u0964\ntasya vidy\u0101 bhav\u0113tsarv\u0101 ga\u1e47\u0113\u015basya pras\u0101data\u1e25 \u0965 8 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c05\u0c37\u0c4d\u0c1f\u0c2d\u0c4d\u0c2f\u0c4b \u0c2c\u0c4d\u0c30\u0c3e\u0c39\u0c4d\u0c2e\u0c23\u0c47\u0c2d\u0c4d\u0c2f\u0c36\u0c4d\u0c1a \u0c32\u0c3f\u0c16\u0c3f\u0c24\u0c4d\u0c35\u0c3e \u0c2f\u0c03 \u0c38\u0c2e\u0c30\u0c4d\u0c2a\u0c2f\u0c47\u0c24\u0c4d \u0964\n\u0c24\u0c38\u0c4d\u0c2f \u0c35\u0c3f\u0c26\u0c4d\u0c2f\u0c3e \u0c2d\u0c35\u0c47\u0c24\u0c4d\u0c38\u0c30\u0c4d\u0c35\u0c3e \u0c17\u0c23\u0c47\u0c36\u0c38\u0c4d\u0c2f \u0c2a\u0c4d\u0c30\u0c38\u0c3e\u0c26\u0c24\u0c03 \u0965 \u0c6e \u0965", "tamil": "\u0b85\u0bb7\u0bcd\u0b9f\u0baa\u0bcd\u0baf\u0bcb \u0baa\u0bcd\u0bb0\u0bbe\u0bb9\u0bcd\u0bae\u0ba3\u0bc7\u0baa\u0bcd\u0baf\u0bb6\u0bcd\u0b9a \u0bb2\u0bbf\u0b95\u0bbf\u0ba4\u0bcd\u0bb5\u0bbe \u0baf\u0b83 \u0bb8\u0bae\u0bb0\u0bcd\u0baa\u0baf\u0bc7\u0ba4\u0bcd \u0964\n\u0ba4\u0bb8\u0bcd\u0baf \u0bb5\u0bbf\u0ba4\u0bcd\u0baf\u0bbe \u0baa\u0bb5\u0bc7\u0ba4\u0bcd\u0bb8\u0bb0\u0bcd\u0bb5\u0bbe \u0b95\u0ba3\u0bc7\u0bb6\u0bb8\u0bcd\u0baf \u0baa\u0bcd\u0bb0\u0bb8\u0bbe\u0ba4\u0ba4\u0b83 \u0965 \u0bee \u0965", "kannada": "\u0c85\u0cb7\u0ccd\u0c9f\u0cad\u0ccd\u0caf\u0ccb \u0cac\u0ccd\u0cb0\u0cbe\u0cb9\u0ccd\u0cae\u0ca3\u0cc7\u0cad\u0ccd\u0caf\u0cb6\u0ccd\u0c9a \u0cb2\u0cbf\u0c96\u0cbf\u0ca4\u0ccd\u0cb5\u0cbe \u0caf\u0c83 \u0cb8\u0cae\u0cb0\u0ccd\u0caa\u0caf\u0cc7\u0ca4\u0ccd \u0964\n\u0ca4\u0cb8\u0ccd\u0caf \u0cb5\u0cbf\u0ca6\u0ccd\u0caf\u0cbe \u0cad\u0cb5\u0cc7\u0ca4\u0ccd\u0cb8\u0cb0\u0ccd\u0cb5\u0cbe \u0c97\u0ca3\u0cc7\u0cb6\u0cb8\u0ccd\u0caf \u0caa\u0ccd\u0cb0\u0cb8\u0cbe\u0ca6\u0ca4\u0c83 \u0965 \u0cee \u0965", "malayalam": "\u0d05\u0d37\u0d4d\u0d1f\u0d2d\u0d4d\u0d2f\u0d4b \u0d2c\u0d4d\u0d30\u0d3e\u0d39\u0d4d\u0d2e\u0d23\u0d47\u0d2d\u0d4d\u0d2f\u0d36\u0d4d\u0d1a \u0d32\u0d3f\u0d16\u0d3f\u0d24\u0d4d\u0d35\u0d3e \u0d2f\u0d03 \u0d38\u0d2e\u0d30\u0d4d\u0d2a\u0d2f\u0d47\u0d24\u0d4d \u0964\n\u0d24\u0d38\u0d4d\u0d2f \u0d35\u0d3f\u0d26\u0d4d\u0d2f\u0d3e \u0d2d\u0d35\u0d47\u0d24\u0d4d\u0d38\u0d30\u0d4d\u0d35\u0d3e \u0d17\u0d23\u0d47\u0d36\u0d38\u0d4d\u0d2f \u0d2a\u0d4d\u0d30\u0d38\u0d3e\u0d26\u0d24\u0d03 \u0965 \u0d6e \u0965", "iast": "a\u1e63\u1e6dabhyo br\u0101hma\u1e47ebhya\u015bca likhitv\u0101 ya\u1e25 samarpayet |\ntasya vidy\u0101 bhavetsarv\u0101 ga\u1e47e\u015basya pras\u0101data\u1e25 || 8 ||"},
        draftTranslation: "Whoever transcribes this sacred hymn and offers it to eight learned devotees attains all knowledge through the divine grace of Lord Ganesha.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
    ],
  ),
  Scripture(
    id: 15,
    contentId: "VEDA-TXT-00013",
    canonicalTitle: "Venkateswara Suprabhatam",
    devanagariTitle: "\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u094d\u0935\u0930\u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d",
    category: "Suprabhatam",
    deity: "Lord Venkateswara",
    composer: "Prativadi Bhayankaram Anna (c. 1400 CE)",
    rishi: "Traditional Vedic Sage",
    chandas: "Vasantatilaka / Malini",
    devata: "Lord Venkateswara",
    sourceScripture: "Tirumala Morning Liturgical Canon",
    traditionalUsage: "Morning awakening liturgy, Tirumala temple dawn service",
    verseCount: 70,
    verses: [
      Verse(
        verseNumber: 1,
        devanagariText: "\u0915\u094c\u0938\u0932\u094d\u092f\u093e \u0938\u0941\u092a\u094d\u0930\u091c\u093e \u0930\u093e\u092e \u092a\u0942\u0930\u094d\u0935\u093e \u0938\u0928\u094d\u0927\u094d\u092f\u093e \u092a\u094d\u0930\u0935\u0930\u094d\u0924\u0924\u0947 \u0964\n\u0909\u0924\u094d\u0924\u093f\u0937\u094d\u0920 \u0928\u0930\u0936\u093e\u0930\u094d\u0926\u0942\u0932 \u0915\u0930\u094d\u0924\u094d\u0924\u0935\u094d\u092f\u0902 \u0926\u0948\u0935\u092e\u093e\u0939\u094d\u0928\u093f\u0915\u092e\u094d \u0965 \u0967 \u0965",
        iastText: "kausaly\u0101 supraj\u0101 r\u0101ma p\u016brv\u0101 sandhy\u0101 pravartat\u0113 \u0964\nutti\u1e63\u1e6dha nara\u015b\u0101rd\u016bla karttavya\u1e41 daivam\u0101hnikam \u0965 1 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c15\u0c4c\u0c38\u0c32\u0c4d\u0c2f\u0c3e \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c1c\u0c3e \u0c30\u0c3e\u0c2e \u0c2a\u0c42\u0c30\u0c4d\u0c35\u0c3e \u0c38\u0c28\u0c4d\u0c27\u0c4d\u0c2f\u0c3e \u0c2a\u0c4d\u0c30\u0c35\u0c30\u0c4d\u0c24\u0c24\u0c47 \u0964\n\u0c09\u0c24\u0c4d\u0c24\u0c3f\u0c37\u0c4d\u0c20 \u0c28\u0c30\u0c36\u0c3e\u0c30\u0c4d\u0c26\u0c42\u0c32 \u0c15\u0c30\u0c4d\u0c24\u0c4d\u0c24\u0c35\u0c4d\u0c2f\u0c02 \u0c26\u0c48\u0c35\u0c2e\u0c3e\u0c39\u0c4d\u0c28\u0c3f\u0c15\u0c2e\u0c4d \u0965 \u0c67 \u0965", "tamil": "\u0b95\u0bcc\u0bb8\u0bb2\u0bcd\u0baf\u0bbe \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0b9c\u0bbe \u0bb0\u0bbe\u0bae \u0baa\u0bc2\u0bb0\u0bcd\u0bb5\u0bbe \u0bb8\u0ba8\u0bcd\u0ba4\u0bcd\u0baf\u0bbe \u0baa\u0bcd\u0bb0\u0bb5\u0bb0\u0bcd\u0ba4\u0ba4\u0bc7 \u0964\n\u0b89\u0ba4\u0bcd\u0ba4\u0bbf\u0bb7\u0bcd\u0b9f \u0ba8\u0bb0\u0bb6\u0bbe\u0bb0\u0bcd\u0ba4\u0bc2\u0bb2 \u0b95\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bcd\u0baf\u0bae\u0bcd \u0ba4\u0bc8\u0bb5\u0bae\u0bbe\u0bb9\u0bcd\u0ba8\u0bbf\u0b95\u0bae\u0bcd \u0965 \u0be7 \u0965", "kannada": "\u0c95\u0ccc\u0cb8\u0cb2\u0ccd\u0caf\u0cbe \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0c9c\u0cbe \u0cb0\u0cbe\u0cae \u0caa\u0cc2\u0cb0\u0ccd\u0cb5\u0cbe \u0cb8\u0ca8\u0ccd\u0ca7\u0ccd\u0caf\u0cbe \u0caa\u0ccd\u0cb0\u0cb5\u0cb0\u0ccd\u0ca4\u0ca4\u0cc7 \u0964\n\u0c89\u0ca4\u0ccd\u0ca4\u0cbf\u0cb7\u0ccd\u0ca0 \u0ca8\u0cb0\u0cb6\u0cbe\u0cb0\u0ccd\u0ca6\u0cc2\u0cb2 \u0c95\u0cb0\u0ccd\u0ca4\u0ccd\u0ca4\u0cb5\u0ccd\u0caf\u0c82 \u0ca6\u0cc8\u0cb5\u0cae\u0cbe\u0cb9\u0ccd\u0ca8\u0cbf\u0c95\u0cae\u0ccd \u0965 \u0ce7 \u0965", "malayalam": "\u0d15\u0d4c\u0d38\u0d32\u0d4d\u0d2f\u0d3e \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d1c\u0d3e \u0d30\u0d3e\u0d2e \u0d2a\u0d42\u0d30\u0d4d\u0d35\u0d3e \u0d38\u0d28\u0d4d\u0d27\u0d4d\u0d2f\u0d3e \u0d2a\u0d4d\u0d30\u0d35\u0d30\u0d4d\u0d24\u0d24\u0d47 \u0964\n\u0d09\u0d24\u0d4d\u0d24\u0d3f\u0d37\u0d4d\u0d20 \u0d28\u0d30\u0d36\u0d3e\u0d30\u0d4d\u0d26\u0d42\u0d32 \u0d15\u0d30\u0d4d\u0d24\u0d4d\u0d24\u0d35\u0d4d\u0d2f\u0d02 \u0d26\u0d48\u0d35\u0d2e\u0d3e\u0d39\u0d4d\u0d28\u0d3f\u0d15\u0d2e\u0d4d \u0965 \u0d67 \u0965", "iast": "kausaly\u0101 supraj\u0101 r\u0101ma p\u016brv\u0101 sandhy\u0101 pravartate |\nutti\u1e63\u1e6dha nara\u015b\u0101rd\u016bla karttavya\u1e43 daivam\u0101hnikam || 1 ||"},
        draftTranslation: "O Rama, noble son of Kausalya! The morning twilight has dawned. Arise, O lion among men! The sacred morning rituals are to be performed.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 2,
        devanagariText: "\u0909\u0924\u094d\u0924\u093f\u0937\u094d\u0920\u094b\u0924\u094d\u0924\u093f\u0937\u094d\u0920 \u0917\u094b\u0935\u093f\u0928\u094d\u0926 \u0909\u0924\u094d\u0924\u093f\u0937\u094d\u0920 \u0917\u0930\u0941\u0921\u0927\u094d\u0935\u091c \u0964\n\u0909\u0924\u094d\u0924\u093f\u0937\u094d\u0920 \u0915\u092e\u0932\u093e\u0915\u093e\u0928\u094d\u0924 \u0924\u094d\u0930\u0948\u0932\u094b\u0915\u094d\u092f\u0902 \u092e\u0919\u094d\u0917\u0932\u0902 \u0915\u0941\u0930\u0941 \u0965 \u0968 \u0965",
        iastText: "utti\u1e63\u1e6dh\u014dtti\u1e63\u1e6dha g\u014dvinda utti\u1e63\u1e6dha garu\u1e0dadhvaja \u0964\nutti\u1e63\u1e6dha kamal\u0101k\u0101nta trail\u014dkya\u1e41 ma\u1e45gala\u1e41 kuru \u0965 2 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c09\u0c24\u0c4d\u0c24\u0c3f\u0c37\u0c4d\u0c20\u0c4b\u0c24\u0c4d\u0c24\u0c3f\u0c37\u0c4d\u0c20 \u0c17\u0c4b\u0c35\u0c3f\u0c28\u0c4d\u0c26 \u0c09\u0c24\u0c4d\u0c24\u0c3f\u0c37\u0c4d\u0c20 \u0c17\u0c30\u0c41\u0c21\u0c27\u0c4d\u0c35\u0c1c \u0964\n\u0c09\u0c24\u0c4d\u0c24\u0c3f\u0c37\u0c4d\u0c20 \u0c15\u0c2e\u0c32\u0c3e\u0c15\u0c3e\u0c28\u0c4d\u0c24 \u0c24\u0c4d\u0c30\u0c48\u0c32\u0c4b\u0c15\u0c4d\u0c2f\u0c02 \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c02 \u0c15\u0c41\u0c30\u0c41 \u0965 \u0c68 \u0965", "tamil": "\u0b89\u0ba4\u0bcd\u0ba4\u0bbf\u0bb7\u0bcd\u0b9f\u0bcb\u0ba4\u0bcd\u0ba4\u0bbf\u0bb7\u0bcd\u0b9f \u0b95\u0bcb\u0bb5\u0bbf\u0ba8\u0bcd\u0ba4 \u0b89\u0ba4\u0bcd\u0ba4\u0bbf\u0bb7\u0bcd\u0b9f \u0b95\u0bb0\u0bc1\u0b9f\u0ba4\u0bcd\u0bb5\u0b9c \u0964\n\u0b89\u0ba4\u0bcd\u0ba4\u0bbf\u0bb7\u0bcd\u0b9f \u0b95\u0bae\u0bb2\u0bbe\u0b95\u0bbe\u0ba8\u0bcd\u0ba4 \u0ba4\u0bcd\u0bb0\u0bc8\u0bb2\u0bcb\u0b95\u0bcd\u0baf\u0bae\u0bcd \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0b95\u0bc1\u0bb0\u0bc1 \u0965 \u0be8 \u0965", "kannada": "\u0c89\u0ca4\u0ccd\u0ca4\u0cbf\u0cb7\u0ccd\u0ca0\u0ccb\u0ca4\u0ccd\u0ca4\u0cbf\u0cb7\u0ccd\u0ca0 \u0c97\u0ccb\u0cb5\u0cbf\u0ca8\u0ccd\u0ca6 \u0c89\u0ca4\u0ccd\u0ca4\u0cbf\u0cb7\u0ccd\u0ca0 \u0c97\u0cb0\u0cc1\u0ca1\u0ca7\u0ccd\u0cb5\u0c9c \u0964\n\u0c89\u0ca4\u0ccd\u0ca4\u0cbf\u0cb7\u0ccd\u0ca0 \u0c95\u0cae\u0cb2\u0cbe\u0c95\u0cbe\u0ca8\u0ccd\u0ca4 \u0ca4\u0ccd\u0cb0\u0cc8\u0cb2\u0ccb\u0c95\u0ccd\u0caf\u0c82 \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0c82 \u0c95\u0cc1\u0cb0\u0cc1 \u0965 \u0ce8 \u0965", "malayalam": "\u0d09\u0d24\u0d4d\u0d24\u0d3f\u0d37\u0d4d\u0d20\u0d4b\u0d24\u0d4d\u0d24\u0d3f\u0d37\u0d4d\u0d20 \u0d17\u0d4b\u0d35\u0d3f\u0d28\u0d4d\u0d26 \u0d09\u0d24\u0d4d\u0d24\u0d3f\u0d37\u0d4d\u0d20 \u0d17\u0d30\u0d41\u0d21\u0d27\u0d4d\u0d35\u0d1c \u0964\n\u0d09\u0d24\u0d4d\u0d24\u0d3f\u0d37\u0d4d\u0d20 \u0d15\u0d2e\u0d32\u0d3e\u0d15\u0d3e\u0d28\u0d4d\u0d24 \u0d24\u0d4d\u0d30\u0d48\u0d32\u0d4b\u0d15\u0d4d\u0d2f\u0d02 \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d02 \u0d15\u0d41\u0d30\u0d41 \u0965 \u0d68 \u0965", "iast": "utti\u1e63\u1e6dhotti\u1e63\u1e6dha govinda utti\u1e63\u1e6dha garu\u1e0dadhvaja |\nutti\u1e63\u1e6dha kamal\u0101k\u0101nta trailokya\u1e43 ma\u1e45gala\u1e43 kuru || 2 ||"},
        draftTranslation: "Arise, arise, O Govinda! Arise, O You who have Garuda on Your banner! Arise, O Beloved of Kamala (Lakshmi)! Bestow auspiciousness upon all three worlds!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 3,
        devanagariText: "\u092e\u093e\u0924\u0938\u094d\u0938\u092e\u0938\u094d\u0924\u091c\u0917\u0924\u093e\u0902 \u092e\u0927\u0941\u0915\u0948\u091f\u092d\u093e\u0930\u0947-\n\u0930\u094d\u0935\u0915\u094d\u0937\u094b\u0935\u093f\u0939\u093e\u0930\u093f\u0923\u093f \u092e\u0928\u094b\u0939\u0930\u0926\u093f\u0935\u094d\u092f\u092e\u0942\u0930\u094d\u0924\u0947 \u0964\n\u0936\u094d\u0930\u0940\u091a\u0928\u094d\u0926\u0928\u094b\u0915\u094d\u0937\u093f\u0924\u092a\u092f\u094b\u0927\u0930\u0926\u093f\u0935\u094d\u092f\u0917\u0928\u094d\u0927\u0947\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u0926\u092f\u093f\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0969 \u0965",
        iastText: "m\u0101tassamastajagat\u0101\u1e41 madhukai\u1e6dabh\u0101r\u0113-\nrrak\u1e63\u014dvih\u0101ri\u1e47i man\u014dharadivyam\u016brt\u0113 \u0964\n\u015br\u012bcandan\u014dk\u1e63itapay\u014ddharadivyagandh\u0113\n\u015br\u012bve\u1e45ka\u1e6d\u0113\u015badayit\u0113 tava suprabh\u0101tam \u0965 3 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2e\u0c3e\u0c24\u0c38\u0c4d\u0c38\u0c2e\u0c38\u0c4d\u0c24\u0c1c\u0c17\u0c24\u0c3e\u0c02 \u0c2e\u0c27\u0c41\u0c15\u0c48\u0c1f\u0c2d\u0c3e\u0c30\u0c47-\n\u0c30\u0c4d\u0c35\u0c15\u0c4d\u0c37\u0c4b\u0c35\u0c3f\u0c39\u0c3e\u0c30\u0c3f\u0c23\u0c3f \u0c2e\u0c28\u0c4b\u0c39\u0c30\u0c26\u0c3f\u0c35\u0c4d\u0c2f\u0c2e\u0c42\u0c30\u0c4d\u0c24\u0c47 \u0964\n\u0c36\u0c4d\u0c30\u0c40\u0c1a\u0c28\u0c4d\u0c26\u0c28\u0c4b\u0c15\u0c4d\u0c37\u0c3f\u0c24\u0c2a\u0c2f\u0c4b\u0c27\u0c30\u0c26\u0c3f\u0c35\u0c4d\u0c2f\u0c17\u0c28\u0c4d\u0c27\u0c47\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c26\u0c2f\u0c3f\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c69 \u0965", "tamil": "\u0bae\u0bbe\u0ba4\u0bb8\u0bcd\u0bb8\u0bae\u0bb8\u0bcd\u0ba4\u0b9c\u0b95\u0ba4\u0bbe\u0bae\u0bcd \u0bae\u0ba4\u0bc1\u0b95\u0bc8\u0b9f\u0baa\u0bbe\u0bb0\u0bc7-\n\u0bb0\u0bcd\u0bb5\u0b95\u0bcd\u0bb7\u0bcb\u0bb5\u0bbf\u0bb9\u0bbe\u0bb0\u0bbf\u0ba3\u0bbf \u0bae\u0ba8\u0bcb\u0bb9\u0bb0\u0ba4\u0bbf\u0bb5\u0bcd\u0baf\u0bae\u0bc2\u0bb0\u0bcd\u0ba4\u0bc7 \u0964\n\u0bb6\u0bcd\u0bb0\u0bc0\u0b9a\u0ba8\u0bcd\u0ba4\u0ba8\u0bcb\u0b95\u0bcd\u0bb7\u0bbf\u0ba4\u0baa\u0baf\u0bcb\u0ba4\u0bb0\u0ba4\u0bbf\u0bb5\u0bcd\u0baf\u0b95\u0ba8\u0bcd\u0ba4\u0bc7\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0ba4\u0baf\u0bbf\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be9 \u0965", "kannada": "\u0cae\u0cbe\u0ca4\u0cb8\u0ccd\u0cb8\u0cae\u0cb8\u0ccd\u0ca4\u0c9c\u0c97\u0ca4\u0cbe\u0c82 \u0cae\u0ca7\u0cc1\u0c95\u0cc8\u0c9f\u0cad\u0cbe\u0cb0\u0cc7-\n\u0cb0\u0ccd\u0cb5\u0c95\u0ccd\u0cb7\u0ccb\u0cb5\u0cbf\u0cb9\u0cbe\u0cb0\u0cbf\u0ca3\u0cbf \u0cae\u0ca8\u0ccb\u0cb9\u0cb0\u0ca6\u0cbf\u0cb5\u0ccd\u0caf\u0cae\u0cc2\u0cb0\u0ccd\u0ca4\u0cc7 \u0964\n\u0cb6\u0ccd\u0cb0\u0cc0\u0c9a\u0ca8\u0ccd\u0ca6\u0ca8\u0ccb\u0c95\u0ccd\u0cb7\u0cbf\u0ca4\u0caa\u0caf\u0ccb\u0ca7\u0cb0\u0ca6\u0cbf\u0cb5\u0ccd\u0caf\u0c97\u0ca8\u0ccd\u0ca7\u0cc7\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0ca6\u0caf\u0cbf\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce9 \u0965", "malayalam": "\u0d2e\u0d3e\u0d24\u0d38\u0d4d\u0d38\u0d2e\u0d38\u0d4d\u0d24\u0d1c\u0d17\u0d24\u0d3e\u0d02 \u0d2e\u0d27\u0d41\u0d15\u0d48\u0d1f\u0d2d\u0d3e\u0d30\u0d47-\n\u0d30\u0d4d\u0d35\u0d15\u0d4d\u0d37\u0d4b\u0d35\u0d3f\u0d39\u0d3e\u0d30\u0d3f\u0d23\u0d3f \u0d2e\u0d28\u0d4b\u0d39\u0d30\u0d26\u0d3f\u0d35\u0d4d\u0d2f\u0d2e\u0d42\u0d30\u0d4d\u0d24\u0d47 \u0964\n\u0d36\u0d4d\u0d30\u0d40\u0d1a\u0d28\u0d4d\u0d26\u0d28\u0d4b\u0d15\u0d4d\u0d37\u0d3f\u0d24\u0d2a\u0d2f\u0d4b\u0d27\u0d30\u0d26\u0d3f\u0d35\u0d4d\u0d2f\u0d17\u0d28\u0d4d\u0d27\u0d47\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d26\u0d2f\u0d3f\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d69 \u0965", "iast": "m\u0101tassamastajagat\u0101\u1e43 madhukai\u1e6dabh\u0101re-\nrvak\u1e63ovih\u0101ri\u1e47i manoharadivyam\u016brte |\n\u015br\u012bcandanok\u1e63itapayodharadivyagandhe\n\u015br\u012bve\u1e45ka\u1e6de\u015badayite tava suprabh\u0101tam || 3 ||"},
        draftTranslation: "O Mother of all worlds, who delight upon the chest of the enemy of Madhu and Kaitabha, endowed with an enchanting divine form, fragrant with sacred sandalwood paste! O beloved of Sri Venkatesha, may auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 4,
        devanagariText: "\u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u0930\u0935\u093f\u0928\u094d\u0926\u0932\u094b\u091a\u0928\u0947\n\u092d\u0935\u0924\u0941 \u092a\u094d\u0930\u0938\u0928\u094d\u0928\u092e\u0941\u0916\u091a\u0928\u094d\u0926\u094d\u0930\u092e\u0923\u094d\u0921\u0932\u0947 \u0964\n\u0935\u093f\u0927\u093f\u0936\u0919\u094d\u0915\u0930\u0947\u0928\u094d\u0926\u094d\u0930\u0935\u0928\u093f\u0924\u093e\u092d\u093f\u0930\u0930\u094d\u091a\u093f\u0924\u0947\n\u0935\u0943\u0937\u0936\u0948\u0932\u0928\u093e\u0925\u0926\u092f\u093f\u0924\u0947 \u0926\u092f\u093e\u0928\u093f\u0927\u0947 \u0965 \u096a \u0965",
        iastText: "tava suprabh\u0101tam aravindal\u014dcan\u0113\nbhavatu prasannamukhacandrama\u1e47\u1e0dal\u0113 \u0964\nvidhi\u015ba\u1e45kar\u0113ndravanit\u0101bhirarcit\u0113\nv\u1e5b\u1e63a\u015bailan\u0101thadayit\u0113 day\u0101nidh\u0113 \u0965 4 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c30\u0c35\u0c3f\u0c28\u0c4d\u0c26\u0c32\u0c4b\u0c1a\u0c28\u0c47\n\u0c2d\u0c35\u0c24\u0c41 \u0c2a\u0c4d\u0c30\u0c38\u0c28\u0c4d\u0c28\u0c2e\u0c41\u0c16\u0c1a\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c2e\u0c23\u0c4d\u0c21\u0c32\u0c47 \u0964\n\u0c35\u0c3f\u0c27\u0c3f\u0c36\u0c19\u0c4d\u0c15\u0c30\u0c47\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c35\u0c28\u0c3f\u0c24\u0c3e\u0c2d\u0c3f\u0c30\u0c30\u0c4d\u0c1a\u0c3f\u0c24\u0c47\n\u0c35\u0c43\u0c37\u0c36\u0c48\u0c32\u0c28\u0c3e\u0c25\u0c26\u0c2f\u0c3f\u0c24\u0c47 \u0c26\u0c2f\u0c3e\u0c28\u0c3f\u0c27\u0c47 \u0965 \u0c6a \u0965", "tamil": "\u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bb0\u0bb5\u0bbf\u0ba8\u0bcd\u0ba4\u0bb2\u0bcb\u0b9a\u0ba8\u0bc7\n\u0baa\u0bb5\u0ba4\u0bc1 \u0baa\u0bcd\u0bb0\u0bb8\u0ba8\u0bcd\u0ba8\u0bae\u0bc1\u0b95\u0b9a\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bae\u0ba3\u0bcd\u0b9f\u0bb2\u0bc7 \u0964\n\u0bb5\u0bbf\u0ba4\u0bbf\u0bb6\u0b99\u0bcd\u0b95\u0bb0\u0bc7\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bb5\u0ba8\u0bbf\u0ba4\u0bbe\u0baa\u0bbf\u0bb0\u0bb0\u0bcd\u0b9a\u0bbf\u0ba4\u0bc7\n\u0bb5\u0bcd\u0bb0\u0bc1'\u0bb7\u0bb6\u0bc8\u0bb2\u0ba8\u0bbe\u0ba4\u0ba4\u0baf\u0bbf\u0ba4\u0bc7 \u0ba4\u0baf\u0bbe\u0ba8\u0bbf\u0ba4\u0bc7 \u0965 \u0bea \u0965", "kannada": "\u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0cb0\u0cb5\u0cbf\u0ca8\u0ccd\u0ca6\u0cb2\u0ccb\u0c9a\u0ca8\u0cc7\n\u0cad\u0cb5\u0ca4\u0cc1 \u0caa\u0ccd\u0cb0\u0cb8\u0ca8\u0ccd\u0ca8\u0cae\u0cc1\u0c96\u0c9a\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0cae\u0ca3\u0ccd\u0ca1\u0cb2\u0cc7 \u0964\n\u0cb5\u0cbf\u0ca7\u0cbf\u0cb6\u0c99\u0ccd\u0c95\u0cb0\u0cc7\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0cb5\u0ca8\u0cbf\u0ca4\u0cbe\u0cad\u0cbf\u0cb0\u0cb0\u0ccd\u0c9a\u0cbf\u0ca4\u0cc7\n\u0cb5\u0cc3\u0cb7\u0cb6\u0cc8\u0cb2\u0ca8\u0cbe\u0ca5\u0ca6\u0caf\u0cbf\u0ca4\u0cc7 \u0ca6\u0caf\u0cbe\u0ca8\u0cbf\u0ca7\u0cc7 \u0965 \u0cea \u0965", "malayalam": "\u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d30\u0d35\u0d3f\u0d28\u0d4d\u0d26\u0d32\u0d4b\u0d1a\u0d28\u0d47\n\u0d2d\u0d35\u0d24\u0d41 \u0d2a\u0d4d\u0d30\u0d38\u0d28\u0d4d\u0d28\u0d2e\u0d41\u0d16\u0d1a\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d2e\u0d23\u0d4d\u0d21\u0d32\u0d47 \u0964\n\u0d35\u0d3f\u0d27\u0d3f\u0d36\u0d19\u0d4d\u0d15\u0d30\u0d47\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d35\u0d28\u0d3f\u0d24\u0d3e\u0d2d\u0d3f\u0d30\u0d30\u0d4d\u0d1a\u0d3f\u0d24\u0d47\n\u0d35\u0d43\u0d37\u0d36\u0d48\u0d32\u0d28\u0d3e\u0d25\u0d26\u0d2f\u0d3f\u0d24\u0d47 \u0d26\u0d2f\u0d3e\u0d28\u0d3f\u0d27\u0d47 \u0965 \u0d6a \u0965", "iast": "tava suprabh\u0101tamaravindalocane\nbhavatu prasannamukhacandrama\u1e47\u1e0dale |\nvidhi\u015ba\u1e45karendravanit\u0101bhirarcite\nv\u1e5b\u1e63a\u015bailan\u0101thadayite day\u0101nidhe || 4 ||"},
        draftTranslation: "May this dawn be auspicious to You, O lotus-eyed Mother whose radiant face shines like the full moon! Adored by the consorts of Brahma, Shiva, and Indra, O beloved consort of the Lord of Vrishadri, O ocean of mercy!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 5,
        devanagariText: "\u0905\u0924\u094d\u0930\u094d\u092f\u093e\u0926\u093f\u092e\u0941\u0916\u094d\u092f\u090b\u0937\u092f\u0938\u094d\u0938\u092e\u0941\u092a\u093e\u0938\u094d\u092f \u0938\u0928\u094d\u0927\u094d\u092f\u093e\u0902\n\u0938\u0930\u094b\u0930\u0941\u0939\u092e\u0941\u0915\u0941\u0932\u094b\u092a\u092e\u0926\u093f\u0935\u094d\u092f\u0928\u0947\u0924\u094d\u0930\u093e\u0903 \u0964\n\u0939\u0930\u094d\u0937\u094b\u0924\u094d\u092b\u0941\u0932\u094d\u0932\u0915\u092e\u0932\u093e\u0915\u094d\u0937 \u0924\u0935\u093e\u092d\u093f\u0935\u0928\u094d\u0926\u094d\u092f\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u096b \u0965",
        iastText: "atry\u0101dimukhya-\u1e5b\u1e63ayassamup\u0101sya sandhy\u0101\u1e41\nsar\u014druhamukul\u014dpamadivyan\u0113tr\u0101\u1e25 \u0964\nhar\u1e63\u014dtphullakamal\u0101k\u1e63a tav\u0101bhivandya\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 5 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c05\u0c24\u0c4d\u0c30\u0c4d\u0c2f\u0c3e\u0c26\u0c3f\u0c2e\u0c41\u0c16\u0c4d\u0c2f\u0c0b\u0c37\u0c2f\u0c38\u0c4d\u0c38\u0c2e\u0c41\u0c2a\u0c3e\u0c38\u0c4d\u0c2f \u0c38\u0c28\u0c4d\u0c27\u0c4d\u0c2f\u0c3e\u0c02\n\u0c38\u0c30\u0c4b\u0c30\u0c41\u0c39\u0c2e\u0c41\u0c15\u0c41\u0c32\u0c4b\u0c2a\u0c2e\u0c26\u0c3f\u0c35\u0c4d\u0c2f\u0c28\u0c47\u0c24\u0c4d\u0c30\u0c3e\u0c03 \u0964\n\u0c39\u0c30\u0c4d\u0c37\u0c4b\u0c24\u0c4d\u0c2b\u0c41\u0c32\u0c4d\u0c32\u0c15\u0c2e\u0c32\u0c3e\u0c15\u0c4d\u0c37 \u0c24\u0c35\u0c3e\u0c2d\u0c3f\u0c35\u0c28\u0c4d\u0c26\u0c4d\u0c2f\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c6b \u0965", "tamil": "\u0b85\u0ba4\u0bcd\u0bb0\u0bcd\u0baf\u0bbe\u0ba4\u0bbf\u0bae\u0bc1\u0b95\u0bcd\u0baf\u0bb0\u0bc1'\u0bb7\u0baf\u0bb8\u0bcd\u0bb8\u0bae\u0bc1\u0baa\u0bbe\u0bb8\u0bcd\u0baf \u0bb8\u0ba8\u0bcd\u0ba4\u0bcd\u0baf\u0bbe\u0bae\u0bcd\n\u0bb8\u0bb0\u0bcb\u0bb0\u0bc1\u0bb9\u0bae\u0bc1\u0b95\u0bc1\u0bb2\u0bcb\u0baa\u0bae\u0ba4\u0bbf\u0bb5\u0bcd\u0baf\u0ba8\u0bc7\u0ba4\u0bcd\u0bb0\u0bbe\u0b83 \u0964\n\u0bb9\u0bb0\u0bcd\u0bb7\u0bcb\u0ba4\u0bcd\u0baa\u0bc1\u0bb2\u0bcd\u0bb2\u0b95\u0bae\u0bb2\u0bbe\u0b95\u0bcd\u0bb7 \u0ba4\u0bb5\u0bbe\u0baa\u0bbf\u0bb5\u0ba8\u0bcd\u0ba4\u0bcd\u0baf\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0beb \u0965", "kannada": "\u0c85\u0ca4\u0ccd\u0cb0\u0ccd\u0caf\u0cbe\u0ca6\u0cbf\u0cae\u0cc1\u0c96\u0ccd\u0caf\u0c8b\u0cb7\u0caf\u0cb8\u0ccd\u0cb8\u0cae\u0cc1\u0caa\u0cbe\u0cb8\u0ccd\u0caf \u0cb8\u0ca8\u0ccd\u0ca7\u0ccd\u0caf\u0cbe\u0c82\n\u0cb8\u0cb0\u0ccb\u0cb0\u0cc1\u0cb9\u0cae\u0cc1\u0c95\u0cc1\u0cb2\u0ccb\u0caa\u0cae\u0ca6\u0cbf\u0cb5\u0ccd\u0caf\u0ca8\u0cc7\u0ca4\u0ccd\u0cb0\u0cbe\u0c83 \u0964\n\u0cb9\u0cb0\u0ccd\u0cb7\u0ccb\u0ca4\u0ccd\u0cab\u0cc1\u0cb2\u0ccd\u0cb2\u0c95\u0cae\u0cb2\u0cbe\u0c95\u0ccd\u0cb7 \u0ca4\u0cb5\u0cbe\u0cad\u0cbf\u0cb5\u0ca8\u0ccd\u0ca6\u0ccd\u0caf\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ceb \u0965", "malayalam": "\u0d05\u0d24\u0d4d\u0d30\u0d4d\u0d2f\u0d3e\u0d26\u0d3f\u0d2e\u0d41\u0d16\u0d4d\u0d2f\u0d0b\u0d37\u0d2f\u0d38\u0d4d\u0d38\u0d2e\u0d41\u0d2a\u0d3e\u0d38\u0d4d\u0d2f \u0d38\u0d28\u0d4d\u0d27\u0d4d\u0d2f\u0d3e\u0d02\n\u0d38\u0d30\u0d4b\u0d30\u0d41\u0d39\u0d2e\u0d41\u0d15\u0d41\u0d32\u0d4b\u0d2a\u0d2e\u0d26\u0d3f\u0d35\u0d4d\u0d2f\u0d28\u0d47\u0d24\u0d4d\u0d30\u0d3e\u0d03 \u0964\n\u0d39\u0d30\u0d4d\u0d37\u0d4b\u0d24\u0d4d\u0d2b\u0d41\u0d32\u0d4d\u0d32\u0d15\u0d2e\u0d32\u0d3e\u0d15\u0d4d\u0d37 \u0d24\u0d35\u0d3e\u0d2d\u0d3f\u0d35\u0d28\u0d4d\u0d26\u0d4d\u0d2f\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d6b \u0965", "iast": "atry\u0101dimukhya\u1e5b\u1e63ayassamup\u0101sya sandhy\u0101\u1e43\nsaroruhamukulopamadivyanetr\u0101\u1e25 |\nhar\u1e63otphullakamal\u0101k\u1e63a tav\u0101bhivandya\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 5 ||"},
        draftTranslation: "Great sages headed by Atri, having concluded their morning prayers, stand with divine reverence awaiting Your blessing, O lotus-eyed Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 6,
        devanagariText: "\u092a\u091e\u094d\u091a\u093e\u0928\u0928\u093e\u0926\u093f\u0926\u093f\u0915\u094d\u092a\u093e\u0932\u092e\u0941\u0916\u094d\u092f\u093e\u0938\u094d\u0938\u0930\u094d\u0935\u0947\n\u0938\u092e\u093e\u0917\u0924\u094d\u092f \u0924\u093f\u0937\u094d\u0920\u0928\u094d\u0924\u093f \u0938\u093e\u091e\u094d\u091c\u0932\u093f\u092c\u0928\u094d\u0927\u093e\u0903 \u0964\n\u0906\u0926\u093f\u0936\u0947\u0937\u093e\u0926\u094d\u092f\u0916\u093f\u0932\u0935\u093f\u0939\u0917\u0947\u0936\u094d\u0935\u0930\u093e\u0926\u094d\u092f\u093e\u0903\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u096c \u0965",
        iastText: "pa\u00f1c\u0101nan\u0101didikp\u0101lamukhy\u0101ssarv\u0113\nsam\u0101gatya ti\u1e63\u1e6dhanti s\u0101\u00f1jalibandh\u0101\u1e25 \u0964\n\u0101di\u015b\u0113\u1e63\u0101dyakhilavihag\u0113\u015bvar\u0101dy\u0101\u1e25\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 6 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2a\u0c1e\u0c4d\u0c1a\u0c3e\u0c28\u0c28\u0c3e\u0c26\u0c3f\u0c26\u0c3f\u0c15\u0c4d\u0c2a\u0c3e\u0c32\u0c2e\u0c41\u0c16\u0c4d\u0c2f\u0c3e\u0c38\u0c4d\u0c38\u0c30\u0c4d\u0c35\u0c47\n\u0c38\u0c2e\u0c3e\u0c17\u0c24\u0c4d\u0c2f \u0c24\u0c3f\u0c37\u0c4d\u0c20\u0c28\u0c4d\u0c24\u0c3f \u0c38\u0c3e\u0c1e\u0c4d\u0c1c\u0c32\u0c3f\u0c2c\u0c28\u0c4d\u0c27\u0c3e\u0c03 \u0964\n\u0c06\u0c26\u0c3f\u0c36\u0c47\u0c37\u0c3e\u0c26\u0c4d\u0c2f\u0c16\u0c3f\u0c32\u0c35\u0c3f\u0c39\u0c17\u0c47\u0c36\u0c4d\u0c35\u0c30\u0c3e\u0c26\u0c4d\u0c2f\u0c3e\u0c03\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c6c \u0965", "tamil": "\u0baa\u0b9e\u0bcd\u0b9a\u0bbe\u0ba8\u0ba8\u0bbe\u0ba4\u0bbf\u0ba4\u0bbf\u0b95\u0bcd\u0baa\u0bbe\u0bb2\u0bae\u0bc1\u0b95\u0bcd\u0baf\u0bbe\u0bb8\u0bcd\u0bb8\u0bb0\u0bcd\u0bb5\u0bc7\n\u0bb8\u0bae\u0bbe\u0b95\u0ba4\u0bcd\u0baf \u0ba4\u0bbf\u0bb7\u0bcd\u0b9f\u0ba8\u0bcd\u0ba4\u0bbf \u0bb8\u0bbe\u0b9e\u0bcd\u0b9c\u0bb2\u0bbf\u0baa\u0ba8\u0bcd\u0ba4\u0bbe\u0b83 \u0964\n\u0b86\u0ba4\u0bbf\u0bb6\u0bc7\u0bb7\u0bbe\u0ba4\u0bcd\u0baf\u0b95\u0bbf\u0bb2\u0bb5\u0bbf\u0bb9\u0b95\u0bc7\u0bb6\u0bcd\u0bb5\u0bb0\u0bbe\u0ba4\u0bcd\u0baf\u0bbe\u0b83\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0bec \u0965", "kannada": "\u0caa\u0c9e\u0ccd\u0c9a\u0cbe\u0ca8\u0ca8\u0cbe\u0ca6\u0cbf\u0ca6\u0cbf\u0c95\u0ccd\u0caa\u0cbe\u0cb2\u0cae\u0cc1\u0c96\u0ccd\u0caf\u0cbe\u0cb8\u0ccd\u0cb8\u0cb0\u0ccd\u0cb5\u0cc7\n\u0cb8\u0cae\u0cbe\u0c97\u0ca4\u0ccd\u0caf \u0ca4\u0cbf\u0cb7\u0ccd\u0ca0\u0ca8\u0ccd\u0ca4\u0cbf \u0cb8\u0cbe\u0c9e\u0ccd\u0c9c\u0cb2\u0cbf\u0cac\u0ca8\u0ccd\u0ca7\u0cbe\u0c83 \u0964\n\u0c86\u0ca6\u0cbf\u0cb6\u0cc7\u0cb7\u0cbe\u0ca6\u0ccd\u0caf\u0c96\u0cbf\u0cb2\u0cb5\u0cbf\u0cb9\u0c97\u0cc7\u0cb6\u0ccd\u0cb5\u0cb0\u0cbe\u0ca6\u0ccd\u0caf\u0cbe\u0c83\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0cec \u0965", "malayalam": "\u0d2a\u0d1e\u0d4d\u0d1a\u0d3e\u0d28\u0d28\u0d3e\u0d26\u0d3f\u0d26\u0d3f\u0d15\u0d4d\u0d2a\u0d3e\u0d32\u0d2e\u0d41\u0d16\u0d4d\u0d2f\u0d3e\u0d38\u0d4d\u0d38\u0d30\u0d4d\u0d35\u0d47\n\u0d38\u0d2e\u0d3e\u0d17\u0d24\u0d4d\u0d2f \u0d24\u0d3f\u0d37\u0d4d\u0d20\u0d28\u0d4d\u0d24\u0d3f \u0d38\u0d3e\u0d1e\u0d4d\u0d1c\u0d32\u0d3f\u0d2c\u0d28\u0d4d\u0d27\u0d3e\u0d03 \u0964\n\u0d06\u0d26\u0d3f\u0d36\u0d47\u0d37\u0d3e\u0d26\u0d4d\u0d2f\u0d16\u0d3f\u0d32\u0d35\u0d3f\u0d39\u0d17\u0d47\u0d36\u0d4d\u0d35\u0d30\u0d3e\u0d26\u0d4d\u0d2f\u0d3e\u0d03\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d6c \u0965", "iast": "pa\u00f1c\u0101nan\u0101didikp\u0101lamukhy\u0101ssarve\nsam\u0101gatya ti\u1e63\u1e6dhanti s\u0101\u00f1jalibandh\u0101\u1e25 |\n\u0101di\u015be\u1e63\u0101dyakhilavihage\u015bvar\u0101dy\u0101\u1e25\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 6 ||"},
        draftTranslation: "The guardians of all directions headed by Indra and the deities, along with Adisesha and the kings of celestial birds, assemble with folded hands at Your threshold, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 7,
        devanagariText: "\u0908\u0937\u0924\u094d\u092a\u094d\u0930\u092b\u0941\u0932\u094d\u0932\u0938\u0930\u0938\u0940\u0930\u0941\u0939\u0928\u093e\u0930\u093f\u0915\u0947\u0932-\n\u092a\u0942\u0917\u0926\u094d\u0930\u0941\u092e\u093e\u0926\u093f\u0938\u0941\u092e\u0928\u094b\u0939\u0930\u0915\u093e\u0928\u094d\u0924\u093f\u092d\u093e\u091c\u093e \u0964\n\u092a\u094d\u0930\u093e\u091a\u0940 \u0935\u093f\u092d\u093e\u0924\u093f \u092a\u0930\u093f\u092a\u093e\u0932\u093f\u0924\u0938\u0930\u094d\u0935\u0932\u094b\u0915\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u096d \u0965",
        iastText: "\u012b\u1e63atpraphullasaras\u012bruhan\u0101rik\u0113la-\np\u016bgadrum\u0101disuman\u014dharak\u0101ntibh\u0101j\u0101 \u0964\npr\u0101c\u012b vibh\u0101ti parip\u0101litasarval\u014dka\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 7 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c08\u0c37\u0c24\u0c4d\u0c2a\u0c4d\u0c30\u0c2b\u0c41\u0c32\u0c4d\u0c32\u0c38\u0c30\u0c38\u0c40\u0c30\u0c41\u0c39\u0c28\u0c3e\u0c30\u0c3f\u0c15\u0c47\u0c32-\n\u0c2a\u0c42\u0c17\u0c26\u0c4d\u0c30\u0c41\u0c2e\u0c3e\u0c26\u0c3f\u0c38\u0c41\u0c2e\u0c28\u0c4b\u0c39\u0c30\u0c15\u0c3e\u0c28\u0c4d\u0c24\u0c3f\u0c2d\u0c3e\u0c1c\u0c3e \u0964\n\u0c2a\u0c4d\u0c30\u0c3e\u0c1a\u0c40 \u0c35\u0c3f\u0c2d\u0c3e\u0c24\u0c3f \u0c2a\u0c30\u0c3f\u0c2a\u0c3e\u0c32\u0c3f\u0c24\u0c38\u0c30\u0c4d\u0c35\u0c32\u0c4b\u0c15\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c6d \u0965", "tamil": "\u0b88\u0bb7\u0ba4\u0bcd\u0baa\u0bcd\u0bb0\u0baa\u0bc1\u0bb2\u0bcd\u0bb2\u0bb8\u0bb0\u0bb8\u0bc0\u0bb0\u0bc1\u0bb9\u0ba8\u0bbe\u0bb0\u0bbf\u0b95\u0bc7\u0bb2-\n\u0baa\u0bc2\u0b95\u0ba4\u0bcd\u0bb0\u0bc1\u0bae\u0bbe\u0ba4\u0bbf\u0bb8\u0bc1\u0bae\u0ba8\u0bcb\u0bb9\u0bb0\u0b95\u0bbe\u0ba8\u0bcd\u0ba4\u0bbf\u0baa\u0bbe\u0b9c\u0bbe \u0964\n\u0baa\u0bcd\u0bb0\u0bbe\u0b9a\u0bc0 \u0bb5\u0bbf\u0baa\u0bbe\u0ba4\u0bbf \u0baa\u0bb0\u0bbf\u0baa\u0bbe\u0bb2\u0bbf\u0ba4\u0bb8\u0bb0\u0bcd\u0bb5\u0bb2\u0bcb\u0b95\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0bed \u0965", "kannada": "\u0c88\u0cb7\u0ca4\u0ccd\u0caa\u0ccd\u0cb0\u0cab\u0cc1\u0cb2\u0ccd\u0cb2\u0cb8\u0cb0\u0cb8\u0cc0\u0cb0\u0cc1\u0cb9\u0ca8\u0cbe\u0cb0\u0cbf\u0c95\u0cc7\u0cb2-\n\u0caa\u0cc2\u0c97\u0ca6\u0ccd\u0cb0\u0cc1\u0cae\u0cbe\u0ca6\u0cbf\u0cb8\u0cc1\u0cae\u0ca8\u0ccb\u0cb9\u0cb0\u0c95\u0cbe\u0ca8\u0ccd\u0ca4\u0cbf\u0cad\u0cbe\u0c9c\u0cbe \u0964\n\u0caa\u0ccd\u0cb0\u0cbe\u0c9a\u0cc0 \u0cb5\u0cbf\u0cad\u0cbe\u0ca4\u0cbf \u0caa\u0cb0\u0cbf\u0caa\u0cbe\u0cb2\u0cbf\u0ca4\u0cb8\u0cb0\u0ccd\u0cb5\u0cb2\u0ccb\u0c95\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ced \u0965", "malayalam": "\u0d08\u0d37\u0d24\u0d4d\u0d2a\u0d4d\u0d30\u0d2b\u0d41\u0d32\u0d4d\u0d32\u0d38\u0d30\u0d38\u0d40\u0d30\u0d41\u0d39\u0d28\u0d3e\u0d30\u0d3f\u0d15\u0d47\u0d32-\n\u0d2a\u0d42\u0d17\u0d26\u0d4d\u0d30\u0d41\u0d2e\u0d3e\u0d26\u0d3f\u0d38\u0d41\u0d2e\u0d28\u0d4b\u0d39\u0d30\u0d15\u0d3e\u0d28\u0d4d\u0d24\u0d3f\u0d2d\u0d3e\u0d1c\u0d3e \u0964\n\u0d2a\u0d4d\u0d30\u0d3e\u0d1a\u0d40 \u0d35\u0d3f\u0d2d\u0d3e\u0d24\u0d3f \u0d2a\u0d30\u0d3f\u0d2a\u0d3e\u0d32\u0d3f\u0d24\u0d38\u0d30\u0d4d\u0d35\u0d32\u0d4b\u0d15\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d6d \u0965", "iast": "\u012b\u1e63atpraphullasaras\u012bruhan\u0101rikela-\np\u016bgadrum\u0101disumanoharak\u0101ntibh\u0101j\u0101 |\npr\u0101c\u012b vibh\u0101ti parip\u0101litasarvaloka\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 7 ||"},
        draftTranslation: "The eastern horizon glows with celestial radiance amid gently blooming lotuses and groves of coconut and areca palms, O Sustainer of all creations, Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 8,
        devanagariText: "\u092b\u0941\u0932\u094d\u0932\u093e\u0930\u0935\u093f\u0928\u094d\u0926\u092a\u0930\u093f\u092e\u0932\u092a\u0935\u0928\u0947\u0928 \u092e\u0928\u094d\u0926\u0902\n\u0938\u091e\u094d\u091a\u093e\u0930\u093f\u0924\u0947\u0928 \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u093f\u0924\u0938\u094c\u0916\u094d\u092f\u0932\u0947\u0936\u093e\u0903 \u0964\n\u0917\u093e\u0928\u0902 \u092a\u094d\u0930\u0915\u0941\u0930\u094d\u0935\u0924\u093f \u0935\u0930\u093e\u0919\u094d\u0917\u093f\u0915\u0941\u0932\u093e\u0928\u093f \u0926\u0947\u0935\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u096e \u0965",
        iastText: "phull\u0101ravindaparimalapavan\u0113na manda\u1e41\nsa\u00f1c\u0101rit\u0113na parikalpitasaukhyal\u0113\u015b\u0101\u1e25 \u0964\ng\u0101na\u1e41 prakurvati var\u0101\u1e45gikul\u0101ni d\u0113va\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 8 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2b\u0c41\u0c32\u0c4d\u0c32\u0c3e\u0c30\u0c35\u0c3f\u0c28\u0c4d\u0c26\u0c2a\u0c30\u0c3f\u0c2e\u0c32\u0c2a\u0c35\u0c28\u0c47\u0c28 \u0c2e\u0c28\u0c4d\u0c26\u0c02\n\u0c38\u0c1e\u0c4d\u0c1a\u0c3e\u0c30\u0c3f\u0c24\u0c47\u0c28 \u0c2a\u0c30\u0c3f\u0c15\u0c32\u0c4d\u0c2a\u0c3f\u0c24\u0c38\u0c4c\u0c16\u0c4d\u0c2f\u0c32\u0c47\u0c36\u0c3e\u0c03 \u0964\n\u0c17\u0c3e\u0c28\u0c02 \u0c2a\u0c4d\u0c30\u0c15\u0c41\u0c30\u0c4d\u0c35\u0c24\u0c3f \u0c35\u0c30\u0c3e\u0c19\u0c4d\u0c17\u0c3f\u0c15\u0c41\u0c32\u0c3e\u0c28\u0c3f \u0c26\u0c47\u0c35\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c6e \u0965", "tamil": "\u0baa\u0bc1\u0bb2\u0bcd\u0bb2\u0bbe\u0bb0\u0bb5\u0bbf\u0ba8\u0bcd\u0ba4\u0baa\u0bb0\u0bbf\u0bae\u0bb2\u0baa\u0bb5\u0ba8\u0bc7\u0ba8 \u0bae\u0ba8\u0bcd\u0ba4\u0bae\u0bcd\n\u0bb8\u0b9e\u0bcd\u0b9a\u0bbe\u0bb0\u0bbf\u0ba4\u0bc7\u0ba8 \u0baa\u0bb0\u0bbf\u0b95\u0bb2\u0bcd\u0baa\u0bbf\u0ba4\u0bb8\u0bcc\u0b95\u0bcd\u0baf\u0bb2\u0bc7\u0bb6\u0bbe\u0b83 \u0964\n\u0b95\u0bbe\u0ba8\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0b95\u0bc1\u0bb0\u0bcd\u0bb5\u0ba4\u0bbf \u0bb5\u0bb0\u0bbe\u0b99\u0bcd\u0b95\u0bbf\u0b95\u0bc1\u0bb2\u0bbe\u0ba8\u0bbf \u0ba4\u0bc7\u0bb5\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0bee \u0965", "kannada": "\u0cab\u0cc1\u0cb2\u0ccd\u0cb2\u0cbe\u0cb0\u0cb5\u0cbf\u0ca8\u0ccd\u0ca6\u0caa\u0cb0\u0cbf\u0cae\u0cb2\u0caa\u0cb5\u0ca8\u0cc7\u0ca8 \u0cae\u0ca8\u0ccd\u0ca6\u0c82\n\u0cb8\u0c9e\u0ccd\u0c9a\u0cbe\u0cb0\u0cbf\u0ca4\u0cc7\u0ca8 \u0caa\u0cb0\u0cbf\u0c95\u0cb2\u0ccd\u0caa\u0cbf\u0ca4\u0cb8\u0ccc\u0c96\u0ccd\u0caf\u0cb2\u0cc7\u0cb6\u0cbe\u0c83 \u0964\n\u0c97\u0cbe\u0ca8\u0c82 \u0caa\u0ccd\u0cb0\u0c95\u0cc1\u0cb0\u0ccd\u0cb5\u0ca4\u0cbf \u0cb5\u0cb0\u0cbe\u0c99\u0ccd\u0c97\u0cbf\u0c95\u0cc1\u0cb2\u0cbe\u0ca8\u0cbf \u0ca6\u0cc7\u0cb5\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0cee \u0965", "malayalam": "\u0d2b\u0d41\u0d32\u0d4d\u0d32\u0d3e\u0d30\u0d35\u0d3f\u0d28\u0d4d\u0d26\u0d2a\u0d30\u0d3f\u0d2e\u0d32\u0d2a\u0d35\u0d28\u0d47\u0d28 \u0d2e\u0d28\u0d4d\u0d26\u0d02\n\u0d38\u0d1e\u0d4d\u0d1a\u0d3e\u0d30\u0d3f\u0d24\u0d47\u0d28 \u0d2a\u0d30\u0d3f\u0d15\u0d32\u0d4d\u0d2a\u0d3f\u0d24\u0d38\u0d4c\u0d16\u0d4d\u0d2f\u0d32\u0d47\u0d36\u0d3e\u0d03 \u0964\n\u0d17\u0d3e\u0d28\u0d02 \u0d2a\u0d4d\u0d30\u0d15\u0d41\u0d30\u0d4d\u0d35\u0d24\u0d3f \u0d35\u0d30\u0d3e\u0d19\u0d4d\u0d17\u0d3f\u0d15\u0d41\u0d32\u0d3e\u0d28\u0d3f \u0d26\u0d47\u0d35\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d6e \u0965", "iast": "phull\u0101ravindaparimalapavanena manda\u1e43\nsa\u00f1c\u0101ritena parikalpitasaukhyale\u015b\u0101\u1e25 |\ng\u0101na\u1e43 prakurvati var\u0101\u1e45gikul\u0101ni deva\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 8 ||"},
        draftTranslation: "Delighted by the gentle morning breeze carrying the perfume of blossomed water-lilies, birds warble sweet songs in praise of the Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 9,
        devanagariText: "\u0935\u0943\u0915\u094d\u0937\u093e\u0935\u0932\u093f\u0937\u0941 \u0935\u093f\u091a\u0930\u0926\u094d\u092d\u093f\u0930\u0928\u0947\u0915\u092a\u0915\u094d\u0937\u0940-\n\u0938\u0919\u094d\u0918\u0948\u0903 \u0938\u092e\u0941\u0926\u094d\u0917\u0924\u092e\u0928\u094b\u0939\u0930\u0928\u093e\u0926\u0928\u093e\u0928\u093e \u0964\n\u0932\u094b\u0915\u094b \u0935\u093f\u092c\u094b\u0927\u094d\u092f\u0924 \u0907\u0935\u093e\u0938\u094d\u0924\u093f \u0938\u092e\u0938\u094d\u0924\u0928\u093e\u0925\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u096f \u0965",
        iastText: "v\u1e5bk\u1e63\u0101vali\u1e63u vicaradbhiran\u0113kapak\u1e63\u012b-\nsa\u1e45ghai\u1e25 samudgataman\u014dharan\u0101dan\u0101n\u0101 \u0964\nl\u014dk\u014d vib\u014ddhyata iv\u0101sti samastan\u0101tha\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 9 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c35\u0c43\u0c15\u0c4d\u0c37\u0c3e\u0c35\u0c32\u0c3f\u0c37\u0c41 \u0c35\u0c3f\u0c1a\u0c30\u0c26\u0c4d\u0c2d\u0c3f\u0c30\u0c28\u0c47\u0c15\u0c2a\u0c15\u0c4d\u0c37\u0c40-\n\u0c38\u0c19\u0c4d\u0c18\u0c48\u0c03 \u0c38\u0c2e\u0c41\u0c26\u0c4d\u0c17\u0c24\u0c2e\u0c28\u0c4b\u0c39\u0c30\u0c28\u0c3e\u0c26\u0c28\u0c3e\u0c28\u0c3e \u0964\n\u0c32\u0c4b\u0c15\u0c4b \u0c35\u0c3f\u0c2c\u0c4b\u0c27\u0c4d\u0c2f\u0c24 \u0c07\u0c35\u0c3e\u0c38\u0c4d\u0c24\u0c3f \u0c38\u0c2e\u0c38\u0c4d\u0c24\u0c28\u0c3e\u0c25\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c6f \u0965", "tamil": "\u0bb5\u0bcd\u0bb0\u0bc1'\u0b95\u0bcd\u0bb7\u0bbe\u0bb5\u0bb2\u0bbf\u0bb7\u0bc1 \u0bb5\u0bbf\u0b9a\u0bb0\u0ba4\u0bcd\u0baa\u0bbf\u0bb0\u0ba8\u0bc7\u0b95\u0baa\u0b95\u0bcd\u0bb7\u0bc0-\n\u0bb8\u0b99\u0bcd\u0b95\u0bc8\u0b83 \u0bb8\u0bae\u0bc1\u0ba4\u0bcd\u0b95\u0ba4\u0bae\u0ba8\u0bcb\u0bb9\u0bb0\u0ba8\u0bbe\u0ba4\u0ba8\u0bbe\u0ba8\u0bbe \u0964\n\u0bb2\u0bcb\u0b95\u0bcb \u0bb5\u0bbf\u0baa\u0bcb\u0ba4\u0bcd\u0baf\u0ba4 \u0b87\u0bb5\u0bbe\u0bb8\u0bcd\u0ba4\u0bbf \u0bb8\u0bae\u0bb8\u0bcd\u0ba4\u0ba8\u0bbe\u0ba4\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0bef \u0965", "kannada": "\u0cb5\u0cc3\u0c95\u0ccd\u0cb7\u0cbe\u0cb5\u0cb2\u0cbf\u0cb7\u0cc1 \u0cb5\u0cbf\u0c9a\u0cb0\u0ca6\u0ccd\u0cad\u0cbf\u0cb0\u0ca8\u0cc7\u0c95\u0caa\u0c95\u0ccd\u0cb7\u0cc0-\n\u0cb8\u0c99\u0ccd\u0c98\u0cc8\u0c83 \u0cb8\u0cae\u0cc1\u0ca6\u0ccd\u0c97\u0ca4\u0cae\u0ca8\u0ccb\u0cb9\u0cb0\u0ca8\u0cbe\u0ca6\u0ca8\u0cbe\u0ca8\u0cbe \u0964\n\u0cb2\u0ccb\u0c95\u0ccb \u0cb5\u0cbf\u0cac\u0ccb\u0ca7\u0ccd\u0caf\u0ca4 \u0c87\u0cb5\u0cbe\u0cb8\u0ccd\u0ca4\u0cbf \u0cb8\u0cae\u0cb8\u0ccd\u0ca4\u0ca8\u0cbe\u0ca5\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0cef \u0965", "malayalam": "\u0d35\u0d43\u0d15\u0d4d\u0d37\u0d3e\u0d35\u0d32\u0d3f\u0d37\u0d41 \u0d35\u0d3f\u0d1a\u0d30\u0d26\u0d4d\u0d2d\u0d3f\u0d30\u0d28\u0d47\u0d15\u0d2a\u0d15\u0d4d\u0d37\u0d40-\n\u0d38\u0d19\u0d4d\u0d18\u0d48\u0d03 \u0d38\u0d2e\u0d41\u0d26\u0d4d\u0d17\u0d24\u0d2e\u0d28\u0d4b\u0d39\u0d30\u0d28\u0d3e\u0d26\u0d28\u0d3e\u0d28\u0d3e \u0964\n\u0d32\u0d4b\u0d15\u0d4b \u0d35\u0d3f\u0d2c\u0d4b\u0d27\u0d4d\u0d2f\u0d24 \u0d07\u0d35\u0d3e\u0d38\u0d4d\u0d24\u0d3f \u0d38\u0d2e\u0d38\u0d4d\u0d24\u0d28\u0d3e\u0d25\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d6f \u0965", "iast": "v\u1e5bk\u1e63\u0101vali\u1e63u vicaradbhiranekapak\u1e63\u012b-\nsa\u1e45ghai\u1e25 samudgatamanoharan\u0101dan\u0101n\u0101 |\nloko vibodhyata iv\u0101sti samastan\u0101tha\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 9 ||"},
        draftTranslation: "Flocks of birds moving through the tree-tops fill the sky with melodious chirping, gently awakening the sleeping world, O Master of the universe, Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 10,
        devanagariText: "\u0938\u092a\u094d\u0924\u0930\u094d\u0937\u093f\u092e\u0923\u094d\u0921\u0932\u092e\u0941\u092a\u093e\u0938\u094d\u092f \u0938\u0941\u092a\u0942\u091c\u094d\u092f\u092a\u093e\u0926\u094c\n\u0938\u0942\u0930\u094d\u092f\u093e\u0926\u093f\u0924\u0947\u091c\u0938\u092e\u093f\u0939\u093e\u092d\u093f\u0938\u092e\u0940\u0915\u094d\u0937\u094d\u092f \u0939\u0943\u0937\u094d\u091f\u093e\u0903 \u0964\n\u0917\u093e\u092f\u0928\u094d\u0924\u093f \u0938\u093e\u092e \u0935\u093f\u0935\u093f\u0927\u0948\u0903 \u092a\u0926\u092a\u0919\u094d\u0915\u094d\u0924\u093f\u092d\u0947\u0926\u0948\u0903\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0967\u0966 \u0965",
        iastText: "saptar\u1e63ima\u1e47\u1e0dalamup\u0101sya sup\u016bjyap\u0101dau\ns\u016bry\u0101dit\u0113jasamih\u0101bhisam\u012bk\u1e63ya h\u1e5b\u1e63\u1e6d\u0101\u1e25 \u0964\ng\u0101yanti s\u0101ma vividhai\u1e25 padapa\u1e45ktibh\u0113dai\u1e25\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 10 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c38\u0c2a\u0c4d\u0c24\u0c30\u0c4d\u0c37\u0c3f\u0c2e\u0c23\u0c4d\u0c21\u0c32\u0c2e\u0c41\u0c2a\u0c3e\u0c38\u0c4d\u0c2f \u0c38\u0c41\u0c2a\u0c42\u0c1c\u0c4d\u0c2f\u0c2a\u0c3e\u0c26\u0c4c\n\u0c38\u0c42\u0c30\u0c4d\u0c2f\u0c3e\u0c26\u0c3f\u0c24\u0c47\u0c1c\u0c38\u0c2e\u0c3f\u0c39\u0c3e\u0c2d\u0c3f\u0c38\u0c2e\u0c40\u0c15\u0c4d\u0c37\u0c4d\u0c2f \u0c39\u0c43\u0c37\u0c4d\u0c1f\u0c3e\u0c03 \u0964\n\u0c17\u0c3e\u0c2f\u0c28\u0c4d\u0c24\u0c3f \u0c38\u0c3e\u0c2e \u0c35\u0c3f\u0c35\u0c3f\u0c27\u0c48\u0c03 \u0c2a\u0c26\u0c2a\u0c19\u0c4d\u0c15\u0c4d\u0c24\u0c3f\u0c2d\u0c47\u0c26\u0c48\u0c03\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c67\u0c66 \u0965", "tamil": "\u0bb8\u0baa\u0bcd\u0ba4\u0bb0\u0bcd\u0bb7\u0bbf\u0bae\u0ba3\u0bcd\u0b9f\u0bb2\u0bae\u0bc1\u0baa\u0bbe\u0bb8\u0bcd\u0baf \u0bb8\u0bc1\u0baa\u0bc2\u0b9c\u0bcd\u0baf\u0baa\u0bbe\u0ba4\u0bcc\n\u0bb8\u0bc2\u0bb0\u0bcd\u0baf\u0bbe\u0ba4\u0bbf\u0ba4\u0bc7\u0b9c\u0bb8\u0bae\u0bbf\u0bb9\u0bbe\u0baa\u0bbf\u0bb8\u0bae\u0bc0\u0b95\u0bcd\u0bb7\u0bcd\u0baf \u0bb9\u0bcd\u0bb0\u0bc1'\u0bb7\u0bcd\u0b9f\u0bbe\u0b83 \u0964\n\u0b95\u0bbe\u0baf\u0ba8\u0bcd\u0ba4\u0bbf \u0bb8\u0bbe\u0bae \u0bb5\u0bbf\u0bb5\u0bbf\u0ba4\u0bc8\u0b83 \u0baa\u0ba4\u0baa\u0b99\u0bcd\u0b95\u0bcd\u0ba4\u0bbf\u0baa\u0bc7\u0ba4\u0bc8\u0b83\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be7\u0be6 \u0965", "kannada": "\u0cb8\u0caa\u0ccd\u0ca4\u0cb0\u0ccd\u0cb7\u0cbf\u0cae\u0ca3\u0ccd\u0ca1\u0cb2\u0cae\u0cc1\u0caa\u0cbe\u0cb8\u0ccd\u0caf \u0cb8\u0cc1\u0caa\u0cc2\u0c9c\u0ccd\u0caf\u0caa\u0cbe\u0ca6\u0ccc\n\u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0cbe\u0ca6\u0cbf\u0ca4\u0cc7\u0c9c\u0cb8\u0cae\u0cbf\u0cb9\u0cbe\u0cad\u0cbf\u0cb8\u0cae\u0cc0\u0c95\u0ccd\u0cb7\u0ccd\u0caf \u0cb9\u0cc3\u0cb7\u0ccd\u0c9f\u0cbe\u0c83 \u0964\n\u0c97\u0cbe\u0caf\u0ca8\u0ccd\u0ca4\u0cbf \u0cb8\u0cbe\u0cae \u0cb5\u0cbf\u0cb5\u0cbf\u0ca7\u0cc8\u0c83 \u0caa\u0ca6\u0caa\u0c99\u0ccd\u0c95\u0ccd\u0ca4\u0cbf\u0cad\u0cc7\u0ca6\u0cc8\u0c83\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce7\u0ce6 \u0965", "malayalam": "\u0d38\u0d2a\u0d4d\u0d24\u0d30\u0d4d\u0d37\u0d3f\u0d2e\u0d23\u0d4d\u0d21\u0d32\u0d2e\u0d41\u0d2a\u0d3e\u0d38\u0d4d\u0d2f \u0d38\u0d41\u0d2a\u0d42\u0d1c\u0d4d\u0d2f\u0d2a\u0d3e\u0d26\u0d4c\n\u0d38\u0d42\u0d30\u0d4d\u0d2f\u0d3e\u0d26\u0d3f\u0d24\u0d47\u0d1c\u0d38\u0d2e\u0d3f\u0d39\u0d3e\u0d2d\u0d3f\u0d38\u0d2e\u0d40\u0d15\u0d4d\u0d37\u0d4d\u0d2f \u0d39\u0d43\u0d37\u0d4d\u0d1f\u0d3e\u0d03 \u0964\n\u0d17\u0d3e\u0d2f\u0d28\u0d4d\u0d24\u0d3f \u0d38\u0d3e\u0d2e \u0d35\u0d3f\u0d35\u0d3f\u0d27\u0d48\u0d03 \u0d2a\u0d26\u0d2a\u0d19\u0d4d\u0d15\u0d4d\u0d24\u0d3f\u0d2d\u0d47\u0d26\u0d48\u0d03\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d67\u0d66 \u0965", "iast": "saptar\u1e63ima\u1e47\u1e0dalamup\u0101sya sup\u016bjyap\u0101dau\ns\u016bry\u0101ditejasamih\u0101bhisam\u012bk\u1e63ya h\u1e5b\u1e63\u1e6d\u0101\u1e25 |\ng\u0101yanti s\u0101ma vividhai\u1e25 padapa\u1e45ktibhedai\u1e25\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 10 ||"},
        draftTranslation: "The constellation of the Seven Sages worships Your venerable feet, chanting divine verses of the Sama Veda in diverse sacred melodies, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 11,
        devanagariText: "\u092d\u094d\u0930\u093e\u0924\u0941\u0938\u094d\u0924\u0926\u0940\u092f\u0935\u093f\u092e\u0941\u0916\u0948\u0903 \u092a\u094d\u0930\u0924\u093f\u092a\u093e\u0926\u094d\u092f\u092e\u093e\u0928\u0902\n\u0938\u094d\u0924\u094b\u0924\u094d\u0930\u0902 \u0928\u093f\u0936\u092e\u094d\u092f \u092e\u0941\u0926\u093f\u0924\u0948\u0930\u094d\u092e\u0941\u0928\u093f\u092d\u093f\u0936\u094d\u091a \u092e\u0941\u0916\u094d\u092f\u0948\u0903 \u0964\n\u0906\u0936\u0940\u0930\u094d\u0935\u091a\u093e\u0902\u0938\u093f \u0935\u093f\u092c\u0941\u0927\u093e\u0903 \u092a\u094d\u0930\u092a\u0920\u0928\u094d\u0924\u093f \u092e\u094b\u0926\u093e\u0924\u094d\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0967\u0967 \u0965",
        iastText: "bhr\u0101tustad\u012byavimukhai\u1e25 pratip\u0101dyam\u0101na\u1e41\nst\u014dtra\u1e41 ni\u015bamya muditairmunibhi\u015bca mukhyai\u1e25 \u0964\n\u0101\u015b\u012brvac\u0101\u1e41si vibudh\u0101\u1e25 prapa\u1e6dhanti m\u014dd\u0101t\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 11 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2d\u0c4d\u0c30\u0c3e\u0c24\u0c41\u0c38\u0c4d\u0c24\u0c26\u0c40\u0c2f\u0c35\u0c3f\u0c2e\u0c41\u0c16\u0c48\u0c03 \u0c2a\u0c4d\u0c30\u0c24\u0c3f\u0c2a\u0c3e\u0c26\u0c4d\u0c2f\u0c2e\u0c3e\u0c28\u0c02\n\u0c38\u0c4d\u0c24\u0c4b\u0c24\u0c4d\u0c30\u0c02 \u0c28\u0c3f\u0c36\u0c2e\u0c4d\u0c2f \u0c2e\u0c41\u0c26\u0c3f\u0c24\u0c48\u0c30\u0c4d\u0c2e\u0c41\u0c28\u0c3f\u0c2d\u0c3f\u0c36\u0c4d\u0c1a \u0c2e\u0c41\u0c16\u0c4d\u0c2f\u0c48\u0c03 \u0964\n\u0c06\u0c36\u0c40\u0c30\u0c4d\u0c35\u0c1a\u0c3e\u0c02\u0c38\u0c3f \u0c35\u0c3f\u0c2c\u0c41\u0c27\u0c3e\u0c03 \u0c2a\u0c4d\u0c30\u0c2a\u0c20\u0c28\u0c4d\u0c24\u0c3f \u0c2e\u0c4b\u0c26\u0c3e\u0c24\u0c4d\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c67\u0c67 \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0bbe\u0ba4\u0bc1\u0bb8\u0bcd\u0ba4\u0ba4\u0bc0\u0baf\u0bb5\u0bbf\u0bae\u0bc1\u0b95\u0bc8\u0b83 \u0baa\u0bcd\u0bb0\u0ba4\u0bbf\u0baa\u0bbe\u0ba4\u0bcd\u0baf\u0bae\u0bbe\u0ba8\u0bae\u0bcd\n\u0bb8\u0bcd\u0ba4\u0bcb\u0ba4\u0bcd\u0bb0\u0bae\u0bcd \u0ba8\u0bbf\u0bb6\u0bae\u0bcd\u0baf \u0bae\u0bc1\u0ba4\u0bbf\u0ba4\u0bc8\u0bb0\u0bcd\u0bae\u0bc1\u0ba8\u0bbf\u0baa\u0bbf\u0bb6\u0bcd\u0b9a \u0bae\u0bc1\u0b95\u0bcd\u0baf\u0bc8\u0b83 \u0964\n\u0b86\u0bb6\u0bc0\u0bb0\u0bcd\u0bb5\u0b9a\u0bbe\u0bae\u0bcd\u0bb8\u0bbf \u0bb5\u0bbf\u0baa\u0bc1\u0ba4\u0bbe\u0b83 \u0baa\u0bcd\u0bb0\u0baa\u0b9f\u0ba8\u0bcd\u0ba4\u0bbf \u0bae\u0bcb\u0ba4\u0bbe\u0ba4\u0bcd\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be7\u0be7 \u0965", "kannada": "\u0cad\u0ccd\u0cb0\u0cbe\u0ca4\u0cc1\u0cb8\u0ccd\u0ca4\u0ca6\u0cc0\u0caf\u0cb5\u0cbf\u0cae\u0cc1\u0c96\u0cc8\u0c83 \u0caa\u0ccd\u0cb0\u0ca4\u0cbf\u0caa\u0cbe\u0ca6\u0ccd\u0caf\u0cae\u0cbe\u0ca8\u0c82\n\u0cb8\u0ccd\u0ca4\u0ccb\u0ca4\u0ccd\u0cb0\u0c82 \u0ca8\u0cbf\u0cb6\u0cae\u0ccd\u0caf \u0cae\u0cc1\u0ca6\u0cbf\u0ca4\u0cc8\u0cb0\u0ccd\u0cae\u0cc1\u0ca8\u0cbf\u0cad\u0cbf\u0cb6\u0ccd\u0c9a \u0cae\u0cc1\u0c96\u0ccd\u0caf\u0cc8\u0c83 \u0964\n\u0c86\u0cb6\u0cc0\u0cb0\u0ccd\u0cb5\u0c9a\u0cbe\u0c82\u0cb8\u0cbf \u0cb5\u0cbf\u0cac\u0cc1\u0ca7\u0cbe\u0c83 \u0caa\u0ccd\u0cb0\u0caa\u0ca0\u0ca8\u0ccd\u0ca4\u0cbf \u0cae\u0ccb\u0ca6\u0cbe\u0ca4\u0ccd\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce7\u0ce7 \u0965", "malayalam": "\u0d2d\u0d4d\u0d30\u0d3e\u0d24\u0d41\u0d38\u0d4d\u0d24\u0d26\u0d40\u0d2f\u0d35\u0d3f\u0d2e\u0d41\u0d16\u0d48\u0d03 \u0d2a\u0d4d\u0d30\u0d24\u0d3f\u0d2a\u0d3e\u0d26\u0d4d\u0d2f\u0d2e\u0d3e\u0d28\u0d02\n\u0d38\u0d4d\u0d24\u0d4b\u0d24\u0d4d\u0d30\u0d02 \u0d28\u0d3f\u0d36\u0d2e\u0d4d\u0d2f \u0d2e\u0d41\u0d26\u0d3f\u0d24\u0d48\u0d30\u0d4d\u0d2e\u0d41\u0d28\u0d3f\u0d2d\u0d3f\u0d36\u0d4d\u0d1a \u0d2e\u0d41\u0d16\u0d4d\u0d2f\u0d48\u0d03 \u0964\n\u0d06\u0d36\u0d40\u0d30\u0d4d\u0d35\u0d1a\u0d3e\u0d02\u0d38\u0d3f \u0d35\u0d3f\u0d2c\u0d41\u0d27\u0d3e\u0d03 \u0d2a\u0d4d\u0d30\u0d2a\u0d20\u0d28\u0d4d\u0d24\u0d3f \u0d2e\u0d4b\u0d26\u0d3e\u0d24\u0d4d\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d67\u0d67 \u0965", "iast": "bhr\u0101tustad\u012byavimukhai\u1e25 pratip\u0101dyam\u0101na\u1e43\nstotra\u1e43 ni\u015bamya muditairmunibhi\u015bca mukhyai\u1e25 |\n\u0101\u015b\u012brvac\u0101\u1e43si vibudh\u0101\u1e25 prapa\u1e6dhanti mod\u0101t\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 11 ||"},
        draftTranslation: "Listening to sacred hymns recited by exalted ascetics, celestials joyously utter auspicious benedictions, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 12,
        devanagariText: "\u0926\u0947\u0935\u0947\u0928\u094d\u0926\u094d\u0930\u092e\u0941\u0916\u094d\u092f\u0938\u0941\u0930\u0938\u0919\u094d\u0918\u092e\u0939\u0930\u094d\u0937\u093f\u0938\u0902\u0918\u093e\u0903\n\u0938\u0902\u0938\u0947\u0935\u093f\u0924\u0941\u0902 \u0924\u0935 \u0935\u093f\u092d\u094b \u091a\u0930\u0923\u094c \u092a\u094d\u0930\u092a\u0928\u094d\u0928\u093e\u0903 \u0964\n\u0928\u0947\u0924\u094d\u0930\u094b\u0924\u094d\u0938\u0935\u093e\u092f \u0938\u0941\u092e\u0941\u0916\u0902 \u0915\u0941\u0930\u0941 \u092e\u0947 \u092a\u094d\u0930\u0938\u0928\u094d\u0928\u0902\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0967\u0968 \u0965",
        iastText: "d\u0113v\u0113ndramukhyasurasa\u1e45ghamahar\u1e63isa\u1e41gh\u0101\u1e25\nsa\u1e41s\u0113vitu\u1e41 tava vibh\u014d cara\u1e47au prapann\u0101\u1e25 \u0964\nn\u0113tr\u014dtsav\u0101ya sumukha\u1e41 kuru m\u0113 prasanna\u1e41\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 12 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c26\u0c47\u0c35\u0c47\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c2e\u0c41\u0c16\u0c4d\u0c2f\u0c38\u0c41\u0c30\u0c38\u0c19\u0c4d\u0c18\u0c2e\u0c39\u0c30\u0c4d\u0c37\u0c3f\u0c38\u0c02\u0c18\u0c3e\u0c03\n\u0c38\u0c02\u0c38\u0c47\u0c35\u0c3f\u0c24\u0c41\u0c02 \u0c24\u0c35 \u0c35\u0c3f\u0c2d\u0c4b \u0c1a\u0c30\u0c23\u0c4c \u0c2a\u0c4d\u0c30\u0c2a\u0c28\u0c4d\u0c28\u0c3e\u0c03 \u0964\n\u0c28\u0c47\u0c24\u0c4d\u0c30\u0c4b\u0c24\u0c4d\u0c38\u0c35\u0c3e\u0c2f \u0c38\u0c41\u0c2e\u0c41\u0c16\u0c02 \u0c15\u0c41\u0c30\u0c41 \u0c2e\u0c47 \u0c2a\u0c4d\u0c30\u0c38\u0c28\u0c4d\u0c28\u0c02\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c67\u0c68 \u0965", "tamil": "\u0ba4\u0bc7\u0bb5\u0bc7\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bae\u0bc1\u0b95\u0bcd\u0baf\u0bb8\u0bc1\u0bb0\u0bb8\u0b99\u0bcd\u0b95\u0bae\u0bb9\u0bb0\u0bcd\u0bb7\u0bbf\u0bb8\u0bae\u0bcd\u0b95\u0bbe\u0b83\n\u0bb8\u0bae\u0bcd\u0bb8\u0bc7\u0bb5\u0bbf\u0ba4\u0bc1\u0bae\u0bcd \u0ba4\u0bb5 \u0bb5\u0bbf\u0baa\u0bcb \u0b9a\u0bb0\u0ba3\u0bcc \u0baa\u0bcd\u0bb0\u0baa\u0ba8\u0bcd\u0ba8\u0bbe\u0b83 \u0964\n\u0ba8\u0bc7\u0ba4\u0bcd\u0bb0\u0bcb\u0ba4\u0bcd\u0bb8\u0bb5\u0bbe\u0baf \u0bb8\u0bc1\u0bae\u0bc1\u0b95\u0bae\u0bcd \u0b95\u0bc1\u0bb0\u0bc1 \u0bae\u0bc7 \u0baa\u0bcd\u0bb0\u0bb8\u0ba8\u0bcd\u0ba8\u0bae\u0bcd\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be7\u0be8 \u0965", "kannada": "\u0ca6\u0cc7\u0cb5\u0cc7\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0cae\u0cc1\u0c96\u0ccd\u0caf\u0cb8\u0cc1\u0cb0\u0cb8\u0c99\u0ccd\u0c98\u0cae\u0cb9\u0cb0\u0ccd\u0cb7\u0cbf\u0cb8\u0c82\u0c98\u0cbe\u0c83\n\u0cb8\u0c82\u0cb8\u0cc7\u0cb5\u0cbf\u0ca4\u0cc1\u0c82 \u0ca4\u0cb5 \u0cb5\u0cbf\u0cad\u0ccb \u0c9a\u0cb0\u0ca3\u0ccc \u0caa\u0ccd\u0cb0\u0caa\u0ca8\u0ccd\u0ca8\u0cbe\u0c83 \u0964\n\u0ca8\u0cc7\u0ca4\u0ccd\u0cb0\u0ccb\u0ca4\u0ccd\u0cb8\u0cb5\u0cbe\u0caf \u0cb8\u0cc1\u0cae\u0cc1\u0c96\u0c82 \u0c95\u0cc1\u0cb0\u0cc1 \u0cae\u0cc7 \u0caa\u0ccd\u0cb0\u0cb8\u0ca8\u0ccd\u0ca8\u0c82\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce7\u0ce8 \u0965", "malayalam": "\u0d26\u0d47\u0d35\u0d47\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d2e\u0d41\u0d16\u0d4d\u0d2f\u0d38\u0d41\u0d30\u0d38\u0d19\u0d4d\u0d18\u0d2e\u0d39\u0d30\u0d4d\u0d37\u0d3f\u0d38\u0d02\u0d18\u0d3e\u0d03\n\u0d38\u0d02\u0d38\u0d47\u0d35\u0d3f\u0d24\u0d41\u0d02 \u0d24\u0d35 \u0d35\u0d3f\u0d2d\u0d4b \u0d1a\u0d30\u0d23\u0d4c \u0d2a\u0d4d\u0d30\u0d2a\u0d28\u0d4d\u0d28\u0d3e\u0d03 \u0964\n\u0d28\u0d47\u0d24\u0d4d\u0d30\u0d4b\u0d24\u0d4d\u0d38\u0d35\u0d3e\u0d2f \u0d38\u0d41\u0d2e\u0d41\u0d16\u0d02 \u0d15\u0d41\u0d30\u0d41 \u0d2e\u0d47 \u0d2a\u0d4d\u0d30\u0d38\u0d28\u0d4d\u0d28\u0d02\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d67\u0d68 \u0965", "iast": "devendramukhyasurasa\u1e45ghamahar\u1e63isa\u1e43gh\u0101\u1e25\nsa\u1e43sevitu\u1e43 tava vibho cara\u1e47au prapann\u0101\u1e25 |\nnetrotsav\u0101ya sumukha\u1e43 kuru me prasanna\u1e43\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 12 ||"},
        draftTranslation: "Assemblies of gods headed by Devendra and crowds of great sages have arrived to serve Your feet, O omnipresent Lord! Turn Your radiant face toward us in grace, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 13,
        devanagariText: "\u0915\u091e\u094d\u091c\u093e\u0938\u0928\u093e\u0926\u093f\u0915\u0935\u093f\u0936\u0947\u0916\u0930\u0935\u0928\u094d\u0926\u093f\u0924\u093e\u0919\u094d\u0918\u094d\u0930\u0947\n\u0917\u0919\u094d\u0917\u093e\u0927\u0930\u092a\u094d\u0930\u0923\u0924\u092a\u093e\u0926\u0938\u0930\u094b\u0930\u0941\u0939\u093e\u0915\u094d\u0937 \u0964\n\u0938\u0902\u0938\u093e\u0930\u092a\u093e\u0930\u092e\u0927\u093f\u0917\u092e\u094d\u092f \u0938\u0941\u092a\u0941\u0923\u094d\u092f\u0930\u093e\u0936\u093f\u0902\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0967\u0969 \u0965",
        iastText: "ka\u00f1j\u0101san\u0101dikavi\u015b\u0113kharavandit\u0101\u1e45ghr\u0113\nga\u1e45g\u0101dharapra\u1e47atap\u0101dasar\u014druh\u0101k\u1e63a \u0964\nsa\u1e41s\u0101rap\u0101ramadhigamya supu\u1e47yar\u0101\u015bi\u1e41\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 13 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c15\u0c1e\u0c4d\u0c1c\u0c3e\u0c38\u0c28\u0c3e\u0c26\u0c3f\u0c15\u0c35\u0c3f\u0c36\u0c47\u0c16\u0c30\u0c35\u0c28\u0c4d\u0c26\u0c3f\u0c24\u0c3e\u0c19\u0c4d\u0c18\u0c4d\u0c30\u0c47\n\u0c17\u0c19\u0c4d\u0c17\u0c3e\u0c27\u0c30\u0c2a\u0c4d\u0c30\u0c23\u0c24\u0c2a\u0c3e\u0c26\u0c38\u0c30\u0c4b\u0c30\u0c41\u0c39\u0c3e\u0c15\u0c4d\u0c37 \u0964\n\u0c38\u0c02\u0c38\u0c3e\u0c30\u0c2a\u0c3e\u0c30\u0c2e\u0c27\u0c3f\u0c17\u0c2e\u0c4d\u0c2f \u0c38\u0c41\u0c2a\u0c41\u0c23\u0c4d\u0c2f\u0c30\u0c3e\u0c36\u0c3f\u0c02\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c67\u0c69 \u0965", "tamil": "\u0b95\u0b9e\u0bcd\u0b9c\u0bbe\u0bb8\u0ba8\u0bbe\u0ba4\u0bbf\u0b95\u0bb5\u0bbf\u0bb6\u0bc7\u0b95\u0bb0\u0bb5\u0ba8\u0bcd\u0ba4\u0bbf\u0ba4\u0bbe\u0b99\u0bcd\u0b95\u0bcd\u0bb0\u0bc7\n\u0b95\u0b99\u0bcd\u0b95\u0bbe\u0ba4\u0bb0\u0baa\u0bcd\u0bb0\u0ba3\u0ba4\u0baa\u0bbe\u0ba4\u0bb8\u0bb0\u0bcb\u0bb0\u0bc1\u0bb9\u0bbe\u0b95\u0bcd\u0bb7 \u0964\n\u0bb8\u0bae\u0bcd\u0bb8\u0bbe\u0bb0\u0baa\u0bbe\u0bb0\u0bae\u0ba4\u0bbf\u0b95\u0bae\u0bcd\u0baf \u0bb8\u0bc1\u0baa\u0bc1\u0ba3\u0bcd\u0baf\u0bb0\u0bbe\u0bb6\u0bbf\u0bae\u0bcd\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be7\u0be9 \u0965", "kannada": "\u0c95\u0c9e\u0ccd\u0c9c\u0cbe\u0cb8\u0ca8\u0cbe\u0ca6\u0cbf\u0c95\u0cb5\u0cbf\u0cb6\u0cc7\u0c96\u0cb0\u0cb5\u0ca8\u0ccd\u0ca6\u0cbf\u0ca4\u0cbe\u0c99\u0ccd\u0c98\u0ccd\u0cb0\u0cc7\n\u0c97\u0c99\u0ccd\u0c97\u0cbe\u0ca7\u0cb0\u0caa\u0ccd\u0cb0\u0ca3\u0ca4\u0caa\u0cbe\u0ca6\u0cb8\u0cb0\u0ccb\u0cb0\u0cc1\u0cb9\u0cbe\u0c95\u0ccd\u0cb7 \u0964\n\u0cb8\u0c82\u0cb8\u0cbe\u0cb0\u0caa\u0cbe\u0cb0\u0cae\u0ca7\u0cbf\u0c97\u0cae\u0ccd\u0caf \u0cb8\u0cc1\u0caa\u0cc1\u0ca3\u0ccd\u0caf\u0cb0\u0cbe\u0cb6\u0cbf\u0c82\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce7\u0ce9 \u0965", "malayalam": "\u0d15\u0d1e\u0d4d\u0d1c\u0d3e\u0d38\u0d28\u0d3e\u0d26\u0d3f\u0d15\u0d35\u0d3f\u0d36\u0d47\u0d16\u0d30\u0d35\u0d28\u0d4d\u0d26\u0d3f\u0d24\u0d3e\u0d19\u0d4d\u0d18\u0d4d\u0d30\u0d47\n\u0d17\u0d19\u0d4d\u0d17\u0d3e\u0d27\u0d30\u0d2a\u0d4d\u0d30\u0d23\u0d24\u0d2a\u0d3e\u0d26\u0d38\u0d30\u0d4b\u0d30\u0d41\u0d39\u0d3e\u0d15\u0d4d\u0d37 \u0964\n\u0d38\u0d02\u0d38\u0d3e\u0d30\u0d2a\u0d3e\u0d30\u0d2e\u0d27\u0d3f\u0d17\u0d2e\u0d4d\u0d2f \u0d38\u0d41\u0d2a\u0d41\u0d23\u0d4d\u0d2f\u0d30\u0d3e\u0d36\u0d3f\u0d02\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d67\u0d69 \u0965", "iast": "ka\u00f1j\u0101san\u0101dikavi\u015bekharavandit\u0101\u1e45ghre\nga\u1e45g\u0101dharapra\u1e47atap\u0101dasaroruh\u0101k\u1e63a |\nsa\u1e43s\u0101rap\u0101ramadhigamya supu\u1e47yar\u0101\u015bi\u1e43\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 13 ||"},
        draftTranslation: "You whose lotus feet are revered by Brahma, Gangadhara (Shiva), and the crest-jewels of poets, granting liberation across the ocean of worldly existence, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 14,
        devanagariText: "\u0935\u0940\u0923\u093e\u092a\u094d\u0930\u092a\u091e\u094d\u091a\u0935\u093f\u092a\u091e\u094d\u091a\u0940\u0936\u094d\u0930\u0941\u0924\u093f\u092e\u0923\u094d\u0921\u093f\u0924\u093e\u0928\u093f\n\u0928\u093e\u0928\u093e\u0935\u093f\u0927\u093e\u0928\u093f \u092e\u0927\u0941\u0930\u0938\u094d\u0935\u0930\u0917\u0940\u0924\u093f\u0915\u093e\u0928\u093f \u0964\n\u0936\u0943\u0923\u094d\u0935\u0928\u094d\u092a\u094d\u0930\u0939\u0943\u0937\u094d\u091f\u0939\u0943\u0926\u092f\u094b \u0935\u093f\u092c\u0941\u0927\u0948\u0930\u094d\u0928\u092e\u0938\u094d\u092f\u0903\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0967\u096a \u0965",
        iastText: "v\u012b\u1e47\u0101prapa\u00f1cavipa\u00f1c\u012b\u015brutima\u1e47\u1e0dit\u0101ni\nn\u0101n\u0101vidh\u0101ni madhurasvarag\u012btik\u0101ni \u0964\n\u015b\u1e5b\u1e47vanprah\u1e5b\u1e63\u1e6dah\u1e5bday\u014d vibudhairnamasya\u1e25\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 14 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c35\u0c40\u0c23\u0c3e\u0c2a\u0c4d\u0c30\u0c2a\u0c1e\u0c4d\u0c1a\u0c35\u0c3f\u0c2a\u0c1e\u0c4d\u0c1a\u0c40\u0c36\u0c4d\u0c30\u0c41\u0c24\u0c3f\u0c2e\u0c23\u0c4d\u0c21\u0c3f\u0c24\u0c3e\u0c28\u0c3f\n\u0c28\u0c3e\u0c28\u0c3e\u0c35\u0c3f\u0c27\u0c3e\u0c28\u0c3f \u0c2e\u0c27\u0c41\u0c30\u0c38\u0c4d\u0c35\u0c30\u0c17\u0c40\u0c24\u0c3f\u0c15\u0c3e\u0c28\u0c3f \u0964\n\u0c36\u0c43\u0c23\u0c4d\u0c35\u0c28\u0c4d\u0c2a\u0c4d\u0c30\u0c39\u0c43\u0c37\u0c4d\u0c1f\u0c39\u0c43\u0c26\u0c2f\u0c4b \u0c35\u0c3f\u0c2c\u0c41\u0c27\u0c48\u0c30\u0c4d\u0c28\u0c2e\u0c38\u0c4d\u0c2f\u0c03\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c67\u0c6a \u0965", "tamil": "\u0bb5\u0bc0\u0ba3\u0bbe\u0baa\u0bcd\u0bb0\u0baa\u0b9e\u0bcd\u0b9a\u0bb5\u0bbf\u0baa\u0b9e\u0bcd\u0b9a\u0bc0\u0bb6\u0bcd\u0bb0\u0bc1\u0ba4\u0bbf\u0bae\u0ba3\u0bcd\u0b9f\u0bbf\u0ba4\u0bbe\u0ba8\u0bbf\n\u0ba8\u0bbe\u0ba8\u0bbe\u0bb5\u0bbf\u0ba4\u0bbe\u0ba8\u0bbf \u0bae\u0ba4\u0bc1\u0bb0\u0bb8\u0bcd\u0bb5\u0bb0\u0b95\u0bc0\u0ba4\u0bbf\u0b95\u0bbe\u0ba8\u0bbf \u0964\n\u0bb6\u0bcd\u0bb0\u0bc1'\u0ba3\u0bcd\u0bb5\u0ba8\u0bcd\u0baa\u0bcd\u0bb0\u0bb9\u0bcd\u0bb0\u0bc1'\u0bb7\u0bcd\u0b9f\u0bb9\u0bcd\u0bb0\u0bc1'\u0ba4\u0baf\u0bcb \u0bb5\u0bbf\u0baa\u0bc1\u0ba4\u0bc8\u0bb0\u0bcd\u0ba8\u0bae\u0bb8\u0bcd\u0baf\u0b83\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be7\u0bea \u0965", "kannada": "\u0cb5\u0cc0\u0ca3\u0cbe\u0caa\u0ccd\u0cb0\u0caa\u0c9e\u0ccd\u0c9a\u0cb5\u0cbf\u0caa\u0c9e\u0ccd\u0c9a\u0cc0\u0cb6\u0ccd\u0cb0\u0cc1\u0ca4\u0cbf\u0cae\u0ca3\u0ccd\u0ca1\u0cbf\u0ca4\u0cbe\u0ca8\u0cbf\n\u0ca8\u0cbe\u0ca8\u0cbe\u0cb5\u0cbf\u0ca7\u0cbe\u0ca8\u0cbf \u0cae\u0ca7\u0cc1\u0cb0\u0cb8\u0ccd\u0cb5\u0cb0\u0c97\u0cc0\u0ca4\u0cbf\u0c95\u0cbe\u0ca8\u0cbf \u0964\n\u0cb6\u0cc3\u0ca3\u0ccd\u0cb5\u0ca8\u0ccd\u0caa\u0ccd\u0cb0\u0cb9\u0cc3\u0cb7\u0ccd\u0c9f\u0cb9\u0cc3\u0ca6\u0caf\u0ccb \u0cb5\u0cbf\u0cac\u0cc1\u0ca7\u0cc8\u0cb0\u0ccd\u0ca8\u0cae\u0cb8\u0ccd\u0caf\u0c83\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce7\u0cea \u0965", "malayalam": "\u0d35\u0d40\u0d23\u0d3e\u0d2a\u0d4d\u0d30\u0d2a\u0d1e\u0d4d\u0d1a\u0d35\u0d3f\u0d2a\u0d1e\u0d4d\u0d1a\u0d40\u0d36\u0d4d\u0d30\u0d41\u0d24\u0d3f\u0d2e\u0d23\u0d4d\u0d21\u0d3f\u0d24\u0d3e\u0d28\u0d3f\n\u0d28\u0d3e\u0d28\u0d3e\u0d35\u0d3f\u0d27\u0d3e\u0d28\u0d3f \u0d2e\u0d27\u0d41\u0d30\u0d38\u0d4d\u0d35\u0d30\u0d17\u0d40\u0d24\u0d3f\u0d15\u0d3e\u0d28\u0d3f \u0964\n\u0d36\u0d43\u0d23\u0d4d\u0d35\u0d28\u0d4d\u0d2a\u0d4d\u0d30\u0d39\u0d43\u0d37\u0d4d\u0d1f\u0d39\u0d43\u0d26\u0d2f\u0d4b \u0d35\u0d3f\u0d2c\u0d41\u0d27\u0d48\u0d30\u0d4d\u0d28\u0d2e\u0d38\u0d4d\u0d2f\u0d03\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d67\u0d6a \u0965", "iast": "v\u012b\u1e47\u0101prapa\u00f1cavipa\u00f1c\u012b\u015brutima\u1e47\u1e0dit\u0101ni\nn\u0101n\u0101vidh\u0101ni madhurasvarag\u012btik\u0101ni |\n\u015b\u1e5b\u1e47vanprah\u1e5b\u1e63\u1e6dah\u1e5bdayo vibudhairnamasya\u1e25\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 14 ||"},
        draftTranslation: "Listening to the exquisite melodies of celestial vinas tuned to divine srutis, worshipped by the gods, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 15,
        devanagariText: "\u0938\u092a\u094d\u0924\u093e\u091e\u094d\u091c\u0928\u093e\u091a\u0932\u092a\u0924\u0947 \u0915\u0930\u0941\u0923\u093e\u092a\u092f\u094b\u0927\u093f-\n\u0915\u0932\u094d\u0932\u094b\u0932\u0936\u0940\u0915\u0930\u0935\u093f\u092e\u093f\u0936\u094d\u0930\u093f\u0924\u0928\u0947\u0924\u094d\u0930\u092a\u093e\u0924\u0948\u0903 \u0964\n\u0932\u094b\u0915\u093e\u0928\u094d\u0938\u092e\u0938\u094d\u0924\u092d\u0941\u0935\u0928\u093e\u0928\u094d\u092f\u092d\u093f\u0930\u0915\u094d\u0937\u092e\u093e\u0923\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0967\u096b \u0965",
        iastText: "sapt\u0101\u00f1jan\u0101calapat\u0113 karu\u1e47\u0101pay\u014ddhi-\nkall\u014dla\u015b\u012bkaravimi\u015britan\u0113trap\u0101tai\u1e25 \u0964\nl\u014dk\u0101nsamastabhuvan\u0101nyabhirak\u1e63am\u0101\u1e47a\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 15 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c38\u0c2a\u0c4d\u0c24\u0c3e\u0c1e\u0c4d\u0c1c\u0c28\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c15\u0c30\u0c41\u0c23\u0c3e\u0c2a\u0c2f\u0c4b\u0c27\u0c3f-\n\u0c15\u0c32\u0c4d\u0c32\u0c4b\u0c32\u0c36\u0c40\u0c15\u0c30\u0c35\u0c3f\u0c2e\u0c3f\u0c36\u0c4d\u0c30\u0c3f\u0c24\u0c28\u0c47\u0c24\u0c4d\u0c30\u0c2a\u0c3e\u0c24\u0c48\u0c03 \u0964\n\u0c32\u0c4b\u0c15\u0c3e\u0c28\u0c4d\u0c38\u0c2e\u0c38\u0c4d\u0c24\u0c2d\u0c41\u0c35\u0c28\u0c3e\u0c28\u0c4d\u0c2f\u0c2d\u0c3f\u0c30\u0c15\u0c4d\u0c37\u0c2e\u0c3e\u0c23\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c67\u0c6b \u0965", "tamil": "\u0bb8\u0baa\u0bcd\u0ba4\u0bbe\u0b9e\u0bcd\u0b9c\u0ba8\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0b95\u0bb0\u0bc1\u0ba3\u0bbe\u0baa\u0baf\u0bcb\u0ba4\u0bbf-\n\u0b95\u0bb2\u0bcd\u0bb2\u0bcb\u0bb2\u0bb6\u0bc0\u0b95\u0bb0\u0bb5\u0bbf\u0bae\u0bbf\u0bb6\u0bcd\u0bb0\u0bbf\u0ba4\u0ba8\u0bc7\u0ba4\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bc8\u0b83 \u0964\n\u0bb2\u0bcb\u0b95\u0bbe\u0ba8\u0bcd\u0bb8\u0bae\u0bb8\u0bcd\u0ba4\u0baa\u0bc1\u0bb5\u0ba8\u0bbe\u0ba8\u0bcd\u0baf\u0baa\u0bbf\u0bb0\u0b95\u0bcd\u0bb7\u0bae\u0bbe\u0ba3\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be7\u0beb \u0965", "kannada": "\u0cb8\u0caa\u0ccd\u0ca4\u0cbe\u0c9e\u0ccd\u0c9c\u0ca8\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0c95\u0cb0\u0cc1\u0ca3\u0cbe\u0caa\u0caf\u0ccb\u0ca7\u0cbf-\n\u0c95\u0cb2\u0ccd\u0cb2\u0ccb\u0cb2\u0cb6\u0cc0\u0c95\u0cb0\u0cb5\u0cbf\u0cae\u0cbf\u0cb6\u0ccd\u0cb0\u0cbf\u0ca4\u0ca8\u0cc7\u0ca4\u0ccd\u0cb0\u0caa\u0cbe\u0ca4\u0cc8\u0c83 \u0964\n\u0cb2\u0ccb\u0c95\u0cbe\u0ca8\u0ccd\u0cb8\u0cae\u0cb8\u0ccd\u0ca4\u0cad\u0cc1\u0cb5\u0ca8\u0cbe\u0ca8\u0ccd\u0caf\u0cad\u0cbf\u0cb0\u0c95\u0ccd\u0cb7\u0cae\u0cbe\u0ca3\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce7\u0ceb \u0965", "malayalam": "\u0d38\u0d2a\u0d4d\u0d24\u0d3e\u0d1e\u0d4d\u0d1c\u0d28\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d15\u0d30\u0d41\u0d23\u0d3e\u0d2a\u0d2f\u0d4b\u0d27\u0d3f-\n\u0d15\u0d32\u0d4d\u0d32\u0d4b\u0d32\u0d36\u0d40\u0d15\u0d30\u0d35\u0d3f\u0d2e\u0d3f\u0d36\u0d4d\u0d30\u0d3f\u0d24\u0d28\u0d47\u0d24\u0d4d\u0d30\u0d2a\u0d3e\u0d24\u0d48\u0d03 \u0964\n\u0d32\u0d4b\u0d15\u0d3e\u0d28\u0d4d\u0d38\u0d2e\u0d38\u0d4d\u0d24\u0d2d\u0d41\u0d35\u0d28\u0d3e\u0d28\u0d4d\u0d2f\u0d2d\u0d3f\u0d30\u0d15\u0d4d\u0d37\u0d2e\u0d3e\u0d23\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d67\u0d6b \u0965", "iast": "sapt\u0101\u00f1jan\u0101calapate karu\u1e47\u0101payodhi-\nkallola\u015b\u012bkaravimi\u015britanetrap\u0101tai\u1e25 |\nlok\u0101nsamastabhuvan\u0101nyabhirak\u1e63am\u0101\u1e47a\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 15 ||"},
        draftTranslation: "O Sovereign of the seven sacred peaks, who protect all creations with glance-sprinkles from the ocean waves of boundless compassion, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 16,
        devanagariText: "\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u0928\u093f\u0915\u093e\u0938 \u0928\u093f\u0930\u0935\u0926\u094d\u092f \u0938\u0941\u092a\u0942\u0930\u094d\u0923\u0915\u093e\u092e\n\u0938\u0930\u094d\u0935\u091c\u094d\u091e \u0938\u0930\u094d\u0935\u0938\u0941\u0939\u0943\u0926\u092d\u092f\u0926\u093e\u0928\u0926\u0915\u094d\u0937 \u0964\n\u0915\u093e\u0930\u0941\u0923\u094d\u092f\u0935\u093e\u0930\u093f\u0928\u093f\u0927\u093f\u0930\u092d\u094d\u092f\u0941\u0926\u092f\u093e\u092f \u0928\u0944\u0923\u093e\u0902\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0967\u096c \u0965",
        iastText: "lak\u1e63m\u012bnik\u0101sa niravadya sup\u016br\u1e47ak\u0101ma\nsarvaj\u00f1a sarvasuh\u1e5bdabhayad\u0101nadak\u1e63a \u0964\nk\u0101ru\u1e47yav\u0101rinidhirabhyuday\u0101ya n\u1e5d\u1e47\u0101\u1e41\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 16 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c40\u0c28\u0c3f\u0c15\u0c3e\u0c38 \u0c28\u0c3f\u0c30\u0c35\u0c26\u0c4d\u0c2f \u0c38\u0c41\u0c2a\u0c42\u0c30\u0c4d\u0c23\u0c15\u0c3e\u0c2e\n\u0c38\u0c30\u0c4d\u0c35\u0c1c\u0c4d\u0c1e \u0c38\u0c30\u0c4d\u0c35\u0c38\u0c41\u0c39\u0c43\u0c26\u0c2d\u0c2f\u0c26\u0c3e\u0c28\u0c26\u0c15\u0c4d\u0c37 \u0964\n\u0c15\u0c3e\u0c30\u0c41\u0c23\u0c4d\u0c2f\u0c35\u0c3e\u0c30\u0c3f\u0c28\u0c3f\u0c27\u0c3f\u0c30\u0c2d\u0c4d\u0c2f\u0c41\u0c26\u0c2f\u0c3e\u0c2f \u0c28\u0c44\u0c23\u0c3e\u0c02\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c67\u0c6c \u0965", "tamil": "\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bc0\u0ba8\u0bbf\u0b95\u0bbe\u0bb8 \u0ba8\u0bbf\u0bb0\u0bb5\u0ba4\u0bcd\u0baf \u0bb8\u0bc1\u0baa\u0bc2\u0bb0\u0bcd\u0ba3\u0b95\u0bbe\u0bae\n\u0bb8\u0bb0\u0bcd\u0bb5\u0b9c\u0bcd\u0b9e \u0bb8\u0bb0\u0bcd\u0bb5\u0bb8\u0bc1\u0bb9\u0bcd\u0bb0\u0bc1'\u0ba4\u0baa\u0baf\u0ba4\u0bbe\u0ba8\u0ba4\u0b95\u0bcd\u0bb7 \u0964\n\u0b95\u0bbe\u0bb0\u0bc1\u0ba3\u0bcd\u0baf\u0bb5\u0bbe\u0bb0\u0bbf\u0ba8\u0bbf\u0ba4\u0bbf\u0bb0\u0baa\u0bcd\u0baf\u0bc1\u0ba4\u0baf\u0bbe\u0baf \u0ba8\u0bcd\u0bb0\u0bc2'\u0ba3\u0bbe\u0bae\u0bcd\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be7\u0bec \u0965", "kannada": "\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cc0\u0ca8\u0cbf\u0c95\u0cbe\u0cb8 \u0ca8\u0cbf\u0cb0\u0cb5\u0ca6\u0ccd\u0caf \u0cb8\u0cc1\u0caa\u0cc2\u0cb0\u0ccd\u0ca3\u0c95\u0cbe\u0cae\n\u0cb8\u0cb0\u0ccd\u0cb5\u0c9c\u0ccd\u0c9e \u0cb8\u0cb0\u0ccd\u0cb5\u0cb8\u0cc1\u0cb9\u0cc3\u0ca6\u0cad\u0caf\u0ca6\u0cbe\u0ca8\u0ca6\u0c95\u0ccd\u0cb7 \u0964\n\u0c95\u0cbe\u0cb0\u0cc1\u0ca3\u0ccd\u0caf\u0cb5\u0cbe\u0cb0\u0cbf\u0ca8\u0cbf\u0ca7\u0cbf\u0cb0\u0cad\u0ccd\u0caf\u0cc1\u0ca6\u0caf\u0cbe\u0caf \u0ca8\u0cc4\u0ca3\u0cbe\u0c82\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce7\u0cec \u0965", "malayalam": "\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d40\u0d28\u0d3f\u0d15\u0d3e\u0d38 \u0d28\u0d3f\u0d30\u0d35\u0d26\u0d4d\u0d2f \u0d38\u0d41\u0d2a\u0d42\u0d30\u0d4d\u0d23\u0d15\u0d3e\u0d2e\n\u0d38\u0d30\u0d4d\u0d35\u0d1c\u0d4d\u0d1e \u0d38\u0d30\u0d4d\u0d35\u0d38\u0d41\u0d39\u0d43\u0d26\u0d2d\u0d2f\u0d26\u0d3e\u0d28\u0d26\u0d15\u0d4d\u0d37 \u0964\n\u0d15\u0d3e\u0d30\u0d41\u0d23\u0d4d\u0d2f\u0d35\u0d3e\u0d30\u0d3f\u0d28\u0d3f\u0d27\u0d3f\u0d30\u0d2d\u0d4d\u0d2f\u0d41\u0d26\u0d2f\u0d3e\u0d2f \u0d28\u0d44\u0d23\u0d3e\u0d02\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d67\u0d6c \u0965", "iast": "lak\u1e63m\u012bnik\u0101sa niravadya sup\u016br\u1e47ak\u0101ma\nsarvaj\u00f1a sarvasuh\u1e5bdabhayad\u0101nadak\u1e63a |\nk\u0101ru\u1e47yav\u0101rinidhirabhyuday\u0101ya n\u1e5d\u1e47\u0101\u1e43\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 16 ||"},
        draftTranslation: "Abode of Lakshmi, flawless, fulfilled in all desires, omniscient friend of all living beings, expert in granting fearlessness, ocean of mercy for human welfare, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 17,
        devanagariText: "\u0915\u093e\u092e\u093e\u0930\u093f\u092a\u0942\u091c\u093f\u0924\u092a\u0926\u093e\u092e\u094d\u092c\u0941\u091c \u0926\u093f\u0935\u094d\u092f\u092e\u0942\u0930\u094d\u0924\u0947\n\u0936\u094d\u0930\u0940\u092e\u0924\u094d\u0938\u0939\u0938\u094d\u0930\u0915\u093f\u0930\u0923\u092a\u094d\u0930\u0924\u093f\u092e\u093e\u092a\u094d\u0930\u092d\u093e\u0935 \u0964\n\u092d\u0915\u094d\u0924\u093e\u0930\u094d\u0924\u093f\u092d\u091e\u094d\u091c\u0928 \u0926\u092f\u093e\u092a\u0930 \u0938\u0930\u094d\u0935\u0932\u094b\u0915\u0947\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0967\u096d \u0965",
        iastText: "k\u0101m\u0101rip\u016bjitapad\u0101mbuja divyam\u016brt\u0113\n\u015br\u012bmatsahasrakira\u1e47apratim\u0101prabh\u0101va \u0964\nbhakt\u0101rtibha\u00f1jana day\u0101para sarval\u014dk\u0113\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 17 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c15\u0c3e\u0c2e\u0c3e\u0c30\u0c3f\u0c2a\u0c42\u0c1c\u0c3f\u0c24\u0c2a\u0c26\u0c3e\u0c2e\u0c4d\u0c2c\u0c41\u0c1c \u0c26\u0c3f\u0c35\u0c4d\u0c2f\u0c2e\u0c42\u0c30\u0c4d\u0c24\u0c47\n\u0c36\u0c4d\u0c30\u0c40\u0c2e\u0c24\u0c4d\u0c38\u0c39\u0c38\u0c4d\u0c30\u0c15\u0c3f\u0c30\u0c23\u0c2a\u0c4d\u0c30\u0c24\u0c3f\u0c2e\u0c3e\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c35 \u0964\n\u0c2d\u0c15\u0c4d\u0c24\u0c3e\u0c30\u0c4d\u0c24\u0c3f\u0c2d\u0c1e\u0c4d\u0c1c\u0c28 \u0c26\u0c2f\u0c3e\u0c2a\u0c30 \u0c38\u0c30\u0c4d\u0c35\u0c32\u0c4b\u0c15\u0c47\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c67\u0c6d \u0965", "tamil": "\u0b95\u0bbe\u0bae\u0bbe\u0bb0\u0bbf\u0baa\u0bc2\u0b9c\u0bbf\u0ba4\u0baa\u0ba4\u0bbe\u0bae\u0bcd\u0baa\u0bc1\u0b9c \u0ba4\u0bbf\u0bb5\u0bcd\u0baf\u0bae\u0bc2\u0bb0\u0bcd\u0ba4\u0bc7\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bae\u0ba4\u0bcd\u0bb8\u0bb9\u0bb8\u0bcd\u0bb0\u0b95\u0bbf\u0bb0\u0ba3\u0baa\u0bcd\u0bb0\u0ba4\u0bbf\u0bae\u0bbe\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0bb5 \u0964\n\u0baa\u0b95\u0bcd\u0ba4\u0bbe\u0bb0\u0bcd\u0ba4\u0bbf\u0baa\u0b9e\u0bcd\u0b9c\u0ba8 \u0ba4\u0baf\u0bbe\u0baa\u0bb0 \u0bb8\u0bb0\u0bcd\u0bb5\u0bb2\u0bcb\u0b95\u0bc7\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be7\u0bed \u0965", "kannada": "\u0c95\u0cbe\u0cae\u0cbe\u0cb0\u0cbf\u0caa\u0cc2\u0c9c\u0cbf\u0ca4\u0caa\u0ca6\u0cbe\u0cae\u0ccd\u0cac\u0cc1\u0c9c \u0ca6\u0cbf\u0cb5\u0ccd\u0caf\u0cae\u0cc2\u0cb0\u0ccd\u0ca4\u0cc7\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cae\u0ca4\u0ccd\u0cb8\u0cb9\u0cb8\u0ccd\u0cb0\u0c95\u0cbf\u0cb0\u0ca3\u0caa\u0ccd\u0cb0\u0ca4\u0cbf\u0cae\u0cbe\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0cb5 \u0964\n\u0cad\u0c95\u0ccd\u0ca4\u0cbe\u0cb0\u0ccd\u0ca4\u0cbf\u0cad\u0c9e\u0ccd\u0c9c\u0ca8 \u0ca6\u0caf\u0cbe\u0caa\u0cb0 \u0cb8\u0cb0\u0ccd\u0cb5\u0cb2\u0ccb\u0c95\u0cc7\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce7\u0ced \u0965", "malayalam": "\u0d15\u0d3e\u0d2e\u0d3e\u0d30\u0d3f\u0d2a\u0d42\u0d1c\u0d3f\u0d24\u0d2a\u0d26\u0d3e\u0d2e\u0d4d\u0d2c\u0d41\u0d1c \u0d26\u0d3f\u0d35\u0d4d\u0d2f\u0d2e\u0d42\u0d30\u0d4d\u0d24\u0d47\n\u0d36\u0d4d\u0d30\u0d40\u0d2e\u0d24\u0d4d\u0d38\u0d39\u0d38\u0d4d\u0d30\u0d15\u0d3f\u0d30\u0d23\u0d2a\u0d4d\u0d30\u0d24\u0d3f\u0d2e\u0d3e\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d35 \u0964\n\u0d2d\u0d15\u0d4d\u0d24\u0d3e\u0d30\u0d4d\u0d24\u0d3f\u0d2d\u0d1e\u0d4d\u0d1c\u0d28 \u0d26\u0d2f\u0d3e\u0d2a\u0d30 \u0d38\u0d30\u0d4d\u0d35\u0d32\u0d4b\u0d15\u0d47\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d67\u0d6d \u0965", "iast": "k\u0101m\u0101rip\u016bjitapad\u0101mbuja divyam\u016brte\n\u015br\u012bmatsahasrakira\u1e47apratim\u0101prabh\u0101va |\nbhakt\u0101rtibha\u00f1jana day\u0101para sarvaloke\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 17 ||"},
        draftTranslation: "You whose lotus feet are revered by the conqueror of Kama (Shiva), dazzling like a thousand suns, dispeller of devotees' afflictions, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 18,
        devanagariText: "\u0936\u094d\u0930\u0940\u092a\u0926\u094d\u092e\u0928\u093e\u092d \u092a\u0941\u0930\u0941\u0937\u094b\u0924\u094d\u0924\u092e \u0935\u093e\u0938\u0941\u0926\u0947\u0935\n\u0935\u0948\u0915\u0941\u0923\u094d\u0920 \u092e\u093e\u0927\u0935 \u091c\u0928\u093e\u0930\u094d\u0926\u0928 \u091a\u0915\u094d\u0930\u092a\u093e\u0923\u0947 \u0964\n\u0936\u094d\u0930\u0940\u0935\u0924\u094d\u0938\u091a\u093f\u0939\u094d\u0928 \u0936\u0930\u0923\u093e\u0917\u0924\u092a\u093e\u0930\u093f\u091c\u093e\u0924\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936 \u092d\u0917\u0935\u0928\u094d \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0967\u096e \u0965",
        iastText: "\u015br\u012bpadman\u0101bha puru\u1e63\u014dttama v\u0101sud\u0113va\nvaiku\u1e47\u1e6dha m\u0101dhava jan\u0101rdana cakrap\u0101\u1e47\u0113 \u0964\n\u015br\u012bvatsacihna \u015bara\u1e47\u0101gatap\u0101rij\u0101ta\n\u015br\u012bve\u1e45ka\u1e6d\u0113\u015ba bhagavan tava suprabh\u0101tam \u0965 18 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c36\u0c4d\u0c30\u0c40\u0c2a\u0c26\u0c4d\u0c2e\u0c28\u0c3e\u0c2d \u0c2a\u0c41\u0c30\u0c41\u0c37\u0c4b\u0c24\u0c4d\u0c24\u0c2e \u0c35\u0c3e\u0c38\u0c41\u0c26\u0c47\u0c35\n\u0c35\u0c48\u0c15\u0c41\u0c23\u0c4d\u0c20 \u0c2e\u0c3e\u0c27\u0c35 \u0c1c\u0c28\u0c3e\u0c30\u0c4d\u0c26\u0c28 \u0c1a\u0c15\u0c4d\u0c30\u0c2a\u0c3e\u0c23\u0c47 \u0964\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c24\u0c4d\u0c38\u0c1a\u0c3f\u0c39\u0c4d\u0c28 \u0c36\u0c30\u0c23\u0c3e\u0c17\u0c24\u0c2a\u0c3e\u0c30\u0c3f\u0c1c\u0c3e\u0c24\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36 \u0c2d\u0c17\u0c35\u0c28\u0c4d \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c67\u0c6e \u0965", "tamil": "\u0bb6\u0bcd\u0bb0\u0bc0\u0baa\u0ba4\u0bcd\u0bae\u0ba8\u0bbe\u0baa \u0baa\u0bc1\u0bb0\u0bc1\u0bb7\u0bcb\u0ba4\u0bcd\u0ba4\u0bae \u0bb5\u0bbe\u0bb8\u0bc1\u0ba4\u0bc7\u0bb5\n\u0bb5\u0bc8\u0b95\u0bc1\u0ba3\u0bcd\u0b9f \u0bae\u0bbe\u0ba4\u0bb5 \u0b9c\u0ba8\u0bbe\u0bb0\u0bcd\u0ba4\u0ba8 \u0b9a\u0b95\u0bcd\u0bb0\u0baa\u0bbe\u0ba3\u0bc7 \u0964\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0ba4\u0bcd\u0bb8\u0b9a\u0bbf\u0bb9\u0bcd\u0ba8 \u0bb6\u0bb0\u0ba3\u0bbe\u0b95\u0ba4\u0baa\u0bbe\u0bb0\u0bbf\u0b9c\u0bbe\u0ba4\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6 \u0baa\u0b95\u0bb5\u0ba8\u0bcd \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be7\u0bee \u0965", "kannada": "\u0cb6\u0ccd\u0cb0\u0cc0\u0caa\u0ca6\u0ccd\u0cae\u0ca8\u0cbe\u0cad \u0caa\u0cc1\u0cb0\u0cc1\u0cb7\u0ccb\u0ca4\u0ccd\u0ca4\u0cae \u0cb5\u0cbe\u0cb8\u0cc1\u0ca6\u0cc7\u0cb5\n\u0cb5\u0cc8\u0c95\u0cc1\u0ca3\u0ccd\u0ca0 \u0cae\u0cbe\u0ca7\u0cb5 \u0c9c\u0ca8\u0cbe\u0cb0\u0ccd\u0ca6\u0ca8 \u0c9a\u0c95\u0ccd\u0cb0\u0caa\u0cbe\u0ca3\u0cc7 \u0964\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0ca4\u0ccd\u0cb8\u0c9a\u0cbf\u0cb9\u0ccd\u0ca8 \u0cb6\u0cb0\u0ca3\u0cbe\u0c97\u0ca4\u0caa\u0cbe\u0cb0\u0cbf\u0c9c\u0cbe\u0ca4\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6 \u0cad\u0c97\u0cb5\u0ca8\u0ccd \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce7\u0cee \u0965", "malayalam": "\u0d36\u0d4d\u0d30\u0d40\u0d2a\u0d26\u0d4d\u0d2e\u0d28\u0d3e\u0d2d \u0d2a\u0d41\u0d30\u0d41\u0d37\u0d4b\u0d24\u0d4d\u0d24\u0d2e \u0d35\u0d3e\u0d38\u0d41\u0d26\u0d47\u0d35\n\u0d35\u0d48\u0d15\u0d41\u0d23\u0d4d\u0d20 \u0d2e\u0d3e\u0d27\u0d35 \u0d1c\u0d28\u0d3e\u0d30\u0d4d\u0d26\u0d28 \u0d1a\u0d15\u0d4d\u0d30\u0d2a\u0d3e\u0d23\u0d47 \u0964\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d24\u0d4d\u0d38\u0d1a\u0d3f\u0d39\u0d4d\u0d28 \u0d36\u0d30\u0d23\u0d3e\u0d17\u0d24\u0d2a\u0d3e\u0d30\u0d3f\u0d1c\u0d3e\u0d24\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36 \u0d2d\u0d17\u0d35\u0d28\u0d4d \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d67\u0d6e \u0965", "iast": "\u015br\u012bpadman\u0101bha puru\u1e63ottama v\u0101sudeva\nvaiku\u1e47\u1e6dha m\u0101dhava jan\u0101rdana cakrap\u0101\u1e47e |\n\u015br\u012bvatsacihna \u015bara\u1e47\u0101gatap\u0101rij\u0101ta\n\u015br\u012bve\u1e45ka\u1e6de\u015ba bhagavan tava suprabh\u0101tam || 18 ||"},
        draftTranslation: "O Padmanabha, Purushottama, Vasudeva, Vaikuntha, Madhava, Janardana, Discus-bearer! Bearing the Srivatsa mark, wishing-tree (Parijata) to all who surrender, O Lord Venkatesha! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 19,
        devanagariText: "\u0915\u0928\u094d\u0926\u0930\u094d\u092a\u0926\u0930\u094d\u092a\u0939\u0930 \u0938\u0941\u0928\u094d\u0926\u0930 \u0926\u093f\u0935\u094d\u092f\u092e\u0942\u0930\u094d\u0924\u0947\n\u0915\u093e\u0928\u094d\u0924\u093e\u0928\u0941\u0915\u0942\u0932 \u0915\u092e\u0928\u0940\u092f\u0917\u0941\u0923\u093e\u092d\u093f\u0930\u093e\u092e\u093e \u0964\n\u0938\u0930\u094d\u0935\u092a\u094d\u0930\u092a\u0928\u094d\u0928\u092a\u0930\u093f\u092a\u093e\u0932\u0928\u092c\u0926\u094d\u0927\u0926\u0940\u0915\u094d\u0937\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936 \u092d\u0917\u0935\u0928\u094d \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0967\u096f \u0965",
        iastText: "kandarpadarpahara sundara divyam\u016brt\u0113\nk\u0101nt\u0101nuk\u016bla kaman\u012byagu\u1e47\u0101bhir\u0101m\u0101 \u0964\nsarvaprapannaparip\u0101lanabaddhad\u012bk\u1e63a\n\u015br\u012bve\u1e45ka\u1e6d\u0113\u015ba bhagavan tava suprabh\u0101tam \u0965 19 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c15\u0c28\u0c4d\u0c26\u0c30\u0c4d\u0c2a\u0c26\u0c30\u0c4d\u0c2a\u0c39\u0c30 \u0c38\u0c41\u0c28\u0c4d\u0c26\u0c30 \u0c26\u0c3f\u0c35\u0c4d\u0c2f\u0c2e\u0c42\u0c30\u0c4d\u0c24\u0c47\n\u0c15\u0c3e\u0c28\u0c4d\u0c24\u0c3e\u0c28\u0c41\u0c15\u0c42\u0c32 \u0c15\u0c2e\u0c28\u0c40\u0c2f\u0c17\u0c41\u0c23\u0c3e\u0c2d\u0c3f\u0c30\u0c3e\u0c2e\u0c3e \u0964\n\u0c38\u0c30\u0c4d\u0c35\u0c2a\u0c4d\u0c30\u0c2a\u0c28\u0c4d\u0c28\u0c2a\u0c30\u0c3f\u0c2a\u0c3e\u0c32\u0c28\u0c2c\u0c26\u0c4d\u0c27\u0c26\u0c40\u0c15\u0c4d\u0c37\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36 \u0c2d\u0c17\u0c35\u0c28\u0c4d \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c67\u0c6f \u0965", "tamil": "\u0b95\u0ba8\u0bcd\u0ba4\u0bb0\u0bcd\u0baa\u0ba4\u0bb0\u0bcd\u0baa\u0bb9\u0bb0 \u0bb8\u0bc1\u0ba8\u0bcd\u0ba4\u0bb0 \u0ba4\u0bbf\u0bb5\u0bcd\u0baf\u0bae\u0bc2\u0bb0\u0bcd\u0ba4\u0bc7\n\u0b95\u0bbe\u0ba8\u0bcd\u0ba4\u0bbe\u0ba8\u0bc1\u0b95\u0bc2\u0bb2 \u0b95\u0bae\u0ba8\u0bc0\u0baf\u0b95\u0bc1\u0ba3\u0bbe\u0baa\u0bbf\u0bb0\u0bbe\u0bae\u0bbe \u0964\n\u0bb8\u0bb0\u0bcd\u0bb5\u0baa\u0bcd\u0bb0\u0baa\u0ba8\u0bcd\u0ba8\u0baa\u0bb0\u0bbf\u0baa\u0bbe\u0bb2\u0ba8\u0baa\u0ba4\u0bcd\u0ba4\u0ba4\u0bc0\u0b95\u0bcd\u0bb7\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6 \u0baa\u0b95\u0bb5\u0ba8\u0bcd \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be7\u0bef \u0965", "kannada": "\u0c95\u0ca8\u0ccd\u0ca6\u0cb0\u0ccd\u0caa\u0ca6\u0cb0\u0ccd\u0caa\u0cb9\u0cb0 \u0cb8\u0cc1\u0ca8\u0ccd\u0ca6\u0cb0 \u0ca6\u0cbf\u0cb5\u0ccd\u0caf\u0cae\u0cc2\u0cb0\u0ccd\u0ca4\u0cc7\n\u0c95\u0cbe\u0ca8\u0ccd\u0ca4\u0cbe\u0ca8\u0cc1\u0c95\u0cc2\u0cb2 \u0c95\u0cae\u0ca8\u0cc0\u0caf\u0c97\u0cc1\u0ca3\u0cbe\u0cad\u0cbf\u0cb0\u0cbe\u0cae\u0cbe \u0964\n\u0cb8\u0cb0\u0ccd\u0cb5\u0caa\u0ccd\u0cb0\u0caa\u0ca8\u0ccd\u0ca8\u0caa\u0cb0\u0cbf\u0caa\u0cbe\u0cb2\u0ca8\u0cac\u0ca6\u0ccd\u0ca7\u0ca6\u0cc0\u0c95\u0ccd\u0cb7\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6 \u0cad\u0c97\u0cb5\u0ca8\u0ccd \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce7\u0cef \u0965", "malayalam": "\u0d15\u0d28\u0d4d\u0d26\u0d30\u0d4d\u0d2a\u0d26\u0d30\u0d4d\u0d2a\u0d39\u0d30 \u0d38\u0d41\u0d28\u0d4d\u0d26\u0d30 \u0d26\u0d3f\u0d35\u0d4d\u0d2f\u0d2e\u0d42\u0d30\u0d4d\u0d24\u0d47\n\u0d15\u0d3e\u0d28\u0d4d\u0d24\u0d3e\u0d28\u0d41\u0d15\u0d42\u0d32 \u0d15\u0d2e\u0d28\u0d40\u0d2f\u0d17\u0d41\u0d23\u0d3e\u0d2d\u0d3f\u0d30\u0d3e\u0d2e\u0d3e \u0964\n\u0d38\u0d30\u0d4d\u0d35\u0d2a\u0d4d\u0d30\u0d2a\u0d28\u0d4d\u0d28\u0d2a\u0d30\u0d3f\u0d2a\u0d3e\u0d32\u0d28\u0d2c\u0d26\u0d4d\u0d27\u0d26\u0d40\u0d15\u0d4d\u0d37\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36 \u0d2d\u0d17\u0d35\u0d28\u0d4d \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d67\u0d6f \u0965", "iast": "kandarpadarpahara sundara divyam\u016brte\nk\u0101nt\u0101nuk\u016bla kaman\u012byagu\u1e47\u0101bhir\u0101m\u0101 |\nsarvaprapannaparip\u0101lanabaddhad\u012bk\u1e63a\n\u015br\u012bve\u1e45ka\u1e6de\u015ba bhagavan tava suprabh\u0101tam || 19 ||"},
        draftTranslation: "Surpassing the charm of Cupid with Your divine radiance, captivating with graceful attributes, vowed to protect all who take refuge, O Lord Venkatesha! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 20,
        devanagariText: "\u0936\u094d\u0930\u0940\u0936\u0948\u0932\u0935\u093e\u0938 \u0935\u093f\u092c\u0941\u0927\u093e\u0930\u094d\u091a\u093f\u0924\u092a\u093e\u0926\u092a\u0926\u094d\u092e\n\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u0928\u093f\u0935\u093e\u0938 \u0915\u092e\u0932\u093e\u092f\u0924\u092a\u0926\u094d\u092e\u0928\u0947\u0924\u094d\u0930 \u0964\n\u0936\u094d\u0930\u0940\u092e\u0928\u094d \u0926\u092f\u093e\u0928\u093f\u0927\u093f\u0930\u092e\u0928\u094d\u0926\u0917\u0941\u0923\u093e\u092e\u0943\u0924\u093e\u092c\u094d\u0927\u0947\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936 \u092d\u0917\u0935\u0928\u094d \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0968\u0966 \u0965",
        iastText: "\u015br\u012b\u015bailav\u0101sa vibudh\u0101rcitap\u0101dapadma\nlak\u1e63m\u012bniv\u0101sa kamal\u0101yatapadman\u0113tra \u0964\n\u015br\u012bman day\u0101nidhiramandagu\u1e47\u0101m\u1e5bt\u0101bdh\u0113\n\u015br\u012bve\u1e45ka\u1e6d\u0113\u015ba bhagavan tava suprabh\u0101tam \u0965 20 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c36\u0c4d\u0c30\u0c40\u0c36\u0c48\u0c32\u0c35\u0c3e\u0c38 \u0c35\u0c3f\u0c2c\u0c41\u0c27\u0c3e\u0c30\u0c4d\u0c1a\u0c3f\u0c24\u0c2a\u0c3e\u0c26\u0c2a\u0c26\u0c4d\u0c2e\n\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c40\u0c28\u0c3f\u0c35\u0c3e\u0c38 \u0c15\u0c2e\u0c32\u0c3e\u0c2f\u0c24\u0c2a\u0c26\u0c4d\u0c2e\u0c28\u0c47\u0c24\u0c4d\u0c30 \u0964\n\u0c36\u0c4d\u0c30\u0c40\u0c2e\u0c28\u0c4d \u0c26\u0c2f\u0c3e\u0c28\u0c3f\u0c27\u0c3f\u0c30\u0c2e\u0c28\u0c4d\u0c26\u0c17\u0c41\u0c23\u0c3e\u0c2e\u0c43\u0c24\u0c3e\u0c2c\u0c4d\u0c27\u0c47\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36 \u0c2d\u0c17\u0c35\u0c28\u0c4d \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c68\u0c66 \u0965", "tamil": "\u0bb6\u0bcd\u0bb0\u0bc0\u0bb6\u0bc8\u0bb2\u0bb5\u0bbe\u0bb8 \u0bb5\u0bbf\u0baa\u0bc1\u0ba4\u0bbe\u0bb0\u0bcd\u0b9a\u0bbf\u0ba4\u0baa\u0bbe\u0ba4\u0baa\u0ba4\u0bcd\u0bae\n\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bc0\u0ba8\u0bbf\u0bb5\u0bbe\u0bb8 \u0b95\u0bae\u0bb2\u0bbe\u0baf\u0ba4\u0baa\u0ba4\u0bcd\u0bae\u0ba8\u0bc7\u0ba4\u0bcd\u0bb0 \u0964\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bae\u0ba8\u0bcd \u0ba4\u0baf\u0bbe\u0ba8\u0bbf\u0ba4\u0bbf\u0bb0\u0bae\u0ba8\u0bcd\u0ba4\u0b95\u0bc1\u0ba3\u0bbe\u0bae\u0bcd\u0bb0\u0bc1'\u0ba4\u0bbe\u0baa\u0bcd\u0ba4\u0bc7\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6 \u0baa\u0b95\u0bb5\u0ba8\u0bcd \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be8\u0be6 \u0965", "kannada": "\u0cb6\u0ccd\u0cb0\u0cc0\u0cb6\u0cc8\u0cb2\u0cb5\u0cbe\u0cb8 \u0cb5\u0cbf\u0cac\u0cc1\u0ca7\u0cbe\u0cb0\u0ccd\u0c9a\u0cbf\u0ca4\u0caa\u0cbe\u0ca6\u0caa\u0ca6\u0ccd\u0cae\n\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cc0\u0ca8\u0cbf\u0cb5\u0cbe\u0cb8 \u0c95\u0cae\u0cb2\u0cbe\u0caf\u0ca4\u0caa\u0ca6\u0ccd\u0cae\u0ca8\u0cc7\u0ca4\u0ccd\u0cb0 \u0964\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cae\u0ca8\u0ccd \u0ca6\u0caf\u0cbe\u0ca8\u0cbf\u0ca7\u0cbf\u0cb0\u0cae\u0ca8\u0ccd\u0ca6\u0c97\u0cc1\u0ca3\u0cbe\u0cae\u0cc3\u0ca4\u0cbe\u0cac\u0ccd\u0ca7\u0cc7\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6 \u0cad\u0c97\u0cb5\u0ca8\u0ccd \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce8\u0ce6 \u0965", "malayalam": "\u0d36\u0d4d\u0d30\u0d40\u0d36\u0d48\u0d32\u0d35\u0d3e\u0d38 \u0d35\u0d3f\u0d2c\u0d41\u0d27\u0d3e\u0d30\u0d4d\u0d1a\u0d3f\u0d24\u0d2a\u0d3e\u0d26\u0d2a\u0d26\u0d4d\u0d2e\n\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d40\u0d28\u0d3f\u0d35\u0d3e\u0d38 \u0d15\u0d2e\u0d32\u0d3e\u0d2f\u0d24\u0d2a\u0d26\u0d4d\u0d2e\u0d28\u0d47\u0d24\u0d4d\u0d30 \u0964\n\u0d36\u0d4d\u0d30\u0d40\u0d2e\u0d28\u0d4d \u0d26\u0d2f\u0d3e\u0d28\u0d3f\u0d27\u0d3f\u0d30\u0d2e\u0d28\u0d4d\u0d26\u0d17\u0d41\u0d23\u0d3e\u0d2e\u0d43\u0d24\u0d3e\u0d2c\u0d4d\u0d27\u0d47\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36 \u0d2d\u0d17\u0d35\u0d28\u0d4d \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d68\u0d66 \u0965", "iast": "\u015br\u012b\u015bailav\u0101sa vibudh\u0101rcitap\u0101dapadma\nlak\u1e63m\u012bniv\u0101sa kamal\u0101yatapadmanetra |\n\u015br\u012bman day\u0101nidhiramandagu\u1e47\u0101m\u1e5bt\u0101bdhe\n\u015br\u012bve\u1e45ka\u1e6de\u015ba bhagavan tava suprabh\u0101tam || 20 ||"},
        draftTranslation: "Dwelling upon the sacred hill, Your lotus feet worshipped by sages, home of Sri Lakshmi, broad lotus-eyed, nectar-ocean of endless virtues, O Lord Venkatesha! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 21,
        devanagariText: "\u0935\u093f\u092a\u094d\u0930\u093e\u0917\u094d\u0930\u094d\u092f\u0938\u0919\u094d\u0918\u092a\u0930\u093f\u0917\u0940\u0924\u0938\u0941\u092a\u0941\u0923\u094d\u092f\u0915\u0940\u0930\u094d\u0924\u0947\n\u0935\u0947\u0926\u093e\u0930\u094d\u0925\u0924\u0924\u094d\u0935\u0928\u093f\u0927\u092f\u0947 \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0928\u094d\u0928\u093e\u0903 \u0964\n\u0915\u093e\u0930\u0941\u0923\u094d\u092f\u092a\u0942\u0930\u092a\u0930\u093f\u092a\u094b\u0937\u093f\u0924\u0938\u0930\u094d\u0935\u0932\u094b\u0915\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936 \u092d\u0917\u0935\u0928\u094d \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0968\u0967 \u0965",
        iastText: "vipr\u0101gryasa\u1e45ghaparig\u012btasupu\u1e47yak\u012brt\u0113\nv\u0113d\u0101rthatatvanidhay\u0113 \u015bara\u1e47a\u1e41 prapann\u0101\u1e25 \u0964\nk\u0101ru\u1e47yap\u016braparip\u014d\u1e63itasarval\u014dka\n\u015br\u012bve\u1e45ka\u1e6d\u0113\u015ba bhagavan tava suprabh\u0101tam \u0965 21 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c35\u0c3f\u0c2a\u0c4d\u0c30\u0c3e\u0c17\u0c4d\u0c30\u0c4d\u0c2f\u0c38\u0c19\u0c4d\u0c18\u0c2a\u0c30\u0c3f\u0c17\u0c40\u0c24\u0c38\u0c41\u0c2a\u0c41\u0c23\u0c4d\u0c2f\u0c15\u0c40\u0c30\u0c4d\u0c24\u0c47\n\u0c35\u0c47\u0c26\u0c3e\u0c30\u0c4d\u0c25\u0c24\u0c24\u0c4d\u0c35\u0c28\u0c3f\u0c27\u0c2f\u0c47 \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c28\u0c4d\u0c28\u0c3e\u0c03 \u0964\n\u0c15\u0c3e\u0c30\u0c41\u0c23\u0c4d\u0c2f\u0c2a\u0c42\u0c30\u0c2a\u0c30\u0c3f\u0c2a\u0c4b\u0c37\u0c3f\u0c24\u0c38\u0c30\u0c4d\u0c35\u0c32\u0c4b\u0c15\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36 \u0c2d\u0c17\u0c35\u0c28\u0c4d \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c68\u0c67 \u0965", "tamil": "\u0bb5\u0bbf\u0baa\u0bcd\u0bb0\u0bbe\u0b95\u0bcd\u0bb0\u0bcd\u0baf\u0bb8\u0b99\u0bcd\u0b95\u0baa\u0bb0\u0bbf\u0b95\u0bc0\u0ba4\u0bb8\u0bc1\u0baa\u0bc1\u0ba3\u0bcd\u0baf\u0b95\u0bc0\u0bb0\u0bcd\u0ba4\u0bc7\n\u0bb5\u0bc7\u0ba4\u0bbe\u0bb0\u0bcd\u0ba4\u0ba4\u0ba4\u0bcd\u0bb5\u0ba8\u0bbf\u0ba4\u0baf\u0bc7 \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba8\u0bcd\u0ba8\u0bbe\u0b83 \u0964\n\u0b95\u0bbe\u0bb0\u0bc1\u0ba3\u0bcd\u0baf\u0baa\u0bc2\u0bb0\u0baa\u0bb0\u0bbf\u0baa\u0bcb\u0bb7\u0bbf\u0ba4\u0bb8\u0bb0\u0bcd\u0bb5\u0bb2\u0bcb\u0b95\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6 \u0baa\u0b95\u0bb5\u0ba8\u0bcd \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be8\u0be7 \u0965", "kannada": "\u0cb5\u0cbf\u0caa\u0ccd\u0cb0\u0cbe\u0c97\u0ccd\u0cb0\u0ccd\u0caf\u0cb8\u0c99\u0ccd\u0c98\u0caa\u0cb0\u0cbf\u0c97\u0cc0\u0ca4\u0cb8\u0cc1\u0caa\u0cc1\u0ca3\u0ccd\u0caf\u0c95\u0cc0\u0cb0\u0ccd\u0ca4\u0cc7\n\u0cb5\u0cc7\u0ca6\u0cbe\u0cb0\u0ccd\u0ca5\u0ca4\u0ca4\u0ccd\u0cb5\u0ca8\u0cbf\u0ca7\u0caf\u0cc7 \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca8\u0ccd\u0ca8\u0cbe\u0c83 \u0964\n\u0c95\u0cbe\u0cb0\u0cc1\u0ca3\u0ccd\u0caf\u0caa\u0cc2\u0cb0\u0caa\u0cb0\u0cbf\u0caa\u0ccb\u0cb7\u0cbf\u0ca4\u0cb8\u0cb0\u0ccd\u0cb5\u0cb2\u0ccb\u0c95\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6 \u0cad\u0c97\u0cb5\u0ca8\u0ccd \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce8\u0ce7 \u0965", "malayalam": "\u0d35\u0d3f\u0d2a\u0d4d\u0d30\u0d3e\u0d17\u0d4d\u0d30\u0d4d\u0d2f\u0d38\u0d19\u0d4d\u0d18\u0d2a\u0d30\u0d3f\u0d17\u0d40\u0d24\u0d38\u0d41\u0d2a\u0d41\u0d23\u0d4d\u0d2f\u0d15\u0d40\u0d30\u0d4d\u0d24\u0d47\n\u0d35\u0d47\u0d26\u0d3e\u0d30\u0d4d\u0d25\u0d24\u0d24\u0d4d\u0d35\u0d28\u0d3f\u0d27\u0d2f\u0d47 \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d28\u0d4d\u0d28\u0d3e\u0d03 \u0964\n\u0d15\u0d3e\u0d30\u0d41\u0d23\u0d4d\u0d2f\u0d2a\u0d42\u0d30\u0d2a\u0d30\u0d3f\u0d2a\u0d4b\u0d37\u0d3f\u0d24\u0d38\u0d30\u0d4d\u0d35\u0d32\u0d4b\u0d15\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36 \u0d2d\u0d17\u0d35\u0d28\u0d4d \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d68\u0d67 \u0965", "iast": "vipr\u0101gryasa\u1e45ghaparig\u012btasupu\u1e47yak\u012brte\nved\u0101rthatatvanidhaye \u015bara\u1e47a\u1e43 prapann\u0101\u1e25 |\nk\u0101ru\u1e47yap\u016braparipo\u1e63itasarvaloka\n\u015br\u012bve\u1e45ka\u1e6de\u015ba bhagavan tava suprabh\u0101tam || 21 ||"},
        draftTranslation: "Whose sacred glory is sung by assemblies of learned scholars, treasure-house of the essence of the Vedas, nourishing all realms with compassion, O Lord Venkatesha! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 22,
        devanagariText: "\u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0947 \u092e\u0941\u0939\u0942\u0930\u094d\u0924\u0947 \u0935\u093f\u0928\u0924\u093e\u0928\u0941\u0915\u0943\u0924\u0947\u0928 \u092d\u0915\u094d\u0924\u094d\u092f\u093e\n\u0938\u0902\u0938\u0947\u0935\u093f\u0924\u0941\u0902 \u0938\u092e\u0941\u092a\u0917\u092e\u094d\u092f \u092e\u0939\u0930\u094d\u0937\u093f\u0938\u0919\u094d\u0918\u093e\u0903 \u0964\n\u0924\u093f\u0937\u094d\u0920\u0928\u094d\u0924\u093f \u0926\u094d\u0935\u093e\u0930\u093f \u0935\u0930\u0926\u093e\u092d\u092f\u0939\u0938\u094d\u0924\u092f\u0941\u0915\u094d\u0924\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0968\u0968 \u0965",
        iastText: "br\u0101hm\u0113 muh\u016brt\u0113 vinat\u0101nuk\u1e5bt\u0113na bhakty\u0101\nsa\u1e41s\u0113vitu\u1e41 samupagamya mahar\u1e63isa\u1e45gh\u0101\u1e25 \u0964\nti\u1e63\u1e6dhanti dv\u0101ri varad\u0101bhayahastayukta\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 22 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2c\u0c4d\u0c30\u0c3e\u0c39\u0c4d\u0c2e\u0c47 \u0c2e\u0c41\u0c39\u0c42\u0c30\u0c4d\u0c24\u0c47 \u0c35\u0c3f\u0c28\u0c24\u0c3e\u0c28\u0c41\u0c15\u0c43\u0c24\u0c47\u0c28 \u0c2d\u0c15\u0c4d\u0c24\u0c4d\u0c2f\u0c3e\n\u0c38\u0c02\u0c38\u0c47\u0c35\u0c3f\u0c24\u0c41\u0c02 \u0c38\u0c2e\u0c41\u0c2a\u0c17\u0c2e\u0c4d\u0c2f \u0c2e\u0c39\u0c30\u0c4d\u0c37\u0c3f\u0c38\u0c19\u0c4d\u0c18\u0c3e\u0c03 \u0964\n\u0c24\u0c3f\u0c37\u0c4d\u0c20\u0c28\u0c4d\u0c24\u0c3f \u0c26\u0c4d\u0c35\u0c3e\u0c30\u0c3f \u0c35\u0c30\u0c26\u0c3e\u0c2d\u0c2f\u0c39\u0c38\u0c4d\u0c24\u0c2f\u0c41\u0c15\u0c4d\u0c24\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c68\u0c68 \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0bbe\u0bb9\u0bcd\u0bae\u0bc7 \u0bae\u0bc1\u0bb9\u0bc2\u0bb0\u0bcd\u0ba4\u0bc7 \u0bb5\u0bbf\u0ba8\u0ba4\u0bbe\u0ba8\u0bc1\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0bc7\u0ba8 \u0baa\u0b95\u0bcd\u0ba4\u0bcd\u0baf\u0bbe\n\u0bb8\u0bae\u0bcd\u0bb8\u0bc7\u0bb5\u0bbf\u0ba4\u0bc1\u0bae\u0bcd \u0bb8\u0bae\u0bc1\u0baa\u0b95\u0bae\u0bcd\u0baf \u0bae\u0bb9\u0bb0\u0bcd\u0bb7\u0bbf\u0bb8\u0b99\u0bcd\u0b95\u0bbe\u0b83 \u0964\n\u0ba4\u0bbf\u0bb7\u0bcd\u0b9f\u0ba8\u0bcd\u0ba4\u0bbf \u0ba4\u0bcd\u0bb5\u0bbe\u0bb0\u0bbf \u0bb5\u0bb0\u0ba4\u0bbe\u0baa\u0baf\u0bb9\u0bb8\u0bcd\u0ba4\u0baf\u0bc1\u0b95\u0bcd\u0ba4\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be8\u0be8 \u0965", "kannada": "\u0cac\u0ccd\u0cb0\u0cbe\u0cb9\u0ccd\u0cae\u0cc7 \u0cae\u0cc1\u0cb9\u0cc2\u0cb0\u0ccd\u0ca4\u0cc7 \u0cb5\u0cbf\u0ca8\u0ca4\u0cbe\u0ca8\u0cc1\u0c95\u0cc3\u0ca4\u0cc7\u0ca8 \u0cad\u0c95\u0ccd\u0ca4\u0ccd\u0caf\u0cbe\n\u0cb8\u0c82\u0cb8\u0cc7\u0cb5\u0cbf\u0ca4\u0cc1\u0c82 \u0cb8\u0cae\u0cc1\u0caa\u0c97\u0cae\u0ccd\u0caf \u0cae\u0cb9\u0cb0\u0ccd\u0cb7\u0cbf\u0cb8\u0c99\u0ccd\u0c98\u0cbe\u0c83 \u0964\n\u0ca4\u0cbf\u0cb7\u0ccd\u0ca0\u0ca8\u0ccd\u0ca4\u0cbf \u0ca6\u0ccd\u0cb5\u0cbe\u0cb0\u0cbf \u0cb5\u0cb0\u0ca6\u0cbe\u0cad\u0caf\u0cb9\u0cb8\u0ccd\u0ca4\u0caf\u0cc1\u0c95\u0ccd\u0ca4\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce8\u0ce8 \u0965", "malayalam": "\u0d2c\u0d4d\u0d30\u0d3e\u0d39\u0d4d\u0d2e\u0d47 \u0d2e\u0d41\u0d39\u0d42\u0d30\u0d4d\u0d24\u0d47 \u0d35\u0d3f\u0d28\u0d24\u0d3e\u0d28\u0d41\u0d15\u0d43\u0d24\u0d47\u0d28 \u0d2d\u0d15\u0d4d\u0d24\u0d4d\u0d2f\u0d3e\n\u0d38\u0d02\u0d38\u0d47\u0d35\u0d3f\u0d24\u0d41\u0d02 \u0d38\u0d2e\u0d41\u0d2a\u0d17\u0d2e\u0d4d\u0d2f \u0d2e\u0d39\u0d30\u0d4d\u0d37\u0d3f\u0d38\u0d19\u0d4d\u0d18\u0d3e\u0d03 \u0964\n\u0d24\u0d3f\u0d37\u0d4d\u0d20\u0d28\u0d4d\u0d24\u0d3f \u0d26\u0d4d\u0d35\u0d3e\u0d30\u0d3f \u0d35\u0d30\u0d26\u0d3e\u0d2d\u0d2f\u0d39\u0d38\u0d4d\u0d24\u0d2f\u0d41\u0d15\u0d4d\u0d24\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d68\u0d68 \u0965", "iast": "br\u0101hme muh\u016brte vinat\u0101nuk\u1e5btena bhakty\u0101\nsa\u1e43sevitu\u1e43 samupagamya mahar\u1e63isa\u1e45gh\u0101\u1e25 |\nti\u1e63\u1e6dhanti dv\u0101ri varad\u0101bhayahastayukta\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 22 ||"},
        draftTranslation: "At the sacred Brahma-muhurta hour, great sages approach Your golden doorway with profound devotion to behold Your hands bestowing boons and fearlessness, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 23,
        devanagariText: "\u0938\u094d\u0928\u093e\u0928\u094b\u0926\u0915\u0948\u0903 \u092a\u0930\u093f\u092e\u0932\u094b\u092a\u092e\u0936\u0940\u0924\u0924\u094b\u092f\u0948\u0903\n\u0938\u0902\u0938\u094d\u0925\u093e\u092a\u093f\u0924\u0948\u0930\u0939\u093f\u0915\u0941\u0932\u0947\u0928\u094d\u0926\u094d\u0930\u0938\u0941\u0930\u0948\u0930\u094d\u0935\u093f\u092e\u093f\u0936\u094d\u0930\u0948\u0903 \u0964\n\u0905\u092d\u093f\u0937\u0947\u091a\u0928\u093e\u092f \u092d\u0935\u0924\u094b \u092e\u0941\u0926\u093f\u0924\u093e \u092d\u0935\u0928\u094d\u0924\u093f\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0968\u0969 \u0965",
        iastText: "sn\u0101n\u014ddakai\u1e25 parimal\u014dpama\u015b\u012btat\u014dyai\u1e25\nsa\u1e41sth\u0101pitairahikul\u0113ndrasurairvimi\u015brai\u1e25 \u0964\nabhi\u1e63\u0113can\u0101ya bhavat\u014d mudit\u0101 bhavanti\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 23 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c38\u0c4d\u0c28\u0c3e\u0c28\u0c4b\u0c26\u0c15\u0c48\u0c03 \u0c2a\u0c30\u0c3f\u0c2e\u0c32\u0c4b\u0c2a\u0c2e\u0c36\u0c40\u0c24\u0c24\u0c4b\u0c2f\u0c48\u0c03\n\u0c38\u0c02\u0c38\u0c4d\u0c25\u0c3e\u0c2a\u0c3f\u0c24\u0c48\u0c30\u0c39\u0c3f\u0c15\u0c41\u0c32\u0c47\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c38\u0c41\u0c30\u0c48\u0c30\u0c4d\u0c35\u0c3f\u0c2e\u0c3f\u0c36\u0c4d\u0c30\u0c48\u0c03 \u0964\n\u0c05\u0c2d\u0c3f\u0c37\u0c47\u0c1a\u0c28\u0c3e\u0c2f \u0c2d\u0c35\u0c24\u0c4b \u0c2e\u0c41\u0c26\u0c3f\u0c24\u0c3e \u0c2d\u0c35\u0c28\u0c4d\u0c24\u0c3f\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c68\u0c69 \u0965", "tamil": "\u0bb8\u0bcd\u0ba8\u0bbe\u0ba8\u0bcb\u0ba4\u0b95\u0bc8\u0b83 \u0baa\u0bb0\u0bbf\u0bae\u0bb2\u0bcb\u0baa\u0bae\u0bb6\u0bc0\u0ba4\u0ba4\u0bcb\u0baf\u0bc8\u0b83\n\u0bb8\u0bae\u0bcd\u0bb8\u0bcd\u0ba4\u0bbe\u0baa\u0bbf\u0ba4\u0bc8\u0bb0\u0bb9\u0bbf\u0b95\u0bc1\u0bb2\u0bc7\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bb8\u0bc1\u0bb0\u0bc8\u0bb0\u0bcd\u0bb5\u0bbf\u0bae\u0bbf\u0bb6\u0bcd\u0bb0\u0bc8\u0b83 \u0964\n\u0b85\u0baa\u0bbf\u0bb7\u0bc7\u0b9a\u0ba8\u0bbe\u0baf \u0baa\u0bb5\u0ba4\u0bcb \u0bae\u0bc1\u0ba4\u0bbf\u0ba4\u0bbe \u0baa\u0bb5\u0ba8\u0bcd\u0ba4\u0bbf\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be8\u0be9 \u0965", "kannada": "\u0cb8\u0ccd\u0ca8\u0cbe\u0ca8\u0ccb\u0ca6\u0c95\u0cc8\u0c83 \u0caa\u0cb0\u0cbf\u0cae\u0cb2\u0ccb\u0caa\u0cae\u0cb6\u0cc0\u0ca4\u0ca4\u0ccb\u0caf\u0cc8\u0c83\n\u0cb8\u0c82\u0cb8\u0ccd\u0ca5\u0cbe\u0caa\u0cbf\u0ca4\u0cc8\u0cb0\u0cb9\u0cbf\u0c95\u0cc1\u0cb2\u0cc7\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0cb8\u0cc1\u0cb0\u0cc8\u0cb0\u0ccd\u0cb5\u0cbf\u0cae\u0cbf\u0cb6\u0ccd\u0cb0\u0cc8\u0c83 \u0964\n\u0c85\u0cad\u0cbf\u0cb7\u0cc7\u0c9a\u0ca8\u0cbe\u0caf \u0cad\u0cb5\u0ca4\u0ccb \u0cae\u0cc1\u0ca6\u0cbf\u0ca4\u0cbe \u0cad\u0cb5\u0ca8\u0ccd\u0ca4\u0cbf\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce8\u0ce9 \u0965", "malayalam": "\u0d38\u0d4d\u0d28\u0d3e\u0d28\u0d4b\u0d26\u0d15\u0d48\u0d03 \u0d2a\u0d30\u0d3f\u0d2e\u0d32\u0d4b\u0d2a\u0d2e\u0d36\u0d40\u0d24\u0d24\u0d4b\u0d2f\u0d48\u0d03\n\u0d38\u0d02\u0d38\u0d4d\u0d25\u0d3e\u0d2a\u0d3f\u0d24\u0d48\u0d30\u0d39\u0d3f\u0d15\u0d41\u0d32\u0d47\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d38\u0d41\u0d30\u0d48\u0d30\u0d4d\u0d35\u0d3f\u0d2e\u0d3f\u0d36\u0d4d\u0d30\u0d48\u0d03 \u0964\n\u0d05\u0d2d\u0d3f\u0d37\u0d47\u0d1a\u0d28\u0d3e\u0d2f \u0d2d\u0d35\u0d24\u0d4b \u0d2e\u0d41\u0d26\u0d3f\u0d24\u0d3e \u0d2d\u0d35\u0d28\u0d4d\u0d24\u0d3f\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d68\u0d69 \u0965", "iast": "sn\u0101nodakai\u1e25 parimalopama\u015b\u012btatoyai\u1e25\nsa\u1e43sth\u0101pitairahikulendrasurairvimi\u015brai\u1e25 |\nabhi\u1e63ecan\u0101ya bhavato mudit\u0101 bhavanti\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 23 ||"},
        draftTranslation: "Golden pots filled with fragrant cool holy waters stand ready for Your sacred ceremonial bath (Abhisheka), brought joyously by priests and devotees, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 24,
        devanagariText: "\u091b\u0924\u094d\u0930\u091a\u093e\u092e\u0930\u0935\u0930\u0948\u0930\u092d\u093f\u0936\u094b\u092d\u092e\u093e\u0928\u093e\u0903\n\u092a\u093e\u0926\u093e\u0930\u0935\u093f\u0928\u094d\u0926\u092f\u0941\u0917\u0932\u092a\u094d\u0930\u0923\u0924\u093e\u0903 \u0938\u092e\u0928\u094d\u0924\u093e\u0924\u094d \u0964\n\u0938\u0942\u0930\u094d\u092f\u0947\u0928\u094d\u0926\u0941\u0935\u0939\u094d\u0928\u093f\u0928\u092f\u0928\u0938\u094d\u092f \u0935\u093f\u092d\u094b\u0903 \u092a\u094d\u0930\u092a\u0928\u094d\u0928\u093e\u0903\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0968\u096a \u0965",
        iastText: "chatrac\u0101maravarairabhi\u015b\u014dbham\u0101n\u0101\u1e25\np\u0101d\u0101ravindayugalapra\u1e47at\u0101\u1e25 samant\u0101t \u0964\ns\u016bry\u0113nduvahninayanasya vibh\u014d\u1e25 prapann\u0101\u1e25\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 24 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c1b\u0c24\u0c4d\u0c30\u0c1a\u0c3e\u0c2e\u0c30\u0c35\u0c30\u0c48\u0c30\u0c2d\u0c3f\u0c36\u0c4b\u0c2d\u0c2e\u0c3e\u0c28\u0c3e\u0c03\n\u0c2a\u0c3e\u0c26\u0c3e\u0c30\u0c35\u0c3f\u0c28\u0c4d\u0c26\u0c2f\u0c41\u0c17\u0c32\u0c2a\u0c4d\u0c30\u0c23\u0c24\u0c3e\u0c03 \u0c38\u0c2e\u0c28\u0c4d\u0c24\u0c3e\u0c24\u0c4d \u0964\n\u0c38\u0c42\u0c30\u0c4d\u0c2f\u0c47\u0c28\u0c4d\u0c26\u0c41\u0c35\u0c39\u0c4d\u0c28\u0c3f\u0c28\u0c2f\u0c28\u0c38\u0c4d\u0c2f \u0c35\u0c3f\u0c2d\u0c4b\u0c03 \u0c2a\u0c4d\u0c30\u0c2a\u0c28\u0c4d\u0c28\u0c3e\u0c03\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c68\u0c6a \u0965", "tamil": "\u0b9a\u0ba4\u0bcd\u0bb0\u0b9a\u0bbe\u0bae\u0bb0\u0bb5\u0bb0\u0bc8\u0bb0\u0baa\u0bbf\u0bb6\u0bcb\u0baa\u0bae\u0bbe\u0ba8\u0bbe\u0b83\n\u0baa\u0bbe\u0ba4\u0bbe\u0bb0\u0bb5\u0bbf\u0ba8\u0bcd\u0ba4\u0baf\u0bc1\u0b95\u0bb2\u0baa\u0bcd\u0bb0\u0ba3\u0ba4\u0bbe\u0b83 \u0bb8\u0bae\u0ba8\u0bcd\u0ba4\u0bbe\u0ba4\u0bcd \u0964\n\u0bb8\u0bc2\u0bb0\u0bcd\u0baf\u0bc7\u0ba8\u0bcd\u0ba4\u0bc1\u0bb5\u0bb9\u0bcd\u0ba8\u0bbf\u0ba8\u0baf\u0ba8\u0bb8\u0bcd\u0baf \u0bb5\u0bbf\u0baa\u0bcb\u0b83 \u0baa\u0bcd\u0bb0\u0baa\u0ba8\u0bcd\u0ba8\u0bbe\u0b83\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be8\u0bea \u0965", "kannada": "\u0c9b\u0ca4\u0ccd\u0cb0\u0c9a\u0cbe\u0cae\u0cb0\u0cb5\u0cb0\u0cc8\u0cb0\u0cad\u0cbf\u0cb6\u0ccb\u0cad\u0cae\u0cbe\u0ca8\u0cbe\u0c83\n\u0caa\u0cbe\u0ca6\u0cbe\u0cb0\u0cb5\u0cbf\u0ca8\u0ccd\u0ca6\u0caf\u0cc1\u0c97\u0cb2\u0caa\u0ccd\u0cb0\u0ca3\u0ca4\u0cbe\u0c83 \u0cb8\u0cae\u0ca8\u0ccd\u0ca4\u0cbe\u0ca4\u0ccd \u0964\n\u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0cc7\u0ca8\u0ccd\u0ca6\u0cc1\u0cb5\u0cb9\u0ccd\u0ca8\u0cbf\u0ca8\u0caf\u0ca8\u0cb8\u0ccd\u0caf \u0cb5\u0cbf\u0cad\u0ccb\u0c83 \u0caa\u0ccd\u0cb0\u0caa\u0ca8\u0ccd\u0ca8\u0cbe\u0c83\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce8\u0cea \u0965", "malayalam": "\u0d1b\u0d24\u0d4d\u0d30\u0d1a\u0d3e\u0d2e\u0d30\u0d35\u0d30\u0d48\u0d30\u0d2d\u0d3f\u0d36\u0d4b\u0d2d\u0d2e\u0d3e\u0d28\u0d3e\u0d03\n\u0d2a\u0d3e\u0d26\u0d3e\u0d30\u0d35\u0d3f\u0d28\u0d4d\u0d26\u0d2f\u0d41\u0d17\u0d32\u0d2a\u0d4d\u0d30\u0d23\u0d24\u0d3e\u0d03 \u0d38\u0d2e\u0d28\u0d4d\u0d24\u0d3e\u0d24\u0d4d \u0964\n\u0d38\u0d42\u0d30\u0d4d\u0d2f\u0d47\u0d28\u0d4d\u0d26\u0d41\u0d35\u0d39\u0d4d\u0d28\u0d3f\u0d28\u0d2f\u0d28\u0d38\u0d4d\u0d2f \u0d35\u0d3f\u0d2d\u0d4b\u0d03 \u0d2a\u0d4d\u0d30\u0d2a\u0d28\u0d4d\u0d28\u0d3e\u0d03\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d68\u0d6a \u0965", "iast": "chatrac\u0101maravarairabhi\u015bobham\u0101n\u0101\u1e25\np\u0101d\u0101ravindayugalapra\u1e47at\u0101\u1e25 samant\u0101t |\ns\u016bryenduvahninayanasya vibho\u1e25 prapann\u0101\u1e25\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 24 ||"},
        draftTranslation: "Bearing royal parasols and white whisk fans, devotees prostrate around Your pair of lotus feet, O Lord whose eyes are the Sun, Moon, and Fire! O Lord of Venkatachala, may auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 25,
        devanagariText: "\u0935\u0930\u0926\u093e\u092d\u092f\u092e\u0941\u0926\u094d\u0930\u093e\u092f\u0941\u0915\u094d\u0924\u0915\u0930\u093e\u091e\u094d\u091a\u093f\u0924\u0926\u093f\u0935\u094d\u092f\u092e\u0942\u0930\u094d\u0924\u0947\n\u0938\u0930\u094d\u0935\u091c\u094d\u091e \u0938\u0930\u094d\u0935\u0935\u0930\u0926 \u092a\u094d\u0930\u0925\u093f\u0924\u092a\u094d\u0930\u0924\u093e\u092a \u0964\n\u0906\u0936\u094d\u0930\u093f\u0924\u094d\u092f \u092a\u093e\u0926\u092f\u0941\u0917\u0932\u0902 \u0915\u0943\u0924\u0915\u0943\u0924\u094d\u092f\u092d\u093e\u091c\u093e\u0902\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0968\u096b \u0965",
        iastText: "varad\u0101bhayamudr\u0101yuktakar\u0101\u00f1citadivyam\u016brt\u0113\nsarvaj\u00f1a sarvavarada prathitaprat\u0101pa \u0964\n\u0101\u015britya p\u0101dayugala\u1e41 k\u1e5btak\u1e5btyabh\u0101j\u0101\u1e41\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 25 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c35\u0c30\u0c26\u0c3e\u0c2d\u0c2f\u0c2e\u0c41\u0c26\u0c4d\u0c30\u0c3e\u0c2f\u0c41\u0c15\u0c4d\u0c24\u0c15\u0c30\u0c3e\u0c1e\u0c4d\u0c1a\u0c3f\u0c24\u0c26\u0c3f\u0c35\u0c4d\u0c2f\u0c2e\u0c42\u0c30\u0c4d\u0c24\u0c47\n\u0c38\u0c30\u0c4d\u0c35\u0c1c\u0c4d\u0c1e \u0c38\u0c30\u0c4d\u0c35\u0c35\u0c30\u0c26 \u0c2a\u0c4d\u0c30\u0c25\u0c3f\u0c24\u0c2a\u0c4d\u0c30\u0c24\u0c3e\u0c2a \u0964\n\u0c06\u0c36\u0c4d\u0c30\u0c3f\u0c24\u0c4d\u0c2f \u0c2a\u0c3e\u0c26\u0c2f\u0c41\u0c17\u0c32\u0c02 \u0c15\u0c43\u0c24\u0c15\u0c43\u0c24\u0c4d\u0c2f\u0c2d\u0c3e\u0c1c\u0c3e\u0c02\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c68\u0c6b \u0965", "tamil": "\u0bb5\u0bb0\u0ba4\u0bbe\u0baa\u0baf\u0bae\u0bc1\u0ba4\u0bcd\u0bb0\u0bbe\u0baf\u0bc1\u0b95\u0bcd\u0ba4\u0b95\u0bb0\u0bbe\u0b9e\u0bcd\u0b9a\u0bbf\u0ba4\u0ba4\u0bbf\u0bb5\u0bcd\u0baf\u0bae\u0bc2\u0bb0\u0bcd\u0ba4\u0bc7\n\u0bb8\u0bb0\u0bcd\u0bb5\u0b9c\u0bcd\u0b9e \u0bb8\u0bb0\u0bcd\u0bb5\u0bb5\u0bb0\u0ba4 \u0baa\u0bcd\u0bb0\u0ba4\u0bbf\u0ba4\u0baa\u0bcd\u0bb0\u0ba4\u0bbe\u0baa \u0964\n\u0b86\u0bb6\u0bcd\u0bb0\u0bbf\u0ba4\u0bcd\u0baf \u0baa\u0bbe\u0ba4\u0baf\u0bc1\u0b95\u0bb2\u0bae\u0bcd \u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0bcd\u0baf\u0baa\u0bbe\u0b9c\u0bbe\u0bae\u0bcd\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be8\u0beb \u0965", "kannada": "\u0cb5\u0cb0\u0ca6\u0cbe\u0cad\u0caf\u0cae\u0cc1\u0ca6\u0ccd\u0cb0\u0cbe\u0caf\u0cc1\u0c95\u0ccd\u0ca4\u0c95\u0cb0\u0cbe\u0c9e\u0ccd\u0c9a\u0cbf\u0ca4\u0ca6\u0cbf\u0cb5\u0ccd\u0caf\u0cae\u0cc2\u0cb0\u0ccd\u0ca4\u0cc7\n\u0cb8\u0cb0\u0ccd\u0cb5\u0c9c\u0ccd\u0c9e \u0cb8\u0cb0\u0ccd\u0cb5\u0cb5\u0cb0\u0ca6 \u0caa\u0ccd\u0cb0\u0ca5\u0cbf\u0ca4\u0caa\u0ccd\u0cb0\u0ca4\u0cbe\u0caa \u0964\n\u0c86\u0cb6\u0ccd\u0cb0\u0cbf\u0ca4\u0ccd\u0caf \u0caa\u0cbe\u0ca6\u0caf\u0cc1\u0c97\u0cb2\u0c82 \u0c95\u0cc3\u0ca4\u0c95\u0cc3\u0ca4\u0ccd\u0caf\u0cad\u0cbe\u0c9c\u0cbe\u0c82\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce8\u0ceb \u0965", "malayalam": "\u0d35\u0d30\u0d26\u0d3e\u0d2d\u0d2f\u0d2e\u0d41\u0d26\u0d4d\u0d30\u0d3e\u0d2f\u0d41\u0d15\u0d4d\u0d24\u0d15\u0d30\u0d3e\u0d1e\u0d4d\u0d1a\u0d3f\u0d24\u0d26\u0d3f\u0d35\u0d4d\u0d2f\u0d2e\u0d42\u0d30\u0d4d\u0d24\u0d47\n\u0d38\u0d30\u0d4d\u0d35\u0d1c\u0d4d\u0d1e \u0d38\u0d30\u0d4d\u0d35\u0d35\u0d30\u0d26 \u0d2a\u0d4d\u0d30\u0d25\u0d3f\u0d24\u0d2a\u0d4d\u0d30\u0d24\u0d3e\u0d2a \u0964\n\u0d06\u0d36\u0d4d\u0d30\u0d3f\u0d24\u0d4d\u0d2f \u0d2a\u0d3e\u0d26\u0d2f\u0d41\u0d17\u0d32\u0d02 \u0d15\u0d43\u0d24\u0d15\u0d43\u0d24\u0d4d\u0d2f\u0d2d\u0d3e\u0d1c\u0d3e\u0d02\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d68\u0d6b \u0965", "iast": "varad\u0101bhayamudr\u0101yuktakar\u0101\u00f1citadivyam\u016brte\nsarvaj\u00f1a sarvavarada prathitaprat\u0101pa |\n\u0101\u015britya p\u0101dayugala\u1e43 k\u1e5btak\u1e5btyabh\u0101j\u0101\u1e43\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 25 ||"},
        draftTranslation: "Endowed with hands gracefully showing the Varada (boon-giving) and Abhaya (fear-dispelling) mudras, O omniscient granter of all blessings, whose lotus feet crown every endeavor, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 26,
        devanagariText: "\u0930\u093e\u092e\u093e\u0928\u0941\u091c\u092a\u094d\u0930\u092e\u0941\u0916\u0938\u0930\u094d\u0935\u092e\u0939\u093e\u092f\u0924\u0940\u0928\u094d\u0926\u094d\u0930\u0948\u0903\n\u0938\u0902\u0938\u0947\u0935\u094d\u092f\u092e\u093e\u0928\u092a\u0926\u092a\u0919\u094d\u0915\u091c\u092a\u093e\u0935\u0928\u093e\u0930\u094d\u0939 \u0964\n\u0938\u0902\u0938\u093e\u0930\u092a\u093e\u0930\u0924\u0930\u0923\u0948\u0915\u0938\u0941\u092a\u094b\u0924\u092d\u0942\u0924\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0968\u096c \u0965",
        iastText: "r\u0101m\u0101nujapramukhasarvamah\u0101yat\u012bndrai\u1e25\nsa\u1e41s\u0113vyam\u0101napadapa\u1e45kajap\u0101van\u0101rha \u0964\nsa\u1e41s\u0101rap\u0101ratara\u1e47aikasup\u014dtabh\u016bta\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 26 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c30\u0c3e\u0c2e\u0c3e\u0c28\u0c41\u0c1c\u0c2a\u0c4d\u0c30\u0c2e\u0c41\u0c16\u0c38\u0c30\u0c4d\u0c35\u0c2e\u0c39\u0c3e\u0c2f\u0c24\u0c40\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c48\u0c03\n\u0c38\u0c02\u0c38\u0c47\u0c35\u0c4d\u0c2f\u0c2e\u0c3e\u0c28\u0c2a\u0c26\u0c2a\u0c19\u0c4d\u0c15\u0c1c\u0c2a\u0c3e\u0c35\u0c28\u0c3e\u0c30\u0c4d\u0c39 \u0964\n\u0c38\u0c02\u0c38\u0c3e\u0c30\u0c2a\u0c3e\u0c30\u0c24\u0c30\u0c23\u0c48\u0c15\u0c38\u0c41\u0c2a\u0c4b\u0c24\u0c2d\u0c42\u0c24\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c68\u0c6c \u0965", "tamil": "\u0bb0\u0bbe\u0bae\u0bbe\u0ba8\u0bc1\u0b9c\u0baa\u0bcd\u0bb0\u0bae\u0bc1\u0b95\u0bb8\u0bb0\u0bcd\u0bb5\u0bae\u0bb9\u0bbe\u0baf\u0ba4\u0bc0\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bc8\u0b83\n\u0bb8\u0bae\u0bcd\u0bb8\u0bc7\u0bb5\u0bcd\u0baf\u0bae\u0bbe\u0ba8\u0baa\u0ba4\u0baa\u0b99\u0bcd\u0b95\u0b9c\u0baa\u0bbe\u0bb5\u0ba8\u0bbe\u0bb0\u0bcd\u0bb9 \u0964\n\u0bb8\u0bae\u0bcd\u0bb8\u0bbe\u0bb0\u0baa\u0bbe\u0bb0\u0ba4\u0bb0\u0ba3\u0bc8\u0b95\u0bb8\u0bc1\u0baa\u0bcb\u0ba4\u0baa\u0bc2\u0ba4\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be8\u0bec \u0965", "kannada": "\u0cb0\u0cbe\u0cae\u0cbe\u0ca8\u0cc1\u0c9c\u0caa\u0ccd\u0cb0\u0cae\u0cc1\u0c96\u0cb8\u0cb0\u0ccd\u0cb5\u0cae\u0cb9\u0cbe\u0caf\u0ca4\u0cc0\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0cc8\u0c83\n\u0cb8\u0c82\u0cb8\u0cc7\u0cb5\u0ccd\u0caf\u0cae\u0cbe\u0ca8\u0caa\u0ca6\u0caa\u0c99\u0ccd\u0c95\u0c9c\u0caa\u0cbe\u0cb5\u0ca8\u0cbe\u0cb0\u0ccd\u0cb9 \u0964\n\u0cb8\u0c82\u0cb8\u0cbe\u0cb0\u0caa\u0cbe\u0cb0\u0ca4\u0cb0\u0ca3\u0cc8\u0c95\u0cb8\u0cc1\u0caa\u0ccb\u0ca4\u0cad\u0cc2\u0ca4\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce8\u0cec \u0965", "malayalam": "\u0d30\u0d3e\u0d2e\u0d3e\u0d28\u0d41\u0d1c\u0d2a\u0d4d\u0d30\u0d2e\u0d41\u0d16\u0d38\u0d30\u0d4d\u0d35\u0d2e\u0d39\u0d3e\u0d2f\u0d24\u0d40\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d48\u0d03\n\u0d38\u0d02\u0d38\u0d47\u0d35\u0d4d\u0d2f\u0d2e\u0d3e\u0d28\u0d2a\u0d26\u0d2a\u0d19\u0d4d\u0d15\u0d1c\u0d2a\u0d3e\u0d35\u0d28\u0d3e\u0d30\u0d4d\u0d39 \u0964\n\u0d38\u0d02\u0d38\u0d3e\u0d30\u0d2a\u0d3e\u0d30\u0d24\u0d30\u0d23\u0d48\u0d15\u0d38\u0d41\u0d2a\u0d4b\u0d24\u0d2d\u0d42\u0d24\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d68\u0d6c \u0965", "iast": "r\u0101m\u0101nujapramukhasarvamah\u0101yat\u012bndrai\u1e25\nsa\u1e43sevyam\u0101napadapa\u1e45kajap\u0101van\u0101rha |\nsa\u1e43s\u0101rap\u0101ratara\u1e47aikasupotabh\u016bta\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 26 ||"},
        draftTranslation: "Whose sacred lotus feet are cherished by eminent preceptors headed by Sri Ramanuja, the solitary unfailing boat across the ocean of worldly existence, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 27,
        devanagariText: "\u0926\u0947\u0935\u0926\u0941\u0930\u094d\u0932\u092d\u0938\u0941\u092a\u0941\u0923\u094d\u092f\u0915\u0925\u093e\u0928\u0941\u092d\u093e\u0935\u0948\u0903\n\u0932\u094b\u0915\u093e\u0928\u094d\u092a\u0941\u0928\u093e\u0928 \u092a\u0930\u092e\u094b\u0924\u094d\u0924\u092e\u0915\u0940\u0930\u094d\u0924\u093f\u092d\u093e\u091c\u093e \u0964\n\u0936\u094d\u0930\u0940\u0936\u0948\u0932\u0936\u0947\u0916\u0930\u092e\u0939\u093e\u0930\u0925\u0935\u093e\u0939\u0928\u093e\u0922\u094d\u092f\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0968\u096d \u0965",
        iastText: "d\u0113vadurlabhasupu\u1e47yakath\u0101nubh\u0101vai\u1e25\nl\u014dk\u0101npun\u0101na param\u014dttamak\u012brtibh\u0101j\u0101 \u0964\n\u015br\u012b\u015baila\u015b\u0113kharamah\u0101rathav\u0101han\u0101\u1e0dhya\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 27 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c26\u0c47\u0c35\u0c26\u0c41\u0c30\u0c4d\u0c32\u0c2d\u0c38\u0c41\u0c2a\u0c41\u0c23\u0c4d\u0c2f\u0c15\u0c25\u0c3e\u0c28\u0c41\u0c2d\u0c3e\u0c35\u0c48\u0c03\n\u0c32\u0c4b\u0c15\u0c3e\u0c28\u0c4d\u0c2a\u0c41\u0c28\u0c3e\u0c28 \u0c2a\u0c30\u0c2e\u0c4b\u0c24\u0c4d\u0c24\u0c2e\u0c15\u0c40\u0c30\u0c4d\u0c24\u0c3f\u0c2d\u0c3e\u0c1c\u0c3e \u0964\n\u0c36\u0c4d\u0c30\u0c40\u0c36\u0c48\u0c32\u0c36\u0c47\u0c16\u0c30\u0c2e\u0c39\u0c3e\u0c30\u0c25\u0c35\u0c3e\u0c39\u0c28\u0c3e\u0c22\u0c4d\u0c2f\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c68\u0c6d \u0965", "tamil": "\u0ba4\u0bc7\u0bb5\u0ba4\u0bc1\u0bb0\u0bcd\u0bb2\u0baa\u0bb8\u0bc1\u0baa\u0bc1\u0ba3\u0bcd\u0baf\u0b95\u0ba4\u0bbe\u0ba8\u0bc1\u0baa\u0bbe\u0bb5\u0bc8\u0b83\n\u0bb2\u0bcb\u0b95\u0bbe\u0ba8\u0bcd\u0baa\u0bc1\u0ba8\u0bbe\u0ba8 \u0baa\u0bb0\u0bae\u0bcb\u0ba4\u0bcd\u0ba4\u0bae\u0b95\u0bc0\u0bb0\u0bcd\u0ba4\u0bbf\u0baa\u0bbe\u0b9c\u0bbe \u0964\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb6\u0bc8\u0bb2\u0bb6\u0bc7\u0b95\u0bb0\u0bae\u0bb9\u0bbe\u0bb0\u0ba4\u0bb5\u0bbe\u0bb9\u0ba8\u0bbe\u0b9f\u0bcd\u0baf\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be8\u0bed \u0965", "kannada": "\u0ca6\u0cc7\u0cb5\u0ca6\u0cc1\u0cb0\u0ccd\u0cb2\u0cad\u0cb8\u0cc1\u0caa\u0cc1\u0ca3\u0ccd\u0caf\u0c95\u0ca5\u0cbe\u0ca8\u0cc1\u0cad\u0cbe\u0cb5\u0cc8\u0c83\n\u0cb2\u0ccb\u0c95\u0cbe\u0ca8\u0ccd\u0caa\u0cc1\u0ca8\u0cbe\u0ca8 \u0caa\u0cb0\u0cae\u0ccb\u0ca4\u0ccd\u0ca4\u0cae\u0c95\u0cc0\u0cb0\u0ccd\u0ca4\u0cbf\u0cad\u0cbe\u0c9c\u0cbe \u0964\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb6\u0cc8\u0cb2\u0cb6\u0cc7\u0c96\u0cb0\u0cae\u0cb9\u0cbe\u0cb0\u0ca5\u0cb5\u0cbe\u0cb9\u0ca8\u0cbe\u0ca2\u0ccd\u0caf\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce8\u0ced \u0965", "malayalam": "\u0d26\u0d47\u0d35\u0d26\u0d41\u0d30\u0d4d\u0d32\u0d2d\u0d38\u0d41\u0d2a\u0d41\u0d23\u0d4d\u0d2f\u0d15\u0d25\u0d3e\u0d28\u0d41\u0d2d\u0d3e\u0d35\u0d48\u0d03\n\u0d32\u0d4b\u0d15\u0d3e\u0d28\u0d4d\u0d2a\u0d41\u0d28\u0d3e\u0d28 \u0d2a\u0d30\u0d2e\u0d4b\u0d24\u0d4d\u0d24\u0d2e\u0d15\u0d40\u0d30\u0d4d\u0d24\u0d3f\u0d2d\u0d3e\u0d1c\u0d3e \u0964\n\u0d36\u0d4d\u0d30\u0d40\u0d36\u0d48\u0d32\u0d36\u0d47\u0d16\u0d30\u0d2e\u0d39\u0d3e\u0d30\u0d25\u0d35\u0d3e\u0d39\u0d28\u0d3e\u0d22\u0d4d\u0d2f\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d68\u0d6d \u0965", "iast": "devadurlabhasupu\u1e47yakath\u0101nubh\u0101vai\u1e25\nlok\u0101npun\u0101na paramottamak\u012brtibh\u0101j\u0101 |\n\u015br\u012b\u015baila\u015bekharamah\u0101rathav\u0101han\u0101\u1e0dhya\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 27 ||"},
        draftTranslation: "Purifying all worlds through the divine glory of Your pastimes celebrated even among the celestials, crowned upon the crest of Venkatadri, O Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 28,
        devanagariText: "\u0936\u094d\u0930\u0940\u092e\u0924\u094d\u0915\u094d\u0930\u093f\u092f\u093e\u0938\u092e\u0941\u0926\u093f\u0924\u0948\u0930\u0939\u0930\u0939\u0903 \u092a\u094d\u0930\u0935\u0943\u0924\u094d\u0924\u0948\u0903\n\u092a\u0941\u0923\u094d\u092f\u093e\u0939\u0935\u093e\u091a\u0928\u092a\u0941\u0930\u0938\u094d\u0938\u0930\u0935\u0947\u0926\u0918\u094b\u0937\u0948\u0903 \u0964\n\u0909\u0926\u094d\u0918\u094b\u0937\u093f\u0924\u093e\u0924\u094d\u092e\u0935\u093f\u092d\u0935\u093e\u092f \u092e\u0941\u0926\u093e\u0928\u094d\u0935\u093f\u0924\u093e\u092f\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u091a\u0932\u092a\u0924\u0947 \u0924\u0935 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u092e\u094d \u0965 \u0968\u096e \u0965",
        iastText: "\u015br\u012bmatkriy\u0101samuditairaharahprav\u1e5bttai\u1e25\npu\u1e47y\u0101hav\u0101canapurassarav\u0113dagh\u014d\u1e63ai\u1e25 \u0964\nudgh\u014d\u1e63it\u0101tmavibhav\u0101ya mud\u0101nvit\u0101ya\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapat\u0113 tava suprabh\u0101tam \u0965 28 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c36\u0c4d\u0c30\u0c40\u0c2e\u0c24\u0c4d\u0c15\u0c4d\u0c30\u0c3f\u0c2f\u0c3e\u0c38\u0c2e\u0c41\u0c26\u0c3f\u0c24\u0c48\u0c30\u0c39\u0c30\u0c39\u0c03 \u0c2a\u0c4d\u0c30\u0c35\u0c43\u0c24\u0c4d\u0c24\u0c48\u0c03\n\u0c2a\u0c41\u0c23\u0c4d\u0c2f\u0c3e\u0c39\u0c35\u0c3e\u0c1a\u0c28\u0c2a\u0c41\u0c30\u0c38\u0c4d\u0c38\u0c30\u0c35\u0c47\u0c26\u0c18\u0c4b\u0c37\u0c48\u0c03 \u0964\n\u0c09\u0c26\u0c4d\u0c18\u0c4b\u0c37\u0c3f\u0c24\u0c3e\u0c24\u0c4d\u0c2e\u0c35\u0c3f\u0c2d\u0c35\u0c3e\u0c2f \u0c2e\u0c41\u0c26\u0c3e\u0c28\u0c4d\u0c35\u0c3f\u0c24\u0c3e\u0c2f\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47 \u0c24\u0c35 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c2e\u0c4d \u0965 \u0c68\u0c6e \u0965", "tamil": "\u0bb6\u0bcd\u0bb0\u0bc0\u0bae\u0ba4\u0bcd\u0b95\u0bcd\u0bb0\u0bbf\u0baf\u0bbe\u0bb8\u0bae\u0bc1\u0ba4\u0bbf\u0ba4\u0bc8\u0bb0\u0bb9\u0bb0\u0bb9\u0b83 \u0baa\u0bcd\u0bb0\u0bb5\u0bcd\u0bb0\u0bc1'\u0ba4\u0bcd\u0ba4\u0bc8\u0b83\n\u0baa\u0bc1\u0ba3\u0bcd\u0baf\u0bbe\u0bb9\u0bb5\u0bbe\u0b9a\u0ba8\u0baa\u0bc1\u0bb0\u0bb8\u0bcd\u0bb8\u0bb0\u0bb5\u0bc7\u0ba4\u0b95\u0bcb\u0bb7\u0bc8\u0b83 \u0964\n\u0b89\u0ba4\u0bcd\u0b95\u0bcb\u0bb7\u0bbf\u0ba4\u0bbe\u0ba4\u0bcd\u0bae\u0bb5\u0bbf\u0baa\u0bb5\u0bbe\u0baf \u0bae\u0bc1\u0ba4\u0bbe\u0ba8\u0bcd\u0bb5\u0bbf\u0ba4\u0bbe\u0baf\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7 \u0ba4\u0bb5 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0965 \u0be8\u0bee \u0965", "kannada": "\u0cb6\u0ccd\u0cb0\u0cc0\u0cae\u0ca4\u0ccd\u0c95\u0ccd\u0cb0\u0cbf\u0caf\u0cbe\u0cb8\u0cae\u0cc1\u0ca6\u0cbf\u0ca4\u0cc8\u0cb0\u0cb9\u0cb0\u0cb9\u0c83 \u0caa\u0ccd\u0cb0\u0cb5\u0cc3\u0ca4\u0ccd\u0ca4\u0cc8\u0c83\n\u0caa\u0cc1\u0ca3\u0ccd\u0caf\u0cbe\u0cb9\u0cb5\u0cbe\u0c9a\u0ca8\u0caa\u0cc1\u0cb0\u0cb8\u0ccd\u0cb8\u0cb0\u0cb5\u0cc7\u0ca6\u0c98\u0ccb\u0cb7\u0cc8\u0c83 \u0964\n\u0c89\u0ca6\u0ccd\u0c98\u0ccb\u0cb7\u0cbf\u0ca4\u0cbe\u0ca4\u0ccd\u0cae\u0cb5\u0cbf\u0cad\u0cb5\u0cbe\u0caf \u0cae\u0cc1\u0ca6\u0cbe\u0ca8\u0ccd\u0cb5\u0cbf\u0ca4\u0cbe\u0caf\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7 \u0ca4\u0cb5 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cae\u0ccd \u0965 \u0ce8\u0cee \u0965", "malayalam": "\u0d36\u0d4d\u0d30\u0d40\u0d2e\u0d24\u0d4d\u0d15\u0d4d\u0d30\u0d3f\u0d2f\u0d3e\u0d38\u0d2e\u0d41\u0d26\u0d3f\u0d24\u0d48\u0d30\u0d39\u0d30\u0d39\u0d03 \u0d2a\u0d4d\u0d30\u0d35\u0d43\u0d24\u0d4d\u0d24\u0d48\u0d03\n\u0d2a\u0d41\u0d23\u0d4d\u0d2f\u0d3e\u0d39\u0d35\u0d3e\u0d1a\u0d28\u0d2a\u0d41\u0d30\u0d38\u0d4d\u0d38\u0d30\u0d35\u0d47\u0d26\u0d18\u0d4b\u0d37\u0d48\u0d03 \u0964\n\u0d09\u0d26\u0d4d\u0d18\u0d4b\u0d37\u0d3f\u0d24\u0d3e\u0d24\u0d4d\u0d2e\u0d35\u0d3f\u0d2d\u0d35\u0d3e\u0d2f \u0d2e\u0d41\u0d26\u0d3e\u0d28\u0d4d\u0d35\u0d3f\u0d24\u0d3e\u0d2f\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47 \u0d24\u0d35 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d2e\u0d4d \u0965 \u0d68\u0d6e \u0965", "iast": "\u015br\u012bmatkriy\u0101samuditairaharaha\u1e25 prav\u1e5bttai\u1e25\npu\u1e47y\u0101hav\u0101canapurassaravedagho\u1e63ai\u1e25 |\nudgho\u1e63it\u0101tmavibhav\u0101ya mud\u0101nvit\u0101ya\n\u015br\u012bve\u1e45ka\u1e6d\u0101calapate tava suprabh\u0101tam || 28 ||"},
        draftTranslation: "Amid resonant Vedic chants and auspicious invocations resounding daily in rituals performed with profound joy, O glorious Lord of Venkatachala! May auspicious dawn greet You!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 29,
        devanagariText: "\u0907\u0924\u094d\u0925\u0902 \u0935\u0943\u0937\u093e\u091a\u0932\u092a\u0924\u0947\u0930\u093f\u0939 \u0938\u0941\u092a\u094d\u0930\u092d\u093e\u0924\u0902\n\u092f\u0947 \u092e\u093e\u0928\u0935\u093e\u0903 \u092a\u094d\u0930\u0924\u093f\u0926\u093f\u0928\u0902 \u092a\u0920\u093f\u0924\u0941\u0902 \u092a\u094d\u0930\u0935\u0943\u0924\u094d\u0924\u093e\u0903 \u0964\n\u0924\u0947\u0937\u093e\u0902 \u092a\u094d\u0930\u092d\u093e\u0924\u0938\u092e\u092f\u0947 \u0938\u094d\u092e\u0943\u0924\u093f\u0915\u0930\u094d\u0924\u0943\u092d\u093e\u091c\u093e\u0902\n\u092a\u094d\u0930\u091c\u094d\u091e\u093e\u0902 \u092a\u0930\u093e\u0902 \u091a \u092a\u0930\u092e\u093e\u0902 \u0936\u094d\u0930\u093f\u092f\u092e\u093f\u0928\u094d\u0926\u0941\u0930\u0941\u091a\u093f\u0902 \u092a\u094d\u0930\u092f\u091a\u094d\u091b \u0965 \u0968\u096f \u0965",
        iastText: "ittha\u1e41 v\u1e5b\u1e63\u0101calapat\u0113riha suprabh\u0101ta\u1e41\ny\u0113 m\u0101nav\u0101\u1e25 pratidina\u1e41 pa\u1e6dhitu\u1e41 prav\u1e5btt\u0101\u1e25 \u0964\nt\u0113\u1e63\u0101\u1e41 prabh\u0101tasamay\u0113 sm\u1e5btikart\u1e5bbh\u0101j\u0101\u1e41\npraj\u00f1\u0101\u1e41 par\u0101\u1e41 ca param\u0101\u1e41 \u015briyaminduruci\u1e41 prayaccha \u0965 29 \u0965",
        meter: "Malini",
        transliterations: {"telugu": "\u0c07\u0c24\u0c4d\u0c25\u0c02 \u0c35\u0c43\u0c37\u0c3e\u0c1a\u0c32\u0c2a\u0c24\u0c47\u0c30\u0c3f\u0c39 \u0c38\u0c41\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c02\n\u0c2f\u0c47 \u0c2e\u0c3e\u0c28\u0c35\u0c3e\u0c03 \u0c2a\u0c4d\u0c30\u0c24\u0c3f\u0c26\u0c3f\u0c28\u0c02 \u0c2a\u0c20\u0c3f\u0c24\u0c41\u0c02 \u0c2a\u0c4d\u0c30\u0c35\u0c43\u0c24\u0c4d\u0c24\u0c3e\u0c03 \u0964\n\u0c24\u0c47\u0c37\u0c3e\u0c02 \u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c24\u0c38\u0c2e\u0c2f\u0c47 \u0c38\u0c4d\u0c2e\u0c43\u0c24\u0c3f\u0c15\u0c30\u0c4d\u0c24\u0c43\u0c2d\u0c3e\u0c1c\u0c3e\u0c02\n\u0c2a\u0c4d\u0c30\u0c1c\u0c4d\u0c1e\u0c3e\u0c02 \u0c2a\u0c30\u0c3e\u0c02 \u0c1a \u0c2a\u0c30\u0c2e\u0c3e\u0c02 \u0c36\u0c4d\u0c30\u0c3f\u0c2f\u0c2e\u0c3f\u0c28\u0c4d\u0c26\u0c41\u0c30\u0c41\u0c1a\u0c3f\u0c02 \u0c2a\u0c4d\u0c30\u0c2f\u0c1a\u0c4d\u0c1b \u0965 \u0c68\u0c6f \u0965", "tamil": "\u0b87\u0ba4\u0bcd\u0ba4\u0bae\u0bcd \u0bb5\u0bcd\u0bb0\u0bc1'\u0bb7\u0bbe\u0b9a\u0bb2\u0baa\u0ba4\u0bc7\u0bb0\u0bbf\u0bb9 \u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bae\u0bcd\n\u0baf\u0bc7 \u0bae\u0bbe\u0ba8\u0bb5\u0bbe\u0b83 \u0baa\u0bcd\u0bb0\u0ba4\u0bbf\u0ba4\u0bbf\u0ba8\u0bae\u0bcd \u0baa\u0b9f\u0bbf\u0ba4\u0bc1\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0bb5\u0bcd\u0bb0\u0bc1'\u0ba4\u0bcd\u0ba4\u0bbe\u0b83 \u0964\n\u0ba4\u0bc7\u0bb7\u0bbe\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0ba4\u0bb8\u0bae\u0baf\u0bc7 \u0bb8\u0bcd\u0bae\u0bcd\u0bb0\u0bc1'\u0ba4\u0bbf\u0b95\u0bb0\u0bcd\u0ba4\u0bcd\u0bb0\u0bc1'\u0baa\u0bbe\u0b9c\u0bbe\u0bae\u0bcd\n\u0baa\u0bcd\u0bb0\u0b9c\u0bcd\u0b9e\u0bbe\u0bae\u0bcd \u0baa\u0bb0\u0bbe\u0bae\u0bcd \u0b9a \u0baa\u0bb0\u0bae\u0bbe\u0bae\u0bcd \u0bb6\u0bcd\u0bb0\u0bbf\u0baf\u0bae\u0bbf\u0ba8\u0bcd\u0ba4\u0bc1\u0bb0\u0bc1\u0b9a\u0bbf\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baf\u0b9a\u0bcd\u0b9a \u0965 \u0be8\u0bef \u0965", "kannada": "\u0c87\u0ca4\u0ccd\u0ca5\u0c82 \u0cb5\u0cc3\u0cb7\u0cbe\u0c9a\u0cb2\u0caa\u0ca4\u0cc7\u0cb0\u0cbf\u0cb9 \u0cb8\u0cc1\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0c82\n\u0caf\u0cc7 \u0cae\u0cbe\u0ca8\u0cb5\u0cbe\u0c83 \u0caa\u0ccd\u0cb0\u0ca4\u0cbf\u0ca6\u0cbf\u0ca8\u0c82 \u0caa\u0ca0\u0cbf\u0ca4\u0cc1\u0c82 \u0caa\u0ccd\u0cb0\u0cb5\u0cc3\u0ca4\u0ccd\u0ca4\u0cbe\u0c83 \u0964\n\u0ca4\u0cc7\u0cb7\u0cbe\u0c82 \u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0ca4\u0cb8\u0cae\u0caf\u0cc7 \u0cb8\u0ccd\u0cae\u0cc3\u0ca4\u0cbf\u0c95\u0cb0\u0ccd\u0ca4\u0cc3\u0cad\u0cbe\u0c9c\u0cbe\u0c82\n\u0caa\u0ccd\u0cb0\u0c9c\u0ccd\u0c9e\u0cbe\u0c82 \u0caa\u0cb0\u0cbe\u0c82 \u0c9a \u0caa\u0cb0\u0cae\u0cbe\u0c82 \u0cb6\u0ccd\u0cb0\u0cbf\u0caf\u0cae\u0cbf\u0ca8\u0ccd\u0ca6\u0cc1\u0cb0\u0cc1\u0c9a\u0cbf\u0c82 \u0caa\u0ccd\u0cb0\u0caf\u0c9a\u0ccd\u0c9b \u0965 \u0ce8\u0cef \u0965", "malayalam": "\u0d07\u0d24\u0d4d\u0d25\u0d02 \u0d35\u0d43\u0d37\u0d3e\u0d1a\u0d32\u0d2a\u0d24\u0d47\u0d30\u0d3f\u0d39 \u0d38\u0d41\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d02\n\u0d2f\u0d47 \u0d2e\u0d3e\u0d28\u0d35\u0d3e\u0d03 \u0d2a\u0d4d\u0d30\u0d24\u0d3f\u0d26\u0d3f\u0d28\u0d02 \u0d2a\u0d20\u0d3f\u0d24\u0d41\u0d02 \u0d2a\u0d4d\u0d30\u0d35\u0d43\u0d24\u0d4d\u0d24\u0d3e\u0d03 \u0964\n\u0d24\u0d47\u0d37\u0d3e\u0d02 \u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d38\u0d2e\u0d2f\u0d47 \u0d38\u0d4d\u0d2e\u0d43\u0d24\u0d3f\u0d15\u0d30\u0d4d\u0d24\u0d43\u0d2d\u0d3e\u0d1c\u0d3e\u0d02\n\u0d2a\u0d4d\u0d30\u0d1c\u0d4d\u0d1e\u0d3e\u0d02 \u0d2a\u0d30\u0d3e\u0d02 \u0d1a \u0d2a\u0d30\u0d2e\u0d3e\u0d02 \u0d36\u0d4d\u0d30\u0d3f\u0d2f\u0d2e\u0d3f\u0d28\u0d4d\u0d26\u0d41\u0d30\u0d41\u0d1a\u0d3f\u0d02 \u0d2a\u0d4d\u0d30\u0d2f\u0d1a\u0d4d\u0d1b \u0965 \u0d68\u0d6f \u0965", "iast": "ittha\u1e43 v\u1e5b\u1e63\u0101calapateriha suprabh\u0101ta\u1e43\nye m\u0101nav\u0101\u1e25 pratidina\u1e43 pa\u1e6dhitu\u1e43 prav\u1e5btt\u0101\u1e25 |\nte\u1e63\u0101\u1e43 prabh\u0101tasamaye sm\u1e5btikart\u1e5bbh\u0101j\u0101\u1e43\npraj\u00f1\u0101\u1e43 par\u0101\u1e43 ca param\u0101\u1e43 \u015briyaminduruci\u1e43 prayaccha || 29 ||"},
        draftTranslation: "Those who daily recite this morning hymn of the Lord of Vrishachala at dawn with devoted remembrance \u2014 to them may You bestow transcendent wisdom, supreme spiritual prosperity, and everlasting tranquility radiant as the moon!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 30,
        devanagariText: "\u0915\u092e\u0932\u093e\u0915\u0941\u091a\u091a\u0942\u091a\u0941\u0915\u0915\u0941\u0919\u094d\u0915\u0941\u092e\u0924\u094b \u0928\u093f\u092f\u0924\u093e\u0930\u0941\u0923\u093f\u0924\u093e\u0924\u0941\u0932\u0928\u0940\u0932\u0924\u0928\u094b \u0964\n\u0915\u092e\u0932\u093e\u092f\u0924\u0932\u094b\u091a\u0928 \u0932\u094b\u0915\u092a\u0924\u0947 \u0935\u093f\u091c\u092f\u0940 \u092d\u0935 \u0935\u0947\u0919\u094d\u0915\u091f\u0936\u0948\u0932\u092a\u0924\u0947 \u0965 \u0967 \u0965",
        iastText: "kamal\u0101kuca-c\u016bcuka-ku\u1e45kumato niyat\u0101ru\u1e47it\u0101tula-n\u012blatan\u014d .\nkamal\u0101yata-l\u014dcana l\u014dkapat\u0113 vijay\u012b bhava v\u0113\u1e45ka\u1e6da-\u015bailapat\u0113 .. 1 ..",
        meter: "Totaka / Vasantatilaka",
        transliterations: {"telugu": "\u0c15\u0c2e\u0c32\u0c3e\u0c15\u0c41\u0c1a\u0c1a\u0c42\u0c1a\u0c41\u0c15\u0c15\u0c41\u0c19\u0c4d\u0c15\u0c41\u0c2e\u0c24\u0c4b \u0c28\u0c3f\u0c2f\u0c24\u0c3e\u0c30\u0c41\u0c23\u0c3f\u0c24\u0c3e\u0c24\u0c41\u0c32\u0c28\u0c40\u0c32\u0c24\u0c28\u0c4b \u0964\n\u0c15\u0c2e\u0c32\u0c3e\u0c2f\u0c24\u0c32\u0c4b\u0c1a\u0c28 \u0c32\u0c4b\u0c15\u0c2a\u0c24\u0c47 \u0c35\u0c3f\u0c1c\u0c2f\u0c40 \u0c2d\u0c35 \u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c36\u0c48\u0c32\u0c2a\u0c24\u0c47 \u0965 \u0c67 \u0965", "tamil": "\u0b95\u0bae\u0bb2\u0bbe\u0b95\u0bc1\u0b9a\u0b9a\u0bc2\u0b9a\u0bc1\u0b95\u0b95\u0bc1\u0b99\u0bcd\u0b95\u0bc1\u0bae\u0ba4\u0bcb \u0ba8\u0bbf\u0baf\u0ba4\u0bbe\u0bb0\u0bc1\u0ba3\u0bbf\u0ba4\u0bbe\u0ba4\u0bc1\u0bb2\u0ba8\u0bc0\u0bb2\u0ba4\u0ba8\u0bcb \u0964\n\u0b95\u0bae\u0bb2\u0bbe\u0baf\u0ba4\u0bb2\u0bcb\u0b9a\u0ba8 \u0bb2\u0bcb\u0b95\u0baa\u0ba4\u0bc7 \u0bb5\u0bbf\u0b9c\u0baf\u0bc0 \u0baa\u0bb5 \u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bb6\u0bc8\u0bb2\u0baa\u0ba4\u0bc7 \u0965 \u0be7 \u0965", "kannada": "\u0c95\u0cae\u0cb2\u0cbe\u0c95\u0cc1\u0c9a\u0c9a\u0cc2\u0c9a\u0cc1\u0c95\u0c95\u0cc1\u0c99\u0ccd\u0c95\u0cc1\u0cae\u0ca4\u0ccb \u0ca8\u0cbf\u0caf\u0ca4\u0cbe\u0cb0\u0cc1\u0ca3\u0cbf\u0ca4\u0cbe\u0ca4\u0cc1\u0cb2\u0ca8\u0cc0\u0cb2\u0ca4\u0ca8\u0ccb \u0964\n\u0c95\u0cae\u0cb2\u0cbe\u0caf\u0ca4\u0cb2\u0ccb\u0c9a\u0ca8 \u0cb2\u0ccb\u0c95\u0caa\u0ca4\u0cc7 \u0cb5\u0cbf\u0c9c\u0caf\u0cc0 \u0cad\u0cb5 \u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cb6\u0cc8\u0cb2\u0caa\u0ca4\u0cc7 \u0965 \u0ce7 \u0965", "malayalam": "\u0d15\u0d2e\u0d32\u0d3e\u0d15\u0d41\u0d1a\u0d1a\u0d42\u0d1a\u0d41\u0d15\u0d15\u0d41\u0d19\u0d4d\u0d15\u0d41\u0d2e\u0d24\u0d4b \u0d28\u0d3f\u0d2f\u0d24\u0d3e\u0d30\u0d41\u0d23\u0d3f\u0d24\u0d3e\u0d24\u0d41\u0d32\u0d28\u0d40\u0d32\u0d24\u0d28\u0d4b \u0964\n\u0d15\u0d2e\u0d32\u0d3e\u0d2f\u0d24\u0d32\u0d4b\u0d1a\u0d28 \u0d32\u0d4b\u0d15\u0d2a\u0d24\u0d47 \u0d35\u0d3f\u0d1c\u0d2f\u0d40 \u0d2d\u0d35 \u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d36\u0d48\u0d32\u0d2a\u0d24\u0d47 \u0965 \u0d67 \u0965", "iast": "kamal\u0101kucac\u016bcukaku\u1e45kumato niyat\u0101ru\u1e47it\u0101tulan\u012blatano |\nkamal\u0101yatalocana lokapate vijay\u012b bhava ve\u1e45ka\u1e6da\u015bailapate || 1 ||"},
        draftTranslation: "O Lord whose peerless dark blue body is perpetually tinged with crimson red from the saffron paste adorning the bosom of Goddess Kamala! Whose eyes are expansive like blooming lotuses! O Lord of all worlds, O Sovereign of Venkatachala, mayest Thou be victorious forever!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 31,
        devanagariText: "\u0938\u091a\u0924\u0941\u0930\u094d\u092e\u0941\u0916\u0937\u0923\u094d\u092e\u0941\u0916\u092a\u091e\u094d\u091a\u092e\u0941\u0916-\u092a\u094d\u0930\u092e\u0941\u0916\u093e\u0916\u093f\u0932\u0926\u0948\u0935\u0924\u092e\u094c\u0932\u093f\u092e\u0923\u0947 \u0964\n\u0936\u0930\u0923\u093e\u0917\u0924\u0935\u0924\u094d\u0938\u0932 \u0938\u093e\u0930\u0928\u093f\u0927\u0947 \u092a\u0930\u093f\u092a\u093e\u0932\u092f \u092e\u093e\u0902 \u0935\u0943\u0937\u0936\u0948\u0932\u092a\u0924\u0947 \u0965 \u0968 \u0965",
        iastText: "sa-caturmukha-\u1e63a\u1e47mukha-pa\u00f1camukha-pramukh\u0101khila-daivata-maulima\u1e47\u0113 .\n\u015bara\u1e47\u0101gata-vatsala s\u0101ra-nidh\u0113 parip\u0101laya m\u0101\u1e41 v\u1e5b\u1e63a-\u015bailapat\u0113 .. 2 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c38\u0c1a\u0c24\u0c41\u0c30\u0c4d\u0c2e\u0c41\u0c16\u0c37\u0c23\u0c4d\u0c2e\u0c41\u0c16\u0c2a\u0c1e\u0c4d\u0c1a\u0c2e\u0c41\u0c16-\u0c2a\u0c4d\u0c30\u0c2e\u0c41\u0c16\u0c3e\u0c16\u0c3f\u0c32\u0c26\u0c48\u0c35\u0c24\u0c2e\u0c4c\u0c32\u0c3f\u0c2e\u0c23\u0c47 \u0964\n\u0c36\u0c30\u0c23\u0c3e\u0c17\u0c24\u0c35\u0c24\u0c4d\u0c38\u0c32 \u0c38\u0c3e\u0c30\u0c28\u0c3f\u0c27\u0c47 \u0c2a\u0c30\u0c3f\u0c2a\u0c3e\u0c32\u0c2f \u0c2e\u0c3e\u0c02 \u0c35\u0c43\u0c37\u0c36\u0c48\u0c32\u0c2a\u0c24\u0c47 \u0965 \u0c68 \u0965", "tamil": "\u0bb8\u0b9a\u0ba4\u0bc1\u0bb0\u0bcd\u0bae\u0bc1\u0b95\u0bb7\u0ba3\u0bcd\u0bae\u0bc1\u0b95\u0baa\u0b9e\u0bcd\u0b9a\u0bae\u0bc1\u0b95-\u0baa\u0bcd\u0bb0\u0bae\u0bc1\u0b95\u0bbe\u0b95\u0bbf\u0bb2\u0ba4\u0bc8\u0bb5\u0ba4\u0bae\u0bcc\u0bb2\u0bbf\u0bae\u0ba3\u0bc7 \u0964\n\u0bb6\u0bb0\u0ba3\u0bbe\u0b95\u0ba4\u0bb5\u0ba4\u0bcd\u0bb8\u0bb2 \u0bb8\u0bbe\u0bb0\u0ba8\u0bbf\u0ba4\u0bc7 \u0baa\u0bb0\u0bbf\u0baa\u0bbe\u0bb2\u0baf \u0bae\u0bbe\u0bae\u0bcd \u0bb5\u0bcd\u0bb0\u0bc1'\u0bb7\u0bb6\u0bc8\u0bb2\u0baa\u0ba4\u0bc7 \u0965 \u0be8 \u0965", "kannada": "\u0cb8\u0c9a\u0ca4\u0cc1\u0cb0\u0ccd\u0cae\u0cc1\u0c96\u0cb7\u0ca3\u0ccd\u0cae\u0cc1\u0c96\u0caa\u0c9e\u0ccd\u0c9a\u0cae\u0cc1\u0c96-\u0caa\u0ccd\u0cb0\u0cae\u0cc1\u0c96\u0cbe\u0c96\u0cbf\u0cb2\u0ca6\u0cc8\u0cb5\u0ca4\u0cae\u0ccc\u0cb2\u0cbf\u0cae\u0ca3\u0cc7 \u0964\n\u0cb6\u0cb0\u0ca3\u0cbe\u0c97\u0ca4\u0cb5\u0ca4\u0ccd\u0cb8\u0cb2 \u0cb8\u0cbe\u0cb0\u0ca8\u0cbf\u0ca7\u0cc7 \u0caa\u0cb0\u0cbf\u0caa\u0cbe\u0cb2\u0caf \u0cae\u0cbe\u0c82 \u0cb5\u0cc3\u0cb7\u0cb6\u0cc8\u0cb2\u0caa\u0ca4\u0cc7 \u0965 \u0ce8 \u0965", "malayalam": "\u0d38\u0d1a\u0d24\u0d41\u0d30\u0d4d\u0d2e\u0d41\u0d16\u0d37\u0d23\u0d4d\u0d2e\u0d41\u0d16\u0d2a\u0d1e\u0d4d\u0d1a\u0d2e\u0d41\u0d16-\u0d2a\u0d4d\u0d30\u0d2e\u0d41\u0d16\u0d3e\u0d16\u0d3f\u0d32\u0d26\u0d48\u0d35\u0d24\u0d2e\u0d4c\u0d32\u0d3f\u0d2e\u0d23\u0d47 \u0964\n\u0d36\u0d30\u0d23\u0d3e\u0d17\u0d24\u0d35\u0d24\u0d4d\u0d38\u0d32 \u0d38\u0d3e\u0d30\u0d28\u0d3f\u0d27\u0d47 \u0d2a\u0d30\u0d3f\u0d2a\u0d3e\u0d32\u0d2f \u0d2e\u0d3e\u0d02 \u0d35\u0d43\u0d37\u0d36\u0d48\u0d32\u0d2a\u0d24\u0d47 \u0965 \u0d68 \u0965", "iast": "sacaturmukha\u1e63a\u1e47mukhapa\u00f1camukha-pramukh\u0101khiladaivatamaulima\u1e47e |\n\u015bara\u1e47\u0101gatavatsala s\u0101ranidhe parip\u0101laya m\u0101\u1e43 v\u1e5b\u1e63a\u015bailapate || 2 ||"},
        draftTranslation: "O Crest-Jewel upon the diadems of all gods headed by the four-faced Brahma, the six-faced Kartikeya, and the five-faced Shiva! Merciful to all who seek refuge, treasury of essence! Protect me completely, O Lord of Vrishabhachala!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 32,
        devanagariText: "\u0905\u0924\u093f\u0935\u0947\u0932\u0924\u092f\u093e \u0924\u0935 \u0926\u0941\u0930\u094d\u0935\u093f\u0937\u0939\u0948\u0930\u0928\u0941\u0935\u0947\u0932\u0915\u0943\u0924\u0948\u0930\u092a\u0930\u093e\u0927\u0936\u0924\u0948\u0903 \u0964\n\u092d\u0930\u093f\u0924\u0902 \u0924\u094d\u0935\u0930\u093f\u0924\u0902 \u0935\u0943\u0937\u0936\u0948\u0932\u092a\u0924\u0947 \u092a\u0930\u092f\u093e \u0915\u0943\u092a\u092f\u093e \u092a\u0930\u093f\u092a\u093e\u0939\u093f \u0939\u0930\u0947 \u0965 \u0969 \u0965",
        iastText: "ativ\u0113latay\u0101 tava durvi\u1e63ahair-anuv\u0113lak\u1e5btair-apar\u0101dha-\u015batai\u1e25 .\nbharita\u1e41 tvarita\u1e41 v\u1e5b\u1e63a-\u015bailapat\u0113 paray\u0101 k\u1e5bpay\u0101 parip\u0101hi har\u0113 .. 3 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c05\u0c24\u0c3f\u0c35\u0c47\u0c32\u0c24\u0c2f\u0c3e \u0c24\u0c35 \u0c26\u0c41\u0c30\u0c4d\u0c35\u0c3f\u0c37\u0c39\u0c48\u0c30\u0c28\u0c41\u0c35\u0c47\u0c32\u0c15\u0c43\u0c24\u0c48\u0c30\u0c2a\u0c30\u0c3e\u0c27\u0c36\u0c24\u0c48\u0c03 \u0964\n\u0c2d\u0c30\u0c3f\u0c24\u0c02 \u0c24\u0c4d\u0c35\u0c30\u0c3f\u0c24\u0c02 \u0c35\u0c43\u0c37\u0c36\u0c48\u0c32\u0c2a\u0c24\u0c47 \u0c2a\u0c30\u0c2f\u0c3e \u0c15\u0c43\u0c2a\u0c2f\u0c3e \u0c2a\u0c30\u0c3f\u0c2a\u0c3e\u0c39\u0c3f \u0c39\u0c30\u0c47 \u0965 \u0c69 \u0965", "tamil": "\u0b85\u0ba4\u0bbf\u0bb5\u0bc7\u0bb2\u0ba4\u0baf\u0bbe \u0ba4\u0bb5 \u0ba4\u0bc1\u0bb0\u0bcd\u0bb5\u0bbf\u0bb7\u0bb9\u0bc8\u0bb0\u0ba8\u0bc1\u0bb5\u0bc7\u0bb2\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0bc8\u0bb0\u0baa\u0bb0\u0bbe\u0ba4\u0bb6\u0ba4\u0bc8\u0b83 \u0964\n\u0baa\u0bb0\u0bbf\u0ba4\u0bae\u0bcd \u0ba4\u0bcd\u0bb5\u0bb0\u0bbf\u0ba4\u0bae\u0bcd \u0bb5\u0bcd\u0bb0\u0bc1'\u0bb7\u0bb6\u0bc8\u0bb2\u0baa\u0ba4\u0bc7 \u0baa\u0bb0\u0baf\u0bbe \u0b95\u0bcd\u0bb0\u0bc1'\u0baa\u0baf\u0bbe \u0baa\u0bb0\u0bbf\u0baa\u0bbe\u0bb9\u0bbf \u0bb9\u0bb0\u0bc7 \u0965 \u0be9 \u0965", "kannada": "\u0c85\u0ca4\u0cbf\u0cb5\u0cc7\u0cb2\u0ca4\u0caf\u0cbe \u0ca4\u0cb5 \u0ca6\u0cc1\u0cb0\u0ccd\u0cb5\u0cbf\u0cb7\u0cb9\u0cc8\u0cb0\u0ca8\u0cc1\u0cb5\u0cc7\u0cb2\u0c95\u0cc3\u0ca4\u0cc8\u0cb0\u0caa\u0cb0\u0cbe\u0ca7\u0cb6\u0ca4\u0cc8\u0c83 \u0964\n\u0cad\u0cb0\u0cbf\u0ca4\u0c82 \u0ca4\u0ccd\u0cb5\u0cb0\u0cbf\u0ca4\u0c82 \u0cb5\u0cc3\u0cb7\u0cb6\u0cc8\u0cb2\u0caa\u0ca4\u0cc7 \u0caa\u0cb0\u0caf\u0cbe \u0c95\u0cc3\u0caa\u0caf\u0cbe \u0caa\u0cb0\u0cbf\u0caa\u0cbe\u0cb9\u0cbf \u0cb9\u0cb0\u0cc7 \u0965 \u0ce9 \u0965", "malayalam": "\u0d05\u0d24\u0d3f\u0d35\u0d47\u0d32\u0d24\u0d2f\u0d3e \u0d24\u0d35 \u0d26\u0d41\u0d30\u0d4d\u0d35\u0d3f\u0d37\u0d39\u0d48\u0d30\u0d28\u0d41\u0d35\u0d47\u0d32\u0d15\u0d43\u0d24\u0d48\u0d30\u0d2a\u0d30\u0d3e\u0d27\u0d36\u0d24\u0d48\u0d03 \u0964\n\u0d2d\u0d30\u0d3f\u0d24\u0d02 \u0d24\u0d4d\u0d35\u0d30\u0d3f\u0d24\u0d02 \u0d35\u0d43\u0d37\u0d36\u0d48\u0d32\u0d2a\u0d24\u0d47 \u0d2a\u0d30\u0d2f\u0d3e \u0d15\u0d43\u0d2a\u0d2f\u0d3e \u0d2a\u0d30\u0d3f\u0d2a\u0d3e\u0d39\u0d3f \u0d39\u0d30\u0d47 \u0965 \u0d69 \u0965", "iast": "ativelatay\u0101 tava durvi\u1e63ahairanuvelak\u1e5btairapar\u0101dha\u015batai\u1e25 |\nbharita\u1e43 tvarita\u1e43 v\u1e5b\u1e63a\u015bailapate paray\u0101 k\u1e5bpay\u0101 parip\u0101hi hare || 3 ||"},
        draftTranslation: "Loaded heavily with hundreds of intolerable offenses committed every moment transgressing all bounds \u2014 swiftly protect and rescue me, O Lord of Vrishabhachala, through Thy supreme, unmerited compassion, O Hari!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 33,
        devanagariText: "\u0905\u0927\u093f\u0935\u0947\u0919\u094d\u0915\u091f\u0936\u0948\u0932\u092e\u0941\u0926\u093e\u0930\u092e\u0924\u0947\u0930\u094d\u091c\u0928\u0924\u093e\u092d\u093f\u092e\u0924\u093e\u0927\u093f\u0915\u0926\u093e\u0928\u0930\u0924\u093e\u0924\u094d \u0964\n\u092a\u0930\u0926\u0947\u0935\u0924\u092f\u093e \u0917\u0926\u093f\u0924\u093e\u0928\u094d\u0928\u093f\u0917\u092e\u0948\u0903 \u0915\u092e\u0932\u093e\u0926\u092f\u093f\u0924\u093e\u0928\u094d\u0928 \u092a\u0930\u0902 \u0915\u0932\u092f\u0947 \u0965 \u096a \u0965",
        iastText: "adhi-v\u0113\u1e45ka\u1e6da-\u015bailam-ud\u0101ramat\u0113r-janat\u0101bhimat\u0101dhika-d\u0101na-rat\u0101t .\nparadaivatay\u0101 gadit\u0101n-nigamai\u1e25 kamal\u0101-dayit\u0101n-na para\u1e41 kalay\u0113 .. 4 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c05\u0c27\u0c3f\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c36\u0c48\u0c32\u0c2e\u0c41\u0c26\u0c3e\u0c30\u0c2e\u0c24\u0c47\u0c30\u0c4d\u0c1c\u0c28\u0c24\u0c3e\u0c2d\u0c3f\u0c2e\u0c24\u0c3e\u0c27\u0c3f\u0c15\u0c26\u0c3e\u0c28\u0c30\u0c24\u0c3e\u0c24\u0c4d \u0964\n\u0c2a\u0c30\u0c26\u0c47\u0c35\u0c24\u0c2f\u0c3e \u0c17\u0c26\u0c3f\u0c24\u0c3e\u0c28\u0c4d\u0c28\u0c3f\u0c17\u0c2e\u0c48\u0c03 \u0c15\u0c2e\u0c32\u0c3e\u0c26\u0c2f\u0c3f\u0c24\u0c3e\u0c28\u0c4d\u0c28 \u0c2a\u0c30\u0c02 \u0c15\u0c32\u0c2f\u0c47 \u0965 \u0c6a \u0965", "tamil": "\u0b85\u0ba4\u0bbf\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bb6\u0bc8\u0bb2\u0bae\u0bc1\u0ba4\u0bbe\u0bb0\u0bae\u0ba4\u0bc7\u0bb0\u0bcd\u0b9c\u0ba8\u0ba4\u0bbe\u0baa\u0bbf\u0bae\u0ba4\u0bbe\u0ba4\u0bbf\u0b95\u0ba4\u0bbe\u0ba8\u0bb0\u0ba4\u0bbe\u0ba4\u0bcd \u0964\n\u0baa\u0bb0\u0ba4\u0bc7\u0bb5\u0ba4\u0baf\u0bbe \u0b95\u0ba4\u0bbf\u0ba4\u0bbe\u0ba8\u0bcd\u0ba8\u0bbf\u0b95\u0bae\u0bc8\u0b83 \u0b95\u0bae\u0bb2\u0bbe\u0ba4\u0baf\u0bbf\u0ba4\u0bbe\u0ba8\u0bcd\u0ba8 \u0baa\u0bb0\u0bae\u0bcd \u0b95\u0bb2\u0baf\u0bc7 \u0965 \u0bea \u0965", "kannada": "\u0c85\u0ca7\u0cbf\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cb6\u0cc8\u0cb2\u0cae\u0cc1\u0ca6\u0cbe\u0cb0\u0cae\u0ca4\u0cc7\u0cb0\u0ccd\u0c9c\u0ca8\u0ca4\u0cbe\u0cad\u0cbf\u0cae\u0ca4\u0cbe\u0ca7\u0cbf\u0c95\u0ca6\u0cbe\u0ca8\u0cb0\u0ca4\u0cbe\u0ca4\u0ccd \u0964\n\u0caa\u0cb0\u0ca6\u0cc7\u0cb5\u0ca4\u0caf\u0cbe \u0c97\u0ca6\u0cbf\u0ca4\u0cbe\u0ca8\u0ccd\u0ca8\u0cbf\u0c97\u0cae\u0cc8\u0c83 \u0c95\u0cae\u0cb2\u0cbe\u0ca6\u0caf\u0cbf\u0ca4\u0cbe\u0ca8\u0ccd\u0ca8 \u0caa\u0cb0\u0c82 \u0c95\u0cb2\u0caf\u0cc7 \u0965 \u0cea \u0965", "malayalam": "\u0d05\u0d27\u0d3f\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d36\u0d48\u0d32\u0d2e\u0d41\u0d26\u0d3e\u0d30\u0d2e\u0d24\u0d47\u0d30\u0d4d\u0d1c\u0d28\u0d24\u0d3e\u0d2d\u0d3f\u0d2e\u0d24\u0d3e\u0d27\u0d3f\u0d15\u0d26\u0d3e\u0d28\u0d30\u0d24\u0d3e\u0d24\u0d4d \u0964\n\u0d2a\u0d30\u0d26\u0d47\u0d35\u0d24\u0d2f\u0d3e \u0d17\u0d26\u0d3f\u0d24\u0d3e\u0d28\u0d4d\u0d28\u0d3f\u0d17\u0d2e\u0d48\u0d03 \u0d15\u0d2e\u0d32\u0d3e\u0d26\u0d2f\u0d3f\u0d24\u0d3e\u0d28\u0d4d\u0d28 \u0d2a\u0d30\u0d02 \u0d15\u0d32\u0d2f\u0d47 \u0965 \u0d6a \u0965", "iast": "adhive\u1e45ka\u1e6da\u015bailamud\u0101ramaterjanat\u0101bhimat\u0101dhikad\u0101narat\u0101t |\nparadevatay\u0101 gadit\u0101nnigamai\u1e25 kamal\u0101dayit\u0101nna para\u1e43 kalaye || 4 ||"},
        draftTranslation: "Abiding upon Mount Venkata, endowed with generous disposition, constantly engaged in granting gifts far exceeding the desires of devotees, proclaimed as the Supreme Divinity by the Vedas \u2014 other than this Beloved Consort of Kamala, I recognize no higher God!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 34,
        devanagariText: "\u0915\u0932\u0935\u0947\u0923\u0941\u0930\u0935\u093e\u0935\u0936\u0917\u094b\u092a\u0935\u0927\u0942-\u0936\u0924\u0915\u094b\u091f\u093f\u0935\u0943\u0924\u093e\u0924\u094d\u0938\u094d\u092e\u0930\u0915\u094b\u091f\u093f\u0938\u092e\u093e\u0924\u094d \u0964\n\u092a\u094d\u0930\u0924\u093f\u0935\u0932\u094d\u0932\u0935\u093f\u0915\u093e\u092d\u093f\u092e\u0924\u093e\u0924\u094d\u0938\u0941\u0916\u0926\u093e\u0926\u094d\u0935\u0938\u0941\u0926\u0947\u0935\u0938\u0941\u0924\u093e\u0928\u094d\u0928 \u092a\u0930\u0902 \u0915\u0932\u092f\u0947 \u0965 \u096b \u0965",
        iastText: "kala-v\u0113\u1e47u-rav\u0101va\u015ba-g\u014dpa-vadh\u016b-\u015bata-k\u014d\u1e6di-v\u1e5bt\u0101t-smara-k\u014d\u1e6di-sam\u0101t .\nprativallavik\u0101bhimat\u0101t-sukhad\u0101d-vasud\u0113va-sut\u0101n-na para\u1e41 kalay\u0113 .. 5 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c15\u0c32\u0c35\u0c47\u0c23\u0c41\u0c30\u0c35\u0c3e\u0c35\u0c36\u0c17\u0c4b\u0c2a\u0c35\u0c27\u0c42-\u0c36\u0c24\u0c15\u0c4b\u0c1f\u0c3f\u0c35\u0c43\u0c24\u0c3e\u0c24\u0c4d\u0c38\u0c4d\u0c2e\u0c30\u0c15\u0c4b\u0c1f\u0c3f\u0c38\u0c2e\u0c3e\u0c24\u0c4d \u0964\n\u0c2a\u0c4d\u0c30\u0c24\u0c3f\u0c35\u0c32\u0c4d\u0c32\u0c35\u0c3f\u0c15\u0c3e\u0c2d\u0c3f\u0c2e\u0c24\u0c3e\u0c24\u0c4d\u0c38\u0c41\u0c16\u0c26\u0c3e\u0c26\u0c4d\u0c35\u0c38\u0c41\u0c26\u0c47\u0c35\u0c38\u0c41\u0c24\u0c3e\u0c28\u0c4d\u0c28 \u0c2a\u0c30\u0c02 \u0c15\u0c32\u0c2f\u0c47 \u0965 \u0c6b \u0965", "tamil": "\u0b95\u0bb2\u0bb5\u0bc7\u0ba3\u0bc1\u0bb0\u0bb5\u0bbe\u0bb5\u0bb6\u0b95\u0bcb\u0baa\u0bb5\u0ba4\u0bc2-\u0bb6\u0ba4\u0b95\u0bcb\u0b9f\u0bbf\u0bb5\u0bcd\u0bb0\u0bc1'\u0ba4\u0bbe\u0ba4\u0bcd\u0bb8\u0bcd\u0bae\u0bb0\u0b95\u0bcb\u0b9f\u0bbf\u0bb8\u0bae\u0bbe\u0ba4\u0bcd \u0964\n\u0baa\u0bcd\u0bb0\u0ba4\u0bbf\u0bb5\u0bb2\u0bcd\u0bb2\u0bb5\u0bbf\u0b95\u0bbe\u0baa\u0bbf\u0bae\u0ba4\u0bbe\u0ba4\u0bcd\u0bb8\u0bc1\u0b95\u0ba4\u0bbe\u0ba4\u0bcd\u0bb5\u0bb8\u0bc1\u0ba4\u0bc7\u0bb5\u0bb8\u0bc1\u0ba4\u0bbe\u0ba8\u0bcd\u0ba8 \u0baa\u0bb0\u0bae\u0bcd \u0b95\u0bb2\u0baf\u0bc7 \u0965 \u0beb \u0965", "kannada": "\u0c95\u0cb2\u0cb5\u0cc7\u0ca3\u0cc1\u0cb0\u0cb5\u0cbe\u0cb5\u0cb6\u0c97\u0ccb\u0caa\u0cb5\u0ca7\u0cc2-\u0cb6\u0ca4\u0c95\u0ccb\u0c9f\u0cbf\u0cb5\u0cc3\u0ca4\u0cbe\u0ca4\u0ccd\u0cb8\u0ccd\u0cae\u0cb0\u0c95\u0ccb\u0c9f\u0cbf\u0cb8\u0cae\u0cbe\u0ca4\u0ccd \u0964\n\u0caa\u0ccd\u0cb0\u0ca4\u0cbf\u0cb5\u0cb2\u0ccd\u0cb2\u0cb5\u0cbf\u0c95\u0cbe\u0cad\u0cbf\u0cae\u0ca4\u0cbe\u0ca4\u0ccd\u0cb8\u0cc1\u0c96\u0ca6\u0cbe\u0ca6\u0ccd\u0cb5\u0cb8\u0cc1\u0ca6\u0cc7\u0cb5\u0cb8\u0cc1\u0ca4\u0cbe\u0ca8\u0ccd\u0ca8 \u0caa\u0cb0\u0c82 \u0c95\u0cb2\u0caf\u0cc7 \u0965 \u0ceb \u0965", "malayalam": "\u0d15\u0d32\u0d35\u0d47\u0d23\u0d41\u0d30\u0d35\u0d3e\u0d35\u0d36\u0d17\u0d4b\u0d2a\u0d35\u0d27\u0d42-\u0d36\u0d24\u0d15\u0d4b\u0d1f\u0d3f\u0d35\u0d43\u0d24\u0d3e\u0d24\u0d4d\u0d38\u0d4d\u0d2e\u0d30\u0d15\u0d4b\u0d1f\u0d3f\u0d38\u0d2e\u0d3e\u0d24\u0d4d \u0964\n\u0d2a\u0d4d\u0d30\u0d24\u0d3f\u0d35\u0d32\u0d4d\u0d32\u0d35\u0d3f\u0d15\u0d3e\u0d2d\u0d3f\u0d2e\u0d24\u0d3e\u0d24\u0d4d\u0d38\u0d41\u0d16\u0d26\u0d3e\u0d26\u0d4d\u0d35\u0d38\u0d41\u0d26\u0d47\u0d35\u0d38\u0d41\u0d24\u0d3e\u0d28\u0d4d\u0d28 \u0d2a\u0d30\u0d02 \u0d15\u0d32\u0d2f\u0d47 \u0965 \u0d6b \u0965", "iast": "kalave\u1e47urav\u0101va\u015bagopavadh\u016b-\u015batako\u1e6div\u1e5bt\u0101tsmarako\u1e6disam\u0101t |\nprativallavik\u0101bhimat\u0101tsukhad\u0101dvasudevasut\u0101nna para\u1e43 kalaye || 5 ||"},
        draftTranslation: "Surrounded by hundreds of millions of Gopis captivated by the sweet melody of His flute! Whose charm equals tens of millions of Kamadevas! Fulfilling the innermost yearning of each individual cowherd maiden and granting supreme bliss \u2014 other than that Son of Vasudeva (Sri Krishna), I know no higher God!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 35,
        devanagariText: "\u0905\u092d\u093f\u0930\u093e\u092e\u0917\u0941\u0923\u093e\u0915\u0930 \u0926\u093e\u0936\u0930\u0925\u0947 \u091c\u0917\u0926\u0947\u0915\u0927\u0928\u0941\u0930\u094d\u0927\u0930 \u0927\u0940\u0930\u092e\u0924\u0947 \u0964\n\u0930\u0918\u0941\u0928\u093e\u092f\u0915 \u0930\u093e\u092e \u0930\u092e\u0947\u0936 \u0935\u093f\u092d\u094b \u0935\u0930\u0926\u094b \u092d\u0935 \u0926\u0947\u0935 \u0926\u092f\u093e\u091c\u0932\u0927\u0947 \u0965 \u096c \u0965",
        iastText: "abhir\u0101ma-gu\u1e47\u0101kara d\u0101\u015barath\u0113 jagad-\u0113ka-dhanurdhara dh\u012bramat\u0113 .\nraghu-n\u0101yaka r\u0101ma ram\u0113\u015ba vibh\u014d varad\u014d bhava d\u0113va day\u0101-jaladh\u0113 .. 6 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c05\u0c2d\u0c3f\u0c30\u0c3e\u0c2e\u0c17\u0c41\u0c23\u0c3e\u0c15\u0c30 \u0c26\u0c3e\u0c36\u0c30\u0c25\u0c47 \u0c1c\u0c17\u0c26\u0c47\u0c15\u0c27\u0c28\u0c41\u0c30\u0c4d\u0c27\u0c30 \u0c27\u0c40\u0c30\u0c2e\u0c24\u0c47 \u0964\n\u0c30\u0c18\u0c41\u0c28\u0c3e\u0c2f\u0c15 \u0c30\u0c3e\u0c2e \u0c30\u0c2e\u0c47\u0c36 \u0c35\u0c3f\u0c2d\u0c4b \u0c35\u0c30\u0c26\u0c4b \u0c2d\u0c35 \u0c26\u0c47\u0c35 \u0c26\u0c2f\u0c3e\u0c1c\u0c32\u0c27\u0c47 \u0965 \u0c6c \u0965", "tamil": "\u0b85\u0baa\u0bbf\u0bb0\u0bbe\u0bae\u0b95\u0bc1\u0ba3\u0bbe\u0b95\u0bb0 \u0ba4\u0bbe\u0bb6\u0bb0\u0ba4\u0bc7 \u0b9c\u0b95\u0ba4\u0bc7\u0b95\u0ba4\u0ba8\u0bc1\u0bb0\u0bcd\u0ba4\u0bb0 \u0ba4\u0bc0\u0bb0\u0bae\u0ba4\u0bc7 \u0964\n\u0bb0\u0b95\u0bc1\u0ba8\u0bbe\u0baf\u0b95 \u0bb0\u0bbe\u0bae \u0bb0\u0bae\u0bc7\u0bb6 \u0bb5\u0bbf\u0baa\u0bcb \u0bb5\u0bb0\u0ba4\u0bcb \u0baa\u0bb5 \u0ba4\u0bc7\u0bb5 \u0ba4\u0baf\u0bbe\u0b9c\u0bb2\u0ba4\u0bc7 \u0965 \u0bec \u0965", "kannada": "\u0c85\u0cad\u0cbf\u0cb0\u0cbe\u0cae\u0c97\u0cc1\u0ca3\u0cbe\u0c95\u0cb0 \u0ca6\u0cbe\u0cb6\u0cb0\u0ca5\u0cc7 \u0c9c\u0c97\u0ca6\u0cc7\u0c95\u0ca7\u0ca8\u0cc1\u0cb0\u0ccd\u0ca7\u0cb0 \u0ca7\u0cc0\u0cb0\u0cae\u0ca4\u0cc7 \u0964\n\u0cb0\u0c98\u0cc1\u0ca8\u0cbe\u0caf\u0c95 \u0cb0\u0cbe\u0cae \u0cb0\u0cae\u0cc7\u0cb6 \u0cb5\u0cbf\u0cad\u0ccb \u0cb5\u0cb0\u0ca6\u0ccb \u0cad\u0cb5 \u0ca6\u0cc7\u0cb5 \u0ca6\u0caf\u0cbe\u0c9c\u0cb2\u0ca7\u0cc7 \u0965 \u0cec \u0965", "malayalam": "\u0d05\u0d2d\u0d3f\u0d30\u0d3e\u0d2e\u0d17\u0d41\u0d23\u0d3e\u0d15\u0d30 \u0d26\u0d3e\u0d36\u0d30\u0d25\u0d47 \u0d1c\u0d17\u0d26\u0d47\u0d15\u0d27\u0d28\u0d41\u0d30\u0d4d\u0d27\u0d30 \u0d27\u0d40\u0d30\u0d2e\u0d24\u0d47 \u0964\n\u0d30\u0d18\u0d41\u0d28\u0d3e\u0d2f\u0d15 \u0d30\u0d3e\u0d2e \u0d30\u0d2e\u0d47\u0d36 \u0d35\u0d3f\u0d2d\u0d4b \u0d35\u0d30\u0d26\u0d4b \u0d2d\u0d35 \u0d26\u0d47\u0d35 \u0d26\u0d2f\u0d3e\u0d1c\u0d32\u0d27\u0d47 \u0965 \u0d6c \u0965", "iast": "abhir\u0101magu\u1e47\u0101kara d\u0101\u015barathe jagadekadhanurdhara dh\u012bramate |\nraghun\u0101yaka r\u0101ma rame\u015ba vibho varado bhava deva day\u0101jaladhe || 6 ||"},
        draftTranslation: "Mine of charming virtues! Son of Dasharatha! Sole sovereign archer of the universe! Endowed with steadfast wisdom! Hero of the Raghus, Rama, Lord of Ramaa (Lakshmi), Omnipresent Divinity, ocean of compassion, be pleased to bestow boons upon me!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 36,
        devanagariText: "\u0905\u0935\u0928\u0940\u0924\u0928\u092f\u093e\u0915\u092e\u0928\u0940\u092f\u0915\u0930\u0902 \u0930\u091c\u0928\u0940\u091a\u0930\u091a\u0915\u094d\u0930\u0924\u092e\u0903\u092a\u0924\u093f\u0924\u092e\u094d \u0964\n\u0905\u092e\u0930\u0940\u092a\u0930\u093f\u0935\u0928\u094d\u0926\u093f\u0924\u092a\u093e\u0926\u092f\u0941\u0917\u0902 \u0935\u0930\u0926\u094b \u092d\u0935 \u0926\u0947\u0935 \u0926\u092f\u093e\u091c\u0932\u0927\u0947 \u0965 \u096d \u0965",
        iastText: "avan\u012b-tanay\u0101-kaman\u012bya-kara\u1e41 rajan\u012bcara-cakra-tama\u1e25-patitam .\namar\u012b-parivandita-p\u0101da-yuga\u1e41 varad\u014d bhava d\u0113va day\u0101-jaladh\u0113 .. 7 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c05\u0c35\u0c28\u0c40\u0c24\u0c28\u0c2f\u0c3e\u0c15\u0c2e\u0c28\u0c40\u0c2f\u0c15\u0c30\u0c02 \u0c30\u0c1c\u0c28\u0c40\u0c1a\u0c30\u0c1a\u0c15\u0c4d\u0c30\u0c24\u0c2e\u0c03\u0c2a\u0c24\u0c3f\u0c24\u0c2e\u0c4d \u0964\n\u0c05\u0c2e\u0c30\u0c40\u0c2a\u0c30\u0c3f\u0c35\u0c28\u0c4d\u0c26\u0c3f\u0c24\u0c2a\u0c3e\u0c26\u0c2f\u0c41\u0c17\u0c02 \u0c35\u0c30\u0c26\u0c4b \u0c2d\u0c35 \u0c26\u0c47\u0c35 \u0c26\u0c2f\u0c3e\u0c1c\u0c32\u0c27\u0c47 \u0965 \u0c6d \u0965", "tamil": "\u0b85\u0bb5\u0ba8\u0bc0\u0ba4\u0ba8\u0baf\u0bbe\u0b95\u0bae\u0ba8\u0bc0\u0baf\u0b95\u0bb0\u0bae\u0bcd \u0bb0\u0b9c\u0ba8\u0bc0\u0b9a\u0bb0\u0b9a\u0b95\u0bcd\u0bb0\u0ba4\u0bae\u0b83\u0baa\u0ba4\u0bbf\u0ba4\u0bae\u0bcd \u0964\n\u0b85\u0bae\u0bb0\u0bc0\u0baa\u0bb0\u0bbf\u0bb5\u0ba8\u0bcd\u0ba4\u0bbf\u0ba4\u0baa\u0bbe\u0ba4\u0baf\u0bc1\u0b95\u0bae\u0bcd \u0bb5\u0bb0\u0ba4\u0bcb \u0baa\u0bb5 \u0ba4\u0bc7\u0bb5 \u0ba4\u0baf\u0bbe\u0b9c\u0bb2\u0ba4\u0bc7 \u0965 \u0bed \u0965", "kannada": "\u0c85\u0cb5\u0ca8\u0cc0\u0ca4\u0ca8\u0caf\u0cbe\u0c95\u0cae\u0ca8\u0cc0\u0caf\u0c95\u0cb0\u0c82 \u0cb0\u0c9c\u0ca8\u0cc0\u0c9a\u0cb0\u0c9a\u0c95\u0ccd\u0cb0\u0ca4\u0cae\u0c83\u0caa\u0ca4\u0cbf\u0ca4\u0cae\u0ccd \u0964\n\u0c85\u0cae\u0cb0\u0cc0\u0caa\u0cb0\u0cbf\u0cb5\u0ca8\u0ccd\u0ca6\u0cbf\u0ca4\u0caa\u0cbe\u0ca6\u0caf\u0cc1\u0c97\u0c82 \u0cb5\u0cb0\u0ca6\u0ccb \u0cad\u0cb5 \u0ca6\u0cc7\u0cb5 \u0ca6\u0caf\u0cbe\u0c9c\u0cb2\u0ca7\u0cc7 \u0965 \u0ced \u0965", "malayalam": "\u0d05\u0d35\u0d28\u0d40\u0d24\u0d28\u0d2f\u0d3e\u0d15\u0d2e\u0d28\u0d40\u0d2f\u0d15\u0d30\u0d02 \u0d30\u0d1c\u0d28\u0d40\u0d1a\u0d30\u0d1a\u0d15\u0d4d\u0d30\u0d24\u0d2e\u0d03\u0d2a\u0d24\u0d3f\u0d24\u0d2e\u0d4d \u0964\n\u0d05\u0d2e\u0d30\u0d40\u0d2a\u0d30\u0d3f\u0d35\u0d28\u0d4d\u0d26\u0d3f\u0d24\u0d2a\u0d3e\u0d26\u0d2f\u0d41\u0d17\u0d02 \u0d35\u0d30\u0d26\u0d4b \u0d2d\u0d35 \u0d26\u0d47\u0d35 \u0d26\u0d2f\u0d3e\u0d1c\u0d32\u0d27\u0d47 \u0965 \u0d6d \u0965", "iast": "avan\u012btanay\u0101kaman\u012byakara\u1e43 rajan\u012bcaracakratama\u1e25patitam |\namar\u012bparivanditap\u0101dayuga\u1e43 varado bhava deva day\u0101jaladhe || 7 ||"},
        draftTranslation: "Holding the charming, lotus-soft hand of the Daughter of the Earth (Sita)! Sun that dispels the darkness of demonic hordes! Whose twin feet are adored by celestial nymphs! Ocean of mercy, be pleased to bestow boons upon me!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 37,
        devanagariText: "\u092e\u0928\u0938\u093e \u0935\u091a\u0938\u093e \u091a \u0924\u0925\u093e \u0935\u092a\u0941\u0937\u093e \u091c\u0928\u0924\u094b\u092a\u0915\u0943\u0924\u0902 \u0928 \u0935\u093f\u091a\u093f\u0928\u094d\u0924\u092f\u0924\u093e\u092e\u094d \u0964\n\u092a\u094d\u0930\u0924\u093f\u092a\u0915\u094d\u0937\u0930\u0925\u0948\u0930\u092a\u0930\u093e\u091c\u093f\u0924\u092f\u094b\u0903 \u0938\u0939\u0938\u093e \u092a\u0924\u0924\u094b\u0930\u094d\u0928 \u092d\u092f\u0902 \u0935\u093f\u0926\u0941\u0937\u093e\u092e\u094d \u0965 \u096e \u0965",
        iastText: "manas\u0101 vacas\u0101 ca tath\u0101 vapu\u1e63\u0101 janat\u014dpak\u1e5bta\u1e41 na vicintayat\u0101m .\npratipak\u1e63a-rathair-apar\u0101jitay\u014d\u1e25 sahas\u0101 patat\u014dr-na bhaya\u1e41 vidu\u1e63\u0101m .. 8 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2e\u0c28\u0c38\u0c3e \u0c35\u0c1a\u0c38\u0c3e \u0c1a \u0c24\u0c25\u0c3e \u0c35\u0c2a\u0c41\u0c37\u0c3e \u0c1c\u0c28\u0c24\u0c4b\u0c2a\u0c15\u0c43\u0c24\u0c02 \u0c28 \u0c35\u0c3f\u0c1a\u0c3f\u0c28\u0c4d\u0c24\u0c2f\u0c24\u0c3e\u0c2e\u0c4d \u0964\n\u0c2a\u0c4d\u0c30\u0c24\u0c3f\u0c2a\u0c15\u0c4d\u0c37\u0c30\u0c25\u0c48\u0c30\u0c2a\u0c30\u0c3e\u0c1c\u0c3f\u0c24\u0c2f\u0c4b\u0c03 \u0c38\u0c39\u0c38\u0c3e \u0c2a\u0c24\u0c24\u0c4b\u0c30\u0c4d\u0c28 \u0c2d\u0c2f\u0c02 \u0c35\u0c3f\u0c26\u0c41\u0c37\u0c3e\u0c2e\u0c4d \u0965 \u0c6e \u0965", "tamil": "\u0bae\u0ba8\u0bb8\u0bbe \u0bb5\u0b9a\u0bb8\u0bbe \u0b9a \u0ba4\u0ba4\u0bbe \u0bb5\u0baa\u0bc1\u0bb7\u0bbe \u0b9c\u0ba8\u0ba4\u0bcb\u0baa\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0bae\u0bcd \u0ba8 \u0bb5\u0bbf\u0b9a\u0bbf\u0ba8\u0bcd\u0ba4\u0baf\u0ba4\u0bbe\u0bae\u0bcd \u0964\n\u0baa\u0bcd\u0bb0\u0ba4\u0bbf\u0baa\u0b95\u0bcd\u0bb7\u0bb0\u0ba4\u0bc8\u0bb0\u0baa\u0bb0\u0bbe\u0b9c\u0bbf\u0ba4\u0baf\u0bcb\u0b83 \u0bb8\u0bb9\u0bb8\u0bbe \u0baa\u0ba4\u0ba4\u0bcb\u0bb0\u0bcd\u0ba8 \u0baa\u0baf\u0bae\u0bcd \u0bb5\u0bbf\u0ba4\u0bc1\u0bb7\u0bbe\u0bae\u0bcd \u0965 \u0bee \u0965", "kannada": "\u0cae\u0ca8\u0cb8\u0cbe \u0cb5\u0c9a\u0cb8\u0cbe \u0c9a \u0ca4\u0ca5\u0cbe \u0cb5\u0caa\u0cc1\u0cb7\u0cbe \u0c9c\u0ca8\u0ca4\u0ccb\u0caa\u0c95\u0cc3\u0ca4\u0c82 \u0ca8 \u0cb5\u0cbf\u0c9a\u0cbf\u0ca8\u0ccd\u0ca4\u0caf\u0ca4\u0cbe\u0cae\u0ccd \u0964\n\u0caa\u0ccd\u0cb0\u0ca4\u0cbf\u0caa\u0c95\u0ccd\u0cb7\u0cb0\u0ca5\u0cc8\u0cb0\u0caa\u0cb0\u0cbe\u0c9c\u0cbf\u0ca4\u0caf\u0ccb\u0c83 \u0cb8\u0cb9\u0cb8\u0cbe \u0caa\u0ca4\u0ca4\u0ccb\u0cb0\u0ccd\u0ca8 \u0cad\u0caf\u0c82 \u0cb5\u0cbf\u0ca6\u0cc1\u0cb7\u0cbe\u0cae\u0ccd \u0965 \u0cee \u0965", "malayalam": "\u0d2e\u0d28\u0d38\u0d3e \u0d35\u0d1a\u0d38\u0d3e \u0d1a \u0d24\u0d25\u0d3e \u0d35\u0d2a\u0d41\u0d37\u0d3e \u0d1c\u0d28\u0d24\u0d4b\u0d2a\u0d15\u0d43\u0d24\u0d02 \u0d28 \u0d35\u0d3f\u0d1a\u0d3f\u0d28\u0d4d\u0d24\u0d2f\u0d24\u0d3e\u0d2e\u0d4d \u0964\n\u0d2a\u0d4d\u0d30\u0d24\u0d3f\u0d2a\u0d15\u0d4d\u0d37\u0d30\u0d25\u0d48\u0d30\u0d2a\u0d30\u0d3e\u0d1c\u0d3f\u0d24\u0d2f\u0d4b\u0d03 \u0d38\u0d39\u0d38\u0d3e \u0d2a\u0d24\u0d24\u0d4b\u0d30\u0d4d\u0d28 \u0d2d\u0d2f\u0d02 \u0d35\u0d3f\u0d26\u0d41\u0d37\u0d3e\u0d2e\u0d4d \u0965 \u0d6e \u0965", "iast": "manas\u0101 vacas\u0101 ca tath\u0101 vapu\u1e63\u0101 janatopak\u1e5bta\u1e43 na vicintayat\u0101m |\npratipak\u1e63arathairapar\u0101jitayo\u1e25 sahas\u0101 patatorna bhaya\u1e43 vidu\u1e63\u0101m || 8 ||"},
        draftTranslation: "For those wise souls who surrender their mind, speech, and physical body in devotion without calculating their own actions, taking shelter under Thy twin feet unvanquished by opposing battle-chariots \u2014 there is never any fear of sudden downfall!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 38,
        devanagariText: "\u0905\u0915\u0941\u0924\u094b\u092d\u092f\u092e\u0947\u0924\u0926\u0928\u0947\u0915\u0926\u093f\u0935\u0902 \u091c\u0928\u0924\u094b\u092a\u0915\u0943\u0924\u0902 \u0938\u0924\u0924\u0902 \u092d\u091c\u0924\u093e\u092e\u094d \u0964\n\u092a\u0930\u092e\u0902 \u092a\u0926\u092e\u093e\u0924\u094d\u092e\u0935\u093f\u0926\u094b \u0935\u093f\u0926\u0941\u0937\u0903 \u0936\u0930\u0923\u0902 \u0935\u0943\u0937\u0936\u0948\u0932\u092a\u0924\u0947\u0930\u094d\u092d\u0935\u0924\u0903 \u0965 \u096f \u0965",
        iastText: "akut\u014dbhayam-\u0113tad-an\u0113ka-diva\u1e41 janat\u014dpak\u1e5bta\u1e41 satata\u1e41 bhajat\u0101m .\nparama\u1e41 padam-\u0101tmavid\u014d vidu\u1e63a\u1e25 \u015bara\u1e47a\u1e41 v\u1e5b\u1e63a-\u015bailapat\u0113r-bhavata\u1e25 .. 9 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c05\u0c15\u0c41\u0c24\u0c4b\u0c2d\u0c2f\u0c2e\u0c47\u0c24\u0c26\u0c28\u0c47\u0c15\u0c26\u0c3f\u0c35\u0c02 \u0c1c\u0c28\u0c24\u0c4b\u0c2a\u0c15\u0c43\u0c24\u0c02 \u0c38\u0c24\u0c24\u0c02 \u0c2d\u0c1c\u0c24\u0c3e\u0c2e\u0c4d \u0964\n\u0c2a\u0c30\u0c2e\u0c02 \u0c2a\u0c26\u0c2e\u0c3e\u0c24\u0c4d\u0c2e\u0c35\u0c3f\u0c26\u0c4b \u0c35\u0c3f\u0c26\u0c41\u0c37\u0c03 \u0c36\u0c30\u0c23\u0c02 \u0c35\u0c43\u0c37\u0c36\u0c48\u0c32\u0c2a\u0c24\u0c47\u0c30\u0c4d\u0c2d\u0c35\u0c24\u0c03 \u0965 \u0c6f \u0965", "tamil": "\u0b85\u0b95\u0bc1\u0ba4\u0bcb\u0baa\u0baf\u0bae\u0bc7\u0ba4\u0ba4\u0ba8\u0bc7\u0b95\u0ba4\u0bbf\u0bb5\u0bae\u0bcd \u0b9c\u0ba8\u0ba4\u0bcb\u0baa\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0bae\u0bcd \u0bb8\u0ba4\u0ba4\u0bae\u0bcd \u0baa\u0b9c\u0ba4\u0bbe\u0bae\u0bcd \u0964\n\u0baa\u0bb0\u0bae\u0bae\u0bcd \u0baa\u0ba4\u0bae\u0bbe\u0ba4\u0bcd\u0bae\u0bb5\u0bbf\u0ba4\u0bcb \u0bb5\u0bbf\u0ba4\u0bc1\u0bb7\u0b83 \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0bb5\u0bcd\u0bb0\u0bc1'\u0bb7\u0bb6\u0bc8\u0bb2\u0baa\u0ba4\u0bc7\u0bb0\u0bcd\u0baa\u0bb5\u0ba4\u0b83 \u0965 \u0bef \u0965", "kannada": "\u0c85\u0c95\u0cc1\u0ca4\u0ccb\u0cad\u0caf\u0cae\u0cc7\u0ca4\u0ca6\u0ca8\u0cc7\u0c95\u0ca6\u0cbf\u0cb5\u0c82 \u0c9c\u0ca8\u0ca4\u0ccb\u0caa\u0c95\u0cc3\u0ca4\u0c82 \u0cb8\u0ca4\u0ca4\u0c82 \u0cad\u0c9c\u0ca4\u0cbe\u0cae\u0ccd \u0964\n\u0caa\u0cb0\u0cae\u0c82 \u0caa\u0ca6\u0cae\u0cbe\u0ca4\u0ccd\u0cae\u0cb5\u0cbf\u0ca6\u0ccb \u0cb5\u0cbf\u0ca6\u0cc1\u0cb7\u0c83 \u0cb6\u0cb0\u0ca3\u0c82 \u0cb5\u0cc3\u0cb7\u0cb6\u0cc8\u0cb2\u0caa\u0ca4\u0cc7\u0cb0\u0ccd\u0cad\u0cb5\u0ca4\u0c83 \u0965 \u0cef \u0965", "malayalam": "\u0d05\u0d15\u0d41\u0d24\u0d4b\u0d2d\u0d2f\u0d2e\u0d47\u0d24\u0d26\u0d28\u0d47\u0d15\u0d26\u0d3f\u0d35\u0d02 \u0d1c\u0d28\u0d24\u0d4b\u0d2a\u0d15\u0d43\u0d24\u0d02 \u0d38\u0d24\u0d24\u0d02 \u0d2d\u0d1c\u0d24\u0d3e\u0d2e\u0d4d \u0964\n\u0d2a\u0d30\u0d2e\u0d02 \u0d2a\u0d26\u0d2e\u0d3e\u0d24\u0d4d\u0d2e\u0d35\u0d3f\u0d26\u0d4b \u0d35\u0d3f\u0d26\u0d41\u0d37\u0d03 \u0d36\u0d30\u0d23\u0d02 \u0d35\u0d43\u0d37\u0d36\u0d48\u0d32\u0d2a\u0d24\u0d47\u0d30\u0d4d\u0d2d\u0d35\u0d24\u0d03 \u0965 \u0d6f \u0965", "iast": "akutobhayametadanekadiva\u1e43 janatopak\u1e5bta\u1e43 satata\u1e43 bhajat\u0101m |\nparama\u1e43 padam\u0101tmavido vidu\u1e63a\u1e25 \u015bara\u1e47a\u1e43 v\u1e5b\u1e63a\u015bailapaterbhavata\u1e25 || 9 ||"},
        draftTranslation: "Bestowing absolute fearlessness, heavenly bliss, and supreme welfare upon those who constantly adore Thee! For self-realized souls knowing the Supreme Truth, Thy refuge alone is the highest transcendental abode (paramam padam), O Lord of Vrishabhachala!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 39,
        devanagariText: "\u0935\u093f\u092e\u0932\u093e\u092d\u0930\u0923\u0948\u0930\u0941\u092a\u0936\u094b\u092d\u093f\u0924\u092f\u094b\u0903 \u0915\u092e\u0932\u093e\u0915\u0930\u0915\u093e\u0928\u094d\u0924\u093f\u0938\u092e\u093e\u0939\u0924\u092f\u094b\u0903 \u0964\n\u0915\u092e\u0932\u093e\u092a\u0924\u093f\u092a\u093e\u0926\u092f\u0941\u0917\u0902 \u092d\u091c\u0924\u094b \u0928 \u092d\u092f\u0902 \u0928 \u092d\u092f\u0902 \u0928\u0930\u0915\u0938\u094d\u092f \u0915\u0926\u093e \u0965 \u0967\u0966 \u0965",
        iastText: "vimal\u0101bhara\u1e47air-upa\u015b\u014dbhitay\u014d\u1e25 kamal\u0101kara-k\u0101nti-sam\u0101hatay\u014d\u1e25 .\nkamal\u0101pati-p\u0101da-yuga\u1e41 bhajato na bhaya\u1e41 na bhaya\u1e41 narakasya kad\u0101 .. 10 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c35\u0c3f\u0c2e\u0c32\u0c3e\u0c2d\u0c30\u0c23\u0c48\u0c30\u0c41\u0c2a\u0c36\u0c4b\u0c2d\u0c3f\u0c24\u0c2f\u0c4b\u0c03 \u0c15\u0c2e\u0c32\u0c3e\u0c15\u0c30\u0c15\u0c3e\u0c28\u0c4d\u0c24\u0c3f\u0c38\u0c2e\u0c3e\u0c39\u0c24\u0c2f\u0c4b\u0c03 \u0964\n\u0c15\u0c2e\u0c32\u0c3e\u0c2a\u0c24\u0c3f\u0c2a\u0c3e\u0c26\u0c2f\u0c41\u0c17\u0c02 \u0c2d\u0c1c\u0c24\u0c4b \u0c28 \u0c2d\u0c2f\u0c02 \u0c28 \u0c2d\u0c2f\u0c02 \u0c28\u0c30\u0c15\u0c38\u0c4d\u0c2f \u0c15\u0c26\u0c3e \u0965 \u0c67\u0c66 \u0965", "tamil": "\u0bb5\u0bbf\u0bae\u0bb2\u0bbe\u0baa\u0bb0\u0ba3\u0bc8\u0bb0\u0bc1\u0baa\u0bb6\u0bcb\u0baa\u0bbf\u0ba4\u0baf\u0bcb\u0b83 \u0b95\u0bae\u0bb2\u0bbe\u0b95\u0bb0\u0b95\u0bbe\u0ba8\u0bcd\u0ba4\u0bbf\u0bb8\u0bae\u0bbe\u0bb9\u0ba4\u0baf\u0bcb\u0b83 \u0964\n\u0b95\u0bae\u0bb2\u0bbe\u0baa\u0ba4\u0bbf\u0baa\u0bbe\u0ba4\u0baf\u0bc1\u0b95\u0bae\u0bcd \u0baa\u0b9c\u0ba4\u0bcb \u0ba8 \u0baa\u0baf\u0bae\u0bcd \u0ba8 \u0baa\u0baf\u0bae\u0bcd \u0ba8\u0bb0\u0b95\u0bb8\u0bcd\u0baf \u0b95\u0ba4\u0bbe \u0965 \u0be7\u0be6 \u0965", "kannada": "\u0cb5\u0cbf\u0cae\u0cb2\u0cbe\u0cad\u0cb0\u0ca3\u0cc8\u0cb0\u0cc1\u0caa\u0cb6\u0ccb\u0cad\u0cbf\u0ca4\u0caf\u0ccb\u0c83 \u0c95\u0cae\u0cb2\u0cbe\u0c95\u0cb0\u0c95\u0cbe\u0ca8\u0ccd\u0ca4\u0cbf\u0cb8\u0cae\u0cbe\u0cb9\u0ca4\u0caf\u0ccb\u0c83 \u0964\n\u0c95\u0cae\u0cb2\u0cbe\u0caa\u0ca4\u0cbf\u0caa\u0cbe\u0ca6\u0caf\u0cc1\u0c97\u0c82 \u0cad\u0c9c\u0ca4\u0ccb \u0ca8 \u0cad\u0caf\u0c82 \u0ca8 \u0cad\u0caf\u0c82 \u0ca8\u0cb0\u0c95\u0cb8\u0ccd\u0caf \u0c95\u0ca6\u0cbe \u0965 \u0ce7\u0ce6 \u0965", "malayalam": "\u0d35\u0d3f\u0d2e\u0d32\u0d3e\u0d2d\u0d30\u0d23\u0d48\u0d30\u0d41\u0d2a\u0d36\u0d4b\u0d2d\u0d3f\u0d24\u0d2f\u0d4b\u0d03 \u0d15\u0d2e\u0d32\u0d3e\u0d15\u0d30\u0d15\u0d3e\u0d28\u0d4d\u0d24\u0d3f\u0d38\u0d2e\u0d3e\u0d39\u0d24\u0d2f\u0d4b\u0d03 \u0964\n\u0d15\u0d2e\u0d32\u0d3e\u0d2a\u0d24\u0d3f\u0d2a\u0d3e\u0d26\u0d2f\u0d41\u0d17\u0d02 \u0d2d\u0d1c\u0d24\u0d4b \u0d28 \u0d2d\u0d2f\u0d02 \u0d28 \u0d2d\u0d2f\u0d02 \u0d28\u0d30\u0d15\u0d38\u0d4d\u0d2f \u0d15\u0d26\u0d3e \u0965 \u0d67\u0d66 \u0965", "iast": "vimal\u0101bhara\u1e47airupa\u015bobhitayo\u1e25 kamal\u0101karak\u0101ntisam\u0101hatayo\u1e25 |\nkamal\u0101patip\u0101dayuga\u1e43 bhajato na bhaya\u1e43 na bhaya\u1e43 narakasya kad\u0101 || 10 ||"},
        draftTranslation: "For the soul who adores the twin lotus feet of the Consort of Kamala, resplendent with immaculate celestial ornaments and outshining the effulgence of blooming lotus clusters \u2014 never is there any fear, never any fear of hell whatsoever!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 40,
        devanagariText: "\u092f\u0926\u093f \u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u092e\u0939\u093f\u092e\u093e\u0924\u093f\u0936\u092f\u0902 \u092f\u0926\u093f \u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u092a\u0926\u092a\u0919\u094d\u0915\u091c\u092f\u0941\u0917\u094d\u092e\u092e\u094d \u0964\n\u0905\u0935\u093f\u0936\u0919\u094d\u0915\u093f\u0924\u092e\u0947\u0924\u093f \u092e\u0928\u094b \u092e\u0928\u0941\u091c\u0903 \u0938 \u092a\u0930\u0902 \u092a\u0926\u092e\u092d\u094d\u092f\u0941\u092a\u0948\u0924\u093f \u0936\u0941\u092d\u092e\u094d \u0965 \u0967\u0967 \u0965",
        iastText: "yadi v\u0113\u1e45ka\u1e6d\u0113\u015ba-mahim\u0101ti\u015baya\u1e41 yadi v\u0113\u1e45ka\u1e6d\u0113\u015ba-pada-pa\u1e45kaja-yugmam .\navi\u015ba\u1e45kitam-\u0113ti man\u014d manuja\u1e25 sa para\u1e41 padam-abhyupaiti \u015bubham .. 11 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2f\u0c26\u0c3f \u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c2e\u0c39\u0c3f\u0c2e\u0c3e\u0c24\u0c3f\u0c36\u0c2f\u0c02 \u0c2f\u0c26\u0c3f \u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c2a\u0c26\u0c2a\u0c19\u0c4d\u0c15\u0c1c\u0c2f\u0c41\u0c17\u0c4d\u0c2e\u0c2e\u0c4d \u0964\n\u0c05\u0c35\u0c3f\u0c36\u0c19\u0c4d\u0c15\u0c3f\u0c24\u0c2e\u0c47\u0c24\u0c3f \u0c2e\u0c28\u0c4b \u0c2e\u0c28\u0c41\u0c1c\u0c03 \u0c38 \u0c2a\u0c30\u0c02 \u0c2a\u0c26\u0c2e\u0c2d\u0c4d\u0c2f\u0c41\u0c2a\u0c48\u0c24\u0c3f \u0c36\u0c41\u0c2d\u0c2e\u0c4d \u0965 \u0c67\u0c67 \u0965", "tamil": "\u0baf\u0ba4\u0bbf \u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0bae\u0bb9\u0bbf\u0bae\u0bbe\u0ba4\u0bbf\u0bb6\u0baf\u0bae\u0bcd \u0baf\u0ba4\u0bbf \u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0baa\u0ba4\u0baa\u0b99\u0bcd\u0b95\u0b9c\u0baf\u0bc1\u0b95\u0bcd\u0bae\u0bae\u0bcd \u0964\n\u0b85\u0bb5\u0bbf\u0bb6\u0b99\u0bcd\u0b95\u0bbf\u0ba4\u0bae\u0bc7\u0ba4\u0bbf \u0bae\u0ba8\u0bcb \u0bae\u0ba8\u0bc1\u0b9c\u0b83 \u0bb8 \u0baa\u0bb0\u0bae\u0bcd \u0baa\u0ba4\u0bae\u0baa\u0bcd\u0baf\u0bc1\u0baa\u0bc8\u0ba4\u0bbf \u0bb6\u0bc1\u0baa\u0bae\u0bcd \u0965 \u0be7\u0be7 \u0965", "kannada": "\u0caf\u0ca6\u0cbf \u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0cae\u0cb9\u0cbf\u0cae\u0cbe\u0ca4\u0cbf\u0cb6\u0caf\u0c82 \u0caf\u0ca6\u0cbf \u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0caa\u0ca6\u0caa\u0c99\u0ccd\u0c95\u0c9c\u0caf\u0cc1\u0c97\u0ccd\u0cae\u0cae\u0ccd \u0964\n\u0c85\u0cb5\u0cbf\u0cb6\u0c99\u0ccd\u0c95\u0cbf\u0ca4\u0cae\u0cc7\u0ca4\u0cbf \u0cae\u0ca8\u0ccb \u0cae\u0ca8\u0cc1\u0c9c\u0c83 \u0cb8 \u0caa\u0cb0\u0c82 \u0caa\u0ca6\u0cae\u0cad\u0ccd\u0caf\u0cc1\u0caa\u0cc8\u0ca4\u0cbf \u0cb6\u0cc1\u0cad\u0cae\u0ccd \u0965 \u0ce7\u0ce7 \u0965", "malayalam": "\u0d2f\u0d26\u0d3f \u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d2e\u0d39\u0d3f\u0d2e\u0d3e\u0d24\u0d3f\u0d36\u0d2f\u0d02 \u0d2f\u0d26\u0d3f \u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d2a\u0d26\u0d2a\u0d19\u0d4d\u0d15\u0d1c\u0d2f\u0d41\u0d17\u0d4d\u0d2e\u0d2e\u0d4d \u0964\n\u0d05\u0d35\u0d3f\u0d36\u0d19\u0d4d\u0d15\u0d3f\u0d24\u0d2e\u0d47\u0d24\u0d3f \u0d2e\u0d28\u0d4b \u0d2e\u0d28\u0d41\u0d1c\u0d03 \u0d38 \u0d2a\u0d30\u0d02 \u0d2a\u0d26\u0d2e\u0d2d\u0d4d\u0d2f\u0d41\u0d2a\u0d48\u0d24\u0d3f \u0d36\u0d41\u0d2d\u0d2e\u0d4d \u0965 \u0d67\u0d67 \u0965", "iast": "yadi ve\u1e45ka\u1e6de\u015bamahim\u0101ti\u015baya\u1e43 yadi ve\u1e45ka\u1e6de\u015bapadapa\u1e45kajayugmam |\navi\u015ba\u1e45kitameti mano manuja\u1e25 sa para\u1e43 padamabhyupaiti \u015bubham || 11 ||"},
        draftTranslation: "If a human being's mind approaches the supreme glory of Lord Venkateswara and fixes itself unhesitatingly and without doubt upon His twin lotus feet \u2014 that mortal certainly attains the highest auspicious transcendental abode (Moksha)!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 41,
        devanagariText: "\u0908\u0936\u093e\u0928\u093e\u0902 \u091c\u0917\u0924\u094b\u093d\u0938\u094d\u092f \u0935\u0947\u0919\u094d\u0915\u091f\u092a\u0924\u0947\u0930\u094d\u0935\u093f\u0937\u094d\u0923\u094b\u0903 \u092a\u0930\u093e\u0902 \u092a\u094d\u0930\u0947\u092f\u0938\u0940\u0902\n\u0924\u0926\u094d\u0935\u0915\u094d\u0937\u0903\u0938\u094d\u0925\u0932\u0928\u093f\u0924\u094d\u092f\u0935\u093e\u0938\u0930\u0938\u093f\u0915\u093e\u0902 \u0924\u0924\u094d\u0915\u094d\u0937\u093e\u0928\u094d\u0924\u093f\u0938\u0902\u0935\u0930\u094d\u0927\u093f\u0928\u0940\u092e\u094d \u0964\n\u092a\u0926\u094d\u092e\u093e\u0932\u0919\u094d\u0915\u0943\u0924\u092a\u093e\u0923\u093f\u092a\u0932\u094d\u0932\u0935\u092f\u0941\u0917\u093e\u0902 \u092a\u0926\u094d\u092e\u093e\u0938\u0928\u0938\u094d\u0925\u093e\u0902 \u0936\u094d\u0930\u093f\u092f\u0902\n\u0935\u093e\u0924\u094d\u0938\u0932\u094d\u092f\u093e\u0926\u093f\u0917\u0941\u0923\u094b\u091c\u094d\u091c\u094d\u0935\u0932\u093e\u0902 \u092d\u0917\u0935\u0924\u0940\u0902 \u0935\u0928\u094d\u0926\u0947 \u091c\u0917\u0928\u094d\u092e\u093e\u0924\u0930\u092e\u094d \u0965 \u0967 \u0965",
        iastText: "\u012b\u015b\u0101n\u0101\u1e41 jagat\u014d\u2019sya v\u0113\u1e45ka\u1e6dapat\u0113r-vi\u1e63\u1e47\u014d\u1e25 par\u0101\u1e41 pr\u0113yas\u012b\u1e41\ntad-vak\u1e63asthala-nityav\u0101sa-rasik\u0101\u1e41 tat-k\u1e63\u0101nti-sa\u1e41vardhin\u012bm .\npadm\u0101la\u1e45k\u1e5bta-p\u0101\u1e47i-pallava-yug\u0101\u1e41 padm\u0101sanasth\u0101\u1e41 \u015briya\u1e41\nv\u0101tsaly\u0101di-gu\u1e47\u014djjval\u0101\u1e41 bhagavat\u012b\u1e41 vand\u0113 jagan-m\u0101taram .. 1 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c08\u0c36\u0c3e\u0c28\u0c3e\u0c02 \u0c1c\u0c17\u0c24\u0c4b\u0c3d\u0c38\u0c4d\u0c2f \u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c2a\u0c24\u0c47\u0c30\u0c4d\u0c35\u0c3f\u0c37\u0c4d\u0c23\u0c4b\u0c03 \u0c2a\u0c30\u0c3e\u0c02 \u0c2a\u0c4d\u0c30\u0c47\u0c2f\u0c38\u0c40\u0c02\n\u0c24\u0c26\u0c4d\u0c35\u0c15\u0c4d\u0c37\u0c03\u0c38\u0c4d\u0c25\u0c32\u0c28\u0c3f\u0c24\u0c4d\u0c2f\u0c35\u0c3e\u0c38\u0c30\u0c38\u0c3f\u0c15\u0c3e\u0c02 \u0c24\u0c24\u0c4d\u0c15\u0c4d\u0c37\u0c3e\u0c28\u0c4d\u0c24\u0c3f\u0c38\u0c02\u0c35\u0c30\u0c4d\u0c27\u0c3f\u0c28\u0c40\u0c2e\u0c4d \u0964\n\u0c2a\u0c26\u0c4d\u0c2e\u0c3e\u0c32\u0c19\u0c4d\u0c15\u0c43\u0c24\u0c2a\u0c3e\u0c23\u0c3f\u0c2a\u0c32\u0c4d\u0c32\u0c35\u0c2f\u0c41\u0c17\u0c3e\u0c02 \u0c2a\u0c26\u0c4d\u0c2e\u0c3e\u0c38\u0c28\u0c38\u0c4d\u0c25\u0c3e\u0c02 \u0c36\u0c4d\u0c30\u0c3f\u0c2f\u0c02\n\u0c35\u0c3e\u0c24\u0c4d\u0c38\u0c32\u0c4d\u0c2f\u0c3e\u0c26\u0c3f\u0c17\u0c41\u0c23\u0c4b\u0c1c\u0c4d\u0c1c\u0c4d\u0c35\u0c32\u0c3e\u0c02 \u0c2d\u0c17\u0c35\u0c24\u0c40\u0c02 \u0c35\u0c28\u0c4d\u0c26\u0c47 \u0c1c\u0c17\u0c28\u0c4d\u0c2e\u0c3e\u0c24\u0c30\u0c2e\u0c4d \u0965 \u0c67 \u0965", "tamil": "\u0b88\u0bb6\u0bbe\u0ba8\u0bbe\u0bae\u0bcd \u0b9c\u0b95\u0ba4\u0bcb\u093d\u0bb8\u0bcd\u0baf \u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0baa\u0ba4\u0bc7\u0bb0\u0bcd\u0bb5\u0bbf\u0bb7\u0bcd\u0ba3\u0bcb\u0b83 \u0baa\u0bb0\u0bbe\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0bc7\u0baf\u0bb8\u0bc0\u0bae\u0bcd\n\u0ba4\u0ba4\u0bcd\u0bb5\u0b95\u0bcd\u0bb7\u0b83\u0bb8\u0bcd\u0ba4\u0bb2\u0ba8\u0bbf\u0ba4\u0bcd\u0baf\u0bb5\u0bbe\u0bb8\u0bb0\u0bb8\u0bbf\u0b95\u0bbe\u0bae\u0bcd \u0ba4\u0ba4\u0bcd\u0b95\u0bcd\u0bb7\u0bbe\u0ba8\u0bcd\u0ba4\u0bbf\u0bb8\u0bae\u0bcd\u0bb5\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bc0\u0bae\u0bcd \u0964\n\u0baa\u0ba4\u0bcd\u0bae\u0bbe\u0bb2\u0b99\u0bcd\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0baa\u0bbe\u0ba3\u0bbf\u0baa\u0bb2\u0bcd\u0bb2\u0bb5\u0baf\u0bc1\u0b95\u0bbe\u0bae\u0bcd \u0baa\u0ba4\u0bcd\u0bae\u0bbe\u0bb8\u0ba8\u0bb8\u0bcd\u0ba4\u0bbe\u0bae\u0bcd \u0bb6\u0bcd\u0bb0\u0bbf\u0baf\u0bae\u0bcd\n\u0bb5\u0bbe\u0ba4\u0bcd\u0bb8\u0bb2\u0bcd\u0baf\u0bbe\u0ba4\u0bbf\u0b95\u0bc1\u0ba3\u0bcb\u0b9c\u0bcd\u0b9c\u0bcd\u0bb5\u0bb2\u0bbe\u0bae\u0bcd \u0baa\u0b95\u0bb5\u0ba4\u0bc0\u0bae\u0bcd \u0bb5\u0ba8\u0bcd\u0ba4\u0bc7 \u0b9c\u0b95\u0ba8\u0bcd\u0bae\u0bbe\u0ba4\u0bb0\u0bae\u0bcd \u0965 \u0be7 \u0965", "kannada": "\u0c88\u0cb6\u0cbe\u0ca8\u0cbe\u0c82 \u0c9c\u0c97\u0ca4\u0ccb\u0cbd\u0cb8\u0ccd\u0caf \u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0caa\u0ca4\u0cc7\u0cb0\u0ccd\u0cb5\u0cbf\u0cb7\u0ccd\u0ca3\u0ccb\u0c83 \u0caa\u0cb0\u0cbe\u0c82 \u0caa\u0ccd\u0cb0\u0cc7\u0caf\u0cb8\u0cc0\u0c82\n\u0ca4\u0ca6\u0ccd\u0cb5\u0c95\u0ccd\u0cb7\u0c83\u0cb8\u0ccd\u0ca5\u0cb2\u0ca8\u0cbf\u0ca4\u0ccd\u0caf\u0cb5\u0cbe\u0cb8\u0cb0\u0cb8\u0cbf\u0c95\u0cbe\u0c82 \u0ca4\u0ca4\u0ccd\u0c95\u0ccd\u0cb7\u0cbe\u0ca8\u0ccd\u0ca4\u0cbf\u0cb8\u0c82\u0cb5\u0cb0\u0ccd\u0ca7\u0cbf\u0ca8\u0cc0\u0cae\u0ccd \u0964\n\u0caa\u0ca6\u0ccd\u0cae\u0cbe\u0cb2\u0c99\u0ccd\u0c95\u0cc3\u0ca4\u0caa\u0cbe\u0ca3\u0cbf\u0caa\u0cb2\u0ccd\u0cb2\u0cb5\u0caf\u0cc1\u0c97\u0cbe\u0c82 \u0caa\u0ca6\u0ccd\u0cae\u0cbe\u0cb8\u0ca8\u0cb8\u0ccd\u0ca5\u0cbe\u0c82 \u0cb6\u0ccd\u0cb0\u0cbf\u0caf\u0c82\n\u0cb5\u0cbe\u0ca4\u0ccd\u0cb8\u0cb2\u0ccd\u0caf\u0cbe\u0ca6\u0cbf\u0c97\u0cc1\u0ca3\u0ccb\u0c9c\u0ccd\u0c9c\u0ccd\u0cb5\u0cb2\u0cbe\u0c82 \u0cad\u0c97\u0cb5\u0ca4\u0cc0\u0c82 \u0cb5\u0ca8\u0ccd\u0ca6\u0cc7 \u0c9c\u0c97\u0ca8\u0ccd\u0cae\u0cbe\u0ca4\u0cb0\u0cae\u0ccd \u0965 \u0ce7 \u0965", "malayalam": "\u0d08\u0d36\u0d3e\u0d28\u0d3e\u0d02 \u0d1c\u0d17\u0d24\u0d4b\u0d3d\u0d38\u0d4d\u0d2f \u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d2a\u0d24\u0d47\u0d30\u0d4d\u0d35\u0d3f\u0d37\u0d4d\u0d23\u0d4b\u0d03 \u0d2a\u0d30\u0d3e\u0d02 \u0d2a\u0d4d\u0d30\u0d47\u0d2f\u0d38\u0d40\u0d02\n\u0d24\u0d26\u0d4d\u0d35\u0d15\u0d4d\u0d37\u0d03\u0d38\u0d4d\u0d25\u0d32\u0d28\u0d3f\u0d24\u0d4d\u0d2f\u0d35\u0d3e\u0d38\u0d30\u0d38\u0d3f\u0d15\u0d3e\u0d02 \u0d24\u0d24\u0d4d\u0d15\u0d4d\u0d37\u0d3e\u0d28\u0d4d\u0d24\u0d3f\u0d38\u0d02\u0d35\u0d30\u0d4d\u0d27\u0d3f\u0d28\u0d40\u0d2e\u0d4d \u0964\n\u0d2a\u0d26\u0d4d\u0d2e\u0d3e\u0d32\u0d19\u0d4d\u0d15\u0d43\u0d24\u0d2a\u0d3e\u0d23\u0d3f\u0d2a\u0d32\u0d4d\u0d32\u0d35\u0d2f\u0d41\u0d17\u0d3e\u0d02 \u0d2a\u0d26\u0d4d\u0d2e\u0d3e\u0d38\u0d28\u0d38\u0d4d\u0d25\u0d3e\u0d02 \u0d36\u0d4d\u0d30\u0d3f\u0d2f\u0d02\n\u0d35\u0d3e\u0d24\u0d4d\u0d38\u0d32\u0d4d\u0d2f\u0d3e\u0d26\u0d3f\u0d17\u0d41\u0d23\u0d4b\u0d1c\u0d4d\u0d1c\u0d4d\u0d35\u0d32\u0d3e\u0d02 \u0d2d\u0d17\u0d35\u0d24\u0d40\u0d02 \u0d35\u0d28\u0d4d\u0d26\u0d47 \u0d1c\u0d17\u0d28\u0d4d\u0d2e\u0d3e\u0d24\u0d30\u0d2e\u0d4d \u0965 \u0d67 \u0965", "iast": "\u012b\u015b\u0101n\u0101\u1e43 jagato'sya ve\u1e45ka\u1e6dapatervi\u1e63\u1e47o\u1e25 par\u0101\u1e43 preyas\u012b\u1e43\ntadvak\u1e63a\u1e25sthalanityav\u0101sarasik\u0101\u1e43 tatk\u1e63\u0101ntisa\u1e43vardhin\u012bm |\npadm\u0101la\u1e45k\u1e5btap\u0101\u1e47ipallavayug\u0101\u1e43 padm\u0101sanasth\u0101\u1e43 \u015briya\u1e43\nv\u0101tsaly\u0101digu\u1e47ojjval\u0101\u1e43 bhagavat\u012b\u1e43 vande jaganm\u0101taram || 1 ||"},
        draftTranslation: "I bow to Goddess Sri (Mahalakshmi), the Mother of the Universe, Supreme Sovereign of this entire creation, deeply beloved consort of Lord Vishnu (Venkateswara), who delights in eternally abiding upon His chest, who heightens His forbearance and compassion toward devotees, whose sprout-like hands are adorned with lotuses, who is seated upon a lotus, and who shines resplendent with maternal affection and divine qualities.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 42,
        devanagariText: "\u0936\u094d\u0930\u0940\u092e\u0928\u094d \u0915\u0943\u092a\u093e\u091c\u0932\u0928\u093f\u0927\u0947 \u0915\u0943\u0924\u0938\u0930\u094d\u0935\u0932\u094b\u0915\n\u0938\u0930\u094d\u0935\u091c\u094d\u091e \u0936\u0915\u094d\u0924 \u0928\u0924\u0935\u0924\u094d\u0938\u0932 \u0938\u0930\u094d\u0935\u0936\u0947\u0937\u093f\u0928\u094d \u0964\n\u0938\u094d\u0935\u093e\u092e\u093f\u0928\u094d \u0938\u0941\u0936\u0940\u0932 \u0938\u0941\u0932\u092d\u093e\u0936\u094d\u0930\u093f\u0924\u092a\u093e\u0930\u093f\u091c\u093e\u0924\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u0968 \u0965",
        iastText: "\u015br\u012bman k\u1e5bp\u0101-jala-nidhe k\u1e5bta-sarva-l\u014dka\nsarvaj\u00f1a \u015bakta nata-vatsala sarva-\u015b\u0113\u1e63in .\nsv\u0101min su\u015b\u012bla sulabh\u0101\u015brita-p\u0101rij\u0101ta\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 2 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c36\u0c4d\u0c30\u0c40\u0c2e\u0c28\u0c4d \u0c15\u0c43\u0c2a\u0c3e\u0c1c\u0c32\u0c28\u0c3f\u0c27\u0c47 \u0c15\u0c43\u0c24\u0c38\u0c30\u0c4d\u0c35\u0c32\u0c4b\u0c15\n\u0c38\u0c30\u0c4d\u0c35\u0c1c\u0c4d\u0c1e \u0c36\u0c15\u0c4d\u0c24 \u0c28\u0c24\u0c35\u0c24\u0c4d\u0c38\u0c32 \u0c38\u0c30\u0c4d\u0c35\u0c36\u0c47\u0c37\u0c3f\u0c28\u0c4d \u0964\n\u0c38\u0c4d\u0c35\u0c3e\u0c2e\u0c3f\u0c28\u0c4d \u0c38\u0c41\u0c36\u0c40\u0c32 \u0c38\u0c41\u0c32\u0c2d\u0c3e\u0c36\u0c4d\u0c30\u0c3f\u0c24\u0c2a\u0c3e\u0c30\u0c3f\u0c1c\u0c3e\u0c24\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c68 \u0965", "tamil": "\u0bb6\u0bcd\u0bb0\u0bc0\u0bae\u0ba8\u0bcd \u0b95\u0bcd\u0bb0\u0bc1'\u0baa\u0bbe\u0b9c\u0bb2\u0ba8\u0bbf\u0ba4\u0bc7 \u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0bb8\u0bb0\u0bcd\u0bb5\u0bb2\u0bcb\u0b95\n\u0bb8\u0bb0\u0bcd\u0bb5\u0b9c\u0bcd\u0b9e \u0bb6\u0b95\u0bcd\u0ba4 \u0ba8\u0ba4\u0bb5\u0ba4\u0bcd\u0bb8\u0bb2 \u0bb8\u0bb0\u0bcd\u0bb5\u0bb6\u0bc7\u0bb7\u0bbf\u0ba8\u0bcd \u0964\n\u0bb8\u0bcd\u0bb5\u0bbe\u0bae\u0bbf\u0ba8\u0bcd \u0bb8\u0bc1\u0bb6\u0bc0\u0bb2 \u0bb8\u0bc1\u0bb2\u0baa\u0bbe\u0bb6\u0bcd\u0bb0\u0bbf\u0ba4\u0baa\u0bbe\u0bb0\u0bbf\u0b9c\u0bbe\u0ba4\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0be8 \u0965", "kannada": "\u0cb6\u0ccd\u0cb0\u0cc0\u0cae\u0ca8\u0ccd \u0c95\u0cc3\u0caa\u0cbe\u0c9c\u0cb2\u0ca8\u0cbf\u0ca7\u0cc7 \u0c95\u0cc3\u0ca4\u0cb8\u0cb0\u0ccd\u0cb5\u0cb2\u0ccb\u0c95\n\u0cb8\u0cb0\u0ccd\u0cb5\u0c9c\u0ccd\u0c9e \u0cb6\u0c95\u0ccd\u0ca4 \u0ca8\u0ca4\u0cb5\u0ca4\u0ccd\u0cb8\u0cb2 \u0cb8\u0cb0\u0ccd\u0cb5\u0cb6\u0cc7\u0cb7\u0cbf\u0ca8\u0ccd \u0964\n\u0cb8\u0ccd\u0cb5\u0cbe\u0cae\u0cbf\u0ca8\u0ccd \u0cb8\u0cc1\u0cb6\u0cc0\u0cb2 \u0cb8\u0cc1\u0cb2\u0cad\u0cbe\u0cb6\u0ccd\u0cb0\u0cbf\u0ca4\u0caa\u0cbe\u0cb0\u0cbf\u0c9c\u0cbe\u0ca4\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0ce8 \u0965", "malayalam": "\u0d36\u0d4d\u0d30\u0d40\u0d2e\u0d28\u0d4d \u0d15\u0d43\u0d2a\u0d3e\u0d1c\u0d32\u0d28\u0d3f\u0d27\u0d47 \u0d15\u0d43\u0d24\u0d38\u0d30\u0d4d\u0d35\u0d32\u0d4b\u0d15\n\u0d38\u0d30\u0d4d\u0d35\u0d1c\u0d4d\u0d1e \u0d36\u0d15\u0d4d\u0d24 \u0d28\u0d24\u0d35\u0d24\u0d4d\u0d38\u0d32 \u0d38\u0d30\u0d4d\u0d35\u0d36\u0d47\u0d37\u0d3f\u0d28\u0d4d \u0964\n\u0d38\u0d4d\u0d35\u0d3e\u0d2e\u0d3f\u0d28\u0d4d \u0d38\u0d41\u0d36\u0d40\u0d32 \u0d38\u0d41\u0d32\u0d2d\u0d3e\u0d36\u0d4d\u0d30\u0d3f\u0d24\u0d2a\u0d3e\u0d30\u0d3f\u0d1c\u0d3e\u0d24\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d68 \u0965", "iast": "\u015br\u012bman k\u1e5bp\u0101jalanidhe k\u1e5btasarvaloka\nsarvaj\u00f1a \u015bakta natavatsala sarva\u015be\u1e63in |\nsv\u0101min su\u015b\u012bla sulabh\u0101\u015britap\u0101rij\u0101ta\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 2 ||"},
        draftTranslation: "O Sriman, ocean of mercy, creator of all worlds, omniscient, all-powerful, affectionate to those who surrender, sovereign lord of all creation, master endowed with noble disposition, easily accessible wish-granting Parijata tree to devotees \u2014 I surrender completely at the holy lotus feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 43,
        devanagariText: "\u0906\u0928\u0942\u092a\u0941\u0930\u093e\u0930\u094d\u092a\u093f\u0924\u0938\u0941\u091c\u093e\u0924\u0938\u0941\u0917\u0928\u094d\u0927\u093f\u092a\u0941\u0937\u094d\u092a-\n\u0938\u094c\u0930\u092d\u094d\u092f\u0938\u094c\u0930\u092d\u0915\u0930\u094c \u0938\u092e\u0938\u0928\u094d\u0928\u093f\u0935\u0947\u0936\u094c \u0964\n\u0938\u094c\u092e\u094d\u092f\u094c \u0938\u0926\u093e\u0928\u0941\u092d\u0935\u0947\u093d\u092a\u093f \u0928\u0935\u093e\u0928\u0941\u092d\u093e\u0935\u094d\u092f\u094c\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u0969 \u0965",
        iastText: "\u0101n\u016bpur\u0101rpita-suj\u0101ta-sugandhi-pu\u1e63pa-\nsaurabhya-saurabha-karau sama-sanniv\u0113\u015bau .\nsaumyau sad\u0101nubhav\u0113\u2019pi nav\u0101nubh\u0101vyau\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 3 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c06\u0c28\u0c42\u0c2a\u0c41\u0c30\u0c3e\u0c30\u0c4d\u0c2a\u0c3f\u0c24\u0c38\u0c41\u0c1c\u0c3e\u0c24\u0c38\u0c41\u0c17\u0c28\u0c4d\u0c27\u0c3f\u0c2a\u0c41\u0c37\u0c4d\u0c2a-\n\u0c38\u0c4c\u0c30\u0c2d\u0c4d\u0c2f\u0c38\u0c4c\u0c30\u0c2d\u0c15\u0c30\u0c4c \u0c38\u0c2e\u0c38\u0c28\u0c4d\u0c28\u0c3f\u0c35\u0c47\u0c36\u0c4c \u0964\n\u0c38\u0c4c\u0c2e\u0c4d\u0c2f\u0c4c \u0c38\u0c26\u0c3e\u0c28\u0c41\u0c2d\u0c35\u0c47\u0c3d\u0c2a\u0c3f \u0c28\u0c35\u0c3e\u0c28\u0c41\u0c2d\u0c3e\u0c35\u0c4d\u0c2f\u0c4c\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c69 \u0965", "tamil": "\u0b86\u0ba8\u0bc2\u0baa\u0bc1\u0bb0\u0bbe\u0bb0\u0bcd\u0baa\u0bbf\u0ba4\u0bb8\u0bc1\u0b9c\u0bbe\u0ba4\u0bb8\u0bc1\u0b95\u0ba8\u0bcd\u0ba4\u0bbf\u0baa\u0bc1\u0bb7\u0bcd\u0baa-\n\u0bb8\u0bcc\u0bb0\u0baa\u0bcd\u0baf\u0bb8\u0bcc\u0bb0\u0baa\u0b95\u0bb0\u0bcc \u0bb8\u0bae\u0bb8\u0ba8\u0bcd\u0ba8\u0bbf\u0bb5\u0bc7\u0bb6\u0bcc \u0964\n\u0bb8\u0bcc\u0bae\u0bcd\u0baf\u0bcc \u0bb8\u0ba4\u0bbe\u0ba8\u0bc1\u0baa\u0bb5\u0bc7\u093d\u0baa\u0bbf \u0ba8\u0bb5\u0bbe\u0ba8\u0bc1\u0baa\u0bbe\u0bb5\u0bcd\u0baf\u0bcc\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0be9 \u0965", "kannada": "\u0c86\u0ca8\u0cc2\u0caa\u0cc1\u0cb0\u0cbe\u0cb0\u0ccd\u0caa\u0cbf\u0ca4\u0cb8\u0cc1\u0c9c\u0cbe\u0ca4\u0cb8\u0cc1\u0c97\u0ca8\u0ccd\u0ca7\u0cbf\u0caa\u0cc1\u0cb7\u0ccd\u0caa-\n\u0cb8\u0ccc\u0cb0\u0cad\u0ccd\u0caf\u0cb8\u0ccc\u0cb0\u0cad\u0c95\u0cb0\u0ccc \u0cb8\u0cae\u0cb8\u0ca8\u0ccd\u0ca8\u0cbf\u0cb5\u0cc7\u0cb6\u0ccc \u0964\n\u0cb8\u0ccc\u0cae\u0ccd\u0caf\u0ccc \u0cb8\u0ca6\u0cbe\u0ca8\u0cc1\u0cad\u0cb5\u0cc7\u0cbd\u0caa\u0cbf \u0ca8\u0cb5\u0cbe\u0ca8\u0cc1\u0cad\u0cbe\u0cb5\u0ccd\u0caf\u0ccc\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0ce9 \u0965", "malayalam": "\u0d06\u0d28\u0d42\u0d2a\u0d41\u0d30\u0d3e\u0d30\u0d4d\u0d2a\u0d3f\u0d24\u0d38\u0d41\u0d1c\u0d3e\u0d24\u0d38\u0d41\u0d17\u0d28\u0d4d\u0d27\u0d3f\u0d2a\u0d41\u0d37\u0d4d\u0d2a-\n\u0d38\u0d4c\u0d30\u0d2d\u0d4d\u0d2f\u0d38\u0d4c\u0d30\u0d2d\u0d15\u0d30\u0d4c \u0d38\u0d2e\u0d38\u0d28\u0d4d\u0d28\u0d3f\u0d35\u0d47\u0d36\u0d4c \u0964\n\u0d38\u0d4c\u0d2e\u0d4d\u0d2f\u0d4c \u0d38\u0d26\u0d3e\u0d28\u0d41\u0d2d\u0d35\u0d47\u0d3d\u0d2a\u0d3f \u0d28\u0d35\u0d3e\u0d28\u0d41\u0d2d\u0d3e\u0d35\u0d4d\u0d2f\u0d4c\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d69 \u0965", "iast": "\u0101n\u016bpur\u0101rpitasuj\u0101tasugandhipu\u1e63pa-\nsaurabhyasaurabhakarau samasannive\u015bau |\nsaumyau sad\u0101nubhave'pi nav\u0101nubh\u0101vyau\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 3 ||"},
        draftTranslation: "Adorned up to the golden anklets with fragrant blossoms that enhance the sublime perfume of the feet themselves, symmetrically fashioned in perfect divine proportion, exquisitely gentle, ever revealing fresh divine nectar however constantly experienced \u2014 I surrender at the holy feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 44,
        devanagariText: "\u0938\u0926\u094d\u092f\u094b\u0935\u093f\u0915\u093e\u0936\u093f\u0938\u092e\u0941\u0926\u093f\u0924\u094d\u0935\u0930\u0938\u093e\u0928\u094d\u0926\u094d\u0930\u0930\u093e\u0917-\n\u0938\u094c\u0930\u092d\u094d\u092f\u0928\u093f\u0930\u094d\u092d\u0930\u0938\u0930\u094b\u0930\u0941\u0939\u0938\u093e\u092e\u094d\u092f\u0935\u093e\u0930\u094d\u0924\u093e\u092e\u094d \u0964\n\u0938\u092e\u094d\u092f\u0915\u094d\u0937\u0941 \u0938\u093e\u0939\u0938\u092a\u0926\u0947\u0937\u0941 \u0935\u093f\u0932\u0947\u0916\u092f\u0928\u094d\u0924\u094c\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u096a \u0965",
        iastText: "sady\u014d-vik\u0101\u015bi-samuditvara-s\u0101ndra-r\u0101ga-\nsaurabhya-nirbhara-sar\u014druha-s\u0101mya-v\u0101rt\u0101m .\nsamyak\u1e63u s\u0101hasa-pad\u0113\u1e63u vil\u0113khayantau\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 4 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c38\u0c26\u0c4d\u0c2f\u0c4b\u0c35\u0c3f\u0c15\u0c3e\u0c36\u0c3f\u0c38\u0c2e\u0c41\u0c26\u0c3f\u0c24\u0c4d\u0c35\u0c30\u0c38\u0c3e\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c30\u0c3e\u0c17-\n\u0c38\u0c4c\u0c30\u0c2d\u0c4d\u0c2f\u0c28\u0c3f\u0c30\u0c4d\u0c2d\u0c30\u0c38\u0c30\u0c4b\u0c30\u0c41\u0c39\u0c38\u0c3e\u0c2e\u0c4d\u0c2f\u0c35\u0c3e\u0c30\u0c4d\u0c24\u0c3e\u0c2e\u0c4d \u0964\n\u0c38\u0c2e\u0c4d\u0c2f\u0c15\u0c4d\u0c37\u0c41 \u0c38\u0c3e\u0c39\u0c38\u0c2a\u0c26\u0c47\u0c37\u0c41 \u0c35\u0c3f\u0c32\u0c47\u0c16\u0c2f\u0c28\u0c4d\u0c24\u0c4c\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c6a \u0965", "tamil": "\u0bb8\u0ba4\u0bcd\u0baf\u0bcb\u0bb5\u0bbf\u0b95\u0bbe\u0bb6\u0bbf\u0bb8\u0bae\u0bc1\u0ba4\u0bbf\u0ba4\u0bcd\u0bb5\u0bb0\u0bb8\u0bbe\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bb0\u0bbe\u0b95-\n\u0bb8\u0bcc\u0bb0\u0baa\u0bcd\u0baf\u0ba8\u0bbf\u0bb0\u0bcd\u0baa\u0bb0\u0bb8\u0bb0\u0bcb\u0bb0\u0bc1\u0bb9\u0bb8\u0bbe\u0bae\u0bcd\u0baf\u0bb5\u0bbe\u0bb0\u0bcd\u0ba4\u0bbe\u0bae\u0bcd \u0964\n\u0bb8\u0bae\u0bcd\u0baf\u0b95\u0bcd\u0bb7\u0bc1 \u0bb8\u0bbe\u0bb9\u0bb8\u0baa\u0ba4\u0bc7\u0bb7\u0bc1 \u0bb5\u0bbf\u0bb2\u0bc7\u0b95\u0baf\u0ba8\u0bcd\u0ba4\u0bcc\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0bea \u0965", "kannada": "\u0cb8\u0ca6\u0ccd\u0caf\u0ccb\u0cb5\u0cbf\u0c95\u0cbe\u0cb6\u0cbf\u0cb8\u0cae\u0cc1\u0ca6\u0cbf\u0ca4\u0ccd\u0cb5\u0cb0\u0cb8\u0cbe\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0cb0\u0cbe\u0c97-\n\u0cb8\u0ccc\u0cb0\u0cad\u0ccd\u0caf\u0ca8\u0cbf\u0cb0\u0ccd\u0cad\u0cb0\u0cb8\u0cb0\u0ccb\u0cb0\u0cc1\u0cb9\u0cb8\u0cbe\u0cae\u0ccd\u0caf\u0cb5\u0cbe\u0cb0\u0ccd\u0ca4\u0cbe\u0cae\u0ccd \u0964\n\u0cb8\u0cae\u0ccd\u0caf\u0c95\u0ccd\u0cb7\u0cc1 \u0cb8\u0cbe\u0cb9\u0cb8\u0caa\u0ca6\u0cc7\u0cb7\u0cc1 \u0cb5\u0cbf\u0cb2\u0cc7\u0c96\u0caf\u0ca8\u0ccd\u0ca4\u0ccc\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0cea \u0965", "malayalam": "\u0d38\u0d26\u0d4d\u0d2f\u0d4b\u0d35\u0d3f\u0d15\u0d3e\u0d36\u0d3f\u0d38\u0d2e\u0d41\u0d26\u0d3f\u0d24\u0d4d\u0d35\u0d30\u0d38\u0d3e\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d30\u0d3e\u0d17-\n\u0d38\u0d4c\u0d30\u0d2d\u0d4d\u0d2f\u0d28\u0d3f\u0d30\u0d4d\u0d2d\u0d30\u0d38\u0d30\u0d4b\u0d30\u0d41\u0d39\u0d38\u0d3e\u0d2e\u0d4d\u0d2f\u0d35\u0d3e\u0d30\u0d4d\u0d24\u0d3e\u0d2e\u0d4d \u0964\n\u0d38\u0d2e\u0d4d\u0d2f\u0d15\u0d4d\u0d37\u0d41 \u0d38\u0d3e\u0d39\u0d38\u0d2a\u0d26\u0d47\u0d37\u0d41 \u0d35\u0d3f\u0d32\u0d47\u0d16\u0d2f\u0d28\u0d4d\u0d24\u0d4c\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d6a \u0965", "iast": "sadyovik\u0101\u015bisamuditvaras\u0101ndrar\u0101ga-\nsaurabhyanirbharasaroruhas\u0101myav\u0101rt\u0101m |\nsamyak\u1e63u s\u0101hasapade\u1e63u vilekhayantau\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 4 ||"},
        draftTranslation: "Comparing which to fresh-blooming lotuses rich with bright crimson hue and dense fragrance is deemed an audacity by poets, for Thy feet far outshine any lotus in tenderness, scent, and crimson splendour \u2014 I surrender at the holy feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 45,
        devanagariText: "\u0930\u0947\u0916\u093e\u092e\u092f\u0927\u094d\u0935\u091c\u0938\u0941\u0927\u093e\u0915\u0932\u0936\u093e\u0924\u092a\u0924\u094d\u0930-\n\u0935\u091c\u094d\u0930\u093e\u0919\u094d\u0915\u0941\u0936\u093e\u092e\u094d\u092c\u0941\u0930\u0941\u0939\u0915\u0932\u094d\u092a\u0915\u0936\u0919\u094d\u0916\u091a\u0915\u094d\u0930\u0948\u0903 \u0964\n\u092d\u0935\u094d\u092f\u0948\u0930\u0932\u0919\u094d\u0915\u0943\u0924\u0924\u0932\u094c \u092a\u0930\u0924\u0924\u094d\u0924\u094d\u0935\u091a\u093f\u0939\u094d\u0928\u0948\u0903\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u096b \u0965",
        iastText: "r\u0113kh\u0101maya-dhvaja-sudh\u0101-kala\u015b\u0101tapatra-\nvajr\u0101\u1e45ku\u015b\u0101mburuha-kalpaka-\u015ba\u1e45kha-cakrai\u1e25 .\nbhavyair-ala\u1e45k\u1e5bta-talau paratattva-cihnai\u1e25\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 5 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c30\u0c47\u0c16\u0c3e\u0c2e\u0c2f\u0c27\u0c4d\u0c35\u0c1c\u0c38\u0c41\u0c27\u0c3e\u0c15\u0c32\u0c36\u0c3e\u0c24\u0c2a\u0c24\u0c4d\u0c30-\n\u0c35\u0c1c\u0c4d\u0c30\u0c3e\u0c19\u0c4d\u0c15\u0c41\u0c36\u0c3e\u0c2e\u0c4d\u0c2c\u0c41\u0c30\u0c41\u0c39\u0c15\u0c32\u0c4d\u0c2a\u0c15\u0c36\u0c19\u0c4d\u0c16\u0c1a\u0c15\u0c4d\u0c30\u0c48\u0c03 \u0964\n\u0c2d\u0c35\u0c4d\u0c2f\u0c48\u0c30\u0c32\u0c19\u0c4d\u0c15\u0c43\u0c24\u0c24\u0c32\u0c4c \u0c2a\u0c30\u0c24\u0c24\u0c4d\u0c24\u0c4d\u0c35\u0c1a\u0c3f\u0c39\u0c4d\u0c28\u0c48\u0c03\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c6b \u0965", "tamil": "\u0bb0\u0bc7\u0b95\u0bbe\u0bae\u0baf\u0ba4\u0bcd\u0bb5\u0b9c\u0bb8\u0bc1\u0ba4\u0bbe\u0b95\u0bb2\u0bb6\u0bbe\u0ba4\u0baa\u0ba4\u0bcd\u0bb0-\n\u0bb5\u0b9c\u0bcd\u0bb0\u0bbe\u0b99\u0bcd\u0b95\u0bc1\u0bb6\u0bbe\u0bae\u0bcd\u0baa\u0bc1\u0bb0\u0bc1\u0bb9\u0b95\u0bb2\u0bcd\u0baa\u0b95\u0bb6\u0b99\u0bcd\u0b95\u0b9a\u0b95\u0bcd\u0bb0\u0bc8\u0b83 \u0964\n\u0baa\u0bb5\u0bcd\u0baf\u0bc8\u0bb0\u0bb2\u0b99\u0bcd\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0ba4\u0bb2\u0bcc \u0baa\u0bb0\u0ba4\u0ba4\u0bcd\u0ba4\u0bcd\u0bb5\u0b9a\u0bbf\u0bb9\u0bcd\u0ba8\u0bc8\u0b83\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0beb \u0965", "kannada": "\u0cb0\u0cc7\u0c96\u0cbe\u0cae\u0caf\u0ca7\u0ccd\u0cb5\u0c9c\u0cb8\u0cc1\u0ca7\u0cbe\u0c95\u0cb2\u0cb6\u0cbe\u0ca4\u0caa\u0ca4\u0ccd\u0cb0-\n\u0cb5\u0c9c\u0ccd\u0cb0\u0cbe\u0c99\u0ccd\u0c95\u0cc1\u0cb6\u0cbe\u0cae\u0ccd\u0cac\u0cc1\u0cb0\u0cc1\u0cb9\u0c95\u0cb2\u0ccd\u0caa\u0c95\u0cb6\u0c99\u0ccd\u0c96\u0c9a\u0c95\u0ccd\u0cb0\u0cc8\u0c83 \u0964\n\u0cad\u0cb5\u0ccd\u0caf\u0cc8\u0cb0\u0cb2\u0c99\u0ccd\u0c95\u0cc3\u0ca4\u0ca4\u0cb2\u0ccc \u0caa\u0cb0\u0ca4\u0ca4\u0ccd\u0ca4\u0ccd\u0cb5\u0c9a\u0cbf\u0cb9\u0ccd\u0ca8\u0cc8\u0c83\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0ceb \u0965", "malayalam": "\u0d30\u0d47\u0d16\u0d3e\u0d2e\u0d2f\u0d27\u0d4d\u0d35\u0d1c\u0d38\u0d41\u0d27\u0d3e\u0d15\u0d32\u0d36\u0d3e\u0d24\u0d2a\u0d24\u0d4d\u0d30-\n\u0d35\u0d1c\u0d4d\u0d30\u0d3e\u0d19\u0d4d\u0d15\u0d41\u0d36\u0d3e\u0d2e\u0d4d\u0d2c\u0d41\u0d30\u0d41\u0d39\u0d15\u0d32\u0d4d\u0d2a\u0d15\u0d36\u0d19\u0d4d\u0d16\u0d1a\u0d15\u0d4d\u0d30\u0d48\u0d03 \u0964\n\u0d2d\u0d35\u0d4d\u0d2f\u0d48\u0d30\u0d32\u0d19\u0d4d\u0d15\u0d43\u0d24\u0d24\u0d32\u0d4c \u0d2a\u0d30\u0d24\u0d24\u0d4d\u0d24\u0d4d\u0d35\u0d1a\u0d3f\u0d39\u0d4d\u0d28\u0d48\u0d03\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d6b \u0965", "iast": "rekh\u0101mayadhvajasudh\u0101kala\u015b\u0101tapatra-\nvajr\u0101\u1e45ku\u015b\u0101mburuhakalpaka\u015ba\u1e45khacakrai\u1e25 |\nbhavyairala\u1e45k\u1e5btatalau paratattvacihnai\u1e25\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 5 ||"},
        draftTranslation: "Whose soles are adorned with auspicious lines marking the Supreme Divinity: the flag (dhvaja), nectar vase (kalasha), umbrella (chhatra), thunderbolt (vajra), elephant goad (ankusha), lotus (amburuha), wish-yielding tree (kalpaka), conch (shankha), and discus (chakra) \u2014 I surrender at the holy feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 46,
        devanagariText: "\u0924\u093e\u092e\u094d\u0930\u094b\u0926\u0930\u0926\u094d\u092f\u0941\u0924\u093f\u092a\u0930\u093e\u091c\u093f\u0924\u092a\u0926\u094d\u092e\u0930\u093e\u0917\u094c\n\u092c\u093e\u0939\u094d\u092f\u0948\u0930\u094d\u092e\u0939\u094b\u092d\u093f\u0930\u092d\u093f\u092d\u0942\u0924\u092e\u0939\u0947\u0902\u0926\u094d\u0930\u0928\u0940\u0932\u094c \u0964\n\u0909\u0926\u094d\u092f\u0928\u094d\u0928\u0916\u093e\u0902\u0936\u0941\u092d\u093f\u0930\u0941\u0926\u0938\u094d\u0924\u0936\u0936\u093e\u0919\u094d\u0915\u092d\u093e\u0938\u094c\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u096c \u0965",
        iastText: "t\u0101mr\u014ddara-dyuti-par\u0101jita-padmar\u0101gau\nb\u0101hyair-mah\u014dbhir-abhibh\u016bta-mah\u0113ndran\u012blau .\nudyan-nakh\u0101\u1e41\u015bubhir-udasta-\u015ba\u015b\u0101\u1e45ka-bh\u0101sau\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 6 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c24\u0c3e\u0c2e\u0c4d\u0c30\u0c4b\u0c26\u0c30\u0c26\u0c4d\u0c2f\u0c41\u0c24\u0c3f\u0c2a\u0c30\u0c3e\u0c1c\u0c3f\u0c24\u0c2a\u0c26\u0c4d\u0c2e\u0c30\u0c3e\u0c17\u0c4c\n\u0c2c\u0c3e\u0c39\u0c4d\u0c2f\u0c48\u0c30\u0c4d\u0c2e\u0c39\u0c4b\u0c2d\u0c3f\u0c30\u0c2d\u0c3f\u0c2d\u0c42\u0c24\u0c2e\u0c39\u0c47\u0c02\u0c26\u0c4d\u0c30\u0c28\u0c40\u0c32\u0c4c \u0964\n\u0c09\u0c26\u0c4d\u0c2f\u0c28\u0c4d\u0c28\u0c16\u0c3e\u0c02\u0c36\u0c41\u0c2d\u0c3f\u0c30\u0c41\u0c26\u0c38\u0c4d\u0c24\u0c36\u0c36\u0c3e\u0c19\u0c4d\u0c15\u0c2d\u0c3e\u0c38\u0c4c\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c6c \u0965", "tamil": "\u0ba4\u0bbe\u0bae\u0bcd\u0bb0\u0bcb\u0ba4\u0bb0\u0ba4\u0bcd\u0baf\u0bc1\u0ba4\u0bbf\u0baa\u0bb0\u0bbe\u0b9c\u0bbf\u0ba4\u0baa\u0ba4\u0bcd\u0bae\u0bb0\u0bbe\u0b95\u0bcc\n\u0baa\u0bbe\u0bb9\u0bcd\u0baf\u0bc8\u0bb0\u0bcd\u0bae\u0bb9\u0bcb\u0baa\u0bbf\u0bb0\u0baa\u0bbf\u0baa\u0bc2\u0ba4\u0bae\u0bb9\u0bc7\u0bae\u0bcd\u0ba4\u0bcd\u0bb0\u0ba8\u0bc0\u0bb2\u0bcc \u0964\n\u0b89\u0ba4\u0bcd\u0baf\u0ba8\u0bcd\u0ba8\u0b95\u0bbe\u0bae\u0bcd\u0bb6\u0bc1\u0baa\u0bbf\u0bb0\u0bc1\u0ba4\u0bb8\u0bcd\u0ba4\u0bb6\u0bb6\u0bbe\u0b99\u0bcd\u0b95\u0baa\u0bbe\u0bb8\u0bcc\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0bec \u0965", "kannada": "\u0ca4\u0cbe\u0cae\u0ccd\u0cb0\u0ccb\u0ca6\u0cb0\u0ca6\u0ccd\u0caf\u0cc1\u0ca4\u0cbf\u0caa\u0cb0\u0cbe\u0c9c\u0cbf\u0ca4\u0caa\u0ca6\u0ccd\u0cae\u0cb0\u0cbe\u0c97\u0ccc\n\u0cac\u0cbe\u0cb9\u0ccd\u0caf\u0cc8\u0cb0\u0ccd\u0cae\u0cb9\u0ccb\u0cad\u0cbf\u0cb0\u0cad\u0cbf\u0cad\u0cc2\u0ca4\u0cae\u0cb9\u0cc7\u0c82\u0ca6\u0ccd\u0cb0\u0ca8\u0cc0\u0cb2\u0ccc \u0964\n\u0c89\u0ca6\u0ccd\u0caf\u0ca8\u0ccd\u0ca8\u0c96\u0cbe\u0c82\u0cb6\u0cc1\u0cad\u0cbf\u0cb0\u0cc1\u0ca6\u0cb8\u0ccd\u0ca4\u0cb6\u0cb6\u0cbe\u0c99\u0ccd\u0c95\u0cad\u0cbe\u0cb8\u0ccc\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0cec \u0965", "malayalam": "\u0d24\u0d3e\u0d2e\u0d4d\u0d30\u0d4b\u0d26\u0d30\u0d26\u0d4d\u0d2f\u0d41\u0d24\u0d3f\u0d2a\u0d30\u0d3e\u0d1c\u0d3f\u0d24\u0d2a\u0d26\u0d4d\u0d2e\u0d30\u0d3e\u0d17\u0d4c\n\u0d2c\u0d3e\u0d39\u0d4d\u0d2f\u0d48\u0d30\u0d4d\u0d2e\u0d39\u0d4b\u0d2d\u0d3f\u0d30\u0d2d\u0d3f\u0d2d\u0d42\u0d24\u0d2e\u0d39\u0d47\u0d02\u0d26\u0d4d\u0d30\u0d28\u0d40\u0d32\u0d4c \u0964\n\u0d09\u0d26\u0d4d\u0d2f\u0d28\u0d4d\u0d28\u0d16\u0d3e\u0d02\u0d36\u0d41\u0d2d\u0d3f\u0d30\u0d41\u0d26\u0d38\u0d4d\u0d24\u0d36\u0d36\u0d3e\u0d19\u0d4d\u0d15\u0d2d\u0d3e\u0d38\u0d4c\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d6c \u0965", "iast": "t\u0101mrodaradyutipar\u0101jitapadmar\u0101gau\nb\u0101hyairmahobhirabhibh\u016btamahe\u1e43dran\u012blau |\nudyannakh\u0101\u1e43\u015bubhirudasta\u015ba\u015b\u0101\u1e45kabh\u0101sau\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 6 ||"},
        draftTranslation: "Whose reddish soles conquer the lustre of rubies (padmaraga), whose upper surface radiates dark sheen surpassing glorious blue sapphires (mahendranila), and whose rising toenail beams eclipse the splendour of the autumn moon \u2014 I surrender at the holy feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 47,
        devanagariText: "\u0938\u092a\u094d\u0930\u0947\u092e\u092d\u0940\u0924\u093f\u0915\u092e\u0932\u093e\u0915\u0930\u092a\u0932\u094d\u0932\u0935\u093e\u092d\u094d\u092f\u093e\u0902\n\u0938\u0902\u0935\u093e\u0939\u0928\u0947\u093d\u092a\u093f \u0938\u092a\u0926\u093f \u0915\u094d\u0932\u092e\u092e\u093e\u0926\u0927\u093e\u0928\u094c \u0964\n\u0915\u093e\u0928\u094d\u0924\u093e\u0935\u0935\u093e\u0919\u094d\u092e\u0928\u0938\u0917\u094b\u091a\u0930\u0938\u094c\u0915\u0941\u092e\u093e\u0930\u094d\u092f\u094c\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u096d \u0965",
        iastText: "sa-pr\u0113ma-bh\u012bti-kamal\u0101-kara-pallav\u0101bhy\u0101\u1e41\nsa\u1e41v\u0101han\u0113\u2019pi sapadi klamam-\u0101dadh\u0101nau .\nk\u0101nt\u0101v-av\u0101\u1e45-manasa-g\u014dcara-saukum\u0101ryau\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 7 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c38\u0c2a\u0c4d\u0c30\u0c47\u0c2e\u0c2d\u0c40\u0c24\u0c3f\u0c15\u0c2e\u0c32\u0c3e\u0c15\u0c30\u0c2a\u0c32\u0c4d\u0c32\u0c35\u0c3e\u0c2d\u0c4d\u0c2f\u0c3e\u0c02\n\u0c38\u0c02\u0c35\u0c3e\u0c39\u0c28\u0c47\u0c3d\u0c2a\u0c3f \u0c38\u0c2a\u0c26\u0c3f \u0c15\u0c4d\u0c32\u0c2e\u0c2e\u0c3e\u0c26\u0c27\u0c3e\u0c28\u0c4c \u0964\n\u0c15\u0c3e\u0c28\u0c4d\u0c24\u0c3e\u0c35\u0c35\u0c3e\u0c19\u0c4d\u0c2e\u0c28\u0c38\u0c17\u0c4b\u0c1a\u0c30\u0c38\u0c4c\u0c15\u0c41\u0c2e\u0c3e\u0c30\u0c4d\u0c2f\u0c4c\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c6d \u0965", "tamil": "\u0bb8\u0baa\u0bcd\u0bb0\u0bc7\u0bae\u0baa\u0bc0\u0ba4\u0bbf\u0b95\u0bae\u0bb2\u0bbe\u0b95\u0bb0\u0baa\u0bb2\u0bcd\u0bb2\u0bb5\u0bbe\u0baa\u0bcd\u0baf\u0bbe\u0bae\u0bcd\n\u0bb8\u0bae\u0bcd\u0bb5\u0bbe\u0bb9\u0ba8\u0bc7\u093d\u0baa\u0bbf \u0bb8\u0baa\u0ba4\u0bbf \u0b95\u0bcd\u0bb2\u0bae\u0bae\u0bbe\u0ba4\u0ba4\u0bbe\u0ba8\u0bcc \u0964\n\u0b95\u0bbe\u0ba8\u0bcd\u0ba4\u0bbe\u0bb5\u0bb5\u0bbe\u0b99\u0bcd\u0bae\u0ba8\u0bb8\u0b95\u0bcb\u0b9a\u0bb0\u0bb8\u0bcc\u0b95\u0bc1\u0bae\u0bbe\u0bb0\u0bcd\u0baf\u0bcc\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0bed \u0965", "kannada": "\u0cb8\u0caa\u0ccd\u0cb0\u0cc7\u0cae\u0cad\u0cc0\u0ca4\u0cbf\u0c95\u0cae\u0cb2\u0cbe\u0c95\u0cb0\u0caa\u0cb2\u0ccd\u0cb2\u0cb5\u0cbe\u0cad\u0ccd\u0caf\u0cbe\u0c82\n\u0cb8\u0c82\u0cb5\u0cbe\u0cb9\u0ca8\u0cc7\u0cbd\u0caa\u0cbf \u0cb8\u0caa\u0ca6\u0cbf \u0c95\u0ccd\u0cb2\u0cae\u0cae\u0cbe\u0ca6\u0ca7\u0cbe\u0ca8\u0ccc \u0964\n\u0c95\u0cbe\u0ca8\u0ccd\u0ca4\u0cbe\u0cb5\u0cb5\u0cbe\u0c99\u0ccd\u0cae\u0ca8\u0cb8\u0c97\u0ccb\u0c9a\u0cb0\u0cb8\u0ccc\u0c95\u0cc1\u0cae\u0cbe\u0cb0\u0ccd\u0caf\u0ccc\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0ced \u0965", "malayalam": "\u0d38\u0d2a\u0d4d\u0d30\u0d47\u0d2e\u0d2d\u0d40\u0d24\u0d3f\u0d15\u0d2e\u0d32\u0d3e\u0d15\u0d30\u0d2a\u0d32\u0d4d\u0d32\u0d35\u0d3e\u0d2d\u0d4d\u0d2f\u0d3e\u0d02\n\u0d38\u0d02\u0d35\u0d3e\u0d39\u0d28\u0d47\u0d3d\u0d2a\u0d3f \u0d38\u0d2a\u0d26\u0d3f \u0d15\u0d4d\u0d32\u0d2e\u0d2e\u0d3e\u0d26\u0d27\u0d3e\u0d28\u0d4c \u0964\n\u0d15\u0d3e\u0d28\u0d4d\u0d24\u0d3e\u0d35\u0d35\u0d3e\u0d19\u0d4d\u0d2e\u0d28\u0d38\u0d17\u0d4b\u0d1a\u0d30\u0d38\u0d4c\u0d15\u0d41\u0d2e\u0d3e\u0d30\u0d4d\u0d2f\u0d4c\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d6d \u0965", "iast": "sapremabh\u012btikamal\u0101karapallav\u0101bhy\u0101\u1e43\nsa\u1e43v\u0101hane'pi sapadi klamam\u0101dadh\u0101nau |\nk\u0101nt\u0101vav\u0101\u1e45manasagocarasaukum\u0101ryau\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 7 ||"},
        draftTranslation: "Which feel fatigue even when massaged most delicately by the tender blossom-hands of Goddess Kamala, who strokes them with mingled love and trembling dread of hurting them; radiating unutterable, unimaginable tenderness \u2014 I surrender at the holy feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 48,
        devanagariText: "\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u092e\u0939\u0940\u0924\u0926\u0928\u0941\u0930\u0942\u092a\u0928\u093f\u091c\u093e\u0928\u0941\u092d\u093e\u0935-\n\u0928\u0940\u0932\u093e\u0926\u093f\u0926\u093f\u0935\u094d\u092f\u092e\u0939\u093f\u0937\u0940\u0915\u0930\u092a\u0932\u094d\u0932\u0935\u093e\u0928\u093e\u092e\u094d \u0964\n\u0906\u0930\u0941\u0923\u094d\u092f\u0938\u0919\u094d\u0915\u094d\u0930\u092e\u0923\u0924\u0903 \u0915\u093f\u0932 \u0938\u093e\u0928\u094d\u0926\u094d\u0930\u0930\u093e\u0917\u094c\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u096e \u0965",
        iastText: "lak\u1e63m\u012b-mah\u012b-tad-anur\u016bpa-nij\u0101nubh\u0101va-\nn\u012bl\u0101di-divya-mahi\u1e63\u012b-kara-pallav\u0101n\u0101m .\n\u0101ru\u1e47ya-sa\u1e45krama\u1e47ata\u1e25 kila s\u0101ndra-r\u0101gau\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 8 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c40\u0c2e\u0c39\u0c40\u0c24\u0c26\u0c28\u0c41\u0c30\u0c42\u0c2a\u0c28\u0c3f\u0c1c\u0c3e\u0c28\u0c41\u0c2d\u0c3e\u0c35-\n\u0c28\u0c40\u0c32\u0c3e\u0c26\u0c3f\u0c26\u0c3f\u0c35\u0c4d\u0c2f\u0c2e\u0c39\u0c3f\u0c37\u0c40\u0c15\u0c30\u0c2a\u0c32\u0c4d\u0c32\u0c35\u0c3e\u0c28\u0c3e\u0c2e\u0c4d \u0964\n\u0c06\u0c30\u0c41\u0c23\u0c4d\u0c2f\u0c38\u0c19\u0c4d\u0c15\u0c4d\u0c30\u0c2e\u0c23\u0c24\u0c03 \u0c15\u0c3f\u0c32 \u0c38\u0c3e\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c30\u0c3e\u0c17\u0c4c\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c6e \u0965", "tamil": "\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bc0\u0bae\u0bb9\u0bc0\u0ba4\u0ba4\u0ba8\u0bc1\u0bb0\u0bc2\u0baa\u0ba8\u0bbf\u0b9c\u0bbe\u0ba8\u0bc1\u0baa\u0bbe\u0bb5-\n\u0ba8\u0bc0\u0bb2\u0bbe\u0ba4\u0bbf\u0ba4\u0bbf\u0bb5\u0bcd\u0baf\u0bae\u0bb9\u0bbf\u0bb7\u0bc0\u0b95\u0bb0\u0baa\u0bb2\u0bcd\u0bb2\u0bb5\u0bbe\u0ba8\u0bbe\u0bae\u0bcd \u0964\n\u0b86\u0bb0\u0bc1\u0ba3\u0bcd\u0baf\u0bb8\u0b99\u0bcd\u0b95\u0bcd\u0bb0\u0bae\u0ba3\u0ba4\u0b83 \u0b95\u0bbf\u0bb2 \u0bb8\u0bbe\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bb0\u0bbe\u0b95\u0bcc\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0bee \u0965", "kannada": "\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cc0\u0cae\u0cb9\u0cc0\u0ca4\u0ca6\u0ca8\u0cc1\u0cb0\u0cc2\u0caa\u0ca8\u0cbf\u0c9c\u0cbe\u0ca8\u0cc1\u0cad\u0cbe\u0cb5-\n\u0ca8\u0cc0\u0cb2\u0cbe\u0ca6\u0cbf\u0ca6\u0cbf\u0cb5\u0ccd\u0caf\u0cae\u0cb9\u0cbf\u0cb7\u0cc0\u0c95\u0cb0\u0caa\u0cb2\u0ccd\u0cb2\u0cb5\u0cbe\u0ca8\u0cbe\u0cae\u0ccd \u0964\n\u0c86\u0cb0\u0cc1\u0ca3\u0ccd\u0caf\u0cb8\u0c99\u0ccd\u0c95\u0ccd\u0cb0\u0cae\u0ca3\u0ca4\u0c83 \u0c95\u0cbf\u0cb2 \u0cb8\u0cbe\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0cb0\u0cbe\u0c97\u0ccc\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0cee \u0965", "malayalam": "\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d40\u0d2e\u0d39\u0d40\u0d24\u0d26\u0d28\u0d41\u0d30\u0d42\u0d2a\u0d28\u0d3f\u0d1c\u0d3e\u0d28\u0d41\u0d2d\u0d3e\u0d35-\n\u0d28\u0d40\u0d32\u0d3e\u0d26\u0d3f\u0d26\u0d3f\u0d35\u0d4d\u0d2f\u0d2e\u0d39\u0d3f\u0d37\u0d40\u0d15\u0d30\u0d2a\u0d32\u0d4d\u0d32\u0d35\u0d3e\u0d28\u0d3e\u0d2e\u0d4d \u0964\n\u0d06\u0d30\u0d41\u0d23\u0d4d\u0d2f\u0d38\u0d19\u0d4d\u0d15\u0d4d\u0d30\u0d2e\u0d23\u0d24\u0d03 \u0d15\u0d3f\u0d32 \u0d38\u0d3e\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d30\u0d3e\u0d17\u0d4c\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d6e \u0965", "iast": "lak\u1e63m\u012bmah\u012btadanur\u016bpanij\u0101nubh\u0101va-\nn\u012bl\u0101didivyamahi\u1e63\u012bkarapallav\u0101n\u0101m |\n\u0101ru\u1e47yasa\u1e45krama\u1e47ata\u1e25 kila s\u0101ndrar\u0101gau\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 8 ||"},
        draftTranslation: "Which appear intensely crimson red as if the natural rosy blush of the sprout-like palms of His divine consorts \u2014 Sridevi, Bhudevi, and Niladevi of equal divine splendour \u2014 has transferred onto them during loving service \u2014 I surrender at the holy feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 49,
        devanagariText: "\u0928\u093f\u0924\u094d\u092f\u0928\u092e\u0926\u094d\u0935\u093f\u0927\u093f\u0936\u093f\u0935\u093e\u0926\u093f\u0917\u093f\u0930\u0940\u091f\u0915\u094b\u091f\u093f-\n\u092a\u094d\u0930\u0924\u094d\u092f\u0941\u092a\u094d\u0924\u0926\u0940\u092a\u094d\u0924\u0928\u0935\u0930\u0924\u094d\u0928\u092e\u0939\u093e\u092a\u094d\u0930\u0930\u094b\u0939\u0948\u0903 \u0964\n\u0928\u0940\u0930\u093e\u091c\u0928\u093e\u0935\u093f\u0927\u093f\u092e\u0941\u0926\u093e\u0930\u092e\u0941\u092a\u093e\u0926\u0927\u093e\u0928\u094c\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u096f \u0965",
        iastText: "nitya-namad-vidhi-\u015biv\u0101di-kir\u012b\u1e6da-k\u014d\u1e6di-\npratyupta-d\u012bpta-navaratna-mah\u0101-prar\u014dhai\u1e25 .\nn\u012br\u0101jan\u0101-vidhim-ud\u0101ram-up\u0101dadh\u0101nau\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 9 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c28\u0c3f\u0c24\u0c4d\u0c2f\u0c28\u0c2e\u0c26\u0c4d\u0c35\u0c3f\u0c27\u0c3f\u0c36\u0c3f\u0c35\u0c3e\u0c26\u0c3f\u0c17\u0c3f\u0c30\u0c40\u0c1f\u0c15\u0c4b\u0c1f\u0c3f-\n\u0c2a\u0c4d\u0c30\u0c24\u0c4d\u0c2f\u0c41\u0c2a\u0c4d\u0c24\u0c26\u0c40\u0c2a\u0c4d\u0c24\u0c28\u0c35\u0c30\u0c24\u0c4d\u0c28\u0c2e\u0c39\u0c3e\u0c2a\u0c4d\u0c30\u0c30\u0c4b\u0c39\u0c48\u0c03 \u0964\n\u0c28\u0c40\u0c30\u0c3e\u0c1c\u0c28\u0c3e\u0c35\u0c3f\u0c27\u0c3f\u0c2e\u0c41\u0c26\u0c3e\u0c30\u0c2e\u0c41\u0c2a\u0c3e\u0c26\u0c27\u0c3e\u0c28\u0c4c\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c6f \u0965", "tamil": "\u0ba8\u0bbf\u0ba4\u0bcd\u0baf\u0ba8\u0bae\u0ba4\u0bcd\u0bb5\u0bbf\u0ba4\u0bbf\u0bb6\u0bbf\u0bb5\u0bbe\u0ba4\u0bbf\u0b95\u0bbf\u0bb0\u0bc0\u0b9f\u0b95\u0bcb\u0b9f\u0bbf-\n\u0baa\u0bcd\u0bb0\u0ba4\u0bcd\u0baf\u0bc1\u0baa\u0bcd\u0ba4\u0ba4\u0bc0\u0baa\u0bcd\u0ba4\u0ba8\u0bb5\u0bb0\u0ba4\u0bcd\u0ba8\u0bae\u0bb9\u0bbe\u0baa\u0bcd\u0bb0\u0bb0\u0bcb\u0bb9\u0bc8\u0b83 \u0964\n\u0ba8\u0bc0\u0bb0\u0bbe\u0b9c\u0ba8\u0bbe\u0bb5\u0bbf\u0ba4\u0bbf\u0bae\u0bc1\u0ba4\u0bbe\u0bb0\u0bae\u0bc1\u0baa\u0bbe\u0ba4\u0ba4\u0bbe\u0ba8\u0bcc\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0bef \u0965", "kannada": "\u0ca8\u0cbf\u0ca4\u0ccd\u0caf\u0ca8\u0cae\u0ca6\u0ccd\u0cb5\u0cbf\u0ca7\u0cbf\u0cb6\u0cbf\u0cb5\u0cbe\u0ca6\u0cbf\u0c97\u0cbf\u0cb0\u0cc0\u0c9f\u0c95\u0ccb\u0c9f\u0cbf-\n\u0caa\u0ccd\u0cb0\u0ca4\u0ccd\u0caf\u0cc1\u0caa\u0ccd\u0ca4\u0ca6\u0cc0\u0caa\u0ccd\u0ca4\u0ca8\u0cb5\u0cb0\u0ca4\u0ccd\u0ca8\u0cae\u0cb9\u0cbe\u0caa\u0ccd\u0cb0\u0cb0\u0ccb\u0cb9\u0cc8\u0c83 \u0964\n\u0ca8\u0cc0\u0cb0\u0cbe\u0c9c\u0ca8\u0cbe\u0cb5\u0cbf\u0ca7\u0cbf\u0cae\u0cc1\u0ca6\u0cbe\u0cb0\u0cae\u0cc1\u0caa\u0cbe\u0ca6\u0ca7\u0cbe\u0ca8\u0ccc\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0cef \u0965", "malayalam": "\u0d28\u0d3f\u0d24\u0d4d\u0d2f\u0d28\u0d2e\u0d26\u0d4d\u0d35\u0d3f\u0d27\u0d3f\u0d36\u0d3f\u0d35\u0d3e\u0d26\u0d3f\u0d17\u0d3f\u0d30\u0d40\u0d1f\u0d15\u0d4b\u0d1f\u0d3f-\n\u0d2a\u0d4d\u0d30\u0d24\u0d4d\u0d2f\u0d41\u0d2a\u0d4d\u0d24\u0d26\u0d40\u0d2a\u0d4d\u0d24\u0d28\u0d35\u0d30\u0d24\u0d4d\u0d28\u0d2e\u0d39\u0d3e\u0d2a\u0d4d\u0d30\u0d30\u0d4b\u0d39\u0d48\u0d03 \u0964\n\u0d28\u0d40\u0d30\u0d3e\u0d1c\u0d28\u0d3e\u0d35\u0d3f\u0d27\u0d3f\u0d2e\u0d41\u0d26\u0d3e\u0d30\u0d2e\u0d41\u0d2a\u0d3e\u0d26\u0d27\u0d3e\u0d28\u0d4c\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d6f \u0965", "iast": "nityanamadvidhi\u015biv\u0101digir\u012b\u1e6dako\u1e6di-\npratyuptad\u012bptanavaratnamah\u0101prarohai\u1e25 |\nn\u012br\u0101jan\u0101vidhimud\u0101ramup\u0101dadh\u0101nau\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 9 ||"},
        draftTranslation: "Before which Brahma, Shiva, and countless deities constantly bow their crowned heads, so that the radiant beams shooting from the dazzling nine gems on their crowns perform a glorious ritual waving of lights (aarati / neerajana) \u2014 I surrender at the holy feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 50,
        devanagariText: "\u0935\u093f\u0937\u094d\u0923\u094b\u0903 \u092a\u0926\u0947 \u092a\u0930\u092e\u0924\u0940\u0935 \u092e\u0941\u0926\u093f\u0924\u092a\u094d\u0930\u0936\u0902\u0938\u094c\n\u092f\u094c \u092e\u0927\u094d\u0935 \u0909\u0924\u094d\u0938 \u0907\u0924\u093f \u092d\u094b\u0917\u094d\u092f\u0924\u092f\u093e\u092a\u094d\u092f\u0941\u092a\u093e\u0924\u094d\u0924\u094c \u0964\n\u092d\u0942\u092f\u0938\u094d\u0924\u0925\u0947\u0924\u093f \u0924\u0935 \u092a\u093e\u0923\u093f\u0924\u0932\u092a\u094d\u0930\u0926\u093f\u0937\u094d\u091f\u094c\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u0967\u0966 \u0965",
        iastText: "vi\u1e63\u1e47\u014d\u1e25 pad\u0113 paramat\u012bva mudita-pra\u015ba\u1e41sau\nyau madhva utsa iti bh\u014dgyatay\u0101\u2019pyup\u0101ttau .\nbh\u016byas-tath\u0113ti tava p\u0101\u1e47itala-pradi\u1e63\u1e6dau\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 10 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c35\u0c3f\u0c37\u0c4d\u0c23\u0c4b\u0c03 \u0c2a\u0c26\u0c47 \u0c2a\u0c30\u0c2e\u0c24\u0c40\u0c35 \u0c2e\u0c41\u0c26\u0c3f\u0c24\u0c2a\u0c4d\u0c30\u0c36\u0c02\u0c38\u0c4c\n\u0c2f\u0c4c \u0c2e\u0c27\u0c4d\u0c35 \u0c09\u0c24\u0c4d\u0c38 \u0c07\u0c24\u0c3f \u0c2d\u0c4b\u0c17\u0c4d\u0c2f\u0c24\u0c2f\u0c3e\u0c2a\u0c4d\u0c2f\u0c41\u0c2a\u0c3e\u0c24\u0c4d\u0c24\u0c4c \u0964\n\u0c2d\u0c42\u0c2f\u0c38\u0c4d\u0c24\u0c25\u0c47\u0c24\u0c3f \u0c24\u0c35 \u0c2a\u0c3e\u0c23\u0c3f\u0c24\u0c32\u0c2a\u0c4d\u0c30\u0c26\u0c3f\u0c37\u0c4d\u0c1f\u0c4c\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c67\u0c66 \u0965", "tamil": "\u0bb5\u0bbf\u0bb7\u0bcd\u0ba3\u0bcb\u0b83 \u0baa\u0ba4\u0bc7 \u0baa\u0bb0\u0bae\u0ba4\u0bc0\u0bb5 \u0bae\u0bc1\u0ba4\u0bbf\u0ba4\u0baa\u0bcd\u0bb0\u0bb6\u0bae\u0bcd\u0bb8\u0bcc\n\u0baf\u0bcc \u0bae\u0ba4\u0bcd\u0bb5 \u0b89\u0ba4\u0bcd\u0bb8 \u0b87\u0ba4\u0bbf \u0baa\u0bcb\u0b95\u0bcd\u0baf\u0ba4\u0baf\u0bbe\u0baa\u0bcd\u0baf\u0bc1\u0baa\u0bbe\u0ba4\u0bcd\u0ba4\u0bcc \u0964\n\u0baa\u0bc2\u0baf\u0bb8\u0bcd\u0ba4\u0ba4\u0bc7\u0ba4\u0bbf \u0ba4\u0bb5 \u0baa\u0bbe\u0ba3\u0bbf\u0ba4\u0bb2\u0baa\u0bcd\u0bb0\u0ba4\u0bbf\u0bb7\u0bcd\u0b9f\u0bcc\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0be7\u0be6 \u0965", "kannada": "\u0cb5\u0cbf\u0cb7\u0ccd\u0ca3\u0ccb\u0c83 \u0caa\u0ca6\u0cc7 \u0caa\u0cb0\u0cae\u0ca4\u0cc0\u0cb5 \u0cae\u0cc1\u0ca6\u0cbf\u0ca4\u0caa\u0ccd\u0cb0\u0cb6\u0c82\u0cb8\u0ccc\n\u0caf\u0ccc \u0cae\u0ca7\u0ccd\u0cb5 \u0c89\u0ca4\u0ccd\u0cb8 \u0c87\u0ca4\u0cbf \u0cad\u0ccb\u0c97\u0ccd\u0caf\u0ca4\u0caf\u0cbe\u0caa\u0ccd\u0caf\u0cc1\u0caa\u0cbe\u0ca4\u0ccd\u0ca4\u0ccc \u0964\n\u0cad\u0cc2\u0caf\u0cb8\u0ccd\u0ca4\u0ca5\u0cc7\u0ca4\u0cbf \u0ca4\u0cb5 \u0caa\u0cbe\u0ca3\u0cbf\u0ca4\u0cb2\u0caa\u0ccd\u0cb0\u0ca6\u0cbf\u0cb7\u0ccd\u0c9f\u0ccc\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0ce7\u0ce6 \u0965", "malayalam": "\u0d35\u0d3f\u0d37\u0d4d\u0d23\u0d4b\u0d03 \u0d2a\u0d26\u0d47 \u0d2a\u0d30\u0d2e\u0d24\u0d40\u0d35 \u0d2e\u0d41\u0d26\u0d3f\u0d24\u0d2a\u0d4d\u0d30\u0d36\u0d02\u0d38\u0d4c\n\u0d2f\u0d4c \u0d2e\u0d27\u0d4d\u0d35 \u0d09\u0d24\u0d4d\u0d38 \u0d07\u0d24\u0d3f \u0d2d\u0d4b\u0d17\u0d4d\u0d2f\u0d24\u0d2f\u0d3e\u0d2a\u0d4d\u0d2f\u0d41\u0d2a\u0d3e\u0d24\u0d4d\u0d24\u0d4c \u0964\n\u0d2d\u0d42\u0d2f\u0d38\u0d4d\u0d24\u0d25\u0d47\u0d24\u0d3f \u0d24\u0d35 \u0d2a\u0d3e\u0d23\u0d3f\u0d24\u0d32\u0d2a\u0d4d\u0d30\u0d26\u0d3f\u0d37\u0d4d\u0d1f\u0d4c\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d67\u0d66 \u0965", "iast": "vi\u1e63\u1e47o\u1e25 pade paramat\u012bva muditapra\u015ba\u1e43sau\nyau madhva utsa iti bhogyatay\u0101pyup\u0101ttau |\nbh\u016byastatheti tava p\u0101\u1e47italapradi\u1e63\u1e6dau\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 10 ||"},
        draftTranslation: "Extolled with boundless joy in the Rigveda as the supreme fountainhead of honeyed nectar (\"madhva utsa iti\"), and which Thou Thyself pointest toward with Thy lowered right hand (Varada / Katihasta) confirming: \"Yes, indeed, here lies salvation!\" \u2014 I surrender at the holy feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 51,
        devanagariText: "\u092a\u093e\u0930\u094d\u0925\u093e\u092f \u0924\u0924\u094d\u0938\u0926\u0943\u0936\u0938\u093e\u0930\u0925\u093f\u0928\u093e \u0924\u094d\u0935\u092f\u0948\u0935\n\u092f\u094c \u0926\u0930\u094d\u0936\u093f\u0924\u094c \u0938\u094d\u0935\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u0935\u094d\u0930\u091c\u0947\u0924\u093f \u0964\n\u092d\u0942\u092f\u094b\u093d\u092a\u093f \u092e\u0939\u094d\u092f\u092e\u093f\u0939 \u0924\u094c \u0915\u0930\u0926\u0930\u094d\u0936\u093f\u0924\u094c \u0924\u0947\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u0967\u0967 \u0965",
        iastText: "p\u0101rth\u0101ya tat-sad\u1e5b\u015ba-s\u0101rathin\u0101 tvayaiva\nyau dar\u015bitau sva-cara\u1e47au \u015bara\u1e47a\u1e41 vraj\u0113ti .\nbh\u016by\u014d\u2019pi mahyam-iha tau kara-dar\u015bitau t\u0113\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 11 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2a\u0c3e\u0c30\u0c4d\u0c25\u0c3e\u0c2f \u0c24\u0c24\u0c4d\u0c38\u0c26\u0c43\u0c36\u0c38\u0c3e\u0c30\u0c25\u0c3f\u0c28\u0c3e \u0c24\u0c4d\u0c35\u0c2f\u0c48\u0c35\n\u0c2f\u0c4c \u0c26\u0c30\u0c4d\u0c36\u0c3f\u0c24\u0c4c \u0c38\u0c4d\u0c35\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c35\u0c4d\u0c30\u0c1c\u0c47\u0c24\u0c3f \u0964\n\u0c2d\u0c42\u0c2f\u0c4b\u0c3d\u0c2a\u0c3f \u0c2e\u0c39\u0c4d\u0c2f\u0c2e\u0c3f\u0c39 \u0c24\u0c4c \u0c15\u0c30\u0c26\u0c30\u0c4d\u0c36\u0c3f\u0c24\u0c4c \u0c24\u0c47\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c67\u0c67 \u0965", "tamil": "\u0baa\u0bbe\u0bb0\u0bcd\u0ba4\u0bbe\u0baf \u0ba4\u0ba4\u0bcd\u0bb8\u0ba4\u0bcd\u0bb0\u0bc1'\u0bb6\u0bb8\u0bbe\u0bb0\u0ba4\u0bbf\u0ba8\u0bbe \u0ba4\u0bcd\u0bb5\u0baf\u0bc8\u0bb5\n\u0baf\u0bcc \u0ba4\u0bb0\u0bcd\u0bb6\u0bbf\u0ba4\u0bcc \u0bb8\u0bcd\u0bb5\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0bb5\u0bcd\u0bb0\u0b9c\u0bc7\u0ba4\u0bbf \u0964\n\u0baa\u0bc2\u0baf\u0bcb\u093d\u0baa\u0bbf \u0bae\u0bb9\u0bcd\u0baf\u0bae\u0bbf\u0bb9 \u0ba4\u0bcc \u0b95\u0bb0\u0ba4\u0bb0\u0bcd\u0bb6\u0bbf\u0ba4\u0bcc \u0ba4\u0bc7\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0be7\u0be7 \u0965", "kannada": "\u0caa\u0cbe\u0cb0\u0ccd\u0ca5\u0cbe\u0caf \u0ca4\u0ca4\u0ccd\u0cb8\u0ca6\u0cc3\u0cb6\u0cb8\u0cbe\u0cb0\u0ca5\u0cbf\u0ca8\u0cbe \u0ca4\u0ccd\u0cb5\u0caf\u0cc8\u0cb5\n\u0caf\u0ccc \u0ca6\u0cb0\u0ccd\u0cb6\u0cbf\u0ca4\u0ccc \u0cb8\u0ccd\u0cb5\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0cb5\u0ccd\u0cb0\u0c9c\u0cc7\u0ca4\u0cbf \u0964\n\u0cad\u0cc2\u0caf\u0ccb\u0cbd\u0caa\u0cbf \u0cae\u0cb9\u0ccd\u0caf\u0cae\u0cbf\u0cb9 \u0ca4\u0ccc \u0c95\u0cb0\u0ca6\u0cb0\u0ccd\u0cb6\u0cbf\u0ca4\u0ccc \u0ca4\u0cc7\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0ce7\u0ce7 \u0965", "malayalam": "\u0d2a\u0d3e\u0d30\u0d4d\u0d25\u0d3e\u0d2f \u0d24\u0d24\u0d4d\u0d38\u0d26\u0d43\u0d36\u0d38\u0d3e\u0d30\u0d25\u0d3f\u0d28\u0d3e \u0d24\u0d4d\u0d35\u0d2f\u0d48\u0d35\n\u0d2f\u0d4c \u0d26\u0d30\u0d4d\u0d36\u0d3f\u0d24\u0d4c \u0d38\u0d4d\u0d35\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d35\u0d4d\u0d30\u0d1c\u0d47\u0d24\u0d3f \u0964\n\u0d2d\u0d42\u0d2f\u0d4b\u0d3d\u0d2a\u0d3f \u0d2e\u0d39\u0d4d\u0d2f\u0d2e\u0d3f\u0d39 \u0d24\u0d4c \u0d15\u0d30\u0d26\u0d30\u0d4d\u0d36\u0d3f\u0d24\u0d4c \u0d24\u0d47\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d67\u0d67 \u0965", "iast": "p\u0101rth\u0101ya tatsad\u1e5b\u015bas\u0101rathin\u0101 tvayaiva\nyau dar\u015bitau svacara\u1e47au \u015bara\u1e47a\u1e43 vrajeti |\nbh\u016byo'pi mahyamiha tau karadar\u015bitau te\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 11 ||"},
        draftTranslation: "Which in the Gita Thou Thyself, acting as Arjuna\u2019s chariot driver, didst reveal saying: \"Surrender unto Me alone!\" (m\u0101m eka\u1e41 \u015bara\u1e47a\u1e41 vraja), and which here on Tirumala Thou pointest to again with Thy hand for my salvation \u2014 I surrender at the holy feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 52,
        devanagariText: "\u092e\u0928\u094d\u092e\u0942\u0930\u094d\u0927\u094d\u0928\u093f \u0915\u093e\u0932\u093f\u092f\u092b\u0923\u0947 \u0935\u093f\u0915\u091f\u093e\u091f\u0935\u0940\u0937\u0941\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u0926\u094d\u0930\u093f\u0936\u093f\u0916\u0930\u0947 \u0936\u093f\u0930\u0938\u093f \u0936\u094d\u0930\u0941\u0924\u0940\u0928\u093e\u092e\u094d \u0964\n\u091a\u093f\u0924\u094d\u0924\u0947\u093d\u092a\u094d\u092f\u0928\u0928\u094d\u092f\u092e\u0928\u0938\u093e\u0902 \u0938\u092e\u092e\u093e\u0939\u093f\u0924\u094c \u0924\u0947\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u0967\u0968 \u0965",
        iastText: "man-m\u016brdhni k\u0101liya-pha\u1e47\u0113 vika\u1e6d\u0101\u1e6dav\u012b\u1e63u\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0101dri-\u015bikhar\u0113 \u015birasi \u015brut\u012bn\u0101m .\ncitt\u0113\u2019py-ananya-manas\u0101\u1e41 samam-\u0101hitau t\u0113\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 12 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2e\u0c28\u0c4d\u0c2e\u0c42\u0c30\u0c4d\u0c27\u0c4d\u0c28\u0c3f \u0c15\u0c3e\u0c32\u0c3f\u0c2f\u0c2b\u0c23\u0c47 \u0c35\u0c3f\u0c15\u0c1f\u0c3e\u0c1f\u0c35\u0c40\u0c37\u0c41\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c26\u0c4d\u0c30\u0c3f\u0c36\u0c3f\u0c16\u0c30\u0c47 \u0c36\u0c3f\u0c30\u0c38\u0c3f \u0c36\u0c4d\u0c30\u0c41\u0c24\u0c40\u0c28\u0c3e\u0c2e\u0c4d \u0964\n\u0c1a\u0c3f\u0c24\u0c4d\u0c24\u0c47\u0c3d\u0c2a\u0c4d\u0c2f\u0c28\u0c28\u0c4d\u0c2f\u0c2e\u0c28\u0c38\u0c3e\u0c02 \u0c38\u0c2e\u0c2e\u0c3e\u0c39\u0c3f\u0c24\u0c4c \u0c24\u0c47\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c67\u0c68 \u0965", "tamil": "\u0bae\u0ba8\u0bcd\u0bae\u0bc2\u0bb0\u0bcd\u0ba4\u0bcd\u0ba8\u0bbf \u0b95\u0bbe\u0bb2\u0bbf\u0baf\u0baa\u0ba3\u0bc7 \u0bb5\u0bbf\u0b95\u0b9f\u0bbe\u0b9f\u0bb5\u0bc0\u0bb7\u0bc1\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0ba4\u0bcd\u0bb0\u0bbf\u0bb6\u0bbf\u0b95\u0bb0\u0bc7 \u0bb6\u0bbf\u0bb0\u0bb8\u0bbf \u0bb6\u0bcd\u0bb0\u0bc1\u0ba4\u0bc0\u0ba8\u0bbe\u0bae\u0bcd \u0964\n\u0b9a\u0bbf\u0ba4\u0bcd\u0ba4\u0bc7\u093d\u0baa\u0bcd\u0baf\u0ba8\u0ba8\u0bcd\u0baf\u0bae\u0ba8\u0bb8\u0bbe\u0bae\u0bcd \u0bb8\u0bae\u0bae\u0bbe\u0bb9\u0bbf\u0ba4\u0bcc \u0ba4\u0bc7\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0be7\u0be8 \u0965", "kannada": "\u0cae\u0ca8\u0ccd\u0cae\u0cc2\u0cb0\u0ccd\u0ca7\u0ccd\u0ca8\u0cbf \u0c95\u0cbe\u0cb2\u0cbf\u0caf\u0cab\u0ca3\u0cc7 \u0cb5\u0cbf\u0c95\u0c9f\u0cbe\u0c9f\u0cb5\u0cc0\u0cb7\u0cc1\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0ca6\u0ccd\u0cb0\u0cbf\u0cb6\u0cbf\u0c96\u0cb0\u0cc7 \u0cb6\u0cbf\u0cb0\u0cb8\u0cbf \u0cb6\u0ccd\u0cb0\u0cc1\u0ca4\u0cc0\u0ca8\u0cbe\u0cae\u0ccd \u0964\n\u0c9a\u0cbf\u0ca4\u0ccd\u0ca4\u0cc7\u0cbd\u0caa\u0ccd\u0caf\u0ca8\u0ca8\u0ccd\u0caf\u0cae\u0ca8\u0cb8\u0cbe\u0c82 \u0cb8\u0cae\u0cae\u0cbe\u0cb9\u0cbf\u0ca4\u0ccc \u0ca4\u0cc7\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0ce7\u0ce8 \u0965", "malayalam": "\u0d2e\u0d28\u0d4d\u0d2e\u0d42\u0d30\u0d4d\u0d27\u0d4d\u0d28\u0d3f \u0d15\u0d3e\u0d32\u0d3f\u0d2f\u0d2b\u0d23\u0d47 \u0d35\u0d3f\u0d15\u0d1f\u0d3e\u0d1f\u0d35\u0d40\u0d37\u0d41\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d26\u0d4d\u0d30\u0d3f\u0d36\u0d3f\u0d16\u0d30\u0d47 \u0d36\u0d3f\u0d30\u0d38\u0d3f \u0d36\u0d4d\u0d30\u0d41\u0d24\u0d40\u0d28\u0d3e\u0d2e\u0d4d \u0964\n\u0d1a\u0d3f\u0d24\u0d4d\u0d24\u0d47\u0d3d\u0d2a\u0d4d\u0d2f\u0d28\u0d28\u0d4d\u0d2f\u0d2e\u0d28\u0d38\u0d3e\u0d02 \u0d38\u0d2e\u0d2e\u0d3e\u0d39\u0d3f\u0d24\u0d4c \u0d24\u0d47\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d67\u0d68 \u0965", "iast": "manm\u016brdhni k\u0101liyapha\u1e47e vika\u1e6d\u0101\u1e6dav\u012b\u1e63u\n\u015br\u012bve\u1e45ka\u1e6d\u0101dri\u015bikhare \u015birasi \u015brut\u012bn\u0101m |\ncitte'pyananyamanas\u0101\u1e43 samam\u0101hitau te\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 12 ||"},
        draftTranslation: "Resting with equal grace upon the hoods of serpent Kaliya, across the rugged forests of Dandaka, atop the peaks of Mount Venkata, crowned upon the crest of the Upanishads (Vedas), within the hearts of one-pointed devotees, and now upon my humble head \u2014 I surrender at the holy feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 53,
        devanagariText: "\u0905\u092e\u094d\u0932\u093e\u0928\u0939\u0943\u0937\u094d\u092f\u0926\u0935\u0928\u0940\u0924\u0930\u093e\u0915\u0940\u0930\u094d\u0923\u092a\u0941\u0937\u094d\u092a\u094c\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u0926\u094d\u0930\u093f\u0936\u093f\u0916\u0930\u093e\u092d\u0930\u0923\u093e\u092f\u092e\u093e\u0928\u094c \u0964\n\u0906\u0928\u0928\u094d\u0926\u093f\u0924\u093e\u0916\u093f\u0932\u092e\u0928\u094b\u0928\u092f\u0928\u094c \u0924\u0935\u0948\u0924\u094c\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u0967\u0969 \u0965",
        iastText: "aml\u0101na-h\u1e5b\u1e63yad-avan\u012btal\u0101-k\u012br\u1e47a-pu\u1e63pau\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0101dri-\u015bikhar\u0101bhara\u1e47\u0101yam\u0101nau .\n\u0101nandit\u0101khila-man\u014d-nayanau tavaitau\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 13 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c05\u0c2e\u0c4d\u0c32\u0c3e\u0c28\u0c39\u0c43\u0c37\u0c4d\u0c2f\u0c26\u0c35\u0c28\u0c40\u0c24\u0c30\u0c3e\u0c15\u0c40\u0c30\u0c4d\u0c23\u0c2a\u0c41\u0c37\u0c4d\u0c2a\u0c4c\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c26\u0c4d\u0c30\u0c3f\u0c36\u0c3f\u0c16\u0c30\u0c3e\u0c2d\u0c30\u0c23\u0c3e\u0c2f\u0c2e\u0c3e\u0c28\u0c4c \u0964\n\u0c06\u0c28\u0c28\u0c4d\u0c26\u0c3f\u0c24\u0c3e\u0c16\u0c3f\u0c32\u0c2e\u0c28\u0c4b\u0c28\u0c2f\u0c28\u0c4c \u0c24\u0c35\u0c48\u0c24\u0c4c\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c67\u0c69 \u0965", "tamil": "\u0b85\u0bae\u0bcd\u0bb2\u0bbe\u0ba8\u0bb9\u0bcd\u0bb0\u0bc1'\u0bb7\u0bcd\u0baf\u0ba4\u0bb5\u0ba8\u0bc0\u0ba4\u0bb0\u0bbe\u0b95\u0bc0\u0bb0\u0bcd\u0ba3\u0baa\u0bc1\u0bb7\u0bcd\u0baa\u0bcc\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0ba4\u0bcd\u0bb0\u0bbf\u0bb6\u0bbf\u0b95\u0bb0\u0bbe\u0baa\u0bb0\u0ba3\u0bbe\u0baf\u0bae\u0bbe\u0ba8\u0bcc \u0964\n\u0b86\u0ba8\u0ba8\u0bcd\u0ba4\u0bbf\u0ba4\u0bbe\u0b95\u0bbf\u0bb2\u0bae\u0ba8\u0bcb\u0ba8\u0baf\u0ba8\u0bcc \u0ba4\u0bb5\u0bc8\u0ba4\u0bcc\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0be7\u0be9 \u0965", "kannada": "\u0c85\u0cae\u0ccd\u0cb2\u0cbe\u0ca8\u0cb9\u0cc3\u0cb7\u0ccd\u0caf\u0ca6\u0cb5\u0ca8\u0cc0\u0ca4\u0cb0\u0cbe\u0c95\u0cc0\u0cb0\u0ccd\u0ca3\u0caa\u0cc1\u0cb7\u0ccd\u0caa\u0ccc\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0ca6\u0ccd\u0cb0\u0cbf\u0cb6\u0cbf\u0c96\u0cb0\u0cbe\u0cad\u0cb0\u0ca3\u0cbe\u0caf\u0cae\u0cbe\u0ca8\u0ccc \u0964\n\u0c86\u0ca8\u0ca8\u0ccd\u0ca6\u0cbf\u0ca4\u0cbe\u0c96\u0cbf\u0cb2\u0cae\u0ca8\u0ccb\u0ca8\u0caf\u0ca8\u0ccc \u0ca4\u0cb5\u0cc8\u0ca4\u0ccc\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0ce7\u0ce9 \u0965", "malayalam": "\u0d05\u0d2e\u0d4d\u0d32\u0d3e\u0d28\u0d39\u0d43\u0d37\u0d4d\u0d2f\u0d26\u0d35\u0d28\u0d40\u0d24\u0d30\u0d3e\u0d15\u0d40\u0d30\u0d4d\u0d23\u0d2a\u0d41\u0d37\u0d4d\u0d2a\u0d4c\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d26\u0d4d\u0d30\u0d3f\u0d36\u0d3f\u0d16\u0d30\u0d3e\u0d2d\u0d30\u0d23\u0d3e\u0d2f\u0d2e\u0d3e\u0d28\u0d4c \u0964\n\u0d06\u0d28\u0d28\u0d4d\u0d26\u0d3f\u0d24\u0d3e\u0d16\u0d3f\u0d32\u0d2e\u0d28\u0d4b\u0d28\u0d2f\u0d28\u0d4c \u0d24\u0d35\u0d48\u0d24\u0d4c\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d67\u0d69 \u0965", "iast": "aml\u0101nah\u1e5b\u1e63yadavan\u012btar\u0101k\u012br\u1e47apu\u1e63pau\n\u015br\u012bve\u1e45ka\u1e6d\u0101dri\u015bikhar\u0101bhara\u1e47\u0101yam\u0101nau |\n\u0101nandit\u0101khilamanonayanau tavaitau\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 13 ||"},
        draftTranslation: "Strewn with unfading, joyous celestial flowers fallen upon the sacred ground, serving as the crown jewel adorning the pinnacle of Mount Venkata, delighting the minds and eyes of all living beings \u2014 I surrender at the holy feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 54,
        devanagariText: "\u092a\u094d\u0930\u093e\u092f\u0903 \u092a\u094d\u0930\u092a\u0928\u094d\u0928\u091c\u0928\u0924\u093e\u092a\u094d\u0930\u0925\u092e\u093e\u0935\u0917\u093e\u0939\u094d\u092f\u094c\n\u092e\u093e\u0924\u0941\u0903 \u0938\u094d\u0924\u0928\u093e\u0935\u093f\u0935 \u0936\u093f\u0936\u094b\u0930\u092e\u0943\u0924\u093e\u092f\u092e\u093e\u0928\u094c \u0964\n\u092a\u094d\u0930\u093e\u092a\u094d\u0924\u094c \u092a\u0930\u0938\u094d\u092a\u0930\u0924\u0941\u0932\u093e\u092e\u092a\u094d\u092f\u0924\u0941\u0932\u093e\u0928\u094d\u0924\u0930\u094c \u0924\u0947\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u0967\u096a \u0965",
        iastText: "pr\u0101ya\u1e25 prapanna-janat\u0101-pratham\u0101vag\u0101hyau\nm\u0101tu\u1e25 stan\u0101viva \u015bi\u015b\u014dr-am\u1e5bt\u0101yam\u0101nau .\npr\u0101ptau paraspara-tul\u0101m-apy-atul\u0101ntarau t\u0113\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 14 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2a\u0c4d\u0c30\u0c3e\u0c2f\u0c03 \u0c2a\u0c4d\u0c30\u0c2a\u0c28\u0c4d\u0c28\u0c1c\u0c28\u0c24\u0c3e\u0c2a\u0c4d\u0c30\u0c25\u0c2e\u0c3e\u0c35\u0c17\u0c3e\u0c39\u0c4d\u0c2f\u0c4c\n\u0c2e\u0c3e\u0c24\u0c41\u0c03 \u0c38\u0c4d\u0c24\u0c28\u0c3e\u0c35\u0c3f\u0c35 \u0c36\u0c3f\u0c36\u0c4b\u0c30\u0c2e\u0c43\u0c24\u0c3e\u0c2f\u0c2e\u0c3e\u0c28\u0c4c \u0964\n\u0c2a\u0c4d\u0c30\u0c3e\u0c2a\u0c4d\u0c24\u0c4c \u0c2a\u0c30\u0c38\u0c4d\u0c2a\u0c30\u0c24\u0c41\u0c32\u0c3e\u0c2e\u0c2a\u0c4d\u0c2f\u0c24\u0c41\u0c32\u0c3e\u0c28\u0c4d\u0c24\u0c30\u0c4c \u0c24\u0c47\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c67\u0c6a \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0bbe\u0baf\u0b83 \u0baa\u0bcd\u0bb0\u0baa\u0ba8\u0bcd\u0ba8\u0b9c\u0ba8\u0ba4\u0bbe\u0baa\u0bcd\u0bb0\u0ba4\u0bae\u0bbe\u0bb5\u0b95\u0bbe\u0bb9\u0bcd\u0baf\u0bcc\n\u0bae\u0bbe\u0ba4\u0bc1\u0b83 \u0bb8\u0bcd\u0ba4\u0ba8\u0bbe\u0bb5\u0bbf\u0bb5 \u0bb6\u0bbf\u0bb6\u0bcb\u0bb0\u0bae\u0bcd\u0bb0\u0bc1'\u0ba4\u0bbe\u0baf\u0bae\u0bbe\u0ba8\u0bcc \u0964\n\u0baa\u0bcd\u0bb0\u0bbe\u0baa\u0bcd\u0ba4\u0bcc \u0baa\u0bb0\u0bb8\u0bcd\u0baa\u0bb0\u0ba4\u0bc1\u0bb2\u0bbe\u0bae\u0baa\u0bcd\u0baf\u0ba4\u0bc1\u0bb2\u0bbe\u0ba8\u0bcd\u0ba4\u0bb0\u0bcc \u0ba4\u0bc7\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0be7\u0bea \u0965", "kannada": "\u0caa\u0ccd\u0cb0\u0cbe\u0caf\u0c83 \u0caa\u0ccd\u0cb0\u0caa\u0ca8\u0ccd\u0ca8\u0c9c\u0ca8\u0ca4\u0cbe\u0caa\u0ccd\u0cb0\u0ca5\u0cae\u0cbe\u0cb5\u0c97\u0cbe\u0cb9\u0ccd\u0caf\u0ccc\n\u0cae\u0cbe\u0ca4\u0cc1\u0c83 \u0cb8\u0ccd\u0ca4\u0ca8\u0cbe\u0cb5\u0cbf\u0cb5 \u0cb6\u0cbf\u0cb6\u0ccb\u0cb0\u0cae\u0cc3\u0ca4\u0cbe\u0caf\u0cae\u0cbe\u0ca8\u0ccc \u0964\n\u0caa\u0ccd\u0cb0\u0cbe\u0caa\u0ccd\u0ca4\u0ccc \u0caa\u0cb0\u0cb8\u0ccd\u0caa\u0cb0\u0ca4\u0cc1\u0cb2\u0cbe\u0cae\u0caa\u0ccd\u0caf\u0ca4\u0cc1\u0cb2\u0cbe\u0ca8\u0ccd\u0ca4\u0cb0\u0ccc \u0ca4\u0cc7\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0ce7\u0cea \u0965", "malayalam": "\u0d2a\u0d4d\u0d30\u0d3e\u0d2f\u0d03 \u0d2a\u0d4d\u0d30\u0d2a\u0d28\u0d4d\u0d28\u0d1c\u0d28\u0d24\u0d3e\u0d2a\u0d4d\u0d30\u0d25\u0d2e\u0d3e\u0d35\u0d17\u0d3e\u0d39\u0d4d\u0d2f\u0d4c\n\u0d2e\u0d3e\u0d24\u0d41\u0d03 \u0d38\u0d4d\u0d24\u0d28\u0d3e\u0d35\u0d3f\u0d35 \u0d36\u0d3f\u0d36\u0d4b\u0d30\u0d2e\u0d43\u0d24\u0d3e\u0d2f\u0d2e\u0d3e\u0d28\u0d4c \u0964\n\u0d2a\u0d4d\u0d30\u0d3e\u0d2a\u0d4d\u0d24\u0d4c \u0d2a\u0d30\u0d38\u0d4d\u0d2a\u0d30\u0d24\u0d41\u0d32\u0d3e\u0d2e\u0d2a\u0d4d\u0d2f\u0d24\u0d41\u0d32\u0d3e\u0d28\u0d4d\u0d24\u0d30\u0d4c \u0d24\u0d47\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d67\u0d6a \u0965", "iast": "pr\u0101ya\u1e25 prapannajanat\u0101pratham\u0101vag\u0101hyau\nm\u0101tu\u1e25 stan\u0101viva \u015bi\u015boram\u1e5bt\u0101yam\u0101nau |\npr\u0101ptau parasparatul\u0101mapyatul\u0101ntarau te\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 14 ||"},
        draftTranslation: "Which are the first and foremost refuge for surrendered souls, nourishing them like a mother\u2019s nectar-filled breasts nourish an infant child, incomparable to anything else in the world except to each other \u2014 I surrender at the holy feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 55,
        devanagariText: "\u0938\u0924\u094d\u0924\u094d\u0935\u094b\u0924\u094d\u0924\u0930\u0948\u0903 \u0938\u0924\u0924\u0938\u0947\u0935\u094d\u092f\u092a\u0926\u093e\u0902\u092c\u0941\u091c\u0947\u0928\n\u0938\u0902\u0938\u093e\u0930\u0924\u093e\u0930\u0915\u0926\u092f\u093e\u0930\u094d\u0926\u094d\u0930\u0926\u0943\u0917\u091e\u094d\u091a\u0932\u0947\u0928 \u0964\n\u0938\u094c\u092e\u094d\u092f\u094b\u092a\u092f\u0928\u094d\u0924\u0943\u092e\u0941\u0928\u093f\u0928\u093e \u092e\u092e \u0926\u0930\u094d\u0936\u093f\u0924\u094c \u0924\u0947\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u091a\u0930\u0923\u094c \u0936\u0930\u0923\u0902 \u092a\u094d\u0930\u092a\u0926\u094d\u092f\u0947 \u0965 \u0967\u096b \u0965",
        iastText: "sattv\u014dttarai\u1e25 satata-s\u0113vya-pad\u0101mbuj\u0113na\nsa\u1e41s\u0101ra-t\u0101raka-day\u0101rdra-d\u1e5bga\u00f1cal\u0113na .\nsaumy\u014dpayant\u1e5b-munin\u0101 mama dar\u015bitau t\u0113\n\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0113\u015ba-cara\u1e47au \u015bara\u1e47a\u1e41 prapady\u0113 .. 15 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c38\u0c24\u0c4d\u0c24\u0c4d\u0c35\u0c4b\u0c24\u0c4d\u0c24\u0c30\u0c48\u0c03 \u0c38\u0c24\u0c24\u0c38\u0c47\u0c35\u0c4d\u0c2f\u0c2a\u0c26\u0c3e\u0c02\u0c2c\u0c41\u0c1c\u0c47\u0c28\n\u0c38\u0c02\u0c38\u0c3e\u0c30\u0c24\u0c3e\u0c30\u0c15\u0c26\u0c2f\u0c3e\u0c30\u0c4d\u0c26\u0c4d\u0c30\u0c26\u0c43\u0c17\u0c1e\u0c4d\u0c1a\u0c32\u0c47\u0c28 \u0964\n\u0c38\u0c4c\u0c2e\u0c4d\u0c2f\u0c4b\u0c2a\u0c2f\u0c28\u0c4d\u0c24\u0c43\u0c2e\u0c41\u0c28\u0c3f\u0c28\u0c3e \u0c2e\u0c2e \u0c26\u0c30\u0c4d\u0c36\u0c3f\u0c24\u0c4c \u0c24\u0c47\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c1a\u0c30\u0c23\u0c4c \u0c36\u0c30\u0c23\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0c26\u0c4d\u0c2f\u0c47 \u0965 \u0c67\u0c6b \u0965", "tamil": "\u0bb8\u0ba4\u0bcd\u0ba4\u0bcd\u0bb5\u0bcb\u0ba4\u0bcd\u0ba4\u0bb0\u0bc8\u0b83 \u0bb8\u0ba4\u0ba4\u0bb8\u0bc7\u0bb5\u0bcd\u0baf\u0baa\u0ba4\u0bbe\u0bae\u0bcd\u0baa\u0bc1\u0b9c\u0bc7\u0ba8\n\u0bb8\u0bae\u0bcd\u0bb8\u0bbe\u0bb0\u0ba4\u0bbe\u0bb0\u0b95\u0ba4\u0baf\u0bbe\u0bb0\u0bcd\u0ba4\u0bcd\u0bb0\u0ba4\u0bcd\u0bb0\u0bc1'\u0b95\u0b9e\u0bcd\u0b9a\u0bb2\u0bc7\u0ba8 \u0964\n\u0bb8\u0bcc\u0bae\u0bcd\u0baf\u0bcb\u0baa\u0baf\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bc1'\u0bae\u0bc1\u0ba8\u0bbf\u0ba8\u0bbe \u0bae\u0bae \u0ba4\u0bb0\u0bcd\u0bb6\u0bbf\u0ba4\u0bcc \u0ba4\u0bc7\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0b9a\u0bb0\u0ba3\u0bcc \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bcd\u0baf\u0bc7 \u0965 \u0be7\u0beb \u0965", "kannada": "\u0cb8\u0ca4\u0ccd\u0ca4\u0ccd\u0cb5\u0ccb\u0ca4\u0ccd\u0ca4\u0cb0\u0cc8\u0c83 \u0cb8\u0ca4\u0ca4\u0cb8\u0cc7\u0cb5\u0ccd\u0caf\u0caa\u0ca6\u0cbe\u0c82\u0cac\u0cc1\u0c9c\u0cc7\u0ca8\n\u0cb8\u0c82\u0cb8\u0cbe\u0cb0\u0ca4\u0cbe\u0cb0\u0c95\u0ca6\u0caf\u0cbe\u0cb0\u0ccd\u0ca6\u0ccd\u0cb0\u0ca6\u0cc3\u0c97\u0c9e\u0ccd\u0c9a\u0cb2\u0cc7\u0ca8 \u0964\n\u0cb8\u0ccc\u0cae\u0ccd\u0caf\u0ccb\u0caa\u0caf\u0ca8\u0ccd\u0ca4\u0cc3\u0cae\u0cc1\u0ca8\u0cbf\u0ca8\u0cbe \u0cae\u0cae \u0ca6\u0cb0\u0ccd\u0cb6\u0cbf\u0ca4\u0ccc \u0ca4\u0cc7\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0c9a\u0cb0\u0ca3\u0ccc \u0cb6\u0cb0\u0ca3\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0ca6\u0ccd\u0caf\u0cc7 \u0965 \u0ce7\u0ceb \u0965", "malayalam": "\u0d38\u0d24\u0d4d\u0d24\u0d4d\u0d35\u0d4b\u0d24\u0d4d\u0d24\u0d30\u0d48\u0d03 \u0d38\u0d24\u0d24\u0d38\u0d47\u0d35\u0d4d\u0d2f\u0d2a\u0d26\u0d3e\u0d02\u0d2c\u0d41\u0d1c\u0d47\u0d28\n\u0d38\u0d02\u0d38\u0d3e\u0d30\u0d24\u0d3e\u0d30\u0d15\u0d26\u0d2f\u0d3e\u0d30\u0d4d\u0d26\u0d4d\u0d30\u0d26\u0d43\u0d17\u0d1e\u0d4d\u0d1a\u0d32\u0d47\u0d28 \u0964\n\u0d38\u0d4c\u0d2e\u0d4d\u0d2f\u0d4b\u0d2a\u0d2f\u0d28\u0d4d\u0d24\u0d43\u0d2e\u0d41\u0d28\u0d3f\u0d28\u0d3e \u0d2e\u0d2e \u0d26\u0d30\u0d4d\u0d36\u0d3f\u0d24\u0d4c \u0d24\u0d47\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d1a\u0d30\u0d23\u0d4c \u0d36\u0d30\u0d23\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0d26\u0d4d\u0d2f\u0d47 \u0965 \u0d67\u0d6b \u0965", "iast": "sattvottarai\u1e25 satatasevyapad\u0101\u1e43bujena\nsa\u1e43s\u0101rat\u0101rakaday\u0101rdrad\u1e5bga\u00f1calena |\nsaumyopayant\u1e5bmunin\u0101 mama dar\u015bitau te\n\u015br\u012bve\u1e45ka\u1e6de\u015bacara\u1e47au \u015bara\u1e47a\u1e43 prapadye || 15 ||"},
        draftTranslation: "Which were mercifully revealed to me by my revered Preceptor, Swami Manavala Mamunigal (Saumyopayantr Muni), whose lotus feet are constantly served by pure sattvic devotees and whose compassionate sidelong glance delivers souls from the ocean of samsara \u2014 I surrender at the holy feet of Lord Venkateswara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 56,
        devanagariText: "\u0936\u094d\u0930\u0940\u0936 \u0936\u094d\u0930\u093f\u092f\u093e \u0918\u091f\u093f\u0915\u092f\u093e \u0924\u094d\u0935\u0926\u0941\u092a\u093e\u092f\u092d\u093e\u0935\u0947\n\u092a\u094d\u0930\u093e\u092a\u094d\u092f\u0947 \u0924\u094d\u0935\u092f\u093f \u0938\u094d\u0935\u092f\u092e\u0941\u092a\u0947\u092f\u0924\u092f\u093e \u0938\u094d\u092b\u0941\u0930\u0928\u094d\u0924\u094d\u092f\u093e \u0964\n\u0928\u093f\u0924\u094d\u092f\u093e\u0936\u094d\u0930\u093f\u0924\u093e\u092f \u0928\u093f\u0930\u0935\u0926\u094d\u092f\u0917\u0941\u0923\u093e\u092f \u0924\u0941\u092d\u094d\u092f\u0902\n\u0938\u094d\u092f\u093e\u0902 \u0915\u093f\u0919\u094d\u0915\u0930\u094b \u0935\u0943\u0937\u0917\u093f\u0930\u0940\u0936 \u0928 \u091c\u093e\u0924\u0941 \u092e\u0939\u094d\u092f\u092e\u094d \u0965 \u0967\u096c \u0965",
        iastText: "\u015br\u012b\u015ba \u015briy\u0101 gha\u1e6dikay\u0101 tvad-up\u0101ya-bh\u0101v\u0113\npr\u0101py\u0113 tvayi svayam-up\u0113yatay\u0101 sphuranty\u0101 .\nnity\u0101\u015brit\u0101ya niravadya-gu\u1e47\u0101ya tubhya\u1e41\nsy\u0101\u1e41 ki\u1e45kar\u014d v\u1e5b\u1e63agir\u012b\u015ba na j\u0101tu mahyam .. 16 ..",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c36\u0c4d\u0c30\u0c40\u0c36 \u0c36\u0c4d\u0c30\u0c3f\u0c2f\u0c3e \u0c18\u0c1f\u0c3f\u0c15\u0c2f\u0c3e \u0c24\u0c4d\u0c35\u0c26\u0c41\u0c2a\u0c3e\u0c2f\u0c2d\u0c3e\u0c35\u0c47\n\u0c2a\u0c4d\u0c30\u0c3e\u0c2a\u0c4d\u0c2f\u0c47 \u0c24\u0c4d\u0c35\u0c2f\u0c3f \u0c38\u0c4d\u0c35\u0c2f\u0c2e\u0c41\u0c2a\u0c47\u0c2f\u0c24\u0c2f\u0c3e \u0c38\u0c4d\u0c2b\u0c41\u0c30\u0c28\u0c4d\u0c24\u0c4d\u0c2f\u0c3e \u0964\n\u0c28\u0c3f\u0c24\u0c4d\u0c2f\u0c3e\u0c36\u0c4d\u0c30\u0c3f\u0c24\u0c3e\u0c2f \u0c28\u0c3f\u0c30\u0c35\u0c26\u0c4d\u0c2f\u0c17\u0c41\u0c23\u0c3e\u0c2f \u0c24\u0c41\u0c2d\u0c4d\u0c2f\u0c02\n\u0c38\u0c4d\u0c2f\u0c3e\u0c02 \u0c15\u0c3f\u0c19\u0c4d\u0c15\u0c30\u0c4b \u0c35\u0c43\u0c37\u0c17\u0c3f\u0c30\u0c40\u0c36 \u0c28 \u0c1c\u0c3e\u0c24\u0c41 \u0c2e\u0c39\u0c4d\u0c2f\u0c2e\u0c4d \u0965 \u0c67\u0c6c \u0965", "tamil": "\u0bb6\u0bcd\u0bb0\u0bc0\u0bb6 \u0bb6\u0bcd\u0bb0\u0bbf\u0baf\u0bbe \u0b95\u0b9f\u0bbf\u0b95\u0baf\u0bbe \u0ba4\u0bcd\u0bb5\u0ba4\u0bc1\u0baa\u0bbe\u0baf\u0baa\u0bbe\u0bb5\u0bc7\n\u0baa\u0bcd\u0bb0\u0bbe\u0baa\u0bcd\u0baf\u0bc7 \u0ba4\u0bcd\u0bb5\u0baf\u0bbf \u0bb8\u0bcd\u0bb5\u0baf\u0bae\u0bc1\u0baa\u0bc7\u0baf\u0ba4\u0baf\u0bbe \u0bb8\u0bcd\u0baa\u0bc1\u0bb0\u0ba8\u0bcd\u0ba4\u0bcd\u0baf\u0bbe \u0964\n\u0ba8\u0bbf\u0ba4\u0bcd\u0baf\u0bbe\u0bb6\u0bcd\u0bb0\u0bbf\u0ba4\u0bbe\u0baf \u0ba8\u0bbf\u0bb0\u0bb5\u0ba4\u0bcd\u0baf\u0b95\u0bc1\u0ba3\u0bbe\u0baf \u0ba4\u0bc1\u0baa\u0bcd\u0baf\u0bae\u0bcd\n\u0bb8\u0bcd\u0baf\u0bbe\u0bae\u0bcd \u0b95\u0bbf\u0b99\u0bcd\u0b95\u0bb0\u0bcb \u0bb5\u0bcd\u0bb0\u0bc1'\u0bb7\u0b95\u0bbf\u0bb0\u0bc0\u0bb6 \u0ba8 \u0b9c\u0bbe\u0ba4\u0bc1 \u0bae\u0bb9\u0bcd\u0baf\u0bae\u0bcd \u0965 \u0be7\u0bec \u0965", "kannada": "\u0cb6\u0ccd\u0cb0\u0cc0\u0cb6 \u0cb6\u0ccd\u0cb0\u0cbf\u0caf\u0cbe \u0c98\u0c9f\u0cbf\u0c95\u0caf\u0cbe \u0ca4\u0ccd\u0cb5\u0ca6\u0cc1\u0caa\u0cbe\u0caf\u0cad\u0cbe\u0cb5\u0cc7\n\u0caa\u0ccd\u0cb0\u0cbe\u0caa\u0ccd\u0caf\u0cc7 \u0ca4\u0ccd\u0cb5\u0caf\u0cbf \u0cb8\u0ccd\u0cb5\u0caf\u0cae\u0cc1\u0caa\u0cc7\u0caf\u0ca4\u0caf\u0cbe \u0cb8\u0ccd\u0cab\u0cc1\u0cb0\u0ca8\u0ccd\u0ca4\u0ccd\u0caf\u0cbe \u0964\n\u0ca8\u0cbf\u0ca4\u0ccd\u0caf\u0cbe\u0cb6\u0ccd\u0cb0\u0cbf\u0ca4\u0cbe\u0caf \u0ca8\u0cbf\u0cb0\u0cb5\u0ca6\u0ccd\u0caf\u0c97\u0cc1\u0ca3\u0cbe\u0caf \u0ca4\u0cc1\u0cad\u0ccd\u0caf\u0c82\n\u0cb8\u0ccd\u0caf\u0cbe\u0c82 \u0c95\u0cbf\u0c99\u0ccd\u0c95\u0cb0\u0ccb \u0cb5\u0cc3\u0cb7\u0c97\u0cbf\u0cb0\u0cc0\u0cb6 \u0ca8 \u0c9c\u0cbe\u0ca4\u0cc1 \u0cae\u0cb9\u0ccd\u0caf\u0cae\u0ccd \u0965 \u0ce7\u0cec \u0965", "malayalam": "\u0d36\u0d4d\u0d30\u0d40\u0d36 \u0d36\u0d4d\u0d30\u0d3f\u0d2f\u0d3e \u0d18\u0d1f\u0d3f\u0d15\u0d2f\u0d3e \u0d24\u0d4d\u0d35\u0d26\u0d41\u0d2a\u0d3e\u0d2f\u0d2d\u0d3e\u0d35\u0d47\n\u0d2a\u0d4d\u0d30\u0d3e\u0d2a\u0d4d\u0d2f\u0d47 \u0d24\u0d4d\u0d35\u0d2f\u0d3f \u0d38\u0d4d\u0d35\u0d2f\u0d2e\u0d41\u0d2a\u0d47\u0d2f\u0d24\u0d2f\u0d3e \u0d38\u0d4d\u0d2b\u0d41\u0d30\u0d28\u0d4d\u0d24\u0d4d\u0d2f\u0d3e \u0964\n\u0d28\u0d3f\u0d24\u0d4d\u0d2f\u0d3e\u0d36\u0d4d\u0d30\u0d3f\u0d24\u0d3e\u0d2f \u0d28\u0d3f\u0d30\u0d35\u0d26\u0d4d\u0d2f\u0d17\u0d41\u0d23\u0d3e\u0d2f \u0d24\u0d41\u0d2d\u0d4d\u0d2f\u0d02\n\u0d38\u0d4d\u0d2f\u0d3e\u0d02 \u0d15\u0d3f\u0d19\u0d4d\u0d15\u0d30\u0d4b \u0d35\u0d43\u0d37\u0d17\u0d3f\u0d30\u0d40\u0d36 \u0d28 \u0d1c\u0d3e\u0d24\u0d41 \u0d2e\u0d39\u0d4d\u0d2f\u0d2e\u0d4d \u0965 \u0d67\u0d6c \u0965", "iast": "\u015br\u012b\u015ba \u015briy\u0101 gha\u1e6dikay\u0101 tvadup\u0101yabh\u0101ve\npr\u0101pye tvayi svayamupeyatay\u0101 sphuranty\u0101 |\nnity\u0101\u015brit\u0101ya niravadyagu\u1e47\u0101ya tubhya\u1e43\nsy\u0101\u1e43 ki\u1e45karo v\u1e5b\u1e63agir\u012b\u015ba na j\u0101tu mahyam || 16 ||"},
        draftTranslation: "O Consort of Sri, Lord of Vrishabhagiri! With Goddess Sri Mahalakshmi acting as the divine mediatrix (Ghatika) in our relationship, while Thou art both the Means (Upaya) and the supreme Goal (Upeya) \u2014 possessing flawless transcendental virtues, may I forever remain Thy dedicated humble servant (kinkara), living never for my selfish ends, but solely for Thy divine pleasure!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 57,
        devanagariText: "\u0936\u094d\u0930\u093f\u092f\u0903 \u0915\u093e\u0928\u094d\u0924\u093e\u092f \u0915\u0932\u094d\u092f\u093e\u0923\u0928\u093f\u0927\u092f\u0947 \u0928\u093f\u0927\u092f\u0947\u093d\u0930\u094d\u0925\u093f\u0928\u093e\u092e\u094d \u0964\n\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u0928\u093f\u0935\u093e\u0938\u093e\u092f \u0936\u094d\u0930\u0940\u0928\u093f\u0935\u093e\u0938\u093e\u092f \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u0967 \u0965",
        iastText: "\u015briya\u1e25 k\u0101nt\u0101ya kaly\u0101\u1e47a-nidhay\u0113 nidhay\u0113\u2019rthin\u0101m .\n\u015br\u012b-v\u0113\u1e45ka\u1e6da-niv\u0101s\u0101ya \u015br\u012bniv\u0101s\u0101ya ma\u1e45galam .. 1 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c36\u0c4d\u0c30\u0c3f\u0c2f\u0c03 \u0c15\u0c3e\u0c28\u0c4d\u0c24\u0c3e\u0c2f \u0c15\u0c32\u0c4d\u0c2f\u0c3e\u0c23\u0c28\u0c3f\u0c27\u0c2f\u0c47 \u0c28\u0c3f\u0c27\u0c2f\u0c47\u0c3d\u0c30\u0c4d\u0c25\u0c3f\u0c28\u0c3e\u0c2e\u0c4d \u0964\n\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c28\u0c3f\u0c35\u0c3e\u0c38\u0c3e\u0c2f \u0c36\u0c4d\u0c30\u0c40\u0c28\u0c3f\u0c35\u0c3e\u0c38\u0c3e\u0c2f \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c67 \u0965", "tamil": "\u0bb6\u0bcd\u0bb0\u0bbf\u0baf\u0b83 \u0b95\u0bbe\u0ba8\u0bcd\u0ba4\u0bbe\u0baf \u0b95\u0bb2\u0bcd\u0baf\u0bbe\u0ba3\u0ba8\u0bbf\u0ba4\u0baf\u0bc7 \u0ba8\u0bbf\u0ba4\u0baf\u0bc7\u093d\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbe\u0bae\u0bcd \u0964\n\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0ba8\u0bbf\u0bb5\u0bbe\u0bb8\u0bbe\u0baf \u0bb6\u0bcd\u0bb0\u0bc0\u0ba8\u0bbf\u0bb5\u0bbe\u0bb8\u0bbe\u0baf \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0be7 \u0965", "kannada": "\u0cb6\u0ccd\u0cb0\u0cbf\u0caf\u0c83 \u0c95\u0cbe\u0ca8\u0ccd\u0ca4\u0cbe\u0caf \u0c95\u0cb2\u0ccd\u0caf\u0cbe\u0ca3\u0ca8\u0cbf\u0ca7\u0caf\u0cc7 \u0ca8\u0cbf\u0ca7\u0caf\u0cc7\u0cbd\u0cb0\u0ccd\u0ca5\u0cbf\u0ca8\u0cbe\u0cae\u0ccd \u0964\n\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0ca8\u0cbf\u0cb5\u0cbe\u0cb8\u0cbe\u0caf \u0cb6\u0ccd\u0cb0\u0cc0\u0ca8\u0cbf\u0cb5\u0cbe\u0cb8\u0cbe\u0caf \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0ce7 \u0965", "malayalam": "\u0d36\u0d4d\u0d30\u0d3f\u0d2f\u0d03 \u0d15\u0d3e\u0d28\u0d4d\u0d24\u0d3e\u0d2f \u0d15\u0d32\u0d4d\u0d2f\u0d3e\u0d23\u0d28\u0d3f\u0d27\u0d2f\u0d47 \u0d28\u0d3f\u0d27\u0d2f\u0d47\u0d3d\u0d30\u0d4d\u0d25\u0d3f\u0d28\u0d3e\u0d2e\u0d4d \u0964\n\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d28\u0d3f\u0d35\u0d3e\u0d38\u0d3e\u0d2f \u0d36\u0d4d\u0d30\u0d40\u0d28\u0d3f\u0d35\u0d3e\u0d38\u0d3e\u0d2f \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d67 \u0965", "iast": "\u015briya\u1e25 k\u0101nt\u0101ya kaly\u0101\u1e47anidhaye nidhaye'rthin\u0101m |\n\u015br\u012bve\u1e45ka\u1e6daniv\u0101s\u0101ya \u015br\u012bniv\u0101s\u0101ya ma\u1e45galam || 1 ||"},
        draftTranslation: "May all auspiciousness (Mangalam) be unto Lord Srinivasa, the beloved Consort of Sri (Lakshmi), the treasury of all auspiciousness, the wish-fulfilling treasure for seekers, who dwells eternally upon Mount Venkata!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 58,
        devanagariText: "\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u0938\u0935\u093f\u092d\u094d\u0930\u092e\u093e\u0932\u094b\u0915\u0938\u0941\u092d\u094d\u0930\u0942\u0935\u093f\u092d\u094d\u0930\u092e\u091a\u0915\u094d\u0937\u0941\u0937\u0947 \u0964\n\u091a\u0915\u094d\u0937\u0941\u0937\u0947 \u0938\u0930\u094d\u0935\u0932\u094b\u0915\u093e\u0928\u093e\u0902 \u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u093e\u092f \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u0968 \u0965",
        iastText: "lak\u1e63m\u012b-sa-vibhram\u0101l\u014dka-subhr\u016b-vibhrama-cak\u1e63u\u1e63\u0113 .\ncak\u1e63u\u1e63\u0113 sarva-l\u014dk\u0101n\u0101\u1e41 v\u0113\u1e45ka\u1e6d\u0113\u015b\u0101ya ma\u1e45galam .. 2 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c40\u0c38\u0c35\u0c3f\u0c2d\u0c4d\u0c30\u0c2e\u0c3e\u0c32\u0c4b\u0c15\u0c38\u0c41\u0c2d\u0c4d\u0c30\u0c42\u0c35\u0c3f\u0c2d\u0c4d\u0c30\u0c2e\u0c1a\u0c15\u0c4d\u0c37\u0c41\u0c37\u0c47 \u0964\n\u0c1a\u0c15\u0c4d\u0c37\u0c41\u0c37\u0c47 \u0c38\u0c30\u0c4d\u0c35\u0c32\u0c4b\u0c15\u0c3e\u0c28\u0c3e\u0c02 \u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c3e\u0c2f \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c68 \u0965", "tamil": "\u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bc0\u0bb8\u0bb5\u0bbf\u0baa\u0bcd\u0bb0\u0bae\u0bbe\u0bb2\u0bcb\u0b95\u0bb8\u0bc1\u0baa\u0bcd\u0bb0\u0bc2\u0bb5\u0bbf\u0baa\u0bcd\u0bb0\u0bae\u0b9a\u0b95\u0bcd\u0bb7\u0bc1\u0bb7\u0bc7 \u0964\n\u0b9a\u0b95\u0bcd\u0bb7\u0bc1\u0bb7\u0bc7 \u0bb8\u0bb0\u0bcd\u0bb5\u0bb2\u0bcb\u0b95\u0bbe\u0ba8\u0bbe\u0bae\u0bcd \u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0bbe\u0baf \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0be8 \u0965", "kannada": "\u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0cc0\u0cb8\u0cb5\u0cbf\u0cad\u0ccd\u0cb0\u0cae\u0cbe\u0cb2\u0ccb\u0c95\u0cb8\u0cc1\u0cad\u0ccd\u0cb0\u0cc2\u0cb5\u0cbf\u0cad\u0ccd\u0cb0\u0cae\u0c9a\u0c95\u0ccd\u0cb7\u0cc1\u0cb7\u0cc7 \u0964\n\u0c9a\u0c95\u0ccd\u0cb7\u0cc1\u0cb7\u0cc7 \u0cb8\u0cb0\u0ccd\u0cb5\u0cb2\u0ccb\u0c95\u0cbe\u0ca8\u0cbe\u0c82 \u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0cbe\u0caf \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0ce8 \u0965", "malayalam": "\u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d40\u0d38\u0d35\u0d3f\u0d2d\u0d4d\u0d30\u0d2e\u0d3e\u0d32\u0d4b\u0d15\u0d38\u0d41\u0d2d\u0d4d\u0d30\u0d42\u0d35\u0d3f\u0d2d\u0d4d\u0d30\u0d2e\u0d1a\u0d15\u0d4d\u0d37\u0d41\u0d37\u0d47 \u0964\n\u0d1a\u0d15\u0d4d\u0d37\u0d41\u0d37\u0d47 \u0d38\u0d30\u0d4d\u0d35\u0d32\u0d4b\u0d15\u0d3e\u0d28\u0d3e\u0d02 \u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d3e\u0d2f \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d68 \u0965", "iast": "lak\u1e63m\u012bsavibhram\u0101lokasubhr\u016bvibhramacak\u1e63u\u1e63e |\ncak\u1e63u\u1e63e sarvalok\u0101n\u0101\u1e43 ve\u1e45ka\u1e6de\u015b\u0101ya ma\u1e45galam || 2 ||"},
        draftTranslation: "Auspiciousness unto Lord Venkateswara, whose lotus eyes lovingly meet the graceful sidelong glances of Goddess Lakshmi, and who is Himself the visionary eye protecting all the worlds!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 59,
        devanagariText: "\u0936\u094d\u0930\u0940\u0935\u0947\u0919\u094d\u0915\u091f\u093e\u0926\u094d\u0930\u093f\u0936\u0943\u0919\u094d\u0917\u093e\u0917\u094d\u0930\u092e\u0919\u094d\u0917\u0932\u093e\u092d\u0930\u0923\u093e\u0919\u094d\u0918\u094d\u0930\u092f\u0947 \u0964\n\u092e\u0919\u094d\u0917\u0932\u093e\u0928\u093e\u0902 \u0928\u093f\u0935\u093e\u0938\u093e\u092f \u0936\u094d\u0930\u0940\u0928\u093f\u0935\u093e\u0938\u093e\u092f \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u0969 \u0965",
        iastText: "\u015br\u012b-v\u0113\u1e45ka\u1e6d\u0101dri-\u015b\u1e5b\u1e45g\u0101gra-ma\u1e45gal\u0101bhara\u1e47\u0101\u1e45ghray\u0113 .\nma\u1e45gal\u0101n\u0101\u1e41 niv\u0101s\u0101ya \u015br\u012bniv\u0101s\u0101ya ma\u1e45galam .. 3 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c3e\u0c26\u0c4d\u0c30\u0c3f\u0c36\u0c43\u0c19\u0c4d\u0c17\u0c3e\u0c17\u0c4d\u0c30\u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c3e\u0c2d\u0c30\u0c23\u0c3e\u0c19\u0c4d\u0c18\u0c4d\u0c30\u0c2f\u0c47 \u0964\n\u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c3e\u0c28\u0c3e\u0c02 \u0c28\u0c3f\u0c35\u0c3e\u0c38\u0c3e\u0c2f \u0c36\u0c4d\u0c30\u0c40\u0c28\u0c3f\u0c35\u0c3e\u0c38\u0c3e\u0c2f \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c69 \u0965", "tamil": "\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bbe\u0ba4\u0bcd\u0bb0\u0bbf\u0bb6\u0bcd\u0bb0\u0bc1'\u0b99\u0bcd\u0b95\u0bbe\u0b95\u0bcd\u0bb0\u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bbe\u0baa\u0bb0\u0ba3\u0bbe\u0b99\u0bcd\u0b95\u0bcd\u0bb0\u0baf\u0bc7 \u0964\n\u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bbe\u0ba8\u0bbe\u0bae\u0bcd \u0ba8\u0bbf\u0bb5\u0bbe\u0bb8\u0bbe\u0baf \u0bb6\u0bcd\u0bb0\u0bc0\u0ba8\u0bbf\u0bb5\u0bbe\u0bb8\u0bbe\u0baf \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0be9 \u0965", "kannada": "\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cbe\u0ca6\u0ccd\u0cb0\u0cbf\u0cb6\u0cc3\u0c99\u0ccd\u0c97\u0cbe\u0c97\u0ccd\u0cb0\u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cbe\u0cad\u0cb0\u0ca3\u0cbe\u0c99\u0ccd\u0c98\u0ccd\u0cb0\u0caf\u0cc7 \u0964\n\u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cbe\u0ca8\u0cbe\u0c82 \u0ca8\u0cbf\u0cb5\u0cbe\u0cb8\u0cbe\u0caf \u0cb6\u0ccd\u0cb0\u0cc0\u0ca8\u0cbf\u0cb5\u0cbe\u0cb8\u0cbe\u0caf \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0ce9 \u0965", "malayalam": "\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d3e\u0d26\u0d4d\u0d30\u0d3f\u0d36\u0d43\u0d19\u0d4d\u0d17\u0d3e\u0d17\u0d4d\u0d30\u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d3e\u0d2d\u0d30\u0d23\u0d3e\u0d19\u0d4d\u0d18\u0d4d\u0d30\u0d2f\u0d47 \u0964\n\u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d3e\u0d28\u0d3e\u0d02 \u0d28\u0d3f\u0d35\u0d3e\u0d38\u0d3e\u0d2f \u0d36\u0d4d\u0d30\u0d40\u0d28\u0d3f\u0d35\u0d3e\u0d38\u0d3e\u0d2f \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d69 \u0965", "iast": "\u015br\u012bve\u1e45ka\u1e6d\u0101dri\u015b\u1e5b\u1e45g\u0101grama\u1e45gal\u0101bhara\u1e47\u0101\u1e45ghraye |\nma\u1e45gal\u0101n\u0101\u1e43 niv\u0101s\u0101ya \u015br\u012bniv\u0101s\u0101ya ma\u1e45galam || 3 ||"},
        draftTranslation: "Auspiciousness unto Lord Srinivasa, whose divine feet serve as the auspicious crest-ornament atop the holy peak of Mount Venkata, and who is Himself the eternal dwelling place of all auspiciousness!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 60,
        devanagariText: "\u0938\u0930\u094d\u0935\u093e\u0935\u092f\u0935\u0938\u094c\u0928\u094d\u0926\u0930\u094d\u092f\u0938\u092e\u094d\u092a\u0926\u093e \u0938\u0930\u094d\u0935\u091a\u0947\u0924\u0938\u093e\u092e\u094d \u0964\n\u0938\u0926\u093e \u0938\u092e\u094d\u092e\u094b\u0939\u0928\u093e\u092f\u093e\u0938\u094d\u0924\u0941 \u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u093e\u092f \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u096a \u0965",
        iastText: "sarv\u0101vayava-saundarya-sampad\u0101 sarva-c\u0113tas\u0101m .\nsad\u0101 samm\u014dhan\u0101y\u0101stu v\u0113\u1e45ka\u1e6d\u0113\u015b\u0101ya ma\u1e45galam .. 4 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0c30\u0c4d\u0c35\u0c3e\u0c35\u0c2f\u0c35\u0c38\u0c4c\u0c28\u0c4d\u0c26\u0c30\u0c4d\u0c2f\u0c38\u0c2e\u0c4d\u0c2a\u0c26\u0c3e \u0c38\u0c30\u0c4d\u0c35\u0c1a\u0c47\u0c24\u0c38\u0c3e\u0c2e\u0c4d \u0964\n\u0c38\u0c26\u0c3e \u0c38\u0c2e\u0c4d\u0c2e\u0c4b\u0c39\u0c28\u0c3e\u0c2f\u0c3e\u0c38\u0c4d\u0c24\u0c41 \u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c3e\u0c2f \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c6a \u0965", "tamil": "\u0bb8\u0bb0\u0bcd\u0bb5\u0bbe\u0bb5\u0baf\u0bb5\u0bb8\u0bcc\u0ba8\u0bcd\u0ba4\u0bb0\u0bcd\u0baf\u0bb8\u0bae\u0bcd\u0baa\u0ba4\u0bbe \u0bb8\u0bb0\u0bcd\u0bb5\u0b9a\u0bc7\u0ba4\u0bb8\u0bbe\u0bae\u0bcd \u0964\n\u0bb8\u0ba4\u0bbe \u0bb8\u0bae\u0bcd\u0bae\u0bcb\u0bb9\u0ba8\u0bbe\u0baf\u0bbe\u0bb8\u0bcd\u0ba4\u0bc1 \u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0bbe\u0baf \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0bea \u0965", "kannada": "\u0cb8\u0cb0\u0ccd\u0cb5\u0cbe\u0cb5\u0caf\u0cb5\u0cb8\u0ccc\u0ca8\u0ccd\u0ca6\u0cb0\u0ccd\u0caf\u0cb8\u0cae\u0ccd\u0caa\u0ca6\u0cbe \u0cb8\u0cb0\u0ccd\u0cb5\u0c9a\u0cc7\u0ca4\u0cb8\u0cbe\u0cae\u0ccd \u0964\n\u0cb8\u0ca6\u0cbe \u0cb8\u0cae\u0ccd\u0cae\u0ccb\u0cb9\u0ca8\u0cbe\u0caf\u0cbe\u0cb8\u0ccd\u0ca4\u0cc1 \u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0cbe\u0caf \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0cea \u0965", "malayalam": "\u0d38\u0d30\u0d4d\u0d35\u0d3e\u0d35\u0d2f\u0d35\u0d38\u0d4c\u0d28\u0d4d\u0d26\u0d30\u0d4d\u0d2f\u0d38\u0d2e\u0d4d\u0d2a\u0d26\u0d3e \u0d38\u0d30\u0d4d\u0d35\u0d1a\u0d47\u0d24\u0d38\u0d3e\u0d2e\u0d4d \u0964\n\u0d38\u0d26\u0d3e \u0d38\u0d2e\u0d4d\u0d2e\u0d4b\u0d39\u0d28\u0d3e\u0d2f\u0d3e\u0d38\u0d4d\u0d24\u0d41 \u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d3e\u0d2f \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d6a \u0965", "iast": "sarv\u0101vayavasaundaryasampad\u0101 sarvacetas\u0101m |\nsad\u0101 sammohan\u0101y\u0101stu ve\u1e45ka\u1e6de\u015b\u0101ya ma\u1e45galam || 4 ||"},
        draftTranslation: "May auspiciousness be unto Lord Venkateswara, who perpetually enchants the hearts of all living beings through the consummate beauty of every single divine limb of His transcendent form!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 61,
        devanagariText: "\u0928\u093f\u0924\u094d\u092f\u094d\u092f\u093e\u092f \u0928\u093f\u0930\u0935\u0926\u094d\u092f\u093e\u092f \u0938\u0924\u094d\u092f\u093e\u0928\u0928\u094d\u0926\u091a\u093f\u0926\u093e\u0924\u094d\u092e\u0928\u0947 \u0964\n\u0938\u0930\u094d\u0935\u093e\u0928\u094d\u0924\u0930\u093e\u0924\u094d\u092e\u0928\u0947 \u0936\u094d\u0930\u0940\u092e\u0926\u094d\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u093e\u092f \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u096b \u0965",
        iastText: "nity\u0101ya niravady\u0101ya saty\u0101nanda-cid\u0101tman\u0113 .\nsarv\u0101ntar\u0101tman\u0113 \u015br\u012bmad-v\u0113\u1e45ka\u1e6d\u0113\u015b\u0101ya ma\u1e45galam .. 5 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c28\u0c3f\u0c24\u0c4d\u0c2f\u0c4d\u0c2f\u0c3e\u0c2f \u0c28\u0c3f\u0c30\u0c35\u0c26\u0c4d\u0c2f\u0c3e\u0c2f \u0c38\u0c24\u0c4d\u0c2f\u0c3e\u0c28\u0c28\u0c4d\u0c26\u0c1a\u0c3f\u0c26\u0c3e\u0c24\u0c4d\u0c2e\u0c28\u0c47 \u0964\n\u0c38\u0c30\u0c4d\u0c35\u0c3e\u0c28\u0c4d\u0c24\u0c30\u0c3e\u0c24\u0c4d\u0c2e\u0c28\u0c47 \u0c36\u0c4d\u0c30\u0c40\u0c2e\u0c26\u0c4d\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c3e\u0c2f \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c6b \u0965", "tamil": "\u0ba8\u0bbf\u0ba4\u0bcd\u0baf\u0bcd\u0baf\u0bbe\u0baf \u0ba8\u0bbf\u0bb0\u0bb5\u0ba4\u0bcd\u0baf\u0bbe\u0baf \u0bb8\u0ba4\u0bcd\u0baf\u0bbe\u0ba8\u0ba8\u0bcd\u0ba4\u0b9a\u0bbf\u0ba4\u0bbe\u0ba4\u0bcd\u0bae\u0ba8\u0bc7 \u0964\n\u0bb8\u0bb0\u0bcd\u0bb5\u0bbe\u0ba8\u0bcd\u0ba4\u0bb0\u0bbe\u0ba4\u0bcd\u0bae\u0ba8\u0bc7 \u0bb6\u0bcd\u0bb0\u0bc0\u0bae\u0ba4\u0bcd\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0bbe\u0baf \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0beb \u0965", "kannada": "\u0ca8\u0cbf\u0ca4\u0ccd\u0caf\u0ccd\u0caf\u0cbe\u0caf \u0ca8\u0cbf\u0cb0\u0cb5\u0ca6\u0ccd\u0caf\u0cbe\u0caf \u0cb8\u0ca4\u0ccd\u0caf\u0cbe\u0ca8\u0ca8\u0ccd\u0ca6\u0c9a\u0cbf\u0ca6\u0cbe\u0ca4\u0ccd\u0cae\u0ca8\u0cc7 \u0964\n\u0cb8\u0cb0\u0ccd\u0cb5\u0cbe\u0ca8\u0ccd\u0ca4\u0cb0\u0cbe\u0ca4\u0ccd\u0cae\u0ca8\u0cc7 \u0cb6\u0ccd\u0cb0\u0cc0\u0cae\u0ca6\u0ccd\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0cbe\u0caf \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0ceb \u0965", "malayalam": "\u0d28\u0d3f\u0d24\u0d4d\u0d2f\u0d4d\u0d2f\u0d3e\u0d2f \u0d28\u0d3f\u0d30\u0d35\u0d26\u0d4d\u0d2f\u0d3e\u0d2f \u0d38\u0d24\u0d4d\u0d2f\u0d3e\u0d28\u0d28\u0d4d\u0d26\u0d1a\u0d3f\u0d26\u0d3e\u0d24\u0d4d\u0d2e\u0d28\u0d47 \u0964\n\u0d38\u0d30\u0d4d\u0d35\u0d3e\u0d28\u0d4d\u0d24\u0d30\u0d3e\u0d24\u0d4d\u0d2e\u0d28\u0d47 \u0d36\u0d4d\u0d30\u0d40\u0d2e\u0d26\u0d4d\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d3e\u0d2f \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d6b \u0965", "iast": "nityy\u0101ya niravady\u0101ya saty\u0101nandacid\u0101tmane |\nsarv\u0101ntar\u0101tmane \u015br\u012bmadve\u1e45ka\u1e6de\u015b\u0101ya ma\u1e45galam || 5 ||"},
        draftTranslation: "Auspiciousness unto glorious Lord Venkateswara, who is eternal (Nitya), flawless (Niravadya), the embodiment of truth, bliss, and pure consciousness (Sat-Chit-Ananda), and the indwelling soul of all existence (Antaryamin)!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 62,
        devanagariText: "\u0938\u094d\u0935\u0924\u0903 \u0938\u0930\u094d\u0935\u0935\u093f\u0926\u0947 \u0938\u0930\u094d\u0935\u0936\u0915\u094d\u0924\u092f\u0947 \u0938\u0930\u094d\u0935\u0936\u0947\u0937\u093f\u0923\u0947 \u0964\n\u0938\u0941\u0932\u092d\u093e\u092f \u0938\u0941\u0936\u0940\u0932\u093e\u092f \u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u093e\u092f \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u096c \u0965",
        iastText: "svata\u1e25 sarvavid\u0113 sarva-\u015baktay\u0113 sarva-\u015b\u0113\u1e63i\u1e47\u0113 .\nsulabh\u0101ya su\u015b\u012bl\u0101ya v\u0113\u1e45ka\u1e6d\u0113\u015b\u0101ya ma\u1e45galam .. 6 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0c4d\u0c35\u0c24\u0c03 \u0c38\u0c30\u0c4d\u0c35\u0c35\u0c3f\u0c26\u0c47 \u0c38\u0c30\u0c4d\u0c35\u0c36\u0c15\u0c4d\u0c24\u0c2f\u0c47 \u0c38\u0c30\u0c4d\u0c35\u0c36\u0c47\u0c37\u0c3f\u0c23\u0c47 \u0964\n\u0c38\u0c41\u0c32\u0c2d\u0c3e\u0c2f \u0c38\u0c41\u0c36\u0c40\u0c32\u0c3e\u0c2f \u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c3e\u0c2f \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c6c \u0965", "tamil": "\u0bb8\u0bcd\u0bb5\u0ba4\u0b83 \u0bb8\u0bb0\u0bcd\u0bb5\u0bb5\u0bbf\u0ba4\u0bc7 \u0bb8\u0bb0\u0bcd\u0bb5\u0bb6\u0b95\u0bcd\u0ba4\u0baf\u0bc7 \u0bb8\u0bb0\u0bcd\u0bb5\u0bb6\u0bc7\u0bb7\u0bbf\u0ba3\u0bc7 \u0964\n\u0bb8\u0bc1\u0bb2\u0baa\u0bbe\u0baf \u0bb8\u0bc1\u0bb6\u0bc0\u0bb2\u0bbe\u0baf \u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0bbe\u0baf \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0bec \u0965", "kannada": "\u0cb8\u0ccd\u0cb5\u0ca4\u0c83 \u0cb8\u0cb0\u0ccd\u0cb5\u0cb5\u0cbf\u0ca6\u0cc7 \u0cb8\u0cb0\u0ccd\u0cb5\u0cb6\u0c95\u0ccd\u0ca4\u0caf\u0cc7 \u0cb8\u0cb0\u0ccd\u0cb5\u0cb6\u0cc7\u0cb7\u0cbf\u0ca3\u0cc7 \u0964\n\u0cb8\u0cc1\u0cb2\u0cad\u0cbe\u0caf \u0cb8\u0cc1\u0cb6\u0cc0\u0cb2\u0cbe\u0caf \u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0cbe\u0caf \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0cec \u0965", "malayalam": "\u0d38\u0d4d\u0d35\u0d24\u0d03 \u0d38\u0d30\u0d4d\u0d35\u0d35\u0d3f\u0d26\u0d47 \u0d38\u0d30\u0d4d\u0d35\u0d36\u0d15\u0d4d\u0d24\u0d2f\u0d47 \u0d38\u0d30\u0d4d\u0d35\u0d36\u0d47\u0d37\u0d3f\u0d23\u0d47 \u0964\n\u0d38\u0d41\u0d32\u0d2d\u0d3e\u0d2f \u0d38\u0d41\u0d36\u0d40\u0d32\u0d3e\u0d2f \u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d3e\u0d2f \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d6c \u0965", "iast": "svata\u1e25 sarvavide sarva\u015baktaye sarva\u015be\u1e63i\u1e47e |\nsulabh\u0101ya su\u015b\u012bl\u0101ya ve\u1e45ka\u1e6de\u015b\u0101ya ma\u1e45galam || 6 ||"},
        draftTranslation: "Auspiciousness unto Lord Venkateswara, who by His very nature is omniscient, omnipotent, the sovereign master of all (Sarva-seshi), yet supremely accessible (Sulabha) and graciously courteous (Sushila) to humble devotees!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 63,
        devanagariText: "\u092a\u0930\u0938\u094d\u092e\u0948 \u092c\u094d\u0930\u0939\u094d\u092e\u0923\u0947 \u092a\u0942\u0930\u094d\u0923\u0915\u093e\u092e\u093e\u092f \u092a\u0930\u092e\u093e\u0924\u094d\u092e\u0928\u0947 \u0964\n\u092a\u094d\u0930\u092f\u0941\u091e\u094d\u091c\u0947 \u092a\u0930\u0924\u0924\u094d\u0924\u094d\u0935\u093e\u092f \u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u093e\u092f \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u096d \u0965",
        iastText: "parasmai brahma\u1e47\u0113 p\u016br\u1e47a-k\u0101m\u0101ya param\u0101tman\u0113 .\nprayu\u00f1j\u0113 paratattv\u0101ya v\u0113\u1e45ka\u1e6d\u0113\u015b\u0101ya ma\u1e45galam .. 7 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2a\u0c30\u0c38\u0c4d\u0c2e\u0c48 \u0c2c\u0c4d\u0c30\u0c39\u0c4d\u0c2e\u0c23\u0c47 \u0c2a\u0c42\u0c30\u0c4d\u0c23\u0c15\u0c3e\u0c2e\u0c3e\u0c2f \u0c2a\u0c30\u0c2e\u0c3e\u0c24\u0c4d\u0c2e\u0c28\u0c47 \u0964\n\u0c2a\u0c4d\u0c30\u0c2f\u0c41\u0c1e\u0c4d\u0c1c\u0c47 \u0c2a\u0c30\u0c24\u0c24\u0c4d\u0c24\u0c4d\u0c35\u0c3e\u0c2f \u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c3e\u0c2f \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c6d \u0965", "tamil": "\u0baa\u0bb0\u0bb8\u0bcd\u0bae\u0bc8 \u0baa\u0bcd\u0bb0\u0bb9\u0bcd\u0bae\u0ba3\u0bc7 \u0baa\u0bc2\u0bb0\u0bcd\u0ba3\u0b95\u0bbe\u0bae\u0bbe\u0baf \u0baa\u0bb0\u0bae\u0bbe\u0ba4\u0bcd\u0bae\u0ba8\u0bc7 \u0964\n\u0baa\u0bcd\u0bb0\u0baf\u0bc1\u0b9e\u0bcd\u0b9c\u0bc7 \u0baa\u0bb0\u0ba4\u0ba4\u0bcd\u0ba4\u0bcd\u0bb5\u0bbe\u0baf \u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0bbe\u0baf \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0bed \u0965", "kannada": "\u0caa\u0cb0\u0cb8\u0ccd\u0cae\u0cc8 \u0cac\u0ccd\u0cb0\u0cb9\u0ccd\u0cae\u0ca3\u0cc7 \u0caa\u0cc2\u0cb0\u0ccd\u0ca3\u0c95\u0cbe\u0cae\u0cbe\u0caf \u0caa\u0cb0\u0cae\u0cbe\u0ca4\u0ccd\u0cae\u0ca8\u0cc7 \u0964\n\u0caa\u0ccd\u0cb0\u0caf\u0cc1\u0c9e\u0ccd\u0c9c\u0cc7 \u0caa\u0cb0\u0ca4\u0ca4\u0ccd\u0ca4\u0ccd\u0cb5\u0cbe\u0caf \u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0cbe\u0caf \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0ced \u0965", "malayalam": "\u0d2a\u0d30\u0d38\u0d4d\u0d2e\u0d48 \u0d2c\u0d4d\u0d30\u0d39\u0d4d\u0d2e\u0d23\u0d47 \u0d2a\u0d42\u0d30\u0d4d\u0d23\u0d15\u0d3e\u0d2e\u0d3e\u0d2f \u0d2a\u0d30\u0d2e\u0d3e\u0d24\u0d4d\u0d2e\u0d28\u0d47 \u0964\n\u0d2a\u0d4d\u0d30\u0d2f\u0d41\u0d1e\u0d4d\u0d1c\u0d47 \u0d2a\u0d30\u0d24\u0d24\u0d4d\u0d24\u0d4d\u0d35\u0d3e\u0d2f \u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d3e\u0d2f \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d6d \u0965", "iast": "parasmai brahma\u1e47e p\u016br\u1e47ak\u0101m\u0101ya param\u0101tmane |\nprayu\u00f1je paratattv\u0101ya ve\u1e45ka\u1e6de\u015b\u0101ya ma\u1e45galam || 7 ||"},
        draftTranslation: "I dedicate auspicious benedictions unto Lord Venkateswara, who is the Supreme Brahman, whose desires are ever completely fulfilled (Purna-kama), the Supreme Self, and the ultimate Reality of realities (Paratattva)!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 64,
        devanagariText: "\u0906\u0915\u093e\u0932\u0924\u0924\u094d\u0924\u094d\u0935\u092e\u0936\u094d\u0930\u093e\u0928\u094d\u0924\u092e\u093e\u0924\u094d\u092e\u0928\u093e\u092e\u0928\u0941\u092a\u0936\u094d\u092f\u0924\u093e\u092e\u094d \u0964\n\u0905\u0924\u0943\u092a\u094d\u0924\u094d\u092f\u092e\u0943\u0924\u0930\u0942\u092a\u093e\u092f \u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u093e\u092f \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u096e \u0965",
        iastText: "\u0101k\u0101la-tattvam-a\u015br\u0101ntam-\u0101tman\u0101m-anupa\u015byat\u0101m .\nat\u1e5bpty-am\u1e5bta-r\u016bp\u0101ya v\u0113\u1e45ka\u1e6d\u0113\u015b\u0101ya ma\u1e45galam .. 8 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c06\u0c15\u0c3e\u0c32\u0c24\u0c24\u0c4d\u0c24\u0c4d\u0c35\u0c2e\u0c36\u0c4d\u0c30\u0c3e\u0c28\u0c4d\u0c24\u0c2e\u0c3e\u0c24\u0c4d\u0c2e\u0c28\u0c3e\u0c2e\u0c28\u0c41\u0c2a\u0c36\u0c4d\u0c2f\u0c24\u0c3e\u0c2e\u0c4d \u0964\n\u0c05\u0c24\u0c43\u0c2a\u0c4d\u0c24\u0c4d\u0c2f\u0c2e\u0c43\u0c24\u0c30\u0c42\u0c2a\u0c3e\u0c2f \u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c3e\u0c2f \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c6e \u0965", "tamil": "\u0b86\u0b95\u0bbe\u0bb2\u0ba4\u0ba4\u0bcd\u0ba4\u0bcd\u0bb5\u0bae\u0bb6\u0bcd\u0bb0\u0bbe\u0ba8\u0bcd\u0ba4\u0bae\u0bbe\u0ba4\u0bcd\u0bae\u0ba8\u0bbe\u0bae\u0ba8\u0bc1\u0baa\u0bb6\u0bcd\u0baf\u0ba4\u0bbe\u0bae\u0bcd \u0964\n\u0b85\u0ba4\u0bcd\u0bb0\u0bc1'\u0baa\u0bcd\u0ba4\u0bcd\u0baf\u0bae\u0bcd\u0bb0\u0bc1'\u0ba4\u0bb0\u0bc2\u0baa\u0bbe\u0baf \u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0bbe\u0baf \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0bee \u0965", "kannada": "\u0c86\u0c95\u0cbe\u0cb2\u0ca4\u0ca4\u0ccd\u0ca4\u0ccd\u0cb5\u0cae\u0cb6\u0ccd\u0cb0\u0cbe\u0ca8\u0ccd\u0ca4\u0cae\u0cbe\u0ca4\u0ccd\u0cae\u0ca8\u0cbe\u0cae\u0ca8\u0cc1\u0caa\u0cb6\u0ccd\u0caf\u0ca4\u0cbe\u0cae\u0ccd \u0964\n\u0c85\u0ca4\u0cc3\u0caa\u0ccd\u0ca4\u0ccd\u0caf\u0cae\u0cc3\u0ca4\u0cb0\u0cc2\u0caa\u0cbe\u0caf \u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0cbe\u0caf \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0cee \u0965", "malayalam": "\u0d06\u0d15\u0d3e\u0d32\u0d24\u0d24\u0d4d\u0d24\u0d4d\u0d35\u0d2e\u0d36\u0d4d\u0d30\u0d3e\u0d28\u0d4d\u0d24\u0d2e\u0d3e\u0d24\u0d4d\u0d2e\u0d28\u0d3e\u0d2e\u0d28\u0d41\u0d2a\u0d36\u0d4d\u0d2f\u0d24\u0d3e\u0d2e\u0d4d \u0964\n\u0d05\u0d24\u0d43\u0d2a\u0d4d\u0d24\u0d4d\u0d2f\u0d2e\u0d43\u0d24\u0d30\u0d42\u0d2a\u0d3e\u0d2f \u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d3e\u0d2f \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d6e \u0965", "iast": "\u0101k\u0101latattvama\u015br\u0101ntam\u0101tman\u0101manupa\u015byat\u0101m |\nat\u1e5bptyam\u1e5btar\u016bp\u0101ya ve\u1e45ka\u1e6de\u015b\u0101ya ma\u1e45galam || 8 ||"},
        draftTranslation: "Auspiciousness unto Lord Venkateswara, who appears as never-satiating divine nectar (Atripti-amrita) to those contemplative souls who gaze upon Him ceaselessly for all eternity!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 65,
        devanagariText: "\u092a\u094d\u0930\u093e\u092f\u0903 \u0938\u094d\u0935\u091a\u0930\u0923\u094c \u092a\u0941\u0902\u0938\u093e\u0902 \u0936\u0930\u0923\u094d\u092f\u0924\u094d\u0935\u0947\u0928 \u092a\u093e\u0923\u093f\u0928\u093e \u0964\n\u0915\u0943\u092a\u092f\u093e\u093d\u093d\u0926\u093f\u0936\u0924\u0947 \u0936\u094d\u0930\u0940\u092e\u0926\u094d\u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u093e\u092f \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u096f \u0965",
        iastText: "pr\u0101ya\u1e25 sva-cara\u1e47au pu\u1e41s\u0101\u1e41 \u015bara\u1e47yatv\u0113na p\u0101\u1e47in\u0101 .\nk\u1e5bpay\u0101''di\u015bat\u0113 \u015br\u012bmad-v\u0113\u1e45ka\u1e6d\u0113\u015b\u0101ya ma\u1e45galam .. 9 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2a\u0c4d\u0c30\u0c3e\u0c2f\u0c03 \u0c38\u0c4d\u0c35\u0c1a\u0c30\u0c23\u0c4c \u0c2a\u0c41\u0c02\u0c38\u0c3e\u0c02 \u0c36\u0c30\u0c23\u0c4d\u0c2f\u0c24\u0c4d\u0c35\u0c47\u0c28 \u0c2a\u0c3e\u0c23\u0c3f\u0c28\u0c3e \u0964\n\u0c15\u0c43\u0c2a\u0c2f\u0c3e\u0c3d\u0c3d\u0c26\u0c3f\u0c36\u0c24\u0c47 \u0c36\u0c4d\u0c30\u0c40\u0c2e\u0c26\u0c4d\u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c3e\u0c2f \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c6f \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0bbe\u0baf\u0b83 \u0bb8\u0bcd\u0bb5\u0b9a\u0bb0\u0ba3\u0bcc \u0baa\u0bc1\u0bae\u0bcd\u0bb8\u0bbe\u0bae\u0bcd \u0bb6\u0bb0\u0ba3\u0bcd\u0baf\u0ba4\u0bcd\u0bb5\u0bc7\u0ba8 \u0baa\u0bbe\u0ba3\u0bbf\u0ba8\u0bbe \u0964\n\u0b95\u0bcd\u0bb0\u0bc1'\u0baa\u0baf\u0bbe\u093d\u093d\u0ba4\u0bbf\u0bb6\u0ba4\u0bc7 \u0bb6\u0bcd\u0bb0\u0bc0\u0bae\u0ba4\u0bcd\u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0bbe\u0baf \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0bef \u0965", "kannada": "\u0caa\u0ccd\u0cb0\u0cbe\u0caf\u0c83 \u0cb8\u0ccd\u0cb5\u0c9a\u0cb0\u0ca3\u0ccc \u0caa\u0cc1\u0c82\u0cb8\u0cbe\u0c82 \u0cb6\u0cb0\u0ca3\u0ccd\u0caf\u0ca4\u0ccd\u0cb5\u0cc7\u0ca8 \u0caa\u0cbe\u0ca3\u0cbf\u0ca8\u0cbe \u0964\n\u0c95\u0cc3\u0caa\u0caf\u0cbe\u0cbd\u0cbd\u0ca6\u0cbf\u0cb6\u0ca4\u0cc7 \u0cb6\u0ccd\u0cb0\u0cc0\u0cae\u0ca6\u0ccd\u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0cbe\u0caf \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0cef \u0965", "malayalam": "\u0d2a\u0d4d\u0d30\u0d3e\u0d2f\u0d03 \u0d38\u0d4d\u0d35\u0d1a\u0d30\u0d23\u0d4c \u0d2a\u0d41\u0d02\u0d38\u0d3e\u0d02 \u0d36\u0d30\u0d23\u0d4d\u0d2f\u0d24\u0d4d\u0d35\u0d47\u0d28 \u0d2a\u0d3e\u0d23\u0d3f\u0d28\u0d3e \u0964\n\u0d15\u0d43\u0d2a\u0d2f\u0d3e\u0d3d\u0d3d\u0d26\u0d3f\u0d36\u0d24\u0d47 \u0d36\u0d4d\u0d30\u0d40\u0d2e\u0d26\u0d4d\u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d3e\u0d2f \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d6f \u0965", "iast": "pr\u0101ya\u1e25 svacara\u1e47au pu\u1e43s\u0101\u1e43 \u015bara\u1e47yatvena p\u0101\u1e47in\u0101 |\nk\u1e5bpay\u0101''di\u015bate \u015br\u012bmadve\u1e45ka\u1e6de\u015b\u0101ya ma\u1e45galam || 9 ||"},
        draftTranslation: "Auspiciousness unto glorious Lord Venkateswara, who out of boundless compassion points downward with His own hand toward His feet, showing mankind that here alone is the supreme refuge!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 66,
        devanagariText: "\u0926\u092f\u093e\u093d\u092e\u0943\u0924\u0924\u0930\u0919\u094d\u0917\u093f\u0923\u094d\u092f\u093e\u0938\u094d\u0924\u0930\u0919\u094d\u0917\u0948\u0930\u093f\u0935 \u0936\u0940\u0924\u0932behind/\u0936\u0940\u0924\u0932\u0948\u0903 \u0964\n\u0905\u092a\u093e\u0919\u094d\u0917\u0948\u0903 \u0938\u093f\u091e\u094d\u091a\u0924\u0947 \u0935\u093f\u0936\u094d\u0935\u0902 \u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u093e\u092f \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u0967\u0966 \u0965",
        iastText: "day\u0101'm\u1e5bta-tara\u1e45gi\u1e47y\u0101s-tara\u1e45gair-iva \u015b\u012btalai\u1e25 .\nap\u0101\u1e45gai\u1e25 si\u00f1cat\u0113 vi\u015bva\u1e41 v\u0113\u1e45ka\u1e6d\u0113\u015b\u0101ya ma\u1e45galam .. 10 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c26\u0c2f\u0c3e\u0c3d\u0c2e\u0c43\u0c24\u0c24\u0c30\u0c19\u0c4d\u0c17\u0c3f\u0c23\u0c4d\u0c2f\u0c3e\u0c38\u0c4d\u0c24\u0c30\u0c19\u0c4d\u0c17\u0c48\u0c30\u0c3f\u0c35 \u0c36\u0c40\u0c24\u0c32behind/\u0c36\u0c40\u0c24\u0c32\u0c48\u0c03 \u0964\n\u0c05\u0c2a\u0c3e\u0c19\u0c4d\u0c17\u0c48\u0c03 \u0c38\u0c3f\u0c1e\u0c4d\u0c1a\u0c24\u0c47 \u0c35\u0c3f\u0c36\u0c4d\u0c35\u0c02 \u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c3e\u0c2f \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c67\u0c66 \u0965", "tamil": "\u0ba4\u0baf\u0bbe\u093d\u0bae\u0bcd\u0bb0\u0bc1'\u0ba4\u0ba4\u0bb0\u0b99\u0bcd\u0b95\u0bbf\u0ba3\u0bcd\u0baf\u0bbe\u0bb8\u0bcd\u0ba4\u0bb0\u0b99\u0bcd\u0b95\u0bc8\u0bb0\u0bbf\u0bb5 \u0bb6\u0bc0\u0ba4\u0bb2behind/\u0bb6\u0bc0\u0ba4\u0bb2\u0bc8\u0b83 \u0964\n\u0b85\u0baa\u0bbe\u0b99\u0bcd\u0b95\u0bc8\u0b83 \u0bb8\u0bbf\u0b9e\u0bcd\u0b9a\u0ba4\u0bc7 \u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0bae\u0bcd \u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0bbe\u0baf \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0be7\u0be6 \u0965", "kannada": "\u0ca6\u0caf\u0cbe\u0cbd\u0cae\u0cc3\u0ca4\u0ca4\u0cb0\u0c99\u0ccd\u0c97\u0cbf\u0ca3\u0ccd\u0caf\u0cbe\u0cb8\u0ccd\u0ca4\u0cb0\u0c99\u0ccd\u0c97\u0cc8\u0cb0\u0cbf\u0cb5 \u0cb6\u0cc0\u0ca4\u0cb2behind/\u0cb6\u0cc0\u0ca4\u0cb2\u0cc8\u0c83 \u0964\n\u0c85\u0caa\u0cbe\u0c99\u0ccd\u0c97\u0cc8\u0c83 \u0cb8\u0cbf\u0c9e\u0ccd\u0c9a\u0ca4\u0cc7 \u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0c82 \u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0cbe\u0caf \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0ce7\u0ce6 \u0965", "malayalam": "\u0d26\u0d2f\u0d3e\u0d3d\u0d2e\u0d43\u0d24\u0d24\u0d30\u0d19\u0d4d\u0d17\u0d3f\u0d23\u0d4d\u0d2f\u0d3e\u0d38\u0d4d\u0d24\u0d30\u0d19\u0d4d\u0d17\u0d48\u0d30\u0d3f\u0d35 \u0d36\u0d40\u0d24\u0d32behind/\u0d36\u0d40\u0d24\u0d32\u0d48\u0d03 \u0964\n\u0d05\u0d2a\u0d3e\u0d19\u0d4d\u0d17\u0d48\u0d03 \u0d38\u0d3f\u0d1e\u0d4d\u0d1a\u0d24\u0d47 \u0d35\u0d3f\u0d36\u0d4d\u0d35\u0d02 \u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d3e\u0d2f \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d67\u0d66 \u0965", "iast": "day\u0101'm\u1e5btatara\u1e45gi\u1e47y\u0101stara\u1e45gairiva \u015b\u012btalabehind/\u015b\u012btalai\u1e25 |\nap\u0101\u1e45gai\u1e25 si\u00f1cate vi\u015bva\u1e43 ve\u1e45ka\u1e6de\u015b\u0101ya ma\u1e45galam || 10 ||"},
        draftTranslation: "Auspiciousness unto Lord Venkateswara, who drenches the burning universe with cool, soothing sidelong glances that flow like refreshing waves from a celestial river of merciful nectar!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 67,
        devanagariText: "\u0938\u094d\u0930\u0917\u094d\u092d\u0942\u0937\u093e\u092e\u094d\u092c\u0930\u0939\u0947\u0924\u0940\u0928\u093e\u0902 \u0938\u0941\u0937\u092e\u093e\u093d\u093d\u0935\u0939\u092e\u0942\u0930\u094d\u0924\u092f\u0947 \u0964\n\u0938\u0930\u094d\u0935\u093e\u0930\u094d\u0930\u094d\u0924\u093f\u0936\u092e\u0928\u093e\u092f\u093e\u0938\u094d\u0924\u0941 \u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u093e\u092f \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u0967\u0967 \u0965",
        iastText: "srag-bh\u016b\u1e63\u0101mbara-h\u0113t\u012bn\u0101\u1e41 su\u1e63am\u0101''vaha-m\u016brtay\u0113 .\nsarv\u0101rt\u012b-\u015baman\u0101y\u0101stu v\u0113\u1e45ka\u1e6d\u0113\u015b\u0101ya ma\u1e45galam .. 11 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0c4d\u0c30\u0c17\u0c4d\u0c2d\u0c42\u0c37\u0c3e\u0c2e\u0c4d\u0c2c\u0c30\u0c39\u0c47\u0c24\u0c40\u0c28\u0c3e\u0c02 \u0c38\u0c41\u0c37\u0c2e\u0c3e\u0c3d\u0c3d\u0c35\u0c39\u0c2e\u0c42\u0c30\u0c4d\u0c24\u0c2f\u0c47 \u0964\n\u0c38\u0c30\u0c4d\u0c35\u0c3e\u0c30\u0c4d\u0c30\u0c4d\u0c24\u0c3f\u0c36\u0c2e\u0c28\u0c3e\u0c2f\u0c3e\u0c38\u0c4d\u0c24\u0c41 \u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c3e\u0c2f \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c67\u0c67 \u0965", "tamil": "\u0bb8\u0bcd\u0bb0\u0b95\u0bcd\u0baa\u0bc2\u0bb7\u0bbe\u0bae\u0bcd\u0baa\u0bb0\u0bb9\u0bc7\u0ba4\u0bc0\u0ba8\u0bbe\u0bae\u0bcd \u0bb8\u0bc1\u0bb7\u0bae\u0bbe\u093d\u093d\u0bb5\u0bb9\u0bae\u0bc2\u0bb0\u0bcd\u0ba4\u0baf\u0bc7 \u0964\n\u0bb8\u0bb0\u0bcd\u0bb5\u0bbe\u0bb0\u0bcd\u0bb0\u0bcd\u0ba4\u0bbf\u0bb6\u0bae\u0ba8\u0bbe\u0baf\u0bbe\u0bb8\u0bcd\u0ba4\u0bc1 \u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0bbe\u0baf \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0be7\u0be7 \u0965", "kannada": "\u0cb8\u0ccd\u0cb0\u0c97\u0ccd\u0cad\u0cc2\u0cb7\u0cbe\u0cae\u0ccd\u0cac\u0cb0\u0cb9\u0cc7\u0ca4\u0cc0\u0ca8\u0cbe\u0c82 \u0cb8\u0cc1\u0cb7\u0cae\u0cbe\u0cbd\u0cbd\u0cb5\u0cb9\u0cae\u0cc2\u0cb0\u0ccd\u0ca4\u0caf\u0cc7 \u0964\n\u0cb8\u0cb0\u0ccd\u0cb5\u0cbe\u0cb0\u0ccd\u0cb0\u0ccd\u0ca4\u0cbf\u0cb6\u0cae\u0ca8\u0cbe\u0caf\u0cbe\u0cb8\u0ccd\u0ca4\u0cc1 \u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0cbe\u0caf \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0ce7\u0ce7 \u0965", "malayalam": "\u0d38\u0d4d\u0d30\u0d17\u0d4d\u0d2d\u0d42\u0d37\u0d3e\u0d2e\u0d4d\u0d2c\u0d30\u0d39\u0d47\u0d24\u0d40\u0d28\u0d3e\u0d02 \u0d38\u0d41\u0d37\u0d2e\u0d3e\u0d3d\u0d3d\u0d35\u0d39\u0d2e\u0d42\u0d30\u0d4d\u0d24\u0d2f\u0d47 \u0964\n\u0d38\u0d30\u0d4d\u0d35\u0d3e\u0d30\u0d4d\u0d30\u0d4d\u0d24\u0d3f\u0d36\u0d2e\u0d28\u0d3e\u0d2f\u0d3e\u0d38\u0d4d\u0d24\u0d41 \u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d3e\u0d2f \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d67\u0d67 \u0965", "iast": "sragbh\u016b\u1e63\u0101mbarahet\u012bn\u0101\u1e43 su\u1e63am\u0101''vaham\u016brtaye |\nsarv\u0101rrti\u015baman\u0101y\u0101stu ve\u1e45ka\u1e6de\u015b\u0101ya ma\u1e45galam || 11 ||"},
        draftTranslation: "May auspiciousness be unto Lord Venkateswara, whose divine form lends additional splendor to the floral garlands, ornaments, silken garments, and weapons adorning Him, and who quells all afflictions of His devotees!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 68,
        devanagariText: "\u0936\u094d\u0930\u0940\u0935\u0948\u0915\u0941\u0923\u094d\u0920\u0935\u093f\u0930\u0915\u094d\u0924\u093e\u092f \u0938\u094d\u0935\u093e\u092e\u093f\u092a\u0941\u0937\u094d\u0915\u0930\u093f\u0923\u0940\u0924\u091f\u0947 \u0964\n\u0930\u092e\u092f\u093e \u0930\u092e\u092e\u093e\u0923\u093e\u092f \u0935\u0947\u0919\u094d\u0915\u091f\u0947\u0936\u093e\u092f \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u0967\u0968 \u0965",
        iastText: "\u015br\u012b-vaiku\u1e47\u1e6dha-virakt\u0101ya sv\u0101mi-pu\u1e63kari\u1e47\u012b-ta\u1e6d\u0113 .\nramay\u0101 ramam\u0101\u1e47\u0101ya v\u0113\u1e45ka\u1e6d\u0113\u015b\u0101ya ma\u1e45galam .. 2 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c36\u0c4d\u0c30\u0c40\u0c35\u0c48\u0c15\u0c41\u0c23\u0c4d\u0c20\u0c35\u0c3f\u0c30\u0c15\u0c4d\u0c24\u0c3e\u0c2f \u0c38\u0c4d\u0c35\u0c3e\u0c2e\u0c3f\u0c2a\u0c41\u0c37\u0c4d\u0c15\u0c30\u0c3f\u0c23\u0c40\u0c24\u0c1f\u0c47 \u0964\n\u0c30\u0c2e\u0c2f\u0c3e \u0c30\u0c2e\u0c2e\u0c3e\u0c23\u0c3e\u0c2f \u0c35\u0c47\u0c19\u0c4d\u0c15\u0c1f\u0c47\u0c36\u0c3e\u0c2f \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c67\u0c68 \u0965", "tamil": "\u0bb6\u0bcd\u0bb0\u0bc0\u0bb5\u0bc8\u0b95\u0bc1\u0ba3\u0bcd\u0b9f\u0bb5\u0bbf\u0bb0\u0b95\u0bcd\u0ba4\u0bbe\u0baf \u0bb8\u0bcd\u0bb5\u0bbe\u0bae\u0bbf\u0baa\u0bc1\u0bb7\u0bcd\u0b95\u0bb0\u0bbf\u0ba3\u0bc0\u0ba4\u0b9f\u0bc7 \u0964\n\u0bb0\u0bae\u0baf\u0bbe \u0bb0\u0bae\u0bae\u0bbe\u0ba3\u0bbe\u0baf \u0bb5\u0bc7\u0b99\u0bcd\u0b95\u0b9f\u0bc7\u0bb6\u0bbe\u0baf \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0be7\u0be8 \u0965", "kannada": "\u0cb6\u0ccd\u0cb0\u0cc0\u0cb5\u0cc8\u0c95\u0cc1\u0ca3\u0ccd\u0ca0\u0cb5\u0cbf\u0cb0\u0c95\u0ccd\u0ca4\u0cbe\u0caf \u0cb8\u0ccd\u0cb5\u0cbe\u0cae\u0cbf\u0caa\u0cc1\u0cb7\u0ccd\u0c95\u0cb0\u0cbf\u0ca3\u0cc0\u0ca4\u0c9f\u0cc7 \u0964\n\u0cb0\u0cae\u0caf\u0cbe \u0cb0\u0cae\u0cae\u0cbe\u0ca3\u0cbe\u0caf \u0cb5\u0cc7\u0c99\u0ccd\u0c95\u0c9f\u0cc7\u0cb6\u0cbe\u0caf \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0ce7\u0ce8 \u0965", "malayalam": "\u0d36\u0d4d\u0d30\u0d40\u0d35\u0d48\u0d15\u0d41\u0d23\u0d4d\u0d20\u0d35\u0d3f\u0d30\u0d15\u0d4d\u0d24\u0d3e\u0d2f \u0d38\u0d4d\u0d35\u0d3e\u0d2e\u0d3f\u0d2a\u0d41\u0d37\u0d4d\u0d15\u0d30\u0d3f\u0d23\u0d40\u0d24\u0d1f\u0d47 \u0964\n\u0d30\u0d2e\u0d2f\u0d3e \u0d30\u0d2e\u0d2e\u0d3e\u0d23\u0d3e\u0d2f \u0d35\u0d47\u0d19\u0d4d\u0d15\u0d1f\u0d47\u0d36\u0d3e\u0d2f \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d67\u0d68 \u0965", "iast": "\u015br\u012bvaiku\u1e47\u1e6dhavirakt\u0101ya sv\u0101mipu\u1e63kari\u1e47\u012bta\u1e6de |\nramay\u0101 ramam\u0101\u1e47\u0101ya ve\u1e45ka\u1e6de\u015b\u0101ya ma\u1e45galam || 12 ||"},
        draftTranslation: "Auspiciousness unto Lord Venkateswara, who renounced even the supreme glory of Sri Vaikuntha in order to sport delightfully with Goddess Rama (Lakshmi) upon the sacred banks of Swami Pushkarini lake!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 69,
        devanagariText: "\u0936\u094d\u0930\u0940\u092e\u0924\u094d\u0938\u0941\u0928\u094d\u0926\u0930\u091c\u093e\u092e\u093e\u0924\u0943\u092e\u0941\u0928\u093f\u092e\u093e\u0928\u0938\u0935\u093e\u0938\u093f\u0928\u0947 \u0964\n\u0938\u0930\u094d\u0935\u0932\u094b\u0915\u0928\u0935\u093e\u0938\u093e\u092f \u0936\u094d\u0930\u0940\u0928\u093f\u0935\u093e\u0938\u093e\u092f \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u0967\u0969 \u0965",
        iastText: "\u015br\u012bmat-sundara-j\u0101m\u0101t\u1e5b-muni-m\u0101nasa-v\u0101sin\u0113 .\nsarva-l\u014dka-niv\u0101s\u0101ya \u015br\u012bniv\u0101s\u0101ya ma\u1e45galam .. 13 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c36\u0c4d\u0c30\u0c40\u0c2e\u0c24\u0c4d\u0c38\u0c41\u0c28\u0c4d\u0c26\u0c30\u0c1c\u0c3e\u0c2e\u0c3e\u0c24\u0c43\u0c2e\u0c41\u0c28\u0c3f\u0c2e\u0c3e\u0c28\u0c38\u0c35\u0c3e\u0c38\u0c3f\u0c28\u0c47 \u0964\n\u0c38\u0c30\u0c4d\u0c35\u0c32\u0c4b\u0c15\u0c28\u0c35\u0c3e\u0c38\u0c3e\u0c2f \u0c36\u0c4d\u0c30\u0c40\u0c28\u0c3f\u0c35\u0c3e\u0c38\u0c3e\u0c2f \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c67\u0c69 \u0965", "tamil": "\u0bb6\u0bcd\u0bb0\u0bc0\u0bae\u0ba4\u0bcd\u0bb8\u0bc1\u0ba8\u0bcd\u0ba4\u0bb0\u0b9c\u0bbe\u0bae\u0bbe\u0ba4\u0bcd\u0bb0\u0bc1'\u0bae\u0bc1\u0ba8\u0bbf\u0bae\u0bbe\u0ba8\u0bb8\u0bb5\u0bbe\u0bb8\u0bbf\u0ba8\u0bc7 \u0964\n\u0bb8\u0bb0\u0bcd\u0bb5\u0bb2\u0bcb\u0b95\u0ba8\u0bb5\u0bbe\u0bb8\u0bbe\u0baf \u0bb6\u0bcd\u0bb0\u0bc0\u0ba8\u0bbf\u0bb5\u0bbe\u0bb8\u0bbe\u0baf \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0be7\u0be9 \u0965", "kannada": "\u0cb6\u0ccd\u0cb0\u0cc0\u0cae\u0ca4\u0ccd\u0cb8\u0cc1\u0ca8\u0ccd\u0ca6\u0cb0\u0c9c\u0cbe\u0cae\u0cbe\u0ca4\u0cc3\u0cae\u0cc1\u0ca8\u0cbf\u0cae\u0cbe\u0ca8\u0cb8\u0cb5\u0cbe\u0cb8\u0cbf\u0ca8\u0cc7 \u0964\n\u0cb8\u0cb0\u0ccd\u0cb5\u0cb2\u0ccb\u0c95\u0ca8\u0cb5\u0cbe\u0cb8\u0cbe\u0caf \u0cb6\u0ccd\u0cb0\u0cc0\u0ca8\u0cbf\u0cb5\u0cbe\u0cb8\u0cbe\u0caf \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0ce7\u0ce9 \u0965", "malayalam": "\u0d36\u0d4d\u0d30\u0d40\u0d2e\u0d24\u0d4d\u0d38\u0d41\u0d28\u0d4d\u0d26\u0d30\u0d1c\u0d3e\u0d2e\u0d3e\u0d24\u0d43\u0d2e\u0d41\u0d28\u0d3f\u0d2e\u0d3e\u0d28\u0d38\u0d35\u0d3e\u0d38\u0d3f\u0d28\u0d47 \u0964\n\u0d38\u0d30\u0d4d\u0d35\u0d32\u0d4b\u0d15\u0d28\u0d35\u0d3e\u0d38\u0d3e\u0d2f \u0d36\u0d4d\u0d30\u0d40\u0d28\u0d3f\u0d35\u0d3e\u0d38\u0d3e\u0d2f \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d67\u0d69 \u0965", "iast": "\u015br\u012bmatsundaraj\u0101m\u0101t\u1e5bmunim\u0101nasav\u0101sine |\nsarvalokanav\u0101s\u0101ya \u015br\u012bniv\u0101s\u0101ya ma\u1e45galam || 13 ||"},
        draftTranslation: "Auspiciousness unto Lord Srinivasa, who ever dwells lovingly within the holy heart of Sri Manavala Mamunigal (Sundara Jamatr Muni), and who is Himself the ultimate dwelling abode for all the worlds!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 70,
        devanagariText: "\u092e\u0919\u094d\u0917\u0932\u093e\u0936\u093e\u0938\u0928\u092a\u0930\u0948\u0930\u094d\u092e\u0926\u093e\u091a\u093e\u0930\u094d\u092f\u092a\u0941\u0930\u094b\u0917\u092e\u0948\u0903 \u0964\n\u0938\u0930\u094d\u0935\u0948\u0936\u094d\u091a \u092a\u0942\u0930\u094d\u0935\u0948\u0930\u093e\u091a\u093e\u0930\u094d\u092f\u0948\u0903 \u0938\u0924\u094d\u0915\u0943\u0924\u093e\u092f\u093e\u0938\u094d\u0924\u0941 \u092e\u0919\u094d\u0917\u0932\u092e\u094d \u0965 \u0967\u096a \u0965",
        iastText: "ma\u1e45gal\u0101\u015b\u0101sana-parair-mad\u0101c\u0101rya-pur\u014dgamai\u1e25 .\nsarvai\u015b-ca p\u016brvair-\u0101c\u0101ryai\u1e25 satk\u1e5bt\u0101y\u0101stu ma\u1e45galam .. 14 ..",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c3e\u0c36\u0c3e\u0c38\u0c28\u0c2a\u0c30\u0c48\u0c30\u0c4d\u0c2e\u0c26\u0c3e\u0c1a\u0c3e\u0c30\u0c4d\u0c2f\u0c2a\u0c41\u0c30\u0c4b\u0c17\u0c2e\u0c48\u0c03 \u0964\n\u0c38\u0c30\u0c4d\u0c35\u0c48\u0c36\u0c4d\u0c1a \u0c2a\u0c42\u0c30\u0c4d\u0c35\u0c48\u0c30\u0c3e\u0c1a\u0c3e\u0c30\u0c4d\u0c2f\u0c48\u0c03 \u0c38\u0c24\u0c4d\u0c15\u0c43\u0c24\u0c3e\u0c2f\u0c3e\u0c38\u0c4d\u0c24\u0c41 \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c2e\u0c4d \u0965 \u0c67\u0c6a \u0965", "tamil": "\u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bbe\u0bb6\u0bbe\u0bb8\u0ba8\u0baa\u0bb0\u0bc8\u0bb0\u0bcd\u0bae\u0ba4\u0bbe\u0b9a\u0bbe\u0bb0\u0bcd\u0baf\u0baa\u0bc1\u0bb0\u0bcb\u0b95\u0bae\u0bc8\u0b83 \u0964\n\u0bb8\u0bb0\u0bcd\u0bb5\u0bc8\u0bb6\u0bcd\u0b9a \u0baa\u0bc2\u0bb0\u0bcd\u0bb5\u0bc8\u0bb0\u0bbe\u0b9a\u0bbe\u0bb0\u0bcd\u0baf\u0bc8\u0b83 \u0bb8\u0ba4\u0bcd\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0bbe\u0baf\u0bbe\u0bb8\u0bcd\u0ba4\u0bc1 \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0bae\u0bcd \u0965 \u0be7\u0bea \u0965", "kannada": "\u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cbe\u0cb6\u0cbe\u0cb8\u0ca8\u0caa\u0cb0\u0cc8\u0cb0\u0ccd\u0cae\u0ca6\u0cbe\u0c9a\u0cbe\u0cb0\u0ccd\u0caf\u0caa\u0cc1\u0cb0\u0ccb\u0c97\u0cae\u0cc8\u0c83 \u0964\n\u0cb8\u0cb0\u0ccd\u0cb5\u0cc8\u0cb6\u0ccd\u0c9a \u0caa\u0cc2\u0cb0\u0ccd\u0cb5\u0cc8\u0cb0\u0cbe\u0c9a\u0cbe\u0cb0\u0ccd\u0caf\u0cc8\u0c83 \u0cb8\u0ca4\u0ccd\u0c95\u0cc3\u0ca4\u0cbe\u0caf\u0cbe\u0cb8\u0ccd\u0ca4\u0cc1 \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0cae\u0ccd \u0965 \u0ce7\u0cea \u0965", "malayalam": "\u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d3e\u0d36\u0d3e\u0d38\u0d28\u0d2a\u0d30\u0d48\u0d30\u0d4d\u0d2e\u0d26\u0d3e\u0d1a\u0d3e\u0d30\u0d4d\u0d2f\u0d2a\u0d41\u0d30\u0d4b\u0d17\u0d2e\u0d48\u0d03 \u0964\n\u0d38\u0d30\u0d4d\u0d35\u0d48\u0d36\u0d4d\u0d1a \u0d2a\u0d42\u0d30\u0d4d\u0d35\u0d48\u0d30\u0d3e\u0d1a\u0d3e\u0d30\u0d4d\u0d2f\u0d48\u0d03 \u0d38\u0d24\u0d4d\u0d15\u0d43\u0d24\u0d3e\u0d2f\u0d3e\u0d38\u0d4d\u0d24\u0d41 \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d2e\u0d4d \u0965 \u0d67\u0d6a \u0965", "iast": "ma\u1e45gal\u0101\u015b\u0101sanaparairmad\u0101c\u0101ryapurogamai\u1e25 |\nsarvai\u015bca p\u016brvair\u0101c\u0101ryai\u1e25 satk\u1e5bt\u0101y\u0101stu ma\u1e45galam || 14 ||"},
        draftTranslation: "May eternal auspiciousness be unto the Lord, who is gloriously worshipped and blessed through hymns of benediction by all the revered ancient Acharyas headed by my own venerable Preceptor (Manavala Mamunigal)!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
    ],
  ),
  Scripture(
    id: 16,
    contentId: "VEDA-TXT-00014",
    canonicalTitle: "Purusha Suktam",
    devanagariTitle: "\u092a\u0941\u0930\u0941\u0937\u0938\u0942\u0915\u094d\u0924\u092e\u094d",
    category: "Suktam",
    deity: "Purusha / Supreme Being",
    composer: "Rishi Narayana",
    rishi: "Traditional Vedic Sage",
    chandas: "Anushtubh (1-15) / Trishtubh (16)",
    devata: "Purusha / Supreme Being",
    sourceScripture: "Rigveda Samhita, Mandala 10, Sukta 90",
    traditionalUsage: "Cosmic creation liturgy, Mahabhisheka ritual chant, Vedic contemplation",
    verseCount: 16,
    verses: [
      Verse(
        verseNumber: 1,
        devanagariText: "\u0938\u0939\u0938\u094d\u0930\u0951\u0936\u0940\u0930\u094d\u0937\u093e \u092a\u0941\u0930\u0941\u0951\u0937\u0903 \u0938\u0939\u0938\u094d\u0930\u093e\u0952\u0915\u094d\u0937\u0903 \u0938\u0952\u0939\u0938\u094d\u0930\u0951\u092a\u093e\u0924\u094d \u0964\n\u0938 \u092d\u0942\u092e\u093f\u0902\u0951 \u0935\u093f\u0952\u0936\u094d\u0935\u0924\u094b\u0951 \u0935\u0943\u0952\u0924\u094d\u0935\u093e\u0924\u094d\u092f\u0951\u0924\u093f\u0937\u094d\u0920\u0926\u094d\u0926\u0936\u093e\u0919\u094d\u0917\u0941\u0952\u0932\u092e\u094d \u0965 \u0967 \u0965",
        iastText: "sahasra\u0951\u015b\u012br\u1e63\u0101 puru\u0951\u1e63a\u1e25 sahasr\u0101\u0952k\u1e63a\u1e25 sa\u0952hasra\u0951p\u0101t \u0964\nsa bh\u016bmi\u1e41\u0951 vi\u0952\u015bvat\u014d\u0951 v\u1e5b\u0952tv\u0101tya\u0951ti\u1e63\u1e6dhadda\u015b\u0101\u1e45gu\u0952lam \u0965 1 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0c39\u0c38\u0c4d\u0c30\u0951\u0c36\u0c40\u0c30\u0c4d\u0c37\u0c3e \u0c2a\u0c41\u0c30\u0c41\u0951\u0c37\u0c03 \u0c38\u0c39\u0c38\u0c4d\u0c30\u0c3e\u0952\u0c15\u0c4d\u0c37\u0c03 \u0c38\u0952\u0c39\u0c38\u0c4d\u0c30\u0951\u0c2a\u0c3e\u0c24\u0c4d \u0964\n\u0c38 \u0c2d\u0c42\u0c2e\u0c3f\u0c02\u0951 \u0c35\u0c3f\u0952\u0c36\u0c4d\u0c35\u0c24\u0c4b\u0951 \u0c35\u0c43\u0952\u0c24\u0c4d\u0c35\u0c3e\u0c24\u0c4d\u0c2f\u0951\u0c24\u0c3f\u0c37\u0c4d\u0c20\u0c26\u0c4d\u0c26\u0c36\u0c3e\u0c19\u0c4d\u0c17\u0c41\u0952\u0c32\u0c2e\u0c4d \u0965 \u0c67 \u0965", "tamil": "\u0bb8\u0bb9\u0bb8\u0bcd\u0bb0\u0951\u0bb6\u0bc0\u0bb0\u0bcd\u0bb7\u0bbe \u0baa\u0bc1\u0bb0\u0bc1\u0951\u0bb7\u0b83 \u0bb8\u0bb9\u0bb8\u0bcd\u0bb0\u0bbe\u0952\u0b95\u0bcd\u0bb7\u0b83 \u0bb8\u0952\u0bb9\u0bb8\u0bcd\u0bb0\u0951\u0baa\u0bbe\u0ba4\u0bcd \u0964\n\u0bb8 \u0baa\u0bc2\u0bae\u0bbf\u0bae\u0bcd\u0951 \u0bb5\u0bbf\u0952\u0bb6\u0bcd\u0bb5\u0ba4\u0bcb\u0951 \u0bb5\u0bcd\u0bb0\u0bc1'\u0952\u0ba4\u0bcd\u0bb5\u0bbe\u0ba4\u0bcd\u0baf\u0951\u0ba4\u0bbf\u0bb7\u0bcd\u0b9f\u0ba4\u0bcd\u0ba4\u0bb6\u0bbe\u0b99\u0bcd\u0b95\u0bc1\u0952\u0bb2\u0bae\u0bcd \u0965 \u0be7 \u0965", "kannada": "\u0cb8\u0cb9\u0cb8\u0ccd\u0cb0\u0951\u0cb6\u0cc0\u0cb0\u0ccd\u0cb7\u0cbe \u0caa\u0cc1\u0cb0\u0cc1\u0951\u0cb7\u0c83 \u0cb8\u0cb9\u0cb8\u0ccd\u0cb0\u0cbe\u0952\u0c95\u0ccd\u0cb7\u0c83 \u0cb8\u0952\u0cb9\u0cb8\u0ccd\u0cb0\u0951\u0caa\u0cbe\u0ca4\u0ccd \u0964\n\u0cb8 \u0cad\u0cc2\u0cae\u0cbf\u0c82\u0951 \u0cb5\u0cbf\u0952\u0cb6\u0ccd\u0cb5\u0ca4\u0ccb\u0951 \u0cb5\u0cc3\u0952\u0ca4\u0ccd\u0cb5\u0cbe\u0ca4\u0ccd\u0caf\u0951\u0ca4\u0cbf\u0cb7\u0ccd\u0ca0\u0ca6\u0ccd\u0ca6\u0cb6\u0cbe\u0c99\u0ccd\u0c97\u0cc1\u0952\u0cb2\u0cae\u0ccd \u0965 \u0ce7 \u0965", "malayalam": "\u0d38\u0d39\u0d38\u0d4d\u0d30\u0951\u0d36\u0d40\u0d30\u0d4d\u0d37\u0d3e \u0d2a\u0d41\u0d30\u0d41\u0951\u0d37\u0d03 \u0d38\u0d39\u0d38\u0d4d\u0d30\u0d3e\u0952\u0d15\u0d4d\u0d37\u0d03 \u0d38\u0952\u0d39\u0d38\u0d4d\u0d30\u0951\u0d2a\u0d3e\u0d24\u0d4d \u0964\n\u0d38 \u0d2d\u0d42\u0d2e\u0d3f\u0d02\u0951 \u0d35\u0d3f\u0952\u0d36\u0d4d\u0d35\u0d24\u0d4b\u0951 \u0d35\u0d43\u0952\u0d24\u0d4d\u0d35\u0d3e\u0d24\u0d4d\u0d2f\u0951\u0d24\u0d3f\u0d37\u0d4d\u0d20\u0d26\u0d4d\u0d26\u0d36\u0d3e\u0d19\u0d4d\u0d17\u0d41\u0952\u0d32\u0d2e\u0d4d \u0965 \u0d67 \u0965", "iast": "sahasra\u032d\u015b\u012br\u1e63\u0101 pur\u1e77\u1e63a\u1e25 sahasr\u0101\u0331k\u1e63a\u1e25 sa\u0331hasra\u032dp\u0101t |\nsa bh\u016bmi\u032d\u1e43 vi\u0331\u015bvato\u032d v\u1e5b\u0331tv\u0101tya\u032dti\u1e63\u1e6dhadda\u015b\u0101\u1e45gu\u0331lam || 1 ||"},
        draftTranslation: "The Supreme Purusha has a thousand heads, a thousand eyes, and a thousand feet. Pervading the entire cosmos on all sides, He extends beyond it by ten fingers' length.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 2,
        devanagariText: "\u092a\u0941\u0930\u0941\u0951\u0937 \u090f\u0952\u0935\u0947\u0926\u0902 \u0938\u0930\u094d\u0935\u0902\u0952 \u092f\u0926\u094d\u092d\u0942\u0952\u0924\u0902 \u092f\u091a\u094d\u091a\u0952 \u092d\u0935\u094d\u092f\u0951\u092e\u094d \u0964\n\u0909\u0952\u0924\u093e\u092e\u0943\u0951\u0924\u0952\u0924\u094d\u0935\u0938\u094d\u092f\u0947\u0936\u093e\u0951\u0928\u094b\u0952 \u092f\u0926\u0928\u094d\u0928\u0947\u0951\u0928\u093e\u0924\u093f\u0952\u0930\u094b\u0939\u0951\u0924\u093f \u0965 \u0968 \u0965",
        iastText: "puru\u0951\u1e63a \u0113\u0952v\u0113da\u1e41 sarva\u1e41\u0952 yadbh\u016b\u0952ta\u1e41 yacca\u0952 bhavya\u0951m \u0964\nu\u0952t\u0101m\u1e5b\u0951ta\u0952tvasy\u0113\u015b\u0101\u0951n\u014d\u0952 yadann\u0113\u0951n\u0101ti\u0952r\u014dha\u0951ti \u0965 2 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2a\u0c41\u0c30\u0c41\u0951\u0c37 \u0c0f\u0952\u0c35\u0c47\u0c26\u0c02 \u0c38\u0c30\u0c4d\u0c35\u0c02\u0952 \u0c2f\u0c26\u0c4d\u0c2d\u0c42\u0952\u0c24\u0c02 \u0c2f\u0c1a\u0c4d\u0c1a\u0952 \u0c2d\u0c35\u0c4d\u0c2f\u0951\u0c2e\u0c4d \u0964\n\u0c09\u0952\u0c24\u0c3e\u0c2e\u0c43\u0951\u0c24\u0952\u0c24\u0c4d\u0c35\u0c38\u0c4d\u0c2f\u0c47\u0c36\u0c3e\u0951\u0c28\u0c4b\u0952 \u0c2f\u0c26\u0c28\u0c4d\u0c28\u0c47\u0951\u0c28\u0c3e\u0c24\u0c3f\u0952\u0c30\u0c4b\u0c39\u0951\u0c24\u0c3f \u0965 \u0c68 \u0965", "tamil": "\u0baa\u0bc1\u0bb0\u0bc1\u0951\u0bb7 \u0b8f\u0952\u0bb5\u0bc7\u0ba4\u0bae\u0bcd \u0bb8\u0bb0\u0bcd\u0bb5\u0bae\u0bcd\u0952 \u0baf\u0ba4\u0bcd\u0baa\u0bc2\u0952\u0ba4\u0bae\u0bcd \u0baf\u0b9a\u0bcd\u0b9a\u0952 \u0baa\u0bb5\u0bcd\u0baf\u0951\u0bae\u0bcd \u0964\n\u0b89\u0952\u0ba4\u0bbe\u0bae\u0bcd\u0bb0\u0bc1'\u0951\u0ba4\u0952\u0ba4\u0bcd\u0bb5\u0bb8\u0bcd\u0baf\u0bc7\u0bb6\u0bbe\u0951\u0ba8\u0bcb\u0952 \u0baf\u0ba4\u0ba8\u0bcd\u0ba8\u0bc7\u0951\u0ba8\u0bbe\u0ba4\u0bbf\u0952\u0bb0\u0bcb\u0bb9\u0951\u0ba4\u0bbf \u0965 \u0be8 \u0965", "kannada": "\u0caa\u0cc1\u0cb0\u0cc1\u0951\u0cb7 \u0c8f\u0952\u0cb5\u0cc7\u0ca6\u0c82 \u0cb8\u0cb0\u0ccd\u0cb5\u0c82\u0952 \u0caf\u0ca6\u0ccd\u0cad\u0cc2\u0952\u0ca4\u0c82 \u0caf\u0c9a\u0ccd\u0c9a\u0952 \u0cad\u0cb5\u0ccd\u0caf\u0951\u0cae\u0ccd \u0964\n\u0c89\u0952\u0ca4\u0cbe\u0cae\u0cc3\u0951\u0ca4\u0952\u0ca4\u0ccd\u0cb5\u0cb8\u0ccd\u0caf\u0cc7\u0cb6\u0cbe\u0951\u0ca8\u0ccb\u0952 \u0caf\u0ca6\u0ca8\u0ccd\u0ca8\u0cc7\u0951\u0ca8\u0cbe\u0ca4\u0cbf\u0952\u0cb0\u0ccb\u0cb9\u0951\u0ca4\u0cbf \u0965 \u0ce8 \u0965", "malayalam": "\u0d2a\u0d41\u0d30\u0d41\u0951\u0d37 \u0d0f\u0952\u0d35\u0d47\u0d26\u0d02 \u0d38\u0d30\u0d4d\u0d35\u0d02\u0952 \u0d2f\u0d26\u0d4d\u0d2d\u0d42\u0952\u0d24\u0d02 \u0d2f\u0d1a\u0d4d\u0d1a\u0952 \u0d2d\u0d35\u0d4d\u0d2f\u0951\u0d2e\u0d4d \u0964\n\u0d09\u0952\u0d24\u0d3e\u0d2e\u0d43\u0951\u0d24\u0952\u0d24\u0d4d\u0d35\u0d38\u0d4d\u0d2f\u0d47\u0d36\u0d3e\u0951\u0d28\u0d4b\u0952 \u0d2f\u0d26\u0d28\u0d4d\u0d28\u0d47\u0951\u0d28\u0d3e\u0d24\u0d3f\u0952\u0d30\u0d4b\u0d39\u0951\u0d24\u0d3f \u0965 \u0d68 \u0965", "iast": "pur\u1e77\u1e63a e\u0331veda\u1e43 sarva\u0331\u1e43 yadbh\u016b\u0331ta\u1e43 yacca\u0331 bhavya\u032dm |\nu\u0331t\u0101m\u1e5b\u032dta\u0331tvasye\u015b\u0101\u032dno\u0331 yadann\u1e19n\u0101ti\u0331roha\u032dti || 2 ||"},
        draftTranslation: "The Purusha alone is all this universe \u2014 all that has been and all that is yet to come. He is also the immortal Lord of eternal life, who grows beyond mortal existence through sustenance.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 3,
        devanagariText: "\u090f\u0952\u0924\u093e\u0935\u093e\u0951\u0928\u0938\u094d\u092f \u092e\u0939\u093f\u0952\u092e\u093e\u0924\u094b\u0952 \u091c\u094d\u092f\u093e\u092f\u093e\u0902\u0951\u0936\u094d\u091a\u0952 \u092a\u0942\u0930\u0941\u0951\u0937\u0903 \u0964\n\u092a\u093e\u0926\u094b\u0951\u093d\u0938\u094d\u092f\u0952 \u0935\u093f\u0936\u094d\u0935\u093e\u0951 \u092d\u0942\u0952\u0924\u093e\u0928\u093f\u0951 \u0924\u094d\u0930\u093f\u0952\u092a\u093e\u0926\u0951\u0938\u094d\u092f\u093e\u0952\u092e\u0943\u0924\u0902\u0951 \u0926\u093f\u0952\u0935\u093f \u0965 \u0969 \u0965",
        iastText: "\u0113\u0952t\u0101v\u0101\u0951nasya mahi\u0952m\u0101t\u014d\u0952 jy\u0101y\u0101\u1e41\u0951\u015bca\u0952 p\u016bru\u0951\u1e63a\u1e25 \u0964\np\u0101d\u014d\u0951'sya\u0952 vi\u015bv\u0101\u0951 bh\u016b\u0952t\u0101ni\u0951 tri\u0952p\u0101da\u0951sy\u0101\u0952m\u1e5bta\u1e41\u0951 di\u0952vi \u0965 3 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c0f\u0952\u0c24\u0c3e\u0c35\u0c3e\u0951\u0c28\u0c38\u0c4d\u0c2f \u0c2e\u0c39\u0c3f\u0952\u0c2e\u0c3e\u0c24\u0c4b\u0952 \u0c1c\u0c4d\u0c2f\u0c3e\u0c2f\u0c3e\u0c02\u0951\u0c36\u0c4d\u0c1a\u0952 \u0c2a\u0c42\u0c30\u0c41\u0951\u0c37\u0c03 \u0964\n\u0c2a\u0c3e\u0c26\u0c4b\u0951\u0c3d\u0c38\u0c4d\u0c2f\u0952 \u0c35\u0c3f\u0c36\u0c4d\u0c35\u0c3e\u0951 \u0c2d\u0c42\u0952\u0c24\u0c3e\u0c28\u0c3f\u0951 \u0c24\u0c4d\u0c30\u0c3f\u0952\u0c2a\u0c3e\u0c26\u0951\u0c38\u0c4d\u0c2f\u0c3e\u0952\u0c2e\u0c43\u0c24\u0c02\u0951 \u0c26\u0c3f\u0952\u0c35\u0c3f \u0965 \u0c69 \u0965", "tamil": "\u0b8f\u0952\u0ba4\u0bbe\u0bb5\u0bbe\u0951\u0ba8\u0bb8\u0bcd\u0baf \u0bae\u0bb9\u0bbf\u0952\u0bae\u0bbe\u0ba4\u0bcb\u0952 \u0b9c\u0bcd\u0baf\u0bbe\u0baf\u0bbe\u0bae\u0bcd\u0951\u0bb6\u0bcd\u0b9a\u0952 \u0baa\u0bc2\u0bb0\u0bc1\u0951\u0bb7\u0b83 \u0964\n\u0baa\u0bbe\u0ba4\u0bcb\u0951\u093d\u0bb8\u0bcd\u0baf\u0952 \u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0bbe\u0951 \u0baa\u0bc2\u0952\u0ba4\u0bbe\u0ba8\u0bbf\u0951 \u0ba4\u0bcd\u0bb0\u0bbf\u0952\u0baa\u0bbe\u0ba4\u0951\u0bb8\u0bcd\u0baf\u0bbe\u0952\u0bae\u0bcd\u0bb0\u0bc1'\u0ba4\u0bae\u0bcd\u0951 \u0ba4\u0bbf\u0952\u0bb5\u0bbf \u0965 \u0be9 \u0965", "kannada": "\u0c8f\u0952\u0ca4\u0cbe\u0cb5\u0cbe\u0951\u0ca8\u0cb8\u0ccd\u0caf \u0cae\u0cb9\u0cbf\u0952\u0cae\u0cbe\u0ca4\u0ccb\u0952 \u0c9c\u0ccd\u0caf\u0cbe\u0caf\u0cbe\u0c82\u0951\u0cb6\u0ccd\u0c9a\u0952 \u0caa\u0cc2\u0cb0\u0cc1\u0951\u0cb7\u0c83 \u0964\n\u0caa\u0cbe\u0ca6\u0ccb\u0951\u0cbd\u0cb8\u0ccd\u0caf\u0952 \u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0cbe\u0951 \u0cad\u0cc2\u0952\u0ca4\u0cbe\u0ca8\u0cbf\u0951 \u0ca4\u0ccd\u0cb0\u0cbf\u0952\u0caa\u0cbe\u0ca6\u0951\u0cb8\u0ccd\u0caf\u0cbe\u0952\u0cae\u0cc3\u0ca4\u0c82\u0951 \u0ca6\u0cbf\u0952\u0cb5\u0cbf \u0965 \u0ce9 \u0965", "malayalam": "\u0d0f\u0952\u0d24\u0d3e\u0d35\u0d3e\u0951\u0d28\u0d38\u0d4d\u0d2f \u0d2e\u0d39\u0d3f\u0952\u0d2e\u0d3e\u0d24\u0d4b\u0952 \u0d1c\u0d4d\u0d2f\u0d3e\u0d2f\u0d3e\u0d02\u0951\u0d36\u0d4d\u0d1a\u0952 \u0d2a\u0d42\u0d30\u0d41\u0951\u0d37\u0d03 \u0964\n\u0d2a\u0d3e\u0d26\u0d4b\u0951\u0d3d\u0d38\u0d4d\u0d2f\u0952 \u0d35\u0d3f\u0d36\u0d4d\u0d35\u0d3e\u0951 \u0d2d\u0d42\u0952\u0d24\u0d3e\u0d28\u0d3f\u0951 \u0d24\u0d4d\u0d30\u0d3f\u0952\u0d2a\u0d3e\u0d26\u0951\u0d38\u0d4d\u0d2f\u0d3e\u0952\u0d2e\u0d43\u0d24\u0d02\u0951 \u0d26\u0d3f\u0952\u0d35\u0d3f \u0965 \u0d69 \u0965", "iast": "e\u0331t\u0101v\u0101\u032dnasya mahi\u0331m\u0101to\u0331 jy\u0101y\u0101\u032d\u1e43\u015bca\u0331 p\u016br\u1e77\u1e63a\u1e25 |\np\u0101do\u032d'sya\u0331 vi\u015bv\u0101\u032d bh\u016b\u0331t\u0101ni\u032d tri\u0331p\u0101da\u032dsy\u0101\u0331m\u1e5bta\u032d\u1e43 di\u0331vi || 3 ||"},
        draftTranslation: "Such is His magnificent greatness, yet greater still is the supreme Purusha. All beings and creations of the universe constitute but one quarter of Him; His immortal three-quarters abide in the transcendent realms.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 4,
        devanagariText: "\u0924\u094d\u0930\u093f\u0952\u092a\u093e\u0926\u0942\u0952\u0930\u094d\u0927\u094d\u0935 \u0909\u0926\u0948\u0952\u0924\u094d\u092a\u0941\u0930\u0941\u0951\u0937\u0903 \u092a\u093e\u0926\u094b\u0951\u093d\u0938\u094d\u092f\u0947\u0952\u0939\u093e\u092d\u0951\u0935\u0952\u0924\u094d\u092a\u0941\u0928\u0903\u0951 \u0964\n\u0924\u0924\u094b\u0952 \u0935\u093f\u0937\u094d\u0935\u0952\u0919\u094d \u0935\u094d\u092f\u0951\u0915\u094d\u0930\u093e\u092e\u0924\u094d\u0938\u093e\u0936\u0928\u093e\u0928\u0936\u0952\u0928\u0947 \u0905\u0952\u092d\u093f \u0965 \u096a \u0965",
        iastText: "tri\u0952p\u0101d\u016b\u0952rdhva udai\u0952tpuru\u0951\u1e63a\u1e25 p\u0101d\u014d\u0951'sy\u0113\u0952h\u0101bha\u0951va\u0952tpuna\u1e25\u0951 \u0964\ntat\u014d\u0952 vi\u1e63va\u0952\u1e45 vya\u0951kr\u0101mats\u0101\u015ban\u0101na\u015ba\u0952n\u0113 a\u0952bhi \u0965 4 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c24\u0c4d\u0c30\u0c3f\u0952\u0c2a\u0c3e\u0c26\u0c42\u0952\u0c30\u0c4d\u0c27\u0c4d\u0c35 \u0c09\u0c26\u0c48\u0952\u0c24\u0c4d\u0c2a\u0c41\u0c30\u0c41\u0951\u0c37\u0c03 \u0c2a\u0c3e\u0c26\u0c4b\u0951\u0c3d\u0c38\u0c4d\u0c2f\u0c47\u0952\u0c39\u0c3e\u0c2d\u0951\u0c35\u0952\u0c24\u0c4d\u0c2a\u0c41\u0c28\u0c03\u0951 \u0964\n\u0c24\u0c24\u0c4b\u0952 \u0c35\u0c3f\u0c37\u0c4d\u0c35\u0952\u0c19\u0c4d \u0c35\u0c4d\u0c2f\u0951\u0c15\u0c4d\u0c30\u0c3e\u0c2e\u0c24\u0c4d\u0c38\u0c3e\u0c36\u0c28\u0c3e\u0c28\u0c36\u0952\u0c28\u0c47 \u0c05\u0952\u0c2d\u0c3f \u0965 \u0c6a \u0965", "tamil": "\u0ba4\u0bcd\u0bb0\u0bbf\u0952\u0baa\u0bbe\u0ba4\u0bc2\u0952\u0bb0\u0bcd\u0ba4\u0bcd\u0bb5 \u0b89\u0ba4\u0bc8\u0952\u0ba4\u0bcd\u0baa\u0bc1\u0bb0\u0bc1\u0951\u0bb7\u0b83 \u0baa\u0bbe\u0ba4\u0bcb\u0951\u093d\u0bb8\u0bcd\u0baf\u0bc7\u0952\u0bb9\u0bbe\u0baa\u0951\u0bb5\u0952\u0ba4\u0bcd\u0baa\u0bc1\u0ba8\u0b83\u0951 \u0964\n\u0ba4\u0ba4\u0bcb\u0952 \u0bb5\u0bbf\u0bb7\u0bcd\u0bb5\u0952\u0b99\u0bcd \u0bb5\u0bcd\u0baf\u0951\u0b95\u0bcd\u0bb0\u0bbe\u0bae\u0ba4\u0bcd\u0bb8\u0bbe\u0bb6\u0ba8\u0bbe\u0ba8\u0bb6\u0952\u0ba8\u0bc7 \u0b85\u0952\u0baa\u0bbf \u0965 \u0bea \u0965", "kannada": "\u0ca4\u0ccd\u0cb0\u0cbf\u0952\u0caa\u0cbe\u0ca6\u0cc2\u0952\u0cb0\u0ccd\u0ca7\u0ccd\u0cb5 \u0c89\u0ca6\u0cc8\u0952\u0ca4\u0ccd\u0caa\u0cc1\u0cb0\u0cc1\u0951\u0cb7\u0c83 \u0caa\u0cbe\u0ca6\u0ccb\u0951\u0cbd\u0cb8\u0ccd\u0caf\u0cc7\u0952\u0cb9\u0cbe\u0cad\u0951\u0cb5\u0952\u0ca4\u0ccd\u0caa\u0cc1\u0ca8\u0c83\u0951 \u0964\n\u0ca4\u0ca4\u0ccb\u0952 \u0cb5\u0cbf\u0cb7\u0ccd\u0cb5\u0952\u0c99\u0ccd \u0cb5\u0ccd\u0caf\u0951\u0c95\u0ccd\u0cb0\u0cbe\u0cae\u0ca4\u0ccd\u0cb8\u0cbe\u0cb6\u0ca8\u0cbe\u0ca8\u0cb6\u0952\u0ca8\u0cc7 \u0c85\u0952\u0cad\u0cbf \u0965 \u0cea \u0965", "malayalam": "\u0d24\u0d4d\u0d30\u0d3f\u0952\u0d2a\u0d3e\u0d26\u0d42\u0952\u0d30\u0d4d\u0d27\u0d4d\u0d35 \u0d09\u0d26\u0d48\u0952\u0d24\u0d4d\u0d2a\u0d41\u0d30\u0d41\u0951\u0d37\u0d03 \u0d2a\u0d3e\u0d26\u0d4b\u0951\u0d3d\u0d38\u0d4d\u0d2f\u0d47\u0952\u0d39\u0d3e\u0d2d\u0951\u0d35\u0952\u0d24\u0d4d\u0d2a\u0d41\u0d28\u0d03\u0951 \u0964\n\u0d24\u0d24\u0d4b\u0952 \u0d35\u0d3f\u0d37\u0d4d\u0d35\u0952\u0d19\u0d4d \u0d35\u0d4d\u0d2f\u0951\u0d15\u0d4d\u0d30\u0d3e\u0d2e\u0d24\u0d4d\u0d38\u0d3e\u0d36\u0d28\u0d3e\u0d28\u0d36\u0952\u0d28\u0d47 \u0d05\u0952\u0d2d\u0d3f \u0965 \u0d6a \u0965", "iast": "tri\u0331p\u0101d\u016b\u0331rdhva udai\u0331tpur\u1e77\u1e63a\u1e25 p\u0101do\u032d'sye\u0331h\u0101bha\u032dva\u0331tpuna\u032d\u1e25 |\ntato\u0331 vi\u1e63va\u0331\u1e45 vya\u032dkr\u0101mats\u0101\u015ban\u0101na\u015ba\u0331ne a\u0331bhi || 4 ||"},
        draftTranslation: "With His three-quarters the Purusha ascended into supreme transcendence, while one quarter manifested here again. From that quarter He expanded in all directions over everything that consumes food and that does not.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 5,
        devanagariText: "\u0924\u0938\u094d\u092e\u093e\u0951\u0926\u094d\u0935\u093f\u0952\u0930\u093e\u0933\u0951\u091c\u093e\u092f\u0924 \u0935\u093f\u0952\u0930\u093e\u091c\u094b\u0952 \u0905\u0927\u093f\u0952 \u092a\u0942\u0930\u0941\u0951\u0937\u0903 \u0964\n\u0938 \u091c\u093e\u0952\u0924\u094b \u0905\u0924\u094d\u092f\u0951\u0930\u093f\u091a\u094d\u092f\u0924 \u092a\u0952\u0936\u094d\u091a\u093e\u0926\u094d\u092d\u0942\u092e\u093f\u0952\u092e\u0925\u094b\u0951 \u092a\u0941\u0952\u0930\u0903 \u0965 \u096b \u0965",
        iastText: "tasm\u0101\u0951dvi\u0952r\u0101\u1e37a\u0951j\u0101yata vi\u0952r\u0101j\u014d\u0952 adhi\u0952 p\u016bru\u0951\u1e63a\u1e25 \u0964\nsa j\u0101\u0952t\u014d atya\u0951ricyata pa\u0952\u015bc\u0101dbh\u016bmi\u0952math\u014d\u0951 pu\u0952ra\u1e25 \u0965 5 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c24\u0c38\u0c4d\u0c2e\u0c3e\u0951\u0c26\u0c4d\u0c35\u0c3f\u0952\u0c30\u0c3e\u0c33\u0951\u0c1c\u0c3e\u0c2f\u0c24 \u0c35\u0c3f\u0952\u0c30\u0c3e\u0c1c\u0c4b\u0952 \u0c05\u0c27\u0c3f\u0952 \u0c2a\u0c42\u0c30\u0c41\u0951\u0c37\u0c03 \u0964\n\u0c38 \u0c1c\u0c3e\u0952\u0c24\u0c4b \u0c05\u0c24\u0c4d\u0c2f\u0951\u0c30\u0c3f\u0c1a\u0c4d\u0c2f\u0c24 \u0c2a\u0952\u0c36\u0c4d\u0c1a\u0c3e\u0c26\u0c4d\u0c2d\u0c42\u0c2e\u0c3f\u0952\u0c2e\u0c25\u0c4b\u0951 \u0c2a\u0c41\u0952\u0c30\u0c03 \u0965 \u0c6b \u0965", "tamil": "\u0ba4\u0bb8\u0bcd\u0bae\u0bbe\u0951\u0ba4\u0bcd\u0bb5\u0bbf\u0952\u0bb0\u0bbe\u0bb3\u0951\u0b9c\u0bbe\u0baf\u0ba4 \u0bb5\u0bbf\u0952\u0bb0\u0bbe\u0b9c\u0bcb\u0952 \u0b85\u0ba4\u0bbf\u0952 \u0baa\u0bc2\u0bb0\u0bc1\u0951\u0bb7\u0b83 \u0964\n\u0bb8 \u0b9c\u0bbe\u0952\u0ba4\u0bcb \u0b85\u0ba4\u0bcd\u0baf\u0951\u0bb0\u0bbf\u0b9a\u0bcd\u0baf\u0ba4 \u0baa\u0952\u0bb6\u0bcd\u0b9a\u0bbe\u0ba4\u0bcd\u0baa\u0bc2\u0bae\u0bbf\u0952\u0bae\u0ba4\u0bcb\u0951 \u0baa\u0bc1\u0952\u0bb0\u0b83 \u0965 \u0beb \u0965", "kannada": "\u0ca4\u0cb8\u0ccd\u0cae\u0cbe\u0951\u0ca6\u0ccd\u0cb5\u0cbf\u0952\u0cb0\u0cbe\u0cb3\u0951\u0c9c\u0cbe\u0caf\u0ca4 \u0cb5\u0cbf\u0952\u0cb0\u0cbe\u0c9c\u0ccb\u0952 \u0c85\u0ca7\u0cbf\u0952 \u0caa\u0cc2\u0cb0\u0cc1\u0951\u0cb7\u0c83 \u0964\n\u0cb8 \u0c9c\u0cbe\u0952\u0ca4\u0ccb \u0c85\u0ca4\u0ccd\u0caf\u0951\u0cb0\u0cbf\u0c9a\u0ccd\u0caf\u0ca4 \u0caa\u0952\u0cb6\u0ccd\u0c9a\u0cbe\u0ca6\u0ccd\u0cad\u0cc2\u0cae\u0cbf\u0952\u0cae\u0ca5\u0ccb\u0951 \u0caa\u0cc1\u0952\u0cb0\u0c83 \u0965 \u0ceb \u0965", "malayalam": "\u0d24\u0d38\u0d4d\u0d2e\u0d3e\u0951\u0d26\u0d4d\u0d35\u0d3f\u0952\u0d30\u0d3e\u0d33\u0951\u0d1c\u0d3e\u0d2f\u0d24 \u0d35\u0d3f\u0952\u0d30\u0d3e\u0d1c\u0d4b\u0952 \u0d05\u0d27\u0d3f\u0952 \u0d2a\u0d42\u0d30\u0d41\u0951\u0d37\u0d03 \u0964\n\u0d38 \u0d1c\u0d3e\u0952\u0d24\u0d4b \u0d05\u0d24\u0d4d\u0d2f\u0951\u0d30\u0d3f\u0d1a\u0d4d\u0d2f\u0d24 \u0d2a\u0952\u0d36\u0d4d\u0d1a\u0d3e\u0d26\u0d4d\u0d2d\u0d42\u0d2e\u0d3f\u0952\u0d2e\u0d25\u0d4b\u0951 \u0d2a\u0d41\u0952\u0d30\u0d03 \u0965 \u0d6b \u0965", "iast": "tasm\u0101\u032ddvi\u0331r\u0101\u1e3ba\u032dj\u0101yata vi\u0331r\u0101jo\u0331 adhi\u0331 p\u016br\u1e77\u1e63a\u1e25 |\nsa j\u0101\u0331to atya\u032dricyata pa\u0331\u015bc\u0101dbh\u016bmi\u0331matho\u032d pu\u0331ra\u1e25 || 5 ||"},
        draftTranslation: "From Him was born the cosmic body Viraj, and from Viraj was manifested the cosmic Purusha. Being born, He spread far beyond the earth, both behind and in front.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 6,
        devanagariText: "\u092f\u0924\u094d\u092a\u0941\u0930\u0941\u0951\u0937\u0947\u0923 \u0939\u0952\u0935\u093f\u0937\u093e\u0951 \u0926\u0947\u0952\u0935\u093e \u092f\u0952\u091c\u094d\u091e\u092e\u0924\u0951\u0928\u094d\u0935\u0924 \u0964\n\u0935\u0952\u0938\u0952\u0928\u094d\u0924\u094b \u0905\u0951\u0938\u094d\u092f\u093e\u0938\u0940\u0952\u0926\u093e\u091c\u094d\u092f\u0902\u0951 \u0917\u094d\u0930\u0940\u0952\u0937\u094d\u092e \u0907\u0952\u0927\u094d\u092e\u0903 \u0936\u0952\u0930\u0926\u094d\u0927\u0952\u0935\u093f\u0903 \u0965 \u096c \u0965",
        iastText: "yatpuru\u0951\u1e63\u0113\u1e47a ha\u0952vi\u1e63\u0101\u0951 d\u0113\u0952v\u0101 ya\u0952j\u00f1amata\u0951nvata \u0964\nva\u0952sa\u0952nt\u014d a\u0951sy\u0101s\u012b\u0952d\u0101jya\u1e41\u0951 gr\u012b\u0952\u1e63ma i\u0952dhma\u1e25 \u015ba\u0952raddha\u0952vi\u1e25 \u0965 6 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2f\u0c24\u0c4d\u0c2a\u0c41\u0c30\u0c41\u0951\u0c37\u0c47\u0c23 \u0c39\u0952\u0c35\u0c3f\u0c37\u0c3e\u0951 \u0c26\u0c47\u0952\u0c35\u0c3e \u0c2f\u0952\u0c1c\u0c4d\u0c1e\u0c2e\u0c24\u0951\u0c28\u0c4d\u0c35\u0c24 \u0964\n\u0c35\u0952\u0c38\u0952\u0c28\u0c4d\u0c24\u0c4b \u0c05\u0951\u0c38\u0c4d\u0c2f\u0c3e\u0c38\u0c40\u0952\u0c26\u0c3e\u0c1c\u0c4d\u0c2f\u0c02\u0951 \u0c17\u0c4d\u0c30\u0c40\u0952\u0c37\u0c4d\u0c2e \u0c07\u0952\u0c27\u0c4d\u0c2e\u0c03 \u0c36\u0952\u0c30\u0c26\u0c4d\u0c27\u0952\u0c35\u0c3f\u0c03 \u0965 \u0c6c \u0965", "tamil": "\u0baf\u0ba4\u0bcd\u0baa\u0bc1\u0bb0\u0bc1\u0951\u0bb7\u0bc7\u0ba3 \u0bb9\u0952\u0bb5\u0bbf\u0bb7\u0bbe\u0951 \u0ba4\u0bc7\u0952\u0bb5\u0bbe \u0baf\u0952\u0b9c\u0bcd\u0b9e\u0bae\u0ba4\u0951\u0ba8\u0bcd\u0bb5\u0ba4 \u0964\n\u0bb5\u0952\u0bb8\u0952\u0ba8\u0bcd\u0ba4\u0bcb \u0b85\u0951\u0bb8\u0bcd\u0baf\u0bbe\u0bb8\u0bc0\u0952\u0ba4\u0bbe\u0b9c\u0bcd\u0baf\u0bae\u0bcd\u0951 \u0b95\u0bcd\u0bb0\u0bc0\u0952\u0bb7\u0bcd\u0bae \u0b87\u0952\u0ba4\u0bcd\u0bae\u0b83 \u0bb6\u0952\u0bb0\u0ba4\u0bcd\u0ba4\u0952\u0bb5\u0bbf\u0b83 \u0965 \u0bec \u0965", "kannada": "\u0caf\u0ca4\u0ccd\u0caa\u0cc1\u0cb0\u0cc1\u0951\u0cb7\u0cc7\u0ca3 \u0cb9\u0952\u0cb5\u0cbf\u0cb7\u0cbe\u0951 \u0ca6\u0cc7\u0952\u0cb5\u0cbe \u0caf\u0952\u0c9c\u0ccd\u0c9e\u0cae\u0ca4\u0951\u0ca8\u0ccd\u0cb5\u0ca4 \u0964\n\u0cb5\u0952\u0cb8\u0952\u0ca8\u0ccd\u0ca4\u0ccb \u0c85\u0951\u0cb8\u0ccd\u0caf\u0cbe\u0cb8\u0cc0\u0952\u0ca6\u0cbe\u0c9c\u0ccd\u0caf\u0c82\u0951 \u0c97\u0ccd\u0cb0\u0cc0\u0952\u0cb7\u0ccd\u0cae \u0c87\u0952\u0ca7\u0ccd\u0cae\u0c83 \u0cb6\u0952\u0cb0\u0ca6\u0ccd\u0ca7\u0952\u0cb5\u0cbf\u0c83 \u0965 \u0cec \u0965", "malayalam": "\u0d2f\u0d24\u0d4d\u0d2a\u0d41\u0d30\u0d41\u0951\u0d37\u0d47\u0d23 \u0d39\u0952\u0d35\u0d3f\u0d37\u0d3e\u0951 \u0d26\u0d47\u0952\u0d35\u0d3e \u0d2f\u0952\u0d1c\u0d4d\u0d1e\u0d2e\u0d24\u0951\u0d28\u0d4d\u0d35\u0d24 \u0964\n\u0d35\u0952\u0d38\u0952\u0d28\u0d4d\u0d24\u0d4b \u0d05\u0951\u0d38\u0d4d\u0d2f\u0d3e\u0d38\u0d40\u0952\u0d26\u0d3e\u0d1c\u0d4d\u0d2f\u0d02\u0951 \u0d17\u0d4d\u0d30\u0d40\u0952\u0d37\u0d4d\u0d2e \u0d07\u0952\u0d27\u0d4d\u0d2e\u0d03 \u0d36\u0952\u0d30\u0d26\u0d4d\u0d27\u0952\u0d35\u0d3f\u0d03 \u0965 \u0d6c \u0965", "iast": "yatpur\u1e77\u1e63e\u1e47a ha\u0331vi\u1e63\u0101\u032d de\u0331v\u0101 ya\u0331j\u00f1amata\u032dnvata |\nva\u0331sa\u0331nto a\u032dsy\u0101s\u012b\u0331d\u0101jya\u032d\u1e43 gr\u012b\u0331\u1e63ma i\u0331dhma\u1e25 \u015ba\u0331raddha\u0331vi\u1e25 || 6 ||"},
        draftTranslation: "When the divine powers performed the cosmic sacrifice with the Purusha as the offering, spring became its clarified butter, summer its sacred fuel, and autumn its oblatory oblation.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 7,
        devanagariText: "\u0938\u0952\u092a\u094d\u0924\u093e\u0938\u094d\u092f\u093e\u0951\u0938\u0928\u094d\u092a\u0930\u093f\u0952\u0927\u092f\u0952\u0938\u094d\u0924\u094d\u0930\u093f\u0903 \u0938\u0952\u092a\u094d\u0924 \u0938\u0952\u092e\u093f\u0927\u0903\u0951 \u0915\u0943\u0952\u0924\u093e\u0903 \u0964\n\u0926\u0947\u0952\u0935\u093e \u092f\u0926\u094d\u092f\u0952\u091c\u094d\u091e\u0902 \u0924\u0951\u0928\u094d\u0935\u093e\u0952\u0928\u093e \u0905\u092c\u0951\u0927\u094d\u0928\u0952\u0928\u094d\u092a\u0941\u0930\u0941\u0951\u0937\u0902 \u092a\u0952\u0936\u0941\u092e\u094d \u0965 \u096d \u0965",
        iastText: "sa\u0952pt\u0101sy\u0101\u0951sanpari\u0952dhaya\u0952stri\u1e25 sa\u0952pta sa\u0952midha\u1e25\u0951 k\u1e5b\u0952t\u0101\u1e25 \u0964\nd\u0113\u0952v\u0101 yadya\u0952j\u00f1a\u1e41 ta\u0951nv\u0101\u0952n\u0101 aba\u0951dhna\u0952npuru\u0951\u1e63a\u1e41 pa\u0952\u015bum \u0965 7 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0952\u0c2a\u0c4d\u0c24\u0c3e\u0c38\u0c4d\u0c2f\u0c3e\u0951\u0c38\u0c28\u0c4d\u0c2a\u0c30\u0c3f\u0952\u0c27\u0c2f\u0952\u0c38\u0c4d\u0c24\u0c4d\u0c30\u0c3f\u0c03 \u0c38\u0952\u0c2a\u0c4d\u0c24 \u0c38\u0952\u0c2e\u0c3f\u0c27\u0c03\u0951 \u0c15\u0c43\u0952\u0c24\u0c3e\u0c03 \u0964\n\u0c26\u0c47\u0952\u0c35\u0c3e \u0c2f\u0c26\u0c4d\u0c2f\u0952\u0c1c\u0c4d\u0c1e\u0c02 \u0c24\u0951\u0c28\u0c4d\u0c35\u0c3e\u0952\u0c28\u0c3e \u0c05\u0c2c\u0951\u0c27\u0c4d\u0c28\u0952\u0c28\u0c4d\u0c2a\u0c41\u0c30\u0c41\u0951\u0c37\u0c02 \u0c2a\u0952\u0c36\u0c41\u0c2e\u0c4d \u0965 \u0c6d \u0965", "tamil": "\u0bb8\u0952\u0baa\u0bcd\u0ba4\u0bbe\u0bb8\u0bcd\u0baf\u0bbe\u0951\u0bb8\u0ba8\u0bcd\u0baa\u0bb0\u0bbf\u0952\u0ba4\u0baf\u0952\u0bb8\u0bcd\u0ba4\u0bcd\u0bb0\u0bbf\u0b83 \u0bb8\u0952\u0baa\u0bcd\u0ba4 \u0bb8\u0952\u0bae\u0bbf\u0ba4\u0b83\u0951 \u0b95\u0bcd\u0bb0\u0bc1'\u0952\u0ba4\u0bbe\u0b83 \u0964\n\u0ba4\u0bc7\u0952\u0bb5\u0bbe \u0baf\u0ba4\u0bcd\u0baf\u0952\u0b9c\u0bcd\u0b9e\u0bae\u0bcd \u0ba4\u0951\u0ba8\u0bcd\u0bb5\u0bbe\u0952\u0ba8\u0bbe \u0b85\u0baa\u0951\u0ba4\u0bcd\u0ba8\u0952\u0ba8\u0bcd\u0baa\u0bc1\u0bb0\u0bc1\u0951\u0bb7\u0bae\u0bcd \u0baa\u0952\u0bb6\u0bc1\u0bae\u0bcd \u0965 \u0bed \u0965", "kannada": "\u0cb8\u0952\u0caa\u0ccd\u0ca4\u0cbe\u0cb8\u0ccd\u0caf\u0cbe\u0951\u0cb8\u0ca8\u0ccd\u0caa\u0cb0\u0cbf\u0952\u0ca7\u0caf\u0952\u0cb8\u0ccd\u0ca4\u0ccd\u0cb0\u0cbf\u0c83 \u0cb8\u0952\u0caa\u0ccd\u0ca4 \u0cb8\u0952\u0cae\u0cbf\u0ca7\u0c83\u0951 \u0c95\u0cc3\u0952\u0ca4\u0cbe\u0c83 \u0964\n\u0ca6\u0cc7\u0952\u0cb5\u0cbe \u0caf\u0ca6\u0ccd\u0caf\u0952\u0c9c\u0ccd\u0c9e\u0c82 \u0ca4\u0951\u0ca8\u0ccd\u0cb5\u0cbe\u0952\u0ca8\u0cbe \u0c85\u0cac\u0951\u0ca7\u0ccd\u0ca8\u0952\u0ca8\u0ccd\u0caa\u0cc1\u0cb0\u0cc1\u0951\u0cb7\u0c82 \u0caa\u0952\u0cb6\u0cc1\u0cae\u0ccd \u0965 \u0ced \u0965", "malayalam": "\u0d38\u0952\u0d2a\u0d4d\u0d24\u0d3e\u0d38\u0d4d\u0d2f\u0d3e\u0951\u0d38\u0d28\u0d4d\u0d2a\u0d30\u0d3f\u0952\u0d27\u0d2f\u0952\u0d38\u0d4d\u0d24\u0d4d\u0d30\u0d3f\u0d03 \u0d38\u0952\u0d2a\u0d4d\u0d24 \u0d38\u0952\u0d2e\u0d3f\u0d27\u0d03\u0951 \u0d15\u0d43\u0952\u0d24\u0d3e\u0d03 \u0964\n\u0d26\u0d47\u0952\u0d35\u0d3e \u0d2f\u0d26\u0d4d\u0d2f\u0952\u0d1c\u0d4d\u0d1e\u0d02 \u0d24\u0951\u0d28\u0d4d\u0d35\u0d3e\u0952\u0d28\u0d3e \u0d05\u0d2c\u0951\u0d27\u0d4d\u0d28\u0952\u0d28\u0d4d\u0d2a\u0d41\u0d30\u0d41\u0951\u0d37\u0d02 \u0d2a\u0952\u0d36\u0d41\u0d2e\u0d4d \u0965 \u0d6d \u0965", "iast": "sa\u0331pt\u0101sy\u0101\u032dsanpari\u0331dhaya\u0331stri\u1e25 sa\u0331pta sa\u0331midha\u032d\u1e25 k\u1e5b\u0331t\u0101\u1e25 |\nde\u0331v\u0101 yadya\u0331j\u00f1a\u1e43 ta\u032dnv\u0101\u0331n\u0101 aba\u032ddhna\u0331npur\u1e77\u1e63a\u1e43 pa\u0331\u015bum || 7 ||"},
        draftTranslation: "Seven were its enclosing border-sticks, and thrice seven (twenty-one) fuel-logs were prepared, when the divine powers offering the cosmic sacrifice bound the Purusha as the sacred victim.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 8,
        devanagariText: "\u0924\u0902 \u092f\u0952\u091c\u094d\u091e\u0902 \u092c\u0952\u0930\u094d\u0939\u093f\u0937\u093f\u0952 \u092a\u094d\u0930\u094c\u0915\u094d\u0937\u0952\u0928\u094d\u092a\u0941\u0930\u0941\u0951\u0937\u0902 \u091c\u093e\u0952\u0924\u092e\u0951\u0917\u094d\u0930\u0952\u0924\u0903 \u0964\n\u0924\u0947\u0928\u0951 \u0926\u0947\u0952\u0935\u093e \u0905\u092f\u0951\u091c\u0928\u094d\u0924 \u0938\u093e\u0952\u0927\u094d\u092f\u093e \u090b\u0937\u0951\u092f\u0936\u094d\u091a\u0952 \u092f\u0947 \u0965 \u096e \u0965",
        iastText: "ta\u1e41 ya\u0952j\u00f1a\u1e41 ba\u0952rhi\u1e63i\u0952 prauk\u1e63a\u0952npuru\u0951\u1e63a\u1e41 j\u0101\u0952tama\u0951gra\u0952ta\u1e25 \u0964\nt\u0113na\u0951 d\u0113\u0952v\u0101 aya\u0951janta s\u0101\u0952dhy\u0101 \u1e5b\u1e63a\u0951ya\u015bca\u0952 y\u0113 \u0965 8 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c24\u0c02 \u0c2f\u0952\u0c1c\u0c4d\u0c1e\u0c02 \u0c2c\u0952\u0c30\u0c4d\u0c39\u0c3f\u0c37\u0c3f\u0952 \u0c2a\u0c4d\u0c30\u0c4c\u0c15\u0c4d\u0c37\u0952\u0c28\u0c4d\u0c2a\u0c41\u0c30\u0c41\u0951\u0c37\u0c02 \u0c1c\u0c3e\u0952\u0c24\u0c2e\u0951\u0c17\u0c4d\u0c30\u0952\u0c24\u0c03 \u0964\n\u0c24\u0c47\u0c28\u0951 \u0c26\u0c47\u0952\u0c35\u0c3e \u0c05\u0c2f\u0951\u0c1c\u0c28\u0c4d\u0c24 \u0c38\u0c3e\u0952\u0c27\u0c4d\u0c2f\u0c3e \u0c0b\u0c37\u0951\u0c2f\u0c36\u0c4d\u0c1a\u0952 \u0c2f\u0c47 \u0965 \u0c6e \u0965", "tamil": "\u0ba4\u0bae\u0bcd \u0baf\u0952\u0b9c\u0bcd\u0b9e\u0bae\u0bcd \u0baa\u0952\u0bb0\u0bcd\u0bb9\u0bbf\u0bb7\u0bbf\u0952 \u0baa\u0bcd\u0bb0\u0bcc\u0b95\u0bcd\u0bb7\u0952\u0ba8\u0bcd\u0baa\u0bc1\u0bb0\u0bc1\u0951\u0bb7\u0bae\u0bcd \u0b9c\u0bbe\u0952\u0ba4\u0bae\u0951\u0b95\u0bcd\u0bb0\u0952\u0ba4\u0b83 \u0964\n\u0ba4\u0bc7\u0ba8\u0951 \u0ba4\u0bc7\u0952\u0bb5\u0bbe \u0b85\u0baf\u0951\u0b9c\u0ba8\u0bcd\u0ba4 \u0bb8\u0bbe\u0952\u0ba4\u0bcd\u0baf\u0bbe \u0bb0\u0bc1'\u0bb7\u0951\u0baf\u0bb6\u0bcd\u0b9a\u0952 \u0baf\u0bc7 \u0965 \u0bee \u0965", "kannada": "\u0ca4\u0c82 \u0caf\u0952\u0c9c\u0ccd\u0c9e\u0c82 \u0cac\u0952\u0cb0\u0ccd\u0cb9\u0cbf\u0cb7\u0cbf\u0952 \u0caa\u0ccd\u0cb0\u0ccc\u0c95\u0ccd\u0cb7\u0952\u0ca8\u0ccd\u0caa\u0cc1\u0cb0\u0cc1\u0951\u0cb7\u0c82 \u0c9c\u0cbe\u0952\u0ca4\u0cae\u0951\u0c97\u0ccd\u0cb0\u0952\u0ca4\u0c83 \u0964\n\u0ca4\u0cc7\u0ca8\u0951 \u0ca6\u0cc7\u0952\u0cb5\u0cbe \u0c85\u0caf\u0951\u0c9c\u0ca8\u0ccd\u0ca4 \u0cb8\u0cbe\u0952\u0ca7\u0ccd\u0caf\u0cbe \u0c8b\u0cb7\u0951\u0caf\u0cb6\u0ccd\u0c9a\u0952 \u0caf\u0cc7 \u0965 \u0cee \u0965", "malayalam": "\u0d24\u0d02 \u0d2f\u0952\u0d1c\u0d4d\u0d1e\u0d02 \u0d2c\u0952\u0d30\u0d4d\u0d39\u0d3f\u0d37\u0d3f\u0952 \u0d2a\u0d4d\u0d30\u0d4c\u0d15\u0d4d\u0d37\u0952\u0d28\u0d4d\u0d2a\u0d41\u0d30\u0d41\u0951\u0d37\u0d02 \u0d1c\u0d3e\u0952\u0d24\u0d2e\u0951\u0d17\u0d4d\u0d30\u0952\u0d24\u0d03 \u0964\n\u0d24\u0d47\u0d28\u0951 \u0d26\u0d47\u0952\u0d35\u0d3e \u0d05\u0d2f\u0951\u0d1c\u0d28\u0d4d\u0d24 \u0d38\u0d3e\u0952\u0d27\u0d4d\u0d2f\u0d3e \u0d0b\u0d37\u0951\u0d2f\u0d36\u0d4d\u0d1a\u0952 \u0d2f\u0d47 \u0965 \u0d6e \u0965", "iast": "ta\u1e43 ya\u0331j\u00f1a\u1e43 ba\u0331rhi\u1e63i\u0331 prauk\u1e63a\u0331npur\u1e77\u1e63a\u1e43 j\u0101\u0331tama\u032dgra\u0331ta\u1e25 |\ntena\u032d de\u0331v\u0101 aya\u032djanta s\u0101\u0331dhy\u0101 \u1e5b\u1e63a\u032dya\u015bca\u0331 ye || 8 ||"},
        draftTranslation: "They sprinkled with sacred waters that Purusha, the primordial sacrifice born at the very beginning, upon the sacred sacrificial grass. With Him the deities, the Sadhyas, and the ancient seers offered the sacrifice.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 9,
        devanagariText: "\u0924\u0938\u094d\u092e\u093e\u0951\u0926\u094d\u092f\u0952\u091c\u094d\u091e\u093e\u0924\u094d\u0938\u0951\u0930\u094d\u0935\u0952\u0939\u0941\u0924\u0903\u0952 \u0938\u0902\u092d\u0943\u0951\u0924\u0902 \u092a\u0943\u0937\u0926\u093e\u0952\u091c\u094d\u092f\u092e\u094d \u0964\n\u092a\u0952\u0936\u0942\u0928\u094d\u0924\u093e\u0902\u0936\u094d\u091a\u0951\u0915\u094d\u0930\u0947 \u0935\u093e\u092f\u0952\u0935\u094d\u092f\u093e\u0928\u093e\u0930\u0952\u0923\u094d\u092f\u093e\u0928\u094d \u0917\u094d\u0930\u093e\u092e\u094d\u092f\u093e\u0951\u0936\u094d\u091a\u0952 \u092f\u0947 \u0965 \u096f \u0965",
        iastText: "tasm\u0101\u0951dya\u0952j\u00f1\u0101tsa\u0951rva\u0952huta\u1e25\u0952 sa\u1e41bh\u1e5b\u0951ta\u1e41 p\u1e5b\u1e63ad\u0101\u0952jyam \u0964\npa\u0952\u015b\u016bnt\u0101\u1e41\u015bca\u0951kr\u0113 v\u0101ya\u0952vy\u0101n\u0101ra\u0952\u1e47y\u0101n gr\u0101my\u0101\u0951\u015bca\u0952 y\u0113 \u0965 9 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c24\u0c38\u0c4d\u0c2e\u0c3e\u0951\u0c26\u0c4d\u0c2f\u0952\u0c1c\u0c4d\u0c1e\u0c3e\u0c24\u0c4d\u0c38\u0951\u0c30\u0c4d\u0c35\u0952\u0c39\u0c41\u0c24\u0c03\u0952 \u0c38\u0c02\u0c2d\u0c43\u0951\u0c24\u0c02 \u0c2a\u0c43\u0c37\u0c26\u0c3e\u0952\u0c1c\u0c4d\u0c2f\u0c2e\u0c4d \u0964\n\u0c2a\u0952\u0c36\u0c42\u0c28\u0c4d\u0c24\u0c3e\u0c02\u0c36\u0c4d\u0c1a\u0951\u0c15\u0c4d\u0c30\u0c47 \u0c35\u0c3e\u0c2f\u0952\u0c35\u0c4d\u0c2f\u0c3e\u0c28\u0c3e\u0c30\u0952\u0c23\u0c4d\u0c2f\u0c3e\u0c28\u0c4d \u0c17\u0c4d\u0c30\u0c3e\u0c2e\u0c4d\u0c2f\u0c3e\u0951\u0c36\u0c4d\u0c1a\u0952 \u0c2f\u0c47 \u0965 \u0c6f \u0965", "tamil": "\u0ba4\u0bb8\u0bcd\u0bae\u0bbe\u0951\u0ba4\u0bcd\u0baf\u0952\u0b9c\u0bcd\u0b9e\u0bbe\u0ba4\u0bcd\u0bb8\u0951\u0bb0\u0bcd\u0bb5\u0952\u0bb9\u0bc1\u0ba4\u0b83\u0952 \u0bb8\u0bae\u0bcd\u0baa\u0bcd\u0bb0\u0bc1'\u0951\u0ba4\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0bc1'\u0bb7\u0ba4\u0bbe\u0952\u0b9c\u0bcd\u0baf\u0bae\u0bcd \u0964\n\u0baa\u0952\u0bb6\u0bc2\u0ba8\u0bcd\u0ba4\u0bbe\u0bae\u0bcd\u0bb6\u0bcd\u0b9a\u0951\u0b95\u0bcd\u0bb0\u0bc7 \u0bb5\u0bbe\u0baf\u0952\u0bb5\u0bcd\u0baf\u0bbe\u0ba8\u0bbe\u0bb0\u0952\u0ba3\u0bcd\u0baf\u0bbe\u0ba8\u0bcd \u0b95\u0bcd\u0bb0\u0bbe\u0bae\u0bcd\u0baf\u0bbe\u0951\u0bb6\u0bcd\u0b9a\u0952 \u0baf\u0bc7 \u0965 \u0bef \u0965", "kannada": "\u0ca4\u0cb8\u0ccd\u0cae\u0cbe\u0951\u0ca6\u0ccd\u0caf\u0952\u0c9c\u0ccd\u0c9e\u0cbe\u0ca4\u0ccd\u0cb8\u0951\u0cb0\u0ccd\u0cb5\u0952\u0cb9\u0cc1\u0ca4\u0c83\u0952 \u0cb8\u0c82\u0cad\u0cc3\u0951\u0ca4\u0c82 \u0caa\u0cc3\u0cb7\u0ca6\u0cbe\u0952\u0c9c\u0ccd\u0caf\u0cae\u0ccd \u0964\n\u0caa\u0952\u0cb6\u0cc2\u0ca8\u0ccd\u0ca4\u0cbe\u0c82\u0cb6\u0ccd\u0c9a\u0951\u0c95\u0ccd\u0cb0\u0cc7 \u0cb5\u0cbe\u0caf\u0952\u0cb5\u0ccd\u0caf\u0cbe\u0ca8\u0cbe\u0cb0\u0952\u0ca3\u0ccd\u0caf\u0cbe\u0ca8\u0ccd \u0c97\u0ccd\u0cb0\u0cbe\u0cae\u0ccd\u0caf\u0cbe\u0951\u0cb6\u0ccd\u0c9a\u0952 \u0caf\u0cc7 \u0965 \u0cef \u0965", "malayalam": "\u0d24\u0d38\u0d4d\u0d2e\u0d3e\u0951\u0d26\u0d4d\u0d2f\u0952\u0d1c\u0d4d\u0d1e\u0d3e\u0d24\u0d4d\u0d38\u0951\u0d30\u0d4d\u0d35\u0952\u0d39\u0d41\u0d24\u0d03\u0952 \u0d38\u0d02\u0d2d\u0d43\u0951\u0d24\u0d02 \u0d2a\u0d43\u0d37\u0d26\u0d3e\u0952\u0d1c\u0d4d\u0d2f\u0d2e\u0d4d \u0964\n\u0d2a\u0952\u0d36\u0d42\u0d28\u0d4d\u0d24\u0d3e\u0d02\u0d36\u0d4d\u0d1a\u0951\u0d15\u0d4d\u0d30\u0d47 \u0d35\u0d3e\u0d2f\u0952\u0d35\u0d4d\u0d2f\u0d3e\u0d28\u0d3e\u0d30\u0952\u0d23\u0d4d\u0d2f\u0d3e\u0d28\u0d4d \u0d17\u0d4d\u0d30\u0d3e\u0d2e\u0d4d\u0d2f\u0d3e\u0951\u0d36\u0d4d\u0d1a\u0952 \u0d2f\u0d47 \u0965 \u0d6f \u0965", "iast": "tasm\u0101\u032ddya\u0331j\u00f1\u0101tsa\u032drva\u0331huta\u0331\u1e25 sa\u1e43bh\u1e5b\u032dta\u1e43 p\u1e5b\u1e63ad\u0101\u0331jyam |\npa\u0331\u015b\u016bnt\u0101\u1e43\u015bca\u032dkre v\u0101ya\u0331vy\u0101n\u0101ra\u0331\u1e47y\u0101n gr\u0101my\u0101\u032d\u015bca\u0331 ye || 9 ||"},
        draftTranslation: "From that cosmic sacrifice in which everything was offered, speckled butter (clarified butter and curds) was collected. From it were formed the creatures ruled by Vayu (air), both wild beasts of the forest and domestic animals.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 10,
        devanagariText: "\u0924\u0938\u094d\u092e\u093e\u0951\u0926\u094d\u092f\u0952\u091c\u094d\u091e\u093e\u0924\u094d\u0938\u0951\u0930\u094d\u0935\u0952\u0939\u0941\u0924\u0952 \u090b\u091a\u0903\u0952 \u0938\u093e\u092e\u093e\u0951\u0928\u093f \u091c\u091c\u094d\u091e\u093f\u0930\u0947 \u0964\n\u091a\u094d\u091b\u0928\u094d\u0926\u093e\u0902\u0951\u0938\u093f \u091c\u091c\u094d\u091e\u093f\u0930\u0947\u0952 \u0924\u0938\u094d\u092e\u093e\u0952\u0926\u094d\u092f\u091c\u0941\u0952\u0938\u094d\u0924\u0938\u094d\u092e\u093e\u0951\u0926\u091c\u093e\u092f\u0924 \u0965 \u0967\u0966 \u0965",
        iastText: "tasm\u0101\u0951dya\u0952j\u00f1\u0101tsa\u0951rva\u0952huta\u0952 \u1e5bca\u1e25\u0952 s\u0101m\u0101\u0951ni jaj\u00f1ir\u0113 \u0964\ncchand\u0101\u1e41\u0951si jaj\u00f1ir\u0113\u0952 tasm\u0101\u0952dyaju\u0952stasm\u0101\u0951daj\u0101yata \u0965 10 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c24\u0c38\u0c4d\u0c2e\u0c3e\u0951\u0c26\u0c4d\u0c2f\u0952\u0c1c\u0c4d\u0c1e\u0c3e\u0c24\u0c4d\u0c38\u0951\u0c30\u0c4d\u0c35\u0952\u0c39\u0c41\u0c24\u0952 \u0c0b\u0c1a\u0c03\u0952 \u0c38\u0c3e\u0c2e\u0c3e\u0951\u0c28\u0c3f \u0c1c\u0c1c\u0c4d\u0c1e\u0c3f\u0c30\u0c47 \u0964\n\u0c1a\u0c4d\u0c1b\u0c28\u0c4d\u0c26\u0c3e\u0c02\u0951\u0c38\u0c3f \u0c1c\u0c1c\u0c4d\u0c1e\u0c3f\u0c30\u0c47\u0952 \u0c24\u0c38\u0c4d\u0c2e\u0c3e\u0952\u0c26\u0c4d\u0c2f\u0c1c\u0c41\u0952\u0c38\u0c4d\u0c24\u0c38\u0c4d\u0c2e\u0c3e\u0951\u0c26\u0c1c\u0c3e\u0c2f\u0c24 \u0965 \u0c67\u0c66 \u0965", "tamil": "\u0ba4\u0bb8\u0bcd\u0bae\u0bbe\u0951\u0ba4\u0bcd\u0baf\u0952\u0b9c\u0bcd\u0b9e\u0bbe\u0ba4\u0bcd\u0bb8\u0951\u0bb0\u0bcd\u0bb5\u0952\u0bb9\u0bc1\u0ba4\u0952 \u0bb0\u0bc1'\u0b9a\u0b83\u0952 \u0bb8\u0bbe\u0bae\u0bbe\u0951\u0ba8\u0bbf \u0b9c\u0b9c\u0bcd\u0b9e\u0bbf\u0bb0\u0bc7 \u0964\n\u0b9a\u0bcd\u0b9a\u0ba8\u0bcd\u0ba4\u0bbe\u0bae\u0bcd\u0951\u0bb8\u0bbf \u0b9c\u0b9c\u0bcd\u0b9e\u0bbf\u0bb0\u0bc7\u0952 \u0ba4\u0bb8\u0bcd\u0bae\u0bbe\u0952\u0ba4\u0bcd\u0baf\u0b9c\u0bc1\u0952\u0bb8\u0bcd\u0ba4\u0bb8\u0bcd\u0bae\u0bbe\u0951\u0ba4\u0b9c\u0bbe\u0baf\u0ba4 \u0965 \u0be7\u0be6 \u0965", "kannada": "\u0ca4\u0cb8\u0ccd\u0cae\u0cbe\u0951\u0ca6\u0ccd\u0caf\u0952\u0c9c\u0ccd\u0c9e\u0cbe\u0ca4\u0ccd\u0cb8\u0951\u0cb0\u0ccd\u0cb5\u0952\u0cb9\u0cc1\u0ca4\u0952 \u0c8b\u0c9a\u0c83\u0952 \u0cb8\u0cbe\u0cae\u0cbe\u0951\u0ca8\u0cbf \u0c9c\u0c9c\u0ccd\u0c9e\u0cbf\u0cb0\u0cc7 \u0964\n\u0c9a\u0ccd\u0c9b\u0ca8\u0ccd\u0ca6\u0cbe\u0c82\u0951\u0cb8\u0cbf \u0c9c\u0c9c\u0ccd\u0c9e\u0cbf\u0cb0\u0cc7\u0952 \u0ca4\u0cb8\u0ccd\u0cae\u0cbe\u0952\u0ca6\u0ccd\u0caf\u0c9c\u0cc1\u0952\u0cb8\u0ccd\u0ca4\u0cb8\u0ccd\u0cae\u0cbe\u0951\u0ca6\u0c9c\u0cbe\u0caf\u0ca4 \u0965 \u0ce7\u0ce6 \u0965", "malayalam": "\u0d24\u0d38\u0d4d\u0d2e\u0d3e\u0951\u0d26\u0d4d\u0d2f\u0952\u0d1c\u0d4d\u0d1e\u0d3e\u0d24\u0d4d\u0d38\u0951\u0d30\u0d4d\u0d35\u0952\u0d39\u0d41\u0d24\u0952 \u0d0b\u0d1a\u0d03\u0952 \u0d38\u0d3e\u0d2e\u0d3e\u0951\u0d28\u0d3f \u0d1c\u0d1c\u0d4d\u0d1e\u0d3f\u0d30\u0d47 \u0964\n\u0d1a\u0d4d\u0d1b\u0d28\u0d4d\u0d26\u0d3e\u0d02\u0951\u0d38\u0d3f \u0d1c\u0d1c\u0d4d\u0d1e\u0d3f\u0d30\u0d47\u0952 \u0d24\u0d38\u0d4d\u0d2e\u0d3e\u0952\u0d26\u0d4d\u0d2f\u0d1c\u0d41\u0952\u0d38\u0d4d\u0d24\u0d38\u0d4d\u0d2e\u0d3e\u0951\u0d26\u0d1c\u0d3e\u0d2f\u0d24 \u0965 \u0d67\u0d66 \u0965", "iast": "tasm\u0101\u032ddya\u0331j\u00f1\u0101tsa\u032drva\u0331huta\u0331 \u1e5bca\u0331\u1e25 s\u0101m\u0101\u032dni jaj\u00f1ire |\ncchand\u0101\u032d\u1e43si jaj\u00f1ire\u0331 tasm\u0101\u0331dyaju\u0331stasm\u0101\u032ddaj\u0101yata || 10 ||"},
        draftTranslation: "From that all-embracing sacrifice the Rig hymns and Sama chants were born. From it the sacred metres were produced, and from it the Yajus sacrificial formulas arose.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 11,
        devanagariText: "\u0924\u0938\u094d\u092e\u093e\u0952\u0926\u0936\u094d\u0935\u093e\u0951 \u0905\u091c\u093e\u092f\u0928\u094d\u0924\u0952 \u092f\u0947 \u0915\u0947 \u091a\u094b\u0951\u092d\u0952\u092f\u093e\u0926\u0951\u0924\u0903 \u0964\n\u0917\u093e\u0935\u094b\u0951 \u0939 \u091c\u091c\u094d\u091e\u093f\u0930\u0947\u0952 \u0924\u0938\u094d\u092e\u093e\u0952\u0924\u094d\u0924\u0938\u094d\u092e\u093e\u0951\u091c\u094d\u091c\u093e\u0952\u0924\u093e \u0905\u0951\u091c\u093e\u0952\u0935\u092f\u0903\u0951 \u0965 \u0967\u0967 \u0965",
        iastText: "tasm\u0101\u0952da\u015bv\u0101\u0951 aj\u0101yanta\u0952 y\u0113 k\u0113 c\u014d\u0951bha\u0952y\u0101da\u0951ta\u1e25 \u0964\ng\u0101v\u014d\u0951 ha jaj\u00f1ir\u0113\u0952 tasm\u0101\u0952ttasm\u0101\u0951jj\u0101\u0952t\u0101 a\u0951j\u0101\u0952vaya\u1e25\u0951 \u0965 11 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c24\u0c38\u0c4d\u0c2e\u0c3e\u0952\u0c26\u0c36\u0c4d\u0c35\u0c3e\u0951 \u0c05\u0c1c\u0c3e\u0c2f\u0c28\u0c4d\u0c24\u0952 \u0c2f\u0c47 \u0c15\u0c47 \u0c1a\u0c4b\u0951\u0c2d\u0952\u0c2f\u0c3e\u0c26\u0951\u0c24\u0c03 \u0964\n\u0c17\u0c3e\u0c35\u0c4b\u0951 \u0c39 \u0c1c\u0c1c\u0c4d\u0c1e\u0c3f\u0c30\u0c47\u0952 \u0c24\u0c38\u0c4d\u0c2e\u0c3e\u0952\u0c24\u0c4d\u0c24\u0c38\u0c4d\u0c2e\u0c3e\u0951\u0c1c\u0c4d\u0c1c\u0c3e\u0952\u0c24\u0c3e \u0c05\u0951\u0c1c\u0c3e\u0952\u0c35\u0c2f\u0c03\u0951 \u0965 \u0c67\u0c67 \u0965", "tamil": "\u0ba4\u0bb8\u0bcd\u0bae\u0bbe\u0952\u0ba4\u0bb6\u0bcd\u0bb5\u0bbe\u0951 \u0b85\u0b9c\u0bbe\u0baf\u0ba8\u0bcd\u0ba4\u0952 \u0baf\u0bc7 \u0b95\u0bc7 \u0b9a\u0bcb\u0951\u0baa\u0952\u0baf\u0bbe\u0ba4\u0951\u0ba4\u0b83 \u0964\n\u0b95\u0bbe\u0bb5\u0bcb\u0951 \u0bb9 \u0b9c\u0b9c\u0bcd\u0b9e\u0bbf\u0bb0\u0bc7\u0952 \u0ba4\u0bb8\u0bcd\u0bae\u0bbe\u0952\u0ba4\u0bcd\u0ba4\u0bb8\u0bcd\u0bae\u0bbe\u0951\u0b9c\u0bcd\u0b9c\u0bbe\u0952\u0ba4\u0bbe \u0b85\u0951\u0b9c\u0bbe\u0952\u0bb5\u0baf\u0b83\u0951 \u0965 \u0be7\u0be7 \u0965", "kannada": "\u0ca4\u0cb8\u0ccd\u0cae\u0cbe\u0952\u0ca6\u0cb6\u0ccd\u0cb5\u0cbe\u0951 \u0c85\u0c9c\u0cbe\u0caf\u0ca8\u0ccd\u0ca4\u0952 \u0caf\u0cc7 \u0c95\u0cc7 \u0c9a\u0ccb\u0951\u0cad\u0952\u0caf\u0cbe\u0ca6\u0951\u0ca4\u0c83 \u0964\n\u0c97\u0cbe\u0cb5\u0ccb\u0951 \u0cb9 \u0c9c\u0c9c\u0ccd\u0c9e\u0cbf\u0cb0\u0cc7\u0952 \u0ca4\u0cb8\u0ccd\u0cae\u0cbe\u0952\u0ca4\u0ccd\u0ca4\u0cb8\u0ccd\u0cae\u0cbe\u0951\u0c9c\u0ccd\u0c9c\u0cbe\u0952\u0ca4\u0cbe \u0c85\u0951\u0c9c\u0cbe\u0952\u0cb5\u0caf\u0c83\u0951 \u0965 \u0ce7\u0ce7 \u0965", "malayalam": "\u0d24\u0d38\u0d4d\u0d2e\u0d3e\u0952\u0d26\u0d36\u0d4d\u0d35\u0d3e\u0951 \u0d05\u0d1c\u0d3e\u0d2f\u0d28\u0d4d\u0d24\u0952 \u0d2f\u0d47 \u0d15\u0d47 \u0d1a\u0d4b\u0951\u0d2d\u0952\u0d2f\u0d3e\u0d26\u0951\u0d24\u0d03 \u0964\n\u0d17\u0d3e\u0d35\u0d4b\u0951 \u0d39 \u0d1c\u0d1c\u0d4d\u0d1e\u0d3f\u0d30\u0d47\u0952 \u0d24\u0d38\u0d4d\u0d2e\u0d3e\u0952\u0d24\u0d4d\u0d24\u0d38\u0d4d\u0d2e\u0d3e\u0951\u0d1c\u0d4d\u0d1c\u0d3e\u0952\u0d24\u0d3e \u0d05\u0951\u0d1c\u0d3e\u0952\u0d35\u0d2f\u0d03\u0951 \u0965 \u0d67\u0d67 \u0965", "iast": "tasm\u0101\u0331da\u015bv\u0101\u032d aj\u0101yanta\u0331 ye ke co\u032dbha\u0331y\u0101da\u032dta\u1e25 |\ng\u0101vo\u032d ha jaj\u00f1ire\u0331 tasm\u0101\u0331ttasm\u0101\u032djj\u0101\u0331t\u0101 a\u032dj\u0101\u0331vaya\u032d\u1e25 || 11 ||"},
        draftTranslation: "From it horses were generated, and all animals possessing two rows of teeth. Cattle were born from it, and from it were born goats and sheep.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 12,
        devanagariText: "\u092f\u0924\u094d\u092a\u0941\u0930\u0941\u0951\u0937\u0902 \u0935\u094d\u092f\u0952\u0926\u0927\u0941\u0903\u0952 \u0915\u0924\u093f\u0952\u0927\u093e \u0935\u094d\u092f\u0951\u0915\u0932\u094d\u092a\u092f\u0928\u094d \u0964\n\u092e\u0941\u0916\u0902\u0952 \u0915\u093f\u092e\u0951\u0938\u094d\u092f\u0952 \u0915\u094c \u092c\u093e\u0952\u0939\u0942 \u0915\u093e\u0935\u0942\u0952\u0930\u0942 \u092a\u093e\u0926\u093e\u0951\u0935\u0941\u091a\u094d\u092f\u0947\u0924\u0947 \u0965 \u0967\u0968 \u0965",
        iastText: "yatpuru\u0951\u1e63a\u1e41 vya\u0952dadhu\u1e25\u0952 kati\u0952dh\u0101 vya\u0951kalpayan \u0964\nmukha\u1e41\u0952 kima\u0951sya\u0952 kau b\u0101\u0952h\u016b k\u0101v\u016b\u0952r\u016b p\u0101d\u0101\u0951vucy\u0113t\u0113 \u0965 12 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2f\u0c24\u0c4d\u0c2a\u0c41\u0c30\u0c41\u0951\u0c37\u0c02 \u0c35\u0c4d\u0c2f\u0952\u0c26\u0c27\u0c41\u0c03\u0952 \u0c15\u0c24\u0c3f\u0952\u0c27\u0c3e \u0c35\u0c4d\u0c2f\u0951\u0c15\u0c32\u0c4d\u0c2a\u0c2f\u0c28\u0c4d \u0964\n\u0c2e\u0c41\u0c16\u0c02\u0952 \u0c15\u0c3f\u0c2e\u0951\u0c38\u0c4d\u0c2f\u0952 \u0c15\u0c4c \u0c2c\u0c3e\u0952\u0c39\u0c42 \u0c15\u0c3e\u0c35\u0c42\u0952\u0c30\u0c42 \u0c2a\u0c3e\u0c26\u0c3e\u0951\u0c35\u0c41\u0c1a\u0c4d\u0c2f\u0c47\u0c24\u0c47 \u0965 \u0c67\u0c68 \u0965", "tamil": "\u0baf\u0ba4\u0bcd\u0baa\u0bc1\u0bb0\u0bc1\u0951\u0bb7\u0bae\u0bcd \u0bb5\u0bcd\u0baf\u0952\u0ba4\u0ba4\u0bc1\u0b83\u0952 \u0b95\u0ba4\u0bbf\u0952\u0ba4\u0bbe \u0bb5\u0bcd\u0baf\u0951\u0b95\u0bb2\u0bcd\u0baa\u0baf\u0ba8\u0bcd \u0964\n\u0bae\u0bc1\u0b95\u0bae\u0bcd\u0952 \u0b95\u0bbf\u0bae\u0951\u0bb8\u0bcd\u0baf\u0952 \u0b95\u0bcc \u0baa\u0bbe\u0952\u0bb9\u0bc2 \u0b95\u0bbe\u0bb5\u0bc2\u0952\u0bb0\u0bc2 \u0baa\u0bbe\u0ba4\u0bbe\u0951\u0bb5\u0bc1\u0b9a\u0bcd\u0baf\u0bc7\u0ba4\u0bc7 \u0965 \u0be7\u0be8 \u0965", "kannada": "\u0caf\u0ca4\u0ccd\u0caa\u0cc1\u0cb0\u0cc1\u0951\u0cb7\u0c82 \u0cb5\u0ccd\u0caf\u0952\u0ca6\u0ca7\u0cc1\u0c83\u0952 \u0c95\u0ca4\u0cbf\u0952\u0ca7\u0cbe \u0cb5\u0ccd\u0caf\u0951\u0c95\u0cb2\u0ccd\u0caa\u0caf\u0ca8\u0ccd \u0964\n\u0cae\u0cc1\u0c96\u0c82\u0952 \u0c95\u0cbf\u0cae\u0951\u0cb8\u0ccd\u0caf\u0952 \u0c95\u0ccc \u0cac\u0cbe\u0952\u0cb9\u0cc2 \u0c95\u0cbe\u0cb5\u0cc2\u0952\u0cb0\u0cc2 \u0caa\u0cbe\u0ca6\u0cbe\u0951\u0cb5\u0cc1\u0c9a\u0ccd\u0caf\u0cc7\u0ca4\u0cc7 \u0965 \u0ce7\u0ce8 \u0965", "malayalam": "\u0d2f\u0d24\u0d4d\u0d2a\u0d41\u0d30\u0d41\u0951\u0d37\u0d02 \u0d35\u0d4d\u0d2f\u0952\u0d26\u0d27\u0d41\u0d03\u0952 \u0d15\u0d24\u0d3f\u0952\u0d27\u0d3e \u0d35\u0d4d\u0d2f\u0951\u0d15\u0d32\u0d4d\u0d2a\u0d2f\u0d28\u0d4d \u0964\n\u0d2e\u0d41\u0d16\u0d02\u0952 \u0d15\u0d3f\u0d2e\u0951\u0d38\u0d4d\u0d2f\u0952 \u0d15\u0d4c \u0d2c\u0d3e\u0952\u0d39\u0d42 \u0d15\u0d3e\u0d35\u0d42\u0952\u0d30\u0d42 \u0d2a\u0d3e\u0d26\u0d3e\u0951\u0d35\u0d41\u0d1a\u0d4d\u0d2f\u0d47\u0d24\u0d47 \u0965 \u0d67\u0d68 \u0965", "iast": "yatpur\u1e77\u1e63a\u1e43 vya\u0331dadhu\u0331\u1e25 kati\u0331dh\u0101 vya\u032dkalpayan |\nmukha\u0331\u1e43 kima\u032dsya\u0331 kau b\u0101\u0331h\u016b k\u0101v\u016b\u0331r\u016b p\u0101d\u0101\u032dvucyete || 12 ||"},
        draftTranslation: "When they partitioned the Purusha, into how many portions did they divide Him? What was His mouth called? What were His arms, His thighs, and His feet named?",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 13,
        devanagariText: "\u092c\u094d\u0930\u093e\u0952\u0939\u094d\u092e\u0952\u0923\u094b\u0951\u093d\u0938\u094d\u092f\u0952 \u092e\u0941\u0916\u0951\u092e\u093e\u0938\u0940\u0926\u094d\u092c\u093e\u0952\u0939\u0942 \u0930\u093e\u0951\u091c\u0952\u0928\u094d\u092f\u0903\u0951 \u0915\u0943\u0952\u0924\u0903 \u0964\n\u090a\u0952\u0930\u0942 \u0924\u0926\u0951\u0938\u094d\u092f\u0952 \u092f\u0926\u094d\u0935\u0948\u0936\u094d\u092f\u0903\u0951 \u092a\u0952\u0926\u094d\u092d\u094d\u092f\u093e\u0902 \u0936\u0942\u0952\u0926\u094d\u0930\u094b \u0905\u0951\u091c\u093e\u092f\u0924 \u0965 \u0967\u0969 \u0965",
        iastText: "br\u0101\u0952hma\u0952\u1e47\u014d\u0951'sya\u0952 mukha\u0951m\u0101s\u012bdb\u0101\u0952h\u016b r\u0101\u0951ja\u0952nya\u1e25\u0951 k\u1e5b\u0952ta\u1e25 \u0964\n\u016b\u0952r\u016b tada\u0951sya\u0952 yadvai\u015bya\u1e25\u0951 pa\u0952dbhy\u0101\u1e41 \u015b\u016b\u0952dr\u014d a\u0951j\u0101yata \u0965 13 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2c\u0c4d\u0c30\u0c3e\u0952\u0c39\u0c4d\u0c2e\u0952\u0c23\u0c4b\u0951\u0c3d\u0c38\u0c4d\u0c2f\u0952 \u0c2e\u0c41\u0c16\u0951\u0c2e\u0c3e\u0c38\u0c40\u0c26\u0c4d\u0c2c\u0c3e\u0952\u0c39\u0c42 \u0c30\u0c3e\u0951\u0c1c\u0952\u0c28\u0c4d\u0c2f\u0c03\u0951 \u0c15\u0c43\u0952\u0c24\u0c03 \u0964\n\u0c0a\u0952\u0c30\u0c42 \u0c24\u0c26\u0951\u0c38\u0c4d\u0c2f\u0952 \u0c2f\u0c26\u0c4d\u0c35\u0c48\u0c36\u0c4d\u0c2f\u0c03\u0951 \u0c2a\u0952\u0c26\u0c4d\u0c2d\u0c4d\u0c2f\u0c3e\u0c02 \u0c36\u0c42\u0952\u0c26\u0c4d\u0c30\u0c4b \u0c05\u0951\u0c1c\u0c3e\u0c2f\u0c24 \u0965 \u0c67\u0c69 \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0bbe\u0952\u0bb9\u0bcd\u0bae\u0952\u0ba3\u0bcb\u0951\u093d\u0bb8\u0bcd\u0baf\u0952 \u0bae\u0bc1\u0b95\u0951\u0bae\u0bbe\u0bb8\u0bc0\u0ba4\u0bcd\u0baa\u0bbe\u0952\u0bb9\u0bc2 \u0bb0\u0bbe\u0951\u0b9c\u0952\u0ba8\u0bcd\u0baf\u0b83\u0951 \u0b95\u0bcd\u0bb0\u0bc1'\u0952\u0ba4\u0b83 \u0964\n\u0b8a\u0952\u0bb0\u0bc2 \u0ba4\u0ba4\u0951\u0bb8\u0bcd\u0baf\u0952 \u0baf\u0ba4\u0bcd\u0bb5\u0bc8\u0bb6\u0bcd\u0baf\u0b83\u0951 \u0baa\u0952\u0ba4\u0bcd\u0baa\u0bcd\u0baf\u0bbe\u0bae\u0bcd \u0bb6\u0bc2\u0952\u0ba4\u0bcd\u0bb0\u0bcb \u0b85\u0951\u0b9c\u0bbe\u0baf\u0ba4 \u0965 \u0be7\u0be9 \u0965", "kannada": "\u0cac\u0ccd\u0cb0\u0cbe\u0952\u0cb9\u0ccd\u0cae\u0952\u0ca3\u0ccb\u0951\u0cbd\u0cb8\u0ccd\u0caf\u0952 \u0cae\u0cc1\u0c96\u0951\u0cae\u0cbe\u0cb8\u0cc0\u0ca6\u0ccd\u0cac\u0cbe\u0952\u0cb9\u0cc2 \u0cb0\u0cbe\u0951\u0c9c\u0952\u0ca8\u0ccd\u0caf\u0c83\u0951 \u0c95\u0cc3\u0952\u0ca4\u0c83 \u0964\n\u0c8a\u0952\u0cb0\u0cc2 \u0ca4\u0ca6\u0951\u0cb8\u0ccd\u0caf\u0952 \u0caf\u0ca6\u0ccd\u0cb5\u0cc8\u0cb6\u0ccd\u0caf\u0c83\u0951 \u0caa\u0952\u0ca6\u0ccd\u0cad\u0ccd\u0caf\u0cbe\u0c82 \u0cb6\u0cc2\u0952\u0ca6\u0ccd\u0cb0\u0ccb \u0c85\u0951\u0c9c\u0cbe\u0caf\u0ca4 \u0965 \u0ce7\u0ce9 \u0965", "malayalam": "\u0d2c\u0d4d\u0d30\u0d3e\u0952\u0d39\u0d4d\u0d2e\u0952\u0d23\u0d4b\u0951\u0d3d\u0d38\u0d4d\u0d2f\u0952 \u0d2e\u0d41\u0d16\u0951\u0d2e\u0d3e\u0d38\u0d40\u0d26\u0d4d\u0d2c\u0d3e\u0952\u0d39\u0d42 \u0d30\u0d3e\u0951\u0d1c\u0952\u0d28\u0d4d\u0d2f\u0d03\u0951 \u0d15\u0d43\u0952\u0d24\u0d03 \u0964\n\u0d0a\u0952\u0d30\u0d42 \u0d24\u0d26\u0951\u0d38\u0d4d\u0d2f\u0952 \u0d2f\u0d26\u0d4d\u0d35\u0d48\u0d36\u0d4d\u0d2f\u0d03\u0951 \u0d2a\u0952\u0d26\u0d4d\u0d2d\u0d4d\u0d2f\u0d3e\u0d02 \u0d36\u0d42\u0952\u0d26\u0d4d\u0d30\u0d4b \u0d05\u0951\u0d1c\u0d3e\u0d2f\u0d24 \u0965 \u0d67\u0d69 \u0965", "iast": "br\u0101\u0331hma\u0331\u1e47o\u032d'sya\u0331 mukha\u032dm\u0101s\u012bdb\u0101\u0331h\u016b r\u0101\u032dja\u0331nya\u032d\u1e25 k\u1e5b\u0331ta\u1e25 |\n\u016b\u0331r\u016b tada\u032dsya\u0331 yadvai\u015bya\u032d\u1e25 pa\u0331dbhy\u0101\u1e43 \u015b\u016b\u0331dro a\u032dj\u0101yata || 13 ||"},
        draftTranslation: "The Brahmana (priest/scholar) was His mouth; the Rajanya (warrior/king) was made from His arms; His thighs became the Vaishya (merchant/agriculturist); from His feet the Shudra (service-provider) was born.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 14,
        devanagariText: "\u091a\u0952\u0928\u094d\u0926\u094d\u0930\u092e\u093e\u0952 \u092e\u0928\u0951\u0938\u094b \u091c\u093e\u0952\u0924\u0936\u094d\u091a\u0915\u094d\u0937\u094b\u0903\u0952 \u0938\u0942\u0930\u094d\u092f\u094b\u0951 \u0905\u091c\u093e\u092f\u0924 \u0964\n\u092e\u0941\u0916\u093e\u0952\u0926\u093f\u0928\u094d\u0926\u094d\u0930\u0951\u0936\u094d\u091a\u093e\u0952\u0917\u094d\u0928\u093f\u0936\u094d\u091a\u0951 \u092a\u094d\u0930\u093e\u0952\u0923\u093e\u0926\u094d\u0935\u093e\u0952\u092f\u0941\u0930\u0951\u091c\u093e\u092f\u0924 \u0965 \u0967\u096a \u0965",
        iastText: "ca\u0952ndram\u0101\u0952 mana\u0951s\u014d j\u0101\u0952ta\u015bcak\u1e63\u014d\u1e25\u0952 s\u016bry\u014d\u0951 aj\u0101yata \u0964\nmukh\u0101\u0952dindra\u0951\u015bc\u0101\u0952gni\u015bca\u0951 pr\u0101\u0952\u1e47\u0101dv\u0101\u0952yura\u0951j\u0101yata \u0965 14 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c1a\u0952\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c2e\u0c3e\u0952 \u0c2e\u0c28\u0951\u0c38\u0c4b \u0c1c\u0c3e\u0952\u0c24\u0c36\u0c4d\u0c1a\u0c15\u0c4d\u0c37\u0c4b\u0c03\u0952 \u0c38\u0c42\u0c30\u0c4d\u0c2f\u0c4b\u0951 \u0c05\u0c1c\u0c3e\u0c2f\u0c24 \u0964\n\u0c2e\u0c41\u0c16\u0c3e\u0952\u0c26\u0c3f\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0951\u0c36\u0c4d\u0c1a\u0c3e\u0952\u0c17\u0c4d\u0c28\u0c3f\u0c36\u0c4d\u0c1a\u0951 \u0c2a\u0c4d\u0c30\u0c3e\u0952\u0c23\u0c3e\u0c26\u0c4d\u0c35\u0c3e\u0952\u0c2f\u0c41\u0c30\u0951\u0c1c\u0c3e\u0c2f\u0c24 \u0965 \u0c67\u0c6a \u0965", "tamil": "\u0b9a\u0952\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bae\u0bbe\u0952 \u0bae\u0ba8\u0951\u0bb8\u0bcb \u0b9c\u0bbe\u0952\u0ba4\u0bb6\u0bcd\u0b9a\u0b95\u0bcd\u0bb7\u0bcb\u0b83\u0952 \u0bb8\u0bc2\u0bb0\u0bcd\u0baf\u0bcb\u0951 \u0b85\u0b9c\u0bbe\u0baf\u0ba4 \u0964\n\u0bae\u0bc1\u0b95\u0bbe\u0952\u0ba4\u0bbf\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0951\u0bb6\u0bcd\u0b9a\u0bbe\u0952\u0b95\u0bcd\u0ba8\u0bbf\u0bb6\u0bcd\u0b9a\u0951 \u0baa\u0bcd\u0bb0\u0bbe\u0952\u0ba3\u0bbe\u0ba4\u0bcd\u0bb5\u0bbe\u0952\u0baf\u0bc1\u0bb0\u0951\u0b9c\u0bbe\u0baf\u0ba4 \u0965 \u0be7\u0bea \u0965", "kannada": "\u0c9a\u0952\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0cae\u0cbe\u0952 \u0cae\u0ca8\u0951\u0cb8\u0ccb \u0c9c\u0cbe\u0952\u0ca4\u0cb6\u0ccd\u0c9a\u0c95\u0ccd\u0cb7\u0ccb\u0c83\u0952 \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0ccb\u0951 \u0c85\u0c9c\u0cbe\u0caf\u0ca4 \u0964\n\u0cae\u0cc1\u0c96\u0cbe\u0952\u0ca6\u0cbf\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0951\u0cb6\u0ccd\u0c9a\u0cbe\u0952\u0c97\u0ccd\u0ca8\u0cbf\u0cb6\u0ccd\u0c9a\u0951 \u0caa\u0ccd\u0cb0\u0cbe\u0952\u0ca3\u0cbe\u0ca6\u0ccd\u0cb5\u0cbe\u0952\u0caf\u0cc1\u0cb0\u0951\u0c9c\u0cbe\u0caf\u0ca4 \u0965 \u0ce7\u0cea \u0965", "malayalam": "\u0d1a\u0952\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d2e\u0d3e\u0952 \u0d2e\u0d28\u0951\u0d38\u0d4b \u0d1c\u0d3e\u0952\u0d24\u0d36\u0d4d\u0d1a\u0d15\u0d4d\u0d37\u0d4b\u0d03\u0952 \u0d38\u0d42\u0d30\u0d4d\u0d2f\u0d4b\u0951 \u0d05\u0d1c\u0d3e\u0d2f\u0d24 \u0964\n\u0d2e\u0d41\u0d16\u0d3e\u0952\u0d26\u0d3f\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0951\u0d36\u0d4d\u0d1a\u0d3e\u0952\u0d17\u0d4d\u0d28\u0d3f\u0d36\u0d4d\u0d1a\u0951 \u0d2a\u0d4d\u0d30\u0d3e\u0952\u0d23\u0d3e\u0d26\u0d4d\u0d35\u0d3e\u0952\u0d2f\u0d41\u0d30\u0951\u0d1c\u0d3e\u0d2f\u0d24 \u0965 \u0d67\u0d6a \u0965", "iast": "ca\u0331ndram\u0101\u0331 mana\u032dso j\u0101\u0331ta\u015bcak\u1e63o\u0331\u1e25 s\u016bryo\u032d aj\u0101yata |\nmukh\u0101\u0331dindra\u032d\u015bc\u0101\u0331gni\u015bca\u032d pr\u0101\u0331\u1e47\u0101dv\u0101\u0331yura\u032dj\u0101yata || 14 ||"},
        draftTranslation: "The Moon was born from His mind; from His eyes the Sun was generated; from His mouth arose Indra and Agni (fire); and from His breath Vayu (vital air) was born.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 15,
        devanagariText: "\u0928\u093e\u092d\u094d\u092f\u093e\u0951 \u0906\u0938\u0940\u0926\u0952\u0928\u094d\u0924\u0930\u093f\u0951\u0915\u094d\u0937\u0902 \u0936\u0940\u0952\u0930\u094d\u0937\u094d\u0923\u094b \u0926\u094d\u092f\u094c\u0903 \u0938\u092e\u0951\u0935\u0930\u094d\u0924\u0924 \u0964\n\u092a\u0952\u0926\u094d\u092d\u094d\u092f\u093e\u0902 \u092d\u0942\u092e\u093f\u0952\u0930\u094d\u0926\u093f\u0936\u0903\u0952 \u0936\u094d\u0930\u094b\u0924\u094d\u0930\u093e\u0952\u0924\u094d\u0924\u0925\u093e\u0951 \u0932\u094b\u0952\u0915\u093e\u0901 \u0905\u0915\u0951\u0932\u094d\u092a\u092f\u0928\u094d \u0965 \u0967\u096b \u0965",
        iastText: "n\u0101bhy\u0101\u0951 \u0101s\u012bda\u0952ntari\u0951k\u1e63a\u1e41 \u015b\u012b\u0952r\u1e63\u1e47\u014d dyau\u1e25 sama\u0951vartata \u0964\npa\u0952dbhy\u0101\u1e41 bh\u016bmi\u0952rdi\u015ba\u1e25\u0952 \u015br\u014dtr\u0101\u0952ttath\u0101\u0951 l\u014d\u0952k\u0101m\u0310 aka\u0951lpayan \u0965 15 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c28\u0c3e\u0c2d\u0c4d\u0c2f\u0c3e\u0951 \u0c06\u0c38\u0c40\u0c26\u0952\u0c28\u0c4d\u0c24\u0c30\u0c3f\u0951\u0c15\u0c4d\u0c37\u0c02 \u0c36\u0c40\u0952\u0c30\u0c4d\u0c37\u0c4d\u0c23\u0c4b \u0c26\u0c4d\u0c2f\u0c4c\u0c03 \u0c38\u0c2e\u0951\u0c35\u0c30\u0c4d\u0c24\u0c24 \u0964\n\u0c2a\u0952\u0c26\u0c4d\u0c2d\u0c4d\u0c2f\u0c3e\u0c02 \u0c2d\u0c42\u0c2e\u0c3f\u0952\u0c30\u0c4d\u0c26\u0c3f\u0c36\u0c03\u0952 \u0c36\u0c4d\u0c30\u0c4b\u0c24\u0c4d\u0c30\u0c3e\u0952\u0c24\u0c4d\u0c24\u0c25\u0c3e\u0951 \u0c32\u0c4b\u0952\u0c15\u0c3e\u0c01 \u0c05\u0c15\u0951\u0c32\u0c4d\u0c2a\u0c2f\u0c28\u0c4d \u0965 \u0c67\u0c6b \u0965", "tamil": "\u0ba8\u0bbe\u0baa\u0bcd\u0baf\u0bbe\u0951 \u0b86\u0bb8\u0bc0\u0ba4\u0952\u0ba8\u0bcd\u0ba4\u0bb0\u0bbf\u0951\u0b95\u0bcd\u0bb7\u0bae\u0bcd \u0bb6\u0bc0\u0952\u0bb0\u0bcd\u0bb7\u0bcd\u0ba3\u0bcb \u0ba4\u0bcd\u0baf\u0bcc\u0b83 \u0bb8\u0bae\u0951\u0bb5\u0bb0\u0bcd\u0ba4\u0ba4 \u0964\n\u0baa\u0952\u0ba4\u0bcd\u0baa\u0bcd\u0baf\u0bbe\u0bae\u0bcd \u0baa\u0bc2\u0bae\u0bbf\u0952\u0bb0\u0bcd\u0ba4\u0bbf\u0bb6\u0b83\u0952 \u0bb6\u0bcd\u0bb0\u0bcb\u0ba4\u0bcd\u0bb0\u0bbe\u0952\u0ba4\u0bcd\u0ba4\u0ba4\u0bbe\u0951 \u0bb2\u0bcb\u0952\u0b95\u0bbe\u0901 \u0b85\u0b95\u0951\u0bb2\u0bcd\u0baa\u0baf\u0ba8\u0bcd \u0965 \u0be7\u0beb \u0965", "kannada": "\u0ca8\u0cbe\u0cad\u0ccd\u0caf\u0cbe\u0951 \u0c86\u0cb8\u0cc0\u0ca6\u0952\u0ca8\u0ccd\u0ca4\u0cb0\u0cbf\u0951\u0c95\u0ccd\u0cb7\u0c82 \u0cb6\u0cc0\u0952\u0cb0\u0ccd\u0cb7\u0ccd\u0ca3\u0ccb \u0ca6\u0ccd\u0caf\u0ccc\u0c83 \u0cb8\u0cae\u0951\u0cb5\u0cb0\u0ccd\u0ca4\u0ca4 \u0964\n\u0caa\u0952\u0ca6\u0ccd\u0cad\u0ccd\u0caf\u0cbe\u0c82 \u0cad\u0cc2\u0cae\u0cbf\u0952\u0cb0\u0ccd\u0ca6\u0cbf\u0cb6\u0c83\u0952 \u0cb6\u0ccd\u0cb0\u0ccb\u0ca4\u0ccd\u0cb0\u0cbe\u0952\u0ca4\u0ccd\u0ca4\u0ca5\u0cbe\u0951 \u0cb2\u0ccb\u0952\u0c95\u0cbe\u0c81 \u0c85\u0c95\u0951\u0cb2\u0ccd\u0caa\u0caf\u0ca8\u0ccd \u0965 \u0ce7\u0ceb \u0965", "malayalam": "\u0d28\u0d3e\u0d2d\u0d4d\u0d2f\u0d3e\u0951 \u0d06\u0d38\u0d40\u0d26\u0952\u0d28\u0d4d\u0d24\u0d30\u0d3f\u0951\u0d15\u0d4d\u0d37\u0d02 \u0d36\u0d40\u0952\u0d30\u0d4d\u0d37\u0d4d\u0d23\u0d4b \u0d26\u0d4d\u0d2f\u0d4c\u0d03 \u0d38\u0d2e\u0951\u0d35\u0d30\u0d4d\u0d24\u0d24 \u0964\n\u0d2a\u0952\u0d26\u0d4d\u0d2d\u0d4d\u0d2f\u0d3e\u0d02 \u0d2d\u0d42\u0d2e\u0d3f\u0952\u0d30\u0d4d\u0d26\u0d3f\u0d36\u0d03\u0952 \u0d36\u0d4d\u0d30\u0d4b\u0d24\u0d4d\u0d30\u0d3e\u0952\u0d24\u0d4d\u0d24\u0d25\u0d3e\u0951 \u0d32\u0d4b\u0952\u0d15\u0d3e\u0d01 \u0d05\u0d15\u0951\u0d32\u0d4d\u0d2a\u0d2f\u0d28\u0d4d \u0965 \u0d67\u0d6b \u0965", "iast": "n\u0101bhy\u0101\u032d \u0101s\u012bda\u0331ntari\u032dk\u1e63a\u1e43 \u015b\u012b\u0331r\u1e63\u1e47o dyau\u1e25 sama\u032dvartata |\npa\u0331dbhy\u0101\u1e43 bh\u016bmi\u0331rdi\u015ba\u0331\u1e25 \u015brotr\u0101\u0331ttath\u0101\u032d lo\u0331k\u0101~ aka\u032dlpayan || 15 ||"},
        draftTranslation: "From His navel the intermediate atmosphere arose; from His head the heavens evolved; from His feet the earth emerged, and the cardinal directions from His ears. In this manner they ordered all the cosmic realms.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 16,
        devanagariText: "\u092f\u0952\u091c\u094d\u091e\u0947\u0928\u0951 \u092f\u0952\u091c\u094d\u091e\u092e\u0951\u092f\u091c\u0928\u094d\u0924 \u0926\u0947\u0952\u0935\u093e\u0938\u094d\u0924\u093e\u0928\u093f\u0952 \u0927\u0930\u094d\u092e\u093e\u0951\u0923\u093f \u092a\u094d\u0930\u0925\u0952\u092e\u093e\u0928\u094d\u092f\u093e\u0951\u0938\u0928\u094d \u0964\n\u0924\u0947 \u0939\u0952 \u0928\u093e\u0915\u0902\u0951 \u092e\u0939\u093f\u0952\u092e\u093e\u0928\u0903\u0951 \u0938\u091a\u0928\u094d\u0924\u0952 \u092f\u0924\u094d\u0930\u0952 \u092a\u0942\u0930\u094d\u0935\u0947\u0951 \u0938\u093e\u0952\u0927\u094d\u092f\u093e\u0903 \u0938\u0928\u094d\u0924\u093f\u0951 \u0926\u0947\u0952\u0935\u093e\u0903 \u0965 \u0967\u096c \u0965",
        iastText: "ya\u0952j\u00f1\u0113na\u0951 ya\u0952j\u00f1ama\u0951yajanta d\u0113\u0952v\u0101st\u0101ni\u0952 dharm\u0101\u0951\u1e47i pratha\u0952m\u0101ny\u0101\u0951san \u0964\nt\u0113 ha\u0952 n\u0101ka\u1e41\u0951 mahi\u0952m\u0101na\u1e25\u0951 sacanta\u0952 yatra\u0952 p\u016brv\u0113\u0951 s\u0101\u0952dhy\u0101\u1e25 santi\u0951 d\u0113\u0952v\u0101\u1e25 \u0965 16 \u0965",
        meter: "Trishtubh",
        transliterations: {"telugu": "\u0c2f\u0952\u0c1c\u0c4d\u0c1e\u0c47\u0c28\u0951 \u0c2f\u0952\u0c1c\u0c4d\u0c1e\u0c2e\u0951\u0c2f\u0c1c\u0c28\u0c4d\u0c24 \u0c26\u0c47\u0952\u0c35\u0c3e\u0c38\u0c4d\u0c24\u0c3e\u0c28\u0c3f\u0952 \u0c27\u0c30\u0c4d\u0c2e\u0c3e\u0951\u0c23\u0c3f \u0c2a\u0c4d\u0c30\u0c25\u0952\u0c2e\u0c3e\u0c28\u0c4d\u0c2f\u0c3e\u0951\u0c38\u0c28\u0c4d \u0964\n\u0c24\u0c47 \u0c39\u0952 \u0c28\u0c3e\u0c15\u0c02\u0951 \u0c2e\u0c39\u0c3f\u0952\u0c2e\u0c3e\u0c28\u0c03\u0951 \u0c38\u0c1a\u0c28\u0c4d\u0c24\u0952 \u0c2f\u0c24\u0c4d\u0c30\u0952 \u0c2a\u0c42\u0c30\u0c4d\u0c35\u0c47\u0951 \u0c38\u0c3e\u0952\u0c27\u0c4d\u0c2f\u0c3e\u0c03 \u0c38\u0c28\u0c4d\u0c24\u0c3f\u0951 \u0c26\u0c47\u0952\u0c35\u0c3e\u0c03 \u0965 \u0c67\u0c6c \u0965", "tamil": "\u0baf\u0952\u0b9c\u0bcd\u0b9e\u0bc7\u0ba8\u0951 \u0baf\u0952\u0b9c\u0bcd\u0b9e\u0bae\u0951\u0baf\u0b9c\u0ba8\u0bcd\u0ba4 \u0ba4\u0bc7\u0952\u0bb5\u0bbe\u0bb8\u0bcd\u0ba4\u0bbe\u0ba8\u0bbf\u0952 \u0ba4\u0bb0\u0bcd\u0bae\u0bbe\u0951\u0ba3\u0bbf \u0baa\u0bcd\u0bb0\u0ba4\u0952\u0bae\u0bbe\u0ba8\u0bcd\u0baf\u0bbe\u0951\u0bb8\u0ba8\u0bcd \u0964\n\u0ba4\u0bc7 \u0bb9\u0952 \u0ba8\u0bbe\u0b95\u0bae\u0bcd\u0951 \u0bae\u0bb9\u0bbf\u0952\u0bae\u0bbe\u0ba8\u0b83\u0951 \u0bb8\u0b9a\u0ba8\u0bcd\u0ba4\u0952 \u0baf\u0ba4\u0bcd\u0bb0\u0952 \u0baa\u0bc2\u0bb0\u0bcd\u0bb5\u0bc7\u0951 \u0bb8\u0bbe\u0952\u0ba4\u0bcd\u0baf\u0bbe\u0b83 \u0bb8\u0ba8\u0bcd\u0ba4\u0bbf\u0951 \u0ba4\u0bc7\u0952\u0bb5\u0bbe\u0b83 \u0965 \u0be7\u0bec \u0965", "kannada": "\u0caf\u0952\u0c9c\u0ccd\u0c9e\u0cc7\u0ca8\u0951 \u0caf\u0952\u0c9c\u0ccd\u0c9e\u0cae\u0951\u0caf\u0c9c\u0ca8\u0ccd\u0ca4 \u0ca6\u0cc7\u0952\u0cb5\u0cbe\u0cb8\u0ccd\u0ca4\u0cbe\u0ca8\u0cbf\u0952 \u0ca7\u0cb0\u0ccd\u0cae\u0cbe\u0951\u0ca3\u0cbf \u0caa\u0ccd\u0cb0\u0ca5\u0952\u0cae\u0cbe\u0ca8\u0ccd\u0caf\u0cbe\u0951\u0cb8\u0ca8\u0ccd \u0964\n\u0ca4\u0cc7 \u0cb9\u0952 \u0ca8\u0cbe\u0c95\u0c82\u0951 \u0cae\u0cb9\u0cbf\u0952\u0cae\u0cbe\u0ca8\u0c83\u0951 \u0cb8\u0c9a\u0ca8\u0ccd\u0ca4\u0952 \u0caf\u0ca4\u0ccd\u0cb0\u0952 \u0caa\u0cc2\u0cb0\u0ccd\u0cb5\u0cc7\u0951 \u0cb8\u0cbe\u0952\u0ca7\u0ccd\u0caf\u0cbe\u0c83 \u0cb8\u0ca8\u0ccd\u0ca4\u0cbf\u0951 \u0ca6\u0cc7\u0952\u0cb5\u0cbe\u0c83 \u0965 \u0ce7\u0cec \u0965", "malayalam": "\u0d2f\u0952\u0d1c\u0d4d\u0d1e\u0d47\u0d28\u0951 \u0d2f\u0952\u0d1c\u0d4d\u0d1e\u0d2e\u0951\u0d2f\u0d1c\u0d28\u0d4d\u0d24 \u0d26\u0d47\u0952\u0d35\u0d3e\u0d38\u0d4d\u0d24\u0d3e\u0d28\u0d3f\u0952 \u0d27\u0d30\u0d4d\u0d2e\u0d3e\u0951\u0d23\u0d3f \u0d2a\u0d4d\u0d30\u0d25\u0952\u0d2e\u0d3e\u0d28\u0d4d\u0d2f\u0d3e\u0951\u0d38\u0d28\u0d4d \u0964\n\u0d24\u0d47 \u0d39\u0952 \u0d28\u0d3e\u0d15\u0d02\u0951 \u0d2e\u0d39\u0d3f\u0952\u0d2e\u0d3e\u0d28\u0d03\u0951 \u0d38\u0d1a\u0d28\u0d4d\u0d24\u0952 \u0d2f\u0d24\u0d4d\u0d30\u0952 \u0d2a\u0d42\u0d30\u0d4d\u0d35\u0d47\u0951 \u0d38\u0d3e\u0952\u0d27\u0d4d\u0d2f\u0d3e\u0d03 \u0d38\u0d28\u0d4d\u0d24\u0d3f\u0951 \u0d26\u0d47\u0952\u0d35\u0d3e\u0d03 \u0965 \u0d67\u0d6c \u0965", "iast": "ya\u0331j\u00f1ena\u032d ya\u0331j\u00f1ama\u032dyajanta de\u0331v\u0101st\u0101ni\u0331 dharm\u0101\u032d\u1e47i pratha\u0331m\u0101ny\u0101\u032dsan |\nte ha\u0331 n\u0101ka\u032d\u1e43 mahi\u0331m\u0101na\u032d\u1e25 sacanta\u0331 yatra\u0331 p\u016brv\u1e19 s\u0101\u0331dhy\u0101\u1e25 santi\u032d de\u0331v\u0101\u1e25 || 16 ||"},
        draftTranslation: "With sacrifice the deities offered worship to the Supreme Sacrifice (Purusha). These became the primordial cosmic ordinances (Dharmas). Those exalted spiritual beings attain the highest celestial realm where the ancient Sadhyas and gods abide.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
    ],
  ),
  Scripture(
    id: 17,
    contentId: "VEDA-TXT-00015",
    canonicalTitle: "Durga Suktam",
    devanagariTitle: "\u0926\u0941\u0930\u094d\u0917\u093e\u0938\u0942\u0915\u094d\u0924\u092e\u094d",
    category: "Suktam",
    deity: "Goddess Durga",
    composer: "Sage Jatavedas",
    rishi: "Traditional Vedic Sage",
    chandas: "Trishtubh",
    devata: "Goddess Durga",
    sourceScripture: "Taittiriya Aranyaka 10.1-2 (Mahanarayana Upanishad 2)",
    traditionalUsage: "Deliverance from perils, removal of sorrow, spiritual protection",
    verseCount: 7,
    verses: [
      Verse(
        verseNumber: 1,
        devanagariText: "\u091c\u093e\u0952\u0924\u0935\u0947\u0951\u0926\u0938\u0947 \u0938\u0941\u0928\u0935\u093e\u092e\u0952 \u0938\u094b\u092e\u0951\u092e\u0930\u093e\u0924\u0940\u092f\u0952\u0924\u094b \u0928\u093f\u0926\u0951\u0939\u093e\u0924\u093f\u0952 \u0935\u0947\u0926\u0903\u0951 \u0964\n\u0938 \u0928\u0903\u0951 \u092a\u0930\u094d\u0937\u0952\u0926\u0924\u093f\u0951 \u0926\u0941\u0952\u0930\u094d\u0917\u093e\u0923\u093f\u0952 \u0935\u093f\u0936\u094d\u0935\u093e\u0951 \u0928\u093e\u0952\u0935\u0947\u0935\u0952 \u0938\u093f\u0928\u094d\u0927\u0941\u0902\u0951 \u0926\u0941\u0930\u093f\u0952\u0924\u093e\u0924\u094d\u092f\u0952\u0917\u094d\u0928\u093f\u0903 \u0965 \u0967 \u0965",
        iastText: "j\u0101\u0952tav\u0113\u0951das\u0113 sunav\u0101ma\u0952 s\u014dma\u0951mar\u0101t\u012bya\u0952t\u014d nida\u0951h\u0101ti\u0952 v\u0113da\u1e25\u0951 \u0964\nsa na\u1e25\u0951 par\u1e63a\u0952dati\u0951 du\u0952rg\u0101\u1e47i\u0952 vi\u015bv\u0101\u0951 n\u0101\u0952v\u0113va\u0952 sindhu\u1e41\u0951 duri\u0952t\u0101tya\u0952gni\u1e25 \u0965 1 \u0965",
        meter: "Trishtubh",
        transliterations: {"telugu": "\u0c1c\u0c3e\u0952\u0c24\u0c35\u0c47\u0951\u0c26\u0c38\u0c47 \u0c38\u0c41\u0c28\u0c35\u0c3e\u0c2e\u0952 \u0c38\u0c4b\u0c2e\u0951\u0c2e\u0c30\u0c3e\u0c24\u0c40\u0c2f\u0952\u0c24\u0c4b \u0c28\u0c3f\u0c26\u0951\u0c39\u0c3e\u0c24\u0c3f\u0952 \u0c35\u0c47\u0c26\u0c03\u0951 \u0964\n\u0c38 \u0c28\u0c03\u0951 \u0c2a\u0c30\u0c4d\u0c37\u0952\u0c26\u0c24\u0c3f\u0951 \u0c26\u0c41\u0952\u0c30\u0c4d\u0c17\u0c3e\u0c23\u0c3f\u0952 \u0c35\u0c3f\u0c36\u0c4d\u0c35\u0c3e\u0951 \u0c28\u0c3e\u0952\u0c35\u0c47\u0c35\u0952 \u0c38\u0c3f\u0c28\u0c4d\u0c27\u0c41\u0c02\u0951 \u0c26\u0c41\u0c30\u0c3f\u0952\u0c24\u0c3e\u0c24\u0c4d\u0c2f\u0952\u0c17\u0c4d\u0c28\u0c3f\u0c03 \u0965 \u0c67 \u0965", "tamil": "\u0b9c\u0bbe\u0952\u0ba4\u0bb5\u0bc7\u0951\u0ba4\u0bb8\u0bc7 \u0bb8\u0bc1\u0ba8\u0bb5\u0bbe\u0bae\u0952 \u0bb8\u0bcb\u0bae\u0951\u0bae\u0bb0\u0bbe\u0ba4\u0bc0\u0baf\u0952\u0ba4\u0bcb \u0ba8\u0bbf\u0ba4\u0951\u0bb9\u0bbe\u0ba4\u0bbf\u0952 \u0bb5\u0bc7\u0ba4\u0b83\u0951 \u0964\n\u0bb8 \u0ba8\u0b83\u0951 \u0baa\u0bb0\u0bcd\u0bb7\u0952\u0ba4\u0ba4\u0bbf\u0951 \u0ba4\u0bc1\u0952\u0bb0\u0bcd\u0b95\u0bbe\u0ba3\u0bbf\u0952 \u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0bbe\u0951 \u0ba8\u0bbe\u0952\u0bb5\u0bc7\u0bb5\u0952 \u0bb8\u0bbf\u0ba8\u0bcd\u0ba4\u0bc1\u0bae\u0bcd\u0951 \u0ba4\u0bc1\u0bb0\u0bbf\u0952\u0ba4\u0bbe\u0ba4\u0bcd\u0baf\u0952\u0b95\u0bcd\u0ba8\u0bbf\u0b83 \u0965 \u0be7 \u0965", "kannada": "\u0c9c\u0cbe\u0952\u0ca4\u0cb5\u0cc7\u0951\u0ca6\u0cb8\u0cc7 \u0cb8\u0cc1\u0ca8\u0cb5\u0cbe\u0cae\u0952 \u0cb8\u0ccb\u0cae\u0951\u0cae\u0cb0\u0cbe\u0ca4\u0cc0\u0caf\u0952\u0ca4\u0ccb \u0ca8\u0cbf\u0ca6\u0951\u0cb9\u0cbe\u0ca4\u0cbf\u0952 \u0cb5\u0cc7\u0ca6\u0c83\u0951 \u0964\n\u0cb8 \u0ca8\u0c83\u0951 \u0caa\u0cb0\u0ccd\u0cb7\u0952\u0ca6\u0ca4\u0cbf\u0951 \u0ca6\u0cc1\u0952\u0cb0\u0ccd\u0c97\u0cbe\u0ca3\u0cbf\u0952 \u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0cbe\u0951 \u0ca8\u0cbe\u0952\u0cb5\u0cc7\u0cb5\u0952 \u0cb8\u0cbf\u0ca8\u0ccd\u0ca7\u0cc1\u0c82\u0951 \u0ca6\u0cc1\u0cb0\u0cbf\u0952\u0ca4\u0cbe\u0ca4\u0ccd\u0caf\u0952\u0c97\u0ccd\u0ca8\u0cbf\u0c83 \u0965 \u0ce7 \u0965", "malayalam": "\u0d1c\u0d3e\u0952\u0d24\u0d35\u0d47\u0951\u0d26\u0d38\u0d47 \u0d38\u0d41\u0d28\u0d35\u0d3e\u0d2e\u0952 \u0d38\u0d4b\u0d2e\u0951\u0d2e\u0d30\u0d3e\u0d24\u0d40\u0d2f\u0952\u0d24\u0d4b \u0d28\u0d3f\u0d26\u0951\u0d39\u0d3e\u0d24\u0d3f\u0952 \u0d35\u0d47\u0d26\u0d03\u0951 \u0964\n\u0d38 \u0d28\u0d03\u0951 \u0d2a\u0d30\u0d4d\u0d37\u0952\u0d26\u0d24\u0d3f\u0951 \u0d26\u0d41\u0952\u0d30\u0d4d\u0d17\u0d3e\u0d23\u0d3f\u0952 \u0d35\u0d3f\u0d36\u0d4d\u0d35\u0d3e\u0951 \u0d28\u0d3e\u0952\u0d35\u0d47\u0d35\u0952 \u0d38\u0d3f\u0d28\u0d4d\u0d27\u0d41\u0d02\u0951 \u0d26\u0d41\u0d30\u0d3f\u0952\u0d24\u0d3e\u0d24\u0d4d\u0d2f\u0952\u0d17\u0d4d\u0d28\u0d3f\u0d03 \u0965 \u0d67 \u0965", "iast": "j\u0101\u0331tav\u1e19dase sunav\u0101ma\u0331 soma\u032dmar\u0101t\u012bya\u0331to nida\u032dh\u0101ti\u0331 veda\u032d\u1e25 |\nsa na\u032d\u1e25 par\u1e63a\u0331dati\u032d du\u0331rg\u0101\u1e47i\u0331 vi\u015bv\u0101\u032d n\u0101\u0331veva\u0331 sindh\u1e77\u1e43 duri\u0331t\u0101tya\u0331gni\u1e25 || 1 ||"},
        draftTranslation: "We press the sacred Soma juice unto Jatavedas (Agni, Knower of all beings). May He consume the enmity of our tormentors. May Agni carry us safely across all formidable perils and difficulties, as a ship conveys passengers across the roaring ocean!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 2,
        devanagariText: "\u0924\u093e\u092e\u0952\u0917\u094d\u0928\u093f\u0935\u0951\u0930\u094d\u0923\u093e\u0902\u0952 \u0924\u092a\u0951\u0938\u093e \u091c\u094d\u0935\u0932\u0952\u0928\u094d\u0924\u0940\u0902 \u0935\u0948\u0951\u0930\u094b\u091a\u0952\u0928\u0940\u0902 \u0915\u0951\u0930\u094d\u092e\u092b\u0952\u0932\u0947\u0937\u0941\u0952 \u091c\u0941\u0937\u094d\u091f\u093e\u092e\u094d \u0964\n\u0926\u0941\u0952\u0930\u094d\u0917\u093e\u0902 \u0926\u0947\u0952\u0935\u0940\u0902 \u0936\u0930\u0951\u0923\u092e\u0952\u0939\u0902 \u092a\u094d\u0930\u092a\u0951\u0926\u094d\u092f\u0947 \u0938\u0941\u0952\u0924\u0930\u0951\u0938\u093f \u0924\u0930\u0938\u0947\u0952 \u0928\u092e\u0903\u0951 \u0965 \u0968 \u0965",
        iastText: "t\u0101ma\u0952gniva\u0951r\u1e47\u0101\u1e41\u0952 tapa\u0951s\u0101 jvala\u0952nt\u012b\u1e41 vai\u0951r\u014dca\u0952n\u012b\u1e41 ka\u0951rmapha\u0952l\u0113\u1e63u\u0952 ju\u1e63\u1e6d\u0101m \u0964\ndu\u0952rg\u0101\u1e41 d\u0113\u0952v\u012b\u1e41 \u015bara\u0951\u1e47ama\u0952ha\u1e41 prapa\u0951dy\u0113 su\u0952tara\u0951si taras\u0113\u0952 nama\u1e25\u0951 \u0965 2 \u0965",
        meter: "Trishtubh",
        transliterations: {"telugu": "\u0c24\u0c3e\u0c2e\u0952\u0c17\u0c4d\u0c28\u0c3f\u0c35\u0951\u0c30\u0c4d\u0c23\u0c3e\u0c02\u0952 \u0c24\u0c2a\u0951\u0c38\u0c3e \u0c1c\u0c4d\u0c35\u0c32\u0952\u0c28\u0c4d\u0c24\u0c40\u0c02 \u0c35\u0c48\u0951\u0c30\u0c4b\u0c1a\u0952\u0c28\u0c40\u0c02 \u0c15\u0951\u0c30\u0c4d\u0c2e\u0c2b\u0952\u0c32\u0c47\u0c37\u0c41\u0952 \u0c1c\u0c41\u0c37\u0c4d\u0c1f\u0c3e\u0c2e\u0c4d \u0964\n\u0c26\u0c41\u0952\u0c30\u0c4d\u0c17\u0c3e\u0c02 \u0c26\u0c47\u0952\u0c35\u0c40\u0c02 \u0c36\u0c30\u0951\u0c23\u0c2e\u0952\u0c39\u0c02 \u0c2a\u0c4d\u0c30\u0c2a\u0951\u0c26\u0c4d\u0c2f\u0c47 \u0c38\u0c41\u0952\u0c24\u0c30\u0951\u0c38\u0c3f \u0c24\u0c30\u0c38\u0c47\u0952 \u0c28\u0c2e\u0c03\u0951 \u0965 \u0c68 \u0965", "tamil": "\u0ba4\u0bbe\u0bae\u0952\u0b95\u0bcd\u0ba8\u0bbf\u0bb5\u0951\u0bb0\u0bcd\u0ba3\u0bbe\u0bae\u0bcd\u0952 \u0ba4\u0baa\u0951\u0bb8\u0bbe \u0b9c\u0bcd\u0bb5\u0bb2\u0952\u0ba8\u0bcd\u0ba4\u0bc0\u0bae\u0bcd \u0bb5\u0bc8\u0951\u0bb0\u0bcb\u0b9a\u0952\u0ba8\u0bc0\u0bae\u0bcd \u0b95\u0951\u0bb0\u0bcd\u0bae\u0baa\u0952\u0bb2\u0bc7\u0bb7\u0bc1\u0952 \u0b9c\u0bc1\u0bb7\u0bcd\u0b9f\u0bbe\u0bae\u0bcd \u0964\n\u0ba4\u0bc1\u0952\u0bb0\u0bcd\u0b95\u0bbe\u0bae\u0bcd \u0ba4\u0bc7\u0952\u0bb5\u0bc0\u0bae\u0bcd \u0bb6\u0bb0\u0951\u0ba3\u0bae\u0952\u0bb9\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0951\u0ba4\u0bcd\u0baf\u0bc7 \u0bb8\u0bc1\u0952\u0ba4\u0bb0\u0951\u0bb8\u0bbf \u0ba4\u0bb0\u0bb8\u0bc7\u0952 \u0ba8\u0bae\u0b83\u0951 \u0965 \u0be8 \u0965", "kannada": "\u0ca4\u0cbe\u0cae\u0952\u0c97\u0ccd\u0ca8\u0cbf\u0cb5\u0951\u0cb0\u0ccd\u0ca3\u0cbe\u0c82\u0952 \u0ca4\u0caa\u0951\u0cb8\u0cbe \u0c9c\u0ccd\u0cb5\u0cb2\u0952\u0ca8\u0ccd\u0ca4\u0cc0\u0c82 \u0cb5\u0cc8\u0951\u0cb0\u0ccb\u0c9a\u0952\u0ca8\u0cc0\u0c82 \u0c95\u0951\u0cb0\u0ccd\u0cae\u0cab\u0952\u0cb2\u0cc7\u0cb7\u0cc1\u0952 \u0c9c\u0cc1\u0cb7\u0ccd\u0c9f\u0cbe\u0cae\u0ccd \u0964\n\u0ca6\u0cc1\u0952\u0cb0\u0ccd\u0c97\u0cbe\u0c82 \u0ca6\u0cc7\u0952\u0cb5\u0cc0\u0c82 \u0cb6\u0cb0\u0951\u0ca3\u0cae\u0952\u0cb9\u0c82 \u0caa\u0ccd\u0cb0\u0caa\u0951\u0ca6\u0ccd\u0caf\u0cc7 \u0cb8\u0cc1\u0952\u0ca4\u0cb0\u0951\u0cb8\u0cbf \u0ca4\u0cb0\u0cb8\u0cc7\u0952 \u0ca8\u0cae\u0c83\u0951 \u0965 \u0ce8 \u0965", "malayalam": "\u0d24\u0d3e\u0d2e\u0952\u0d17\u0d4d\u0d28\u0d3f\u0d35\u0951\u0d30\u0d4d\u0d23\u0d3e\u0d02\u0952 \u0d24\u0d2a\u0951\u0d38\u0d3e \u0d1c\u0d4d\u0d35\u0d32\u0952\u0d28\u0d4d\u0d24\u0d40\u0d02 \u0d35\u0d48\u0951\u0d30\u0d4b\u0d1a\u0952\u0d28\u0d40\u0d02 \u0d15\u0951\u0d30\u0d4d\u0d2e\u0d2b\u0952\u0d32\u0d47\u0d37\u0d41\u0952 \u0d1c\u0d41\u0d37\u0d4d\u0d1f\u0d3e\u0d2e\u0d4d \u0964\n\u0d26\u0d41\u0952\u0d30\u0d4d\u0d17\u0d3e\u0d02 \u0d26\u0d47\u0952\u0d35\u0d40\u0d02 \u0d36\u0d30\u0951\u0d23\u0d2e\u0952\u0d39\u0d02 \u0d2a\u0d4d\u0d30\u0d2a\u0951\u0d26\u0d4d\u0d2f\u0d47 \u0d38\u0d41\u0952\u0d24\u0d30\u0951\u0d38\u0d3f \u0d24\u0d30\u0d38\u0d47\u0952 \u0d28\u0d2e\u0d03\u0951 \u0965 \u0d68 \u0965", "iast": "t\u0101ma\u0331gniva\u032dr\u1e47\u0101\u0331\u1e43 tapa\u032ds\u0101 jvala\u0331nt\u012b\u1e43 vai\u032droca\u0331n\u012b\u1e43 ka\u032drmapha\u0331le\u1e63u\u0331 ju\u1e63\u1e6d\u0101m |\ndu\u0331rg\u0101\u1e43 de\u0331v\u012b\u1e43 \u015bara\u032d\u1e47ama\u0331ha\u1e43 prapa\u032ddye su\u0331tara\u032dsi tarase\u0331 nama\u032d\u1e25 || 2 ||"},
        draftTranslation: "Unto Her who shines with fiery luster, burning with ascetic radiance, daughter of the Divine Light (Vairochani), delighted in the righteous fruits of works \u2014 unto that Goddess Durga I take refuge! O Deliverer supreme across the ocean of delusion, salutations unto Your swift rescuing power!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 3,
        devanagariText: "\u0905\u0917\u094d\u0928\u0947\u0952 \u0924\u094d\u0935\u0902 \u092a\u093e\u0951\u0930\u092f\u093e\u0952 \u0928\u0935\u094d\u092f\u094b\u0951 \u0905\u0952\u0938\u094d\u092e\u093e\u0928\u094d\u0938\u094d\u0935\u0952\u0938\u094d\u0924\u093f\u092d\u093f\u0952\u0930\u0924\u093f\u0951 \u0926\u0941\u0952\u0930\u094d\u0917\u093e\u0923\u093f\u0952 \u0935\u093f\u0936\u094d\u0935\u093e\u0951 \u0964\n\u092a\u0942\u0936\u094d\u091a\u0951 \u092a\u0943\u0952\u0925\u094d\u0935\u0940 \u092c\u0951\u0939\u0941\u0952\u0932\u093e \u0928\u0951 \u0909\u0952\u0930\u094d\u0935\u0940 \u092d\u0935\u093e\u0951 \u0924\u094b\u0952\u0915\u093e\u092f\u0952 \u0924\u0928\u0951\u092f\u093e\u092f\u0952 \u0936\u0902 \u092f\u094b\u0903 \u0965 \u0969 \u0965",
        iastText: "agn\u0113\u0952 tva\u1e41 p\u0101\u0951ray\u0101\u0952 navy\u014d\u0951 a\u0952sm\u0101nswa\u0952stibhi\u0952rati\u0951 du\u0952rg\u0101\u1e47i\u0952 vi\u015bv\u0101\u0951 \u0964\np\u016b\u015bca\u0951 p\u1e5b\u0952thv\u012b ba\u0951hu\u0952l\u0101 na\u0951 u\u0952rv\u012b bhav\u0101\u0951 t\u014d\u0952k\u0101ya\u0952 tana\u0951y\u0101ya\u0952 \u015ba\u1e41 y\u014d\u1e25 \u0965 3 \u0965",
        meter: "Trishtubh",
        transliterations: {"telugu": "\u0c05\u0c17\u0c4d\u0c28\u0c47\u0952 \u0c24\u0c4d\u0c35\u0c02 \u0c2a\u0c3e\u0951\u0c30\u0c2f\u0c3e\u0952 \u0c28\u0c35\u0c4d\u0c2f\u0c4b\u0951 \u0c05\u0952\u0c38\u0c4d\u0c2e\u0c3e\u0c28\u0c4d\u0c38\u0c4d\u0c35\u0952\u0c38\u0c4d\u0c24\u0c3f\u0c2d\u0c3f\u0952\u0c30\u0c24\u0c3f\u0951 \u0c26\u0c41\u0952\u0c30\u0c4d\u0c17\u0c3e\u0c23\u0c3f\u0952 \u0c35\u0c3f\u0c36\u0c4d\u0c35\u0c3e\u0951 \u0964\n\u0c2a\u0c42\u0c36\u0c4d\u0c1a\u0951 \u0c2a\u0c43\u0952\u0c25\u0c4d\u0c35\u0c40 \u0c2c\u0951\u0c39\u0c41\u0952\u0c32\u0c3e \u0c28\u0951 \u0c09\u0952\u0c30\u0c4d\u0c35\u0c40 \u0c2d\u0c35\u0c3e\u0951 \u0c24\u0c4b\u0952\u0c15\u0c3e\u0c2f\u0952 \u0c24\u0c28\u0951\u0c2f\u0c3e\u0c2f\u0952 \u0c36\u0c02 \u0c2f\u0c4b\u0c03 \u0965 \u0c69 \u0965", "tamil": "\u0b85\u0b95\u0bcd\u0ba8\u0bc7\u0952 \u0ba4\u0bcd\u0bb5\u0bae\u0bcd \u0baa\u0bbe\u0951\u0bb0\u0baf\u0bbe\u0952 \u0ba8\u0bb5\u0bcd\u0baf\u0bcb\u0951 \u0b85\u0952\u0bb8\u0bcd\u0bae\u0bbe\u0ba8\u0bcd\u0bb8\u0bcd\u0bb5\u0952\u0bb8\u0bcd\u0ba4\u0bbf\u0baa\u0bbf\u0952\u0bb0\u0ba4\u0bbf\u0951 \u0ba4\u0bc1\u0952\u0bb0\u0bcd\u0b95\u0bbe\u0ba3\u0bbf\u0952 \u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0bbe\u0951 \u0964\n\u0baa\u0bc2\u0bb6\u0bcd\u0b9a\u0951 \u0baa\u0bcd\u0bb0\u0bc1'\u0952\u0ba4\u0bcd\u0bb5\u0bc0 \u0baa\u0951\u0bb9\u0bc1\u0952\u0bb2\u0bbe \u0ba8\u0951 \u0b89\u0952\u0bb0\u0bcd\u0bb5\u0bc0 \u0baa\u0bb5\u0bbe\u0951 \u0ba4\u0bcb\u0952\u0b95\u0bbe\u0baf\u0952 \u0ba4\u0ba8\u0951\u0baf\u0bbe\u0baf\u0952 \u0bb6\u0bae\u0bcd \u0baf\u0bcb\u0b83 \u0965 \u0be9 \u0965", "kannada": "\u0c85\u0c97\u0ccd\u0ca8\u0cc7\u0952 \u0ca4\u0ccd\u0cb5\u0c82 \u0caa\u0cbe\u0951\u0cb0\u0caf\u0cbe\u0952 \u0ca8\u0cb5\u0ccd\u0caf\u0ccb\u0951 \u0c85\u0952\u0cb8\u0ccd\u0cae\u0cbe\u0ca8\u0ccd\u0cb8\u0ccd\u0cb5\u0952\u0cb8\u0ccd\u0ca4\u0cbf\u0cad\u0cbf\u0952\u0cb0\u0ca4\u0cbf\u0951 \u0ca6\u0cc1\u0952\u0cb0\u0ccd\u0c97\u0cbe\u0ca3\u0cbf\u0952 \u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0cbe\u0951 \u0964\n\u0caa\u0cc2\u0cb6\u0ccd\u0c9a\u0951 \u0caa\u0cc3\u0952\u0ca5\u0ccd\u0cb5\u0cc0 \u0cac\u0951\u0cb9\u0cc1\u0952\u0cb2\u0cbe \u0ca8\u0951 \u0c89\u0952\u0cb0\u0ccd\u0cb5\u0cc0 \u0cad\u0cb5\u0cbe\u0951 \u0ca4\u0ccb\u0952\u0c95\u0cbe\u0caf\u0952 \u0ca4\u0ca8\u0951\u0caf\u0cbe\u0caf\u0952 \u0cb6\u0c82 \u0caf\u0ccb\u0c83 \u0965 \u0ce9 \u0965", "malayalam": "\u0d05\u0d17\u0d4d\u0d28\u0d47\u0952 \u0d24\u0d4d\u0d35\u0d02 \u0d2a\u0d3e\u0951\u0d30\u0d2f\u0d3e\u0952 \u0d28\u0d35\u0d4d\u0d2f\u0d4b\u0951 \u0d05\u0952\u0d38\u0d4d\u0d2e\u0d3e\u0d28\u0d4d\u0d38\u0d4d\u0d35\u0952\u0d38\u0d4d\u0d24\u0d3f\u0d2d\u0d3f\u0952\u0d30\u0d24\u0d3f\u0951 \u0d26\u0d41\u0952\u0d30\u0d4d\u0d17\u0d3e\u0d23\u0d3f\u0952 \u0d35\u0d3f\u0d36\u0d4d\u0d35\u0d3e\u0951 \u0964\n\u0d2a\u0d42\u0d36\u0d4d\u0d1a\u0951 \u0d2a\u0d43\u0952\u0d25\u0d4d\u0d35\u0d40 \u0d2c\u0951\u0d39\u0d41\u0952\u0d32\u0d3e \u0d28\u0951 \u0d09\u0952\u0d30\u0d4d\u0d35\u0d40 \u0d2d\u0d35\u0d3e\u0951 \u0d24\u0d4b\u0952\u0d15\u0d3e\u0d2f\u0952 \u0d24\u0d28\u0951\u0d2f\u0d3e\u0d2f\u0952 \u0d36\u0d02 \u0d2f\u0d4b\u0d03 \u0965 \u0d69 \u0965", "iast": "agne\u0331 tva\u1e43 p\u0101\u032dray\u0101\u0331 navyo\u032d a\u0331sm\u0101nsva\u0331stibhi\u0331rati\u032d du\u0331rg\u0101\u1e47i\u0331 vi\u015bv\u0101\u032d |\np\u016b\u015bca\u032d p\u1e5b\u0331thv\u012b ba\u032dhu\u0331l\u0101 na\u032d u\u0331rv\u012b bhav\u0101\u032d to\u0331k\u0101ya\u0331 tana\u032dy\u0101ya\u0331 \u015ba\u1e43 yo\u1e25 || 3 ||"},
        draftTranslation: "O Agni, ever youthful and praiseworthy! Carry us across all afflictions and dangers with auspicious blessings. May our city and earth be wide and bountiful; bestow supreme welfare, peace, and protection upon our children and future generations!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 4,
        devanagariText: "\u0935\u093f\u0936\u094d\u0935\u093e\u0951\u0928\u093f \u0928\u094b \u0926\u0941\u0952\u0930\u094d\u0917\u0939\u093e\u0951 \u091c\u093e\u0924\u0935\u0947\u0926\u0903\u0952 \u0938\u093f\u0928\u094d\u0927\u0941\u0902\u0952 \u0928 \u0928\u093e\u0952\u0935\u093e \u0926\u0941\u0951\u0930\u093f\u0952\u0924\u093e\u093d\u0924\u093f\u0951\u092a\u0930\u094d\u0937\u093f \u0964\n\u0905\u0917\u094d\u0928\u0947\u0951 \u0905\u0924\u094d\u0930\u093f\u0935\u0952\u0928\u094d\u092e\u0928\u0951\u0938\u093e \u0917\u0943\u0923\u093e\u0952\u0928\u094b\u093d\u0938\u094d\u092e\u093e\u0915\u0902\u0951 \u092c\u094b\u0927\u094d\u092f\u0935\u093f\u0952\u0924\u093e \u0924\u0952\u0928\u0942\u0928\u093e\u092e\u094d \u0965 \u096a \u0965",
        iastText: "vi\u015bv\u0101\u0951ni n\u014d du\u0952rgah\u0101\u0951 j\u0101tav\u0113da\u1e25\u0952 sindhu\u1e41\u0952 na n\u0101\u0952v\u0101 du\u0951ri\u0952t\u0101'ti\u0951par\u1e63i \u0964\nagn\u0113\u0951 atrizva\u0952nmana\u0951s\u0101 g\u1e5b\u1e47\u0101\u0952n\u014d'sm\u0101ka\u1e41\u0951 b\u014ddhyavi\u0952t\u0101 ta\u0952n\u016bn\u0101m \u0965 4 \u0965",
        meter: "Trishtubh",
        transliterations: {"telugu": "\u0c35\u0c3f\u0c36\u0c4d\u0c35\u0c3e\u0951\u0c28\u0c3f \u0c28\u0c4b \u0c26\u0c41\u0952\u0c30\u0c4d\u0c17\u0c39\u0c3e\u0951 \u0c1c\u0c3e\u0c24\u0c35\u0c47\u0c26\u0c03\u0952 \u0c38\u0c3f\u0c28\u0c4d\u0c27\u0c41\u0c02\u0952 \u0c28 \u0c28\u0c3e\u0952\u0c35\u0c3e \u0c26\u0c41\u0951\u0c30\u0c3f\u0952\u0c24\u0c3e\u0c3d\u0c24\u0c3f\u0951\u0c2a\u0c30\u0c4d\u0c37\u0c3f \u0964\n\u0c05\u0c17\u0c4d\u0c28\u0c47\u0951 \u0c05\u0c24\u0c4d\u0c30\u0c3f\u0c35\u0952\u0c28\u0c4d\u0c2e\u0c28\u0951\u0c38\u0c3e \u0c17\u0c43\u0c23\u0c3e\u0952\u0c28\u0c4b\u0c3d\u0c38\u0c4d\u0c2e\u0c3e\u0c15\u0c02\u0951 \u0c2c\u0c4b\u0c27\u0c4d\u0c2f\u0c35\u0c3f\u0952\u0c24\u0c3e \u0c24\u0952\u0c28\u0c42\u0c28\u0c3e\u0c2e\u0c4d \u0965 \u0c6a \u0965", "tamil": "\u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0bbe\u0951\u0ba8\u0bbf \u0ba8\u0bcb \u0ba4\u0bc1\u0952\u0bb0\u0bcd\u0b95\u0bb9\u0bbe\u0951 \u0b9c\u0bbe\u0ba4\u0bb5\u0bc7\u0ba4\u0b83\u0952 \u0bb8\u0bbf\u0ba8\u0bcd\u0ba4\u0bc1\u0bae\u0bcd\u0952 \u0ba8 \u0ba8\u0bbe\u0952\u0bb5\u0bbe \u0ba4\u0bc1\u0951\u0bb0\u0bbf\u0952\u0ba4\u0bbe\u093d\u0ba4\u0bbf\u0951\u0baa\u0bb0\u0bcd\u0bb7\u0bbf \u0964\n\u0b85\u0b95\u0bcd\u0ba8\u0bc7\u0951 \u0b85\u0ba4\u0bcd\u0bb0\u0bbf\u0bb5\u0952\u0ba8\u0bcd\u0bae\u0ba8\u0951\u0bb8\u0bbe \u0b95\u0bcd\u0bb0\u0bc1'\u0ba3\u0bbe\u0952\u0ba8\u0bcb\u093d\u0bb8\u0bcd\u0bae\u0bbe\u0b95\u0bae\u0bcd\u0951 \u0baa\u0bcb\u0ba4\u0bcd\u0baf\u0bb5\u0bbf\u0952\u0ba4\u0bbe \u0ba4\u0952\u0ba8\u0bc2\u0ba8\u0bbe\u0bae\u0bcd \u0965 \u0bea \u0965", "kannada": "\u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0cbe\u0951\u0ca8\u0cbf \u0ca8\u0ccb \u0ca6\u0cc1\u0952\u0cb0\u0ccd\u0c97\u0cb9\u0cbe\u0951 \u0c9c\u0cbe\u0ca4\u0cb5\u0cc7\u0ca6\u0c83\u0952 \u0cb8\u0cbf\u0ca8\u0ccd\u0ca7\u0cc1\u0c82\u0952 \u0ca8 \u0ca8\u0cbe\u0952\u0cb5\u0cbe \u0ca6\u0cc1\u0951\u0cb0\u0cbf\u0952\u0ca4\u0cbe\u0cbd\u0ca4\u0cbf\u0951\u0caa\u0cb0\u0ccd\u0cb7\u0cbf \u0964\n\u0c85\u0c97\u0ccd\u0ca8\u0cc7\u0951 \u0c85\u0ca4\u0ccd\u0cb0\u0cbf\u0cb5\u0952\u0ca8\u0ccd\u0cae\u0ca8\u0951\u0cb8\u0cbe \u0c97\u0cc3\u0ca3\u0cbe\u0952\u0ca8\u0ccb\u0cbd\u0cb8\u0ccd\u0cae\u0cbe\u0c95\u0c82\u0951 \u0cac\u0ccb\u0ca7\u0ccd\u0caf\u0cb5\u0cbf\u0952\u0ca4\u0cbe \u0ca4\u0952\u0ca8\u0cc2\u0ca8\u0cbe\u0cae\u0ccd \u0965 \u0cea \u0965", "malayalam": "\u0d35\u0d3f\u0d36\u0d4d\u0d35\u0d3e\u0951\u0d28\u0d3f \u0d28\u0d4b \u0d26\u0d41\u0952\u0d30\u0d4d\u0d17\u0d39\u0d3e\u0951 \u0d1c\u0d3e\u0d24\u0d35\u0d47\u0d26\u0d03\u0952 \u0d38\u0d3f\u0d28\u0d4d\u0d27\u0d41\u0d02\u0952 \u0d28 \u0d28\u0d3e\u0952\u0d35\u0d3e \u0d26\u0d41\u0951\u0d30\u0d3f\u0952\u0d24\u0d3e\u0d3d\u0d24\u0d3f\u0951\u0d2a\u0d30\u0d4d\u0d37\u0d3f \u0964\n\u0d05\u0d17\u0d4d\u0d28\u0d47\u0951 \u0d05\u0d24\u0d4d\u0d30\u0d3f\u0d35\u0952\u0d28\u0d4d\u0d2e\u0d28\u0951\u0d38\u0d3e \u0d17\u0d43\u0d23\u0d3e\u0952\u0d28\u0d4b\u0d3d\u0d38\u0d4d\u0d2e\u0d3e\u0d15\u0d02\u0951 \u0d2c\u0d4b\u0d27\u0d4d\u0d2f\u0d35\u0d3f\u0952\u0d24\u0d3e \u0d24\u0952\u0d28\u0d42\u0d28\u0d3e\u0d2e\u0d4d \u0965 \u0d6a \u0965", "iast": "vi\u015bv\u0101\u032dni no du\u0331rgah\u0101\u032d j\u0101taveda\u0331\u1e25 sindhu\u0331\u1e43 na n\u0101\u0331v\u0101 d\u1e77ri\u0331t\u0101'ti\u032dpar\u1e63i |\nagn\u1e19 atriva\u0331nmana\u032ds\u0101 g\u1e5b\u1e47\u0101\u0331no'sm\u0101ka\u032d\u1e43 bodhyavi\u0331t\u0101 ta\u0331n\u016bn\u0101m || 4 ||"},
        draftTranslation: "O Jatavedas! Safely convey us past all impassable barriers and sins, just as a boatman ferries passengers across the surging sea. O Agni, celebrated in prayer like Sage Atri, awaken as the perpetual guardian and protector of our lives!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 5,
        devanagariText: "\u092a\u0943\u0924\u0951\u0928\u093e\u0952\u091c\u093f\u0924\u0902\u0952 \u0938\u0939\u0951\u092e\u093e\u0928\u092e\u0941\u0952\u0917\u094d\u0930\u092e\u0952\u0917\u094d\u0928\u093f\u0902 \u0939\u0941\u0951\u0935\u0947\u092e \u092a\u0930\u0952\u092e\u093e\u0924\u094d\u0938\u0952\u0927\u0938\u094d\u0925\u093e\u0951\u0924\u094d \u0964\n\u0938 \u0928\u0903\u0951 \u092a\u0930\u094d\u0937\u0952\u0926\u0924\u093f\u0951 \u0926\u0941\u0952\u0930\u094d\u0917\u093e\u0923\u093f\u0952 \u0935\u093f\u0936\u094d\u0935\u093e\u0952 \u0915\u094d\u0937\u093e\u092e\u0951\u0926\u094d\u0926\u0947\u0935\u094b \u0905\u0924\u093f\u0926\u0941\u0930\u093f\u0952\u0924\u093e\u0924\u094d\u092f\u0952\u0917\u094d\u0928\u093f\u0903 \u0965 \u096b \u0965",
        iastText: "p\u1e5bta\u0951n\u0101\u0952jita\u1e41\u0952 saha\u0951m\u0101namu\u0952grama\u0952gni\u1e41 hu\u0951v\u0113ma para\u0952m\u0101tsa\u0952dhasth\u0101\u0951t \u0964\nsa na\u1e25\u0951 par\u1e63a\u0952dati\u0951 du\u0952rg\u0101\u1e47i\u0952 vi\u015bv\u0101\u0952 k\u1e63\u0101ma\u0951dd\u0113v\u014d atiduri\u0952t\u0101tya\u0952gni\u1e25 \u0965 5 \u0965",
        meter: "Trishtubh",
        transliterations: {"telugu": "\u0c2a\u0c43\u0c24\u0951\u0c28\u0c3e\u0952\u0c1c\u0c3f\u0c24\u0c02\u0952 \u0c38\u0c39\u0951\u0c2e\u0c3e\u0c28\u0c2e\u0c41\u0952\u0c17\u0c4d\u0c30\u0c2e\u0952\u0c17\u0c4d\u0c28\u0c3f\u0c02 \u0c39\u0c41\u0951\u0c35\u0c47\u0c2e \u0c2a\u0c30\u0952\u0c2e\u0c3e\u0c24\u0c4d\u0c38\u0952\u0c27\u0c38\u0c4d\u0c25\u0c3e\u0951\u0c24\u0c4d \u0964\n\u0c38 \u0c28\u0c03\u0951 \u0c2a\u0c30\u0c4d\u0c37\u0952\u0c26\u0c24\u0c3f\u0951 \u0c26\u0c41\u0952\u0c30\u0c4d\u0c17\u0c3e\u0c23\u0c3f\u0952 \u0c35\u0c3f\u0c36\u0c4d\u0c35\u0c3e\u0952 \u0c15\u0c4d\u0c37\u0c3e\u0c2e\u0951\u0c26\u0c4d\u0c26\u0c47\u0c35\u0c4b \u0c05\u0c24\u0c3f\u0c26\u0c41\u0c30\u0c3f\u0952\u0c24\u0c3e\u0c24\u0c4d\u0c2f\u0952\u0c17\u0c4d\u0c28\u0c3f\u0c03 \u0965 \u0c6b \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0bc1'\u0ba4\u0951\u0ba8\u0bbe\u0952\u0b9c\u0bbf\u0ba4\u0bae\u0bcd\u0952 \u0bb8\u0bb9\u0951\u0bae\u0bbe\u0ba8\u0bae\u0bc1\u0952\u0b95\u0bcd\u0bb0\u0bae\u0952\u0b95\u0bcd\u0ba8\u0bbf\u0bae\u0bcd \u0bb9\u0bc1\u0951\u0bb5\u0bc7\u0bae \u0baa\u0bb0\u0952\u0bae\u0bbe\u0ba4\u0bcd\u0bb8\u0952\u0ba4\u0bb8\u0bcd\u0ba4\u0bbe\u0951\u0ba4\u0bcd \u0964\n\u0bb8 \u0ba8\u0b83\u0951 \u0baa\u0bb0\u0bcd\u0bb7\u0952\u0ba4\u0ba4\u0bbf\u0951 \u0ba4\u0bc1\u0952\u0bb0\u0bcd\u0b95\u0bbe\u0ba3\u0bbf\u0952 \u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0bbe\u0952 \u0b95\u0bcd\u0bb7\u0bbe\u0bae\u0951\u0ba4\u0bcd\u0ba4\u0bc7\u0bb5\u0bcb \u0b85\u0ba4\u0bbf\u0ba4\u0bc1\u0bb0\u0bbf\u0952\u0ba4\u0bbe\u0ba4\u0bcd\u0baf\u0952\u0b95\u0bcd\u0ba8\u0bbf\u0b83 \u0965 \u0beb \u0965", "kannada": "\u0caa\u0cc3\u0ca4\u0951\u0ca8\u0cbe\u0952\u0c9c\u0cbf\u0ca4\u0c82\u0952 \u0cb8\u0cb9\u0951\u0cae\u0cbe\u0ca8\u0cae\u0cc1\u0952\u0c97\u0ccd\u0cb0\u0cae\u0952\u0c97\u0ccd\u0ca8\u0cbf\u0c82 \u0cb9\u0cc1\u0951\u0cb5\u0cc7\u0cae \u0caa\u0cb0\u0952\u0cae\u0cbe\u0ca4\u0ccd\u0cb8\u0952\u0ca7\u0cb8\u0ccd\u0ca5\u0cbe\u0951\u0ca4\u0ccd \u0964\n\u0cb8 \u0ca8\u0c83\u0951 \u0caa\u0cb0\u0ccd\u0cb7\u0952\u0ca6\u0ca4\u0cbf\u0951 \u0ca6\u0cc1\u0952\u0cb0\u0ccd\u0c97\u0cbe\u0ca3\u0cbf\u0952 \u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0cbe\u0952 \u0c95\u0ccd\u0cb7\u0cbe\u0cae\u0951\u0ca6\u0ccd\u0ca6\u0cc7\u0cb5\u0ccb \u0c85\u0ca4\u0cbf\u0ca6\u0cc1\u0cb0\u0cbf\u0952\u0ca4\u0cbe\u0ca4\u0ccd\u0caf\u0952\u0c97\u0ccd\u0ca8\u0cbf\u0c83 \u0965 \u0ceb \u0965", "malayalam": "\u0d2a\u0d43\u0d24\u0951\u0d28\u0d3e\u0952\u0d1c\u0d3f\u0d24\u0d02\u0952 \u0d38\u0d39\u0951\u0d2e\u0d3e\u0d28\u0d2e\u0d41\u0952\u0d17\u0d4d\u0d30\u0d2e\u0952\u0d17\u0d4d\u0d28\u0d3f\u0d02 \u0d39\u0d41\u0951\u0d35\u0d47\u0d2e \u0d2a\u0d30\u0952\u0d2e\u0d3e\u0d24\u0d4d\u0d38\u0952\u0d27\u0d38\u0d4d\u0d25\u0d3e\u0951\u0d24\u0d4d \u0964\n\u0d38 \u0d28\u0d03\u0951 \u0d2a\u0d30\u0d4d\u0d37\u0952\u0d26\u0d24\u0d3f\u0951 \u0d26\u0d41\u0952\u0d30\u0d4d\u0d17\u0d3e\u0d23\u0d3f\u0952 \u0d35\u0d3f\u0d36\u0d4d\u0d35\u0d3e\u0952 \u0d15\u0d4d\u0d37\u0d3e\u0d2e\u0951\u0d26\u0d4d\u0d26\u0d47\u0d35\u0d4b \u0d05\u0d24\u0d3f\u0d26\u0d41\u0d30\u0d3f\u0952\u0d24\u0d3e\u0d24\u0d4d\u0d2f\u0952\u0d17\u0d4d\u0d28\u0d3f\u0d03 \u0965 \u0d6b \u0965", "iast": "p\u1e5bta\u032dn\u0101\u0331jita\u0331\u1e43 saha\u032dm\u0101namu\u0331grama\u0331gni\u1e43 h\u1e77vema para\u0331m\u0101tsa\u0331dhasth\u0101\u032dt |\nsa na\u032d\u1e25 par\u1e63a\u0331dati\u032d du\u0331rg\u0101\u1e47i\u0331 vi\u015bv\u0101\u0331 k\u1e63\u0101ma\u032dddevo atiduri\u0331t\u0101tya\u0331gni\u1e25 || 5 ||"},
        draftTranslation: "We invoke Agni, the conqueror of hostile armies, triumphant and formidable, from His supreme celestial assembly! May He, the luminous God, consume our transgressions and transport us safely across every tribulation!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 6,
        devanagariText: "\u092a\u094d\u0930\u0952\u0924\u094d\u0928\u094b\u0937\u093f\u0951 \u0915\u0952\u092e\u0940\u0921\u094d\u092f\u094b\u0951 \u0905\u0927\u094d\u0935\u0952\u0930\u0947\u0937\u0941\u0951 \u0938\u0952\u0928\u093e\u091a\u094d\u091a\u0952 \u0939\u094b\u0924\u093e\u0952 \u0928\u0935\u094d\u092f\u0951\u0936\u094d\u091a\u0952 \u0938\u0924\u094d\u0938\u093f\u0951 \u0964\n\u0938\u094d\u0935\u093e\u091e\u094d\u091a\u093e\u0951\u0917\u094d\u0928\u0947 \u0924\u0952\u0928\u0941\u0935\u0902\u0951 \u092a\u093f\u0952\u092a\u094d\u0930\u092f\u0951\u0938\u094d\u0935\u093e\u0952\u0938\u094d\u092e\u092d\u094d\u092f\u0902\u0951 \u091a\u0952 \u0938\u094c\u092d\u0951\u0917\u0952\u092e\u093e\u092f\u0951\u091c\u0938\u094d\u0935 \u0965 \u096c \u0965",
        iastText: "pra\u0952tn\u014d\u1e63i\u0951 ka\u0952m\u012b\u1e0dy\u014d\u0951 adhva\u0952r\u0113\u1e63u\u0951 sa\u0952n\u0101cca\u0952 h\u014dt\u0101\u0952 navya\u0951\u015bca\u0952 satsi\u0951 \u0964\nsv\u0101\u00f1c\u0101\u0951gn\u0113 ta\u0952nuva\u1e41\u0951 pi\u0952praya\u0951sw\u0101\u0952smabhya\u1e41\u0951 ca\u0952 saubha\u0951ga\u0952m\u0101ya\u0951jasva \u0965 6 \u0965",
        meter: "Trishtubh",
        transliterations: {"telugu": "\u0c2a\u0c4d\u0c30\u0952\u0c24\u0c4d\u0c28\u0c4b\u0c37\u0c3f\u0951 \u0c15\u0952\u0c2e\u0c40\u0c21\u0c4d\u0c2f\u0c4b\u0951 \u0c05\u0c27\u0c4d\u0c35\u0952\u0c30\u0c47\u0c37\u0c41\u0951 \u0c38\u0952\u0c28\u0c3e\u0c1a\u0c4d\u0c1a\u0952 \u0c39\u0c4b\u0c24\u0c3e\u0952 \u0c28\u0c35\u0c4d\u0c2f\u0951\u0c36\u0c4d\u0c1a\u0952 \u0c38\u0c24\u0c4d\u0c38\u0c3f\u0951 \u0964\n\u0c38\u0c4d\u0c35\u0c3e\u0c1e\u0c4d\u0c1a\u0c3e\u0951\u0c17\u0c4d\u0c28\u0c47 \u0c24\u0952\u0c28\u0c41\u0c35\u0c02\u0951 \u0c2a\u0c3f\u0952\u0c2a\u0c4d\u0c30\u0c2f\u0951\u0c38\u0c4d\u0c35\u0c3e\u0952\u0c38\u0c4d\u0c2e\u0c2d\u0c4d\u0c2f\u0c02\u0951 \u0c1a\u0952 \u0c38\u0c4c\u0c2d\u0951\u0c17\u0952\u0c2e\u0c3e\u0c2f\u0951\u0c1c\u0c38\u0c4d\u0c35 \u0965 \u0c6c \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0952\u0ba4\u0bcd\u0ba8\u0bcb\u0bb7\u0bbf\u0951 \u0b95\u0952\u0bae\u0bc0\u0b9f\u0bcd\u0baf\u0bcb\u0951 \u0b85\u0ba4\u0bcd\u0bb5\u0952\u0bb0\u0bc7\u0bb7\u0bc1\u0951 \u0bb8\u0952\u0ba8\u0bbe\u0b9a\u0bcd\u0b9a\u0952 \u0bb9\u0bcb\u0ba4\u0bbe\u0952 \u0ba8\u0bb5\u0bcd\u0baf\u0951\u0bb6\u0bcd\u0b9a\u0952 \u0bb8\u0ba4\u0bcd\u0bb8\u0bbf\u0951 \u0964\n\u0bb8\u0bcd\u0bb5\u0bbe\u0b9e\u0bcd\u0b9a\u0bbe\u0951\u0b95\u0bcd\u0ba8\u0bc7 \u0ba4\u0952\u0ba8\u0bc1\u0bb5\u0bae\u0bcd\u0951 \u0baa\u0bbf\u0952\u0baa\u0bcd\u0bb0\u0baf\u0951\u0bb8\u0bcd\u0bb5\u0bbe\u0952\u0bb8\u0bcd\u0bae\u0baa\u0bcd\u0baf\u0bae\u0bcd\u0951 \u0b9a\u0952 \u0bb8\u0bcc\u0baa\u0951\u0b95\u0952\u0bae\u0bbe\u0baf\u0951\u0b9c\u0bb8\u0bcd\u0bb5 \u0965 \u0bec \u0965", "kannada": "\u0caa\u0ccd\u0cb0\u0952\u0ca4\u0ccd\u0ca8\u0ccb\u0cb7\u0cbf\u0951 \u0c95\u0952\u0cae\u0cc0\u0ca1\u0ccd\u0caf\u0ccb\u0951 \u0c85\u0ca7\u0ccd\u0cb5\u0952\u0cb0\u0cc7\u0cb7\u0cc1\u0951 \u0cb8\u0952\u0ca8\u0cbe\u0c9a\u0ccd\u0c9a\u0952 \u0cb9\u0ccb\u0ca4\u0cbe\u0952 \u0ca8\u0cb5\u0ccd\u0caf\u0951\u0cb6\u0ccd\u0c9a\u0952 \u0cb8\u0ca4\u0ccd\u0cb8\u0cbf\u0951 \u0964\n\u0cb8\u0ccd\u0cb5\u0cbe\u0c9e\u0ccd\u0c9a\u0cbe\u0951\u0c97\u0ccd\u0ca8\u0cc7 \u0ca4\u0952\u0ca8\u0cc1\u0cb5\u0c82\u0951 \u0caa\u0cbf\u0952\u0caa\u0ccd\u0cb0\u0caf\u0951\u0cb8\u0ccd\u0cb5\u0cbe\u0952\u0cb8\u0ccd\u0cae\u0cad\u0ccd\u0caf\u0c82\u0951 \u0c9a\u0952 \u0cb8\u0ccc\u0cad\u0951\u0c97\u0952\u0cae\u0cbe\u0caf\u0951\u0c9c\u0cb8\u0ccd\u0cb5 \u0965 \u0cec \u0965", "malayalam": "\u0d2a\u0d4d\u0d30\u0952\u0d24\u0d4d\u0d28\u0d4b\u0d37\u0d3f\u0951 \u0d15\u0952\u0d2e\u0d40\u0d21\u0d4d\u0d2f\u0d4b\u0951 \u0d05\u0d27\u0d4d\u0d35\u0952\u0d30\u0d47\u0d37\u0d41\u0951 \u0d38\u0952\u0d28\u0d3e\u0d1a\u0d4d\u0d1a\u0952 \u0d39\u0d4b\u0d24\u0d3e\u0952 \u0d28\u0d35\u0d4d\u0d2f\u0951\u0d36\u0d4d\u0d1a\u0952 \u0d38\u0d24\u0d4d\u0d38\u0d3f\u0951 \u0964\n\u0d38\u0d4d\u0d35\u0d3e\u0d1e\u0d4d\u0d1a\u0d3e\u0951\u0d17\u0d4d\u0d28\u0d47 \u0d24\u0952\u0d28\u0d41\u0d35\u0d02\u0951 \u0d2a\u0d3f\u0952\u0d2a\u0d4d\u0d30\u0d2f\u0951\u0d38\u0d4d\u0d35\u0d3e\u0952\u0d38\u0d4d\u0d2e\u0d2d\u0d4d\u0d2f\u0d02\u0951 \u0d1a\u0952 \u0d38\u0d4c\u0d2d\u0951\u0d17\u0952\u0d2e\u0d3e\u0d2f\u0951\u0d1c\u0d38\u0d4d\u0d35 \u0965 \u0d6c \u0965", "iast": "pra\u0331tno\u1e63i\u032d ka\u0331m\u012b\u1e0dyo\u032d adhva\u0331re\u1e63\u1e77 sa\u0331n\u0101cca\u0331 hot\u0101\u0331 navya\u032d\u015bca\u0331 satsi\u032d |\nsv\u0101\u00f1c\u0101\u032dgne ta\u0331nuva\u032d\u1e43 pi\u0331praya\u032dsv\u0101\u0331smabhya\u032d\u1e43 ca\u0331 saubha\u032dga\u0331m\u0101ya\u032djasva || 6 ||"},
        draftTranslation: "You are praiseworthy in all sacred sacrifices since ancient times; You are the eternal Priest (Hota), yet ever fresh and new! O Agni, delight in Your own divine form and bestow glorious auspiciousness, spiritual wealth, and fortune upon us!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 7,
        devanagariText: "\u0917\u094b\u092d\u093f\u0952\u0930\u094d\u091c\u0941\u0937\u094d\u091f\u0952\u092e\u092f\u0941\u0951\u091c\u094b\u0952 \u0928\u093f\u0937\u093f\u0951\u0915\u094d\u0924\u0902\u0952 \u0924\u0935\u0947\u0951\u0928\u094d\u0926\u094d\u0930 \u0935\u093f\u0937\u094d\u0923\u094b\u0952\u0930\u0928\u0941\u0952\u0938\u0902\u091a\u0951\u0930\u0947\u092e \u0964\n\u0928\u093e\u0915\u0951\u0938\u094d\u092f \u092a\u0943\u0952\u0937\u094d\u0920\u092e\u0952\u092d\u093f \u0938\u0902\u0952\u0935\u0938\u093e\u0951\u0928\u094b\u0952 \u0935\u0948\u0937\u094d\u0923\u0951\u0935\u0940\u0902 \u0932\u094b\u0952\u0915 \u0907\u0952\u0939 \u092e\u093e\u0951\u0926\u092f\u0928\u094d\u0924\u093e\u092e\u094d \u0965 \u096d \u0965",
        iastText: "g\u014dbhi\u0952rju\u1e63\u1e6da\u0952mayu\u0951j\u014d\u0952 ni\u1e63i\u0951kta\u1e41\u0952 tav\u0113\u0951ndra vi\u1e63\u1e47\u014d\u0952ranu\u0952sa\u1e41ca\u0951r\u0113ma \u0964\nn\u0101ka\u0951sya p\u1e5b\u0952\u1e63\u1e6dhama\u0952bhi sa\u1e41\u0952vas\u0101\u0951n\u014d\u0952 vai\u1e63\u1e47a\u0951v\u012b\u1e41 l\u014d\u0952ka i\u0952ha m\u0101\u0951dayant\u0101m \u0965 7 \u0965",
        meter: "Trishtubh",
        transliterations: {"telugu": "\u0c17\u0c4b\u0c2d\u0c3f\u0952\u0c30\u0c4d\u0c1c\u0c41\u0c37\u0c4d\u0c1f\u0952\u0c2e\u0c2f\u0c41\u0951\u0c1c\u0c4b\u0952 \u0c28\u0c3f\u0c37\u0c3f\u0951\u0c15\u0c4d\u0c24\u0c02\u0952 \u0c24\u0c35\u0c47\u0951\u0c28\u0c4d\u0c26\u0c4d\u0c30 \u0c35\u0c3f\u0c37\u0c4d\u0c23\u0c4b\u0952\u0c30\u0c28\u0c41\u0952\u0c38\u0c02\u0c1a\u0951\u0c30\u0c47\u0c2e \u0964\n\u0c28\u0c3e\u0c15\u0951\u0c38\u0c4d\u0c2f \u0c2a\u0c43\u0952\u0c37\u0c4d\u0c20\u0c2e\u0952\u0c2d\u0c3f \u0c38\u0c02\u0952\u0c35\u0c38\u0c3e\u0951\u0c28\u0c4b\u0952 \u0c35\u0c48\u0c37\u0c4d\u0c23\u0951\u0c35\u0c40\u0c02 \u0c32\u0c4b\u0952\u0c15 \u0c07\u0952\u0c39 \u0c2e\u0c3e\u0951\u0c26\u0c2f\u0c28\u0c4d\u0c24\u0c3e\u0c2e\u0c4d \u0965 \u0c6d \u0965", "tamil": "\u0b95\u0bcb\u0baa\u0bbf\u0952\u0bb0\u0bcd\u0b9c\u0bc1\u0bb7\u0bcd\u0b9f\u0952\u0bae\u0baf\u0bc1\u0951\u0b9c\u0bcb\u0952 \u0ba8\u0bbf\u0bb7\u0bbf\u0951\u0b95\u0bcd\u0ba4\u0bae\u0bcd\u0952 \u0ba4\u0bb5\u0bc7\u0951\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0 \u0bb5\u0bbf\u0bb7\u0bcd\u0ba3\u0bcb\u0952\u0bb0\u0ba8\u0bc1\u0952\u0bb8\u0bae\u0bcd\u0b9a\u0951\u0bb0\u0bc7\u0bae \u0964\n\u0ba8\u0bbe\u0b95\u0951\u0bb8\u0bcd\u0baf \u0baa\u0bcd\u0bb0\u0bc1'\u0952\u0bb7\u0bcd\u0b9f\u0bae\u0952\u0baa\u0bbf \u0bb8\u0bae\u0bcd\u0952\u0bb5\u0bb8\u0bbe\u0951\u0ba8\u0bcb\u0952 \u0bb5\u0bc8\u0bb7\u0bcd\u0ba3\u0951\u0bb5\u0bc0\u0bae\u0bcd \u0bb2\u0bcb\u0952\u0b95 \u0b87\u0952\u0bb9 \u0bae\u0bbe\u0951\u0ba4\u0baf\u0ba8\u0bcd\u0ba4\u0bbe\u0bae\u0bcd \u0965 \u0bed \u0965", "kannada": "\u0c97\u0ccb\u0cad\u0cbf\u0952\u0cb0\u0ccd\u0c9c\u0cc1\u0cb7\u0ccd\u0c9f\u0952\u0cae\u0caf\u0cc1\u0951\u0c9c\u0ccb\u0952 \u0ca8\u0cbf\u0cb7\u0cbf\u0951\u0c95\u0ccd\u0ca4\u0c82\u0952 \u0ca4\u0cb5\u0cc7\u0951\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0 \u0cb5\u0cbf\u0cb7\u0ccd\u0ca3\u0ccb\u0952\u0cb0\u0ca8\u0cc1\u0952\u0cb8\u0c82\u0c9a\u0951\u0cb0\u0cc7\u0cae \u0964\n\u0ca8\u0cbe\u0c95\u0951\u0cb8\u0ccd\u0caf \u0caa\u0cc3\u0952\u0cb7\u0ccd\u0ca0\u0cae\u0952\u0cad\u0cbf \u0cb8\u0c82\u0952\u0cb5\u0cb8\u0cbe\u0951\u0ca8\u0ccb\u0952 \u0cb5\u0cc8\u0cb7\u0ccd\u0ca3\u0951\u0cb5\u0cc0\u0c82 \u0cb2\u0ccb\u0952\u0c95 \u0c87\u0952\u0cb9 \u0cae\u0cbe\u0951\u0ca6\u0caf\u0ca8\u0ccd\u0ca4\u0cbe\u0cae\u0ccd \u0965 \u0ced \u0965", "malayalam": "\u0d17\u0d4b\u0d2d\u0d3f\u0952\u0d30\u0d4d\u0d1c\u0d41\u0d37\u0d4d\u0d1f\u0952\u0d2e\u0d2f\u0d41\u0951\u0d1c\u0d4b\u0952 \u0d28\u0d3f\u0d37\u0d3f\u0951\u0d15\u0d4d\u0d24\u0d02\u0952 \u0d24\u0d35\u0d47\u0951\u0d28\u0d4d\u0d26\u0d4d\u0d30 \u0d35\u0d3f\u0d37\u0d4d\u0d23\u0d4b\u0952\u0d30\u0d28\u0d41\u0952\u0d38\u0d02\u0d1a\u0951\u0d30\u0d47\u0d2e \u0964\n\u0d28\u0d3e\u0d15\u0951\u0d38\u0d4d\u0d2f \u0d2a\u0d43\u0952\u0d37\u0d4d\u0d20\u0d2e\u0952\u0d2d\u0d3f \u0d38\u0d02\u0952\u0d35\u0d38\u0d3e\u0951\u0d28\u0d4b\u0952 \u0d35\u0d48\u0d37\u0d4d\u0d23\u0951\u0d35\u0d40\u0d02 \u0d32\u0d4b\u0952\u0d15 \u0d07\u0952\u0d39 \u0d2e\u0d3e\u0951\u0d26\u0d2f\u0d28\u0d4d\u0d24\u0d3e\u0d2e\u0d4d \u0965 \u0d6d \u0965", "iast": "gobhi\u0331rju\u1e63\u1e6da\u0331may\u1e77jo\u0331 ni\u1e63i\u032dkta\u0331\u1e43 tav\u1e19ndra vi\u1e63\u1e47o\u0331ranu\u0331sa\u1e43ca\u032drema |\nn\u0101ka\u032dsya p\u1e5b\u0331\u1e63\u1e6dhama\u0331bhi sa\u0331\u1e43vas\u0101\u032dno\u0331 vai\u1e63\u1e47a\u032dv\u012b\u1e43 lo\u0331ka i\u0331ha m\u0101\u032ddayant\u0101m || 7 ||"},
        draftTranslation: "Blessed with spiritual wisdom, may we walk in harmony with Indra and Vishnu! Ascending to the radiant summit of the highest heaven, established in the transcendent Vaishnavi realm, may the seekers rejoice in everlasting bliss!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
    ],
  ),
  Scripture(
    id: 19,
    contentId: "VEDA-TXT-00016",
    canonicalTitle: "Narayana Suktam",
    devanagariTitle: "\u0928\u093e\u0930\u093e\u092f\u0923\u0938\u0942\u0915\u094d\u0924\u092e\u094d",
    category: "Suktam",
    deity: "Purusha / Supreme Being",
    composer: "Rishi Narayana",
    rishi: "Traditional Vedic Sage",
    chandas: "Anushtubh",
    devata: "Purusha / Supreme Being",
    sourceScripture: "Taittiriya Aranyaka 10.13 (Mahanarayana Upanishad 13)",
    traditionalUsage: "Meditation on the inner flame of the heart (Dahara Vidya), Narayana Upasana",
    verseCount: 12,
    verses: [
      Verse(
        verseNumber: 1,
        devanagariText: "\u0938\u0952\u0939\u0938\u094d\u0930\u0951\u0936\u0940\u0930\u094d\u0937\u0902 \u0926\u0947\u0935\u0902\u0952 \u0935\u093f\u0952\u0936\u094d\u0935\u093e\u0915\u094d\u0937\u0902\u0951 \u0935\u093f\u0952\u0936\u094d\u0935\u0936\u0951\u092e\u094d\u092d\u0941\u0935\u092e\u094d \u0964\n\u0935\u093f\u0936\u094d\u0935\u0902\u0951 \u0928\u093e\u0952\u0930\u093e\u092f\u0951\u0923\u0902 \u0926\u0947\u0952\u0935\u0952\u092e\u0952\u0915\u094d\u0937\u0930\u0902\u0951 \u092a\u0930\u0952\u092e\u0902 \u092a\u0926\u092e\u094d \u0965 \u0967 \u0965",
        iastText: "sa\u0952hasra\u0951\u015b\u012br\u1e63a\u1e41 d\u0113va\u1e41\u0952 vi\u0952\u015bv\u0101k\u1e63a\u1e41\u0951 vi\u0952\u015bva\u015ba\u0951mbhuvam \u0964\nvi\u015bva\u1e41\u0951 n\u0101\u0952r\u0101ya\u0951\u1e47a\u1e41 d\u0113\u0952va\u0952ma\u0952k\u1e63ara\u1e41\u0951 para\u0952ma\u1e41 padam \u0965 1 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0952\u0c39\u0c38\u0c4d\u0c30\u0951\u0c36\u0c40\u0c30\u0c4d\u0c37\u0c02 \u0c26\u0c47\u0c35\u0c02\u0952 \u0c35\u0c3f\u0952\u0c36\u0c4d\u0c35\u0c3e\u0c15\u0c4d\u0c37\u0c02\u0951 \u0c35\u0c3f\u0952\u0c36\u0c4d\u0c35\u0c36\u0951\u0c2e\u0c4d\u0c2d\u0c41\u0c35\u0c2e\u0c4d \u0964\n\u0c35\u0c3f\u0c36\u0c4d\u0c35\u0c02\u0951 \u0c28\u0c3e\u0952\u0c30\u0c3e\u0c2f\u0951\u0c23\u0c02 \u0c26\u0c47\u0952\u0c35\u0952\u0c2e\u0952\u0c15\u0c4d\u0c37\u0c30\u0c02\u0951 \u0c2a\u0c30\u0952\u0c2e\u0c02 \u0c2a\u0c26\u0c2e\u0c4d \u0965 \u0c67 \u0965", "tamil": "\u0bb8\u0952\u0bb9\u0bb8\u0bcd\u0bb0\u0951\u0bb6\u0bc0\u0bb0\u0bcd\u0bb7\u0bae\u0bcd \u0ba4\u0bc7\u0bb5\u0bae\u0bcd\u0952 \u0bb5\u0bbf\u0952\u0bb6\u0bcd\u0bb5\u0bbe\u0b95\u0bcd\u0bb7\u0bae\u0bcd\u0951 \u0bb5\u0bbf\u0952\u0bb6\u0bcd\u0bb5\u0bb6\u0951\u0bae\u0bcd\u0baa\u0bc1\u0bb5\u0bae\u0bcd \u0964\n\u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0bae\u0bcd\u0951 \u0ba8\u0bbe\u0952\u0bb0\u0bbe\u0baf\u0951\u0ba3\u0bae\u0bcd \u0ba4\u0bc7\u0952\u0bb5\u0952\u0bae\u0952\u0b95\u0bcd\u0bb7\u0bb0\u0bae\u0bcd\u0951 \u0baa\u0bb0\u0952\u0bae\u0bae\u0bcd \u0baa\u0ba4\u0bae\u0bcd \u0965 \u0be7 \u0965", "kannada": "\u0cb8\u0952\u0cb9\u0cb8\u0ccd\u0cb0\u0951\u0cb6\u0cc0\u0cb0\u0ccd\u0cb7\u0c82 \u0ca6\u0cc7\u0cb5\u0c82\u0952 \u0cb5\u0cbf\u0952\u0cb6\u0ccd\u0cb5\u0cbe\u0c95\u0ccd\u0cb7\u0c82\u0951 \u0cb5\u0cbf\u0952\u0cb6\u0ccd\u0cb5\u0cb6\u0951\u0cae\u0ccd\u0cad\u0cc1\u0cb5\u0cae\u0ccd \u0964\n\u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0c82\u0951 \u0ca8\u0cbe\u0952\u0cb0\u0cbe\u0caf\u0951\u0ca3\u0c82 \u0ca6\u0cc7\u0952\u0cb5\u0952\u0cae\u0952\u0c95\u0ccd\u0cb7\u0cb0\u0c82\u0951 \u0caa\u0cb0\u0952\u0cae\u0c82 \u0caa\u0ca6\u0cae\u0ccd \u0965 \u0ce7 \u0965", "malayalam": "\u0d38\u0952\u0d39\u0d38\u0d4d\u0d30\u0951\u0d36\u0d40\u0d30\u0d4d\u0d37\u0d02 \u0d26\u0d47\u0d35\u0d02\u0952 \u0d35\u0d3f\u0952\u0d36\u0d4d\u0d35\u0d3e\u0d15\u0d4d\u0d37\u0d02\u0951 \u0d35\u0d3f\u0952\u0d36\u0d4d\u0d35\u0d36\u0951\u0d2e\u0d4d\u0d2d\u0d41\u0d35\u0d2e\u0d4d \u0964\n\u0d35\u0d3f\u0d36\u0d4d\u0d35\u0d02\u0951 \u0d28\u0d3e\u0952\u0d30\u0d3e\u0d2f\u0951\u0d23\u0d02 \u0d26\u0d47\u0952\u0d35\u0952\u0d2e\u0952\u0d15\u0d4d\u0d37\u0d30\u0d02\u0951 \u0d2a\u0d30\u0952\u0d2e\u0d02 \u0d2a\u0d26\u0d2e\u0d4d \u0965 \u0d67 \u0965", "iast": "sa\u0331hasra\u032d\u015b\u012br\u1e63a\u1e43 deva\u0331\u1e43 vi\u0331\u015bv\u0101k\u1e63a\u032d\u1e43 vi\u0331\u015bva\u015ba\u032dmbhuvam |\nvi\u015bva\u032d\u1e43 n\u0101\u0331r\u0101ya\u032d\u1e47a\u1e43 de\u0331va\u0331ma\u0331k\u1e63ara\u032d\u1e43 para\u0331ma\u1e43 padam || 1 ||"},
        draftTranslation: "We meditate upon the Supreme Lord Narayana, who has a thousand heads, who is all-seeing (with eyes everywhere), who is the source of all auspiciousness and happiness to the universe, who is the universe itself, imperishable, and the supreme goal.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 2,
        devanagariText: "\u0935\u093f\u0936\u094d\u0935\u0951\u0924\u0903 \u092a\u0930\u0952\u092e\u093e\u0928\u094d\u0928\u093f\u0952\u0924\u094d\u092f\u0902\u0952 \u0935\u093f\u0952\u0936\u094d\u0935\u0902 \u0928\u093e\u0951\u0930\u093e\u092f\u0952\u0923\u0902 \u0939\u0930\u093f\u0951\u092e\u094d \u0964\n\u0935\u093f\u0936\u094d\u0935\u0951\u092e\u0947\u0952\u0935\u0947\u0926\u0902 \u092a\u0941\u0930\u0941\u0951\u0937\u0952\u0938\u094d\u0924\u0926\u094d\u0935\u093f\u0936\u094d\u0935\u0952\u092e\u0941\u092a\u0951\u091c\u0940\u0935\u0924\u093f \u0965 \u0968 \u0965",
        iastText: "vi\u015bva\u0951ta\u1e25 para\u0952m\u0101nni\u0952tya\u1e41\u0952 vi\u0952\u015bva\u1e41 n\u0101\u0951raya\u0952\u1e47a\u1e41 hari\u0951m \u0964\nvi\u015bva\u0951m\u0113\u0952v\u0113da\u1e41 puru\u0951\u1e63a\u0952stadvi\u015bva\u0952mupa\u0951j\u012bvati \u0965 2 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c35\u0c3f\u0c36\u0c4d\u0c35\u0951\u0c24\u0c03 \u0c2a\u0c30\u0952\u0c2e\u0c3e\u0c28\u0c4d\u0c28\u0c3f\u0952\u0c24\u0c4d\u0c2f\u0c02\u0952 \u0c35\u0c3f\u0952\u0c36\u0c4d\u0c35\u0c02 \u0c28\u0c3e\u0951\u0c30\u0c3e\u0c2f\u0952\u0c23\u0c02 \u0c39\u0c30\u0c3f\u0951\u0c2e\u0c4d \u0964\n\u0c35\u0c3f\u0c36\u0c4d\u0c35\u0951\u0c2e\u0c47\u0952\u0c35\u0c47\u0c26\u0c02 \u0c2a\u0c41\u0c30\u0c41\u0951\u0c37\u0952\u0c38\u0c4d\u0c24\u0c26\u0c4d\u0c35\u0c3f\u0c36\u0c4d\u0c35\u0952\u0c2e\u0c41\u0c2a\u0951\u0c1c\u0c40\u0c35\u0c24\u0c3f \u0965 \u0c68 \u0965", "tamil": "\u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0951\u0ba4\u0b83 \u0baa\u0bb0\u0952\u0bae\u0bbe\u0ba8\u0bcd\u0ba8\u0bbf\u0952\u0ba4\u0bcd\u0baf\u0bae\u0bcd\u0952 \u0bb5\u0bbf\u0952\u0bb6\u0bcd\u0bb5\u0bae\u0bcd \u0ba8\u0bbe\u0951\u0bb0\u0bbe\u0baf\u0952\u0ba3\u0bae\u0bcd \u0bb9\u0bb0\u0bbf\u0951\u0bae\u0bcd \u0964\n\u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0951\u0bae\u0bc7\u0952\u0bb5\u0bc7\u0ba4\u0bae\u0bcd \u0baa\u0bc1\u0bb0\u0bc1\u0951\u0bb7\u0952\u0bb8\u0bcd\u0ba4\u0ba4\u0bcd\u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0952\u0bae\u0bc1\u0baa\u0951\u0b9c\u0bc0\u0bb5\u0ba4\u0bbf \u0965 \u0be8 \u0965", "kannada": "\u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0951\u0ca4\u0c83 \u0caa\u0cb0\u0952\u0cae\u0cbe\u0ca8\u0ccd\u0ca8\u0cbf\u0952\u0ca4\u0ccd\u0caf\u0c82\u0952 \u0cb5\u0cbf\u0952\u0cb6\u0ccd\u0cb5\u0c82 \u0ca8\u0cbe\u0951\u0cb0\u0cbe\u0caf\u0952\u0ca3\u0c82 \u0cb9\u0cb0\u0cbf\u0951\u0cae\u0ccd \u0964\n\u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0951\u0cae\u0cc7\u0952\u0cb5\u0cc7\u0ca6\u0c82 \u0caa\u0cc1\u0cb0\u0cc1\u0951\u0cb7\u0952\u0cb8\u0ccd\u0ca4\u0ca6\u0ccd\u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0952\u0cae\u0cc1\u0caa\u0951\u0c9c\u0cc0\u0cb5\u0ca4\u0cbf \u0965 \u0ce8 \u0965", "malayalam": "\u0d35\u0d3f\u0d36\u0d4d\u0d35\u0951\u0d24\u0d03 \u0d2a\u0d30\u0952\u0d2e\u0d3e\u0d28\u0d4d\u0d28\u0d3f\u0952\u0d24\u0d4d\u0d2f\u0d02\u0952 \u0d35\u0d3f\u0952\u0d36\u0d4d\u0d35\u0d02 \u0d28\u0d3e\u0951\u0d30\u0d3e\u0d2f\u0952\u0d23\u0d02 \u0d39\u0d30\u0d3f\u0951\u0d2e\u0d4d \u0964\n\u0d35\u0d3f\u0d36\u0d4d\u0d35\u0951\u0d2e\u0d47\u0952\u0d35\u0d47\u0d26\u0d02 \u0d2a\u0d41\u0d30\u0d41\u0951\u0d37\u0952\u0d38\u0d4d\u0d24\u0d26\u0d4d\u0d35\u0d3f\u0d36\u0d4d\u0d35\u0952\u0d2e\u0d41\u0d2a\u0951\u0d1c\u0d40\u0d35\u0d24\u0d3f \u0965 \u0d68 \u0965", "iast": "vi\u015bva\u032dta\u1e25 para\u0331m\u0101nni\u0331tya\u0331\u1e43 vi\u0331\u015bva\u1e43 n\u0101\u032dr\u0101ya\u0331\u1e47a\u1e43 hari\u032dm |\nvi\u015bva\u032dme\u0331veda\u1e43 pur\u1e77\u1e63a\u0331stadvi\u015bva\u0331mupa\u032dj\u012bvati || 2 ||"},
        draftTranslation: "Narayana is the supreme transcendent reality beyond all cosmos, eternal. Narayana is Hari, the all-pervading universe. This entire cosmos is the Purusha alone; upon Him the whole universe depends for its existence.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 3,
        devanagariText: "\u092a\u0924\u093f\u0902\u0952 \u0935\u093f\u0936\u094d\u0935\u0951\u0938\u094d\u092f\u093e\u0952\u0924\u094d\u092e\u0947\u0936\u094d\u200d\u0935\u0951\u0930\u0902\u0952 \u0936\u093e\u0936\u094d\u0935\u0951\u0924\u0902 \u0936\u093f\u0952\u0935\u092e\u0951\u091a\u094d\u092f\u0941\u0924\u092e\u094d \u0964\n\u0928\u093e\u0952\u0930\u093e\u092f\u0952\u0923\u0902 \u092e\u0951\u0939\u093e\u091c\u094d\u091e\u0947\u0952\u092f\u0902\u0952 \u0935\u093f\u0952\u0936\u094d\u0935\u093e\u0924\u094d\u092e\u093e\u0951\u0928\u0902 \u092a\u0951\u0930\u093e\u092f\u0952\u0923\u092e\u094d \u0965 \u0969 \u0965",
        iastText: "pati\u1e41\u0952 vi\u015bva\u0951sy\u0101\u0952tm\u0113\u015bva\u0951ra\u1e41\u0952 \u015b\u0101\u015bwa\u0951ta\u1e41 \u015bi\u0952vama\u0951cyutam \u0964\nn\u0101\u0952r\u0101ya\u0952\u1e47a\u1e41 ma\u0951h\u0101j\u00f1\u0113\u0952ya\u1e41\u0952 vi\u0952\u015bw\u0101tm\u0101\u0951na\u1e41 pa\u0951r\u0101ya\u0952\u1e47am \u0965 3 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2a\u0c24\u0c3f\u0c02\u0952 \u0c35\u0c3f\u0c36\u0c4d\u0c35\u0951\u0c38\u0c4d\u0c2f\u0c3e\u0952\u0c24\u0c4d\u0c2e\u0c47\u0c36\u0c4d\u200d\u0c35\u0951\u0c30\u0c02\u0952 \u0c36\u0c3e\u0c36\u0c4d\u0c35\u0951\u0c24\u0c02 \u0c36\u0c3f\u0952\u0c35\u0c2e\u0951\u0c1a\u0c4d\u0c2f\u0c41\u0c24\u0c2e\u0c4d \u0964\n\u0c28\u0c3e\u0952\u0c30\u0c3e\u0c2f\u0952\u0c23\u0c02 \u0c2e\u0951\u0c39\u0c3e\u0c1c\u0c4d\u0c1e\u0c47\u0952\u0c2f\u0c02\u0952 \u0c35\u0c3f\u0952\u0c36\u0c4d\u0c35\u0c3e\u0c24\u0c4d\u0c2e\u0c3e\u0951\u0c28\u0c02 \u0c2a\u0951\u0c30\u0c3e\u0c2f\u0952\u0c23\u0c2e\u0c4d \u0965 \u0c69 \u0965", "tamil": "\u0baa\u0ba4\u0bbf\u0bae\u0bcd\u0952 \u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0951\u0bb8\u0bcd\u0baf\u0bbe\u0952\u0ba4\u0bcd\u0bae\u0bc7\u0bb6\u0bcd\u200d\u0bb5\u0951\u0bb0\u0bae\u0bcd\u0952 \u0bb6\u0bbe\u0bb6\u0bcd\u0bb5\u0951\u0ba4\u0bae\u0bcd \u0bb6\u0bbf\u0952\u0bb5\u0bae\u0951\u0b9a\u0bcd\u0baf\u0bc1\u0ba4\u0bae\u0bcd \u0964\n\u0ba8\u0bbe\u0952\u0bb0\u0bbe\u0baf\u0952\u0ba3\u0bae\u0bcd \u0bae\u0951\u0bb9\u0bbe\u0b9c\u0bcd\u0b9e\u0bc7\u0952\u0baf\u0bae\u0bcd\u0952 \u0bb5\u0bbf\u0952\u0bb6\u0bcd\u0bb5\u0bbe\u0ba4\u0bcd\u0bae\u0bbe\u0951\u0ba8\u0bae\u0bcd \u0baa\u0951\u0bb0\u0bbe\u0baf\u0952\u0ba3\u0bae\u0bcd \u0965 \u0be9 \u0965", "kannada": "\u0caa\u0ca4\u0cbf\u0c82\u0952 \u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0951\u0cb8\u0ccd\u0caf\u0cbe\u0952\u0ca4\u0ccd\u0cae\u0cc7\u0cb6\u0ccd\u200d\u0cb5\u0951\u0cb0\u0c82\u0952 \u0cb6\u0cbe\u0cb6\u0ccd\u0cb5\u0951\u0ca4\u0c82 \u0cb6\u0cbf\u0952\u0cb5\u0cae\u0951\u0c9a\u0ccd\u0caf\u0cc1\u0ca4\u0cae\u0ccd \u0964\n\u0ca8\u0cbe\u0952\u0cb0\u0cbe\u0caf\u0952\u0ca3\u0c82 \u0cae\u0951\u0cb9\u0cbe\u0c9c\u0ccd\u0c9e\u0cc7\u0952\u0caf\u0c82\u0952 \u0cb5\u0cbf\u0952\u0cb6\u0ccd\u0cb5\u0cbe\u0ca4\u0ccd\u0cae\u0cbe\u0951\u0ca8\u0c82 \u0caa\u0951\u0cb0\u0cbe\u0caf\u0952\u0ca3\u0cae\u0ccd \u0965 \u0ce9 \u0965", "malayalam": "\u0d2a\u0d24\u0d3f\u0d02\u0952 \u0d35\u0d3f\u0d36\u0d4d\u0d35\u0951\u0d38\u0d4d\u0d2f\u0d3e\u0952\u0d24\u0d4d\u0d2e\u0d47\u0d36\u0d4d\u200d\u0d35\u0951\u0d30\u0d02\u0952 \u0d36\u0d3e\u0d36\u0d4d\u0d35\u0951\u0d24\u0d02 \u0d36\u0d3f\u0952\u0d35\u0d2e\u0951\u0d1a\u0d4d\u0d2f\u0d41\u0d24\u0d2e\u0d4d \u0964\n\u0d28\u0d3e\u0952\u0d30\u0d3e\u0d2f\u0952\u0d23\u0d02 \u0d2e\u0951\u0d39\u0d3e\u0d1c\u0d4d\u0d1e\u0d47\u0952\u0d2f\u0d02\u0952 \u0d35\u0d3f\u0952\u0d36\u0d4d\u0d35\u0d3e\u0d24\u0d4d\u0d2e\u0d3e\u0951\u0d28\u0d02 \u0d2a\u0951\u0d30\u0d3e\u0d2f\u0952\u0d23\u0d2e\u0d4d \u0965 \u0d69 \u0965", "iast": "pati\u0331\u1e43 vi\u015bva\u032dsy\u0101\u0331tme\u015b\u200dva\u032dra\u0331\u1e43 \u015b\u0101\u015bva\u032dta\u1e43 \u015bi\u0331vama\u032dcyutam |\nn\u0101\u0331r\u0101ya\u0331\u1e47a\u1e43 ma\u032dh\u0101j\u00f1e\u0331ya\u0331\u1e43 vi\u0331\u015bv\u0101tm\u0101\u032dna\u1e43 pa\u032dr\u0101ya\u0331\u1e47am || 3 ||"},
        draftTranslation: "He is the Sovereign of the universe, the Lord of all souls, eternal, all-auspicious, and imperishable. Narayana is the supreme object of knowledge, the innermost Soul of the universe, and the supreme refuge of all.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 4,
        devanagariText: "\u0928\u093e\u0952\u0930\u093e\u092f\u0952\u0923\u0903 \u092a\u0951\u0930\u094b \u091c\u094d\u092f\u094b\u0924\u093f\u0952\u0930\u093e\u0952\u0924\u094d\u092e\u093e \u0928\u093e\u0951\u0930\u093e\u092f\u0952\u0923\u0903 \u092a\u0951\u0930\u0903 \u0964\n\u0928\u093e\u0952\u0930\u093e\u092f\u0952\u0923\u0903 \u092a\u0951\u0930\u0902 \u092c\u094d\u0930\u0952\u0939\u094d\u092e\u0952 \u0924\u0924\u094d\u0924\u094d\u0935\u0902 \u0928\u093e\u0951\u0930\u093e\u092f\u0952\u0923\u0903 \u092a\u0951\u0930\u0903 \u0964\n\u0928\u093e\u0952\u0930\u093e\u092f\u0952\u0923\u0903 \u092a\u0951\u0930\u094b \u0927\u094d\u092f\u093e\u0952\u0924\u093e\u0952 \u0927\u094d\u092f\u093e\u0952\u0928\u0902 \u0928\u093e\u0951\u0930\u093e\u092f\u0952\u0923\u0903 \u092a\u0951\u0930\u0903 \u0965 \u096a \u0965",
        iastText: "n\u0101\u0952r\u0101ya\u0952\u1e47a\u1e25 pa\u0951r\u014d jy\u014dti\u0952r\u0101\u0952tm\u0101 n\u0101\u0951raya\u0952\u1e47a\u1e25 pa\u0951ra\u1e25 \u0964\nn\u0101\u0952r\u0101ya\u0952\u1e47a\u1e25 pa\u0951ra\u1e41 bra\u0952hma\u0952 tattva\u1e41 n\u0101\u0951raya\u0952\u1e47a\u1e25 pa\u0951ra\u1e25 \u0964\nn\u0101\u0952r\u0101ya\u0952\u1e47a\u1e25 pa\u0951r\u014d dhy\u0101\u0952t\u0101\u0952 dhy\u0101\u0952na\u1e41 n\u0101\u0951raya\u0952\u1e47a\u1e25 pa\u0951ra\u1e25 \u0965 4 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c28\u0c3e\u0952\u0c30\u0c3e\u0c2f\u0952\u0c23\u0c03 \u0c2a\u0951\u0c30\u0c4b \u0c1c\u0c4d\u0c2f\u0c4b\u0c24\u0c3f\u0952\u0c30\u0c3e\u0952\u0c24\u0c4d\u0c2e\u0c3e \u0c28\u0c3e\u0951\u0c30\u0c3e\u0c2f\u0952\u0c23\u0c03 \u0c2a\u0951\u0c30\u0c03 \u0964\n\u0c28\u0c3e\u0952\u0c30\u0c3e\u0c2f\u0952\u0c23\u0c03 \u0c2a\u0951\u0c30\u0c02 \u0c2c\u0c4d\u0c30\u0952\u0c39\u0c4d\u0c2e\u0952 \u0c24\u0c24\u0c4d\u0c24\u0c4d\u0c35\u0c02 \u0c28\u0c3e\u0951\u0c30\u0c3e\u0c2f\u0952\u0c23\u0c03 \u0c2a\u0951\u0c30\u0c03 \u0964\n\u0c28\u0c3e\u0952\u0c30\u0c3e\u0c2f\u0952\u0c23\u0c03 \u0c2a\u0951\u0c30\u0c4b \u0c27\u0c4d\u0c2f\u0c3e\u0952\u0c24\u0c3e\u0952 \u0c27\u0c4d\u0c2f\u0c3e\u0952\u0c28\u0c02 \u0c28\u0c3e\u0951\u0c30\u0c3e\u0c2f\u0952\u0c23\u0c03 \u0c2a\u0951\u0c30\u0c03 \u0965 \u0c6a \u0965", "tamil": "\u0ba8\u0bbe\u0952\u0bb0\u0bbe\u0baf\u0952\u0ba3\u0b83 \u0baa\u0951\u0bb0\u0bcb \u0b9c\u0bcd\u0baf\u0bcb\u0ba4\u0bbf\u0952\u0bb0\u0bbe\u0952\u0ba4\u0bcd\u0bae\u0bbe \u0ba8\u0bbe\u0951\u0bb0\u0bbe\u0baf\u0952\u0ba3\u0b83 \u0baa\u0951\u0bb0\u0b83 \u0964\n\u0ba8\u0bbe\u0952\u0bb0\u0bbe\u0baf\u0952\u0ba3\u0b83 \u0baa\u0951\u0bb0\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0952\u0bb9\u0bcd\u0bae\u0952 \u0ba4\u0ba4\u0bcd\u0ba4\u0bcd\u0bb5\u0bae\u0bcd \u0ba8\u0bbe\u0951\u0bb0\u0bbe\u0baf\u0952\u0ba3\u0b83 \u0baa\u0951\u0bb0\u0b83 \u0964\n\u0ba8\u0bbe\u0952\u0bb0\u0bbe\u0baf\u0952\u0ba3\u0b83 \u0baa\u0951\u0bb0\u0bcb \u0ba4\u0bcd\u0baf\u0bbe\u0952\u0ba4\u0bbe\u0952 \u0ba4\u0bcd\u0baf\u0bbe\u0952\u0ba8\u0bae\u0bcd \u0ba8\u0bbe\u0951\u0bb0\u0bbe\u0baf\u0952\u0ba3\u0b83 \u0baa\u0951\u0bb0\u0b83 \u0965 \u0bea \u0965", "kannada": "\u0ca8\u0cbe\u0952\u0cb0\u0cbe\u0caf\u0952\u0ca3\u0c83 \u0caa\u0951\u0cb0\u0ccb \u0c9c\u0ccd\u0caf\u0ccb\u0ca4\u0cbf\u0952\u0cb0\u0cbe\u0952\u0ca4\u0ccd\u0cae\u0cbe \u0ca8\u0cbe\u0951\u0cb0\u0cbe\u0caf\u0952\u0ca3\u0c83 \u0caa\u0951\u0cb0\u0c83 \u0964\n\u0ca8\u0cbe\u0952\u0cb0\u0cbe\u0caf\u0952\u0ca3\u0c83 \u0caa\u0951\u0cb0\u0c82 \u0cac\u0ccd\u0cb0\u0952\u0cb9\u0ccd\u0cae\u0952 \u0ca4\u0ca4\u0ccd\u0ca4\u0ccd\u0cb5\u0c82 \u0ca8\u0cbe\u0951\u0cb0\u0cbe\u0caf\u0952\u0ca3\u0c83 \u0caa\u0951\u0cb0\u0c83 \u0964\n\u0ca8\u0cbe\u0952\u0cb0\u0cbe\u0caf\u0952\u0ca3\u0c83 \u0caa\u0951\u0cb0\u0ccb \u0ca7\u0ccd\u0caf\u0cbe\u0952\u0ca4\u0cbe\u0952 \u0ca7\u0ccd\u0caf\u0cbe\u0952\u0ca8\u0c82 \u0ca8\u0cbe\u0951\u0cb0\u0cbe\u0caf\u0952\u0ca3\u0c83 \u0caa\u0951\u0cb0\u0c83 \u0965 \u0cea \u0965", "malayalam": "\u0d28\u0d3e\u0952\u0d30\u0d3e\u0d2f\u0952\u0d23\u0d03 \u0d2a\u0951\u0d30\u0d4b \u0d1c\u0d4d\u0d2f\u0d4b\u0d24\u0d3f\u0952\u0d30\u0d3e\u0952\u0d24\u0d4d\u0d2e\u0d3e \u0d28\u0d3e\u0951\u0d30\u0d3e\u0d2f\u0952\u0d23\u0d03 \u0d2a\u0951\u0d30\u0d03 \u0964\n\u0d28\u0d3e\u0952\u0d30\u0d3e\u0d2f\u0952\u0d23\u0d03 \u0d2a\u0951\u0d30\u0d02 \u0d2c\u0d4d\u0d30\u0952\u0d39\u0d4d\u0d2e\u0952 \u0d24\u0d24\u0d4d\u0d24\u0d4d\u0d35\u0d02 \u0d28\u0d3e\u0951\u0d30\u0d3e\u0d2f\u0952\u0d23\u0d03 \u0d2a\u0951\u0d30\u0d03 \u0964\n\u0d28\u0d3e\u0952\u0d30\u0d3e\u0d2f\u0952\u0d23\u0d03 \u0d2a\u0951\u0d30\u0d4b \u0d27\u0d4d\u0d2f\u0d3e\u0952\u0d24\u0d3e\u0952 \u0d27\u0d4d\u0d2f\u0d3e\u0952\u0d28\u0d02 \u0d28\u0d3e\u0951\u0d30\u0d3e\u0d2f\u0952\u0d23\u0d03 \u0d2a\u0951\u0d30\u0d03 \u0965 \u0d6a \u0965", "iast": "n\u0101\u0331r\u0101ya\u0331\u1e47a\u1e25 pa\u032dro jyoti\u0331r\u0101\u0331tm\u0101 n\u0101\u032dr\u0101ya\u0331\u1e47a\u1e25 pa\u032dra\u1e25 |\nn\u0101\u0331r\u0101ya\u0331\u1e47a\u1e25 pa\u032dra\u1e43 bra\u0331hma\u0331 tattva\u1e43 n\u0101\u032dr\u0101ya\u0331\u1e47a\u1e25 pa\u032dra\u1e25 |\nn\u0101\u0331r\u0101ya\u0331\u1e47a\u1e25 pa\u032dro dhy\u0101\u0331t\u0101\u0331 dhy\u0101\u0331na\u1e43 n\u0101\u032dr\u0101ya\u0331\u1e47a\u1e25 pa\u032dra\u1e25 || 4 ||"},
        draftTranslation: "Narayana is the supreme light. Narayana is the supreme Self. Narayana is the supreme Brahman. Narayana is the supreme truth. Narayana is the supreme meditator, and Narayana is the supreme meditation.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 5,
        devanagariText: "\u092f\u091a\u094d\u091a\u0951 \u0915\u093f\u0952\u091e\u094d\u091a\u093f\u091c\u094d\u091c\u0917\u0951\u0924\u094d\u0938\u0930\u094d\u0935\u0902\u0952 \u0926\u0943\u0952\u0936\u094d\u092f\u0924\u0947\u0951 \u0936\u094d\u0930\u0942\u092f\u0952\u0924\u0947\u093d\u092a\u093f\u0951 \u0935\u093e \u0964\n\u0905\u0928\u094d\u0924\u0951\u0930\u094d\u092c\u0952\u0939\u093f\u0936\u094d\u091a\u0951 \u0924\u0924\u094d\u0938\u0930\u094d\u0935\u0902\u0952 \u0935\u094d\u092f\u093e\u0952\u092a\u094d\u092f \u0928\u093e\u0951\u0930\u093e\u092f\u0952\u0923\u0903 \u0938\u094d\u0925\u093f\u0951\u0924\u0903 \u0965 \u096b \u0965",
        iastText: "yacca\u0951 ki\u0952\u00f1cijjaga\u0951tsarva\u1e41\u0952 d\u1e5b\u0952\u015byat\u0113\u0951 \u015br\u016bya\u0952t\u0113'pi\u0951 v\u0101 \u0964\nanta\u0951rba\u0952hi\u015bca\u0951 tatsarva\u1e41\u0952 vy\u0101\u0952pya n\u0101\u0951raya\u0952\u1e47a\u1e25 sthi\u0951ta\u1e25 \u0965 5 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2f\u0c1a\u0c4d\u0c1a\u0951 \u0c15\u0c3f\u0952\u0c1e\u0c4d\u0c1a\u0c3f\u0c1c\u0c4d\u0c1c\u0c17\u0951\u0c24\u0c4d\u0c38\u0c30\u0c4d\u0c35\u0c02\u0952 \u0c26\u0c43\u0952\u0c36\u0c4d\u0c2f\u0c24\u0c47\u0951 \u0c36\u0c4d\u0c30\u0c42\u0c2f\u0952\u0c24\u0c47\u0c3d\u0c2a\u0c3f\u0951 \u0c35\u0c3e \u0964\n\u0c05\u0c28\u0c4d\u0c24\u0951\u0c30\u0c4d\u0c2c\u0952\u0c39\u0c3f\u0c36\u0c4d\u0c1a\u0951 \u0c24\u0c24\u0c4d\u0c38\u0c30\u0c4d\u0c35\u0c02\u0952 \u0c35\u0c4d\u0c2f\u0c3e\u0952\u0c2a\u0c4d\u0c2f \u0c28\u0c3e\u0951\u0c30\u0c3e\u0c2f\u0952\u0c23\u0c03 \u0c38\u0c4d\u0c25\u0c3f\u0951\u0c24\u0c03 \u0965 \u0c6b \u0965", "tamil": "\u0baf\u0b9a\u0bcd\u0b9a\u0951 \u0b95\u0bbf\u0952\u0b9e\u0bcd\u0b9a\u0bbf\u0b9c\u0bcd\u0b9c\u0b95\u0951\u0ba4\u0bcd\u0bb8\u0bb0\u0bcd\u0bb5\u0bae\u0bcd\u0952 \u0ba4\u0bcd\u0bb0\u0bc1'\u0952\u0bb6\u0bcd\u0baf\u0ba4\u0bc7\u0951 \u0bb6\u0bcd\u0bb0\u0bc2\u0baf\u0952\u0ba4\u0bc7\u093d\u0baa\u0bbf\u0951 \u0bb5\u0bbe \u0964\n\u0b85\u0ba8\u0bcd\u0ba4\u0951\u0bb0\u0bcd\u0baa\u0952\u0bb9\u0bbf\u0bb6\u0bcd\u0b9a\u0951 \u0ba4\u0ba4\u0bcd\u0bb8\u0bb0\u0bcd\u0bb5\u0bae\u0bcd\u0952 \u0bb5\u0bcd\u0baf\u0bbe\u0952\u0baa\u0bcd\u0baf \u0ba8\u0bbe\u0951\u0bb0\u0bbe\u0baf\u0952\u0ba3\u0b83 \u0bb8\u0bcd\u0ba4\u0bbf\u0951\u0ba4\u0b83 \u0965 \u0beb \u0965", "kannada": "\u0caf\u0c9a\u0ccd\u0c9a\u0951 \u0c95\u0cbf\u0952\u0c9e\u0ccd\u0c9a\u0cbf\u0c9c\u0ccd\u0c9c\u0c97\u0951\u0ca4\u0ccd\u0cb8\u0cb0\u0ccd\u0cb5\u0c82\u0952 \u0ca6\u0cc3\u0952\u0cb6\u0ccd\u0caf\u0ca4\u0cc7\u0951 \u0cb6\u0ccd\u0cb0\u0cc2\u0caf\u0952\u0ca4\u0cc7\u0cbd\u0caa\u0cbf\u0951 \u0cb5\u0cbe \u0964\n\u0c85\u0ca8\u0ccd\u0ca4\u0951\u0cb0\u0ccd\u0cac\u0952\u0cb9\u0cbf\u0cb6\u0ccd\u0c9a\u0951 \u0ca4\u0ca4\u0ccd\u0cb8\u0cb0\u0ccd\u0cb5\u0c82\u0952 \u0cb5\u0ccd\u0caf\u0cbe\u0952\u0caa\u0ccd\u0caf \u0ca8\u0cbe\u0951\u0cb0\u0cbe\u0caf\u0952\u0ca3\u0c83 \u0cb8\u0ccd\u0ca5\u0cbf\u0951\u0ca4\u0c83 \u0965 \u0ceb \u0965", "malayalam": "\u0d2f\u0d1a\u0d4d\u0d1a\u0951 \u0d15\u0d3f\u0952\u0d1e\u0d4d\u0d1a\u0d3f\u0d1c\u0d4d\u0d1c\u0d17\u0951\u0d24\u0d4d\u0d38\u0d30\u0d4d\u0d35\u0d02\u0952 \u0d26\u0d43\u0952\u0d36\u0d4d\u0d2f\u0d24\u0d47\u0951 \u0d36\u0d4d\u0d30\u0d42\u0d2f\u0952\u0d24\u0d47\u0d3d\u0d2a\u0d3f\u0951 \u0d35\u0d3e \u0964\n\u0d05\u0d28\u0d4d\u0d24\u0951\u0d30\u0d4d\u0d2c\u0952\u0d39\u0d3f\u0d36\u0d4d\u0d1a\u0951 \u0d24\u0d24\u0d4d\u0d38\u0d30\u0d4d\u0d35\u0d02\u0952 \u0d35\u0d4d\u0d2f\u0d3e\u0952\u0d2a\u0d4d\u0d2f \u0d28\u0d3e\u0951\u0d30\u0d3e\u0d2f\u0952\u0d23\u0d03 \u0d38\u0d4d\u0d25\u0d3f\u0951\u0d24\u0d03 \u0965 \u0d6b \u0965", "iast": "yacca\u032d ki\u0331\u00f1cijjaga\u032dtsarva\u0331\u1e43 d\u1e5b\u0331\u015byat\u1e19 \u015br\u016bya\u0331te'pi\u032d v\u0101 |\nanta\u032drba\u0331hi\u015bca\u032d tatsarva\u0331\u1e43 vy\u0101\u0331pya n\u0101\u032dr\u0101ya\u0331\u1e47a\u1e25 sthi\u032dta\u1e25 || 5 ||"},
        draftTranslation: "Whatever exists in this universe, whether seen or heard \u2014 Narayana pervades all of that completely, both from within and from without.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 6,
        devanagariText: "\u0905\u0928\u0951\u0928\u094d\u0924\u0952\u092e\u0935\u094d\u092f\u0951\u092f\u0902 \u0915\u0952\u0935\u093f\u0902 \u0938\u092e\u0941\u0952\u0926\u094d\u0930\u0947\u093d\u0928\u094d\u0924\u0902\u0951 \u0935\u093f\u0952\u0936\u094d\u0935\u0936\u0951\u092e\u094d\u092d\u0941\u0935\u092e\u094d \u0964\n\u092a\u0952\u0926\u094d\u092e\u0952\u0915\u094b\u0952\u0936\u092a\u094d\u0930\u0951\u0924\u0940\u0915\u093e\u0952\u0936\u0902\u0952 \u0939\u0943\u0952\u0926\u092f\u0902\u0951 \u091a\u093e\u092a\u094d\u092f\u0927\u094b\u092e\u0941\u0916\u092e\u094d \u0965 \u096c \u0965",
        iastText: "ana\u0951nta\u0952mavya\u0951ya\u1e41 ka\u0952vi\u1e41 samu\u0952dr\u0113'nta\u1e41\u0951 vi\u0952\u015bva\u015ba\u0951mbhuvam \u0964\npa\u0952dma\u0952k\u014d\u0952\u015bapra\u0951t\u012bk\u0101\u0952\u015ba\u1e41\u0952 h\u1e5b\u0952daya\u1e41\u0951 c\u0101pyadh\u014dmukham \u0965 6 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c05\u0c28\u0951\u0c28\u0c4d\u0c24\u0952\u0c2e\u0c35\u0c4d\u0c2f\u0951\u0c2f\u0c02 \u0c15\u0952\u0c35\u0c3f\u0c02 \u0c38\u0c2e\u0c41\u0952\u0c26\u0c4d\u0c30\u0c47\u0c3d\u0c28\u0c4d\u0c24\u0c02\u0951 \u0c35\u0c3f\u0952\u0c36\u0c4d\u0c35\u0c36\u0951\u0c2e\u0c4d\u0c2d\u0c41\u0c35\u0c2e\u0c4d \u0964\n\u0c2a\u0952\u0c26\u0c4d\u0c2e\u0952\u0c15\u0c4b\u0952\u0c36\u0c2a\u0c4d\u0c30\u0951\u0c24\u0c40\u0c15\u0c3e\u0952\u0c36\u0c02\u0952 \u0c39\u0c43\u0952\u0c26\u0c2f\u0c02\u0951 \u0c1a\u0c3e\u0c2a\u0c4d\u0c2f\u0c27\u0c4b\u0c2e\u0c41\u0c16\u0c2e\u0c4d \u0965 \u0c6c \u0965", "tamil": "\u0b85\u0ba8\u0951\u0ba8\u0bcd\u0ba4\u0952\u0bae\u0bb5\u0bcd\u0baf\u0951\u0baf\u0bae\u0bcd \u0b95\u0952\u0bb5\u0bbf\u0bae\u0bcd \u0bb8\u0bae\u0bc1\u0952\u0ba4\u0bcd\u0bb0\u0bc7\u093d\u0ba8\u0bcd\u0ba4\u0bae\u0bcd\u0951 \u0bb5\u0bbf\u0952\u0bb6\u0bcd\u0bb5\u0bb6\u0951\u0bae\u0bcd\u0baa\u0bc1\u0bb5\u0bae\u0bcd \u0964\n\u0baa\u0952\u0ba4\u0bcd\u0bae\u0952\u0b95\u0bcb\u0952\u0bb6\u0baa\u0bcd\u0bb0\u0951\u0ba4\u0bc0\u0b95\u0bbe\u0952\u0bb6\u0bae\u0bcd\u0952 \u0bb9\u0bcd\u0bb0\u0bc1'\u0952\u0ba4\u0baf\u0bae\u0bcd\u0951 \u0b9a\u0bbe\u0baa\u0bcd\u0baf\u0ba4\u0bcb\u0bae\u0bc1\u0b95\u0bae\u0bcd \u0965 \u0bec \u0965", "kannada": "\u0c85\u0ca8\u0951\u0ca8\u0ccd\u0ca4\u0952\u0cae\u0cb5\u0ccd\u0caf\u0951\u0caf\u0c82 \u0c95\u0952\u0cb5\u0cbf\u0c82 \u0cb8\u0cae\u0cc1\u0952\u0ca6\u0ccd\u0cb0\u0cc7\u0cbd\u0ca8\u0ccd\u0ca4\u0c82\u0951 \u0cb5\u0cbf\u0952\u0cb6\u0ccd\u0cb5\u0cb6\u0951\u0cae\u0ccd\u0cad\u0cc1\u0cb5\u0cae\u0ccd \u0964\n\u0caa\u0952\u0ca6\u0ccd\u0cae\u0952\u0c95\u0ccb\u0952\u0cb6\u0caa\u0ccd\u0cb0\u0951\u0ca4\u0cc0\u0c95\u0cbe\u0952\u0cb6\u0c82\u0952 \u0cb9\u0cc3\u0952\u0ca6\u0caf\u0c82\u0951 \u0c9a\u0cbe\u0caa\u0ccd\u0caf\u0ca7\u0ccb\u0cae\u0cc1\u0c96\u0cae\u0ccd \u0965 \u0cec \u0965", "malayalam": "\u0d05\u0d28\u0951\u0d28\u0d4d\u0d24\u0952\u0d2e\u0d35\u0d4d\u0d2f\u0951\u0d2f\u0d02 \u0d15\u0952\u0d35\u0d3f\u0d02 \u0d38\u0d2e\u0d41\u0952\u0d26\u0d4d\u0d30\u0d47\u0d3d\u0d28\u0d4d\u0d24\u0d02\u0951 \u0d35\u0d3f\u0952\u0d36\u0d4d\u0d35\u0d36\u0951\u0d2e\u0d4d\u0d2d\u0d41\u0d35\u0d2e\u0d4d \u0964\n\u0d2a\u0952\u0d26\u0d4d\u0d2e\u0952\u0d15\u0d4b\u0952\u0d36\u0d2a\u0d4d\u0d30\u0951\u0d24\u0d40\u0d15\u0d3e\u0952\u0d36\u0d02\u0952 \u0d39\u0d43\u0952\u0d26\u0d2f\u0d02\u0951 \u0d1a\u0d3e\u0d2a\u0d4d\u0d2f\u0d27\u0d4b\u0d2e\u0d41\u0d16\u0d2e\u0d4d \u0965 \u0d6c \u0965", "iast": "ana\u032dnta\u0331mavya\u032dya\u1e43 ka\u0331vi\u1e43 samu\u0331dre'nta\u032d\u1e43 vi\u0331\u015bva\u015ba\u032dmbhuvam |\npa\u0331dma\u0331ko\u0331\u015bapra\u032dt\u012bk\u0101\u0331\u015ba\u0331\u1e43 h\u1e5b\u0331daya\u032d\u1e43 c\u0101pyadhomukham || 6 ||"},
        draftTranslation: "The infinite, imperishable, all-seeing Seer, who resides in the cosmic waters of consciousness, the source of supreme auspiciousness! Resembling an inverted lotus bud is the subtle spiritual heart.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 7,
        devanagariText: "\u0905\u0927\u094b\u0951 \u0928\u093f\u0952\u0937\u094d\u091f\u094d\u092f\u093e \u0935\u093f\u0951\u0924\u0938\u094d\u0924\u094d\u092f\u093e\u0952\u0928\u094d\u0924\u0947\u0952 \u0928\u093e\u092d\u094d\u092f\u093e\u0951\u092e\u0941\u092a\u0951\u0930\u093f \u0924\u093f\u0937\u094d\u0920\u0924\u093f \u0964\n\u091c\u094d\u0935\u093e\u0952\u0932\u0952\u092e\u093e\u0952\u0932\u093e\u0915\u0941\u0951\u0932\u0902 \u092d\u093e\u0952\u0924\u0940\u0952 \u0935\u093f\u0952\u0936\u094d\u0935\u0938\u094d\u092f\u093e\u0951\u092f\u0924\u0952\u0928\u0902 \u092e\u0951\u0939\u0924\u094d \u0965 \u096d \u0965",
        iastText: "adh\u014d\u0951 ni\u0952\u1e63\u1e6dy\u0101 vi\u0951tasty\u0101\u0952nt\u0113\u0952 n\u0101bhy\u0101\u0951mupa\u0951ri ti\u1e63\u1e6dhati \u0964\njv\u0101\u0952la\u0952m\u0101\u0952l\u0101ku\u0951la\u1e41 bh\u0101\u0952t\u012b\u0952 vi\u0952\u015bvasy\u0101\u0951yata\u0952na\u1e41 ma\u0951hat \u0965 7 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c05\u0c27\u0c4b\u0951 \u0c28\u0c3f\u0952\u0c37\u0c4d\u0c1f\u0c4d\u0c2f\u0c3e \u0c35\u0c3f\u0951\u0c24\u0c38\u0c4d\u0c24\u0c4d\u0c2f\u0c3e\u0952\u0c28\u0c4d\u0c24\u0c47\u0952 \u0c28\u0c3e\u0c2d\u0c4d\u0c2f\u0c3e\u0951\u0c2e\u0c41\u0c2a\u0951\u0c30\u0c3f \u0c24\u0c3f\u0c37\u0c4d\u0c20\u0c24\u0c3f \u0964\n\u0c1c\u0c4d\u0c35\u0c3e\u0952\u0c32\u0952\u0c2e\u0c3e\u0952\u0c32\u0c3e\u0c15\u0c41\u0951\u0c32\u0c02 \u0c2d\u0c3e\u0952\u0c24\u0c40\u0952 \u0c35\u0c3f\u0952\u0c36\u0c4d\u0c35\u0c38\u0c4d\u0c2f\u0c3e\u0951\u0c2f\u0c24\u0952\u0c28\u0c02 \u0c2e\u0951\u0c39\u0c24\u0c4d \u0965 \u0c6d \u0965", "tamil": "\u0b85\u0ba4\u0bcb\u0951 \u0ba8\u0bbf\u0952\u0bb7\u0bcd\u0b9f\u0bcd\u0baf\u0bbe \u0bb5\u0bbf\u0951\u0ba4\u0bb8\u0bcd\u0ba4\u0bcd\u0baf\u0bbe\u0952\u0ba8\u0bcd\u0ba4\u0bc7\u0952 \u0ba8\u0bbe\u0baa\u0bcd\u0baf\u0bbe\u0951\u0bae\u0bc1\u0baa\u0951\u0bb0\u0bbf \u0ba4\u0bbf\u0bb7\u0bcd\u0b9f\u0ba4\u0bbf \u0964\n\u0b9c\u0bcd\u0bb5\u0bbe\u0952\u0bb2\u0952\u0bae\u0bbe\u0952\u0bb2\u0bbe\u0b95\u0bc1\u0951\u0bb2\u0bae\u0bcd \u0baa\u0bbe\u0952\u0ba4\u0bc0\u0952 \u0bb5\u0bbf\u0952\u0bb6\u0bcd\u0bb5\u0bb8\u0bcd\u0baf\u0bbe\u0951\u0baf\u0ba4\u0952\u0ba8\u0bae\u0bcd \u0bae\u0951\u0bb9\u0ba4\u0bcd \u0965 \u0bed \u0965", "kannada": "\u0c85\u0ca7\u0ccb\u0951 \u0ca8\u0cbf\u0952\u0cb7\u0ccd\u0c9f\u0ccd\u0caf\u0cbe \u0cb5\u0cbf\u0951\u0ca4\u0cb8\u0ccd\u0ca4\u0ccd\u0caf\u0cbe\u0952\u0ca8\u0ccd\u0ca4\u0cc7\u0952 \u0ca8\u0cbe\u0cad\u0ccd\u0caf\u0cbe\u0951\u0cae\u0cc1\u0caa\u0951\u0cb0\u0cbf \u0ca4\u0cbf\u0cb7\u0ccd\u0ca0\u0ca4\u0cbf \u0964\n\u0c9c\u0ccd\u0cb5\u0cbe\u0952\u0cb2\u0952\u0cae\u0cbe\u0952\u0cb2\u0cbe\u0c95\u0cc1\u0951\u0cb2\u0c82 \u0cad\u0cbe\u0952\u0ca4\u0cc0\u0952 \u0cb5\u0cbf\u0952\u0cb6\u0ccd\u0cb5\u0cb8\u0ccd\u0caf\u0cbe\u0951\u0caf\u0ca4\u0952\u0ca8\u0c82 \u0cae\u0951\u0cb9\u0ca4\u0ccd \u0965 \u0ced \u0965", "malayalam": "\u0d05\u0d27\u0d4b\u0951 \u0d28\u0d3f\u0952\u0d37\u0d4d\u0d1f\u0d4d\u0d2f\u0d3e \u0d35\u0d3f\u0951\u0d24\u0d38\u0d4d\u0d24\u0d4d\u0d2f\u0d3e\u0952\u0d28\u0d4d\u0d24\u0d47\u0952 \u0d28\u0d3e\u0d2d\u0d4d\u0d2f\u0d3e\u0951\u0d2e\u0d41\u0d2a\u0951\u0d30\u0d3f \u0d24\u0d3f\u0d37\u0d4d\u0d20\u0d24\u0d3f \u0964\n\u0d1c\u0d4d\u0d35\u0d3e\u0952\u0d32\u0952\u0d2e\u0d3e\u0952\u0d32\u0d3e\u0d15\u0d41\u0951\u0d32\u0d02 \u0d2d\u0d3e\u0952\u0d24\u0d40\u0952 \u0d35\u0d3f\u0952\u0d36\u0d4d\u0d35\u0d38\u0d4d\u0d2f\u0d3e\u0951\u0d2f\u0d24\u0952\u0d28\u0d02 \u0d2e\u0951\u0d39\u0d24\u0d4d \u0965 \u0d6d \u0965", "iast": "adho\u032d ni\u0331\u1e63\u1e6dy\u0101 vi\u032dtasty\u0101\u0331nte\u0331 n\u0101bhy\u0101\u032dmupa\u032dri ti\u1e63\u1e6dhati |\njv\u0101\u0331la\u0331m\u0101\u0331l\u0101k\u1e77la\u1e43 bh\u0101\u0331t\u012b\u0331 vi\u0331\u015bvasy\u0101\u032dyata\u0331na\u1e43 ma\u032dhat || 7 ||"},
        draftTranslation: "Located below the throat and a span (vitasti) above the navel, glowing with a garland of celestial flames, stands that great sanctuary of the entire universe.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 8,
        devanagariText: "\u0938\u0952\u0928\u094d\u0924\u0952\u0924\u0902 \u0936\u093f\u0952\u0932\u093e\u092d\u093f\u0951\u0938\u094d\u0924\u0941\u0952 \u0932\u092e\u094d\u092c\u0951\u0924\u094d\u092f\u093e\u0915\u094b\u0936\u0952\u0938\u0928\u094d\u0928\u093f\u0951\u092d\u092e\u094d \u0964\n\u0924\u0938\u094d\u092f\u093e\u0928\u094d\u0924\u0947\u0951 \u0938\u0941\u0937\u093f\u0952\u0930\u0902 \u0938\u0942\u0952\u0915\u094d\u0937\u094d\u092e\u0902 \u0924\u0938\u094d\u092e\u093f\u0951\u0928\u094d\u0924\u094d\u0938\u0930\u094d\u0935\u0902\u0952 \u092a\u094d\u0930\u0924\u093f\u0951\u0937\u094d\u0920\u093f\u0924\u092e\u094d \u0965 \u096e \u0965",
        iastText: "sa\u0952nta\u0952ta\u1e41 \u015bi\u0952l\u0101bhi\u0951stu\u0952 lamba\u0951ty\u0101k\u014d\u015ba\u0952sanni\u0951bham \u0964\ntasy\u0101nt\u0113\u0951 su\u1e63i\u0952ra\u1e41 s\u016b\u0952k\u1e63ma\u1e41 tasmi\u0951ntsarva\u1e41\u0952 prati\u0951\u1e63\u1e6dhitam \u0965 8 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0952\u0c28\u0c4d\u0c24\u0952\u0c24\u0c02 \u0c36\u0c3f\u0952\u0c32\u0c3e\u0c2d\u0c3f\u0951\u0c38\u0c4d\u0c24\u0c41\u0952 \u0c32\u0c2e\u0c4d\u0c2c\u0951\u0c24\u0c4d\u0c2f\u0c3e\u0c15\u0c4b\u0c36\u0952\u0c38\u0c28\u0c4d\u0c28\u0c3f\u0951\u0c2d\u0c2e\u0c4d \u0964\n\u0c24\u0c38\u0c4d\u0c2f\u0c3e\u0c28\u0c4d\u0c24\u0c47\u0951 \u0c38\u0c41\u0c37\u0c3f\u0952\u0c30\u0c02 \u0c38\u0c42\u0952\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c02 \u0c24\u0c38\u0c4d\u0c2e\u0c3f\u0951\u0c28\u0c4d\u0c24\u0c4d\u0c38\u0c30\u0c4d\u0c35\u0c02\u0952 \u0c2a\u0c4d\u0c30\u0c24\u0c3f\u0951\u0c37\u0c4d\u0c20\u0c3f\u0c24\u0c2e\u0c4d \u0965 \u0c6e \u0965", "tamil": "\u0bb8\u0952\u0ba8\u0bcd\u0ba4\u0952\u0ba4\u0bae\u0bcd \u0bb6\u0bbf\u0952\u0bb2\u0bbe\u0baa\u0bbf\u0951\u0bb8\u0bcd\u0ba4\u0bc1\u0952 \u0bb2\u0bae\u0bcd\u0baa\u0951\u0ba4\u0bcd\u0baf\u0bbe\u0b95\u0bcb\u0bb6\u0952\u0bb8\u0ba8\u0bcd\u0ba8\u0bbf\u0951\u0baa\u0bae\u0bcd \u0964\n\u0ba4\u0bb8\u0bcd\u0baf\u0bbe\u0ba8\u0bcd\u0ba4\u0bc7\u0951 \u0bb8\u0bc1\u0bb7\u0bbf\u0952\u0bb0\u0bae\u0bcd \u0bb8\u0bc2\u0952\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bae\u0bcd \u0ba4\u0bb8\u0bcd\u0bae\u0bbf\u0951\u0ba8\u0bcd\u0ba4\u0bcd\u0bb8\u0bb0\u0bcd\u0bb5\u0bae\u0bcd\u0952 \u0baa\u0bcd\u0bb0\u0ba4\u0bbf\u0951\u0bb7\u0bcd\u0b9f\u0bbf\u0ba4\u0bae\u0bcd \u0965 \u0bee \u0965", "kannada": "\u0cb8\u0952\u0ca8\u0ccd\u0ca4\u0952\u0ca4\u0c82 \u0cb6\u0cbf\u0952\u0cb2\u0cbe\u0cad\u0cbf\u0951\u0cb8\u0ccd\u0ca4\u0cc1\u0952 \u0cb2\u0cae\u0ccd\u0cac\u0951\u0ca4\u0ccd\u0caf\u0cbe\u0c95\u0ccb\u0cb6\u0952\u0cb8\u0ca8\u0ccd\u0ca8\u0cbf\u0951\u0cad\u0cae\u0ccd \u0964\n\u0ca4\u0cb8\u0ccd\u0caf\u0cbe\u0ca8\u0ccd\u0ca4\u0cc7\u0951 \u0cb8\u0cc1\u0cb7\u0cbf\u0952\u0cb0\u0c82 \u0cb8\u0cc2\u0952\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0c82 \u0ca4\u0cb8\u0ccd\u0cae\u0cbf\u0951\u0ca8\u0ccd\u0ca4\u0ccd\u0cb8\u0cb0\u0ccd\u0cb5\u0c82\u0952 \u0caa\u0ccd\u0cb0\u0ca4\u0cbf\u0951\u0cb7\u0ccd\u0ca0\u0cbf\u0ca4\u0cae\u0ccd \u0965 \u0cee \u0965", "malayalam": "\u0d38\u0952\u0d28\u0d4d\u0d24\u0952\u0d24\u0d02 \u0d36\u0d3f\u0952\u0d32\u0d3e\u0d2d\u0d3f\u0951\u0d38\u0d4d\u0d24\u0d41\u0952 \u0d32\u0d2e\u0d4d\u0d2c\u0951\u0d24\u0d4d\u0d2f\u0d3e\u0d15\u0d4b\u0d36\u0952\u0d38\u0d28\u0d4d\u0d28\u0d3f\u0951\u0d2d\u0d2e\u0d4d \u0964\n\u0d24\u0d38\u0d4d\u0d2f\u0d3e\u0d28\u0d4d\u0d24\u0d47\u0951 \u0d38\u0d41\u0d37\u0d3f\u0952\u0d30\u0d02 \u0d38\u0d42\u0952\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d02 \u0d24\u0d38\u0d4d\u0d2e\u0d3f\u0951\u0d28\u0d4d\u0d24\u0d4d\u0d38\u0d30\u0d4d\u0d35\u0d02\u0952 \u0d2a\u0d4d\u0d30\u0d24\u0d3f\u0951\u0d37\u0d4d\u0d20\u0d3f\u0d24\u0d2e\u0d4d \u0965 \u0d6e \u0965", "iast": "sa\u0331nta\u0331ta\u1e43 \u015bi\u0331l\u0101bhi\u032dstu\u0331 lamba\u032dty\u0101ko\u015ba\u0331sanni\u032dbham |\ntasy\u0101nt\u1e19 su\u1e63i\u0331ra\u1e43 s\u016b\u0331k\u1e63ma\u1e43 tasmi\u032dntsarva\u0331\u1e43 prati\u032d\u1e63\u1e6dhitam || 8 ||"},
        draftTranslation: "Surrounded by delicate veins (nadis), hanging like an unopened flower bud, at its apex is a subtle microscopic aperture (sushira); in that subtle space, everything in creation is established.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 9,
        devanagariText: "\u0924\u0938\u094d\u092f\u0952 \u092e\u0927\u094d\u092f\u0947\u0902\u0951 \u092e\u0952\u0939\u093e\u0928\u0951\u0917\u094d\u0928\u093f\u0952\u0930\u094d\u0935\u093f\u0936\u094d\u0935\u093e\u0930\u094d\u091a\u093f\u0951\u0930\u094d\u0935\u093f\u0952\u0936\u094d\u0935\u0924\u094b\u0951\u092e\u0941\u0916\u0903 \u0964\n\u0938\u094b\u093d\u0917\u094d\u0930\u0951\u092d\u0941\u0952\u0917\u094d\u0935\u093f\u092d\u0951\u091c\u0928\u094d\u0924\u093f\u0952\u0937\u094d\u0920\u0952\u0928\u094d\u0928\u093e\u0939\u093e\u0951\u0930\u092e\u091c\u0952\u0930\u0903 \u0915\u0952\u0935\u093f\u0903 \u0965 \u096f \u0965",
        iastText: "tasya\u0952 madhy\u0113\u0951 ma\u0952h\u0101na\u0951gni\u0952rvi\u015bv\u0101rci\u0951rvi\u0952\u015bvat\u014d\u0951mukha\u1e25 \u0964\ns\u014d'gra\u0951bhu\u0952gvibha\u0951janti\u0952\u1e63\u1e6dha\u0952nn\u0101h\u0101\u0951ramaja\u0952ra\u1e25 ka\u0952vi\u1e25 \u0965 9 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c24\u0c38\u0c4d\u0c2f\u0952 \u0c2e\u0c27\u0c4d\u0c2f\u0c47\u0c02\u0951 \u0c2e\u0952\u0c39\u0c3e\u0c28\u0951\u0c17\u0c4d\u0c28\u0c3f\u0952\u0c30\u0c4d\u0c35\u0c3f\u0c36\u0c4d\u0c35\u0c3e\u0c30\u0c4d\u0c1a\u0c3f\u0951\u0c30\u0c4d\u0c35\u0c3f\u0952\u0c36\u0c4d\u0c35\u0c24\u0c4b\u0951\u0c2e\u0c41\u0c16\u0c03 \u0964\n\u0c38\u0c4b\u0c3d\u0c17\u0c4d\u0c30\u0951\u0c2d\u0c41\u0952\u0c17\u0c4d\u0c35\u0c3f\u0c2d\u0951\u0c1c\u0c28\u0c4d\u0c24\u0c3f\u0952\u0c37\u0c4d\u0c20\u0952\u0c28\u0c4d\u0c28\u0c3e\u0c39\u0c3e\u0951\u0c30\u0c2e\u0c1c\u0952\u0c30\u0c03 \u0c15\u0952\u0c35\u0c3f\u0c03 \u0965 \u0c6f \u0965", "tamil": "\u0ba4\u0bb8\u0bcd\u0baf\u0952 \u0bae\u0ba4\u0bcd\u0baf\u0bc7\u0bae\u0bcd\u0951 \u0bae\u0952\u0bb9\u0bbe\u0ba8\u0951\u0b95\u0bcd\u0ba8\u0bbf\u0952\u0bb0\u0bcd\u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0bbe\u0bb0\u0bcd\u0b9a\u0bbf\u0951\u0bb0\u0bcd\u0bb5\u0bbf\u0952\u0bb6\u0bcd\u0bb5\u0ba4\u0bcb\u0951\u0bae\u0bc1\u0b95\u0b83 \u0964\n\u0bb8\u0bcb\u093d\u0b95\u0bcd\u0bb0\u0951\u0baa\u0bc1\u0952\u0b95\u0bcd\u0bb5\u0bbf\u0baa\u0951\u0b9c\u0ba8\u0bcd\u0ba4\u0bbf\u0952\u0bb7\u0bcd\u0b9f\u0952\u0ba8\u0bcd\u0ba8\u0bbe\u0bb9\u0bbe\u0951\u0bb0\u0bae\u0b9c\u0952\u0bb0\u0b83 \u0b95\u0952\u0bb5\u0bbf\u0b83 \u0965 \u0bef \u0965", "kannada": "\u0ca4\u0cb8\u0ccd\u0caf\u0952 \u0cae\u0ca7\u0ccd\u0caf\u0cc7\u0c82\u0951 \u0cae\u0952\u0cb9\u0cbe\u0ca8\u0951\u0c97\u0ccd\u0ca8\u0cbf\u0952\u0cb0\u0ccd\u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0cbe\u0cb0\u0ccd\u0c9a\u0cbf\u0951\u0cb0\u0ccd\u0cb5\u0cbf\u0952\u0cb6\u0ccd\u0cb5\u0ca4\u0ccb\u0951\u0cae\u0cc1\u0c96\u0c83 \u0964\n\u0cb8\u0ccb\u0cbd\u0c97\u0ccd\u0cb0\u0951\u0cad\u0cc1\u0952\u0c97\u0ccd\u0cb5\u0cbf\u0cad\u0951\u0c9c\u0ca8\u0ccd\u0ca4\u0cbf\u0952\u0cb7\u0ccd\u0ca0\u0952\u0ca8\u0ccd\u0ca8\u0cbe\u0cb9\u0cbe\u0951\u0cb0\u0cae\u0c9c\u0952\u0cb0\u0c83 \u0c95\u0952\u0cb5\u0cbf\u0c83 \u0965 \u0cef \u0965", "malayalam": "\u0d24\u0d38\u0d4d\u0d2f\u0952 \u0d2e\u0d27\u0d4d\u0d2f\u0d47\u0d02\u0951 \u0d2e\u0952\u0d39\u0d3e\u0d28\u0951\u0d17\u0d4d\u0d28\u0d3f\u0952\u0d30\u0d4d\u0d35\u0d3f\u0d36\u0d4d\u0d35\u0d3e\u0d30\u0d4d\u0d1a\u0d3f\u0951\u0d30\u0d4d\u0d35\u0d3f\u0952\u0d36\u0d4d\u0d35\u0d24\u0d4b\u0951\u0d2e\u0d41\u0d16\u0d03 \u0964\n\u0d38\u0d4b\u0d3d\u0d17\u0d4d\u0d30\u0951\u0d2d\u0d41\u0952\u0d17\u0d4d\u0d35\u0d3f\u0d2d\u0951\u0d1c\u0d28\u0d4d\u0d24\u0d3f\u0952\u0d37\u0d4d\u0d20\u0952\u0d28\u0d4d\u0d28\u0d3e\u0d39\u0d3e\u0951\u0d30\u0d2e\u0d1c\u0952\u0d30\u0d03 \u0d15\u0952\u0d35\u0d3f\u0d03 \u0965 \u0d6f \u0965", "iast": "tasya\u0331 madhy\u1e19\u1e43 ma\u0331h\u0101na\u032dgni\u0331rvi\u015bv\u0101rci\u032drvi\u0331\u015bvato\u032dmukha\u1e25 |\nso'gra\u032dbhu\u0331gvibha\u032djanti\u0331\u1e63\u1e6dha\u0331nn\u0101h\u0101\u032dramaja\u0331ra\u1e25 ka\u0331vi\u1e25 || 9 ||"},
        draftTranslation: "In the center of that heart-space burns a great cosmic fire, radiating all rays, facing every direction. He is the first consumer of nourishment, distributing it throughout the body, ageless and all-knowing.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 10,
        devanagariText: "\u0924\u093f\u0952\u0930\u094d\u092f\u0952\u0917\u0942\u0952\u0930\u094d\u0927\u094d\u0935\u092e\u0951\u0927\u0903\u0936\u093e\u0952\u092f\u0940\u0952 \u0930\u0952\u0936\u094d\u092e\u092f\u0951\u0938\u094d\u0924\u0938\u094d\u092f \u0938\u0928\u094d\u0924\u0924\u093e\u0903 \u0964\n\u0938\u0952\u0928\u094d\u0924\u093e\u0952\u092a\u092f\u0951\u0924\u093f \u0938\u094d\u0935\u0902 \u0926\u0947\u0952\u0939\u092e\u093e\u092a\u093e\u0951\u0926\u0924\u0932\u092e\u0938\u094d\u0924\u0952\u0915\u0903 \u0965 \u0967\u0966 \u0965",
        iastText: "ti\u0952rya\u0952g\u016b\u0952rdhvama\u0951dha\u1e25\u015b\u0101\u0952y\u012b\u0952 ra\u0952\u015bmaya\u0951stasya santat\u0101\u1e25 \u0964\nsa\u0952nt\u0101\u0952paya\u0951ti sva\u1e41 d\u0113\u0952ham\u0101p\u0101\u0951datalamasta\u0952ka\u1e25 \u0965 10 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c24\u0c3f\u0952\u0c30\u0c4d\u0c2f\u0952\u0c17\u0c42\u0952\u0c30\u0c4d\u0c27\u0c4d\u0c35\u0c2e\u0951\u0c27\u0c03\u0c36\u0c3e\u0952\u0c2f\u0c40\u0952 \u0c30\u0952\u0c36\u0c4d\u0c2e\u0c2f\u0951\u0c38\u0c4d\u0c24\u0c38\u0c4d\u0c2f \u0c38\u0c28\u0c4d\u0c24\u0c24\u0c3e\u0c03 \u0964\n\u0c38\u0952\u0c28\u0c4d\u0c24\u0c3e\u0952\u0c2a\u0c2f\u0951\u0c24\u0c3f \u0c38\u0c4d\u0c35\u0c02 \u0c26\u0c47\u0952\u0c39\u0c2e\u0c3e\u0c2a\u0c3e\u0951\u0c26\u0c24\u0c32\u0c2e\u0c38\u0c4d\u0c24\u0952\u0c15\u0c03 \u0965 \u0c67\u0c66 \u0965", "tamil": "\u0ba4\u0bbf\u0952\u0bb0\u0bcd\u0baf\u0952\u0b95\u0bc2\u0952\u0bb0\u0bcd\u0ba4\u0bcd\u0bb5\u0bae\u0951\u0ba4\u0b83\u0bb6\u0bbe\u0952\u0baf\u0bc0\u0952 \u0bb0\u0952\u0bb6\u0bcd\u0bae\u0baf\u0951\u0bb8\u0bcd\u0ba4\u0bb8\u0bcd\u0baf \u0bb8\u0ba8\u0bcd\u0ba4\u0ba4\u0bbe\u0b83 \u0964\n\u0bb8\u0952\u0ba8\u0bcd\u0ba4\u0bbe\u0952\u0baa\u0baf\u0951\u0ba4\u0bbf \u0bb8\u0bcd\u0bb5\u0bae\u0bcd \u0ba4\u0bc7\u0952\u0bb9\u0bae\u0bbe\u0baa\u0bbe\u0951\u0ba4\u0ba4\u0bb2\u0bae\u0bb8\u0bcd\u0ba4\u0952\u0b95\u0b83 \u0965 \u0be7\u0be6 \u0965", "kannada": "\u0ca4\u0cbf\u0952\u0cb0\u0ccd\u0caf\u0952\u0c97\u0cc2\u0952\u0cb0\u0ccd\u0ca7\u0ccd\u0cb5\u0cae\u0951\u0ca7\u0c83\u0cb6\u0cbe\u0952\u0caf\u0cc0\u0952 \u0cb0\u0952\u0cb6\u0ccd\u0cae\u0caf\u0951\u0cb8\u0ccd\u0ca4\u0cb8\u0ccd\u0caf \u0cb8\u0ca8\u0ccd\u0ca4\u0ca4\u0cbe\u0c83 \u0964\n\u0cb8\u0952\u0ca8\u0ccd\u0ca4\u0cbe\u0952\u0caa\u0caf\u0951\u0ca4\u0cbf \u0cb8\u0ccd\u0cb5\u0c82 \u0ca6\u0cc7\u0952\u0cb9\u0cae\u0cbe\u0caa\u0cbe\u0951\u0ca6\u0ca4\u0cb2\u0cae\u0cb8\u0ccd\u0ca4\u0952\u0c95\u0c83 \u0965 \u0ce7\u0ce6 \u0965", "malayalam": "\u0d24\u0d3f\u0952\u0d30\u0d4d\u0d2f\u0952\u0d17\u0d42\u0952\u0d30\u0d4d\u0d27\u0d4d\u0d35\u0d2e\u0951\u0d27\u0d03\u0d36\u0d3e\u0952\u0d2f\u0d40\u0952 \u0d30\u0952\u0d36\u0d4d\u0d2e\u0d2f\u0951\u0d38\u0d4d\u0d24\u0d38\u0d4d\u0d2f \u0d38\u0d28\u0d4d\u0d24\u0d24\u0d3e\u0d03 \u0964\n\u0d38\u0952\u0d28\u0d4d\u0d24\u0d3e\u0952\u0d2a\u0d2f\u0951\u0d24\u0d3f \u0d38\u0d4d\u0d35\u0d02 \u0d26\u0d47\u0952\u0d39\u0d2e\u0d3e\u0d2a\u0d3e\u0951\u0d26\u0d24\u0d32\u0d2e\u0d38\u0d4d\u0d24\u0952\u0d15\u0d03 \u0965 \u0d67\u0d66 \u0965", "iast": "ti\u0331rya\u0331g\u016b\u0331rdhvama\u032ddha\u1e25\u015b\u0101\u0331y\u012b\u0331 ra\u0331\u015bmaya\u032dstasya santat\u0101\u1e25 |\nsa\u0331nt\u0101\u0331paya\u032dti sva\u1e43 de\u0331ham\u0101p\u0101\u032ddatalamasta\u0331ka\u1e25 || 10 ||"},
        draftTranslation: "Its radiant rays spread horizontally, upward, and downward, warming and energizing its own bodily vessel from the soles of the feet to the crown of the head.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 11,
        devanagariText: "\u0924\u0938\u094d\u092f\u0952 \u092e\u0927\u094d\u092f\u0947\u0902\u0952 \u0935\u0939\u094d\u0928\u093f\u0936\u093f\u0916\u093e \u0905\u0923\u0940\u0951\u092f\u094b\u0952\u0930\u094d\u0927\u094d\u0935\u093e \u0935\u094d\u092f\u0951\u0935\u0938\u094d\u0925\u093f\u0952\u0924\u093e \u0964\n\u0928\u0940\u0952\u0932\u0924\u094b\u0951\u092f\u0926\u0952\u092e\u0927\u094d\u092f\u0951\u0938\u094d\u0925\u093e\u0926\u094d \u0935\u093f\u0952\u0926\u094d\u092f\u0941\u0932\u094d\u0932\u0947\u0951\u0916\u0947\u0935 \u092d\u093e\u0938\u094d\u0935\u0952\u0930\u093e \u0965 \u0967\u0967 \u0965",
        iastText: "tasya\u0952 madhy\u0113\u0951 vahni\u015bikh\u0101 a\u1e47\u012b\u0951y\u014d\u0952rdhv\u0101 vya\u0951vasthi\u0952t\u0101 \u0964\nn\u012b\u0952lat\u014d\u0951yada\u0952madhya\u0951sth\u0101d vi\u0952dyull\u0113\u0951kh\u0113va bh\u0101sva\u0952r\u0101 \u0965 11 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c24\u0c38\u0c4d\u0c2f\u0952 \u0c2e\u0c27\u0c4d\u0c2f\u0c47\u0c02\u0952 \u0c35\u0c39\u0c4d\u0c28\u0c3f\u0c36\u0c3f\u0c16\u0c3e \u0c05\u0c23\u0c40\u0951\u0c2f\u0c4b\u0952\u0c30\u0c4d\u0c27\u0c4d\u0c35\u0c3e \u0c35\u0c4d\u0c2f\u0951\u0c35\u0c38\u0c4d\u0c25\u0c3f\u0952\u0c24\u0c3e \u0964\n\u0c28\u0c40\u0952\u0c32\u0c24\u0c4b\u0951\u0c2f\u0c26\u0952\u0c2e\u0c27\u0c4d\u0c2f\u0951\u0c38\u0c4d\u0c25\u0c3e\u0c26\u0c4d \u0c35\u0c3f\u0952\u0c26\u0c4d\u0c2f\u0c41\u0c32\u0c4d\u0c32\u0c47\u0951\u0c16\u0c47\u0c35 \u0c2d\u0c3e\u0c38\u0c4d\u0c35\u0952\u0c30\u0c3e \u0965 \u0c67\u0c67 \u0965", "tamil": "\u0ba4\u0bb8\u0bcd\u0baf\u0952 \u0bae\u0ba4\u0bcd\u0baf\u0bc7\u0bae\u0bcd\u0952 \u0bb5\u0bb9\u0bcd\u0ba8\u0bbf\u0bb6\u0bbf\u0b95\u0bbe \u0b85\u0ba3\u0bc0\u0951\u0baf\u0bcb\u0952\u0bb0\u0bcd\u0ba4\u0bcd\u0bb5\u0bbe \u0bb5\u0bcd\u0baf\u0951\u0bb5\u0bb8\u0bcd\u0ba4\u0bbf\u0952\u0ba4\u0bbe \u0964\n\u0ba8\u0bc0\u0952\u0bb2\u0ba4\u0bcb\u0951\u0baf\u0ba4\u0952\u0bae\u0ba4\u0bcd\u0baf\u0951\u0bb8\u0bcd\u0ba4\u0bbe\u0ba4\u0bcd \u0bb5\u0bbf\u0952\u0ba4\u0bcd\u0baf\u0bc1\u0bb2\u0bcd\u0bb2\u0bc7\u0951\u0b95\u0bc7\u0bb5 \u0baa\u0bbe\u0bb8\u0bcd\u0bb5\u0952\u0bb0\u0bbe \u0965 \u0be7\u0be7 \u0965", "kannada": "\u0ca4\u0cb8\u0ccd\u0caf\u0952 \u0cae\u0ca7\u0ccd\u0caf\u0cc7\u0c82\u0952 \u0cb5\u0cb9\u0ccd\u0ca8\u0cbf\u0cb6\u0cbf\u0c96\u0cbe \u0c85\u0ca3\u0cc0\u0951\u0caf\u0ccb\u0952\u0cb0\u0ccd\u0ca7\u0ccd\u0cb5\u0cbe \u0cb5\u0ccd\u0caf\u0951\u0cb5\u0cb8\u0ccd\u0ca5\u0cbf\u0952\u0ca4\u0cbe \u0964\n\u0ca8\u0cc0\u0952\u0cb2\u0ca4\u0ccb\u0951\u0caf\u0ca6\u0952\u0cae\u0ca7\u0ccd\u0caf\u0951\u0cb8\u0ccd\u0ca5\u0cbe\u0ca6\u0ccd \u0cb5\u0cbf\u0952\u0ca6\u0ccd\u0caf\u0cc1\u0cb2\u0ccd\u0cb2\u0cc7\u0951\u0c96\u0cc7\u0cb5 \u0cad\u0cbe\u0cb8\u0ccd\u0cb5\u0952\u0cb0\u0cbe \u0965 \u0ce7\u0ce7 \u0965", "malayalam": "\u0d24\u0d38\u0d4d\u0d2f\u0952 \u0d2e\u0d27\u0d4d\u0d2f\u0d47\u0d02\u0952 \u0d35\u0d39\u0d4d\u0d28\u0d3f\u0d36\u0d3f\u0d16\u0d3e \u0d05\u0d23\u0d40\u0951\u0d2f\u0d4b\u0952\u0d30\u0d4d\u0d27\u0d4d\u0d35\u0d3e \u0d35\u0d4d\u0d2f\u0951\u0d35\u0d38\u0d4d\u0d25\u0d3f\u0952\u0d24\u0d3e \u0964\n\u0d28\u0d40\u0952\u0d32\u0d24\u0d4b\u0951\u0d2f\u0d26\u0952\u0d2e\u0d27\u0d4d\u0d2f\u0951\u0d38\u0d4d\u0d25\u0d3e\u0d26\u0d4d \u0d35\u0d3f\u0952\u0d26\u0d4d\u0d2f\u0d41\u0d32\u0d4d\u0d32\u0d47\u0951\u0d16\u0d47\u0d35 \u0d2d\u0d3e\u0d38\u0d4d\u0d35\u0952\u0d30\u0d3e \u0965 \u0d67\u0d67 \u0965", "iast": "tasya\u0331 madhye\u0331\u1e43 vahni\u015bikh\u0101 a\u1e47\u012b\u032dyo\u0331rdhv\u0101 vya\u032dvasthi\u0331t\u0101 |\nn\u012b\u0331lato\u032dyada\u0331madhya\u032dsth\u0101d vi\u0331dyull\u1e19kheva bh\u0101sva\u0331r\u0101 || 11 ||"},
        draftTranslation: "In the center of that fire stands an exceedingly subtle flame pointing upward, brilliant and dazzling like a flash of golden lightning in the heart of a dark rain-bearing cloud.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 12,
        devanagariText: "\u0924\u0938\u094d\u092f\u093e\u0903\u0951 \u0936\u093f\u0916\u093e\u0952\u092f\u093e \u092e\u0951\u0927\u094d\u092f\u0947 \u092a\u0952\u0930\u092e\u093e\u0951\u0924\u094d\u092e\u093e \u0935\u094d\u092f\u0952\u0935\u0938\u094d\u0925\u093f\u0951\u0924\u0903 \u0964\n\u0938 \u092c\u094d\u0930\u0952\u0939\u094d\u092e\u093e \u0938 \u0936\u093f\u0952\u0935\u0903 \u0938 \u0939\u0930\u093f\u0903\u0952 \u0938 \u0907\u0928\u094d\u0926\u094d\u0930\u0903\u0952 \u0938\u094b\u093d\u0915\u094d\u0937\u0930\u0903\u0951 \u092a\u0930\u0952\u092e\u0903 \u0938\u094d\u0935\u0952\u0930\u093e\u091f\u094d \u0965 \u0967\u0968 \u0965",
        iastText: "tasy\u0101\u1e25\u0951 \u015bikh\u0101\u0952y\u0101 ma\u0951dhy\u0113 pa\u0952ram\u0101\u0951tm\u0101 vya\u0952vasthi\u0951ta\u1e25 \u0964\nsa bra\u0952hm\u0101 sa \u015bi\u0952va\u1e25 sa hari\u1e25\u0952 sa indra\u1e25\u0952 s\u014d'k\u1e63ara\u1e25\u0951 para\u0952ma\u1e25 sva\u0952r\u0101\u1e6d \u0965 12 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c24\u0c38\u0c4d\u0c2f\u0c3e\u0c03\u0951 \u0c36\u0c3f\u0c16\u0c3e\u0952\u0c2f\u0c3e \u0c2e\u0951\u0c27\u0c4d\u0c2f\u0c47 \u0c2a\u0952\u0c30\u0c2e\u0c3e\u0951\u0c24\u0c4d\u0c2e\u0c3e \u0c35\u0c4d\u0c2f\u0952\u0c35\u0c38\u0c4d\u0c25\u0c3f\u0951\u0c24\u0c03 \u0964\n\u0c38 \u0c2c\u0c4d\u0c30\u0952\u0c39\u0c4d\u0c2e\u0c3e \u0c38 \u0c36\u0c3f\u0952\u0c35\u0c03 \u0c38 \u0c39\u0c30\u0c3f\u0c03\u0952 \u0c38 \u0c07\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c03\u0952 \u0c38\u0c4b\u0c3d\u0c15\u0c4d\u0c37\u0c30\u0c03\u0951 \u0c2a\u0c30\u0952\u0c2e\u0c03 \u0c38\u0c4d\u0c35\u0952\u0c30\u0c3e\u0c1f\u0c4d \u0965 \u0c67\u0c68 \u0965", "tamil": "\u0ba4\u0bb8\u0bcd\u0baf\u0bbe\u0b83\u0951 \u0bb6\u0bbf\u0b95\u0bbe\u0952\u0baf\u0bbe \u0bae\u0951\u0ba4\u0bcd\u0baf\u0bc7 \u0baa\u0952\u0bb0\u0bae\u0bbe\u0951\u0ba4\u0bcd\u0bae\u0bbe \u0bb5\u0bcd\u0baf\u0952\u0bb5\u0bb8\u0bcd\u0ba4\u0bbf\u0951\u0ba4\u0b83 \u0964\n\u0bb8 \u0baa\u0bcd\u0bb0\u0952\u0bb9\u0bcd\u0bae\u0bbe \u0bb8 \u0bb6\u0bbf\u0952\u0bb5\u0b83 \u0bb8 \u0bb9\u0bb0\u0bbf\u0b83\u0952 \u0bb8 \u0b87\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0b83\u0952 \u0bb8\u0bcb\u093d\u0b95\u0bcd\u0bb7\u0bb0\u0b83\u0951 \u0baa\u0bb0\u0952\u0bae\u0b83 \u0bb8\u0bcd\u0bb5\u0952\u0bb0\u0bbe\u0b9f\u0bcd \u0965 \u0be7\u0be8 \u0965", "kannada": "\u0ca4\u0cb8\u0ccd\u0caf\u0cbe\u0c83\u0951 \u0cb6\u0cbf\u0c96\u0cbe\u0952\u0caf\u0cbe \u0cae\u0951\u0ca7\u0ccd\u0caf\u0cc7 \u0caa\u0952\u0cb0\u0cae\u0cbe\u0951\u0ca4\u0ccd\u0cae\u0cbe \u0cb5\u0ccd\u0caf\u0952\u0cb5\u0cb8\u0ccd\u0ca5\u0cbf\u0951\u0ca4\u0c83 \u0964\n\u0cb8 \u0cac\u0ccd\u0cb0\u0952\u0cb9\u0ccd\u0cae\u0cbe \u0cb8 \u0cb6\u0cbf\u0952\u0cb5\u0c83 \u0cb8 \u0cb9\u0cb0\u0cbf\u0c83\u0952 \u0cb8 \u0c87\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0c83\u0952 \u0cb8\u0ccb\u0cbd\u0c95\u0ccd\u0cb7\u0cb0\u0c83\u0951 \u0caa\u0cb0\u0952\u0cae\u0c83 \u0cb8\u0ccd\u0cb5\u0952\u0cb0\u0cbe\u0c9f\u0ccd \u0965 \u0ce7\u0ce8 \u0965", "malayalam": "\u0d24\u0d38\u0d4d\u0d2f\u0d3e\u0d03\u0951 \u0d36\u0d3f\u0d16\u0d3e\u0952\u0d2f\u0d3e \u0d2e\u0951\u0d27\u0d4d\u0d2f\u0d47 \u0d2a\u0952\u0d30\u0d2e\u0d3e\u0951\u0d24\u0d4d\u0d2e\u0d3e \u0d35\u0d4d\u0d2f\u0952\u0d35\u0d38\u0d4d\u0d25\u0d3f\u0951\u0d24\u0d03 \u0964\n\u0d38 \u0d2c\u0d4d\u0d30\u0952\u0d39\u0d4d\u0d2e\u0d3e \u0d38 \u0d36\u0d3f\u0952\u0d35\u0d03 \u0d38 \u0d39\u0d30\u0d3f\u0d03\u0952 \u0d38 \u0d07\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d03\u0952 \u0d38\u0d4b\u0d3d\u0d15\u0d4d\u0d37\u0d30\u0d03\u0951 \u0d2a\u0d30\u0952\u0d2e\u0d03 \u0d38\u0d4d\u0d35\u0952\u0d30\u0d3e\u0d1f\u0d4d \u0965 \u0d67\u0d68 \u0965", "iast": "tasy\u0101\u032d\u1e25 \u015bikh\u0101\u0331y\u0101 ma\u032ddhye pa\u0331ram\u0101\u032dtm\u0101 vya\u0331vasthi\u032dta\u1e25 |\nsa bra\u0331hm\u0101 sa \u015bi\u0331va\u1e25 sa hari\u0331\u1e25 sa indra\u0331\u1e25 so'k\u1e63ara\u032d\u1e25 para\u0331ma\u1e25 sva\u0331r\u0101\u1e6d || 12 ||"},
        draftTranslation: "In the very core of that subtle flame resides the Supreme Paramatman. He is Brahma, He is Shiva, He is Hari (Vishnu), He is Indra; He is the Imperishable, the Supreme, and the Self-Luminous Sovereign!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
    ],
  ),
  Scripture(
    id: 20,
    contentId: "VEDA-TXT-00017",
    canonicalTitle: "Surya Ashtakam",
    devanagariTitle: "\u0938\u0942\u0930\u094d\u092f\u093e\u0937\u094d\u091f\u0915\u092e\u094d",
    category: "Ashtakam",
    deity: "Lord Surya",
    composer: "Samba Purana / Sage Agastya",
    rishi: "Traditional Vedic Sage",
    chandas: "Anushtubh",
    devata: "Lord Surya",
    sourceScripture: "Samba Purana / Saura Stotra Samgraha",
    traditionalUsage: "Sun worship, removal of eye afflictions, health, dispelling planetary doshas",
    verseCount: 10,
    verses: [
      Verse(
        verseNumber: 1,
        devanagariText: "\u0906\u0926\u093f\u0926\u0947\u0935 \u0928\u092e\u0938\u094d\u0924\u0941\u092d\u094d\u092f\u0902 \u092a\u094d\u0930\u0938\u0940\u0926 \u092e\u092e \u092d\u093e\u0938\u094d\u0915\u0930 \u0964\n\u0926\u093f\u0935\u093e\u0915\u0930 \u0928\u092e\u0938\u094d\u0924\u0941\u092d\u094d\u092f\u0902 \u092a\u094d\u0930\u092d\u093e\u0915\u0930 \u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0924\u0947 \u0965 \u0967 \u0965",
        iastText: "\u0101did\u0113va namastubhya\u1e41 pras\u012bda mama bh\u0101skara \u0964\ndiv\u0101kara namastubhya\u1e41 prabh\u0101kara nam\u014d'stu t\u0113 \u0965 1 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c06\u0c26\u0c3f\u0c26\u0c47\u0c35 \u0c28\u0c2e\u0c38\u0c4d\u0c24\u0c41\u0c2d\u0c4d\u0c2f\u0c02 \u0c2a\u0c4d\u0c30\u0c38\u0c40\u0c26 \u0c2e\u0c2e \u0c2d\u0c3e\u0c38\u0c4d\u0c15\u0c30 \u0964\n\u0c26\u0c3f\u0c35\u0c3e\u0c15\u0c30 \u0c28\u0c2e\u0c38\u0c4d\u0c24\u0c41\u0c2d\u0c4d\u0c2f\u0c02 \u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c15\u0c30 \u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c24\u0c47 \u0965 \u0c67 \u0965", "tamil": "\u0b86\u0ba4\u0bbf\u0ba4\u0bc7\u0bb5 \u0ba8\u0bae\u0bb8\u0bcd\u0ba4\u0bc1\u0baa\u0bcd\u0baf\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0bb8\u0bc0\u0ba4 \u0bae\u0bae \u0baa\u0bbe\u0bb8\u0bcd\u0b95\u0bb0 \u0964\n\u0ba4\u0bbf\u0bb5\u0bbe\u0b95\u0bb0 \u0ba8\u0bae\u0bb8\u0bcd\u0ba4\u0bc1\u0baa\u0bcd\u0baf\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0b95\u0bb0 \u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bc7 \u0965 \u0be7 \u0965", "kannada": "\u0c86\u0ca6\u0cbf\u0ca6\u0cc7\u0cb5 \u0ca8\u0cae\u0cb8\u0ccd\u0ca4\u0cc1\u0cad\u0ccd\u0caf\u0c82 \u0caa\u0ccd\u0cb0\u0cb8\u0cc0\u0ca6 \u0cae\u0cae \u0cad\u0cbe\u0cb8\u0ccd\u0c95\u0cb0 \u0964\n\u0ca6\u0cbf\u0cb5\u0cbe\u0c95\u0cb0 \u0ca8\u0cae\u0cb8\u0ccd\u0ca4\u0cc1\u0cad\u0ccd\u0caf\u0c82 \u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0c95\u0cb0 \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca4\u0cc7 \u0965 \u0ce7 \u0965", "malayalam": "\u0d06\u0d26\u0d3f\u0d26\u0d47\u0d35 \u0d28\u0d2e\u0d38\u0d4d\u0d24\u0d41\u0d2d\u0d4d\u0d2f\u0d02 \u0d2a\u0d4d\u0d30\u0d38\u0d40\u0d26 \u0d2e\u0d2e \u0d2d\u0d3e\u0d38\u0d4d\u0d15\u0d30 \u0964\n\u0d26\u0d3f\u0d35\u0d3e\u0d15\u0d30 \u0d28\u0d2e\u0d38\u0d4d\u0d24\u0d41\u0d2d\u0d4d\u0d2f\u0d02 \u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d15\u0d30 \u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d24\u0d47 \u0965 \u0d67 \u0965", "iast": "\u0101dideva namastubhya\u1e43 pras\u012bda mama bh\u0101skara |\ndiv\u0101kara namastubhya\u1e43 prabh\u0101kara namo'stu te || 1 ||"},
        draftTranslation: "Salutations to You, O Primordial God! Be gracious unto me, O Bhaskara (Creator of Light)! Salutations to You, O Divakara (Maker of the Day)! Salutations unto You, O Prabhakara (Maker of Splendor)!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 2,
        devanagariText: "\u0938\u092a\u094d\u0924\u093e\u0936\u094d\u0935\u0930\u0925\u092e\u093e\u0930\u0942\u0922\u0902 \u092a\u094d\u0930\u091a\u0923\u094d\u0921\u0902 \u0915\u0936\u094d\u092f\u092a\u093e\u0924\u094d\u092e\u091c\u092e\u094d \u0964\n\u0936\u094d\u0935\u0947\u0924\u092a\u0926\u094d\u092e\u0927\u0930\u0902 \u0926\u0947\u0935\u0902 \u0924\u0902 \u0938\u0942\u0930\u094d\u092f\u0902 \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u094d\u092f\u0939\u092e\u094d \u0965 \u0968 \u0965",
        iastText: "sapt\u0101\u015bvaratham\u0101r\u016b\u1e0dha\u1e41 praca\u1e47\u1e0da\u1e41 ka\u015byap\u0101tmajam \u0964\n\u015bv\u0113tapadmadhara\u1e41 d\u0113va\u1e41 ta\u1e41 s\u016brya\u1e41 pra\u1e47am\u0101myaham \u0965 2 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0c2a\u0c4d\u0c24\u0c3e\u0c36\u0c4d\u0c35\u0c30\u0c25\u0c2e\u0c3e\u0c30\u0c42\u0c22\u0c02 \u0c2a\u0c4d\u0c30\u0c1a\u0c23\u0c4d\u0c21\u0c02 \u0c15\u0c36\u0c4d\u0c2f\u0c2a\u0c3e\u0c24\u0c4d\u0c2e\u0c1c\u0c2e\u0c4d \u0964\n\u0c36\u0c4d\u0c35\u0c47\u0c24\u0c2a\u0c26\u0c4d\u0c2e\u0c27\u0c30\u0c02 \u0c26\u0c47\u0c35\u0c02 \u0c24\u0c02 \u0c38\u0c42\u0c30\u0c4d\u0c2f\u0c02 \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c4d\u0c2f\u0c39\u0c2e\u0c4d \u0965 \u0c68 \u0965", "tamil": "\u0bb8\u0baa\u0bcd\u0ba4\u0bbe\u0bb6\u0bcd\u0bb5\u0bb0\u0ba4\u0bae\u0bbe\u0bb0\u0bc2\u0b9f\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0b9a\u0ba3\u0bcd\u0b9f\u0bae\u0bcd \u0b95\u0bb6\u0bcd\u0baf\u0baa\u0bbe\u0ba4\u0bcd\u0bae\u0b9c\u0bae\u0bcd \u0964\n\u0bb6\u0bcd\u0bb5\u0bc7\u0ba4\u0baa\u0ba4\u0bcd\u0bae\u0ba4\u0bb0\u0bae\u0bcd \u0ba4\u0bc7\u0bb5\u0bae\u0bcd \u0ba4\u0bae\u0bcd \u0bb8\u0bc2\u0bb0\u0bcd\u0baf\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bcd\u0baf\u0bb9\u0bae\u0bcd \u0965 \u0be8 \u0965", "kannada": "\u0cb8\u0caa\u0ccd\u0ca4\u0cbe\u0cb6\u0ccd\u0cb5\u0cb0\u0ca5\u0cae\u0cbe\u0cb0\u0cc2\u0ca2\u0c82 \u0caa\u0ccd\u0cb0\u0c9a\u0ca3\u0ccd\u0ca1\u0c82 \u0c95\u0cb6\u0ccd\u0caf\u0caa\u0cbe\u0ca4\u0ccd\u0cae\u0c9c\u0cae\u0ccd \u0964\n\u0cb6\u0ccd\u0cb5\u0cc7\u0ca4\u0caa\u0ca6\u0ccd\u0cae\u0ca7\u0cb0\u0c82 \u0ca6\u0cc7\u0cb5\u0c82 \u0ca4\u0c82 \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0c82 \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0ccd\u0caf\u0cb9\u0cae\u0ccd \u0965 \u0ce8 \u0965", "malayalam": "\u0d38\u0d2a\u0d4d\u0d24\u0d3e\u0d36\u0d4d\u0d35\u0d30\u0d25\u0d2e\u0d3e\u0d30\u0d42\u0d22\u0d02 \u0d2a\u0d4d\u0d30\u0d1a\u0d23\u0d4d\u0d21\u0d02 \u0d15\u0d36\u0d4d\u0d2f\u0d2a\u0d3e\u0d24\u0d4d\u0d2e\u0d1c\u0d2e\u0d4d \u0964\n\u0d36\u0d4d\u0d35\u0d47\u0d24\u0d2a\u0d26\u0d4d\u0d2e\u0d27\u0d30\u0d02 \u0d26\u0d47\u0d35\u0d02 \u0d24\u0d02 \u0d38\u0d42\u0d30\u0d4d\u0d2f\u0d02 \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d4d\u0d2f\u0d39\u0d2e\u0d4d \u0965 \u0d68 \u0965", "iast": "sapt\u0101\u015bvaratham\u0101r\u016b\u1e0dha\u1e43 praca\u1e47\u1e0da\u1e43 ka\u015byap\u0101tmajam |\n\u015bvetapadmadhara\u1e43 deva\u1e43 ta\u1e43 s\u016brya\u1e43 pra\u1e47am\u0101myaham || 2 ||"},
        draftTranslation: "Mounted upon a chariot drawn by seven horses, immensely powerful, son of Sage Kashyapa, holding a white lotus in His hand, unto that Sun-God I bow down.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 3,
        devanagariText: "\u0932\u094b\u0939\u093f\u0924\u0902 \u0930\u0925\u092e\u093e\u0930\u0942\u0922\u0902 \u0938\u0930\u094d\u0935\u0932\u094b\u0915\u092a\u093f\u0924\u093e\u092e\u0939\u092e\u094d \u0964\n\u092e\u0939\u093e\u092a\u093e\u092a\u0939\u0930\u0902 \u0926\u0947\u0935\u0902 \u0924\u0902 \u0938\u0942\u0930\u094d\u092f\u0902 \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u094d\u092f\u0939\u092e\u094d \u0965 \u0969 \u0965",
        iastText: "l\u014dhita\u1e41 ratham\u0101r\u016b\u1e0dha\u1e41 sarval\u014dkapit\u0101maham \u0964\nmah\u0101p\u0101pahara\u1e41 d\u0113va\u1e41 ta\u1e41 s\u016brya\u1e41 pra\u1e47am\u0101myaham \u0965 3 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c32\u0c4b\u0c39\u0c3f\u0c24\u0c02 \u0c30\u0c25\u0c2e\u0c3e\u0c30\u0c42\u0c22\u0c02 \u0c38\u0c30\u0c4d\u0c35\u0c32\u0c4b\u0c15\u0c2a\u0c3f\u0c24\u0c3e\u0c2e\u0c39\u0c2e\u0c4d \u0964\n\u0c2e\u0c39\u0c3e\u0c2a\u0c3e\u0c2a\u0c39\u0c30\u0c02 \u0c26\u0c47\u0c35\u0c02 \u0c24\u0c02 \u0c38\u0c42\u0c30\u0c4d\u0c2f\u0c02 \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c4d\u0c2f\u0c39\u0c2e\u0c4d \u0965 \u0c69 \u0965", "tamil": "\u0bb2\u0bcb\u0bb9\u0bbf\u0ba4\u0bae\u0bcd \u0bb0\u0ba4\u0bae\u0bbe\u0bb0\u0bc2\u0b9f\u0bae\u0bcd \u0bb8\u0bb0\u0bcd\u0bb5\u0bb2\u0bcb\u0b95\u0baa\u0bbf\u0ba4\u0bbe\u0bae\u0bb9\u0bae\u0bcd \u0964\n\u0bae\u0bb9\u0bbe\u0baa\u0bbe\u0baa\u0bb9\u0bb0\u0bae\u0bcd \u0ba4\u0bc7\u0bb5\u0bae\u0bcd \u0ba4\u0bae\u0bcd \u0bb8\u0bc2\u0bb0\u0bcd\u0baf\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bcd\u0baf\u0bb9\u0bae\u0bcd \u0965 \u0be9 \u0965", "kannada": "\u0cb2\u0ccb\u0cb9\u0cbf\u0ca4\u0c82 \u0cb0\u0ca5\u0cae\u0cbe\u0cb0\u0cc2\u0ca2\u0c82 \u0cb8\u0cb0\u0ccd\u0cb5\u0cb2\u0ccb\u0c95\u0caa\u0cbf\u0ca4\u0cbe\u0cae\u0cb9\u0cae\u0ccd \u0964\n\u0cae\u0cb9\u0cbe\u0caa\u0cbe\u0caa\u0cb9\u0cb0\u0c82 \u0ca6\u0cc7\u0cb5\u0c82 \u0ca4\u0c82 \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0c82 \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0ccd\u0caf\u0cb9\u0cae\u0ccd \u0965 \u0ce9 \u0965", "malayalam": "\u0d32\u0d4b\u0d39\u0d3f\u0d24\u0d02 \u0d30\u0d25\u0d2e\u0d3e\u0d30\u0d42\u0d22\u0d02 \u0d38\u0d30\u0d4d\u0d35\u0d32\u0d4b\u0d15\u0d2a\u0d3f\u0d24\u0d3e\u0d2e\u0d39\u0d2e\u0d4d \u0964\n\u0d2e\u0d39\u0d3e\u0d2a\u0d3e\u0d2a\u0d39\u0d30\u0d02 \u0d26\u0d47\u0d35\u0d02 \u0d24\u0d02 \u0d38\u0d42\u0d30\u0d4d\u0d2f\u0d02 \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d4d\u0d2f\u0d39\u0d2e\u0d4d \u0965 \u0d69 \u0965", "iast": "lohita\u1e43 ratham\u0101r\u016b\u1e0dha\u1e43 sarvalokapit\u0101maham |\nmah\u0101p\u0101pahara\u1e43 deva\u1e43 ta\u1e43 s\u016brya\u1e43 pra\u1e47am\u0101myaham || 3 ||"},
        draftTranslation: "Mounted upon a radiant reddish chariot, the grand ancestor of all worlds, the divine dispeller of great sins, unto that Sun-God I bow down.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 4,
        devanagariText: "\u0924\u094d\u0930\u0948\u0917\u0941\u0923\u094d\u092f\u0902 \u091a \u092e\u0939\u093e\u0936\u0942\u0930\u0902 \u092c\u094d\u0930\u0939\u094d\u092e\u0935\u093f\u0937\u094d\u0923\u0941\u092e\u0939\u0947\u0936\u094d\u0935\u0930\u092e\u094d \u0964\n\u092e\u0939\u093e\u092a\u093e\u092a\u0939\u0930\u0902 \u0926\u0947\u0935\u0902 \u0924\u0902 \u0938\u0942\u0930\u094d\u092f\u0902 \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u094d\u092f\u0939\u092e\u094d \u0965 \u096a \u0965",
        iastText: "traigu\u1e47ya\u1e41 ca mah\u0101\u015b\u016bra\u1e41 brahmavi\u1e63\u1e47umah\u0113\u015bvaram \u0964\nmah\u0101p\u0101pahara\u1e41 d\u0113va\u1e41 ta\u1e41 s\u016brya\u1e41 pra\u1e47am\u0101myaham \u0965 4 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c24\u0c4d\u0c30\u0c48\u0c17\u0c41\u0c23\u0c4d\u0c2f\u0c02 \u0c1a \u0c2e\u0c39\u0c3e\u0c36\u0c42\u0c30\u0c02 \u0c2c\u0c4d\u0c30\u0c39\u0c4d\u0c2e\u0c35\u0c3f\u0c37\u0c4d\u0c23\u0c41\u0c2e\u0c39\u0c47\u0c36\u0c4d\u0c35\u0c30\u0c2e\u0c4d \u0964\n\u0c2e\u0c39\u0c3e\u0c2a\u0c3e\u0c2a\u0c39\u0c30\u0c02 \u0c26\u0c47\u0c35\u0c02 \u0c24\u0c02 \u0c38\u0c42\u0c30\u0c4d\u0c2f\u0c02 \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c4d\u0c2f\u0c39\u0c2e\u0c4d \u0965 \u0c6a \u0965", "tamil": "\u0ba4\u0bcd\u0bb0\u0bc8\u0b95\u0bc1\u0ba3\u0bcd\u0baf\u0bae\u0bcd \u0b9a \u0bae\u0bb9\u0bbe\u0bb6\u0bc2\u0bb0\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0bb9\u0bcd\u0bae\u0bb5\u0bbf\u0bb7\u0bcd\u0ba3\u0bc1\u0bae\u0bb9\u0bc7\u0bb6\u0bcd\u0bb5\u0bb0\u0bae\u0bcd \u0964\n\u0bae\u0bb9\u0bbe\u0baa\u0bbe\u0baa\u0bb9\u0bb0\u0bae\u0bcd \u0ba4\u0bc7\u0bb5\u0bae\u0bcd \u0ba4\u0bae\u0bcd \u0bb8\u0bc2\u0bb0\u0bcd\u0baf\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bcd\u0baf\u0bb9\u0bae\u0bcd \u0965 \u0bea \u0965", "kannada": "\u0ca4\u0ccd\u0cb0\u0cc8\u0c97\u0cc1\u0ca3\u0ccd\u0caf\u0c82 \u0c9a \u0cae\u0cb9\u0cbe\u0cb6\u0cc2\u0cb0\u0c82 \u0cac\u0ccd\u0cb0\u0cb9\u0ccd\u0cae\u0cb5\u0cbf\u0cb7\u0ccd\u0ca3\u0cc1\u0cae\u0cb9\u0cc7\u0cb6\u0ccd\u0cb5\u0cb0\u0cae\u0ccd \u0964\n\u0cae\u0cb9\u0cbe\u0caa\u0cbe\u0caa\u0cb9\u0cb0\u0c82 \u0ca6\u0cc7\u0cb5\u0c82 \u0ca4\u0c82 \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0c82 \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0ccd\u0caf\u0cb9\u0cae\u0ccd \u0965 \u0cea \u0965", "malayalam": "\u0d24\u0d4d\u0d30\u0d48\u0d17\u0d41\u0d23\u0d4d\u0d2f\u0d02 \u0d1a \u0d2e\u0d39\u0d3e\u0d36\u0d42\u0d30\u0d02 \u0d2c\u0d4d\u0d30\u0d39\u0d4d\u0d2e\u0d35\u0d3f\u0d37\u0d4d\u0d23\u0d41\u0d2e\u0d39\u0d47\u0d36\u0d4d\u0d35\u0d30\u0d2e\u0d4d \u0964\n\u0d2e\u0d39\u0d3e\u0d2a\u0d3e\u0d2a\u0d39\u0d30\u0d02 \u0d26\u0d47\u0d35\u0d02 \u0d24\u0d02 \u0d38\u0d42\u0d30\u0d4d\u0d2f\u0d02 \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d4d\u0d2f\u0d39\u0d2e\u0d4d \u0965 \u0d6a \u0965", "iast": "traigu\u1e47ya\u1e43 ca mah\u0101\u015b\u016bra\u1e43 brahmavi\u1e63\u1e47umahe\u015bvaram |\nmah\u0101p\u0101pahara\u1e43 deva\u1e43 ta\u1e43 s\u016brya\u1e43 pra\u1e47am\u0101myaham || 4 ||"},
        draftTranslation: "Embodiment of the three Gunas (Sattva, Rajas, Tamas), valiant warrior, essence of Brahma, Vishnu, and Shiva, dispeller of great sins, unto that Sun-God I bow down.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 5,
        devanagariText: "\u092c\u0943\u0902\u0939\u093f\u0924\u0902 \u0924\u0947\u091c\u0938\u093e\u0902 \u092a\u0941\u091e\u094d\u091c\u0902 \u0935\u093e\u092f\u0941\u092e\u093e\u0915\u093e\u0936\u092e\u0947\u0935 \u091a \u0964\n\u092a\u094d\u0930\u092d\u0941\u0902 \u091a \u0938\u0930\u094d\u0935\u0932\u094b\u0915\u093e\u0928\u093e\u0902 \u0924\u0902 \u0938\u0942\u0930\u094d\u092f\u0902 \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u094d\u092f\u0939\u092e\u094d \u0965 \u096b \u0965",
        iastText: "b\u1e5b\u1e41hita\u1e41 t\u0113jas\u0101\u1e41 pu\u00f1ja\u1e41 v\u0101yum\u0101k\u0101\u015bam\u0113va ca \u0964\nprabhu\u1e41 ca sarval\u014dk\u0101n\u0101\u1e41 ta\u1e41 s\u016brya\u1e41 pra\u1e47am\u0101myaham \u0965 5 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2c\u0c43\u0c02\u0c39\u0c3f\u0c24\u0c02 \u0c24\u0c47\u0c1c\u0c38\u0c3e\u0c02 \u0c2a\u0c41\u0c1e\u0c4d\u0c1c\u0c02 \u0c35\u0c3e\u0c2f\u0c41\u0c2e\u0c3e\u0c15\u0c3e\u0c36\u0c2e\u0c47\u0c35 \u0c1a \u0964\n\u0c2a\u0c4d\u0c30\u0c2d\u0c41\u0c02 \u0c1a \u0c38\u0c30\u0c4d\u0c35\u0c32\u0c4b\u0c15\u0c3e\u0c28\u0c3e\u0c02 \u0c24\u0c02 \u0c38\u0c42\u0c30\u0c4d\u0c2f\u0c02 \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c4d\u0c2f\u0c39\u0c2e\u0c4d \u0965 \u0c6b \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0bc1'\u0bae\u0bcd\u0bb9\u0bbf\u0ba4\u0bae\u0bcd \u0ba4\u0bc7\u0b9c\u0bb8\u0bbe\u0bae\u0bcd \u0baa\u0bc1\u0b9e\u0bcd\u0b9c\u0bae\u0bcd \u0bb5\u0bbe\u0baf\u0bc1\u0bae\u0bbe\u0b95\u0bbe\u0bb6\u0bae\u0bc7\u0bb5 \u0b9a \u0964\n\u0baa\u0bcd\u0bb0\u0baa\u0bc1\u0bae\u0bcd \u0b9a \u0bb8\u0bb0\u0bcd\u0bb5\u0bb2\u0bcb\u0b95\u0bbe\u0ba8\u0bbe\u0bae\u0bcd \u0ba4\u0bae\u0bcd \u0bb8\u0bc2\u0bb0\u0bcd\u0baf\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bcd\u0baf\u0bb9\u0bae\u0bcd \u0965 \u0beb \u0965", "kannada": "\u0cac\u0cc3\u0c82\u0cb9\u0cbf\u0ca4\u0c82 \u0ca4\u0cc7\u0c9c\u0cb8\u0cbe\u0c82 \u0caa\u0cc1\u0c9e\u0ccd\u0c9c\u0c82 \u0cb5\u0cbe\u0caf\u0cc1\u0cae\u0cbe\u0c95\u0cbe\u0cb6\u0cae\u0cc7\u0cb5 \u0c9a \u0964\n\u0caa\u0ccd\u0cb0\u0cad\u0cc1\u0c82 \u0c9a \u0cb8\u0cb0\u0ccd\u0cb5\u0cb2\u0ccb\u0c95\u0cbe\u0ca8\u0cbe\u0c82 \u0ca4\u0c82 \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0c82 \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0ccd\u0caf\u0cb9\u0cae\u0ccd \u0965 \u0ceb \u0965", "malayalam": "\u0d2c\u0d43\u0d02\u0d39\u0d3f\u0d24\u0d02 \u0d24\u0d47\u0d1c\u0d38\u0d3e\u0d02 \u0d2a\u0d41\u0d1e\u0d4d\u0d1c\u0d02 \u0d35\u0d3e\u0d2f\u0d41\u0d2e\u0d3e\u0d15\u0d3e\u0d36\u0d2e\u0d47\u0d35 \u0d1a \u0964\n\u0d2a\u0d4d\u0d30\u0d2d\u0d41\u0d02 \u0d1a \u0d38\u0d30\u0d4d\u0d35\u0d32\u0d4b\u0d15\u0d3e\u0d28\u0d3e\u0d02 \u0d24\u0d02 \u0d38\u0d42\u0d30\u0d4d\u0d2f\u0d02 \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d4d\u0d2f\u0d39\u0d2e\u0d4d \u0965 \u0d6b \u0965", "iast": "b\u1e5b\u1e43hita\u1e43 tejas\u0101\u1e43 pu\u00f1ja\u1e43 v\u0101yum\u0101k\u0101\u015bameva ca |\nprabhu\u1e43 ca sarvalok\u0101n\u0101\u1e43 ta\u1e43 s\u016brya\u1e43 pra\u1e47am\u0101myaham || 5 ||"},
        draftTranslation: "Magnified mass of radiant energy, pervading the air and the space, Lord of all the realms, unto that Sun-God I bow down.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 6,
        devanagariText: "\u092c\u0928\u094d\u0927\u0942\u0915\u092a\u0941\u0937\u094d\u092a\u0938\u0902\u0915\u093e\u0936\u0902 \u0939\u093e\u0930\u0915\u0941\u0923\u094d\u0921\u0932\u092d\u0942\u0937\u093f\u0924\u092e\u094d \u0964\n\u090f\u0915\u091a\u0915\u094d\u0930\u0927\u0930\u0902 \u0926\u0947\u0935\u0902 \u0924\u0902 \u0938\u0942\u0930\u094d\u092f\u0902 \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u094d\u092f\u0939\u092e\u094d \u0965 \u096c \u0965",
        iastText: "bandh\u016bkapu\u1e63pasa\u1e41k\u0101\u015ba\u1e41 h\u0101raku\u1e47\u1e0dalabh\u016b\u1e63itam \u0964\n\u0113kacakradhara\u1e41 d\u0113va\u1e41 ta\u1e41 s\u016brya\u1e41 pra\u1e47am\u0101myaham \u0965 6 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c2c\u0c28\u0c4d\u0c27\u0c42\u0c15\u0c2a\u0c41\u0c37\u0c4d\u0c2a\u0c38\u0c02\u0c15\u0c3e\u0c36\u0c02 \u0c39\u0c3e\u0c30\u0c15\u0c41\u0c23\u0c4d\u0c21\u0c32\u0c2d\u0c42\u0c37\u0c3f\u0c24\u0c2e\u0c4d \u0964\n\u0c0f\u0c15\u0c1a\u0c15\u0c4d\u0c30\u0c27\u0c30\u0c02 \u0c26\u0c47\u0c35\u0c02 \u0c24\u0c02 \u0c38\u0c42\u0c30\u0c4d\u0c2f\u0c02 \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c4d\u0c2f\u0c39\u0c2e\u0c4d \u0965 \u0c6c \u0965", "tamil": "\u0baa\u0ba8\u0bcd\u0ba4\u0bc2\u0b95\u0baa\u0bc1\u0bb7\u0bcd\u0baa\u0bb8\u0bae\u0bcd\u0b95\u0bbe\u0bb6\u0bae\u0bcd \u0bb9\u0bbe\u0bb0\u0b95\u0bc1\u0ba3\u0bcd\u0b9f\u0bb2\u0baa\u0bc2\u0bb7\u0bbf\u0ba4\u0bae\u0bcd \u0964\n\u0b8f\u0b95\u0b9a\u0b95\u0bcd\u0bb0\u0ba4\u0bb0\u0bae\u0bcd \u0ba4\u0bc7\u0bb5\u0bae\u0bcd \u0ba4\u0bae\u0bcd \u0bb8\u0bc2\u0bb0\u0bcd\u0baf\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bcd\u0baf\u0bb9\u0bae\u0bcd \u0965 \u0bec \u0965", "kannada": "\u0cac\u0ca8\u0ccd\u0ca7\u0cc2\u0c95\u0caa\u0cc1\u0cb7\u0ccd\u0caa\u0cb8\u0c82\u0c95\u0cbe\u0cb6\u0c82 \u0cb9\u0cbe\u0cb0\u0c95\u0cc1\u0ca3\u0ccd\u0ca1\u0cb2\u0cad\u0cc2\u0cb7\u0cbf\u0ca4\u0cae\u0ccd \u0964\n\u0c8f\u0c95\u0c9a\u0c95\u0ccd\u0cb0\u0ca7\u0cb0\u0c82 \u0ca6\u0cc7\u0cb5\u0c82 \u0ca4\u0c82 \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0c82 \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0ccd\u0caf\u0cb9\u0cae\u0ccd \u0965 \u0cec \u0965", "malayalam": "\u0d2c\u0d28\u0d4d\u0d27\u0d42\u0d15\u0d2a\u0d41\u0d37\u0d4d\u0d2a\u0d38\u0d02\u0d15\u0d3e\u0d36\u0d02 \u0d39\u0d3e\u0d30\u0d15\u0d41\u0d23\u0d4d\u0d21\u0d32\u0d2d\u0d42\u0d37\u0d3f\u0d24\u0d2e\u0d4d \u0964\n\u0d0f\u0d15\u0d1a\u0d15\u0d4d\u0d30\u0d27\u0d30\u0d02 \u0d26\u0d47\u0d35\u0d02 \u0d24\u0d02 \u0d38\u0d42\u0d30\u0d4d\u0d2f\u0d02 \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d4d\u0d2f\u0d39\u0d2e\u0d4d \u0965 \u0d6c \u0965", "iast": "bandh\u016bkapu\u1e63pasa\u1e43k\u0101\u015ba\u1e43 h\u0101raku\u1e47\u1e0dalabh\u016b\u1e63itam |\nekacakradhara\u1e43 deva\u1e43 ta\u1e43 s\u016brya\u1e43 pra\u1e47am\u0101myaham || 6 ||"},
        draftTranslation: "Radiant like the scarlet Bandhuka flower, adorned with necklaces and glittering ear-pendants, presiding over a chariot with a single wheel (the cycle of time), unto that Sun-God I bow down.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 7,
        devanagariText: "\u0924\u0902 \u0938\u0942\u0930\u094d\u092f\u0902 \u091c\u0917\u0924\u094d\u0915\u0930\u094d\u0924\u093e\u0930\u0902 \u092e\u0939\u093e\u0924\u0947\u091c\u0903\u092a\u094d\u0930\u0926\u0940\u092a\u0928\u092e\u094d \u0964\n\u092e\u0939\u093e\u092a\u093e\u092a\u0939\u0930\u0902 \u0926\u0947\u0935\u0902 \u0924\u0902 \u0938\u0942\u0930\u094d\u092f\u0902 \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u094d\u092f\u0939\u092e\u094d \u0965 \u096d \u0965",
        iastText: "ta\u1e41 s\u016brya\u1e41 jagatkart\u0101ra\u1e41 mah\u0101t\u0113ja\u1e25prad\u012bpanam \u0964\nmah\u0101p\u0101pahara\u1e41 d\u0113va\u1e41 ta\u1e41 s\u016brya\u1e41 pra\u1e47am\u0101myaham \u0965 7 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c24\u0c02 \u0c38\u0c42\u0c30\u0c4d\u0c2f\u0c02 \u0c1c\u0c17\u0c24\u0c4d\u0c15\u0c30\u0c4d\u0c24\u0c3e\u0c30\u0c02 \u0c2e\u0c39\u0c3e\u0c24\u0c47\u0c1c\u0c03\u0c2a\u0c4d\u0c30\u0c26\u0c40\u0c2a\u0c28\u0c2e\u0c4d \u0964\n\u0c2e\u0c39\u0c3e\u0c2a\u0c3e\u0c2a\u0c39\u0c30\u0c02 \u0c26\u0c47\u0c35\u0c02 \u0c24\u0c02 \u0c38\u0c42\u0c30\u0c4d\u0c2f\u0c02 \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c4d\u0c2f\u0c39\u0c2e\u0c4d \u0965 \u0c6d \u0965", "tamil": "\u0ba4\u0bae\u0bcd \u0bb8\u0bc2\u0bb0\u0bcd\u0baf\u0bae\u0bcd \u0b9c\u0b95\u0ba4\u0bcd\u0b95\u0bb0\u0bcd\u0ba4\u0bbe\u0bb0\u0bae\u0bcd \u0bae\u0bb9\u0bbe\u0ba4\u0bc7\u0b9c\u0b83\u0baa\u0bcd\u0bb0\u0ba4\u0bc0\u0baa\u0ba8\u0bae\u0bcd \u0964\n\u0bae\u0bb9\u0bbe\u0baa\u0bbe\u0baa\u0bb9\u0bb0\u0bae\u0bcd \u0ba4\u0bc7\u0bb5\u0bae\u0bcd \u0ba4\u0bae\u0bcd \u0bb8\u0bc2\u0bb0\u0bcd\u0baf\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bcd\u0baf\u0bb9\u0bae\u0bcd \u0965 \u0bed \u0965", "kannada": "\u0ca4\u0c82 \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0c82 \u0c9c\u0c97\u0ca4\u0ccd\u0c95\u0cb0\u0ccd\u0ca4\u0cbe\u0cb0\u0c82 \u0cae\u0cb9\u0cbe\u0ca4\u0cc7\u0c9c\u0c83\u0caa\u0ccd\u0cb0\u0ca6\u0cc0\u0caa\u0ca8\u0cae\u0ccd \u0964\n\u0cae\u0cb9\u0cbe\u0caa\u0cbe\u0caa\u0cb9\u0cb0\u0c82 \u0ca6\u0cc7\u0cb5\u0c82 \u0ca4\u0c82 \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0c82 \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0ccd\u0caf\u0cb9\u0cae\u0ccd \u0965 \u0ced \u0965", "malayalam": "\u0d24\u0d02 \u0d38\u0d42\u0d30\u0d4d\u0d2f\u0d02 \u0d1c\u0d17\u0d24\u0d4d\u0d15\u0d30\u0d4d\u0d24\u0d3e\u0d30\u0d02 \u0d2e\u0d39\u0d3e\u0d24\u0d47\u0d1c\u0d03\u0d2a\u0d4d\u0d30\u0d26\u0d40\u0d2a\u0d28\u0d2e\u0d4d \u0964\n\u0d2e\u0d39\u0d3e\u0d2a\u0d3e\u0d2a\u0d39\u0d30\u0d02 \u0d26\u0d47\u0d35\u0d02 \u0d24\u0d02 \u0d38\u0d42\u0d30\u0d4d\u0d2f\u0d02 \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d4d\u0d2f\u0d39\u0d2e\u0d4d \u0965 \u0d6d \u0965", "iast": "ta\u1e43 s\u016brya\u1e43 jagatkart\u0101ra\u1e43 mah\u0101teja\u1e25prad\u012bpanam |\nmah\u0101p\u0101pahara\u1e43 deva\u1e43 ta\u1e43 s\u016brya\u1e43 pra\u1e47am\u0101myaham || 7 ||"},
        draftTranslation: "Unto that Sun who is the creator of the world, who blazes with supreme splendor, the divine remover of all sins, unto that Sun-God I bow down.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 8,
        devanagariText: "\u0924\u0902 \u0938\u0942\u0930\u094d\u092f\u0902 \u091c\u0917\u0924\u093e\u0902 \u0928\u093e\u0925\u0902 \u091c\u094d\u091e\u093e\u0928\u0935\u093f\u091c\u094d\u091e\u093e\u0928\u092e\u094b\u0915\u094d\u0937\u0926\u092e\u094d \u0964\n\u092e\u0939\u093e\u092a\u093e\u092a\u0939\u0930\u0902 \u0926\u0947\u0935\u0902 \u0924\u0902 \u0938\u0942\u0930\u094d\u092f\u0902 \u092a\u094d\u0930\u0923\u092e\u093e\u092e\u094d\u092f\u0939\u092e\u094d \u0965 \u096e \u0965",
        iastText: "ta\u1e41 s\u016brya\u1e41 jagat\u0101\u1e41 n\u0101tha\u1e41 j\u00f1\u0101navij\u00f1\u0101nam\u014dk\u1e63adam \u0964\nmah\u0101p\u0101pahara\u1e41 d\u0113va\u1e41 ta\u1e41 s\u016brya\u1e41 pra\u1e47am\u0101myaham \u0965 8 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c24\u0c02 \u0c38\u0c42\u0c30\u0c4d\u0c2f\u0c02 \u0c1c\u0c17\u0c24\u0c3e\u0c02 \u0c28\u0c3e\u0c25\u0c02 \u0c1c\u0c4d\u0c1e\u0c3e\u0c28\u0c35\u0c3f\u0c1c\u0c4d\u0c1e\u0c3e\u0c28\u0c2e\u0c4b\u0c15\u0c4d\u0c37\u0c26\u0c2e\u0c4d \u0964\n\u0c2e\u0c39\u0c3e\u0c2a\u0c3e\u0c2a\u0c39\u0c30\u0c02 \u0c26\u0c47\u0c35\u0c02 \u0c24\u0c02 \u0c38\u0c42\u0c30\u0c4d\u0c2f\u0c02 \u0c2a\u0c4d\u0c30\u0c23\u0c2e\u0c3e\u0c2e\u0c4d\u0c2f\u0c39\u0c2e\u0c4d \u0965 \u0c6e \u0965", "tamil": "\u0ba4\u0bae\u0bcd \u0bb8\u0bc2\u0bb0\u0bcd\u0baf\u0bae\u0bcd \u0b9c\u0b95\u0ba4\u0bbe\u0bae\u0bcd \u0ba8\u0bbe\u0ba4\u0bae\u0bcd \u0b9c\u0bcd\u0b9e\u0bbe\u0ba8\u0bb5\u0bbf\u0b9c\u0bcd\u0b9e\u0bbe\u0ba8\u0bae\u0bcb\u0b95\u0bcd\u0bb7\u0ba4\u0bae\u0bcd \u0964\n\u0bae\u0bb9\u0bbe\u0baa\u0bbe\u0baa\u0bb9\u0bb0\u0bae\u0bcd \u0ba4\u0bc7\u0bb5\u0bae\u0bcd \u0ba4\u0bae\u0bcd \u0bb8\u0bc2\u0bb0\u0bcd\u0baf\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0ba3\u0bae\u0bbe\u0bae\u0bcd\u0baf\u0bb9\u0bae\u0bcd \u0965 \u0bee \u0965", "kannada": "\u0ca4\u0c82 \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0c82 \u0c9c\u0c97\u0ca4\u0cbe\u0c82 \u0ca8\u0cbe\u0ca5\u0c82 \u0c9c\u0ccd\u0c9e\u0cbe\u0ca8\u0cb5\u0cbf\u0c9c\u0ccd\u0c9e\u0cbe\u0ca8\u0cae\u0ccb\u0c95\u0ccd\u0cb7\u0ca6\u0cae\u0ccd \u0964\n\u0cae\u0cb9\u0cbe\u0caa\u0cbe\u0caa\u0cb9\u0cb0\u0c82 \u0ca6\u0cc7\u0cb5\u0c82 \u0ca4\u0c82 \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0c82 \u0caa\u0ccd\u0cb0\u0ca3\u0cae\u0cbe\u0cae\u0ccd\u0caf\u0cb9\u0cae\u0ccd \u0965 \u0cee \u0965", "malayalam": "\u0d24\u0d02 \u0d38\u0d42\u0d30\u0d4d\u0d2f\u0d02 \u0d1c\u0d17\u0d24\u0d3e\u0d02 \u0d28\u0d3e\u0d25\u0d02 \u0d1c\u0d4d\u0d1e\u0d3e\u0d28\u0d35\u0d3f\u0d1c\u0d4d\u0d1e\u0d3e\u0d28\u0d2e\u0d4b\u0d15\u0d4d\u0d37\u0d26\u0d2e\u0d4d \u0964\n\u0d2e\u0d39\u0d3e\u0d2a\u0d3e\u0d2a\u0d39\u0d30\u0d02 \u0d26\u0d47\u0d35\u0d02 \u0d24\u0d02 \u0d38\u0d42\u0d30\u0d4d\u0d2f\u0d02 \u0d2a\u0d4d\u0d30\u0d23\u0d2e\u0d3e\u0d2e\u0d4d\u0d2f\u0d39\u0d2e\u0d4d \u0965 \u0d6e \u0965", "iast": "ta\u1e43 s\u016brya\u1e43 jagat\u0101\u1e43 n\u0101tha\u1e43 j\u00f1\u0101navij\u00f1\u0101namok\u1e63adam |\nmah\u0101p\u0101pahara\u1e43 deva\u1e43 ta\u1e43 s\u016brya\u1e43 pra\u1e47am\u0101myaham || 8 ||"},
        draftTranslation: "Unto that Sun who is the master of all worlds, the bestower of sacred knowledge, empirical discernment, and spiritual liberation, unto that Sun-God I bow down.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 9,
        devanagariText: "\u0938\u0942\u0930\u094d\u092f\u093e\u0937\u094d\u091f\u0915\u0902 \u092a\u0920\u0947\u0928\u094d\u0928\u093f\u0924\u094d\u092f\u0902 \u0917\u094d\u0930\u0939\u092a\u0940\u0921\u093e\u092a\u094d\u0930\u0923\u093e\u0936\u0928\u092e\u094d \u0964\n\u0905\u092a\u0941\u0924\u094d\u0930\u094b \u0932\u092d\u0924\u0947 \u092a\u0941\u0924\u094d\u0930\u0902 \u0926\u0930\u093f\u0926\u094d\u0930\u094b \u0927\u0928\u0935\u093e\u0928\u094d \u092d\u0935\u0947\u0924\u094d \u0965 \u096f \u0965",
        iastText: "s\u016bry\u0101\u1e63\u1e6daka\u1e41 pa\u1e6dh\u0113nnitya\u1e41 grahap\u012b\u1e0d\u0101pra\u1e47\u0101\u015banam \u0964\naputr\u014d labhat\u0113 putra\u1e41 daridr\u014d dhanav\u0101n bhav\u0113t \u0965 9 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c38\u0c42\u0c30\u0c4d\u0c2f\u0c3e\u0c37\u0c4d\u0c1f\u0c15\u0c02 \u0c2a\u0c20\u0c47\u0c28\u0c4d\u0c28\u0c3f\u0c24\u0c4d\u0c2f\u0c02 \u0c17\u0c4d\u0c30\u0c39\u0c2a\u0c40\u0c21\u0c3e\u0c2a\u0c4d\u0c30\u0c23\u0c3e\u0c36\u0c28\u0c2e\u0c4d \u0964\n\u0c05\u0c2a\u0c41\u0c24\u0c4d\u0c30\u0c4b \u0c32\u0c2d\u0c24\u0c47 \u0c2a\u0c41\u0c24\u0c4d\u0c30\u0c02 \u0c26\u0c30\u0c3f\u0c26\u0c4d\u0c30\u0c4b \u0c27\u0c28\u0c35\u0c3e\u0c28\u0c4d \u0c2d\u0c35\u0c47\u0c24\u0c4d \u0965 \u0c6f \u0965", "tamil": "\u0bb8\u0bc2\u0bb0\u0bcd\u0baf\u0bbe\u0bb7\u0bcd\u0b9f\u0b95\u0bae\u0bcd \u0baa\u0b9f\u0bc7\u0ba8\u0bcd\u0ba8\u0bbf\u0ba4\u0bcd\u0baf\u0bae\u0bcd \u0b95\u0bcd\u0bb0\u0bb9\u0baa\u0bc0\u0b9f\u0bbe\u0baa\u0bcd\u0bb0\u0ba3\u0bbe\u0bb6\u0ba8\u0bae\u0bcd \u0964\n\u0b85\u0baa\u0bc1\u0ba4\u0bcd\u0bb0\u0bcb \u0bb2\u0baa\u0ba4\u0bc7 \u0baa\u0bc1\u0ba4\u0bcd\u0bb0\u0bae\u0bcd \u0ba4\u0bb0\u0bbf\u0ba4\u0bcd\u0bb0\u0bcb \u0ba4\u0ba8\u0bb5\u0bbe\u0ba8\u0bcd \u0baa\u0bb5\u0bc7\u0ba4\u0bcd \u0965 \u0bef \u0965", "kannada": "\u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0cbe\u0cb7\u0ccd\u0c9f\u0c95\u0c82 \u0caa\u0ca0\u0cc7\u0ca8\u0ccd\u0ca8\u0cbf\u0ca4\u0ccd\u0caf\u0c82 \u0c97\u0ccd\u0cb0\u0cb9\u0caa\u0cc0\u0ca1\u0cbe\u0caa\u0ccd\u0cb0\u0ca3\u0cbe\u0cb6\u0ca8\u0cae\u0ccd \u0964\n\u0c85\u0caa\u0cc1\u0ca4\u0ccd\u0cb0\u0ccb \u0cb2\u0cad\u0ca4\u0cc7 \u0caa\u0cc1\u0ca4\u0ccd\u0cb0\u0c82 \u0ca6\u0cb0\u0cbf\u0ca6\u0ccd\u0cb0\u0ccb \u0ca7\u0ca8\u0cb5\u0cbe\u0ca8\u0ccd \u0cad\u0cb5\u0cc7\u0ca4\u0ccd \u0965 \u0cef \u0965", "malayalam": "\u0d38\u0d42\u0d30\u0d4d\u0d2f\u0d3e\u0d37\u0d4d\u0d1f\u0d15\u0d02 \u0d2a\u0d20\u0d47\u0d28\u0d4d\u0d28\u0d3f\u0d24\u0d4d\u0d2f\u0d02 \u0d17\u0d4d\u0d30\u0d39\u0d2a\u0d40\u0d21\u0d3e\u0d2a\u0d4d\u0d30\u0d23\u0d3e\u0d36\u0d28\u0d2e\u0d4d \u0964\n\u0d05\u0d2a\u0d41\u0d24\u0d4d\u0d30\u0d4b \u0d32\u0d2d\u0d24\u0d47 \u0d2a\u0d41\u0d24\u0d4d\u0d30\u0d02 \u0d26\u0d30\u0d3f\u0d26\u0d4d\u0d30\u0d4b \u0d27\u0d28\u0d35\u0d3e\u0d28\u0d4d \u0d2d\u0d35\u0d47\u0d24\u0d4d \u0965 \u0d6f \u0965", "iast": "s\u016bry\u0101\u1e63\u1e6daka\u1e43 pa\u1e6dhennitya\u1e43 grahap\u012b\u1e0d\u0101pra\u1e47\u0101\u015banam |\naputro labhate putra\u1e43 daridro dhanav\u0101n bhavet || 9 ||"},
        draftTranslation: "Whoever daily recites this Suryashtakam is freed from all planetary afflictions; the childless receives a noble child, and the impoverished becomes wealthy.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 10,
        devanagariText: "\u0906\u092e\u093f\u0937\u0902 \u092e\u0927\u0941\u092a\u093e\u0928\u0902 \u091a \u092f\u0903 \u0915\u0930\u094b\u0924\u093f \u0930\u0935\u0947\u0930\u094d\u0926\u093f\u0928\u0947 \u0964\n\u0938\u092a\u094d\u0924\u091c\u0928\u094d\u092e \u092d\u0935\u0947\u0926\u094d\u0930\u094b\u0917\u0940 \u091c\u0928\u094d\u092e\u091c\u0928\u094d\u092e \u0926\u0930\u093f\u0926\u094d\u0930\u0924\u093e \u0965 \u0967\u0966 \u0965",
        iastText: "\u0101mi\u1e63a\u1e41 madhup\u0101na\u1e41 ca ya\u1e25 kar\u014dti rav\u0113rdin\u0113 \u0964\nsaptajanma bhav\u0113dr\u014dg\u012b janmajanma daridrat\u0101 \u0965 10 \u0965",
        meter: "Anushtubh",
        transliterations: {"telugu": "\u0c06\u0c2e\u0c3f\u0c37\u0c02 \u0c2e\u0c27\u0c41\u0c2a\u0c3e\u0c28\u0c02 \u0c1a \u0c2f\u0c03 \u0c15\u0c30\u0c4b\u0c24\u0c3f \u0c30\u0c35\u0c47\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c47 \u0964\n\u0c38\u0c2a\u0c4d\u0c24\u0c1c\u0c28\u0c4d\u0c2e \u0c2d\u0c35\u0c47\u0c26\u0c4d\u0c30\u0c4b\u0c17\u0c40 \u0c1c\u0c28\u0c4d\u0c2e\u0c1c\u0c28\u0c4d\u0c2e \u0c26\u0c30\u0c3f\u0c26\u0c4d\u0c30\u0c24\u0c3e \u0965 \u0c67\u0c66 \u0965", "tamil": "\u0b86\u0bae\u0bbf\u0bb7\u0bae\u0bcd \u0bae\u0ba4\u0bc1\u0baa\u0bbe\u0ba8\u0bae\u0bcd \u0b9a \u0baf\u0b83 \u0b95\u0bb0\u0bcb\u0ba4\u0bbf \u0bb0\u0bb5\u0bc7\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bc7 \u0964\n\u0bb8\u0baa\u0bcd\u0ba4\u0b9c\u0ba8\u0bcd\u0bae \u0baa\u0bb5\u0bc7\u0ba4\u0bcd\u0bb0\u0bcb\u0b95\u0bc0 \u0b9c\u0ba8\u0bcd\u0bae\u0b9c\u0ba8\u0bcd\u0bae \u0ba4\u0bb0\u0bbf\u0ba4\u0bcd\u0bb0\u0ba4\u0bbe \u0965 \u0be7\u0be6 \u0965", "kannada": "\u0c86\u0cae\u0cbf\u0cb7\u0c82 \u0cae\u0ca7\u0cc1\u0caa\u0cbe\u0ca8\u0c82 \u0c9a \u0caf\u0c83 \u0c95\u0cb0\u0ccb\u0ca4\u0cbf \u0cb0\u0cb5\u0cc7\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cc7 \u0964\n\u0cb8\u0caa\u0ccd\u0ca4\u0c9c\u0ca8\u0ccd\u0cae \u0cad\u0cb5\u0cc7\u0ca6\u0ccd\u0cb0\u0ccb\u0c97\u0cc0 \u0c9c\u0ca8\u0ccd\u0cae\u0c9c\u0ca8\u0ccd\u0cae \u0ca6\u0cb0\u0cbf\u0ca6\u0ccd\u0cb0\u0ca4\u0cbe \u0965 \u0ce7\u0ce6 \u0965", "malayalam": "\u0d06\u0d2e\u0d3f\u0d37\u0d02 \u0d2e\u0d27\u0d41\u0d2a\u0d3e\u0d28\u0d02 \u0d1a \u0d2f\u0d03 \u0d15\u0d30\u0d4b\u0d24\u0d3f \u0d30\u0d35\u0d47\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d47 \u0964\n\u0d38\u0d2a\u0d4d\u0d24\u0d1c\u0d28\u0d4d\u0d2e \u0d2d\u0d35\u0d47\u0d26\u0d4d\u0d30\u0d4b\u0d17\u0d40 \u0d1c\u0d28\u0d4d\u0d2e\u0d1c\u0d28\u0d4d\u0d2e \u0d26\u0d30\u0d3f\u0d26\u0d4d\u0d30\u0d24\u0d3e \u0965 \u0d67\u0d66 \u0965", "iast": "\u0101mi\u1e63a\u1e43 madhup\u0101na\u1e43 ca ya\u1e25 karoti raverdine |\nsaptajanma bhavedrog\u012b janmajanma daridrat\u0101 || 10 ||"},
        draftTranslation: "Whoever consumes meat or intoxicating drinks on Sunday (the day of the Sun) suffers illness for seven births and poverty birth after birth. Therefore, let one worship the Sun with purity.",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
    ],
  ),
  Scripture(
    id: 21,
    contentId: "VEDA-TXT-00018",
    canonicalTitle: "Kanakadhara Stotram",
    devanagariTitle: "\u0915\u0928\u0915\u0927\u093e\u0930\u093e\u0938\u094d\u0924\u094b\u0924\u094d\u0930\u092e\u094d",
    category: "Stotra",
    deity: "Goddess Lakshmi / Devi",
    composer: "Adi Shankaracharya (c. 788\u2013820 CE)",
    rishi: "Traditional Vedic Sage",
    chandas: "Vasantatilaka",
    devata: "Goddess Lakshmi / Devi",
    sourceScripture: "Advaita Smartha Stotra Samgraha",
    traditionalUsage: "Removal of poverty, prosperity, abundance, Mahalakshmi Upasana",
    verseCount: 21,
    verses: [
      Verse(
        verseNumber: 1,
        devanagariText: "\u0905\u0919\u094d\u0917\u0902 \u0939\u0930\u0947\u0903 \u092a\u0941\u0932\u0915\u092d\u0942\u0937\u0923\u092e\u093e\u0936\u094d\u0930\u092f\u0928\u094d\u0924\u0940\n\u092d\u0943\u0919\u094d\u0917\u093e\u0919\u094d\u0917\u0928\u0947\u0935 \u092e\u0941\u0915\u0941\u0932\u093e\u092d\u0930\u0923\u0902 \u0924\u092e\u093e\u0932\u092e\u094d \u0964\n\u0905\u0919\u094d\u0917\u0940\u0915\u0943\u0924\u093e\u0916\u093f\u0932\u0935\u093f\u092d\u0942\u0924\u093f\u0930\u092a\u093e\u0919\u094d\u0917\u0932\u0940\u0932\u093e\n\u092e\u093e\u0919\u094d\u0917\u0932\u094d\u092f\u0926\u093e\u0938\u094d\u0924\u0941 \u092e\u092e \u092e\u0919\u094d\u0917\u0932\u0926\u0947\u0935\u0924\u093e\u092f\u093e\u0903 \u0965 \u0967 \u0965",
        iastText: "a\u1e45ga\u1e41 har\u0113\u1e25 pulakabh\u016b\u1e63a\u1e47am\u0101\u015brayant\u012b\nbh\u1e5b\u1e45g\u0101\u1e45gan\u0113va mukul\u0101bhara\u1e47a\u1e41 tam\u0101lam \u0964\na\u1e45g\u012bk\u1e5bt\u0101khilavibh\u016btirap\u0101\u1e45gal\u012bl\u0101\nm\u0101\u1e45galyad\u0101stu mama ma\u1e45galad\u0113vat\u0101y\u0101\u1e25 \u0965 1 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c05\u0c19\u0c4d\u0c17\u0c02 \u0c39\u0c30\u0c47\u0c03 \u0c2a\u0c41\u0c32\u0c15\u0c2d\u0c42\u0c37\u0c23\u0c2e\u0c3e\u0c36\u0c4d\u0c30\u0c2f\u0c28\u0c4d\u0c24\u0c40\n\u0c2d\u0c43\u0c19\u0c4d\u0c17\u0c3e\u0c19\u0c4d\u0c17\u0c28\u0c47\u0c35 \u0c2e\u0c41\u0c15\u0c41\u0c32\u0c3e\u0c2d\u0c30\u0c23\u0c02 \u0c24\u0c2e\u0c3e\u0c32\u0c2e\u0c4d \u0964\n\u0c05\u0c19\u0c4d\u0c17\u0c40\u0c15\u0c43\u0c24\u0c3e\u0c16\u0c3f\u0c32\u0c35\u0c3f\u0c2d\u0c42\u0c24\u0c3f\u0c30\u0c2a\u0c3e\u0c19\u0c4d\u0c17\u0c32\u0c40\u0c32\u0c3e\n\u0c2e\u0c3e\u0c19\u0c4d\u0c17\u0c32\u0c4d\u0c2f\u0c26\u0c3e\u0c38\u0c4d\u0c24\u0c41 \u0c2e\u0c2e \u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c26\u0c47\u0c35\u0c24\u0c3e\u0c2f\u0c3e\u0c03 \u0965 \u0c67 \u0965", "tamil": "\u0b85\u0b99\u0bcd\u0b95\u0bae\u0bcd \u0bb9\u0bb0\u0bc7\u0b83 \u0baa\u0bc1\u0bb2\u0b95\u0baa\u0bc2\u0bb7\u0ba3\u0bae\u0bbe\u0bb6\u0bcd\u0bb0\u0baf\u0ba8\u0bcd\u0ba4\u0bc0\n\u0baa\u0bcd\u0bb0\u0bc1'\u0b99\u0bcd\u0b95\u0bbe\u0b99\u0bcd\u0b95\u0ba8\u0bc7\u0bb5 \u0bae\u0bc1\u0b95\u0bc1\u0bb2\u0bbe\u0baa\u0bb0\u0ba3\u0bae\u0bcd \u0ba4\u0bae\u0bbe\u0bb2\u0bae\u0bcd \u0964\n\u0b85\u0b99\u0bcd\u0b95\u0bc0\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0bbe\u0b95\u0bbf\u0bb2\u0bb5\u0bbf\u0baa\u0bc2\u0ba4\u0bbf\u0bb0\u0baa\u0bbe\u0b99\u0bcd\u0b95\u0bb2\u0bc0\u0bb2\u0bbe\n\u0bae\u0bbe\u0b99\u0bcd\u0b95\u0bb2\u0bcd\u0baf\u0ba4\u0bbe\u0bb8\u0bcd\u0ba4\u0bc1 \u0bae\u0bae \u0bae\u0b99\u0bcd\u0b95\u0bb2\u0ba4\u0bc7\u0bb5\u0ba4\u0bbe\u0baf\u0bbe\u0b83 \u0965 \u0be7 \u0965", "kannada": "\u0c85\u0c99\u0ccd\u0c97\u0c82 \u0cb9\u0cb0\u0cc7\u0c83 \u0caa\u0cc1\u0cb2\u0c95\u0cad\u0cc2\u0cb7\u0ca3\u0cae\u0cbe\u0cb6\u0ccd\u0cb0\u0caf\u0ca8\u0ccd\u0ca4\u0cc0\n\u0cad\u0cc3\u0c99\u0ccd\u0c97\u0cbe\u0c99\u0ccd\u0c97\u0ca8\u0cc7\u0cb5 \u0cae\u0cc1\u0c95\u0cc1\u0cb2\u0cbe\u0cad\u0cb0\u0ca3\u0c82 \u0ca4\u0cae\u0cbe\u0cb2\u0cae\u0ccd \u0964\n\u0c85\u0c99\u0ccd\u0c97\u0cc0\u0c95\u0cc3\u0ca4\u0cbe\u0c96\u0cbf\u0cb2\u0cb5\u0cbf\u0cad\u0cc2\u0ca4\u0cbf\u0cb0\u0caa\u0cbe\u0c99\u0ccd\u0c97\u0cb2\u0cc0\u0cb2\u0cbe\n\u0cae\u0cbe\u0c99\u0ccd\u0c97\u0cb2\u0ccd\u0caf\u0ca6\u0cbe\u0cb8\u0ccd\u0ca4\u0cc1 \u0cae\u0cae \u0cae\u0c99\u0ccd\u0c97\u0cb2\u0ca6\u0cc7\u0cb5\u0ca4\u0cbe\u0caf\u0cbe\u0c83 \u0965 \u0ce7 \u0965", "malayalam": "\u0d05\u0d19\u0d4d\u0d17\u0d02 \u0d39\u0d30\u0d47\u0d03 \u0d2a\u0d41\u0d32\u0d15\u0d2d\u0d42\u0d37\u0d23\u0d2e\u0d3e\u0d36\u0d4d\u0d30\u0d2f\u0d28\u0d4d\u0d24\u0d40\n\u0d2d\u0d43\u0d19\u0d4d\u0d17\u0d3e\u0d19\u0d4d\u0d17\u0d28\u0d47\u0d35 \u0d2e\u0d41\u0d15\u0d41\u0d32\u0d3e\u0d2d\u0d30\u0d23\u0d02 \u0d24\u0d2e\u0d3e\u0d32\u0d2e\u0d4d \u0964\n\u0d05\u0d19\u0d4d\u0d17\u0d40\u0d15\u0d43\u0d24\u0d3e\u0d16\u0d3f\u0d32\u0d35\u0d3f\u0d2d\u0d42\u0d24\u0d3f\u0d30\u0d2a\u0d3e\u0d19\u0d4d\u0d17\u0d32\u0d40\u0d32\u0d3e\n\u0d2e\u0d3e\u0d19\u0d4d\u0d17\u0d32\u0d4d\u0d2f\u0d26\u0d3e\u0d38\u0d4d\u0d24\u0d41 \u0d2e\u0d2e \u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d26\u0d47\u0d35\u0d24\u0d3e\u0d2f\u0d3e\u0d03 \u0965 \u0d67 \u0965", "iast": "a\u1e45ga\u1e43 hare\u1e25 pulakabh\u016b\u1e63a\u1e47am\u0101\u015brayant\u012b\nbh\u1e5b\u1e45g\u0101\u1e45ganeva mukul\u0101bhara\u1e47a\u1e43 tam\u0101lam |\na\u1e45g\u012bk\u1e5bt\u0101khilavibh\u016btirap\u0101\u1e45gal\u012bl\u0101\nm\u0101\u1e45galyad\u0101stu mama ma\u1e45galadevat\u0101y\u0101\u1e25 || 1 ||"},
        draftTranslation: "Like a honeybee resting upon a dark blossom-laden Tamala tree, the glance of Goddess Sri Lakshmi rests on the dark form of Lord Hari, causing hairs of divine joy to thrill. May that glance of the Goddess of all auspiciousness bestow prosperity upon me!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 2,
        devanagariText: "\u092e\u0941\u0917\u094d\u0927\u093e \u092e\u0941\u0939\u0941\u0930\u094d\u0935\u093f\u0926\u0927\u0924\u0940 \u0935\u0926\u0928\u0947 \u092e\u0941\u0930\u093e\u0930\u0947\u0903\n\u092a\u094d\u0930\u0947\u092e\u0924\u094d\u0930\u092a\u093e\u092a\u094d\u0930\u0923\u093f\u0939\u093f\u0924\u093e\u0928\u093f \u0917\u0924\u093e\u0917\u0924\u093e\u0928\u093f \u0964\n\u092e\u093e\u0932\u093e \u0926\u0943\u0936\u094b\u0930\u094d\u092e\u0927\u0941\u0915\u0930\u0940\u0935 \u092e\u0939\u094b\u0924\u094d\u092a\u0932\u0947 \u092f\u093e\n\u0938\u093e \u092e\u0947 \u0936\u094d\u0930\u093f\u092f\u0902 \u0926\u093f\u0936\u0924\u0941 \u0938\u093e\u0917\u0930\u0938\u0902\u092d\u0935\u093e\u092f\u093e\u0903 \u0965 \u0968 \u0965",
        iastText: "mugdh\u0101 muhurvidadhat\u012b vadan\u0113 mur\u0101r\u0113\u1e25\npr\u0113matrap\u0101pra\u1e47ihit\u0101ni gat\u0101gat\u0101ni \u0964\nm\u0101l\u0101 d\u1e5b\u015b\u014drmadhukar\u012bva mah\u014dtpal\u0113 y\u0101\ns\u0101 m\u0113 \u015briya\u1e41 di\u015batu s\u0101garasa\u1e41bhav\u0101y\u0101\u1e25 \u0965 2 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2e\u0c41\u0c17\u0c4d\u0c27\u0c3e \u0c2e\u0c41\u0c39\u0c41\u0c30\u0c4d\u0c35\u0c3f\u0c26\u0c27\u0c24\u0c40 \u0c35\u0c26\u0c28\u0c47 \u0c2e\u0c41\u0c30\u0c3e\u0c30\u0c47\u0c03\n\u0c2a\u0c4d\u0c30\u0c47\u0c2e\u0c24\u0c4d\u0c30\u0c2a\u0c3e\u0c2a\u0c4d\u0c30\u0c23\u0c3f\u0c39\u0c3f\u0c24\u0c3e\u0c28\u0c3f \u0c17\u0c24\u0c3e\u0c17\u0c24\u0c3e\u0c28\u0c3f \u0964\n\u0c2e\u0c3e\u0c32\u0c3e \u0c26\u0c43\u0c36\u0c4b\u0c30\u0c4d\u0c2e\u0c27\u0c41\u0c15\u0c30\u0c40\u0c35 \u0c2e\u0c39\u0c4b\u0c24\u0c4d\u0c2a\u0c32\u0c47 \u0c2f\u0c3e\n\u0c38\u0c3e \u0c2e\u0c47 \u0c36\u0c4d\u0c30\u0c3f\u0c2f\u0c02 \u0c26\u0c3f\u0c36\u0c24\u0c41 \u0c38\u0c3e\u0c17\u0c30\u0c38\u0c02\u0c2d\u0c35\u0c3e\u0c2f\u0c3e\u0c03 \u0965 \u0c68 \u0965", "tamil": "\u0bae\u0bc1\u0b95\u0bcd\u0ba4\u0bbe \u0bae\u0bc1\u0bb9\u0bc1\u0bb0\u0bcd\u0bb5\u0bbf\u0ba4\u0ba4\u0ba4\u0bc0 \u0bb5\u0ba4\u0ba8\u0bc7 \u0bae\u0bc1\u0bb0\u0bbe\u0bb0\u0bc7\u0b83\n\u0baa\u0bcd\u0bb0\u0bc7\u0bae\u0ba4\u0bcd\u0bb0\u0baa\u0bbe\u0baa\u0bcd\u0bb0\u0ba3\u0bbf\u0bb9\u0bbf\u0ba4\u0bbe\u0ba8\u0bbf \u0b95\u0ba4\u0bbe\u0b95\u0ba4\u0bbe\u0ba8\u0bbf \u0964\n\u0bae\u0bbe\u0bb2\u0bbe \u0ba4\u0bcd\u0bb0\u0bc1'\u0bb6\u0bcb\u0bb0\u0bcd\u0bae\u0ba4\u0bc1\u0b95\u0bb0\u0bc0\u0bb5 \u0bae\u0bb9\u0bcb\u0ba4\u0bcd\u0baa\u0bb2\u0bc7 \u0baf\u0bbe\n\u0bb8\u0bbe \u0bae\u0bc7 \u0bb6\u0bcd\u0bb0\u0bbf\u0baf\u0bae\u0bcd \u0ba4\u0bbf\u0bb6\u0ba4\u0bc1 \u0bb8\u0bbe\u0b95\u0bb0\u0bb8\u0bae\u0bcd\u0baa\u0bb5\u0bbe\u0baf\u0bbe\u0b83 \u0965 \u0be8 \u0965", "kannada": "\u0cae\u0cc1\u0c97\u0ccd\u0ca7\u0cbe \u0cae\u0cc1\u0cb9\u0cc1\u0cb0\u0ccd\u0cb5\u0cbf\u0ca6\u0ca7\u0ca4\u0cc0 \u0cb5\u0ca6\u0ca8\u0cc7 \u0cae\u0cc1\u0cb0\u0cbe\u0cb0\u0cc7\u0c83\n\u0caa\u0ccd\u0cb0\u0cc7\u0cae\u0ca4\u0ccd\u0cb0\u0caa\u0cbe\u0caa\u0ccd\u0cb0\u0ca3\u0cbf\u0cb9\u0cbf\u0ca4\u0cbe\u0ca8\u0cbf \u0c97\u0ca4\u0cbe\u0c97\u0ca4\u0cbe\u0ca8\u0cbf \u0964\n\u0cae\u0cbe\u0cb2\u0cbe \u0ca6\u0cc3\u0cb6\u0ccb\u0cb0\u0ccd\u0cae\u0ca7\u0cc1\u0c95\u0cb0\u0cc0\u0cb5 \u0cae\u0cb9\u0ccb\u0ca4\u0ccd\u0caa\u0cb2\u0cc7 \u0caf\u0cbe\n\u0cb8\u0cbe \u0cae\u0cc7 \u0cb6\u0ccd\u0cb0\u0cbf\u0caf\u0c82 \u0ca6\u0cbf\u0cb6\u0ca4\u0cc1 \u0cb8\u0cbe\u0c97\u0cb0\u0cb8\u0c82\u0cad\u0cb5\u0cbe\u0caf\u0cbe\u0c83 \u0965 \u0ce8 \u0965", "malayalam": "\u0d2e\u0d41\u0d17\u0d4d\u0d27\u0d3e \u0d2e\u0d41\u0d39\u0d41\u0d30\u0d4d\u0d35\u0d3f\u0d26\u0d27\u0d24\u0d40 \u0d35\u0d26\u0d28\u0d47 \u0d2e\u0d41\u0d30\u0d3e\u0d30\u0d47\u0d03\n\u0d2a\u0d4d\u0d30\u0d47\u0d2e\u0d24\u0d4d\u0d30\u0d2a\u0d3e\u0d2a\u0d4d\u0d30\u0d23\u0d3f\u0d39\u0d3f\u0d24\u0d3e\u0d28\u0d3f \u0d17\u0d24\u0d3e\u0d17\u0d24\u0d3e\u0d28\u0d3f \u0964\n\u0d2e\u0d3e\u0d32\u0d3e \u0d26\u0d43\u0d36\u0d4b\u0d30\u0d4d\u0d2e\u0d27\u0d41\u0d15\u0d30\u0d40\u0d35 \u0d2e\u0d39\u0d4b\u0d24\u0d4d\u0d2a\u0d32\u0d47 \u0d2f\u0d3e\n\u0d38\u0d3e \u0d2e\u0d47 \u0d36\u0d4d\u0d30\u0d3f\u0d2f\u0d02 \u0d26\u0d3f\u0d36\u0d24\u0d41 \u0d38\u0d3e\u0d17\u0d30\u0d38\u0d02\u0d2d\u0d35\u0d3e\u0d2f\u0d3e\u0d03 \u0965 \u0d68 \u0965", "iast": "mugdh\u0101 muhurvidadhat\u012b vadane mur\u0101re\u1e25\nprematrap\u0101pra\u1e47ihit\u0101ni gat\u0101gat\u0101ni |\nm\u0101l\u0101 d\u1e5b\u015bormadhukar\u012bva mahotpale y\u0101\ns\u0101 me \u015briya\u1e43 di\u015batu s\u0101garasa\u1e43bhav\u0101y\u0101\u1e25 || 2 ||"},
        draftTranslation: "Gazing coyly upon the face of Murari, moving back and forth with love and modesty like bees hovering around a grand blue lotus \u2014 may that glance of the ocean-born Goddess bestow auspicious wealth upon me!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 3,
        devanagariText: "\u0906\u092e\u0940\u0932\u093f\u0924\u093e\u0915\u094d\u0937\u092e\u0927\u093f\u0917\u092e\u094d\u092f \u092e\u0941\u0926\u093e \u092e\u0941\u0915\u0941\u0928\u094d\u0926\u092e\u094d\n\u0906\u0928\u0928\u094d\u0926\u0915\u0928\u094d\u0926\u092e\u0928\u093f\u092e\u0947\u0937\u092e\u0928\u0919\u094d\u0917\u0924\u0928\u094d\u0924\u094d\u0930\u092e\u094d \u0964\n\u0906\u0915\u0947\u0915\u0930\u0938\u094d\u0925\u093f\u0924\u0915\u0928\u0940\u0928\u093f\u0915\u092a\u0915\u094d\u0937\u094d\u092e\u0928\u0947\u0924\u094d\u0930\u0902\n\u092d\u0942\u0924\u094d\u092f\u0948 \u092d\u0935\u0947\u0928\u094d\u092e\u092e \u092d\u0941\u091c\u0919\u094d\u0917\u0936\u092f\u093e\u0919\u094d\u0917\u0928\u093e\u092f\u093e\u0903 \u0965 \u0969 \u0965",
        iastText: "\u0101m\u012blit\u0101k\u1e63amadhigamya mud\u0101 mukundam\n\u0101nandakandamanim\u0113\u1e63amana\u1e45gatantram \u0964\n\u0101k\u0113karasthitakan\u012bnikapak\u1e63man\u0113tra\u1e41\nbh\u016btyai bhav\u0113nmama bhuja\u1e45ga\u015bay\u0101\u1e45gan\u0101y\u0101\u1e25 \u0965 3 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c06\u0c2e\u0c40\u0c32\u0c3f\u0c24\u0c3e\u0c15\u0c4d\u0c37\u0c2e\u0c27\u0c3f\u0c17\u0c2e\u0c4d\u0c2f \u0c2e\u0c41\u0c26\u0c3e \u0c2e\u0c41\u0c15\u0c41\u0c28\u0c4d\u0c26\u0c2e\u0c4d\n\u0c06\u0c28\u0c28\u0c4d\u0c26\u0c15\u0c28\u0c4d\u0c26\u0c2e\u0c28\u0c3f\u0c2e\u0c47\u0c37\u0c2e\u0c28\u0c19\u0c4d\u0c17\u0c24\u0c28\u0c4d\u0c24\u0c4d\u0c30\u0c2e\u0c4d \u0964\n\u0c06\u0c15\u0c47\u0c15\u0c30\u0c38\u0c4d\u0c25\u0c3f\u0c24\u0c15\u0c28\u0c40\u0c28\u0c3f\u0c15\u0c2a\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c28\u0c47\u0c24\u0c4d\u0c30\u0c02\n\u0c2d\u0c42\u0c24\u0c4d\u0c2f\u0c48 \u0c2d\u0c35\u0c47\u0c28\u0c4d\u0c2e\u0c2e \u0c2d\u0c41\u0c1c\u0c19\u0c4d\u0c17\u0c36\u0c2f\u0c3e\u0c19\u0c4d\u0c17\u0c28\u0c3e\u0c2f\u0c3e\u0c03 \u0965 \u0c69 \u0965", "tamil": "\u0b86\u0bae\u0bc0\u0bb2\u0bbf\u0ba4\u0bbe\u0b95\u0bcd\u0bb7\u0bae\u0ba4\u0bbf\u0b95\u0bae\u0bcd\u0baf \u0bae\u0bc1\u0ba4\u0bbe \u0bae\u0bc1\u0b95\u0bc1\u0ba8\u0bcd\u0ba4\u0bae\u0bcd\n\u0b86\u0ba8\u0ba8\u0bcd\u0ba4\u0b95\u0ba8\u0bcd\u0ba4\u0bae\u0ba8\u0bbf\u0bae\u0bc7\u0bb7\u0bae\u0ba8\u0b99\u0bcd\u0b95\u0ba4\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bae\u0bcd \u0964\n\u0b86\u0b95\u0bc7\u0b95\u0bb0\u0bb8\u0bcd\u0ba4\u0bbf\u0ba4\u0b95\u0ba8\u0bc0\u0ba8\u0bbf\u0b95\u0baa\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0ba8\u0bc7\u0ba4\u0bcd\u0bb0\u0bae\u0bcd\n\u0baa\u0bc2\u0ba4\u0bcd\u0baf\u0bc8 \u0baa\u0bb5\u0bc7\u0ba8\u0bcd\u0bae\u0bae \u0baa\u0bc1\u0b9c\u0b99\u0bcd\u0b95\u0bb6\u0baf\u0bbe\u0b99\u0bcd\u0b95\u0ba8\u0bbe\u0baf\u0bbe\u0b83 \u0965 \u0be9 \u0965", "kannada": "\u0c86\u0cae\u0cc0\u0cb2\u0cbf\u0ca4\u0cbe\u0c95\u0ccd\u0cb7\u0cae\u0ca7\u0cbf\u0c97\u0cae\u0ccd\u0caf \u0cae\u0cc1\u0ca6\u0cbe \u0cae\u0cc1\u0c95\u0cc1\u0ca8\u0ccd\u0ca6\u0cae\u0ccd\n\u0c86\u0ca8\u0ca8\u0ccd\u0ca6\u0c95\u0ca8\u0ccd\u0ca6\u0cae\u0ca8\u0cbf\u0cae\u0cc7\u0cb7\u0cae\u0ca8\u0c99\u0ccd\u0c97\u0ca4\u0ca8\u0ccd\u0ca4\u0ccd\u0cb0\u0cae\u0ccd \u0964\n\u0c86\u0c95\u0cc7\u0c95\u0cb0\u0cb8\u0ccd\u0ca5\u0cbf\u0ca4\u0c95\u0ca8\u0cc0\u0ca8\u0cbf\u0c95\u0caa\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0ca8\u0cc7\u0ca4\u0ccd\u0cb0\u0c82\n\u0cad\u0cc2\u0ca4\u0ccd\u0caf\u0cc8 \u0cad\u0cb5\u0cc7\u0ca8\u0ccd\u0cae\u0cae \u0cad\u0cc1\u0c9c\u0c99\u0ccd\u0c97\u0cb6\u0caf\u0cbe\u0c99\u0ccd\u0c97\u0ca8\u0cbe\u0caf\u0cbe\u0c83 \u0965 \u0ce9 \u0965", "malayalam": "\u0d06\u0d2e\u0d40\u0d32\u0d3f\u0d24\u0d3e\u0d15\u0d4d\u0d37\u0d2e\u0d27\u0d3f\u0d17\u0d2e\u0d4d\u0d2f \u0d2e\u0d41\u0d26\u0d3e \u0d2e\u0d41\u0d15\u0d41\u0d28\u0d4d\u0d26\u0d2e\u0d4d\n\u0d06\u0d28\u0d28\u0d4d\u0d26\u0d15\u0d28\u0d4d\u0d26\u0d2e\u0d28\u0d3f\u0d2e\u0d47\u0d37\u0d2e\u0d28\u0d19\u0d4d\u0d17\u0d24\u0d28\u0d4d\u0d24\u0d4d\u0d30\u0d2e\u0d4d \u0964\n\u0d06\u0d15\u0d47\u0d15\u0d30\u0d38\u0d4d\u0d25\u0d3f\u0d24\u0d15\u0d28\u0d40\u0d28\u0d3f\u0d15\u0d2a\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d28\u0d47\u0d24\u0d4d\u0d30\u0d02\n\u0d2d\u0d42\u0d24\u0d4d\u0d2f\u0d48 \u0d2d\u0d35\u0d47\u0d28\u0d4d\u0d2e\u0d2e \u0d2d\u0d41\u0d1c\u0d19\u0d4d\u0d17\u0d36\u0d2f\u0d3e\u0d19\u0d4d\u0d17\u0d28\u0d3e\u0d2f\u0d3e\u0d03 \u0965 \u0d69 \u0965", "iast": "\u0101m\u012blit\u0101k\u1e63amadhigamya mud\u0101 mukundam\n\u0101nandakandamanime\u1e63amana\u1e45gatantram |\n\u0101kekarasthitakan\u012bnikapak\u1e63manetra\u1e43\nbh\u016btyai bhavenmama bhuja\u1e45ga\u015bay\u0101\u1e45gan\u0101y\u0101\u1e25 || 3 ||"},
        draftTranslation: "Looking upon Lord Mukunda, the root of bliss, who blissfully closes His eyes in transcendental slumber, may the half-closed, tenderly glancing eyes of the consort of the serpent-reclining Lord bring boundless spiritual abundance unto me!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 4,
        devanagariText: "\u092c\u093e\u0939\u094d\u0935\u0928\u094d\u0924\u0930\u0947 \u092e\u0927\u0941\u091c\u093f\u0924\u0903 \u0936\u094d\u0930\u093f\u0924\u0915\u094c\u0938\u094d\u0924\u0941\u092d\u0947 \u092f\u093e\n\u0939\u093e\u0930\u093e\u0935\u0932\u0940\u0935 \u0939\u0930\u093f\u0928\u0940\u0932\u092e\u092f\u0940 \u0935\u093f\u092d\u093e\u0924\u093f \u0964\n\u0915\u093e\u092e\u092a\u094d\u0930\u0926\u093e \u092d\u0917\u0935\u0924\u094b\u093d\u092a\u093f \u0915\u091f\u093e\u0915\u094d\u0937\u092e\u093e\u0932\u093e\n\u0915\u0932\u094d\u092f\u093e\u0923\u092e\u093e\u0935\u0939\u0924\u0941 \u092e\u0947 \u0915\u092e\u0932\u093e\u0932\u092f\u093e\u092f\u093e\u0903 \u0965 \u096a \u0965",
        iastText: "b\u0101hvantar\u0113 madhujita\u1e25 \u015britakaustubh\u0113 y\u0101\nh\u0101r\u0101val\u012bva harin\u012blamay\u012b vibh\u0101ti \u0964\nk\u0101maprad\u0101 bhagavat\u014d'pi ka\u1e6d\u0101k\u1e63am\u0101l\u0101\nkaly\u0101\u1e47am\u0101vahatu m\u0113 kamal\u0101lay\u0101y\u0101\u1e25 \u0965 4 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2c\u0c3e\u0c39\u0c4d\u0c35\u0c28\u0c4d\u0c24\u0c30\u0c47 \u0c2e\u0c27\u0c41\u0c1c\u0c3f\u0c24\u0c03 \u0c36\u0c4d\u0c30\u0c3f\u0c24\u0c15\u0c4c\u0c38\u0c4d\u0c24\u0c41\u0c2d\u0c47 \u0c2f\u0c3e\n\u0c39\u0c3e\u0c30\u0c3e\u0c35\u0c32\u0c40\u0c35 \u0c39\u0c30\u0c3f\u0c28\u0c40\u0c32\u0c2e\u0c2f\u0c40 \u0c35\u0c3f\u0c2d\u0c3e\u0c24\u0c3f \u0964\n\u0c15\u0c3e\u0c2e\u0c2a\u0c4d\u0c30\u0c26\u0c3e \u0c2d\u0c17\u0c35\u0c24\u0c4b\u0c3d\u0c2a\u0c3f \u0c15\u0c1f\u0c3e\u0c15\u0c4d\u0c37\u0c2e\u0c3e\u0c32\u0c3e\n\u0c15\u0c32\u0c4d\u0c2f\u0c3e\u0c23\u0c2e\u0c3e\u0c35\u0c39\u0c24\u0c41 \u0c2e\u0c47 \u0c15\u0c2e\u0c32\u0c3e\u0c32\u0c2f\u0c3e\u0c2f\u0c3e\u0c03 \u0965 \u0c6a \u0965", "tamil": "\u0baa\u0bbe\u0bb9\u0bcd\u0bb5\u0ba8\u0bcd\u0ba4\u0bb0\u0bc7 \u0bae\u0ba4\u0bc1\u0b9c\u0bbf\u0ba4\u0b83 \u0bb6\u0bcd\u0bb0\u0bbf\u0ba4\u0b95\u0bcc\u0bb8\u0bcd\u0ba4\u0bc1\u0baa\u0bc7 \u0baf\u0bbe\n\u0bb9\u0bbe\u0bb0\u0bbe\u0bb5\u0bb2\u0bc0\u0bb5 \u0bb9\u0bb0\u0bbf\u0ba8\u0bc0\u0bb2\u0bae\u0baf\u0bc0 \u0bb5\u0bbf\u0baa\u0bbe\u0ba4\u0bbf \u0964\n\u0b95\u0bbe\u0bae\u0baa\u0bcd\u0bb0\u0ba4\u0bbe \u0baa\u0b95\u0bb5\u0ba4\u0bcb\u093d\u0baa\u0bbf \u0b95\u0b9f\u0bbe\u0b95\u0bcd\u0bb7\u0bae\u0bbe\u0bb2\u0bbe\n\u0b95\u0bb2\u0bcd\u0baf\u0bbe\u0ba3\u0bae\u0bbe\u0bb5\u0bb9\u0ba4\u0bc1 \u0bae\u0bc7 \u0b95\u0bae\u0bb2\u0bbe\u0bb2\u0baf\u0bbe\u0baf\u0bbe\u0b83 \u0965 \u0bea \u0965", "kannada": "\u0cac\u0cbe\u0cb9\u0ccd\u0cb5\u0ca8\u0ccd\u0ca4\u0cb0\u0cc7 \u0cae\u0ca7\u0cc1\u0c9c\u0cbf\u0ca4\u0c83 \u0cb6\u0ccd\u0cb0\u0cbf\u0ca4\u0c95\u0ccc\u0cb8\u0ccd\u0ca4\u0cc1\u0cad\u0cc7 \u0caf\u0cbe\n\u0cb9\u0cbe\u0cb0\u0cbe\u0cb5\u0cb2\u0cc0\u0cb5 \u0cb9\u0cb0\u0cbf\u0ca8\u0cc0\u0cb2\u0cae\u0caf\u0cc0 \u0cb5\u0cbf\u0cad\u0cbe\u0ca4\u0cbf \u0964\n\u0c95\u0cbe\u0cae\u0caa\u0ccd\u0cb0\u0ca6\u0cbe \u0cad\u0c97\u0cb5\u0ca4\u0ccb\u0cbd\u0caa\u0cbf \u0c95\u0c9f\u0cbe\u0c95\u0ccd\u0cb7\u0cae\u0cbe\u0cb2\u0cbe\n\u0c95\u0cb2\u0ccd\u0caf\u0cbe\u0ca3\u0cae\u0cbe\u0cb5\u0cb9\u0ca4\u0cc1 \u0cae\u0cc7 \u0c95\u0cae\u0cb2\u0cbe\u0cb2\u0caf\u0cbe\u0caf\u0cbe\u0c83 \u0965 \u0cea \u0965", "malayalam": "\u0d2c\u0d3e\u0d39\u0d4d\u0d35\u0d28\u0d4d\u0d24\u0d30\u0d47 \u0d2e\u0d27\u0d41\u0d1c\u0d3f\u0d24\u0d03 \u0d36\u0d4d\u0d30\u0d3f\u0d24\u0d15\u0d4c\u0d38\u0d4d\u0d24\u0d41\u0d2d\u0d47 \u0d2f\u0d3e\n\u0d39\u0d3e\u0d30\u0d3e\u0d35\u0d32\u0d40\u0d35 \u0d39\u0d30\u0d3f\u0d28\u0d40\u0d32\u0d2e\u0d2f\u0d40 \u0d35\u0d3f\u0d2d\u0d3e\u0d24\u0d3f \u0964\n\u0d15\u0d3e\u0d2e\u0d2a\u0d4d\u0d30\u0d26\u0d3e \u0d2d\u0d17\u0d35\u0d24\u0d4b\u0d3d\u0d2a\u0d3f \u0d15\u0d1f\u0d3e\u0d15\u0d4d\u0d37\u0d2e\u0d3e\u0d32\u0d3e\n\u0d15\u0d32\u0d4d\u0d2f\u0d3e\u0d23\u0d2e\u0d3e\u0d35\u0d39\u0d24\u0d41 \u0d2e\u0d47 \u0d15\u0d2e\u0d32\u0d3e\u0d32\u0d2f\u0d3e\u0d2f\u0d3e\u0d03 \u0965 \u0d6a \u0965", "iast": "b\u0101hvantare madhujita\u1e25 \u015britakaustubhe y\u0101\nh\u0101r\u0101val\u012bva harin\u012blamay\u012b vibh\u0101ti |\nk\u0101maprad\u0101 bhagavato'pi ka\u1e6d\u0101k\u1e63am\u0101l\u0101\nkaly\u0101\u1e47am\u0101vahatu me kamal\u0101lay\u0101y\u0101\u1e25 || 4 ||"},
        draftTranslation: "Shining like a necklace of sapphires upon the Kaustubha-adorned bosom of Madhusudana, awakening love even in the Supreme Lord Himself \u2014 may that glance of Kamala (Lakshmi) bring supreme blessings unto me!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 5,
        devanagariText: "\u0915\u093e\u0932\u093e\u092e\u094d\u092c\u0941\u0926\u093e\u0932\u093f\u0932\u0932\u093f\u0924\u094b\u0930\u0938\u093f \u0915\u0948\u091f\u092d\u093e\u0930\u0947-\n\u0930\u094d\u0927\u093e\u0930\u093e\u0927\u0930\u0947 \u0938\u094d\u092b\u0941\u0930\u0924\u093f \u092f\u093e \u0924\u0921\u093f\u0926\u0919\u094d\u0917\u0928\u0947\u0935 \u0964\n\u092e\u093e\u0924\u0941\u0903 \u0938\u092e\u0938\u094d\u0924\u091c\u0917\u0924\u093e\u0902 \u092e\u0939\u0928\u0940\u092f\u092e\u0942\u0930\u094d\u0924\u093f\u0903\n\u092d\u0926\u094d\u0930\u093e\u0923\u093f \u092e\u0947 \u0926\u093f\u0936\u0924\u0941 \u092d\u093e\u0930\u094d\u0917\u0935\u0928\u0928\u094d\u0926\u0928\u093e\u092f\u093e\u0903 \u0965 \u096b \u0965",
        iastText: "k\u0101l\u0101mbud\u0101lilalit\u014drasi kai\u1e6dabh\u0101r\u0113-\nrdh\u0101r\u0101dhar\u0113 sphurati y\u0101 ta\u1e0dida\u1e45gan\u0113va \u0964\nm\u0101tu\u1e25 samastajagat\u0101\u1e41 mahan\u012byam\u016brti\u1e25\nbhadr\u0101\u1e47i m\u0113 di\u015batu bh\u0101rgavanandan\u0101y\u0101\u1e25 \u0965 5 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c15\u0c3e\u0c32\u0c3e\u0c2e\u0c4d\u0c2c\u0c41\u0c26\u0c3e\u0c32\u0c3f\u0c32\u0c32\u0c3f\u0c24\u0c4b\u0c30\u0c38\u0c3f \u0c15\u0c48\u0c1f\u0c2d\u0c3e\u0c30\u0c47-\n\u0c30\u0c4d\u0c27\u0c3e\u0c30\u0c3e\u0c27\u0c30\u0c47 \u0c38\u0c4d\u0c2b\u0c41\u0c30\u0c24\u0c3f \u0c2f\u0c3e \u0c24\u0c21\u0c3f\u0c26\u0c19\u0c4d\u0c17\u0c28\u0c47\u0c35 \u0964\n\u0c2e\u0c3e\u0c24\u0c41\u0c03 \u0c38\u0c2e\u0c38\u0c4d\u0c24\u0c1c\u0c17\u0c24\u0c3e\u0c02 \u0c2e\u0c39\u0c28\u0c40\u0c2f\u0c2e\u0c42\u0c30\u0c4d\u0c24\u0c3f\u0c03\n\u0c2d\u0c26\u0c4d\u0c30\u0c3e\u0c23\u0c3f \u0c2e\u0c47 \u0c26\u0c3f\u0c36\u0c24\u0c41 \u0c2d\u0c3e\u0c30\u0c4d\u0c17\u0c35\u0c28\u0c28\u0c4d\u0c26\u0c28\u0c3e\u0c2f\u0c3e\u0c03 \u0965 \u0c6b \u0965", "tamil": "\u0b95\u0bbe\u0bb2\u0bbe\u0bae\u0bcd\u0baa\u0bc1\u0ba4\u0bbe\u0bb2\u0bbf\u0bb2\u0bb2\u0bbf\u0ba4\u0bcb\u0bb0\u0bb8\u0bbf \u0b95\u0bc8\u0b9f\u0baa\u0bbe\u0bb0\u0bc7-\n\u0bb0\u0bcd\u0ba4\u0bbe\u0bb0\u0bbe\u0ba4\u0bb0\u0bc7 \u0bb8\u0bcd\u0baa\u0bc1\u0bb0\u0ba4\u0bbf \u0baf\u0bbe \u0ba4\u0b9f\u0bbf\u0ba4\u0b99\u0bcd\u0b95\u0ba8\u0bc7\u0bb5 \u0964\n\u0bae\u0bbe\u0ba4\u0bc1\u0b83 \u0bb8\u0bae\u0bb8\u0bcd\u0ba4\u0b9c\u0b95\u0ba4\u0bbe\u0bae\u0bcd \u0bae\u0bb9\u0ba8\u0bc0\u0baf\u0bae\u0bc2\u0bb0\u0bcd\u0ba4\u0bbf\u0b83\n\u0baa\u0ba4\u0bcd\u0bb0\u0bbe\u0ba3\u0bbf \u0bae\u0bc7 \u0ba4\u0bbf\u0bb6\u0ba4\u0bc1 \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bb5\u0ba8\u0ba8\u0bcd\u0ba4\u0ba8\u0bbe\u0baf\u0bbe\u0b83 \u0965 \u0beb \u0965", "kannada": "\u0c95\u0cbe\u0cb2\u0cbe\u0cae\u0ccd\u0cac\u0cc1\u0ca6\u0cbe\u0cb2\u0cbf\u0cb2\u0cb2\u0cbf\u0ca4\u0ccb\u0cb0\u0cb8\u0cbf \u0c95\u0cc8\u0c9f\u0cad\u0cbe\u0cb0\u0cc7-\n\u0cb0\u0ccd\u0ca7\u0cbe\u0cb0\u0cbe\u0ca7\u0cb0\u0cc7 \u0cb8\u0ccd\u0cab\u0cc1\u0cb0\u0ca4\u0cbf \u0caf\u0cbe \u0ca4\u0ca1\u0cbf\u0ca6\u0c99\u0ccd\u0c97\u0ca8\u0cc7\u0cb5 \u0964\n\u0cae\u0cbe\u0ca4\u0cc1\u0c83 \u0cb8\u0cae\u0cb8\u0ccd\u0ca4\u0c9c\u0c97\u0ca4\u0cbe\u0c82 \u0cae\u0cb9\u0ca8\u0cc0\u0caf\u0cae\u0cc2\u0cb0\u0ccd\u0ca4\u0cbf\u0c83\n\u0cad\u0ca6\u0ccd\u0cb0\u0cbe\u0ca3\u0cbf \u0cae\u0cc7 \u0ca6\u0cbf\u0cb6\u0ca4\u0cc1 \u0cad\u0cbe\u0cb0\u0ccd\u0c97\u0cb5\u0ca8\u0ca8\u0ccd\u0ca6\u0ca8\u0cbe\u0caf\u0cbe\u0c83 \u0965 \u0ceb \u0965", "malayalam": "\u0d15\u0d3e\u0d32\u0d3e\u0d2e\u0d4d\u0d2c\u0d41\u0d26\u0d3e\u0d32\u0d3f\u0d32\u0d32\u0d3f\u0d24\u0d4b\u0d30\u0d38\u0d3f \u0d15\u0d48\u0d1f\u0d2d\u0d3e\u0d30\u0d47-\n\u0d30\u0d4d\u0d27\u0d3e\u0d30\u0d3e\u0d27\u0d30\u0d47 \u0d38\u0d4d\u0d2b\u0d41\u0d30\u0d24\u0d3f \u0d2f\u0d3e \u0d24\u0d21\u0d3f\u0d26\u0d19\u0d4d\u0d17\u0d28\u0d47\u0d35 \u0964\n\u0d2e\u0d3e\u0d24\u0d41\u0d03 \u0d38\u0d2e\u0d38\u0d4d\u0d24\u0d1c\u0d17\u0d24\u0d3e\u0d02 \u0d2e\u0d39\u0d28\u0d40\u0d2f\u0d2e\u0d42\u0d30\u0d4d\u0d24\u0d3f\u0d03\n\u0d2d\u0d26\u0d4d\u0d30\u0d3e\u0d23\u0d3f \u0d2e\u0d47 \u0d26\u0d3f\u0d36\u0d24\u0d41 \u0d2d\u0d3e\u0d30\u0d4d\u0d17\u0d35\u0d28\u0d28\u0d4d\u0d26\u0d28\u0d3e\u0d2f\u0d3e\u0d03 \u0965 \u0d6b \u0965", "iast": "k\u0101l\u0101mbud\u0101lilalitorasi kai\u1e6dabh\u0101re-\nrdh\u0101r\u0101dhare sphurati y\u0101 ta\u1e0dida\u1e45ganeva |\nm\u0101tu\u1e25 samastajagat\u0101\u1e43 mahan\u012byam\u016brti\u1e25\nbhadr\u0101\u1e47i me di\u015batu bh\u0101rgavanandan\u0101y\u0101\u1e25 || 5 ||"},
        draftTranslation: "Flashing like brilliant lightning upon the dark rain-cloud bosom of the enemy of Kaitabha, majestic mother of all creation, daughter of Sage Bhrigu \u2014 may Her compassionate gaze shower auspiciousness upon me!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 6,
        devanagariText: "\u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0902 \u092a\u0926\u0902 \u092a\u094d\u0930\u0925\u092e\u0924\u0903 \u0916\u0932\u0941 \u092f\u0924\u094d\u092a\u094d\u0930\u092d\u093e\u0935\u093e-\n\u0928\u094d\u092e\u093e\u0919\u094d\u0917\u0932\u094d\u092f\u092d\u093e\u091c\u093f \u092e\u0927\u0941\u092e\u093e\u0925\u093f\u0928\u093f \u092e\u0928\u094d\u092e\u0925\u0947\u0928 \u0964\n\u092e\u092f\u094d\u092f\u093e\u092a\u0924\u0947\u0924\u094d\u0924\u0926\u093f\u0939 \u092e\u0928\u094d\u0925\u0930\u092e\u0940\u0915\u094d\u0937\u0923\u093e\u0930\u094d\u0927\u0902\n\u092e\u0928\u094d\u0926\u093e\u0932\u0938\u0902 \u091a \u092e\u0915\u0930\u093e\u0932\u092f\u0915\u0928\u094d\u092f\u0915\u093e\u092f\u093e\u0903 \u0965 \u096c \u0965",
        iastText: "pr\u0101pta\u1e41 pada\u1e41 prathamata\u1e25 khalu yatprabh\u0101v\u0101-\nnm\u0101\u1e45galyabh\u0101ji madhum\u0101thini manmath\u0113na \u0964\nmayy\u0101pat\u0113ttadiha mantharam\u012bk\u1e63a\u1e47\u0101rdha\u1e41\nmand\u0101lasa\u1e41 ca makar\u0101layakanyak\u0101y\u0101\u1e25 \u0965 6 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2a\u0c4d\u0c30\u0c3e\u0c2a\u0c4d\u0c24\u0c02 \u0c2a\u0c26\u0c02 \u0c2a\u0c4d\u0c30\u0c25\u0c2e\u0c24\u0c03 \u0c16\u0c32\u0c41 \u0c2f\u0c24\u0c4d\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c35\u0c3e-\n\u0c28\u0c4d\u0c2e\u0c3e\u0c19\u0c4d\u0c17\u0c32\u0c4d\u0c2f\u0c2d\u0c3e\u0c1c\u0c3f \u0c2e\u0c27\u0c41\u0c2e\u0c3e\u0c25\u0c3f\u0c28\u0c3f \u0c2e\u0c28\u0c4d\u0c2e\u0c25\u0c47\u0c28 \u0964\n\u0c2e\u0c2f\u0c4d\u0c2f\u0c3e\u0c2a\u0c24\u0c47\u0c24\u0c4d\u0c24\u0c26\u0c3f\u0c39 \u0c2e\u0c28\u0c4d\u0c25\u0c30\u0c2e\u0c40\u0c15\u0c4d\u0c37\u0c23\u0c3e\u0c30\u0c4d\u0c27\u0c02\n\u0c2e\u0c28\u0c4d\u0c26\u0c3e\u0c32\u0c38\u0c02 \u0c1a \u0c2e\u0c15\u0c30\u0c3e\u0c32\u0c2f\u0c15\u0c28\u0c4d\u0c2f\u0c15\u0c3e\u0c2f\u0c3e\u0c03 \u0965 \u0c6c \u0965", "tamil": "\u0baa\u0bcd\u0bb0\u0bbe\u0baa\u0bcd\u0ba4\u0bae\u0bcd \u0baa\u0ba4\u0bae\u0bcd \u0baa\u0bcd\u0bb0\u0ba4\u0bae\u0ba4\u0b83 \u0b95\u0bb2\u0bc1 \u0baf\u0ba4\u0bcd\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0bb5\u0bbe-\n\u0ba8\u0bcd\u0bae\u0bbe\u0b99\u0bcd\u0b95\u0bb2\u0bcd\u0baf\u0baa\u0bbe\u0b9c\u0bbf \u0bae\u0ba4\u0bc1\u0bae\u0bbe\u0ba4\u0bbf\u0ba8\u0bbf \u0bae\u0ba8\u0bcd\u0bae\u0ba4\u0bc7\u0ba8 \u0964\n\u0bae\u0baf\u0bcd\u0baf\u0bbe\u0baa\u0ba4\u0bc7\u0ba4\u0bcd\u0ba4\u0ba4\u0bbf\u0bb9 \u0bae\u0ba8\u0bcd\u0ba4\u0bb0\u0bae\u0bc0\u0b95\u0bcd\u0bb7\u0ba3\u0bbe\u0bb0\u0bcd\u0ba4\u0bae\u0bcd\n\u0bae\u0ba8\u0bcd\u0ba4\u0bbe\u0bb2\u0bb8\u0bae\u0bcd \u0b9a \u0bae\u0b95\u0bb0\u0bbe\u0bb2\u0baf\u0b95\u0ba8\u0bcd\u0baf\u0b95\u0bbe\u0baf\u0bbe\u0b83 \u0965 \u0bec \u0965", "kannada": "\u0caa\u0ccd\u0cb0\u0cbe\u0caa\u0ccd\u0ca4\u0c82 \u0caa\u0ca6\u0c82 \u0caa\u0ccd\u0cb0\u0ca5\u0cae\u0ca4\u0c83 \u0c96\u0cb2\u0cc1 \u0caf\u0ca4\u0ccd\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0cb5\u0cbe-\n\u0ca8\u0ccd\u0cae\u0cbe\u0c99\u0ccd\u0c97\u0cb2\u0ccd\u0caf\u0cad\u0cbe\u0c9c\u0cbf \u0cae\u0ca7\u0cc1\u0cae\u0cbe\u0ca5\u0cbf\u0ca8\u0cbf \u0cae\u0ca8\u0ccd\u0cae\u0ca5\u0cc7\u0ca8 \u0964\n\u0cae\u0caf\u0ccd\u0caf\u0cbe\u0caa\u0ca4\u0cc7\u0ca4\u0ccd\u0ca4\u0ca6\u0cbf\u0cb9 \u0cae\u0ca8\u0ccd\u0ca5\u0cb0\u0cae\u0cc0\u0c95\u0ccd\u0cb7\u0ca3\u0cbe\u0cb0\u0ccd\u0ca7\u0c82\n\u0cae\u0ca8\u0ccd\u0ca6\u0cbe\u0cb2\u0cb8\u0c82 \u0c9a \u0cae\u0c95\u0cb0\u0cbe\u0cb2\u0caf\u0c95\u0ca8\u0ccd\u0caf\u0c95\u0cbe\u0caf\u0cbe\u0c83 \u0965 \u0cec \u0965", "malayalam": "\u0d2a\u0d4d\u0d30\u0d3e\u0d2a\u0d4d\u0d24\u0d02 \u0d2a\u0d26\u0d02 \u0d2a\u0d4d\u0d30\u0d25\u0d2e\u0d24\u0d03 \u0d16\u0d32\u0d41 \u0d2f\u0d24\u0d4d\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d35\u0d3e-\n\u0d28\u0d4d\u0d2e\u0d3e\u0d19\u0d4d\u0d17\u0d32\u0d4d\u0d2f\u0d2d\u0d3e\u0d1c\u0d3f \u0d2e\u0d27\u0d41\u0d2e\u0d3e\u0d25\u0d3f\u0d28\u0d3f \u0d2e\u0d28\u0d4d\u0d2e\u0d25\u0d47\u0d28 \u0964\n\u0d2e\u0d2f\u0d4d\u0d2f\u0d3e\u0d2a\u0d24\u0d47\u0d24\u0d4d\u0d24\u0d26\u0d3f\u0d39 \u0d2e\u0d28\u0d4d\u0d25\u0d30\u0d2e\u0d40\u0d15\u0d4d\u0d37\u0d23\u0d3e\u0d30\u0d4d\u0d27\u0d02\n\u0d2e\u0d28\u0d4d\u0d26\u0d3e\u0d32\u0d38\u0d02 \u0d1a \u0d2e\u0d15\u0d30\u0d3e\u0d32\u0d2f\u0d15\u0d28\u0d4d\u0d2f\u0d15\u0d3e\u0d2f\u0d3e\u0d03 \u0965 \u0d6c \u0965", "iast": "pr\u0101pta\u1e43 pada\u1e43 prathamata\u1e25 khalu yatprabh\u0101v\u0101-\nnm\u0101\u1e45galyabh\u0101ji madhum\u0101thini manmathena |\nmayy\u0101patettadiha mantharam\u012bk\u1e63a\u1e47\u0101rdha\u1e43\nmand\u0101lasa\u1e43 ca makar\u0101layakanyak\u0101y\u0101\u1e25 || 6 ||"},
        draftTranslation: "By the sheer potency of whose grace Kamadeva (Cupid) regained his realm upon the conqueror of Madhu, may that gentle, benevolent half-glance of the daughter of the ocean fall graciously upon me!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 7,
        devanagariText: "\u0935\u093f\u0936\u094d\u0935\u093e\u092e\u0930\u0947\u0928\u094d\u0926\u094d\u0930\u092a\u0926\u0935\u093f\u092d\u094d\u0930\u092e\u0926\u093e\u0928\u0926\u0915\u094d\u0937\u092e\u094d\n\u0906\u0928\u0928\u094d\u0926\u0939\u0947\u0924\u0941\u0930\u0927\u093f\u0915\u0902 \u092e\u0941\u0930\u0935\u093f\u0926\u094d\u0935\u093f\u0937\u094b\u093d\u092a\u093f \u0964\n\u0908\u0937\u0928\u094d\u0928\u093f\u0937\u0940\u0926\u0924\u0941 \u092e\u092f\u093f \u0915\u094d\u0937\u0923\u092e\u0940\u0915\u094d\u0937\u0923\u093e\u0930\u094d\u0927\u092e\u094d\n\u0907\u0928\u094d\u0926\u0940\u0935\u0930\u094b\u0926\u0930\u0938\u0939\u094b\u0926\u0930\u092e\u093f\u0928\u094d\u0926\u093f\u0930\u093e\u092f\u093e\u0903 \u0965 \u096d \u0965",
        iastText: "vi\u015bv\u0101mar\u0113ndrapadavibhramad\u0101nadak\u1e63am\n\u0101nandah\u0113turadhika\u1e41 muravidvi\u1e63\u014d'pi \u0964\n\u012b\u1e63anni\u1e63\u012bdatu mayi k\u1e63a\u1e47am\u012bk\u1e63a\u1e47\u0101rdham\nind\u012bvar\u014ddarasah\u014ddaramindir\u0101y\u0101\u1e25 \u0965 7 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c35\u0c3f\u0c36\u0c4d\u0c35\u0c3e\u0c2e\u0c30\u0c47\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c2a\u0c26\u0c35\u0c3f\u0c2d\u0c4d\u0c30\u0c2e\u0c26\u0c3e\u0c28\u0c26\u0c15\u0c4d\u0c37\u0c2e\u0c4d\n\u0c06\u0c28\u0c28\u0c4d\u0c26\u0c39\u0c47\u0c24\u0c41\u0c30\u0c27\u0c3f\u0c15\u0c02 \u0c2e\u0c41\u0c30\u0c35\u0c3f\u0c26\u0c4d\u0c35\u0c3f\u0c37\u0c4b\u0c3d\u0c2a\u0c3f \u0964\n\u0c08\u0c37\u0c28\u0c4d\u0c28\u0c3f\u0c37\u0c40\u0c26\u0c24\u0c41 \u0c2e\u0c2f\u0c3f \u0c15\u0c4d\u0c37\u0c23\u0c2e\u0c40\u0c15\u0c4d\u0c37\u0c23\u0c3e\u0c30\u0c4d\u0c27\u0c2e\u0c4d\n\u0c07\u0c28\u0c4d\u0c26\u0c40\u0c35\u0c30\u0c4b\u0c26\u0c30\u0c38\u0c39\u0c4b\u0c26\u0c30\u0c2e\u0c3f\u0c28\u0c4d\u0c26\u0c3f\u0c30\u0c3e\u0c2f\u0c3e\u0c03 \u0965 \u0c6d \u0965", "tamil": "\u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0bbe\u0bae\u0bb0\u0bc7\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0baa\u0ba4\u0bb5\u0bbf\u0baa\u0bcd\u0bb0\u0bae\u0ba4\u0bbe\u0ba8\u0ba4\u0b95\u0bcd\u0bb7\u0bae\u0bcd\n\u0b86\u0ba8\u0ba8\u0bcd\u0ba4\u0bb9\u0bc7\u0ba4\u0bc1\u0bb0\u0ba4\u0bbf\u0b95\u0bae\u0bcd \u0bae\u0bc1\u0bb0\u0bb5\u0bbf\u0ba4\u0bcd\u0bb5\u0bbf\u0bb7\u0bcb\u093d\u0baa\u0bbf \u0964\n\u0b88\u0bb7\u0ba8\u0bcd\u0ba8\u0bbf\u0bb7\u0bc0\u0ba4\u0ba4\u0bc1 \u0bae\u0baf\u0bbf \u0b95\u0bcd\u0bb7\u0ba3\u0bae\u0bc0\u0b95\u0bcd\u0bb7\u0ba3\u0bbe\u0bb0\u0bcd\u0ba4\u0bae\u0bcd\n\u0b87\u0ba8\u0bcd\u0ba4\u0bc0\u0bb5\u0bb0\u0bcb\u0ba4\u0bb0\u0bb8\u0bb9\u0bcb\u0ba4\u0bb0\u0bae\u0bbf\u0ba8\u0bcd\u0ba4\u0bbf\u0bb0\u0bbe\u0baf\u0bbe\u0b83 \u0965 \u0bed \u0965", "kannada": "\u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0cbe\u0cae\u0cb0\u0cc7\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0caa\u0ca6\u0cb5\u0cbf\u0cad\u0ccd\u0cb0\u0cae\u0ca6\u0cbe\u0ca8\u0ca6\u0c95\u0ccd\u0cb7\u0cae\u0ccd\n\u0c86\u0ca8\u0ca8\u0ccd\u0ca6\u0cb9\u0cc7\u0ca4\u0cc1\u0cb0\u0ca7\u0cbf\u0c95\u0c82 \u0cae\u0cc1\u0cb0\u0cb5\u0cbf\u0ca6\u0ccd\u0cb5\u0cbf\u0cb7\u0ccb\u0cbd\u0caa\u0cbf \u0964\n\u0c88\u0cb7\u0ca8\u0ccd\u0ca8\u0cbf\u0cb7\u0cc0\u0ca6\u0ca4\u0cc1 \u0cae\u0caf\u0cbf \u0c95\u0ccd\u0cb7\u0ca3\u0cae\u0cc0\u0c95\u0ccd\u0cb7\u0ca3\u0cbe\u0cb0\u0ccd\u0ca7\u0cae\u0ccd\n\u0c87\u0ca8\u0ccd\u0ca6\u0cc0\u0cb5\u0cb0\u0ccb\u0ca6\u0cb0\u0cb8\u0cb9\u0ccb\u0ca6\u0cb0\u0cae\u0cbf\u0ca8\u0ccd\u0ca6\u0cbf\u0cb0\u0cbe\u0caf\u0cbe\u0c83 \u0965 \u0ced \u0965", "malayalam": "\u0d35\u0d3f\u0d36\u0d4d\u0d35\u0d3e\u0d2e\u0d30\u0d47\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d2a\u0d26\u0d35\u0d3f\u0d2d\u0d4d\u0d30\u0d2e\u0d26\u0d3e\u0d28\u0d26\u0d15\u0d4d\u0d37\u0d2e\u0d4d\n\u0d06\u0d28\u0d28\u0d4d\u0d26\u0d39\u0d47\u0d24\u0d41\u0d30\u0d27\u0d3f\u0d15\u0d02 \u0d2e\u0d41\u0d30\u0d35\u0d3f\u0d26\u0d4d\u0d35\u0d3f\u0d37\u0d4b\u0d3d\u0d2a\u0d3f \u0964\n\u0d08\u0d37\u0d28\u0d4d\u0d28\u0d3f\u0d37\u0d40\u0d26\u0d24\u0d41 \u0d2e\u0d2f\u0d3f \u0d15\u0d4d\u0d37\u0d23\u0d2e\u0d40\u0d15\u0d4d\u0d37\u0d23\u0d3e\u0d30\u0d4d\u0d27\u0d2e\u0d4d\n\u0d07\u0d28\u0d4d\u0d26\u0d40\u0d35\u0d30\u0d4b\u0d26\u0d30\u0d38\u0d39\u0d4b\u0d26\u0d30\u0d2e\u0d3f\u0d28\u0d4d\u0d26\u0d3f\u0d30\u0d3e\u0d2f\u0d3e\u0d03 \u0965 \u0d6d \u0965", "iast": "vi\u015bv\u0101marendrapadavibhramad\u0101nadak\u1e63am\n\u0101nandaheturadhika\u1e43 muravidvi\u1e63o'pi |\n\u012b\u1e63anni\u1e63\u012bdatu mayi k\u1e63a\u1e47am\u012bk\u1e63a\u1e47\u0101rdham\nind\u012bvarodarasahodaramindir\u0101y\u0101\u1e25 || 7 ||"},
        draftTranslation: "Capable of bestowing sovereignty even over all celestial realms, the supreme cause of divine delight to the Lord, resembling the deep blue heart of a blossoming lotus \u2014 may that gentle glance of Indira dwell upon me!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 8,
        devanagariText: "\u0907\u0937\u094d\u091f\u093e \u0935\u093f\u0936\u093f\u0937\u094d\u091f\u092e\u0924\u092f\u094b\u093d\u092a\u093f \u092f\u092f\u093e \u0926\u092f\u093e\u0930\u094d\u0926\u094d\u0930-\n\u0926\u0943\u0937\u094d\u091f\u094d\u092f\u093e \u0924\u094d\u0930\u093f\u0935\u093f\u0937\u094d\u091f\u092a\u092a\u0926\u0902 \u0938\u0941\u0932\u092d\u0902 \u0932\u092d\u0928\u094d\u0924\u0947 \u0964\n\u0926\u0943\u0937\u094d\u091f\u093f\u0903 \u092a\u094d\u0930\u0939\u0943\u0937\u094d\u091f\u0915\u092e\u0932\u094b\u0926\u0930\u0926\u0940\u092a\u094d\u0924\u093f\u0930\u093f\u0937\u094d\u091f\u093e\u0902\n\u092a\u0941\u0937\u094d\u091f\u093f\u0902 \u0915\u0943\u0937\u0940\u0937\u094d\u091f \u092e\u092e \u092a\u0941\u0937\u094d\u0915\u0930\u0935\u093f\u0937\u094d\u091f\u0930\u093e\u092f\u093e\u0903 \u0965 \u096e \u0965",
        iastText: "i\u1e63\u1e6d\u0101 vi\u015bi\u1e63\u1e6damatay\u014d'pi yay\u0101 day\u0101rdra-\nd\u1e5b\u1e63\u1e6dy\u0101 trivi\u1e63\u1e6dapapada\u1e41 sulabha\u1e41 labhant\u0113 \u0964\nd\u1e5b\u1e63\u1e6di\u1e25 prah\u1e5b\u1e63\u1e6dakamal\u014ddarad\u012bptiri\u1e63\u1e6d\u0101\u1e41\npu\u1e63\u1e6di\u1e41 k\u1e5b\u1e63\u012b\u1e63\u1e6da mama pu\u1e63karavi\u1e63\u1e6dar\u0101y\u0101\u1e25 \u0965 8 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c07\u0c37\u0c4d\u0c1f\u0c3e \u0c35\u0c3f\u0c36\u0c3f\u0c37\u0c4d\u0c1f\u0c2e\u0c24\u0c2f\u0c4b\u0c3d\u0c2a\u0c3f \u0c2f\u0c2f\u0c3e \u0c26\u0c2f\u0c3e\u0c30\u0c4d\u0c26\u0c4d\u0c30-\n\u0c26\u0c43\u0c37\u0c4d\u0c1f\u0c4d\u0c2f\u0c3e \u0c24\u0c4d\u0c30\u0c3f\u0c35\u0c3f\u0c37\u0c4d\u0c1f\u0c2a\u0c2a\u0c26\u0c02 \u0c38\u0c41\u0c32\u0c2d\u0c02 \u0c32\u0c2d\u0c28\u0c4d\u0c24\u0c47 \u0964\n\u0c26\u0c43\u0c37\u0c4d\u0c1f\u0c3f\u0c03 \u0c2a\u0c4d\u0c30\u0c39\u0c43\u0c37\u0c4d\u0c1f\u0c15\u0c2e\u0c32\u0c4b\u0c26\u0c30\u0c26\u0c40\u0c2a\u0c4d\u0c24\u0c3f\u0c30\u0c3f\u0c37\u0c4d\u0c1f\u0c3e\u0c02\n\u0c2a\u0c41\u0c37\u0c4d\u0c1f\u0c3f\u0c02 \u0c15\u0c43\u0c37\u0c40\u0c37\u0c4d\u0c1f \u0c2e\u0c2e \u0c2a\u0c41\u0c37\u0c4d\u0c15\u0c30\u0c35\u0c3f\u0c37\u0c4d\u0c1f\u0c30\u0c3e\u0c2f\u0c3e\u0c03 \u0965 \u0c6e \u0965", "tamil": "\u0b87\u0bb7\u0bcd\u0b9f\u0bbe \u0bb5\u0bbf\u0bb6\u0bbf\u0bb7\u0bcd\u0b9f\u0bae\u0ba4\u0baf\u0bcb\u093d\u0baa\u0bbf \u0baf\u0baf\u0bbe \u0ba4\u0baf\u0bbe\u0bb0\u0bcd\u0ba4\u0bcd\u0bb0-\n\u0ba4\u0bcd\u0bb0\u0bc1'\u0bb7\u0bcd\u0b9f\u0bcd\u0baf\u0bbe \u0ba4\u0bcd\u0bb0\u0bbf\u0bb5\u0bbf\u0bb7\u0bcd\u0b9f\u0baa\u0baa\u0ba4\u0bae\u0bcd \u0bb8\u0bc1\u0bb2\u0baa\u0bae\u0bcd \u0bb2\u0baa\u0ba8\u0bcd\u0ba4\u0bc7 \u0964\n\u0ba4\u0bcd\u0bb0\u0bc1'\u0bb7\u0bcd\u0b9f\u0bbf\u0b83 \u0baa\u0bcd\u0bb0\u0bb9\u0bcd\u0bb0\u0bc1'\u0bb7\u0bcd\u0b9f\u0b95\u0bae\u0bb2\u0bcb\u0ba4\u0bb0\u0ba4\u0bc0\u0baa\u0bcd\u0ba4\u0bbf\u0bb0\u0bbf\u0bb7\u0bcd\u0b9f\u0bbe\u0bae\u0bcd\n\u0baa\u0bc1\u0bb7\u0bcd\u0b9f\u0bbf\u0bae\u0bcd \u0b95\u0bcd\u0bb0\u0bc1'\u0bb7\u0bc0\u0bb7\u0bcd\u0b9f \u0bae\u0bae \u0baa\u0bc1\u0bb7\u0bcd\u0b95\u0bb0\u0bb5\u0bbf\u0bb7\u0bcd\u0b9f\u0bb0\u0bbe\u0baf\u0bbe\u0b83 \u0965 \u0bee \u0965", "kannada": "\u0c87\u0cb7\u0ccd\u0c9f\u0cbe \u0cb5\u0cbf\u0cb6\u0cbf\u0cb7\u0ccd\u0c9f\u0cae\u0ca4\u0caf\u0ccb\u0cbd\u0caa\u0cbf \u0caf\u0caf\u0cbe \u0ca6\u0caf\u0cbe\u0cb0\u0ccd\u0ca6\u0ccd\u0cb0-\n\u0ca6\u0cc3\u0cb7\u0ccd\u0c9f\u0ccd\u0caf\u0cbe \u0ca4\u0ccd\u0cb0\u0cbf\u0cb5\u0cbf\u0cb7\u0ccd\u0c9f\u0caa\u0caa\u0ca6\u0c82 \u0cb8\u0cc1\u0cb2\u0cad\u0c82 \u0cb2\u0cad\u0ca8\u0ccd\u0ca4\u0cc7 \u0964\n\u0ca6\u0cc3\u0cb7\u0ccd\u0c9f\u0cbf\u0c83 \u0caa\u0ccd\u0cb0\u0cb9\u0cc3\u0cb7\u0ccd\u0c9f\u0c95\u0cae\u0cb2\u0ccb\u0ca6\u0cb0\u0ca6\u0cc0\u0caa\u0ccd\u0ca4\u0cbf\u0cb0\u0cbf\u0cb7\u0ccd\u0c9f\u0cbe\u0c82\n\u0caa\u0cc1\u0cb7\u0ccd\u0c9f\u0cbf\u0c82 \u0c95\u0cc3\u0cb7\u0cc0\u0cb7\u0ccd\u0c9f \u0cae\u0cae \u0caa\u0cc1\u0cb7\u0ccd\u0c95\u0cb0\u0cb5\u0cbf\u0cb7\u0ccd\u0c9f\u0cb0\u0cbe\u0caf\u0cbe\u0c83 \u0965 \u0cee \u0965", "malayalam": "\u0d07\u0d37\u0d4d\u0d1f\u0d3e \u0d35\u0d3f\u0d36\u0d3f\u0d37\u0d4d\u0d1f\u0d2e\u0d24\u0d2f\u0d4b\u0d3d\u0d2a\u0d3f \u0d2f\u0d2f\u0d3e \u0d26\u0d2f\u0d3e\u0d30\u0d4d\u0d26\u0d4d\u0d30-\n\u0d26\u0d43\u0d37\u0d4d\u0d1f\u0d4d\u0d2f\u0d3e \u0d24\u0d4d\u0d30\u0d3f\u0d35\u0d3f\u0d37\u0d4d\u0d1f\u0d2a\u0d2a\u0d26\u0d02 \u0d38\u0d41\u0d32\u0d2d\u0d02 \u0d32\u0d2d\u0d28\u0d4d\u0d24\u0d47 \u0964\n\u0d26\u0d43\u0d37\u0d4d\u0d1f\u0d3f\u0d03 \u0d2a\u0d4d\u0d30\u0d39\u0d43\u0d37\u0d4d\u0d1f\u0d15\u0d2e\u0d32\u0d4b\u0d26\u0d30\u0d26\u0d40\u0d2a\u0d4d\u0d24\u0d3f\u0d30\u0d3f\u0d37\u0d4d\u0d1f\u0d3e\u0d02\n\u0d2a\u0d41\u0d37\u0d4d\u0d1f\u0d3f\u0d02 \u0d15\u0d43\u0d37\u0d40\u0d37\u0d4d\u0d1f \u0d2e\u0d2e \u0d2a\u0d41\u0d37\u0d4d\u0d15\u0d30\u0d35\u0d3f\u0d37\u0d4d\u0d1f\u0d30\u0d3e\u0d2f\u0d3e\u0d03 \u0965 \u0d6e \u0965", "iast": "i\u1e63\u1e6d\u0101 vi\u015bi\u1e63\u1e6damatayo'pi yay\u0101 day\u0101rdra-\nd\u1e5b\u1e63\u1e6dy\u0101 trivi\u1e63\u1e6dapapada\u1e43 sulabha\u1e43 labhante |\nd\u1e5b\u1e63\u1e6di\u1e25 prah\u1e5b\u1e63\u1e6dakamalodarad\u012bptiri\u1e63\u1e6d\u0101\u1e43\npu\u1e63\u1e6di\u1e43 k\u1e5b\u1e63\u012b\u1e63\u1e6da mama pu\u1e63karavi\u1e63\u1e6dar\u0101y\u0101\u1e25 || 8 ||"},
        draftTranslation: "By whose glance moist with mercy even ordinary seekers effortlessly attain highest heaven, brilliant like the core of an open lotus \u2014 may the gaze of Her who sits upon the lotus seat nourish my life with fullness!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 9,
        devanagariText: "\u0926\u0926\u094d\u092f\u093e\u0926\u094d\u0926\u092f\u093e\u0928\u0941\u092a\u0935\u0928\u094b \u0926\u094d\u0930\u0935\u093f\u0923\u093e\u092e\u094d\u092c\u0941\u0927\u093e\u0930\u093e-\n\u092e\u0938\u094d\u092e\u093f\u0928\u094d\u0928\u0915\u093f\u091e\u094d\u091a\u0928\u0935\u093f\u0939\u0919\u094d\u0917\u0936\u093f\u0936\u094c \u0935\u093f\u0937\u0923\u094d\u0923\u0947 \u0964\n\u0926\u0941\u0937\u094d\u0915\u0930\u094d\u092e\u0918\u0930\u094d\u092e\u092e\u092a\u0928\u0940\u092f \u091a\u093f\u0930\u093e\u092f \u0926\u0942\u0930\u0902\n\u0928\u093e\u0930\u093e\u092f\u0923\u092a\u094d\u0930\u0923\u092f\u093f\u0928\u0940\u0928\u092f\u0928\u093e\u092e\u094d\u092c\u0941\u0935\u093e\u0939\u0903 \u0965 \u096f \u0965",
        iastText: "dady\u0101dday\u0101nupavan\u014d dravi\u1e47\u0101mbudh\u0101r\u0101-\nmasminnaki\u00f1canaviha\u1e45ga\u015bi\u015bau vi\u1e63a\u1e47\u1e47\u0113 \u0964\ndu\u1e63karmagharmamapan\u012bya cir\u0101ya d\u016bra\u1e41\nn\u0101r\u0101ya\u1e47apra\u1e47ayin\u012bnayan\u0101mbuv\u0101ha\u1e25 \u0965 9 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c26\u0c26\u0c4d\u0c2f\u0c3e\u0c26\u0c4d\u0c26\u0c2f\u0c3e\u0c28\u0c41\u0c2a\u0c35\u0c28\u0c4b \u0c26\u0c4d\u0c30\u0c35\u0c3f\u0c23\u0c3e\u0c2e\u0c4d\u0c2c\u0c41\u0c27\u0c3e\u0c30\u0c3e-\n\u0c2e\u0c38\u0c4d\u0c2e\u0c3f\u0c28\u0c4d\u0c28\u0c15\u0c3f\u0c1e\u0c4d\u0c1a\u0c28\u0c35\u0c3f\u0c39\u0c19\u0c4d\u0c17\u0c36\u0c3f\u0c36\u0c4c \u0c35\u0c3f\u0c37\u0c23\u0c4d\u0c23\u0c47 \u0964\n\u0c26\u0c41\u0c37\u0c4d\u0c15\u0c30\u0c4d\u0c2e\u0c18\u0c30\u0c4d\u0c2e\u0c2e\u0c2a\u0c28\u0c40\u0c2f \u0c1a\u0c3f\u0c30\u0c3e\u0c2f \u0c26\u0c42\u0c30\u0c02\n\u0c28\u0c3e\u0c30\u0c3e\u0c2f\u0c23\u0c2a\u0c4d\u0c30\u0c23\u0c2f\u0c3f\u0c28\u0c40\u0c28\u0c2f\u0c28\u0c3e\u0c2e\u0c4d\u0c2c\u0c41\u0c35\u0c3e\u0c39\u0c03 \u0965 \u0c6f \u0965", "tamil": "\u0ba4\u0ba4\u0bcd\u0baf\u0bbe\u0ba4\u0bcd\u0ba4\u0baf\u0bbe\u0ba8\u0bc1\u0baa\u0bb5\u0ba8\u0bcb \u0ba4\u0bcd\u0bb0\u0bb5\u0bbf\u0ba3\u0bbe\u0bae\u0bcd\u0baa\u0bc1\u0ba4\u0bbe\u0bb0\u0bbe-\n\u0bae\u0bb8\u0bcd\u0bae\u0bbf\u0ba8\u0bcd\u0ba8\u0b95\u0bbf\u0b9e\u0bcd\u0b9a\u0ba8\u0bb5\u0bbf\u0bb9\u0b99\u0bcd\u0b95\u0bb6\u0bbf\u0bb6\u0bcc \u0bb5\u0bbf\u0bb7\u0ba3\u0bcd\u0ba3\u0bc7 \u0964\n\u0ba4\u0bc1\u0bb7\u0bcd\u0b95\u0bb0\u0bcd\u0bae\u0b95\u0bb0\u0bcd\u0bae\u0bae\u0baa\u0ba8\u0bc0\u0baf \u0b9a\u0bbf\u0bb0\u0bbe\u0baf \u0ba4\u0bc2\u0bb0\u0bae\u0bcd\n\u0ba8\u0bbe\u0bb0\u0bbe\u0baf\u0ba3\u0baa\u0bcd\u0bb0\u0ba3\u0baf\u0bbf\u0ba8\u0bc0\u0ba8\u0baf\u0ba8\u0bbe\u0bae\u0bcd\u0baa\u0bc1\u0bb5\u0bbe\u0bb9\u0b83 \u0965 \u0bef \u0965", "kannada": "\u0ca6\u0ca6\u0ccd\u0caf\u0cbe\u0ca6\u0ccd\u0ca6\u0caf\u0cbe\u0ca8\u0cc1\u0caa\u0cb5\u0ca8\u0ccb \u0ca6\u0ccd\u0cb0\u0cb5\u0cbf\u0ca3\u0cbe\u0cae\u0ccd\u0cac\u0cc1\u0ca7\u0cbe\u0cb0\u0cbe-\n\u0cae\u0cb8\u0ccd\u0cae\u0cbf\u0ca8\u0ccd\u0ca8\u0c95\u0cbf\u0c9e\u0ccd\u0c9a\u0ca8\u0cb5\u0cbf\u0cb9\u0c99\u0ccd\u0c97\u0cb6\u0cbf\u0cb6\u0ccc \u0cb5\u0cbf\u0cb7\u0ca3\u0ccd\u0ca3\u0cc7 \u0964\n\u0ca6\u0cc1\u0cb7\u0ccd\u0c95\u0cb0\u0ccd\u0cae\u0c98\u0cb0\u0ccd\u0cae\u0cae\u0caa\u0ca8\u0cc0\u0caf \u0c9a\u0cbf\u0cb0\u0cbe\u0caf \u0ca6\u0cc2\u0cb0\u0c82\n\u0ca8\u0cbe\u0cb0\u0cbe\u0caf\u0ca3\u0caa\u0ccd\u0cb0\u0ca3\u0caf\u0cbf\u0ca8\u0cc0\u0ca8\u0caf\u0ca8\u0cbe\u0cae\u0ccd\u0cac\u0cc1\u0cb5\u0cbe\u0cb9\u0c83 \u0965 \u0cef \u0965", "malayalam": "\u0d26\u0d26\u0d4d\u0d2f\u0d3e\u0d26\u0d4d\u0d26\u0d2f\u0d3e\u0d28\u0d41\u0d2a\u0d35\u0d28\u0d4b \u0d26\u0d4d\u0d30\u0d35\u0d3f\u0d23\u0d3e\u0d2e\u0d4d\u0d2c\u0d41\u0d27\u0d3e\u0d30\u0d3e-\n\u0d2e\u0d38\u0d4d\u0d2e\u0d3f\u0d28\u0d4d\u0d28\u0d15\u0d3f\u0d1e\u0d4d\u0d1a\u0d28\u0d35\u0d3f\u0d39\u0d19\u0d4d\u0d17\u0d36\u0d3f\u0d36\u0d4c \u0d35\u0d3f\u0d37\u0d23\u0d4d\u0d23\u0d47 \u0964\n\u0d26\u0d41\u0d37\u0d4d\u0d15\u0d30\u0d4d\u0d2e\u0d18\u0d30\u0d4d\u0d2e\u0d2e\u0d2a\u0d28\u0d40\u0d2f \u0d1a\u0d3f\u0d30\u0d3e\u0d2f \u0d26\u0d42\u0d30\u0d02\n\u0d28\u0d3e\u0d30\u0d3e\u0d2f\u0d23\u0d2a\u0d4d\u0d30\u0d23\u0d2f\u0d3f\u0d28\u0d40\u0d28\u0d2f\u0d28\u0d3e\u0d2e\u0d4d\u0d2c\u0d41\u0d35\u0d3e\u0d39\u0d03 \u0965 \u0d6f \u0965", "iast": "dady\u0101dday\u0101nupavano dravi\u1e47\u0101mbudh\u0101r\u0101-\nmasminnaki\u00f1canaviha\u1e45ga\u015bi\u015bau vi\u1e63a\u1e47\u1e47e |\ndu\u1e63karmagharmamapan\u012bya cir\u0101ya d\u016bra\u1e43\nn\u0101r\u0101ya\u1e47apra\u1e47ayin\u012bnayan\u0101mbuv\u0101ha\u1e25 || 9 ||"},
        draftTranslation: "May the cloud of Narayana's beloved's compassionate eyes, impelled by the breeze of Her mercy, shower a torrent of gold and fortune upon this destitute fledgling bird (myself), driving far away the scorch of past sins!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 10,
        devanagariText: "\u0917\u0940\u0930\u094d\u0926\u0947\u0935\u0924\u0947\u0924\u093f \u0917\u0930\u0941\u0921\u0927\u094d\u0935\u091c\u0938\u0941\u0928\u094d\u0926\u0930\u0940\u0924\u093f\n\u0936\u093e\u0915\u092e\u094d\u092d\u0930\u0940\u0924\u093f \u0936\u0936\u093f\u0936\u0947\u0916\u0930\u0935\u0932\u094d\u0932\u092d\u0947\u0924\u093f \u0964\n\u0938\u0943\u0937\u094d\u091f\u093f\u0938\u094d\u0925\u093f\u0924\u093f\u092a\u094d\u0930\u0932\u092f\u0915\u0947\u0932\u093f\u0937\u0941 \u0938\u0902\u0938\u094d\u0925\u093f\u0924\u093e\u092f\u0948\n\u0924\u0938\u094d\u092f\u0948 \u0928\u092e\u0938\u094d\u0924\u094d\u0930\u093f\u092d\u0941\u0935\u0928\u0948\u0915\u0917\u0941\u0930\u094b\u0938\u094d\u0924\u0930\u0941\u0923\u094d\u092f\u0948 \u0965 \u0967\u0966 \u0965",
        iastText: "g\u012brd\u0113vat\u0113ti garu\u1e0dadhvajasundar\u012bti\n\u015b\u0101kambhar\u012bti \u015ba\u015bi\u015b\u0113kharavallabh\u0113ti \u0964\ns\u1e5b\u1e63\u1e6disthitipralayak\u0113li\u1e63u sa\u1e41sthit\u0101yai\ntasyai namastribhuvanaikagur\u014dstaru\u1e47yai \u0965 10 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c17\u0c40\u0c30\u0c4d\u0c26\u0c47\u0c35\u0c24\u0c47\u0c24\u0c3f \u0c17\u0c30\u0c41\u0c21\u0c27\u0c4d\u0c35\u0c1c\u0c38\u0c41\u0c28\u0c4d\u0c26\u0c30\u0c40\u0c24\u0c3f\n\u0c36\u0c3e\u0c15\u0c2e\u0c4d\u0c2d\u0c30\u0c40\u0c24\u0c3f \u0c36\u0c36\u0c3f\u0c36\u0c47\u0c16\u0c30\u0c35\u0c32\u0c4d\u0c32\u0c2d\u0c47\u0c24\u0c3f \u0964\n\u0c38\u0c43\u0c37\u0c4d\u0c1f\u0c3f\u0c38\u0c4d\u0c25\u0c3f\u0c24\u0c3f\u0c2a\u0c4d\u0c30\u0c32\u0c2f\u0c15\u0c47\u0c32\u0c3f\u0c37\u0c41 \u0c38\u0c02\u0c38\u0c4d\u0c25\u0c3f\u0c24\u0c3e\u0c2f\u0c48\n\u0c24\u0c38\u0c4d\u0c2f\u0c48 \u0c28\u0c2e\u0c38\u0c4d\u0c24\u0c4d\u0c30\u0c3f\u0c2d\u0c41\u0c35\u0c28\u0c48\u0c15\u0c17\u0c41\u0c30\u0c4b\u0c38\u0c4d\u0c24\u0c30\u0c41\u0c23\u0c4d\u0c2f\u0c48 \u0965 \u0c67\u0c66 \u0965", "tamil": "\u0b95\u0bc0\u0bb0\u0bcd\u0ba4\u0bc7\u0bb5\u0ba4\u0bc7\u0ba4\u0bbf \u0b95\u0bb0\u0bc1\u0b9f\u0ba4\u0bcd\u0bb5\u0b9c\u0bb8\u0bc1\u0ba8\u0bcd\u0ba4\u0bb0\u0bc0\u0ba4\u0bbf\n\u0bb6\u0bbe\u0b95\u0bae\u0bcd\u0baa\u0bb0\u0bc0\u0ba4\u0bbf \u0bb6\u0bb6\u0bbf\u0bb6\u0bc7\u0b95\u0bb0\u0bb5\u0bb2\u0bcd\u0bb2\u0baa\u0bc7\u0ba4\u0bbf \u0964\n\u0bb8\u0bcd\u0bb0\u0bc1'\u0bb7\u0bcd\u0b9f\u0bbf\u0bb8\u0bcd\u0ba4\u0bbf\u0ba4\u0bbf\u0baa\u0bcd\u0bb0\u0bb2\u0baf\u0b95\u0bc7\u0bb2\u0bbf\u0bb7\u0bc1 \u0bb8\u0bae\u0bcd\u0bb8\u0bcd\u0ba4\u0bbf\u0ba4\u0bbe\u0baf\u0bc8\n\u0ba4\u0bb8\u0bcd\u0baf\u0bc8 \u0ba8\u0bae\u0bb8\u0bcd\u0ba4\u0bcd\u0bb0\u0bbf\u0baa\u0bc1\u0bb5\u0ba8\u0bc8\u0b95\u0b95\u0bc1\u0bb0\u0bcb\u0bb8\u0bcd\u0ba4\u0bb0\u0bc1\u0ba3\u0bcd\u0baf\u0bc8 \u0965 \u0be7\u0be6 \u0965", "kannada": "\u0c97\u0cc0\u0cb0\u0ccd\u0ca6\u0cc7\u0cb5\u0ca4\u0cc7\u0ca4\u0cbf \u0c97\u0cb0\u0cc1\u0ca1\u0ca7\u0ccd\u0cb5\u0c9c\u0cb8\u0cc1\u0ca8\u0ccd\u0ca6\u0cb0\u0cc0\u0ca4\u0cbf\n\u0cb6\u0cbe\u0c95\u0cae\u0ccd\u0cad\u0cb0\u0cc0\u0ca4\u0cbf \u0cb6\u0cb6\u0cbf\u0cb6\u0cc7\u0c96\u0cb0\u0cb5\u0cb2\u0ccd\u0cb2\u0cad\u0cc7\u0ca4\u0cbf \u0964\n\u0cb8\u0cc3\u0cb7\u0ccd\u0c9f\u0cbf\u0cb8\u0ccd\u0ca5\u0cbf\u0ca4\u0cbf\u0caa\u0ccd\u0cb0\u0cb2\u0caf\u0c95\u0cc7\u0cb2\u0cbf\u0cb7\u0cc1 \u0cb8\u0c82\u0cb8\u0ccd\u0ca5\u0cbf\u0ca4\u0cbe\u0caf\u0cc8\n\u0ca4\u0cb8\u0ccd\u0caf\u0cc8 \u0ca8\u0cae\u0cb8\u0ccd\u0ca4\u0ccd\u0cb0\u0cbf\u0cad\u0cc1\u0cb5\u0ca8\u0cc8\u0c95\u0c97\u0cc1\u0cb0\u0ccb\u0cb8\u0ccd\u0ca4\u0cb0\u0cc1\u0ca3\u0ccd\u0caf\u0cc8 \u0965 \u0ce7\u0ce6 \u0965", "malayalam": "\u0d17\u0d40\u0d30\u0d4d\u0d26\u0d47\u0d35\u0d24\u0d47\u0d24\u0d3f \u0d17\u0d30\u0d41\u0d21\u0d27\u0d4d\u0d35\u0d1c\u0d38\u0d41\u0d28\u0d4d\u0d26\u0d30\u0d40\u0d24\u0d3f\n\u0d36\u0d3e\u0d15\u0d2e\u0d4d\u0d2d\u0d30\u0d40\u0d24\u0d3f \u0d36\u0d36\u0d3f\u0d36\u0d47\u0d16\u0d30\u0d35\u0d32\u0d4d\u0d32\u0d2d\u0d47\u0d24\u0d3f \u0964\n\u0d38\u0d43\u0d37\u0d4d\u0d1f\u0d3f\u0d38\u0d4d\u0d25\u0d3f\u0d24\u0d3f\u0d2a\u0d4d\u0d30\u0d32\u0d2f\u0d15\u0d47\u0d32\u0d3f\u0d37\u0d41 \u0d38\u0d02\u0d38\u0d4d\u0d25\u0d3f\u0d24\u0d3e\u0d2f\u0d48\n\u0d24\u0d38\u0d4d\u0d2f\u0d48 \u0d28\u0d2e\u0d38\u0d4d\u0d24\u0d4d\u0d30\u0d3f\u0d2d\u0d41\u0d35\u0d28\u0d48\u0d15\u0d17\u0d41\u0d30\u0d4b\u0d38\u0d4d\u0d24\u0d30\u0d41\u0d23\u0d4d\u0d2f\u0d48 \u0965 \u0d67\u0d66 \u0965", "iast": "g\u012brdevateti garu\u1e0dadhvajasundar\u012bti\n\u015b\u0101kambhar\u012bti \u015ba\u015bi\u015bekharavallabheti |\ns\u1e5b\u1e63\u1e6disthitipralayakeli\u1e63u sa\u1e43sthit\u0101yai\ntasyai namastribhuvanaikagurostaru\u1e47yai || 10 ||"},
        draftTranslation: "Revering Her as Sarasvati (wisdom), Lakshmi (consort of Vishnu), Shakambhari, and Parvati (consort of Shiva), presiding over creation, preservation, and dissolution \u2014 salutations unto that maiden consort of the Supreme Guru of the three worlds!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 11,
        devanagariText: "\u0936\u094d\u0930\u0941\u0924\u094d\u092f\u0948 \u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0936\u0941\u092d\u0915\u0930\u094d\u092e\u092b\u0932\u092a\u094d\u0930\u0938\u0942\u0924\u094d\u092f\u0948\n\u0930\u0924\u094d\u092f\u0948 \u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0930\u092e\u0923\u0940\u092f\u0917\u0941\u0923\u093e\u0930\u094d\u0923\u0935\u093e\u092f\u0948 \u0964\n\u0936\u0915\u094d\u0924\u094d\u092f\u0948 \u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0936\u0924\u092a\u0924\u094d\u0930\u0928\u093f\u0915\u0947\u0924\u0928\u093e\u092f\u0948\n\u092a\u0941\u0937\u094d\u091f\u094d\u092f\u0948 \u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u092a\u0941\u0930\u0941\u0937\u094b\u0924\u094d\u0924\u092e\u0935\u0932\u094d\u0932\u092d\u093e\u092f\u0948 \u0965 \u0967\u0967 \u0965",
        iastText: "\u015brutyai nam\u014d'stu \u015bubhakarmaphalapras\u016btyai\nratyai nam\u014d'stu rama\u1e47\u012byagu\u1e47\u0101r\u1e47av\u0101yai \u0964\n\u015baktyai nam\u014d'stu \u015batapatranik\u0113tan\u0101yai\npu\u1e63\u1e6dyai nam\u014d'stu puru\u1e63\u014dttamavallabh\u0101yai \u0965 11 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c36\u0c4d\u0c30\u0c41\u0c24\u0c4d\u0c2f\u0c48 \u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c36\u0c41\u0c2d\u0c15\u0c30\u0c4d\u0c2e\u0c2b\u0c32\u0c2a\u0c4d\u0c30\u0c38\u0c42\u0c24\u0c4d\u0c2f\u0c48\n\u0c30\u0c24\u0c4d\u0c2f\u0c48 \u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c30\u0c2e\u0c23\u0c40\u0c2f\u0c17\u0c41\u0c23\u0c3e\u0c30\u0c4d\u0c23\u0c35\u0c3e\u0c2f\u0c48 \u0964\n\u0c36\u0c15\u0c4d\u0c24\u0c4d\u0c2f\u0c48 \u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c36\u0c24\u0c2a\u0c24\u0c4d\u0c30\u0c28\u0c3f\u0c15\u0c47\u0c24\u0c28\u0c3e\u0c2f\u0c48\n\u0c2a\u0c41\u0c37\u0c4d\u0c1f\u0c4d\u0c2f\u0c48 \u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c2a\u0c41\u0c30\u0c41\u0c37\u0c4b\u0c24\u0c4d\u0c24\u0c2e\u0c35\u0c32\u0c4d\u0c32\u0c2d\u0c3e\u0c2f\u0c48 \u0965 \u0c67\u0c67 \u0965", "tamil": "\u0bb6\u0bcd\u0bb0\u0bc1\u0ba4\u0bcd\u0baf\u0bc8 \u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0bb6\u0bc1\u0baa\u0b95\u0bb0\u0bcd\u0bae\u0baa\u0bb2\u0baa\u0bcd\u0bb0\u0bb8\u0bc2\u0ba4\u0bcd\u0baf\u0bc8\n\u0bb0\u0ba4\u0bcd\u0baf\u0bc8 \u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0bb0\u0bae\u0ba3\u0bc0\u0baf\u0b95\u0bc1\u0ba3\u0bbe\u0bb0\u0bcd\u0ba3\u0bb5\u0bbe\u0baf\u0bc8 \u0964\n\u0bb6\u0b95\u0bcd\u0ba4\u0bcd\u0baf\u0bc8 \u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0bb6\u0ba4\u0baa\u0ba4\u0bcd\u0bb0\u0ba8\u0bbf\u0b95\u0bc7\u0ba4\u0ba8\u0bbe\u0baf\u0bc8\n\u0baa\u0bc1\u0bb7\u0bcd\u0b9f\u0bcd\u0baf\u0bc8 \u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0baa\u0bc1\u0bb0\u0bc1\u0bb7\u0bcb\u0ba4\u0bcd\u0ba4\u0bae\u0bb5\u0bb2\u0bcd\u0bb2\u0baa\u0bbe\u0baf\u0bc8 \u0965 \u0be7\u0be7 \u0965", "kannada": "\u0cb6\u0ccd\u0cb0\u0cc1\u0ca4\u0ccd\u0caf\u0cc8 \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0cb6\u0cc1\u0cad\u0c95\u0cb0\u0ccd\u0cae\u0cab\u0cb2\u0caa\u0ccd\u0cb0\u0cb8\u0cc2\u0ca4\u0ccd\u0caf\u0cc8\n\u0cb0\u0ca4\u0ccd\u0caf\u0cc8 \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0cb0\u0cae\u0ca3\u0cc0\u0caf\u0c97\u0cc1\u0ca3\u0cbe\u0cb0\u0ccd\u0ca3\u0cb5\u0cbe\u0caf\u0cc8 \u0964\n\u0cb6\u0c95\u0ccd\u0ca4\u0ccd\u0caf\u0cc8 \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0cb6\u0ca4\u0caa\u0ca4\u0ccd\u0cb0\u0ca8\u0cbf\u0c95\u0cc7\u0ca4\u0ca8\u0cbe\u0caf\u0cc8\n\u0caa\u0cc1\u0cb7\u0ccd\u0c9f\u0ccd\u0caf\u0cc8 \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0caa\u0cc1\u0cb0\u0cc1\u0cb7\u0ccb\u0ca4\u0ccd\u0ca4\u0cae\u0cb5\u0cb2\u0ccd\u0cb2\u0cad\u0cbe\u0caf\u0cc8 \u0965 \u0ce7\u0ce7 \u0965", "malayalam": "\u0d36\u0d4d\u0d30\u0d41\u0d24\u0d4d\u0d2f\u0d48 \u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d36\u0d41\u0d2d\u0d15\u0d30\u0d4d\u0d2e\u0d2b\u0d32\u0d2a\u0d4d\u0d30\u0d38\u0d42\u0d24\u0d4d\u0d2f\u0d48\n\u0d30\u0d24\u0d4d\u0d2f\u0d48 \u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d30\u0d2e\u0d23\u0d40\u0d2f\u0d17\u0d41\u0d23\u0d3e\u0d30\u0d4d\u0d23\u0d35\u0d3e\u0d2f\u0d48 \u0964\n\u0d36\u0d15\u0d4d\u0d24\u0d4d\u0d2f\u0d48 \u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d36\u0d24\u0d2a\u0d24\u0d4d\u0d30\u0d28\u0d3f\u0d15\u0d47\u0d24\u0d28\u0d3e\u0d2f\u0d48\n\u0d2a\u0d41\u0d37\u0d4d\u0d1f\u0d4d\u0d2f\u0d48 \u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d2a\u0d41\u0d30\u0d41\u0d37\u0d4b\u0d24\u0d4d\u0d24\u0d2e\u0d35\u0d32\u0d4d\u0d32\u0d2d\u0d3e\u0d2f\u0d48 \u0965 \u0d67\u0d67 \u0965", "iast": "\u015brutyai namo'stu \u015bubhakarmaphalapras\u016btyai\nratyai namo'stu rama\u1e47\u012byagu\u1e47\u0101r\u1e47av\u0101yai |\n\u015baktyai namo'stu \u015batapatraniketan\u0101yai\npu\u1e63\u1e6dyai namo'stu puru\u1e63ottamavallabh\u0101yai || 11 ||"},
        draftTranslation: "Salutations to You as Shruti (the Vedas) bestowing the fruits of righteous deeds! Salutations as Rati, the ocean of endearing virtues! Salutations as Shakti, enthroned upon the hundred-petaled lotus! Salutations as Pushti, beloved of Purushottama!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 12,
        devanagariText: "\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0928\u093e\u0932\u0940\u0915\u0928\u093f\u092d\u093e\u0928\u0928\u093e\u092f\u0948\n\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0926\u0941\u0917\u094d\u0927\u094b\u0926\u0927\u093f\u091c\u0928\u094d\u092e\u092d\u0942\u092e\u094d\u092f\u0948 \u0964\n\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0938\u094b\u092e\u093e\u092e\u0943\u0924\u0938\u094b\u0926\u0930\u093e\u092f\u0948\n\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0928\u093e\u0930\u093e\u092f\u0923\u0935\u0932\u094d\u0932\u092d\u093e\u092f\u0948 \u0965 \u0967\u0968 \u0965",
        iastText: "nam\u014d'stu n\u0101l\u012bkanibh\u0101nan\u0101yai\nnam\u014d'stu dugdh\u014ddadhijanmabh\u016bmyai \u0964\nnam\u014d'stu s\u014dm\u0101m\u1e5btas\u014ddar\u0101yai\nnam\u014d'stu n\u0101r\u0101ya\u1e47avallabh\u0101yai \u0965 12 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c28\u0c3e\u0c32\u0c40\u0c15\u0c28\u0c3f\u0c2d\u0c3e\u0c28\u0c28\u0c3e\u0c2f\u0c48\n\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c26\u0c41\u0c17\u0c4d\u0c27\u0c4b\u0c26\u0c27\u0c3f\u0c1c\u0c28\u0c4d\u0c2e\u0c2d\u0c42\u0c2e\u0c4d\u0c2f\u0c48 \u0964\n\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c38\u0c4b\u0c2e\u0c3e\u0c2e\u0c43\u0c24\u0c38\u0c4b\u0c26\u0c30\u0c3e\u0c2f\u0c48\n\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c28\u0c3e\u0c30\u0c3e\u0c2f\u0c23\u0c35\u0c32\u0c4d\u0c32\u0c2d\u0c3e\u0c2f\u0c48 \u0965 \u0c67\u0c68 \u0965", "tamil": "\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba8\u0bbe\u0bb2\u0bc0\u0b95\u0ba8\u0bbf\u0baa\u0bbe\u0ba8\u0ba8\u0bbe\u0baf\u0bc8\n\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bc1\u0b95\u0bcd\u0ba4\u0bcb\u0ba4\u0ba4\u0bbf\u0b9c\u0ba8\u0bcd\u0bae\u0baa\u0bc2\u0bae\u0bcd\u0baf\u0bc8 \u0964\n\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0bb8\u0bcb\u0bae\u0bbe\u0bae\u0bcd\u0bb0\u0bc1'\u0ba4\u0bb8\u0bcb\u0ba4\u0bb0\u0bbe\u0baf\u0bc8\n\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba8\u0bbe\u0bb0\u0bbe\u0baf\u0ba3\u0bb5\u0bb2\u0bcd\u0bb2\u0baa\u0bbe\u0baf\u0bc8 \u0965 \u0be7\u0be8 \u0965", "kannada": "\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca8\u0cbe\u0cb2\u0cc0\u0c95\u0ca8\u0cbf\u0cad\u0cbe\u0ca8\u0ca8\u0cbe\u0caf\u0cc8\n\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca6\u0cc1\u0c97\u0ccd\u0ca7\u0ccb\u0ca6\u0ca7\u0cbf\u0c9c\u0ca8\u0ccd\u0cae\u0cad\u0cc2\u0cae\u0ccd\u0caf\u0cc8 \u0964\n\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0cb8\u0ccb\u0cae\u0cbe\u0cae\u0cc3\u0ca4\u0cb8\u0ccb\u0ca6\u0cb0\u0cbe\u0caf\u0cc8\n\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca8\u0cbe\u0cb0\u0cbe\u0caf\u0ca3\u0cb5\u0cb2\u0ccd\u0cb2\u0cad\u0cbe\u0caf\u0cc8 \u0965 \u0ce7\u0ce8 \u0965", "malayalam": "\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d28\u0d3e\u0d32\u0d40\u0d15\u0d28\u0d3f\u0d2d\u0d3e\u0d28\u0d28\u0d3e\u0d2f\u0d48\n\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d26\u0d41\u0d17\u0d4d\u0d27\u0d4b\u0d26\u0d27\u0d3f\u0d1c\u0d28\u0d4d\u0d2e\u0d2d\u0d42\u0d2e\u0d4d\u0d2f\u0d48 \u0964\n\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d38\u0d4b\u0d2e\u0d3e\u0d2e\u0d43\u0d24\u0d38\u0d4b\u0d26\u0d30\u0d3e\u0d2f\u0d48\n\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d28\u0d3e\u0d30\u0d3e\u0d2f\u0d23\u0d35\u0d32\u0d4d\u0d32\u0d2d\u0d3e\u0d2f\u0d48 \u0965 \u0d67\u0d68 \u0965", "iast": "namo'stu n\u0101l\u012bkanibh\u0101nan\u0101yai\nnamo'stu dugdhodadhijanmabh\u016bmyai |\nnamo'stu som\u0101m\u1e5btasodar\u0101yai\nnamo'stu n\u0101r\u0101ya\u1e47avallabh\u0101yai || 12 ||"},
        draftTranslation: "Salutations to Her whose face is fair as the blooming lotus! Salutations to Her whose birthplace is the Milky Ocean! Salutations to the sister of the Moon and divine nectar! Salutations to the beloved of Narayana!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 13,
        devanagariText: "\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0939\u0947\u092e\u093e\u092e\u094d\u092c\u0941\u091c\u092a\u0940\u0920\u093f\u0915\u093e\u092f\u0948\n\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u092d\u0942\u092e\u0923\u094d\u0921\u0932\u0928\u093e\u092f\u093f\u0915\u093e\u092f\u0948 \u0964\n\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0926\u0947\u0935\u093e\u0926\u093f\u0926\u092f\u093e\u092a\u0930\u093e\u092f\u0948\n\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0936\u093e\u0930\u094d\u0919\u094d\u0917\u092f\u0941\u0927\u0935\u0932\u094d\u0932\u092d\u093e\u092f\u0948 \u0965 \u0967\u0969 \u0965",
        iastText: "nam\u014d'stu h\u0113m\u0101mbujap\u012b\u1e6dhik\u0101yai\nnam\u014d'stu bh\u016bma\u1e47\u1e0dalan\u0101yik\u0101yai \u0964\nnam\u014d'stu d\u0113v\u0101diday\u0101par\u0101yai\nnam\u014d'stu \u015b\u0101r\u1e45gayudhavallabh\u0101yai \u0965 13 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c39\u0c47\u0c2e\u0c3e\u0c2e\u0c4d\u0c2c\u0c41\u0c1c\u0c2a\u0c40\u0c20\u0c3f\u0c15\u0c3e\u0c2f\u0c48\n\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c2d\u0c42\u0c2e\u0c23\u0c4d\u0c21\u0c32\u0c28\u0c3e\u0c2f\u0c3f\u0c15\u0c3e\u0c2f\u0c48 \u0964\n\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c26\u0c47\u0c35\u0c3e\u0c26\u0c3f\u0c26\u0c2f\u0c3e\u0c2a\u0c30\u0c3e\u0c2f\u0c48\n\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c36\u0c3e\u0c30\u0c4d\u0c19\u0c4d\u0c17\u0c2f\u0c41\u0c27\u0c35\u0c32\u0c4d\u0c32\u0c2d\u0c3e\u0c2f\u0c48 \u0965 \u0c67\u0c69 \u0965", "tamil": "\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0bb9\u0bc7\u0bae\u0bbe\u0bae\u0bcd\u0baa\u0bc1\u0b9c\u0baa\u0bc0\u0b9f\u0bbf\u0b95\u0bbe\u0baf\u0bc8\n\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0baa\u0bc2\u0bae\u0ba3\u0bcd\u0b9f\u0bb2\u0ba8\u0bbe\u0baf\u0bbf\u0b95\u0bbe\u0baf\u0bc8 \u0964\n\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bc7\u0bb5\u0bbe\u0ba4\u0bbf\u0ba4\u0baf\u0bbe\u0baa\u0bb0\u0bbe\u0baf\u0bc8\n\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0bb6\u0bbe\u0bb0\u0bcd\u0b99\u0bcd\u0b95\u0baf\u0bc1\u0ba4\u0bb5\u0bb2\u0bcd\u0bb2\u0baa\u0bbe\u0baf\u0bc8 \u0965 \u0be7\u0be9 \u0965", "kannada": "\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0cb9\u0cc7\u0cae\u0cbe\u0cae\u0ccd\u0cac\u0cc1\u0c9c\u0caa\u0cc0\u0ca0\u0cbf\u0c95\u0cbe\u0caf\u0cc8\n\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0cad\u0cc2\u0cae\u0ca3\u0ccd\u0ca1\u0cb2\u0ca8\u0cbe\u0caf\u0cbf\u0c95\u0cbe\u0caf\u0cc8 \u0964\n\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca6\u0cc7\u0cb5\u0cbe\u0ca6\u0cbf\u0ca6\u0caf\u0cbe\u0caa\u0cb0\u0cbe\u0caf\u0cc8\n\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0cb6\u0cbe\u0cb0\u0ccd\u0c99\u0ccd\u0c97\u0caf\u0cc1\u0ca7\u0cb5\u0cb2\u0ccd\u0cb2\u0cad\u0cbe\u0caf\u0cc8 \u0965 \u0ce7\u0ce9 \u0965", "malayalam": "\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d39\u0d47\u0d2e\u0d3e\u0d2e\u0d4d\u0d2c\u0d41\u0d1c\u0d2a\u0d40\u0d20\u0d3f\u0d15\u0d3e\u0d2f\u0d48\n\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d2d\u0d42\u0d2e\u0d23\u0d4d\u0d21\u0d32\u0d28\u0d3e\u0d2f\u0d3f\u0d15\u0d3e\u0d2f\u0d48 \u0964\n\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d26\u0d47\u0d35\u0d3e\u0d26\u0d3f\u0d26\u0d2f\u0d3e\u0d2a\u0d30\u0d3e\u0d2f\u0d48\n\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d36\u0d3e\u0d30\u0d4d\u0d19\u0d4d\u0d17\u0d2f\u0d41\u0d27\u0d35\u0d32\u0d4d\u0d32\u0d2d\u0d3e\u0d2f\u0d48 \u0965 \u0d67\u0d69 \u0965", "iast": "namo'stu hem\u0101mbujap\u012b\u1e6dhik\u0101yai\nnamo'stu bh\u016bma\u1e47\u1e0dalan\u0101yik\u0101yai |\nnamo'stu dev\u0101diday\u0101par\u0101yai\nnamo'stu \u015b\u0101r\u1e45gayudhavallabh\u0101yai || 13 ||"},
        draftTranslation: "Salutations to Her seated upon the golden lotus altar! Salutations to the Sovereign Empress of the entire earth! Salutations to Her who overflows with mercy toward the gods! Salutations to the beloved consort of the bearer of the Sarnga bow!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 14,
        devanagariText: "\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0926\u0947\u0935\u094d\u092f\u0948 \u092d\u0943\u0917\u0941\u0928\u0928\u094d\u0926\u0928\u093e\u092f\u0948\n\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0935\u093f\u0937\u094d\u0923\u094b\u0930\u0941\u0930\u0938\u093f \u0938\u094d\u0925\u093f\u0924\u093e\u092f\u0948 \u0964\n\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0932\u0915\u094d\u0937\u094d\u092e\u094d\u092f\u0948 \u0915\u092e\u0932\u093e\u0932\u092f\u093e\u092f\u0948\n\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0926\u093e\u092e\u094b\u0926\u0930\u0935\u0932\u094d\u0932\u092d\u093e\u092f\u0948 \u0965 \u0967\u096a \u0965",
        iastText: "nam\u014d'stu d\u0113vyai bh\u1e5bgunandan\u0101yai\nnam\u014d'stu vi\u1e63\u1e47\u014drurasi sthit\u0101yai \u0964\nnam\u014d'stu lak\u1e63myai kamal\u0101lay\u0101yai\nnam\u014d'stu d\u0101m\u014ddaravallabh\u0101yai \u0965 14 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c26\u0c47\u0c35\u0c4d\u0c2f\u0c48 \u0c2d\u0c43\u0c17\u0c41\u0c28\u0c28\u0c4d\u0c26\u0c28\u0c3e\u0c2f\u0c48\n\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c35\u0c3f\u0c37\u0c4d\u0c23\u0c4b\u0c30\u0c41\u0c30\u0c38\u0c3f \u0c38\u0c4d\u0c25\u0c3f\u0c24\u0c3e\u0c2f\u0c48 \u0964\n\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c32\u0c15\u0c4d\u0c37\u0c4d\u0c2e\u0c4d\u0c2f\u0c48 \u0c15\u0c2e\u0c32\u0c3e\u0c32\u0c2f\u0c3e\u0c2f\u0c48\n\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c26\u0c3e\u0c2e\u0c4b\u0c26\u0c30\u0c35\u0c32\u0c4d\u0c32\u0c2d\u0c3e\u0c2f\u0c48 \u0965 \u0c67\u0c6a \u0965", "tamil": "\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bc7\u0bb5\u0bcd\u0baf\u0bc8 \u0baa\u0bcd\u0bb0\u0bc1'\u0b95\u0bc1\u0ba8\u0ba8\u0bcd\u0ba4\u0ba8\u0bbe\u0baf\u0bc8\n\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0bb5\u0bbf\u0bb7\u0bcd\u0ba3\u0bcb\u0bb0\u0bc1\u0bb0\u0bb8\u0bbf \u0bb8\u0bcd\u0ba4\u0bbf\u0ba4\u0bbe\u0baf\u0bc8 \u0964\n\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0bb2\u0b95\u0bcd\u0bb7\u0bcd\u0bae\u0bcd\u0baf\u0bc8 \u0b95\u0bae\u0bb2\u0bbe\u0bb2\u0baf\u0bbe\u0baf\u0bc8\n\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bbe\u0bae\u0bcb\u0ba4\u0bb0\u0bb5\u0bb2\u0bcd\u0bb2\u0baa\u0bbe\u0baf\u0bc8 \u0965 \u0be7\u0bea \u0965", "kannada": "\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca6\u0cc7\u0cb5\u0ccd\u0caf\u0cc8 \u0cad\u0cc3\u0c97\u0cc1\u0ca8\u0ca8\u0ccd\u0ca6\u0ca8\u0cbe\u0caf\u0cc8\n\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0cb5\u0cbf\u0cb7\u0ccd\u0ca3\u0ccb\u0cb0\u0cc1\u0cb0\u0cb8\u0cbf \u0cb8\u0ccd\u0ca5\u0cbf\u0ca4\u0cbe\u0caf\u0cc8 \u0964\n\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0cb2\u0c95\u0ccd\u0cb7\u0ccd\u0cae\u0ccd\u0caf\u0cc8 \u0c95\u0cae\u0cb2\u0cbe\u0cb2\u0caf\u0cbe\u0caf\u0cc8\n\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca6\u0cbe\u0cae\u0ccb\u0ca6\u0cb0\u0cb5\u0cb2\u0ccd\u0cb2\u0cad\u0cbe\u0caf\u0cc8 \u0965 \u0ce7\u0cea \u0965", "malayalam": "\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d26\u0d47\u0d35\u0d4d\u0d2f\u0d48 \u0d2d\u0d43\u0d17\u0d41\u0d28\u0d28\u0d4d\u0d26\u0d28\u0d3e\u0d2f\u0d48\n\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d35\u0d3f\u0d37\u0d4d\u0d23\u0d4b\u0d30\u0d41\u0d30\u0d38\u0d3f \u0d38\u0d4d\u0d25\u0d3f\u0d24\u0d3e\u0d2f\u0d48 \u0964\n\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d32\u0d15\u0d4d\u0d37\u0d4d\u0d2e\u0d4d\u0d2f\u0d48 \u0d15\u0d2e\u0d32\u0d3e\u0d32\u0d2f\u0d3e\u0d2f\u0d48\n\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d26\u0d3e\u0d2e\u0d4b\u0d26\u0d30\u0d35\u0d32\u0d4d\u0d32\u0d2d\u0d3e\u0d2f\u0d48 \u0965 \u0d67\u0d6a \u0965", "iast": "namo'stu devyai bh\u1e5bgunandan\u0101yai\nnamo'stu vi\u1e63\u1e47orurasi sthit\u0101yai |\nnamo'stu lak\u1e63myai kamal\u0101lay\u0101yai\nnamo'stu d\u0101modaravallabh\u0101yai || 14 ||"},
        draftTranslation: "Salutations to the divine daughter of Sage Bhrigu! Salutations to Her who ever abides upon the chest of Vishnu! Salutations to Lakshmi, dwelling in the lotus! Salutations to the beloved consort of Damodara!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 15,
        devanagariText: "\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0915\u093e\u0928\u094d\u0924\u094d\u092f\u0948 \u0915\u092e\u0932\u0947\u0915\u094d\u0937\u0923\u093e\u092f\u0948\n\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u092d\u0942\u0924\u094d\u092f\u0948 \u092d\u0941\u0935\u0928\u092a\u094d\u0930\u0938\u0942\u0924\u094d\u092f\u0948 \u0964\n\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0926\u0947\u0935\u093e\u0926\u093f\u092d\u093f\u0930\u0930\u094d\u091a\u093f\u0924\u093e\u092f\u0948\n\u0928\u092e\u094b\u093d\u0938\u094d\u0924\u0941 \u0928\u0928\u094d\u0926\u093e\u0924\u094d\u092e\u091c\u0935\u0932\u094d\u0932\u092d\u093e\u092f\u0948 \u0965 \u0967\u096b \u0965",
        iastText: "nam\u014d'stu k\u0101ntyai kamal\u0113k\u1e63a\u1e47\u0101yai\nnam\u014d'stu bh\u016btyai bhuvanapras\u016btyai \u0964\nnam\u014d'stu d\u0113v\u0101dibhirarcit\u0101yai\nnam\u014d'stu nand\u0101tmajavallabh\u0101yai \u0965 15 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c15\u0c3e\u0c28\u0c4d\u0c24\u0c4d\u0c2f\u0c48 \u0c15\u0c2e\u0c32\u0c47\u0c15\u0c4d\u0c37\u0c23\u0c3e\u0c2f\u0c48\n\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c2d\u0c42\u0c24\u0c4d\u0c2f\u0c48 \u0c2d\u0c41\u0c35\u0c28\u0c2a\u0c4d\u0c30\u0c38\u0c42\u0c24\u0c4d\u0c2f\u0c48 \u0964\n\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c26\u0c47\u0c35\u0c3e\u0c26\u0c3f\u0c2d\u0c3f\u0c30\u0c30\u0c4d\u0c1a\u0c3f\u0c24\u0c3e\u0c2f\u0c48\n\u0c28\u0c2e\u0c4b\u0c3d\u0c38\u0c4d\u0c24\u0c41 \u0c28\u0c28\u0c4d\u0c26\u0c3e\u0c24\u0c4d\u0c2e\u0c1c\u0c35\u0c32\u0c4d\u0c32\u0c2d\u0c3e\u0c2f\u0c48 \u0965 \u0c67\u0c6b \u0965", "tamil": "\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0b95\u0bbe\u0ba8\u0bcd\u0ba4\u0bcd\u0baf\u0bc8 \u0b95\u0bae\u0bb2\u0bc7\u0b95\u0bcd\u0bb7\u0ba3\u0bbe\u0baf\u0bc8\n\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0baa\u0bc2\u0ba4\u0bcd\u0baf\u0bc8 \u0baa\u0bc1\u0bb5\u0ba8\u0baa\u0bcd\u0bb0\u0bb8\u0bc2\u0ba4\u0bcd\u0baf\u0bc8 \u0964\n\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba4\u0bc7\u0bb5\u0bbe\u0ba4\u0bbf\u0baa\u0bbf\u0bb0\u0bb0\u0bcd\u0b9a\u0bbf\u0ba4\u0bbe\u0baf\u0bc8\n\u0ba8\u0bae\u0bcb\u093d\u0bb8\u0bcd\u0ba4\u0bc1 \u0ba8\u0ba8\u0bcd\u0ba4\u0bbe\u0ba4\u0bcd\u0bae\u0b9c\u0bb5\u0bb2\u0bcd\u0bb2\u0baa\u0bbe\u0baf\u0bc8 \u0965 \u0be7\u0beb \u0965", "kannada": "\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0c95\u0cbe\u0ca8\u0ccd\u0ca4\u0ccd\u0caf\u0cc8 \u0c95\u0cae\u0cb2\u0cc7\u0c95\u0ccd\u0cb7\u0ca3\u0cbe\u0caf\u0cc8\n\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0cad\u0cc2\u0ca4\u0ccd\u0caf\u0cc8 \u0cad\u0cc1\u0cb5\u0ca8\u0caa\u0ccd\u0cb0\u0cb8\u0cc2\u0ca4\u0ccd\u0caf\u0cc8 \u0964\n\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca6\u0cc7\u0cb5\u0cbe\u0ca6\u0cbf\u0cad\u0cbf\u0cb0\u0cb0\u0ccd\u0c9a\u0cbf\u0ca4\u0cbe\u0caf\u0cc8\n\u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca8\u0ca8\u0ccd\u0ca6\u0cbe\u0ca4\u0ccd\u0cae\u0c9c\u0cb5\u0cb2\u0ccd\u0cb2\u0cad\u0cbe\u0caf\u0cc8 \u0965 \u0ce7\u0ceb \u0965", "malayalam": "\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d15\u0d3e\u0d28\u0d4d\u0d24\u0d4d\u0d2f\u0d48 \u0d15\u0d2e\u0d32\u0d47\u0d15\u0d4d\u0d37\u0d23\u0d3e\u0d2f\u0d48\n\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d2d\u0d42\u0d24\u0d4d\u0d2f\u0d48 \u0d2d\u0d41\u0d35\u0d28\u0d2a\u0d4d\u0d30\u0d38\u0d42\u0d24\u0d4d\u0d2f\u0d48 \u0964\n\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d26\u0d47\u0d35\u0d3e\u0d26\u0d3f\u0d2d\u0d3f\u0d30\u0d30\u0d4d\u0d1a\u0d3f\u0d24\u0d3e\u0d2f\u0d48\n\u0d28\u0d2e\u0d4b\u0d3d\u0d38\u0d4d\u0d24\u0d41 \u0d28\u0d28\u0d4d\u0d26\u0d3e\u0d24\u0d4d\u0d2e\u0d1c\u0d35\u0d32\u0d4d\u0d32\u0d2d\u0d3e\u0d2f\u0d48 \u0965 \u0d67\u0d6b \u0965", "iast": "namo'stu k\u0101ntyai kamalek\u1e63a\u1e47\u0101yai\nnamo'stu bh\u016btyai bhuvanapras\u016btyai |\nnamo'stu dev\u0101dibhirarcit\u0101yai\nnamo'stu nand\u0101tmajavallabh\u0101yai || 15 ||"},
        draftTranslation: "Salutations to Her who is radiant beauty incarnate with lotus eyes! Salutations to Her who is wealth and mother of all worlds! Salutations to Her adored by all celestials! Salutations to the beloved of the son of Nanda!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 16,
        devanagariText: "\u0938\u092e\u094d\u092a\u0924\u094d\u0915\u0930\u093e\u0923\u093f \u0938\u0915\u0932\u0947\u0928\u094d\u0926\u094d\u0930\u093f\u092f\u0928\u0928\u094d\u0926\u0928\u093e\u0928\u093f\n\u0938\u093e\u092e\u094d\u0930\u093e\u091c\u094d\u092f\u0926\u093e\u0928\u0935\u093f\u092d\u0935\u093e\u0928\u093f \u0938\u0930\u094b\u0930\u0941\u0939\u093e\u0923\u093f \u0964\n\u0924\u094d\u0935\u0926\u094d\u0935\u0928\u094d\u0926\u0928\u093e\u0928\u093f \u0926\u0941\u0930\u093f\u0924\u093e\u0939\u0930\u0923\u094b\u0926\u094d\u092f\u0924\u093e\u0928\u093f\n\u092e\u093e\u092e\u0947\u0935 \u092e\u093e\u0924\u0930\u0928\u093f\u0936\u0902 \u0915\u0932\u092f\u0928\u094d\u0924\u0941 \u092e\u093e\u0928\u094d\u092f\u0947 \u0965 \u0967\u096c \u0965",
        iastText: "sampatkar\u0101\u1e47i sakal\u0113ndriyanandan\u0101ni\ns\u0101mr\u0101jyad\u0101navibhav\u0101ni sar\u014druh\u0101\u1e47i \u0964\ntvadvandan\u0101ni durit\u0101hara\u1e47\u014ddyat\u0101ni\nm\u0101m\u0113va m\u0101t\u0259rani\u015ba\u1e41 kalayantu m\u0101ny\u0113 \u0965 16 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c38\u0c2e\u0c4d\u0c2a\u0c24\u0c4d\u0c15\u0c30\u0c3e\u0c23\u0c3f \u0c38\u0c15\u0c32\u0c47\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c3f\u0c2f\u0c28\u0c28\u0c4d\u0c26\u0c28\u0c3e\u0c28\u0c3f\n\u0c38\u0c3e\u0c2e\u0c4d\u0c30\u0c3e\u0c1c\u0c4d\u0c2f\u0c26\u0c3e\u0c28\u0c35\u0c3f\u0c2d\u0c35\u0c3e\u0c28\u0c3f \u0c38\u0c30\u0c4b\u0c30\u0c41\u0c39\u0c3e\u0c23\u0c3f \u0964\n\u0c24\u0c4d\u0c35\u0c26\u0c4d\u0c35\u0c28\u0c4d\u0c26\u0c28\u0c3e\u0c28\u0c3f \u0c26\u0c41\u0c30\u0c3f\u0c24\u0c3e\u0c39\u0c30\u0c23\u0c4b\u0c26\u0c4d\u0c2f\u0c24\u0c3e\u0c28\u0c3f\n\u0c2e\u0c3e\u0c2e\u0c47\u0c35 \u0c2e\u0c3e\u0c24\u0c30\u0c28\u0c3f\u0c36\u0c02 \u0c15\u0c32\u0c2f\u0c28\u0c4d\u0c24\u0c41 \u0c2e\u0c3e\u0c28\u0c4d\u0c2f\u0c47 \u0965 \u0c67\u0c6c \u0965", "tamil": "\u0bb8\u0bae\u0bcd\u0baa\u0ba4\u0bcd\u0b95\u0bb0\u0bbe\u0ba3\u0bbf \u0bb8\u0b95\u0bb2\u0bc7\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bbf\u0baf\u0ba8\u0ba8\u0bcd\u0ba4\u0ba8\u0bbe\u0ba8\u0bbf\n\u0bb8\u0bbe\u0bae\u0bcd\u0bb0\u0bbe\u0b9c\u0bcd\u0baf\u0ba4\u0bbe\u0ba8\u0bb5\u0bbf\u0baa\u0bb5\u0bbe\u0ba8\u0bbf \u0bb8\u0bb0\u0bcb\u0bb0\u0bc1\u0bb9\u0bbe\u0ba3\u0bbf \u0964\n\u0ba4\u0bcd\u0bb5\u0ba4\u0bcd\u0bb5\u0ba8\u0bcd\u0ba4\u0ba8\u0bbe\u0ba8\u0bbf \u0ba4\u0bc1\u0bb0\u0bbf\u0ba4\u0bbe\u0bb9\u0bb0\u0ba3\u0bcb\u0ba4\u0bcd\u0baf\u0ba4\u0bbe\u0ba8\u0bbf\n\u0bae\u0bbe\u0bae\u0bc7\u0bb5 \u0bae\u0bbe\u0ba4\u0bb0\u0ba8\u0bbf\u0bb6\u0bae\u0bcd \u0b95\u0bb2\u0baf\u0ba8\u0bcd\u0ba4\u0bc1 \u0bae\u0bbe\u0ba8\u0bcd\u0baf\u0bc7 \u0965 \u0be7\u0bec \u0965", "kannada": "\u0cb8\u0cae\u0ccd\u0caa\u0ca4\u0ccd\u0c95\u0cb0\u0cbe\u0ca3\u0cbf \u0cb8\u0c95\u0cb2\u0cc7\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0cbf\u0caf\u0ca8\u0ca8\u0ccd\u0ca6\u0ca8\u0cbe\u0ca8\u0cbf\n\u0cb8\u0cbe\u0cae\u0ccd\u0cb0\u0cbe\u0c9c\u0ccd\u0caf\u0ca6\u0cbe\u0ca8\u0cb5\u0cbf\u0cad\u0cb5\u0cbe\u0ca8\u0cbf \u0cb8\u0cb0\u0ccb\u0cb0\u0cc1\u0cb9\u0cbe\u0ca3\u0cbf \u0964\n\u0ca4\u0ccd\u0cb5\u0ca6\u0ccd\u0cb5\u0ca8\u0ccd\u0ca6\u0ca8\u0cbe\u0ca8\u0cbf \u0ca6\u0cc1\u0cb0\u0cbf\u0ca4\u0cbe\u0cb9\u0cb0\u0ca3\u0ccb\u0ca6\u0ccd\u0caf\u0ca4\u0cbe\u0ca8\u0cbf\n\u0cae\u0cbe\u0cae\u0cc7\u0cb5 \u0cae\u0cbe\u0ca4\u0cb0\u0ca8\u0cbf\u0cb6\u0c82 \u0c95\u0cb2\u0caf\u0ca8\u0ccd\u0ca4\u0cc1 \u0cae\u0cbe\u0ca8\u0ccd\u0caf\u0cc7 \u0965 \u0ce7\u0cec \u0965", "malayalam": "\u0d38\u0d2e\u0d4d\u0d2a\u0d24\u0d4d\u0d15\u0d30\u0d3e\u0d23\u0d3f \u0d38\u0d15\u0d32\u0d47\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d3f\u0d2f\u0d28\u0d28\u0d4d\u0d26\u0d28\u0d3e\u0d28\u0d3f\n\u0d38\u0d3e\u0d2e\u0d4d\u0d30\u0d3e\u0d1c\u0d4d\u0d2f\u0d26\u0d3e\u0d28\u0d35\u0d3f\u0d2d\u0d35\u0d3e\u0d28\u0d3f \u0d38\u0d30\u0d4b\u0d30\u0d41\u0d39\u0d3e\u0d23\u0d3f \u0964\n\u0d24\u0d4d\u0d35\u0d26\u0d4d\u0d35\u0d28\u0d4d\u0d26\u0d28\u0d3e\u0d28\u0d3f \u0d26\u0d41\u0d30\u0d3f\u0d24\u0d3e\u0d39\u0d30\u0d23\u0d4b\u0d26\u0d4d\u0d2f\u0d24\u0d3e\u0d28\u0d3f\n\u0d2e\u0d3e\u0d2e\u0d47\u0d35 \u0d2e\u0d3e\u0d24\u0d30\u0d28\u0d3f\u0d36\u0d02 \u0d15\u0d32\u0d2f\u0d28\u0d4d\u0d24\u0d41 \u0d2e\u0d3e\u0d28\u0d4d\u0d2f\u0d47 \u0965 \u0d67\u0d6c \u0965", "iast": "sampatkar\u0101\u1e47i sakalendriyanandan\u0101ni\ns\u0101mr\u0101jyad\u0101navibhav\u0101ni saroruh\u0101\u1e47i |\ntvadvandan\u0101ni durit\u0101hara\u1e47odyat\u0101ni\nm\u0101meva m\u0101tarani\u015ba\u1e43 kalayantu m\u0101nye || 16 ||"},
        draftTranslation: "Bestowing wealth, delighting all senses, endowed with the power to confer celestial sovereignty, dispelling all sins \u2014 may prostrations to You, O venerable Mother, ever purify and uplift me day and night!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 17,
        devanagariText: "\u092f\u0924\u094d\u0915\u091f\u093e\u0915\u094d\u0937\u0938\u092e\u0941\u092a\u093e\u0938\u0928\u093e\u0935\u093f\u0927\u093f\u0903\n\u0938\u0947\u0935\u0915\u0938\u094d\u092f \u0938\u0915\u0932\u093e\u0930\u094d\u0925\u0938\u092e\u094d\u092a\u0926\u0903 \u0964\n\u0938\u0902\u0924\u0928\u094b\u0924\u093f \u0935\u091a\u0928\u093e\u0919\u094d\u0917\u092e\u093e\u0928\u0938\u0948-\n\u0938\u094d\u0924\u094d\u0935\u093e\u0902 \u092e\u0941\u0930\u093e\u0930\u093f\u0939\u0943\u0926\u092f\u0947\u0936\u094d\u0935\u0930\u0940\u0902 \u092d\u091c\u0947 \u0965 \u0967\u096d \u0965",
        iastText: "yatka\u1e6d\u0101k\u1e63asamup\u0101san\u0101vidhi\u1e25\ns\u0113vakasya sakal\u0101rthasampada\u1e25 \u0964\nsa\u1e41tan\u014dti vacan\u0101\u1e45gam\u0101nasai-\nstv\u0101\u1e41 mur\u0101rih\u1e5bday\u0113\u015bvar\u012b\u1e41 bhaj\u0113 \u0965 17 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c2f\u0c24\u0c4d\u0c15\u0c1f\u0c3e\u0c15\u0c4d\u0c37\u0c38\u0c2e\u0c41\u0c2a\u0c3e\u0c38\u0c28\u0c3e\u0c35\u0c3f\u0c27\u0c3f\u0c03\n\u0c38\u0c47\u0c35\u0c15\u0c38\u0c4d\u0c2f \u0c38\u0c15\u0c32\u0c3e\u0c30\u0c4d\u0c25\u0c38\u0c2e\u0c4d\u0c2a\u0c26\u0c03 \u0964\n\u0c38\u0c02\u0c24\u0c28\u0c4b\u0c24\u0c3f \u0c35\u0c1a\u0c28\u0c3e\u0c19\u0c4d\u0c17\u0c2e\u0c3e\u0c28\u0c38\u0c48-\n\u0c38\u0c4d\u0c24\u0c4d\u0c35\u0c3e\u0c02 \u0c2e\u0c41\u0c30\u0c3e\u0c30\u0c3f\u0c39\u0c43\u0c26\u0c2f\u0c47\u0c36\u0c4d\u0c35\u0c30\u0c40\u0c02 \u0c2d\u0c1c\u0c47 \u0965 \u0c67\u0c6d \u0965", "tamil": "\u0baf\u0ba4\u0bcd\u0b95\u0b9f\u0bbe\u0b95\u0bcd\u0bb7\u0bb8\u0bae\u0bc1\u0baa\u0bbe\u0bb8\u0ba8\u0bbe\u0bb5\u0bbf\u0ba4\u0bbf\u0b83\n\u0bb8\u0bc7\u0bb5\u0b95\u0bb8\u0bcd\u0baf \u0bb8\u0b95\u0bb2\u0bbe\u0bb0\u0bcd\u0ba4\u0bb8\u0bae\u0bcd\u0baa\u0ba4\u0b83 \u0964\n\u0bb8\u0bae\u0bcd\u0ba4\u0ba8\u0bcb\u0ba4\u0bbf \u0bb5\u0b9a\u0ba8\u0bbe\u0b99\u0bcd\u0b95\u0bae\u0bbe\u0ba8\u0bb8\u0bc8-\n\u0bb8\u0bcd\u0ba4\u0bcd\u0bb5\u0bbe\u0bae\u0bcd \u0bae\u0bc1\u0bb0\u0bbe\u0bb0\u0bbf\u0bb9\u0bcd\u0bb0\u0bc1'\u0ba4\u0baf\u0bc7\u0bb6\u0bcd\u0bb5\u0bb0\u0bc0\u0bae\u0bcd \u0baa\u0b9c\u0bc7 \u0965 \u0be7\u0bed \u0965", "kannada": "\u0caf\u0ca4\u0ccd\u0c95\u0c9f\u0cbe\u0c95\u0ccd\u0cb7\u0cb8\u0cae\u0cc1\u0caa\u0cbe\u0cb8\u0ca8\u0cbe\u0cb5\u0cbf\u0ca7\u0cbf\u0c83\n\u0cb8\u0cc7\u0cb5\u0c95\u0cb8\u0ccd\u0caf \u0cb8\u0c95\u0cb2\u0cbe\u0cb0\u0ccd\u0ca5\u0cb8\u0cae\u0ccd\u0caa\u0ca6\u0c83 \u0964\n\u0cb8\u0c82\u0ca4\u0ca8\u0ccb\u0ca4\u0cbf \u0cb5\u0c9a\u0ca8\u0cbe\u0c99\u0ccd\u0c97\u0cae\u0cbe\u0ca8\u0cb8\u0cc8-\n\u0cb8\u0ccd\u0ca4\u0ccd\u0cb5\u0cbe\u0c82 \u0cae\u0cc1\u0cb0\u0cbe\u0cb0\u0cbf\u0cb9\u0cc3\u0ca6\u0caf\u0cc7\u0cb6\u0ccd\u0cb5\u0cb0\u0cc0\u0c82 \u0cad\u0c9c\u0cc7 \u0965 \u0ce7\u0ced \u0965", "malayalam": "\u0d2f\u0d24\u0d4d\u0d15\u0d1f\u0d3e\u0d15\u0d4d\u0d37\u0d38\u0d2e\u0d41\u0d2a\u0d3e\u0d38\u0d28\u0d3e\u0d35\u0d3f\u0d27\u0d3f\u0d03\n\u0d38\u0d47\u0d35\u0d15\u0d38\u0d4d\u0d2f \u0d38\u0d15\u0d32\u0d3e\u0d30\u0d4d\u0d25\u0d38\u0d2e\u0d4d\u0d2a\u0d26\u0d03 \u0964\n\u0d38\u0d02\u0d24\u0d28\u0d4b\u0d24\u0d3f \u0d35\u0d1a\u0d28\u0d3e\u0d19\u0d4d\u0d17\u0d2e\u0d3e\u0d28\u0d38\u0d48-\n\u0d38\u0d4d\u0d24\u0d4d\u0d35\u0d3e\u0d02 \u0d2e\u0d41\u0d30\u0d3e\u0d30\u0d3f\u0d39\u0d43\u0d26\u0d2f\u0d47\u0d36\u0d4d\u0d35\u0d30\u0d40\u0d02 \u0d2d\u0d1c\u0d47 \u0965 \u0d67\u0d6d \u0965", "iast": "yatka\u1e6d\u0101k\u1e63asamup\u0101san\u0101vidhi\u1e25\nsevakasya sakal\u0101rthasampada\u1e25 |\nsa\u1e43tanoti vacan\u0101\u1e45gam\u0101nasai-\nstv\u0101\u1e43 mur\u0101rih\u1e5bdaye\u015bvar\u012b\u1e43 bhaje || 17 ||"},
        draftTranslation: "By the contemplation of whose compassionate glance all fourfold aims of life blossom for the servant \u2014 unto You, Empress of Murari's heart, I offer worship through word, body, and mind!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 18,
        devanagariText: "\u0938\u0930\u0938\u093f\u091c\u0928\u093f\u0932\u092f\u0947 \u0938\u0930\u094b\u091c\u0939\u0938\u094d\u0924\u0947\n\u0927\u0935\u0932\u0924\u092e\u093e\u0902\u0936\u0941\u0915\u0917\u0928\u094d\u0927\u092e\u093e\u0932\u094d\u092f\u0936\u094b\u092d\u0947 \u0964\n\u092d\u0917\u0935\u0924\u093f \u0939\u0930\u093f\u0935\u0932\u094d\u0932\u092d\u0947 \u092e\u0928\u094b\u091c\u094d\u091e\u0947\n\u0924\u094d\u0930\u093f\u092d\u0941\u0935\u0928\u092d\u0942\u0924\u093f\u0915\u0930\u093f \u092a\u094d\u0930\u0938\u0940\u0926 \u092e\u0939\u094d\u092f\u092e\u094d \u0965 \u0967\u096e \u0965",
        iastText: "sarasijanilay\u0113 sar\u014djahast\u0113\ndhavalatam\u0101\u1e41\u015bukagandham\u0101lya\u015b\u014dbh\u0113 \u0964\nbhagavati harivallabh\u0113 man\u014dj\u00f1\u0113\ntribhuvanabh\u016btikari pras\u012bda mahyam \u0965 18 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c38\u0c30\u0c38\u0c3f\u0c1c\u0c28\u0c3f\u0c32\u0c2f\u0c47 \u0c38\u0c30\u0c4b\u0c1c\u0c39\u0c38\u0c4d\u0c24\u0c47\n\u0c27\u0c35\u0c32\u0c24\u0c2e\u0c3e\u0c02\u0c36\u0c41\u0c15\u0c17\u0c28\u0c4d\u0c27\u0c2e\u0c3e\u0c32\u0c4d\u0c2f\u0c36\u0c4b\u0c2d\u0c47 \u0964\n\u0c2d\u0c17\u0c35\u0c24\u0c3f \u0c39\u0c30\u0c3f\u0c35\u0c32\u0c4d\u0c32\u0c2d\u0c47 \u0c2e\u0c28\u0c4b\u0c1c\u0c4d\u0c1e\u0c47\n\u0c24\u0c4d\u0c30\u0c3f\u0c2d\u0c41\u0c35\u0c28\u0c2d\u0c42\u0c24\u0c3f\u0c15\u0c30\u0c3f \u0c2a\u0c4d\u0c30\u0c38\u0c40\u0c26 \u0c2e\u0c39\u0c4d\u0c2f\u0c2e\u0c4d \u0965 \u0c67\u0c6e \u0965", "tamil": "\u0bb8\u0bb0\u0bb8\u0bbf\u0b9c\u0ba8\u0bbf\u0bb2\u0baf\u0bc7 \u0bb8\u0bb0\u0bcb\u0b9c\u0bb9\u0bb8\u0bcd\u0ba4\u0bc7\n\u0ba4\u0bb5\u0bb2\u0ba4\u0bae\u0bbe\u0bae\u0bcd\u0bb6\u0bc1\u0b95\u0b95\u0ba8\u0bcd\u0ba4\u0bae\u0bbe\u0bb2\u0bcd\u0baf\u0bb6\u0bcb\u0baa\u0bc7 \u0964\n\u0baa\u0b95\u0bb5\u0ba4\u0bbf \u0bb9\u0bb0\u0bbf\u0bb5\u0bb2\u0bcd\u0bb2\u0baa\u0bc7 \u0bae\u0ba8\u0bcb\u0b9c\u0bcd\u0b9e\u0bc7\n\u0ba4\u0bcd\u0bb0\u0bbf\u0baa\u0bc1\u0bb5\u0ba8\u0baa\u0bc2\u0ba4\u0bbf\u0b95\u0bb0\u0bbf \u0baa\u0bcd\u0bb0\u0bb8\u0bc0\u0ba4 \u0bae\u0bb9\u0bcd\u0baf\u0bae\u0bcd \u0965 \u0be7\u0bee \u0965", "kannada": "\u0cb8\u0cb0\u0cb8\u0cbf\u0c9c\u0ca8\u0cbf\u0cb2\u0caf\u0cc7 \u0cb8\u0cb0\u0ccb\u0c9c\u0cb9\u0cb8\u0ccd\u0ca4\u0cc7\n\u0ca7\u0cb5\u0cb2\u0ca4\u0cae\u0cbe\u0c82\u0cb6\u0cc1\u0c95\u0c97\u0ca8\u0ccd\u0ca7\u0cae\u0cbe\u0cb2\u0ccd\u0caf\u0cb6\u0ccb\u0cad\u0cc7 \u0964\n\u0cad\u0c97\u0cb5\u0ca4\u0cbf \u0cb9\u0cb0\u0cbf\u0cb5\u0cb2\u0ccd\u0cb2\u0cad\u0cc7 \u0cae\u0ca8\u0ccb\u0c9c\u0ccd\u0c9e\u0cc7\n\u0ca4\u0ccd\u0cb0\u0cbf\u0cad\u0cc1\u0cb5\u0ca8\u0cad\u0cc2\u0ca4\u0cbf\u0c95\u0cb0\u0cbf \u0caa\u0ccd\u0cb0\u0cb8\u0cc0\u0ca6 \u0cae\u0cb9\u0ccd\u0caf\u0cae\u0ccd \u0965 \u0ce7\u0cee \u0965", "malayalam": "\u0d38\u0d30\u0d38\u0d3f\u0d1c\u0d28\u0d3f\u0d32\u0d2f\u0d47 \u0d38\u0d30\u0d4b\u0d1c\u0d39\u0d38\u0d4d\u0d24\u0d47\n\u0d27\u0d35\u0d32\u0d24\u0d2e\u0d3e\u0d02\u0d36\u0d41\u0d15\u0d17\u0d28\u0d4d\u0d27\u0d2e\u0d3e\u0d32\u0d4d\u0d2f\u0d36\u0d4b\u0d2d\u0d47 \u0964\n\u0d2d\u0d17\u0d35\u0d24\u0d3f \u0d39\u0d30\u0d3f\u0d35\u0d32\u0d4d\u0d32\u0d2d\u0d47 \u0d2e\u0d28\u0d4b\u0d1c\u0d4d\u0d1e\u0d47\n\u0d24\u0d4d\u0d30\u0d3f\u0d2d\u0d41\u0d35\u0d28\u0d2d\u0d42\u0d24\u0d3f\u0d15\u0d30\u0d3f \u0d2a\u0d4d\u0d30\u0d38\u0d40\u0d26 \u0d2e\u0d39\u0d4d\u0d2f\u0d2e\u0d4d \u0965 \u0d67\u0d6e \u0965", "iast": "sarasijanilaye sarojahaste\ndhavalatam\u0101\u1e43\u015bukagandham\u0101lya\u015bobhe |\nbhagavati harivallabhe manoj\u00f1e\ntribhuvanabh\u016btikari pras\u012bda mahyam || 18 ||"},
        draftTranslation: "Dwelling in the lotus, holding lotuses in Your hands, dazzling in pristine white robes, fragrant with celestial garlands, adorable consort of Hari, conferring fortune on all three worlds \u2014 O Divine Mother, be merciful unto me!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 19,
        devanagariText: "\u0926\u093f\u0919\u094d\u0918\u0938\u094d\u0924\u093f\u092d\u093f\u0903 \u0915\u0928\u0915\u0915\u0941\u092e\u094d\u092d\u092e\u0941\u0916\u093e\u0935\u0938\u0943\u0937\u094d\u091f-\n\u0938\u094d\u0935\u0930\u094d\u0935\u093e\u0939\u093f\u0928\u0940\u0935\u093f\u092e\u0932\u091a\u093e\u0930\u0941\u091c\u0932\u092a\u094d\u0932\u0941\u0924\u093e\u0919\u094d\u0917\u0940\u092e\u094d \u0964\n\u092a\u094d\u0930\u093e\u0924\u0930\u094d\u0928\u092e\u093e\u092e\u093f \u091c\u0917\u0924\u093e\u0902 \u091c\u0928\u0928\u0940\u092e\u0936\u0947\u0937-\n\u0932\u094b\u0915\u093e\u0927\u093f\u0928\u093e\u0925\u0917\u0943\u0939\u093f\u0923\u0940\u092e\u092e\u0943\u0924\u093e\u092c\u094d\u0927\u093f\u092a\u0941\u0924\u094d\u0930\u0940\u092e\u094d \u0965 \u0967\u096f \u0965",
        iastText: "di\u1e45ghastibhi\u1e25 kanakakumbhamukh\u0101vas\u1e5b\u1e63\u1e6da-\nsvarv\u0101hin\u012bvimalac\u0101rujalaplut\u0101\u1e45g\u012bm \u0964\npr\u0101tarnam\u0101mi jagat\u0101\u1e41 janan\u012bma\u015b\u0113\u1e63a-\nl\u014dk\u0101dhin\u0101thag\u1e5bhi\u1e47\u012bmam\u1e5bt\u0101bdhiputr\u012bm \u0965 19 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c26\u0c3f\u0c19\u0c4d\u0c18\u0c38\u0c4d\u0c24\u0c3f\u0c2d\u0c3f\u0c03 \u0c15\u0c28\u0c15\u0c15\u0c41\u0c2e\u0c4d\u0c2d\u0c2e\u0c41\u0c16\u0c3e\u0c35\u0c38\u0c43\u0c37\u0c4d\u0c1f-\n\u0c38\u0c4d\u0c35\u0c30\u0c4d\u0c35\u0c3e\u0c39\u0c3f\u0c28\u0c40\u0c35\u0c3f\u0c2e\u0c32\u0c1a\u0c3e\u0c30\u0c41\u0c1c\u0c32\u0c2a\u0c4d\u0c32\u0c41\u0c24\u0c3e\u0c19\u0c4d\u0c17\u0c40\u0c2e\u0c4d \u0964\n\u0c2a\u0c4d\u0c30\u0c3e\u0c24\u0c30\u0c4d\u0c28\u0c2e\u0c3e\u0c2e\u0c3f \u0c1c\u0c17\u0c24\u0c3e\u0c02 \u0c1c\u0c28\u0c28\u0c40\u0c2e\u0c36\u0c47\u0c37-\n\u0c32\u0c4b\u0c15\u0c3e\u0c27\u0c3f\u0c28\u0c3e\u0c25\u0c17\u0c43\u0c39\u0c3f\u0c23\u0c40\u0c2e\u0c2e\u0c43\u0c24\u0c3e\u0c2c\u0c4d\u0c27\u0c3f\u0c2a\u0c41\u0c24\u0c4d\u0c30\u0c40\u0c2e\u0c4d \u0965 \u0c67\u0c6f \u0965", "tamil": "\u0ba4\u0bbf\u0b99\u0bcd\u0b95\u0bb8\u0bcd\u0ba4\u0bbf\u0baa\u0bbf\u0b83 \u0b95\u0ba8\u0b95\u0b95\u0bc1\u0bae\u0bcd\u0baa\u0bae\u0bc1\u0b95\u0bbe\u0bb5\u0bb8\u0bcd\u0bb0\u0bc1'\u0bb7\u0bcd\u0b9f-\n\u0bb8\u0bcd\u0bb5\u0bb0\u0bcd\u0bb5\u0bbe\u0bb9\u0bbf\u0ba8\u0bc0\u0bb5\u0bbf\u0bae\u0bb2\u0b9a\u0bbe\u0bb0\u0bc1\u0b9c\u0bb2\u0baa\u0bcd\u0bb2\u0bc1\u0ba4\u0bbe\u0b99\u0bcd\u0b95\u0bc0\u0bae\u0bcd \u0964\n\u0baa\u0bcd\u0bb0\u0bbe\u0ba4\u0bb0\u0bcd\u0ba8\u0bae\u0bbe\u0bae\u0bbf \u0b9c\u0b95\u0ba4\u0bbe\u0bae\u0bcd \u0b9c\u0ba8\u0ba8\u0bc0\u0bae\u0bb6\u0bc7\u0bb7-\n\u0bb2\u0bcb\u0b95\u0bbe\u0ba4\u0bbf\u0ba8\u0bbe\u0ba4\u0b95\u0bcd\u0bb0\u0bc1'\u0bb9\u0bbf\u0ba3\u0bc0\u0bae\u0bae\u0bcd\u0bb0\u0bc1'\u0ba4\u0bbe\u0baa\u0bcd\u0ba4\u0bbf\u0baa\u0bc1\u0ba4\u0bcd\u0bb0\u0bc0\u0bae\u0bcd \u0965 \u0be7\u0bef \u0965", "kannada": "\u0ca6\u0cbf\u0c99\u0ccd\u0c98\u0cb8\u0ccd\u0ca4\u0cbf\u0cad\u0cbf\u0c83 \u0c95\u0ca8\u0c95\u0c95\u0cc1\u0cae\u0ccd\u0cad\u0cae\u0cc1\u0c96\u0cbe\u0cb5\u0cb8\u0cc3\u0cb7\u0ccd\u0c9f-\n\u0cb8\u0ccd\u0cb5\u0cb0\u0ccd\u0cb5\u0cbe\u0cb9\u0cbf\u0ca8\u0cc0\u0cb5\u0cbf\u0cae\u0cb2\u0c9a\u0cbe\u0cb0\u0cc1\u0c9c\u0cb2\u0caa\u0ccd\u0cb2\u0cc1\u0ca4\u0cbe\u0c99\u0ccd\u0c97\u0cc0\u0cae\u0ccd \u0964\n\u0caa\u0ccd\u0cb0\u0cbe\u0ca4\u0cb0\u0ccd\u0ca8\u0cae\u0cbe\u0cae\u0cbf \u0c9c\u0c97\u0ca4\u0cbe\u0c82 \u0c9c\u0ca8\u0ca8\u0cc0\u0cae\u0cb6\u0cc7\u0cb7-\n\u0cb2\u0ccb\u0c95\u0cbe\u0ca7\u0cbf\u0ca8\u0cbe\u0ca5\u0c97\u0cc3\u0cb9\u0cbf\u0ca3\u0cc0\u0cae\u0cae\u0cc3\u0ca4\u0cbe\u0cac\u0ccd\u0ca7\u0cbf\u0caa\u0cc1\u0ca4\u0ccd\u0cb0\u0cc0\u0cae\u0ccd \u0965 \u0ce7\u0cef \u0965", "malayalam": "\u0d26\u0d3f\u0d19\u0d4d\u0d18\u0d38\u0d4d\u0d24\u0d3f\u0d2d\u0d3f\u0d03 \u0d15\u0d28\u0d15\u0d15\u0d41\u0d2e\u0d4d\u0d2d\u0d2e\u0d41\u0d16\u0d3e\u0d35\u0d38\u0d43\u0d37\u0d4d\u0d1f-\n\u0d38\u0d4d\u0d35\u0d30\u0d4d\u0d35\u0d3e\u0d39\u0d3f\u0d28\u0d40\u0d35\u0d3f\u0d2e\u0d32\u0d1a\u0d3e\u0d30\u0d41\u0d1c\u0d32\u0d2a\u0d4d\u0d32\u0d41\u0d24\u0d3e\u0d19\u0d4d\u0d17\u0d40\u0d2e\u0d4d \u0964\n\u0d2a\u0d4d\u0d30\u0d3e\u0d24\u0d30\u0d4d\u0d28\u0d2e\u0d3e\u0d2e\u0d3f \u0d1c\u0d17\u0d24\u0d3e\u0d02 \u0d1c\u0d28\u0d28\u0d40\u0d2e\u0d36\u0d47\u0d37-\n\u0d32\u0d4b\u0d15\u0d3e\u0d27\u0d3f\u0d28\u0d3e\u0d25\u0d17\u0d43\u0d39\u0d3f\u0d23\u0d40\u0d2e\u0d2e\u0d43\u0d24\u0d3e\u0d2c\u0d4d\u0d27\u0d3f\u0d2a\u0d41\u0d24\u0d4d\u0d30\u0d40\u0d2e\u0d4d \u0965 \u0d67\u0d6f \u0965", "iast": "di\u1e45ghastibhi\u1e25 kanakakumbhamukh\u0101vas\u1e5b\u1e63\u1e6da-\nsvarv\u0101hin\u012bvimalac\u0101rujalaplut\u0101\u1e45g\u012bm |\npr\u0101tarnam\u0101mi jagat\u0101\u1e43 janan\u012bma\u015be\u1e63a-\nlok\u0101dhin\u0101thag\u1e5bhi\u1e47\u012bmam\u1e5bt\u0101bdhiputr\u012bm || 19 ||"},
        draftTranslation: "Bathed in the pure waters of the celestial Ganga poured from golden jars held by guardian elephants of the quarters, at dawn I bow down to the Mother of all worlds, queen of the Sovereign of the universe, daughter of the ocean of immortality!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 20,
        devanagariText: "\u0915\u092e\u0932\u0947 \u0915\u092e\u0932\u093e\u0935\u0924\u093e\u0915\u094d\u0937\u0915\u093e\u0928\u094d\u0924\u0947\n\u0915\u0930\u0941\u0923\u093e\u092a\u0942\u0930\u0924\u0930\u0919\u094d\u0917\u093f\u0924\u0948\u0930\u092a\u093e\u0919\u094d\u0917\u0948\u0903 \u0964\n\u0905\u0935\u0932\u094b\u0915\u092f \u092e\u093e\u092e\u0915\u093f\u091e\u094d\u091a\u0928\u093e\u0928\u093e\u0902\n\u092a\u094d\u0930\u0925\u092e\u0902 \u092d\u0915\u094d\u0924\u093f\u092e\u092d\u0915\u094d\u0924\u093f\u0939\u0940\u0928\u0928\u0947\u0924\u094d\u0930\u0947 \u0965 \u0968\u0966 \u0965",
        iastText: "kamal\u0113 kamal\u0101vat\u0101k\u1e63ak\u0101nt\u0113\nkaru\u1e47\u0101p\u016bratara\u1e45gitairap\u0101\u1e45gai\u1e25 \u0964\naval\u014dkaya m\u0101maki\u00f1can\u0101n\u0101\u1e41\nprathama\u1e41 bhaktimabaktih\u012bnan\u0113tr\u0113 \u0965 20 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c15\u0c2e\u0c32\u0c47 \u0c15\u0c2e\u0c32\u0c3e\u0c35\u0c24\u0c3e\u0c15\u0c4d\u0c37\u0c15\u0c3e\u0c28\u0c4d\u0c24\u0c47\n\u0c15\u0c30\u0c41\u0c23\u0c3e\u0c2a\u0c42\u0c30\u0c24\u0c30\u0c19\u0c4d\u0c17\u0c3f\u0c24\u0c48\u0c30\u0c2a\u0c3e\u0c19\u0c4d\u0c17\u0c48\u0c03 \u0964\n\u0c05\u0c35\u0c32\u0c4b\u0c15\u0c2f \u0c2e\u0c3e\u0c2e\u0c15\u0c3f\u0c1e\u0c4d\u0c1a\u0c28\u0c3e\u0c28\u0c3e\u0c02\n\u0c2a\u0c4d\u0c30\u0c25\u0c2e\u0c02 \u0c2d\u0c15\u0c4d\u0c24\u0c3f\u0c2e\u0c2d\u0c15\u0c4d\u0c24\u0c3f\u0c39\u0c40\u0c28\u0c28\u0c47\u0c24\u0c4d\u0c30\u0c47 \u0965 \u0c68\u0c66 \u0965", "tamil": "\u0b95\u0bae\u0bb2\u0bc7 \u0b95\u0bae\u0bb2\u0bbe\u0bb5\u0ba4\u0bbe\u0b95\u0bcd\u0bb7\u0b95\u0bbe\u0ba8\u0bcd\u0ba4\u0bc7\n\u0b95\u0bb0\u0bc1\u0ba3\u0bbe\u0baa\u0bc2\u0bb0\u0ba4\u0bb0\u0b99\u0bcd\u0b95\u0bbf\u0ba4\u0bc8\u0bb0\u0baa\u0bbe\u0b99\u0bcd\u0b95\u0bc8\u0b83 \u0964\n\u0b85\u0bb5\u0bb2\u0bcb\u0b95\u0baf \u0bae\u0bbe\u0bae\u0b95\u0bbf\u0b9e\u0bcd\u0b9a\u0ba8\u0bbe\u0ba8\u0bbe\u0bae\u0bcd\n\u0baa\u0bcd\u0bb0\u0ba4\u0bae\u0bae\u0bcd \u0baa\u0b95\u0bcd\u0ba4\u0bbf\u0bae\u0baa\u0b95\u0bcd\u0ba4\u0bbf\u0bb9\u0bc0\u0ba8\u0ba8\u0bc7\u0ba4\u0bcd\u0bb0\u0bc7 \u0965 \u0be8\u0be6 \u0965", "kannada": "\u0c95\u0cae\u0cb2\u0cc7 \u0c95\u0cae\u0cb2\u0cbe\u0cb5\u0ca4\u0cbe\u0c95\u0ccd\u0cb7\u0c95\u0cbe\u0ca8\u0ccd\u0ca4\u0cc7\n\u0c95\u0cb0\u0cc1\u0ca3\u0cbe\u0caa\u0cc2\u0cb0\u0ca4\u0cb0\u0c99\u0ccd\u0c97\u0cbf\u0ca4\u0cc8\u0cb0\u0caa\u0cbe\u0c99\u0ccd\u0c97\u0cc8\u0c83 \u0964\n\u0c85\u0cb5\u0cb2\u0ccb\u0c95\u0caf \u0cae\u0cbe\u0cae\u0c95\u0cbf\u0c9e\u0ccd\u0c9a\u0ca8\u0cbe\u0ca8\u0cbe\u0c82\n\u0caa\u0ccd\u0cb0\u0ca5\u0cae\u0c82 \u0cad\u0c95\u0ccd\u0ca4\u0cbf\u0cae\u0cad\u0c95\u0ccd\u0ca4\u0cbf\u0cb9\u0cc0\u0ca8\u0ca8\u0cc7\u0ca4\u0ccd\u0cb0\u0cc7 \u0965 \u0ce8\u0ce6 \u0965", "malayalam": "\u0d15\u0d2e\u0d32\u0d47 \u0d15\u0d2e\u0d32\u0d3e\u0d35\u0d24\u0d3e\u0d15\u0d4d\u0d37\u0d15\u0d3e\u0d28\u0d4d\u0d24\u0d47\n\u0d15\u0d30\u0d41\u0d23\u0d3e\u0d2a\u0d42\u0d30\u0d24\u0d30\u0d19\u0d4d\u0d17\u0d3f\u0d24\u0d48\u0d30\u0d2a\u0d3e\u0d19\u0d4d\u0d17\u0d48\u0d03 \u0964\n\u0d05\u0d35\u0d32\u0d4b\u0d15\u0d2f \u0d2e\u0d3e\u0d2e\u0d15\u0d3f\u0d1e\u0d4d\u0d1a\u0d28\u0d3e\u0d28\u0d3e\u0d02\n\u0d2a\u0d4d\u0d30\u0d25\u0d2e\u0d02 \u0d2d\u0d15\u0d4d\u0d24\u0d3f\u0d2e\u0d2d\u0d15\u0d4d\u0d24\u0d3f\u0d39\u0d40\u0d28\u0d28\u0d47\u0d24\u0d4d\u0d30\u0d47 \u0965 \u0d68\u0d66 \u0965", "iast": "kamale kamal\u0101vat\u0101k\u1e63ak\u0101nte\nkaru\u1e47\u0101p\u016bratara\u1e45gitairap\u0101\u1e45gai\u1e25 |\navalokaya m\u0101maki\u00f1can\u0101n\u0101\u1e43\nprathama\u1e43 bhaktimabhaktih\u012bnanetre || 20 ||"},
        draftTranslation: "O Kamala! Beloved of the broad lotus-eyed Lord! With sidelong glances undulating like waves in an ocean of boundless compassion, look upon me, foremost among the destitute, O Mother whose eyes beam on sincere devotion!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 21,
        devanagariText: "\u0938\u094d\u0924\u0941\u0935\u0928\u094d\u0924\u093f \u092f\u0947 \u0938\u094d\u0924\u0941\u0924\u093f\u092d\u093f\u0930\u092e\u0940\u092d\u093f\u0930\u0928\u094d\u0935\u0939\u0902\n\u0924\u094d\u0930\u092f\u0940\u092e\u092f\u0940\u0902 \u0924\u094d\u0930\u093f\u092d\u0941\u0935\u0928\u092e\u093e\u0924\u0930\u0902 \u0930\u092e\u093e\u092e\u094d \u0964\n\u0917\u0941\u0923\u093e\u0927\u093f\u0915\u093e \u0917\u0941\u0930\u0941\u0924\u0930\u092d\u093e\u0917\u094d\u092f\u092d\u093e\u0917\u093f\u0928\u094b\n\u092d\u0935\u0928\u094d\u0924\u093f \u0924\u0947 \u092d\u0941\u0935\u093f \u092c\u0941\u0927\u092d\u093e\u0935\u093f\u0924\u093e\u0936\u092f\u093e\u0903 \u0965 \u0968\u0967 \u0965",
        iastText: "stuvanti y\u0113 stutibhiram\u012bbhiranvaha\u1e41\ntray\u012bmay\u012b\u1e41 tribhuvanam\u0101tara\u1e41 ram\u0101m \u0964\ngu\u1e47\u0101dhik\u0101 gurutarabh\u0101gyabh\u0101gin\u014d\nbhavanti t\u0113 bhuvi budhabh\u0101vit\u0101\u015bay\u0101\u1e25 \u0965 21 \u0965",
        meter: "Vasantatilaka",
        transliterations: {"telugu": "\u0c38\u0c4d\u0c24\u0c41\u0c35\u0c28\u0c4d\u0c24\u0c3f \u0c2f\u0c47 \u0c38\u0c4d\u0c24\u0c41\u0c24\u0c3f\u0c2d\u0c3f\u0c30\u0c2e\u0c40\u0c2d\u0c3f\u0c30\u0c28\u0c4d\u0c35\u0c39\u0c02\n\u0c24\u0c4d\u0c30\u0c2f\u0c40\u0c2e\u0c2f\u0c40\u0c02 \u0c24\u0c4d\u0c30\u0c3f\u0c2d\u0c41\u0c35\u0c28\u0c2e\u0c3e\u0c24\u0c30\u0c02 \u0c30\u0c2e\u0c3e\u0c2e\u0c4d \u0964\n\u0c17\u0c41\u0c23\u0c3e\u0c27\u0c3f\u0c15\u0c3e \u0c17\u0c41\u0c30\u0c41\u0c24\u0c30\u0c2d\u0c3e\u0c17\u0c4d\u0c2f\u0c2d\u0c3e\u0c17\u0c3f\u0c28\u0c4b\n\u0c2d\u0c35\u0c28\u0c4d\u0c24\u0c3f \u0c24\u0c47 \u0c2d\u0c41\u0c35\u0c3f \u0c2c\u0c41\u0c27\u0c2d\u0c3e\u0c35\u0c3f\u0c24\u0c3e\u0c36\u0c2f\u0c3e\u0c03 \u0965 \u0c68\u0c67 \u0965", "tamil": "\u0bb8\u0bcd\u0ba4\u0bc1\u0bb5\u0ba8\u0bcd\u0ba4\u0bbf \u0baf\u0bc7 \u0bb8\u0bcd\u0ba4\u0bc1\u0ba4\u0bbf\u0baa\u0bbf\u0bb0\u0bae\u0bc0\u0baa\u0bbf\u0bb0\u0ba8\u0bcd\u0bb5\u0bb9\u0bae\u0bcd\n\u0ba4\u0bcd\u0bb0\u0baf\u0bc0\u0bae\u0baf\u0bc0\u0bae\u0bcd \u0ba4\u0bcd\u0bb0\u0bbf\u0baa\u0bc1\u0bb5\u0ba8\u0bae\u0bbe\u0ba4\u0bb0\u0bae\u0bcd \u0bb0\u0bae\u0bbe\u0bae\u0bcd \u0964\n\u0b95\u0bc1\u0ba3\u0bbe\u0ba4\u0bbf\u0b95\u0bbe \u0b95\u0bc1\u0bb0\u0bc1\u0ba4\u0bb0\u0baa\u0bbe\u0b95\u0bcd\u0baf\u0baa\u0bbe\u0b95\u0bbf\u0ba8\u0bcb\n\u0baa\u0bb5\u0ba8\u0bcd\u0ba4\u0bbf \u0ba4\u0bc7 \u0baa\u0bc1\u0bb5\u0bbf \u0baa\u0bc1\u0ba4\u0baa\u0bbe\u0bb5\u0bbf\u0ba4\u0bbe\u0bb6\u0baf\u0bbe\u0b83 \u0965 \u0be8\u0be7 \u0965", "kannada": "\u0cb8\u0ccd\u0ca4\u0cc1\u0cb5\u0ca8\u0ccd\u0ca4\u0cbf \u0caf\u0cc7 \u0cb8\u0ccd\u0ca4\u0cc1\u0ca4\u0cbf\u0cad\u0cbf\u0cb0\u0cae\u0cc0\u0cad\u0cbf\u0cb0\u0ca8\u0ccd\u0cb5\u0cb9\u0c82\n\u0ca4\u0ccd\u0cb0\u0caf\u0cc0\u0cae\u0caf\u0cc0\u0c82 \u0ca4\u0ccd\u0cb0\u0cbf\u0cad\u0cc1\u0cb5\u0ca8\u0cae\u0cbe\u0ca4\u0cb0\u0c82 \u0cb0\u0cae\u0cbe\u0cae\u0ccd \u0964\n\u0c97\u0cc1\u0ca3\u0cbe\u0ca7\u0cbf\u0c95\u0cbe \u0c97\u0cc1\u0cb0\u0cc1\u0ca4\u0cb0\u0cad\u0cbe\u0c97\u0ccd\u0caf\u0cad\u0cbe\u0c97\u0cbf\u0ca8\u0ccb\n\u0cad\u0cb5\u0ca8\u0ccd\u0ca4\u0cbf \u0ca4\u0cc7 \u0cad\u0cc1\u0cb5\u0cbf \u0cac\u0cc1\u0ca7\u0cad\u0cbe\u0cb5\u0cbf\u0ca4\u0cbe\u0cb6\u0caf\u0cbe\u0c83 \u0965 \u0ce8\u0ce7 \u0965", "malayalam": "\u0d38\u0d4d\u0d24\u0d41\u0d35\u0d28\u0d4d\u0d24\u0d3f \u0d2f\u0d47 \u0d38\u0d4d\u0d24\u0d41\u0d24\u0d3f\u0d2d\u0d3f\u0d30\u0d2e\u0d40\u0d2d\u0d3f\u0d30\u0d28\u0d4d\u0d35\u0d39\u0d02\n\u0d24\u0d4d\u0d30\u0d2f\u0d40\u0d2e\u0d2f\u0d40\u0d02 \u0d24\u0d4d\u0d30\u0d3f\u0d2d\u0d41\u0d35\u0d28\u0d2e\u0d3e\u0d24\u0d30\u0d02 \u0d30\u0d2e\u0d3e\u0d2e\u0d4d \u0964\n\u0d17\u0d41\u0d23\u0d3e\u0d27\u0d3f\u0d15\u0d3e \u0d17\u0d41\u0d30\u0d41\u0d24\u0d30\u0d2d\u0d3e\u0d17\u0d4d\u0d2f\u0d2d\u0d3e\u0d17\u0d3f\u0d28\u0d4b\n\u0d2d\u0d35\u0d28\u0d4d\u0d24\u0d3f \u0d24\u0d47 \u0d2d\u0d41\u0d35\u0d3f \u0d2c\u0d41\u0d27\u0d2d\u0d3e\u0d35\u0d3f\u0d24\u0d3e\u0d36\u0d2f\u0d3e\u0d03 \u0965 \u0d68\u0d67 \u0965", "iast": "stuvanti ye stutibhiram\u012bbhiranvaha\u1e43\ntray\u012bmay\u012b\u1e43 tribhuvanam\u0101tara\u1e43 ram\u0101m |\ngu\u1e47\u0101dhik\u0101 gurutarabh\u0101gyabh\u0101gino\nbhavanti te bhuvi budhabh\u0101vit\u0101\u015bay\u0101\u1e25 || 21 ||"},
        draftTranslation: "Those who daily praise Rama (Lakshmi), the embodiment of the three Vedas, the Mother of the three worlds, with these hymns of praise \u2014 they become endowed with noble virtues, inherit immense fortune, and are honored by the wise across the earth!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
    ],
  ),
  Scripture(
    id: 22,
    contentId: "VEDA-TXT-00019",
    canonicalTitle: "Mahishasura Mardini Stotram",
    devanagariTitle: "\u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f\u0938\u094d\u0924\u094b\u0924\u094d\u0930\u092e\u094d",
    category: "Stotra",
    deity: "Goddess Durga",
    composer: "Adi Shankaracharya / Traditional",
    rishi: "Traditional Vedic Sage",
    chandas: "Dandaka-Rhythmic",
    devata: "Goddess Durga",
    sourceScripture: "Devi Mahatmya / Shakta Stotra Samgraha",
    traditionalUsage: "Victory over negative forces, inner strength, protection, Mahishasuramardini Upasana",
    verseCount: 21,
    verses: [
      Verse(
        verseNumber: 1,
        devanagariText: "\u0905\u092f\u093f \u0917\u093f\u0930\u093f\u0928\u0928\u094d\u0926\u093f\u0928\u093f \u0928\u0928\u094d\u0926\u093f\u0924\u092e\u0947\u0926\u093f\u0928\u093f \u0935\u093f\u0936\u094d\u0935\u0935\u093f\u0928\u094b\u0926\u093f\u0928\u093f \u0928\u0928\u094d\u0926\u093f\u0928\u0941\u0924\u0947\n\u0917\u093f\u0930\u093f\u0935\u0930\u0935\u093f\u0928\u094d\u0927\u094d\u092f\u0936\u093f\u0930\u094b\u093d\u0927\u093f\u0928\u093f\u0935\u093e\u0938\u093f\u0928\u093f \u0935\u093f\u0937\u094d\u0923\u0941\u0935\u093f\u0932\u093e\u0938\u093f\u0928\u093f \u091c\u093f\u0937\u094d\u0923\u0941\u0928\u0941\u0924\u0947 \u0964\n\u092d\u0917\u0935\u0924\u093f \u0939\u0947 \u0936\u093f\u0924\u093f\u0915\u0923\u094d\u0920\u0915\u0941\u091f\u0941\u092e\u094d\u092c\u093f\u0928\u093f \u092d\u0942\u0930\u093f\u0915\u0941\u091f\u0941\u092e\u094d\u092c\u093f\u0928\u093f \u092d\u0942\u0930\u093f\u0915\u0943\u0924\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0967 \u0965",
        iastText: "ayi girinandini nanditam\u0113dini vi\u015bvavin\u014ddini nandinut\u0113\ngirivaravindhya\u015bir\u014d'dhiniv\u0101sini vi\u1e63\u1e47uvil\u0101sini ji\u1e63\u1e47unut\u0113 \u0964\nbhagavati h\u0113 \u015bitika\u1e47\u1e6dhaku\u1e6dumbini bh\u016briku\u1e6dumbini bh\u016brik\u1e5bt\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 1 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c05\u0c2f\u0c3f \u0c17\u0c3f\u0c30\u0c3f\u0c28\u0c28\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c28\u0c28\u0c4d\u0c26\u0c3f\u0c24\u0c2e\u0c47\u0c26\u0c3f\u0c28\u0c3f \u0c35\u0c3f\u0c36\u0c4d\u0c35\u0c35\u0c3f\u0c28\u0c4b\u0c26\u0c3f\u0c28\u0c3f \u0c28\u0c28\u0c4d\u0c26\u0c3f\u0c28\u0c41\u0c24\u0c47\n\u0c17\u0c3f\u0c30\u0c3f\u0c35\u0c30\u0c35\u0c3f\u0c28\u0c4d\u0c27\u0c4d\u0c2f\u0c36\u0c3f\u0c30\u0c4b\u0c3d\u0c27\u0c3f\u0c28\u0c3f\u0c35\u0c3e\u0c38\u0c3f\u0c28\u0c3f \u0c35\u0c3f\u0c37\u0c4d\u0c23\u0c41\u0c35\u0c3f\u0c32\u0c3e\u0c38\u0c3f\u0c28\u0c3f \u0c1c\u0c3f\u0c37\u0c4d\u0c23\u0c41\u0c28\u0c41\u0c24\u0c47 \u0964\n\u0c2d\u0c17\u0c35\u0c24\u0c3f \u0c39\u0c47 \u0c36\u0c3f\u0c24\u0c3f\u0c15\u0c23\u0c4d\u0c20\u0c15\u0c41\u0c1f\u0c41\u0c2e\u0c4d\u0c2c\u0c3f\u0c28\u0c3f \u0c2d\u0c42\u0c30\u0c3f\u0c15\u0c41\u0c1f\u0c41\u0c2e\u0c4d\u0c2c\u0c3f\u0c28\u0c3f \u0c2d\u0c42\u0c30\u0c3f\u0c15\u0c43\u0c24\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c67 \u0965", "tamil": "\u0b85\u0baf\u0bbf \u0b95\u0bbf\u0bb0\u0bbf\u0ba8\u0ba8\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0ba8\u0ba8\u0bcd\u0ba4\u0bbf\u0ba4\u0bae\u0bc7\u0ba4\u0bbf\u0ba8\u0bbf \u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0bb5\u0bbf\u0ba8\u0bcb\u0ba4\u0bbf\u0ba8\u0bbf \u0ba8\u0ba8\u0bcd\u0ba4\u0bbf\u0ba8\u0bc1\u0ba4\u0bc7\n\u0b95\u0bbf\u0bb0\u0bbf\u0bb5\u0bb0\u0bb5\u0bbf\u0ba8\u0bcd\u0ba4\u0bcd\u0baf\u0bb6\u0bbf\u0bb0\u0bcb\u093d\u0ba4\u0bbf\u0ba8\u0bbf\u0bb5\u0bbe\u0bb8\u0bbf\u0ba8\u0bbf \u0bb5\u0bbf\u0bb7\u0bcd\u0ba3\u0bc1\u0bb5\u0bbf\u0bb2\u0bbe\u0bb8\u0bbf\u0ba8\u0bbf \u0b9c\u0bbf\u0bb7\u0bcd\u0ba3\u0bc1\u0ba8\u0bc1\u0ba4\u0bc7 \u0964\n\u0baa\u0b95\u0bb5\u0ba4\u0bbf \u0bb9\u0bc7 \u0bb6\u0bbf\u0ba4\u0bbf\u0b95\u0ba3\u0bcd\u0b9f\u0b95\u0bc1\u0b9f\u0bc1\u0bae\u0bcd\u0baa\u0bbf\u0ba8\u0bbf \u0baa\u0bc2\u0bb0\u0bbf\u0b95\u0bc1\u0b9f\u0bc1\u0bae\u0bcd\u0baa\u0bbf\u0ba8\u0bbf \u0baa\u0bc2\u0bb0\u0bbf\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be7 \u0965", "kannada": "\u0c85\u0caf\u0cbf \u0c97\u0cbf\u0cb0\u0cbf\u0ca8\u0ca8\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0ca8\u0ca8\u0ccd\u0ca6\u0cbf\u0ca4\u0cae\u0cc7\u0ca6\u0cbf\u0ca8\u0cbf \u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0cb5\u0cbf\u0ca8\u0ccb\u0ca6\u0cbf\u0ca8\u0cbf \u0ca8\u0ca8\u0ccd\u0ca6\u0cbf\u0ca8\u0cc1\u0ca4\u0cc7\n\u0c97\u0cbf\u0cb0\u0cbf\u0cb5\u0cb0\u0cb5\u0cbf\u0ca8\u0ccd\u0ca7\u0ccd\u0caf\u0cb6\u0cbf\u0cb0\u0ccb\u0cbd\u0ca7\u0cbf\u0ca8\u0cbf\u0cb5\u0cbe\u0cb8\u0cbf\u0ca8\u0cbf \u0cb5\u0cbf\u0cb7\u0ccd\u0ca3\u0cc1\u0cb5\u0cbf\u0cb2\u0cbe\u0cb8\u0cbf\u0ca8\u0cbf \u0c9c\u0cbf\u0cb7\u0ccd\u0ca3\u0cc1\u0ca8\u0cc1\u0ca4\u0cc7 \u0964\n\u0cad\u0c97\u0cb5\u0ca4\u0cbf \u0cb9\u0cc7 \u0cb6\u0cbf\u0ca4\u0cbf\u0c95\u0ca3\u0ccd\u0ca0\u0c95\u0cc1\u0c9f\u0cc1\u0cae\u0ccd\u0cac\u0cbf\u0ca8\u0cbf \u0cad\u0cc2\u0cb0\u0cbf\u0c95\u0cc1\u0c9f\u0cc1\u0cae\u0ccd\u0cac\u0cbf\u0ca8\u0cbf \u0cad\u0cc2\u0cb0\u0cbf\u0c95\u0cc3\u0ca4\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce7 \u0965", "malayalam": "\u0d05\u0d2f\u0d3f \u0d17\u0d3f\u0d30\u0d3f\u0d28\u0d28\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d28\u0d28\u0d4d\u0d26\u0d3f\u0d24\u0d2e\u0d47\u0d26\u0d3f\u0d28\u0d3f \u0d35\u0d3f\u0d36\u0d4d\u0d35\u0d35\u0d3f\u0d28\u0d4b\u0d26\u0d3f\u0d28\u0d3f \u0d28\u0d28\u0d4d\u0d26\u0d3f\u0d28\u0d41\u0d24\u0d47\n\u0d17\u0d3f\u0d30\u0d3f\u0d35\u0d30\u0d35\u0d3f\u0d28\u0d4d\u0d27\u0d4d\u0d2f\u0d36\u0d3f\u0d30\u0d4b\u0d3d\u0d27\u0d3f\u0d28\u0d3f\u0d35\u0d3e\u0d38\u0d3f\u0d28\u0d3f \u0d35\u0d3f\u0d37\u0d4d\u0d23\u0d41\u0d35\u0d3f\u0d32\u0d3e\u0d38\u0d3f\u0d28\u0d3f \u0d1c\u0d3f\u0d37\u0d4d\u0d23\u0d41\u0d28\u0d41\u0d24\u0d47 \u0964\n\u0d2d\u0d17\u0d35\u0d24\u0d3f \u0d39\u0d47 \u0d36\u0d3f\u0d24\u0d3f\u0d15\u0d23\u0d4d\u0d20\u0d15\u0d41\u0d1f\u0d41\u0d2e\u0d4d\u0d2c\u0d3f\u0d28\u0d3f \u0d2d\u0d42\u0d30\u0d3f\u0d15\u0d41\u0d1f\u0d41\u0d2e\u0d4d\u0d2c\u0d3f\u0d28\u0d3f \u0d2d\u0d42\u0d30\u0d3f\u0d15\u0d43\u0d24\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d67 \u0965", "iast": "ayi girinandini nanditamedini vi\u015bvavinodini nandinute\ngirivaravindhya\u015biro'dhiniv\u0101sini vi\u1e63\u1e47uvil\u0101sini ji\u1e63\u1e47unute |\nbhagavati he \u015bitika\u1e47\u1e6dhaku\u1e6dumbini bh\u016briku\u1e6dumbini bh\u016brik\u1e5bte\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 1 ||"},
        draftTranslation: "O Daughter of the Mountain, who gladdens the earth, rejoices the cosmos, praised by Nandi! Dwelling on the crest of the magnificent Vindhya mountains, joy of Vishnu, praised by Indra! O Goddess, consort of the blue-throated Shiva, mother of the vast universe, creator of abundance! Victory to You, O Slayer of Mahishasura, with captivating braided hair, O daughter of the Mountain!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 2,
        devanagariText: "\u0938\u0941\u0930\u0935\u0930\u0935\u0930\u094d\u0937\u093f\u0923\u093f \u0926\u0941\u0930\u094d\u0927\u0930\u0927\u0930\u094d\u0937\u093f\u0923\u093f \u0926\u0941\u0930\u094d\u092e\u0941\u0916\u092e\u0930\u094d\u0937\u093f\u0923\u093f \u0939\u0930\u094d\u0937\u0930\u0924\u0947\n\u0924\u094d\u0930\u093f\u092d\u0941\u0935\u0928\u092a\u094b\u0937\u093f\u0923\u093f \u0936\u0919\u094d\u0915\u0930\u0924\u094b\u0937\u093f\u0923\u093f \u0915\u093f\u0932\u094d\u092c\u093f\u0937\u092e\u094b\u0937\u093f\u0923\u093f \u0918\u094b\u0937\u0930\u0924\u0947 \u0964\n\u0926\u0928\u0941\u091c\u0936\u094b\u0937\u093f\u0923\u0940 \u0926\u0941\u0930\u094d\u092e\u0926\u0936\u094b\u0937\u093f\u0923\u093f \u0915\u093f\u0932\u094d\u092c\u093f\u0937\u0926\u094b\u0937\u093f\u0923\u093f \u0926\u093e\u0928\u0935\u0930\u0924\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0968 \u0965",
        iastText: "suravaravar\u1e63i\u1e47i durdharadhar\u1e63i\u1e47i durmukhamar\u1e63i\u1e47i har\u1e63arat\u0113\ntribhuvanap\u014d\u1e63i\u1e47i \u015ba\u1e45karat\u014d\u1e63i\u1e47i kilbi\u1e63am\u014d\u1e63i\u1e47i gh\u014d\u1e63arat\u0113 \u0964\ndanuja\u015b\u014d\u1e63i\u1e47\u012b durmada\u015b\u014d\u1e63i\u1e47i kilbi\u1e63ad\u014d\u1e63i\u1e47i d\u0101navarat\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 2 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c38\u0c41\u0c30\u0c35\u0c30\u0c35\u0c30\u0c4d\u0c37\u0c3f\u0c23\u0c3f \u0c26\u0c41\u0c30\u0c4d\u0c27\u0c30\u0c27\u0c30\u0c4d\u0c37\u0c3f\u0c23\u0c3f \u0c26\u0c41\u0c30\u0c4d\u0c2e\u0c41\u0c16\u0c2e\u0c30\u0c4d\u0c37\u0c3f\u0c23\u0c3f \u0c39\u0c30\u0c4d\u0c37\u0c30\u0c24\u0c47\n\u0c24\u0c4d\u0c30\u0c3f\u0c2d\u0c41\u0c35\u0c28\u0c2a\u0c4b\u0c37\u0c3f\u0c23\u0c3f \u0c36\u0c19\u0c4d\u0c15\u0c30\u0c24\u0c4b\u0c37\u0c3f\u0c23\u0c3f \u0c15\u0c3f\u0c32\u0c4d\u0c2c\u0c3f\u0c37\u0c2e\u0c4b\u0c37\u0c3f\u0c23\u0c3f \u0c18\u0c4b\u0c37\u0c30\u0c24\u0c47 \u0964\n\u0c26\u0c28\u0c41\u0c1c\u0c36\u0c4b\u0c37\u0c3f\u0c23\u0c40 \u0c26\u0c41\u0c30\u0c4d\u0c2e\u0c26\u0c36\u0c4b\u0c37\u0c3f\u0c23\u0c3f \u0c15\u0c3f\u0c32\u0c4d\u0c2c\u0c3f\u0c37\u0c26\u0c4b\u0c37\u0c3f\u0c23\u0c3f \u0c26\u0c3e\u0c28\u0c35\u0c30\u0c24\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c68 \u0965", "tamil": "\u0bb8\u0bc1\u0bb0\u0bb5\u0bb0\u0bb5\u0bb0\u0bcd\u0bb7\u0bbf\u0ba3\u0bbf \u0ba4\u0bc1\u0bb0\u0bcd\u0ba4\u0bb0\u0ba4\u0bb0\u0bcd\u0bb7\u0bbf\u0ba3\u0bbf \u0ba4\u0bc1\u0bb0\u0bcd\u0bae\u0bc1\u0b95\u0bae\u0bb0\u0bcd\u0bb7\u0bbf\u0ba3\u0bbf \u0bb9\u0bb0\u0bcd\u0bb7\u0bb0\u0ba4\u0bc7\n\u0ba4\u0bcd\u0bb0\u0bbf\u0baa\u0bc1\u0bb5\u0ba8\u0baa\u0bcb\u0bb7\u0bbf\u0ba3\u0bbf \u0bb6\u0b99\u0bcd\u0b95\u0bb0\u0ba4\u0bcb\u0bb7\u0bbf\u0ba3\u0bbf \u0b95\u0bbf\u0bb2\u0bcd\u0baa\u0bbf\u0bb7\u0bae\u0bcb\u0bb7\u0bbf\u0ba3\u0bbf \u0b95\u0bcb\u0bb7\u0bb0\u0ba4\u0bc7 \u0964\n\u0ba4\u0ba8\u0bc1\u0b9c\u0bb6\u0bcb\u0bb7\u0bbf\u0ba3\u0bc0 \u0ba4\u0bc1\u0bb0\u0bcd\u0bae\u0ba4\u0bb6\u0bcb\u0bb7\u0bbf\u0ba3\u0bbf \u0b95\u0bbf\u0bb2\u0bcd\u0baa\u0bbf\u0bb7\u0ba4\u0bcb\u0bb7\u0bbf\u0ba3\u0bbf \u0ba4\u0bbe\u0ba8\u0bb5\u0bb0\u0ba4\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be8 \u0965", "kannada": "\u0cb8\u0cc1\u0cb0\u0cb5\u0cb0\u0cb5\u0cb0\u0ccd\u0cb7\u0cbf\u0ca3\u0cbf \u0ca6\u0cc1\u0cb0\u0ccd\u0ca7\u0cb0\u0ca7\u0cb0\u0ccd\u0cb7\u0cbf\u0ca3\u0cbf \u0ca6\u0cc1\u0cb0\u0ccd\u0cae\u0cc1\u0c96\u0cae\u0cb0\u0ccd\u0cb7\u0cbf\u0ca3\u0cbf \u0cb9\u0cb0\u0ccd\u0cb7\u0cb0\u0ca4\u0cc7\n\u0ca4\u0ccd\u0cb0\u0cbf\u0cad\u0cc1\u0cb5\u0ca8\u0caa\u0ccb\u0cb7\u0cbf\u0ca3\u0cbf \u0cb6\u0c99\u0ccd\u0c95\u0cb0\u0ca4\u0ccb\u0cb7\u0cbf\u0ca3\u0cbf \u0c95\u0cbf\u0cb2\u0ccd\u0cac\u0cbf\u0cb7\u0cae\u0ccb\u0cb7\u0cbf\u0ca3\u0cbf \u0c98\u0ccb\u0cb7\u0cb0\u0ca4\u0cc7 \u0964\n\u0ca6\u0ca8\u0cc1\u0c9c\u0cb6\u0ccb\u0cb7\u0cbf\u0ca3\u0cc0 \u0ca6\u0cc1\u0cb0\u0ccd\u0cae\u0ca6\u0cb6\u0ccb\u0cb7\u0cbf\u0ca3\u0cbf \u0c95\u0cbf\u0cb2\u0ccd\u0cac\u0cbf\u0cb7\u0ca6\u0ccb\u0cb7\u0cbf\u0ca3\u0cbf \u0ca6\u0cbe\u0ca8\u0cb5\u0cb0\u0ca4\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce8 \u0965", "malayalam": "\u0d38\u0d41\u0d30\u0d35\u0d30\u0d35\u0d30\u0d4d\u0d37\u0d3f\u0d23\u0d3f \u0d26\u0d41\u0d30\u0d4d\u0d27\u0d30\u0d27\u0d30\u0d4d\u0d37\u0d3f\u0d23\u0d3f \u0d26\u0d41\u0d30\u0d4d\u0d2e\u0d41\u0d16\u0d2e\u0d30\u0d4d\u0d37\u0d3f\u0d23\u0d3f \u0d39\u0d30\u0d4d\u0d37\u0d30\u0d24\u0d47\n\u0d24\u0d4d\u0d30\u0d3f\u0d2d\u0d41\u0d35\u0d28\u0d2a\u0d4b\u0d37\u0d3f\u0d23\u0d3f \u0d36\u0d19\u0d4d\u0d15\u0d30\u0d24\u0d4b\u0d37\u0d3f\u0d23\u0d3f \u0d15\u0d3f\u0d32\u0d4d\u0d2c\u0d3f\u0d37\u0d2e\u0d4b\u0d37\u0d3f\u0d23\u0d3f \u0d18\u0d4b\u0d37\u0d30\u0d24\u0d47 \u0964\n\u0d26\u0d28\u0d41\u0d1c\u0d36\u0d4b\u0d37\u0d3f\u0d23\u0d40 \u0d26\u0d41\u0d30\u0d4d\u0d2e\u0d26\u0d36\u0d4b\u0d37\u0d3f\u0d23\u0d3f \u0d15\u0d3f\u0d32\u0d4d\u0d2c\u0d3f\u0d37\u0d26\u0d4b\u0d37\u0d3f\u0d23\u0d3f \u0d26\u0d3e\u0d28\u0d35\u0d30\u0d24\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d68 \u0965", "iast": "suravaravar\u1e63i\u1e47i durdharadhar\u1e63i\u1e47i durmukhamar\u1e63i\u1e47i har\u1e63arate\ntribhuvanapo\u1e63i\u1e47i \u015ba\u1e45karato\u1e63i\u1e47i kilbi\u1e63amo\u1e63i\u1e47i gho\u1e63arate |\ndanuja\u015bo\u1e63i\u1e47\u012b durmada\u015bo\u1e63i\u1e47i kilbi\u1e63ado\u1e63i\u1e47i d\u0101navarate\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 2 ||"},
        draftTranslation: "Bestowing divine boons upon the celestials, overpowering the unvanquished, subduing the arrogant Durmukha demon, delighting in blissful joy! Nourishing the three worlds, pleasing to Shankara, erasing all sins! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 3,
        devanagariText: "\u0905\u092f\u093f \u091c\u0917\u0926\u092e\u094d\u092c \u092e\u0926\u092e\u094d\u092c \u0915\u0926\u092e\u094d\u092c\u0935\u0928\u092a\u094d\u0930\u093f\u092f\u0935\u093e\u0938\u093f\u0928\u093f \u0939\u093e\u0938\u0930\u0924\u0947\n\u0936\u093f\u0916\u0930\u093f\u0936\u093f\u0930\u094b\u092e\u0923\u093f \u0924\u0941\u0919\u094d\u0917\u0939\u093f\u092e\u093e\u0932\u092f\u0936\u0943\u0919\u094d\u0917\u0928\u093f\u091c\u093e\u0932\u092f\u092e\u0927\u094d\u092f\u0917\u0924\u0947 \u0964\n\u092e\u0927\u0941\u092e\u0927\u0941\u0930\u0947 \u092e\u0927\u0941\u0915\u0948\u091f\u092d\u0917\u091e\u094d\u091c\u093f\u0928\u093f \u0915\u0948\u091f\u092d\u092d\u091e\u094d\u091c\u093f\u0928\u093f \u0930\u093e\u0938\u0930\u0924\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0969 \u0965",
        iastText: "ayi jagadamba madamba kadambavanapriyav\u0101sini h\u0101sarat\u0113\n\u015bikhari\u015bir\u014dma\u1e47i tu\u1e45gahim\u0101laya\u015b\u1e5b\u1e45ganij\u0101layamadhyagat\u0113 \u0964\nmadhumadhur\u0113 madhukai\u1e6dabhaga\u00f1jini kai\u1e6dabhabha\u00f1jini r\u0101sarat\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 3 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c05\u0c2f\u0c3f \u0c1c\u0c17\u0c26\u0c2e\u0c4d\u0c2c \u0c2e\u0c26\u0c2e\u0c4d\u0c2c \u0c15\u0c26\u0c2e\u0c4d\u0c2c\u0c35\u0c28\u0c2a\u0c4d\u0c30\u0c3f\u0c2f\u0c35\u0c3e\u0c38\u0c3f\u0c28\u0c3f \u0c39\u0c3e\u0c38\u0c30\u0c24\u0c47\n\u0c36\u0c3f\u0c16\u0c30\u0c3f\u0c36\u0c3f\u0c30\u0c4b\u0c2e\u0c23\u0c3f \u0c24\u0c41\u0c19\u0c4d\u0c17\u0c39\u0c3f\u0c2e\u0c3e\u0c32\u0c2f\u0c36\u0c43\u0c19\u0c4d\u0c17\u0c28\u0c3f\u0c1c\u0c3e\u0c32\u0c2f\u0c2e\u0c27\u0c4d\u0c2f\u0c17\u0c24\u0c47 \u0964\n\u0c2e\u0c27\u0c41\u0c2e\u0c27\u0c41\u0c30\u0c47 \u0c2e\u0c27\u0c41\u0c15\u0c48\u0c1f\u0c2d\u0c17\u0c1e\u0c4d\u0c1c\u0c3f\u0c28\u0c3f \u0c15\u0c48\u0c1f\u0c2d\u0c2d\u0c1e\u0c4d\u0c1c\u0c3f\u0c28\u0c3f \u0c30\u0c3e\u0c38\u0c30\u0c24\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c69 \u0965", "tamil": "\u0b85\u0baf\u0bbf \u0b9c\u0b95\u0ba4\u0bae\u0bcd\u0baa \u0bae\u0ba4\u0bae\u0bcd\u0baa \u0b95\u0ba4\u0bae\u0bcd\u0baa\u0bb5\u0ba8\u0baa\u0bcd\u0bb0\u0bbf\u0baf\u0bb5\u0bbe\u0bb8\u0bbf\u0ba8\u0bbf \u0bb9\u0bbe\u0bb8\u0bb0\u0ba4\u0bc7\n\u0bb6\u0bbf\u0b95\u0bb0\u0bbf\u0bb6\u0bbf\u0bb0\u0bcb\u0bae\u0ba3\u0bbf \u0ba4\u0bc1\u0b99\u0bcd\u0b95\u0bb9\u0bbf\u0bae\u0bbe\u0bb2\u0baf\u0bb6\u0bcd\u0bb0\u0bc1'\u0b99\u0bcd\u0b95\u0ba8\u0bbf\u0b9c\u0bbe\u0bb2\u0baf\u0bae\u0ba4\u0bcd\u0baf\u0b95\u0ba4\u0bc7 \u0964\n\u0bae\u0ba4\u0bc1\u0bae\u0ba4\u0bc1\u0bb0\u0bc7 \u0bae\u0ba4\u0bc1\u0b95\u0bc8\u0b9f\u0baa\u0b95\u0b9e\u0bcd\u0b9c\u0bbf\u0ba8\u0bbf \u0b95\u0bc8\u0b9f\u0baa\u0baa\u0b9e\u0bcd\u0b9c\u0bbf\u0ba8\u0bbf \u0bb0\u0bbe\u0bb8\u0bb0\u0ba4\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be9 \u0965", "kannada": "\u0c85\u0caf\u0cbf \u0c9c\u0c97\u0ca6\u0cae\u0ccd\u0cac \u0cae\u0ca6\u0cae\u0ccd\u0cac \u0c95\u0ca6\u0cae\u0ccd\u0cac\u0cb5\u0ca8\u0caa\u0ccd\u0cb0\u0cbf\u0caf\u0cb5\u0cbe\u0cb8\u0cbf\u0ca8\u0cbf \u0cb9\u0cbe\u0cb8\u0cb0\u0ca4\u0cc7\n\u0cb6\u0cbf\u0c96\u0cb0\u0cbf\u0cb6\u0cbf\u0cb0\u0ccb\u0cae\u0ca3\u0cbf \u0ca4\u0cc1\u0c99\u0ccd\u0c97\u0cb9\u0cbf\u0cae\u0cbe\u0cb2\u0caf\u0cb6\u0cc3\u0c99\u0ccd\u0c97\u0ca8\u0cbf\u0c9c\u0cbe\u0cb2\u0caf\u0cae\u0ca7\u0ccd\u0caf\u0c97\u0ca4\u0cc7 \u0964\n\u0cae\u0ca7\u0cc1\u0cae\u0ca7\u0cc1\u0cb0\u0cc7 \u0cae\u0ca7\u0cc1\u0c95\u0cc8\u0c9f\u0cad\u0c97\u0c9e\u0ccd\u0c9c\u0cbf\u0ca8\u0cbf \u0c95\u0cc8\u0c9f\u0cad\u0cad\u0c9e\u0ccd\u0c9c\u0cbf\u0ca8\u0cbf \u0cb0\u0cbe\u0cb8\u0cb0\u0ca4\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce9 \u0965", "malayalam": "\u0d05\u0d2f\u0d3f \u0d1c\u0d17\u0d26\u0d2e\u0d4d\u0d2c \u0d2e\u0d26\u0d2e\u0d4d\u0d2c \u0d15\u0d26\u0d2e\u0d4d\u0d2c\u0d35\u0d28\u0d2a\u0d4d\u0d30\u0d3f\u0d2f\u0d35\u0d3e\u0d38\u0d3f\u0d28\u0d3f \u0d39\u0d3e\u0d38\u0d30\u0d24\u0d47\n\u0d36\u0d3f\u0d16\u0d30\u0d3f\u0d36\u0d3f\u0d30\u0d4b\u0d2e\u0d23\u0d3f \u0d24\u0d41\u0d19\u0d4d\u0d17\u0d39\u0d3f\u0d2e\u0d3e\u0d32\u0d2f\u0d36\u0d43\u0d19\u0d4d\u0d17\u0d28\u0d3f\u0d1c\u0d3e\u0d32\u0d2f\u0d2e\u0d27\u0d4d\u0d2f\u0d17\u0d24\u0d47 \u0964\n\u0d2e\u0d27\u0d41\u0d2e\u0d27\u0d41\u0d30\u0d47 \u0d2e\u0d27\u0d41\u0d15\u0d48\u0d1f\u0d2d\u0d17\u0d1e\u0d4d\u0d1c\u0d3f\u0d28\u0d3f \u0d15\u0d48\u0d1f\u0d2d\u0d2d\u0d1e\u0d4d\u0d1c\u0d3f\u0d28\u0d3f \u0d30\u0d3e\u0d38\u0d30\u0d24\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d69 \u0965", "iast": "ayi jagadamba madamba kadambavanapriyav\u0101sini h\u0101sarate\n\u015bikhari\u015biroma\u1e47i tu\u1e45gahim\u0101laya\u015b\u1e5b\u1e45ganij\u0101layamadhyagate |\nmadhumadhure madhukai\u1e6dabhaga\u00f1jini kai\u1e6dabhabha\u00f1jini r\u0101sarate\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 3 ||"},
        draftTranslation: "O Mother of the universe, my own mother, fond of dwelling in the fragrant Kadamba groves, rejoicing in smiles! Residing atop the lofty Himalayan peaks, crushing the demons Madhu and Kaitabha! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 4,
        devanagariText: "\u0905\u092f\u093f \u0936\u0924\u0916\u0923\u094d\u0921\u0935\u093f\u0916\u0923\u094d\u0921\u093f\u0924\u0930\u0941\u0923\u094d\u0921\u0935\u093f\u0924\u0941\u0923\u094d\u0921\u093f\u0924\u0936\u0941\u0923\u094d\u0921\u0917\u091c\u093e\u0927\u093f\u092a\u0924\u0947\n\u0930\u093f\u092a\u0941\u0917\u091c\u0917\u0923\u094d\u0921\u0935\u093f\u0926\u093e\u0930\u0923\u091a\u0923\u094d\u0921\u092a\u0930\u093e\u0915\u094d\u0930\u092e\u0936\u0941\u0923\u094d\u0921\u092e\u0943\u0917\u093e\u0927\u093f\u092a\u0924\u0947 \u0964\n\u0928\u093f\u091c\u092d\u0941\u091c\u0926\u0923\u094d\u0921\u0928\u093f\u092a\u093e\u0924\u093f\u0924\u0916\u0923\u094d\u0921\u0935\u093f\u092a\u093e\u0924\u093f\u0924\u092e\u0941\u0923\u094d\u0921\u092d\u091f\u093e\u0927\u093f\u092a\u0924\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u096a \u0965",
        iastText: "ayi \u015batakha\u1e47\u1e0davikha\u1e47\u1e0ditaru\u1e47\u1e0davitu\u1e47\u1e0dita\u015bu\u1e47\u1e0dagaj\u0101dhipat\u0113\nripugajaga\u1e47\u1e0david\u0101ra\u1e47aca\u1e47\u1e0dapar\u0101krama\u015bu\u1e47\u1e0dam\u1e5bg\u0101dhipat\u0113 \u0964\nnijabhujada\u1e47\u1e0danip\u0101titakha\u1e47\u1e0davip\u0101titamu\u1e47\u1e0dabha\u1e6d\u0101dhipat\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 4 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c05\u0c2f\u0c3f \u0c36\u0c24\u0c16\u0c23\u0c4d\u0c21\u0c35\u0c3f\u0c16\u0c23\u0c4d\u0c21\u0c3f\u0c24\u0c30\u0c41\u0c23\u0c4d\u0c21\u0c35\u0c3f\u0c24\u0c41\u0c23\u0c4d\u0c21\u0c3f\u0c24\u0c36\u0c41\u0c23\u0c4d\u0c21\u0c17\u0c1c\u0c3e\u0c27\u0c3f\u0c2a\u0c24\u0c47\n\u0c30\u0c3f\u0c2a\u0c41\u0c17\u0c1c\u0c17\u0c23\u0c4d\u0c21\u0c35\u0c3f\u0c26\u0c3e\u0c30\u0c23\u0c1a\u0c23\u0c4d\u0c21\u0c2a\u0c30\u0c3e\u0c15\u0c4d\u0c30\u0c2e\u0c36\u0c41\u0c23\u0c4d\u0c21\u0c2e\u0c43\u0c17\u0c3e\u0c27\u0c3f\u0c2a\u0c24\u0c47 \u0964\n\u0c28\u0c3f\u0c1c\u0c2d\u0c41\u0c1c\u0c26\u0c23\u0c4d\u0c21\u0c28\u0c3f\u0c2a\u0c3e\u0c24\u0c3f\u0c24\u0c16\u0c23\u0c4d\u0c21\u0c35\u0c3f\u0c2a\u0c3e\u0c24\u0c3f\u0c24\u0c2e\u0c41\u0c23\u0c4d\u0c21\u0c2d\u0c1f\u0c3e\u0c27\u0c3f\u0c2a\u0c24\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c6a \u0965", "tamil": "\u0b85\u0baf\u0bbf \u0bb6\u0ba4\u0b95\u0ba3\u0bcd\u0b9f\u0bb5\u0bbf\u0b95\u0ba3\u0bcd\u0b9f\u0bbf\u0ba4\u0bb0\u0bc1\u0ba3\u0bcd\u0b9f\u0bb5\u0bbf\u0ba4\u0bc1\u0ba3\u0bcd\u0b9f\u0bbf\u0ba4\u0bb6\u0bc1\u0ba3\u0bcd\u0b9f\u0b95\u0b9c\u0bbe\u0ba4\u0bbf\u0baa\u0ba4\u0bc7\n\u0bb0\u0bbf\u0baa\u0bc1\u0b95\u0b9c\u0b95\u0ba3\u0bcd\u0b9f\u0bb5\u0bbf\u0ba4\u0bbe\u0bb0\u0ba3\u0b9a\u0ba3\u0bcd\u0b9f\u0baa\u0bb0\u0bbe\u0b95\u0bcd\u0bb0\u0bae\u0bb6\u0bc1\u0ba3\u0bcd\u0b9f\u0bae\u0bcd\u0bb0\u0bc1'\u0b95\u0bbe\u0ba4\u0bbf\u0baa\u0ba4\u0bc7 \u0964\n\u0ba8\u0bbf\u0b9c\u0baa\u0bc1\u0b9c\u0ba4\u0ba3\u0bcd\u0b9f\u0ba8\u0bbf\u0baa\u0bbe\u0ba4\u0bbf\u0ba4\u0b95\u0ba3\u0bcd\u0b9f\u0bb5\u0bbf\u0baa\u0bbe\u0ba4\u0bbf\u0ba4\u0bae\u0bc1\u0ba3\u0bcd\u0b9f\u0baa\u0b9f\u0bbe\u0ba4\u0bbf\u0baa\u0ba4\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0bea \u0965", "kannada": "\u0c85\u0caf\u0cbf \u0cb6\u0ca4\u0c96\u0ca3\u0ccd\u0ca1\u0cb5\u0cbf\u0c96\u0ca3\u0ccd\u0ca1\u0cbf\u0ca4\u0cb0\u0cc1\u0ca3\u0ccd\u0ca1\u0cb5\u0cbf\u0ca4\u0cc1\u0ca3\u0ccd\u0ca1\u0cbf\u0ca4\u0cb6\u0cc1\u0ca3\u0ccd\u0ca1\u0c97\u0c9c\u0cbe\u0ca7\u0cbf\u0caa\u0ca4\u0cc7\n\u0cb0\u0cbf\u0caa\u0cc1\u0c97\u0c9c\u0c97\u0ca3\u0ccd\u0ca1\u0cb5\u0cbf\u0ca6\u0cbe\u0cb0\u0ca3\u0c9a\u0ca3\u0ccd\u0ca1\u0caa\u0cb0\u0cbe\u0c95\u0ccd\u0cb0\u0cae\u0cb6\u0cc1\u0ca3\u0ccd\u0ca1\u0cae\u0cc3\u0c97\u0cbe\u0ca7\u0cbf\u0caa\u0ca4\u0cc7 \u0964\n\u0ca8\u0cbf\u0c9c\u0cad\u0cc1\u0c9c\u0ca6\u0ca3\u0ccd\u0ca1\u0ca8\u0cbf\u0caa\u0cbe\u0ca4\u0cbf\u0ca4\u0c96\u0ca3\u0ccd\u0ca1\u0cb5\u0cbf\u0caa\u0cbe\u0ca4\u0cbf\u0ca4\u0cae\u0cc1\u0ca3\u0ccd\u0ca1\u0cad\u0c9f\u0cbe\u0ca7\u0cbf\u0caa\u0ca4\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0cea \u0965", "malayalam": "\u0d05\u0d2f\u0d3f \u0d36\u0d24\u0d16\u0d23\u0d4d\u0d21\u0d35\u0d3f\u0d16\u0d23\u0d4d\u0d21\u0d3f\u0d24\u0d30\u0d41\u0d23\u0d4d\u0d21\u0d35\u0d3f\u0d24\u0d41\u0d23\u0d4d\u0d21\u0d3f\u0d24\u0d36\u0d41\u0d23\u0d4d\u0d21\u0d17\u0d1c\u0d3e\u0d27\u0d3f\u0d2a\u0d24\u0d47\n\u0d30\u0d3f\u0d2a\u0d41\u0d17\u0d1c\u0d17\u0d23\u0d4d\u0d21\u0d35\u0d3f\u0d26\u0d3e\u0d30\u0d23\u0d1a\u0d23\u0d4d\u0d21\u0d2a\u0d30\u0d3e\u0d15\u0d4d\u0d30\u0d2e\u0d36\u0d41\u0d23\u0d4d\u0d21\u0d2e\u0d43\u0d17\u0d3e\u0d27\u0d3f\u0d2a\u0d24\u0d47 \u0964\n\u0d28\u0d3f\u0d1c\u0d2d\u0d41\u0d1c\u0d26\u0d23\u0d4d\u0d21\u0d28\u0d3f\u0d2a\u0d3e\u0d24\u0d3f\u0d24\u0d16\u0d23\u0d4d\u0d21\u0d35\u0d3f\u0d2a\u0d3e\u0d24\u0d3f\u0d24\u0d2e\u0d41\u0d23\u0d4d\u0d21\u0d2d\u0d1f\u0d3e\u0d27\u0d3f\u0d2a\u0d24\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d6a \u0965", "iast": "ayi \u015batakha\u1e47\u1e0davikha\u1e47\u1e0ditaru\u1e47\u1e0davitu\u1e47\u1e0dita\u015bu\u1e47\u1e0dagaj\u0101dhipate\nripugajaga\u1e47\u1e0david\u0101ra\u1e47aca\u1e47\u1e0dapar\u0101krama\u015bu\u1e47\u1e0dam\u1e5bg\u0101dhipate |\nnijabhujada\u1e47\u1e0danip\u0101titakha\u1e47\u1e0davip\u0101titamu\u1e47\u1e0dabha\u1e6d\u0101dhipate\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 4 ||"},
        draftTranslation: "Severing into a hundred pieces the torsos and trunks of the ferocious battle-elephants, mounted upon the lion whose fierce might tears through enemy beasts, crushing demon warriors with Your powerful arms! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 5,
        devanagariText: "\u0905\u092f\u093f \u0930\u0923\u0926\u0941\u0930\u094d\u092e\u0926\u0936\u0924\u094d\u0930\u0941\u0935\u0927\u094b\u0926\u093f\u0924\u0926\u0941\u0930\u094d\u0927\u0930\u0928\u093f\u0930\u094d\u091c\u0930\u0936\u0915\u094d\u0924\u093f\u092d\u0943\u0924\u0947\n\u091a\u0924\u0941\u0930\u0935\u093f\u091a\u093e\u0930\u0927\u0941\u0930\u0940\u0923\u092e\u0939\u093e\u0936\u093f\u0935\u0926\u0942\u0924\u0915\u0943\u0924\u092a\u094d\u0930\u092e\u0925\u093e\u0927\u093f\u092a\u0924\u0947 \u0964\n\u0926\u0941\u0930\u093f\u0924\u0926\u0941\u0930\u0940\u0939\u0926\u0941\u0930\u093e\u0936\u092f\u0926\u0941\u0930\u094d\u092e\u0924\u093f\u0926\u093e\u0928\u0935\u0926\u0942\u0924\u0915\u0943\u0924\u093e\u0928\u094d\u0924\u0917\u0924\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u096b \u0965",
        iastText: "ayi ra\u1e47adurmada\u015batruvadh\u014dditadurdharanirjara\u015baktibh\u1e5bt\u0113\ncaturavic\u0101radhur\u012b\u1e47amah\u0101\u015bivad\u016btak\u1e5btapramath\u0101dhipat\u0113 \u0964\nduritadur\u012bhadur\u0101\u015bayadurmatid\u0101navad\u016btak\u1e5bt\u0101ntagat\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 5 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c05\u0c2f\u0c3f \u0c30\u0c23\u0c26\u0c41\u0c30\u0c4d\u0c2e\u0c26\u0c36\u0c24\u0c4d\u0c30\u0c41\u0c35\u0c27\u0c4b\u0c26\u0c3f\u0c24\u0c26\u0c41\u0c30\u0c4d\u0c27\u0c30\u0c28\u0c3f\u0c30\u0c4d\u0c1c\u0c30\u0c36\u0c15\u0c4d\u0c24\u0c3f\u0c2d\u0c43\u0c24\u0c47\n\u0c1a\u0c24\u0c41\u0c30\u0c35\u0c3f\u0c1a\u0c3e\u0c30\u0c27\u0c41\u0c30\u0c40\u0c23\u0c2e\u0c39\u0c3e\u0c36\u0c3f\u0c35\u0c26\u0c42\u0c24\u0c15\u0c43\u0c24\u0c2a\u0c4d\u0c30\u0c2e\u0c25\u0c3e\u0c27\u0c3f\u0c2a\u0c24\u0c47 \u0964\n\u0c26\u0c41\u0c30\u0c3f\u0c24\u0c26\u0c41\u0c30\u0c40\u0c39\u0c26\u0c41\u0c30\u0c3e\u0c36\u0c2f\u0c26\u0c41\u0c30\u0c4d\u0c2e\u0c24\u0c3f\u0c26\u0c3e\u0c28\u0c35\u0c26\u0c42\u0c24\u0c15\u0c43\u0c24\u0c3e\u0c28\u0c4d\u0c24\u0c17\u0c24\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c6b \u0965", "tamil": "\u0b85\u0baf\u0bbf \u0bb0\u0ba3\u0ba4\u0bc1\u0bb0\u0bcd\u0bae\u0ba4\u0bb6\u0ba4\u0bcd\u0bb0\u0bc1\u0bb5\u0ba4\u0bcb\u0ba4\u0bbf\u0ba4\u0ba4\u0bc1\u0bb0\u0bcd\u0ba4\u0bb0\u0ba8\u0bbf\u0bb0\u0bcd\u0b9c\u0bb0\u0bb6\u0b95\u0bcd\u0ba4\u0bbf\u0baa\u0bcd\u0bb0\u0bc1'\u0ba4\u0bc7\n\u0b9a\u0ba4\u0bc1\u0bb0\u0bb5\u0bbf\u0b9a\u0bbe\u0bb0\u0ba4\u0bc1\u0bb0\u0bc0\u0ba3\u0bae\u0bb9\u0bbe\u0bb6\u0bbf\u0bb5\u0ba4\u0bc2\u0ba4\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0baa\u0bcd\u0bb0\u0bae\u0ba4\u0bbe\u0ba4\u0bbf\u0baa\u0ba4\u0bc7 \u0964\n\u0ba4\u0bc1\u0bb0\u0bbf\u0ba4\u0ba4\u0bc1\u0bb0\u0bc0\u0bb9\u0ba4\u0bc1\u0bb0\u0bbe\u0bb6\u0baf\u0ba4\u0bc1\u0bb0\u0bcd\u0bae\u0ba4\u0bbf\u0ba4\u0bbe\u0ba8\u0bb5\u0ba4\u0bc2\u0ba4\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0bbe\u0ba8\u0bcd\u0ba4\u0b95\u0ba4\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0beb \u0965", "kannada": "\u0c85\u0caf\u0cbf \u0cb0\u0ca3\u0ca6\u0cc1\u0cb0\u0ccd\u0cae\u0ca6\u0cb6\u0ca4\u0ccd\u0cb0\u0cc1\u0cb5\u0ca7\u0ccb\u0ca6\u0cbf\u0ca4\u0ca6\u0cc1\u0cb0\u0ccd\u0ca7\u0cb0\u0ca8\u0cbf\u0cb0\u0ccd\u0c9c\u0cb0\u0cb6\u0c95\u0ccd\u0ca4\u0cbf\u0cad\u0cc3\u0ca4\u0cc7\n\u0c9a\u0ca4\u0cc1\u0cb0\u0cb5\u0cbf\u0c9a\u0cbe\u0cb0\u0ca7\u0cc1\u0cb0\u0cc0\u0ca3\u0cae\u0cb9\u0cbe\u0cb6\u0cbf\u0cb5\u0ca6\u0cc2\u0ca4\u0c95\u0cc3\u0ca4\u0caa\u0ccd\u0cb0\u0cae\u0ca5\u0cbe\u0ca7\u0cbf\u0caa\u0ca4\u0cc7 \u0964\n\u0ca6\u0cc1\u0cb0\u0cbf\u0ca4\u0ca6\u0cc1\u0cb0\u0cc0\u0cb9\u0ca6\u0cc1\u0cb0\u0cbe\u0cb6\u0caf\u0ca6\u0cc1\u0cb0\u0ccd\u0cae\u0ca4\u0cbf\u0ca6\u0cbe\u0ca8\u0cb5\u0ca6\u0cc2\u0ca4\u0c95\u0cc3\u0ca4\u0cbe\u0ca8\u0ccd\u0ca4\u0c97\u0ca4\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ceb \u0965", "malayalam": "\u0d05\u0d2f\u0d3f \u0d30\u0d23\u0d26\u0d41\u0d30\u0d4d\u0d2e\u0d26\u0d36\u0d24\u0d4d\u0d30\u0d41\u0d35\u0d27\u0d4b\u0d26\u0d3f\u0d24\u0d26\u0d41\u0d30\u0d4d\u0d27\u0d30\u0d28\u0d3f\u0d30\u0d4d\u0d1c\u0d30\u0d36\u0d15\u0d4d\u0d24\u0d3f\u0d2d\u0d43\u0d24\u0d47\n\u0d1a\u0d24\u0d41\u0d30\u0d35\u0d3f\u0d1a\u0d3e\u0d30\u0d27\u0d41\u0d30\u0d40\u0d23\u0d2e\u0d39\u0d3e\u0d36\u0d3f\u0d35\u0d26\u0d42\u0d24\u0d15\u0d43\u0d24\u0d2a\u0d4d\u0d30\u0d2e\u0d25\u0d3e\u0d27\u0d3f\u0d2a\u0d24\u0d47 \u0964\n\u0d26\u0d41\u0d30\u0d3f\u0d24\u0d26\u0d41\u0d30\u0d40\u0d39\u0d26\u0d41\u0d30\u0d3e\u0d36\u0d2f\u0d26\u0d41\u0d30\u0d4d\u0d2e\u0d24\u0d3f\u0d26\u0d3e\u0d28\u0d35\u0d26\u0d42\u0d24\u0d15\u0d43\u0d24\u0d3e\u0d28\u0d4d\u0d24\u0d17\u0d24\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d6b \u0965", "iast": "ayi ra\u1e47adurmada\u015batruvadhoditadurdharanirjara\u015baktibh\u1e5bte\ncaturavic\u0101radhur\u012b\u1e47amah\u0101\u015bivad\u016btak\u1e5btapramath\u0101dhipate |\nduritadur\u012bhadur\u0101\u015bayadurmatid\u0101navad\u016btak\u1e5bt\u0101ntagate\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 5 ||"},
        draftTranslation: "Manifesting the irresistible collective energy of the celestials to destroy battle-crazed demons, commissioning Shiva Himself as emissary to the arrogant asura hosts, bringing destruction upon wicked messengers! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 6,
        devanagariText: "\u0905\u092f\u093f \u0936\u0930\u0923\u093e\u0917\u0924\u0935\u0948\u0930\u093f\u0935\u0927\u0942\u0935\u0926\u0928\u093e\u0930\u094d\u091a\u093f\u0924\u091a\u093e\u091f\u0941\u0935\u0926\u093e\u0928\u094d\u092f\u0935\u093f\u0927\u0947\n\u0935\u093f\u0926\u0941\u0937\u0935\u0930\u093e\u0930\u094d\u091a\u093f\u0924\u092a\u0926\u094d\u092e\u092a\u0926\u093e\u0916\u093f\u0932\u0935\u093f\u0936\u094d\u0935\u092a\u0924\u0947 \u0926\u093f\u0924\u093f\u091c\u093e\u0930\u094d\u0924\u093f\u0939\u0930\u0947 \u0964\n\u0905\u0935\u093f\u091a\u0932\u092d\u0915\u094d\u0924\u093f\u0915\u0943\u092a\u093e\u0932\u0941\u091c\u0928\u0947\u0937\u094d\u0935\u092d\u092f\u092a\u094d\u0930\u0926\u0939\u0938\u094d\u0924\u0938\u0930\u094b\u0930\u0941\u0939\u092d\u093e\u0915\u094d\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u096c \u0965",
        iastText: "ayi \u015bara\u1e47\u0101gatavairivadh\u016bvadan\u0101rcitac\u0101\u1e6duvad\u0101nyavidh\u0113\nvidu\u1e63avar\u0101rcitapadmapad\u0101khilavi\u015bvapat\u0113 ditij\u0101rtihar\u0113 \u0964\navicalabhaktik\u1e5bp\u0101lujan\u0113\u1e63vabhayapradahastasar\u014druhabh\u0101k\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 6 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c05\u0c2f\u0c3f \u0c36\u0c30\u0c23\u0c3e\u0c17\u0c24\u0c35\u0c48\u0c30\u0c3f\u0c35\u0c27\u0c42\u0c35\u0c26\u0c28\u0c3e\u0c30\u0c4d\u0c1a\u0c3f\u0c24\u0c1a\u0c3e\u0c1f\u0c41\u0c35\u0c26\u0c3e\u0c28\u0c4d\u0c2f\u0c35\u0c3f\u0c27\u0c47\n\u0c35\u0c3f\u0c26\u0c41\u0c37\u0c35\u0c30\u0c3e\u0c30\u0c4d\u0c1a\u0c3f\u0c24\u0c2a\u0c26\u0c4d\u0c2e\u0c2a\u0c26\u0c3e\u0c16\u0c3f\u0c32\u0c35\u0c3f\u0c36\u0c4d\u0c35\u0c2a\u0c24\u0c47 \u0c26\u0c3f\u0c24\u0c3f\u0c1c\u0c3e\u0c30\u0c4d\u0c24\u0c3f\u0c39\u0c30\u0c47 \u0964\n\u0c05\u0c35\u0c3f\u0c1a\u0c32\u0c2d\u0c15\u0c4d\u0c24\u0c3f\u0c15\u0c43\u0c2a\u0c3e\u0c32\u0c41\u0c1c\u0c28\u0c47\u0c37\u0c4d\u0c35\u0c2d\u0c2f\u0c2a\u0c4d\u0c30\u0c26\u0c39\u0c38\u0c4d\u0c24\u0c38\u0c30\u0c4b\u0c30\u0c41\u0c39\u0c2d\u0c3e\u0c15\u0c4d\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c6c \u0965", "tamil": "\u0b85\u0baf\u0bbf \u0bb6\u0bb0\u0ba3\u0bbe\u0b95\u0ba4\u0bb5\u0bc8\u0bb0\u0bbf\u0bb5\u0ba4\u0bc2\u0bb5\u0ba4\u0ba8\u0bbe\u0bb0\u0bcd\u0b9a\u0bbf\u0ba4\u0b9a\u0bbe\u0b9f\u0bc1\u0bb5\u0ba4\u0bbe\u0ba8\u0bcd\u0baf\u0bb5\u0bbf\u0ba4\u0bc7\n\u0bb5\u0bbf\u0ba4\u0bc1\u0bb7\u0bb5\u0bb0\u0bbe\u0bb0\u0bcd\u0b9a\u0bbf\u0ba4\u0baa\u0ba4\u0bcd\u0bae\u0baa\u0ba4\u0bbe\u0b95\u0bbf\u0bb2\u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0baa\u0ba4\u0bc7 \u0ba4\u0bbf\u0ba4\u0bbf\u0b9c\u0bbe\u0bb0\u0bcd\u0ba4\u0bbf\u0bb9\u0bb0\u0bc7 \u0964\n\u0b85\u0bb5\u0bbf\u0b9a\u0bb2\u0baa\u0b95\u0bcd\u0ba4\u0bbf\u0b95\u0bcd\u0bb0\u0bc1'\u0baa\u0bbe\u0bb2\u0bc1\u0b9c\u0ba8\u0bc7\u0bb7\u0bcd\u0bb5\u0baa\u0baf\u0baa\u0bcd\u0bb0\u0ba4\u0bb9\u0bb8\u0bcd\u0ba4\u0bb8\u0bb0\u0bcb\u0bb0\u0bc1\u0bb9\u0baa\u0bbe\u0b95\u0bcd\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0bec \u0965", "kannada": "\u0c85\u0caf\u0cbf \u0cb6\u0cb0\u0ca3\u0cbe\u0c97\u0ca4\u0cb5\u0cc8\u0cb0\u0cbf\u0cb5\u0ca7\u0cc2\u0cb5\u0ca6\u0ca8\u0cbe\u0cb0\u0ccd\u0c9a\u0cbf\u0ca4\u0c9a\u0cbe\u0c9f\u0cc1\u0cb5\u0ca6\u0cbe\u0ca8\u0ccd\u0caf\u0cb5\u0cbf\u0ca7\u0cc7\n\u0cb5\u0cbf\u0ca6\u0cc1\u0cb7\u0cb5\u0cb0\u0cbe\u0cb0\u0ccd\u0c9a\u0cbf\u0ca4\u0caa\u0ca6\u0ccd\u0cae\u0caa\u0ca6\u0cbe\u0c96\u0cbf\u0cb2\u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0caa\u0ca4\u0cc7 \u0ca6\u0cbf\u0ca4\u0cbf\u0c9c\u0cbe\u0cb0\u0ccd\u0ca4\u0cbf\u0cb9\u0cb0\u0cc7 \u0964\n\u0c85\u0cb5\u0cbf\u0c9a\u0cb2\u0cad\u0c95\u0ccd\u0ca4\u0cbf\u0c95\u0cc3\u0caa\u0cbe\u0cb2\u0cc1\u0c9c\u0ca8\u0cc7\u0cb7\u0ccd\u0cb5\u0cad\u0caf\u0caa\u0ccd\u0cb0\u0ca6\u0cb9\u0cb8\u0ccd\u0ca4\u0cb8\u0cb0\u0ccb\u0cb0\u0cc1\u0cb9\u0cad\u0cbe\u0c95\u0ccd\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0cec \u0965", "malayalam": "\u0d05\u0d2f\u0d3f \u0d36\u0d30\u0d23\u0d3e\u0d17\u0d24\u0d35\u0d48\u0d30\u0d3f\u0d35\u0d27\u0d42\u0d35\u0d26\u0d28\u0d3e\u0d30\u0d4d\u0d1a\u0d3f\u0d24\u0d1a\u0d3e\u0d1f\u0d41\u0d35\u0d26\u0d3e\u0d28\u0d4d\u0d2f\u0d35\u0d3f\u0d27\u0d47\n\u0d35\u0d3f\u0d26\u0d41\u0d37\u0d35\u0d30\u0d3e\u0d30\u0d4d\u0d1a\u0d3f\u0d24\u0d2a\u0d26\u0d4d\u0d2e\u0d2a\u0d26\u0d3e\u0d16\u0d3f\u0d32\u0d35\u0d3f\u0d36\u0d4d\u0d35\u0d2a\u0d24\u0d47 \u0d26\u0d3f\u0d24\u0d3f\u0d1c\u0d3e\u0d30\u0d4d\u0d24\u0d3f\u0d39\u0d30\u0d47 \u0964\n\u0d05\u0d35\u0d3f\u0d1a\u0d32\u0d2d\u0d15\u0d4d\u0d24\u0d3f\u0d15\u0d43\u0d2a\u0d3e\u0d32\u0d41\u0d1c\u0d28\u0d47\u0d37\u0d4d\u0d35\u0d2d\u0d2f\u0d2a\u0d4d\u0d30\u0d26\u0d39\u0d38\u0d4d\u0d24\u0d38\u0d30\u0d4b\u0d30\u0d41\u0d39\u0d2d\u0d3e\u0d15\u0d4d\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d6c \u0965", "iast": "ayi \u015bara\u1e47\u0101gatavairivadh\u016bvadan\u0101rcitac\u0101\u1e6duvad\u0101nyavidhe\nvidu\u1e63avar\u0101rcitapadmapad\u0101khilavi\u015bvapate ditij\u0101rtihare |\navicalabhaktik\u1e5bp\u0101lujane\u1e63vabhayapradahastasaroruhabh\u0101k\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 6 ||"},
        draftTranslation: "Bestowing mercy even upon the pleading wives of surrendering enemies, whose lotus feet are revered by great sages, dispelling the afflictions of creation, extending the lotus hand of fearlessness to steady devotees! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 7,
        devanagariText: "\u0905\u092f\u093f \u0928\u093f\u091c\u0939\u0941\u0919\u094d\u0915\u0943\u0924\u092e\u093e\u0924\u094d\u0930\u0928\u093f\u0930\u093e\u0915\u0943\u0924\u0927\u0942\u092e\u094d\u0930\u0935\u093f\u0932\u094b\u091a\u0928\u0927\u0942\u092e\u094d\u0930\u0936\u0924\u0947\n\u0938\u092e\u0930\u0935\u093f\u0936\u094b\u0937\u093f\u0924\u0936\u094b\u0923\u093f\u0924\u092c\u0940\u091c\u0938\u092e\u0941\u0926\u094d\u092d\u0935\u092c\u0940\u091c\u0932\u0924\u093e\u0935\u093f\u0915\u0943\u0924\u0947 \u0964\n\u0936\u093f\u0935\u0936\u093f\u0935\u0936\u0941\u092e\u094d\u092d\u0928\u093f\u0936\u0941\u092e\u094d\u092d\u092e\u0939\u093e\u0939\u0935\u0924\u0930\u094d\u092a\u093f\u0924\u092d\u0942\u0924\u092a\u093f\u0936\u093e\u091a\u0930\u0924\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u096d \u0965",
        iastText: "ayi nijahu\u1e45k\u1e5btam\u0101tranir\u0101k\u1e5btadh\u016bmravil\u014dcanadh\u016bmra\u015bat\u0113\nsamaravi\u015b\u014d\u1e63ita\u015b\u014d\u1e47itab\u012bjasamudbhavab\u012bjalat\u0101vik\u1e5bt\u0113 \u0964\n\u015biva\u015biva\u015bumbhani\u015bumbhamah\u0101havatarpitabh\u016btapi\u015b\u0101carat\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 7 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c05\u0c2f\u0c3f \u0c28\u0c3f\u0c1c\u0c39\u0c41\u0c19\u0c4d\u0c15\u0c43\u0c24\u0c2e\u0c3e\u0c24\u0c4d\u0c30\u0c28\u0c3f\u0c30\u0c3e\u0c15\u0c43\u0c24\u0c27\u0c42\u0c2e\u0c4d\u0c30\u0c35\u0c3f\u0c32\u0c4b\u0c1a\u0c28\u0c27\u0c42\u0c2e\u0c4d\u0c30\u0c36\u0c24\u0c47\n\u0c38\u0c2e\u0c30\u0c35\u0c3f\u0c36\u0c4b\u0c37\u0c3f\u0c24\u0c36\u0c4b\u0c23\u0c3f\u0c24\u0c2c\u0c40\u0c1c\u0c38\u0c2e\u0c41\u0c26\u0c4d\u0c2d\u0c35\u0c2c\u0c40\u0c1c\u0c32\u0c24\u0c3e\u0c35\u0c3f\u0c15\u0c43\u0c24\u0c47 \u0964\n\u0c36\u0c3f\u0c35\u0c36\u0c3f\u0c35\u0c36\u0c41\u0c2e\u0c4d\u0c2d\u0c28\u0c3f\u0c36\u0c41\u0c2e\u0c4d\u0c2d\u0c2e\u0c39\u0c3e\u0c39\u0c35\u0c24\u0c30\u0c4d\u0c2a\u0c3f\u0c24\u0c2d\u0c42\u0c24\u0c2a\u0c3f\u0c36\u0c3e\u0c1a\u0c30\u0c24\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c6d \u0965", "tamil": "\u0b85\u0baf\u0bbf \u0ba8\u0bbf\u0b9c\u0bb9\u0bc1\u0b99\u0bcd\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0bae\u0bbe\u0ba4\u0bcd\u0bb0\u0ba8\u0bbf\u0bb0\u0bbe\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0ba4\u0bc2\u0bae\u0bcd\u0bb0\u0bb5\u0bbf\u0bb2\u0bcb\u0b9a\u0ba8\u0ba4\u0bc2\u0bae\u0bcd\u0bb0\u0bb6\u0ba4\u0bc7\n\u0bb8\u0bae\u0bb0\u0bb5\u0bbf\u0bb6\u0bcb\u0bb7\u0bbf\u0ba4\u0bb6\u0bcb\u0ba3\u0bbf\u0ba4\u0baa\u0bc0\u0b9c\u0bb8\u0bae\u0bc1\u0ba4\u0bcd\u0baa\u0bb5\u0baa\u0bc0\u0b9c\u0bb2\u0ba4\u0bbe\u0bb5\u0bbf\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0bc7 \u0964\n\u0bb6\u0bbf\u0bb5\u0bb6\u0bbf\u0bb5\u0bb6\u0bc1\u0bae\u0bcd\u0baa\u0ba8\u0bbf\u0bb6\u0bc1\u0bae\u0bcd\u0baa\u0bae\u0bb9\u0bbe\u0bb9\u0bb5\u0ba4\u0bb0\u0bcd\u0baa\u0bbf\u0ba4\u0baa\u0bc2\u0ba4\u0baa\u0bbf\u0bb6\u0bbe\u0b9a\u0bb0\u0ba4\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0bed \u0965", "kannada": "\u0c85\u0caf\u0cbf \u0ca8\u0cbf\u0c9c\u0cb9\u0cc1\u0c99\u0ccd\u0c95\u0cc3\u0ca4\u0cae\u0cbe\u0ca4\u0ccd\u0cb0\u0ca8\u0cbf\u0cb0\u0cbe\u0c95\u0cc3\u0ca4\u0ca7\u0cc2\u0cae\u0ccd\u0cb0\u0cb5\u0cbf\u0cb2\u0ccb\u0c9a\u0ca8\u0ca7\u0cc2\u0cae\u0ccd\u0cb0\u0cb6\u0ca4\u0cc7\n\u0cb8\u0cae\u0cb0\u0cb5\u0cbf\u0cb6\u0ccb\u0cb7\u0cbf\u0ca4\u0cb6\u0ccb\u0ca3\u0cbf\u0ca4\u0cac\u0cc0\u0c9c\u0cb8\u0cae\u0cc1\u0ca6\u0ccd\u0cad\u0cb5\u0cac\u0cc0\u0c9c\u0cb2\u0ca4\u0cbe\u0cb5\u0cbf\u0c95\u0cc3\u0ca4\u0cc7 \u0964\n\u0cb6\u0cbf\u0cb5\u0cb6\u0cbf\u0cb5\u0cb6\u0cc1\u0cae\u0ccd\u0cad\u0ca8\u0cbf\u0cb6\u0cc1\u0cae\u0ccd\u0cad\u0cae\u0cb9\u0cbe\u0cb9\u0cb5\u0ca4\u0cb0\u0ccd\u0caa\u0cbf\u0ca4\u0cad\u0cc2\u0ca4\u0caa\u0cbf\u0cb6\u0cbe\u0c9a\u0cb0\u0ca4\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ced \u0965", "malayalam": "\u0d05\u0d2f\u0d3f \u0d28\u0d3f\u0d1c\u0d39\u0d41\u0d19\u0d4d\u0d15\u0d43\u0d24\u0d2e\u0d3e\u0d24\u0d4d\u0d30\u0d28\u0d3f\u0d30\u0d3e\u0d15\u0d43\u0d24\u0d27\u0d42\u0d2e\u0d4d\u0d30\u0d35\u0d3f\u0d32\u0d4b\u0d1a\u0d28\u0d27\u0d42\u0d2e\u0d4d\u0d30\u0d36\u0d24\u0d47\n\u0d38\u0d2e\u0d30\u0d35\u0d3f\u0d36\u0d4b\u0d37\u0d3f\u0d24\u0d36\u0d4b\u0d23\u0d3f\u0d24\u0d2c\u0d40\u0d1c\u0d38\u0d2e\u0d41\u0d26\u0d4d\u0d2d\u0d35\u0d2c\u0d40\u0d1c\u0d32\u0d24\u0d3e\u0d35\u0d3f\u0d15\u0d43\u0d24\u0d47 \u0964\n\u0d36\u0d3f\u0d35\u0d36\u0d3f\u0d35\u0d36\u0d41\u0d2e\u0d4d\u0d2d\u0d28\u0d3f\u0d36\u0d41\u0d2e\u0d4d\u0d2d\u0d2e\u0d39\u0d3e\u0d39\u0d35\u0d24\u0d30\u0d4d\u0d2a\u0d3f\u0d24\u0d2d\u0d42\u0d24\u0d2a\u0d3f\u0d36\u0d3e\u0d1a\u0d30\u0d24\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d6d \u0965", "iast": "ayi nijahu\u1e45k\u1e5btam\u0101tranir\u0101k\u1e5btadh\u016bmravilocanadh\u016bmra\u015bate\nsamaravi\u015bo\u1e63ita\u015bo\u1e47itab\u012bjasamudbhavab\u012bjalat\u0101vik\u1e5bte |\n\u015biva\u015biva\u015bumbhani\u015bumbhamah\u0101havatarpitabh\u016btapi\u015b\u0101carate\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 7 ||"},
        draftTranslation: "Destroying the demon Dhumralochana with a solitary roar of Hum, drinking the blood of Raktabija so no demon seeds could multiply, delighting the celestial spirits in the destruction of Shumbha and Nishumbha! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 8,
        devanagariText: "\u0927\u0928\u0941\u0930\u0928\u0941\u0937\u0919\u094d\u0917\u0935\u093f\u092e\u0941\u0915\u094d\u0924\u0936\u0930\u094b\u0924\u094d\u0915\u0932\u093f\u0915\u0940\u0930\u094d\u0923\u0939\u0930\u094b\u092a\u0939\u0924\u093e\u0919\u094d\u0917\u0917\u0924\u0947\n\u0938\u0930\u0932\u0935\u093f\u091a\u093f\u0924\u094d\u0930\u0938\u0941\u0935\u0930\u094d\u0923\u0935\u093f\u091a\u093f\u0924\u094d\u0930\u0935\u093f\u091a\u093f\u0924\u094d\u0930\u092c\u092d\u094d\u0930\u0941\u0935\u093f\u091a\u093f\u0924\u094d\u0930\u0930\u0924\u0947 \u0964\n\u0905\u092e\u0943\u0924\u0930\u0938\u092a\u094d\u0930\u0938\u0943\u0924\u093e\u0935\u092f\u0935\u0947 \u092e\u0926\u093f\u0930\u0947\u0915\u094d\u0937\u0923\u0935\u093f\u0939\u094d\u0935\u0932\u092d\u0915\u094d\u0924\u0939\u0943\u0924\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u096e \u0965",
        iastText: "dhanuranu\u1e63a\u1e45gavimukta\u015bar\u014dtkalik\u012br\u1e47ahar\u014dpahat\u0101\u1e45gagat\u0113\nsaralavicitrasuvar\u1e47avicitravicitrababhruvicitrarat\u0113 \u0964\nam\u1e5btarasapras\u1e5bt\u0101vayav\u0113 madir\u0113k\u1e63a\u1e47avihvalabhaktah\u1e5bt\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 8 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c27\u0c28\u0c41\u0c30\u0c28\u0c41\u0c37\u0c19\u0c4d\u0c17\u0c35\u0c3f\u0c2e\u0c41\u0c15\u0c4d\u0c24\u0c36\u0c30\u0c4b\u0c24\u0c4d\u0c15\u0c32\u0c3f\u0c15\u0c40\u0c30\u0c4d\u0c23\u0c39\u0c30\u0c4b\u0c2a\u0c39\u0c24\u0c3e\u0c19\u0c4d\u0c17\u0c17\u0c24\u0c47\n\u0c38\u0c30\u0c32\u0c35\u0c3f\u0c1a\u0c3f\u0c24\u0c4d\u0c30\u0c38\u0c41\u0c35\u0c30\u0c4d\u0c23\u0c35\u0c3f\u0c1a\u0c3f\u0c24\u0c4d\u0c30\u0c35\u0c3f\u0c1a\u0c3f\u0c24\u0c4d\u0c30\u0c2c\u0c2d\u0c4d\u0c30\u0c41\u0c35\u0c3f\u0c1a\u0c3f\u0c24\u0c4d\u0c30\u0c30\u0c24\u0c47 \u0964\n\u0c05\u0c2e\u0c43\u0c24\u0c30\u0c38\u0c2a\u0c4d\u0c30\u0c38\u0c43\u0c24\u0c3e\u0c35\u0c2f\u0c35\u0c47 \u0c2e\u0c26\u0c3f\u0c30\u0c47\u0c15\u0c4d\u0c37\u0c23\u0c35\u0c3f\u0c39\u0c4d\u0c35\u0c32\u0c2d\u0c15\u0c4d\u0c24\u0c39\u0c43\u0c24\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c6e \u0965", "tamil": "\u0ba4\u0ba8\u0bc1\u0bb0\u0ba8\u0bc1\u0bb7\u0b99\u0bcd\u0b95\u0bb5\u0bbf\u0bae\u0bc1\u0b95\u0bcd\u0ba4\u0bb6\u0bb0\u0bcb\u0ba4\u0bcd\u0b95\u0bb2\u0bbf\u0b95\u0bc0\u0bb0\u0bcd\u0ba3\u0bb9\u0bb0\u0bcb\u0baa\u0bb9\u0ba4\u0bbe\u0b99\u0bcd\u0b95\u0b95\u0ba4\u0bc7\n\u0bb8\u0bb0\u0bb2\u0bb5\u0bbf\u0b9a\u0bbf\u0ba4\u0bcd\u0bb0\u0bb8\u0bc1\u0bb5\u0bb0\u0bcd\u0ba3\u0bb5\u0bbf\u0b9a\u0bbf\u0ba4\u0bcd\u0bb0\u0bb5\u0bbf\u0b9a\u0bbf\u0ba4\u0bcd\u0bb0\u0baa\u0baa\u0bcd\u0bb0\u0bc1\u0bb5\u0bbf\u0b9a\u0bbf\u0ba4\u0bcd\u0bb0\u0bb0\u0ba4\u0bc7 \u0964\n\u0b85\u0bae\u0bcd\u0bb0\u0bc1'\u0ba4\u0bb0\u0bb8\u0baa\u0bcd\u0bb0\u0bb8\u0bcd\u0bb0\u0bc1'\u0ba4\u0bbe\u0bb5\u0baf\u0bb5\u0bc7 \u0bae\u0ba4\u0bbf\u0bb0\u0bc7\u0b95\u0bcd\u0bb7\u0ba3\u0bb5\u0bbf\u0bb9\u0bcd\u0bb5\u0bb2\u0baa\u0b95\u0bcd\u0ba4\u0bb9\u0bcd\u0bb0\u0bc1'\u0ba4\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0bee \u0965", "kannada": "\u0ca7\u0ca8\u0cc1\u0cb0\u0ca8\u0cc1\u0cb7\u0c99\u0ccd\u0c97\u0cb5\u0cbf\u0cae\u0cc1\u0c95\u0ccd\u0ca4\u0cb6\u0cb0\u0ccb\u0ca4\u0ccd\u0c95\u0cb2\u0cbf\u0c95\u0cc0\u0cb0\u0ccd\u0ca3\u0cb9\u0cb0\u0ccb\u0caa\u0cb9\u0ca4\u0cbe\u0c99\u0ccd\u0c97\u0c97\u0ca4\u0cc7\n\u0cb8\u0cb0\u0cb2\u0cb5\u0cbf\u0c9a\u0cbf\u0ca4\u0ccd\u0cb0\u0cb8\u0cc1\u0cb5\u0cb0\u0ccd\u0ca3\u0cb5\u0cbf\u0c9a\u0cbf\u0ca4\u0ccd\u0cb0\u0cb5\u0cbf\u0c9a\u0cbf\u0ca4\u0ccd\u0cb0\u0cac\u0cad\u0ccd\u0cb0\u0cc1\u0cb5\u0cbf\u0c9a\u0cbf\u0ca4\u0ccd\u0cb0\u0cb0\u0ca4\u0cc7 \u0964\n\u0c85\u0cae\u0cc3\u0ca4\u0cb0\u0cb8\u0caa\u0ccd\u0cb0\u0cb8\u0cc3\u0ca4\u0cbe\u0cb5\u0caf\u0cb5\u0cc7 \u0cae\u0ca6\u0cbf\u0cb0\u0cc7\u0c95\u0ccd\u0cb7\u0ca3\u0cb5\u0cbf\u0cb9\u0ccd\u0cb5\u0cb2\u0cad\u0c95\u0ccd\u0ca4\u0cb9\u0cc3\u0ca4\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0cee \u0965", "malayalam": "\u0d27\u0d28\u0d41\u0d30\u0d28\u0d41\u0d37\u0d19\u0d4d\u0d17\u0d35\u0d3f\u0d2e\u0d41\u0d15\u0d4d\u0d24\u0d36\u0d30\u0d4b\u0d24\u0d4d\u0d15\u0d32\u0d3f\u0d15\u0d40\u0d30\u0d4d\u0d23\u0d39\u0d30\u0d4b\u0d2a\u0d39\u0d24\u0d3e\u0d19\u0d4d\u0d17\u0d17\u0d24\u0d47\n\u0d38\u0d30\u0d32\u0d35\u0d3f\u0d1a\u0d3f\u0d24\u0d4d\u0d30\u0d38\u0d41\u0d35\u0d30\u0d4d\u0d23\u0d35\u0d3f\u0d1a\u0d3f\u0d24\u0d4d\u0d30\u0d35\u0d3f\u0d1a\u0d3f\u0d24\u0d4d\u0d30\u0d2c\u0d2d\u0d4d\u0d30\u0d41\u0d35\u0d3f\u0d1a\u0d3f\u0d24\u0d4d\u0d30\u0d30\u0d24\u0d47 \u0964\n\u0d05\u0d2e\u0d43\u0d24\u0d30\u0d38\u0d2a\u0d4d\u0d30\u0d38\u0d43\u0d24\u0d3e\u0d35\u0d2f\u0d35\u0d47 \u0d2e\u0d26\u0d3f\u0d30\u0d47\u0d15\u0d4d\u0d37\u0d23\u0d35\u0d3f\u0d39\u0d4d\u0d35\u0d32\u0d2d\u0d15\u0d4d\u0d24\u0d39\u0d43\u0d24\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d6e \u0965", "iast": "dhanuranu\u1e63a\u1e45gavimukta\u015barotkalik\u012br\u1e47aharopahat\u0101\u1e45gagate\nsaralavicitrasuvar\u1e47avicitravicitrababhruvicitrarate |\nam\u1e5btarasapras\u1e5bt\u0101vayave madirek\u1e63a\u1e47avihvalabhaktah\u1e5bte\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 8 ||"},
        draftTranslation: "Unleashing showers of arrows from Your celestial bow, radiant in dazzling golden ornaments of intricate design, whose divine limbs overflow with nectar, enchanting the hearts of ardent devotees! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 9,
        devanagariText: "\u0938\u0941\u0930\u0932\u0932\u0928\u093e\u0924\u0924\u0925\u0947\u092f\u093f\u0924\u0925\u0947\u092f\u093f\u0924\u0925\u093e\u092d\u093f\u0928\u092f\u094b\u0924\u094d\u0924\u0930\u0928\u0943\u0924\u094d\u092f\u0930\u0924\u0947\n\u0939\u093e\u0938\u0935\u093f\u0932\u093e\u0938\u0938\u092e\u093e\u0915\u0941\u0932\u092e\u093e\u0928\u0938\u092e\u0919\u094d\u0917\u0932\u0917\u093e\u0928\u0938\u0941\u0917\u0940\u0924\u0930\u0924\u0947 \u0964\n\u0915\u094d\u0935\u0923\u093f\u0924\u093e\u0938\u0941\u092a\u0942\u0930\u0935\u093f\u091a\u093f\u0924\u094d\u0930\u0915\u0919\u094d\u0915\u0923\u0915\u0942\u091c\u093f\u0924\u0928\u0942\u092a\u0941\u0930\u0928\u093e\u0926\u0930\u0924\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u096f \u0965",
        iastText: "suralalan\u0101tatath\u0113yitath\u0113yitath\u0101bhinay\u014dttaran\u1e5btyarat\u0113\nh\u0101savil\u0101sasam\u0101kulam\u0101nasama\u1e45galag\u0101nasug\u012btarat\u0113 \u0964\nkva\u1e47it\u0101sup\u016bravicitraka\u1e45ka\u1e47ak\u016bjitan\u016bpuran\u0101darat\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 9 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c38\u0c41\u0c30\u0c32\u0c32\u0c28\u0c3e\u0c24\u0c24\u0c25\u0c47\u0c2f\u0c3f\u0c24\u0c25\u0c47\u0c2f\u0c3f\u0c24\u0c25\u0c3e\u0c2d\u0c3f\u0c28\u0c2f\u0c4b\u0c24\u0c4d\u0c24\u0c30\u0c28\u0c43\u0c24\u0c4d\u0c2f\u0c30\u0c24\u0c47\n\u0c39\u0c3e\u0c38\u0c35\u0c3f\u0c32\u0c3e\u0c38\u0c38\u0c2e\u0c3e\u0c15\u0c41\u0c32\u0c2e\u0c3e\u0c28\u0c38\u0c2e\u0c19\u0c4d\u0c17\u0c32\u0c17\u0c3e\u0c28\u0c38\u0c41\u0c17\u0c40\u0c24\u0c30\u0c24\u0c47 \u0964\n\u0c15\u0c4d\u0c35\u0c23\u0c3f\u0c24\u0c3e\u0c38\u0c41\u0c2a\u0c42\u0c30\u0c35\u0c3f\u0c1a\u0c3f\u0c24\u0c4d\u0c30\u0c15\u0c19\u0c4d\u0c15\u0c23\u0c15\u0c42\u0c1c\u0c3f\u0c24\u0c28\u0c42\u0c2a\u0c41\u0c30\u0c28\u0c3e\u0c26\u0c30\u0c24\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c6f \u0965", "tamil": "\u0bb8\u0bc1\u0bb0\u0bb2\u0bb2\u0ba8\u0bbe\u0ba4\u0ba4\u0ba4\u0bc7\u0baf\u0bbf\u0ba4\u0ba4\u0bc7\u0baf\u0bbf\u0ba4\u0ba4\u0bbe\u0baa\u0bbf\u0ba8\u0baf\u0bcb\u0ba4\u0bcd\u0ba4\u0bb0\u0ba8\u0bcd\u0bb0\u0bc1'\u0ba4\u0bcd\u0baf\u0bb0\u0ba4\u0bc7\n\u0bb9\u0bbe\u0bb8\u0bb5\u0bbf\u0bb2\u0bbe\u0bb8\u0bb8\u0bae\u0bbe\u0b95\u0bc1\u0bb2\u0bae\u0bbe\u0ba8\u0bb8\u0bae\u0b99\u0bcd\u0b95\u0bb2\u0b95\u0bbe\u0ba8\u0bb8\u0bc1\u0b95\u0bc0\u0ba4\u0bb0\u0ba4\u0bc7 \u0964\n\u0b95\u0bcd\u0bb5\u0ba3\u0bbf\u0ba4\u0bbe\u0bb8\u0bc1\u0baa\u0bc2\u0bb0\u0bb5\u0bbf\u0b9a\u0bbf\u0ba4\u0bcd\u0bb0\u0b95\u0b99\u0bcd\u0b95\u0ba3\u0b95\u0bc2\u0b9c\u0bbf\u0ba4\u0ba8\u0bc2\u0baa\u0bc1\u0bb0\u0ba8\u0bbe\u0ba4\u0bb0\u0ba4\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0bef \u0965", "kannada": "\u0cb8\u0cc1\u0cb0\u0cb2\u0cb2\u0ca8\u0cbe\u0ca4\u0ca4\u0ca5\u0cc7\u0caf\u0cbf\u0ca4\u0ca5\u0cc7\u0caf\u0cbf\u0ca4\u0ca5\u0cbe\u0cad\u0cbf\u0ca8\u0caf\u0ccb\u0ca4\u0ccd\u0ca4\u0cb0\u0ca8\u0cc3\u0ca4\u0ccd\u0caf\u0cb0\u0ca4\u0cc7\n\u0cb9\u0cbe\u0cb8\u0cb5\u0cbf\u0cb2\u0cbe\u0cb8\u0cb8\u0cae\u0cbe\u0c95\u0cc1\u0cb2\u0cae\u0cbe\u0ca8\u0cb8\u0cae\u0c99\u0ccd\u0c97\u0cb2\u0c97\u0cbe\u0ca8\u0cb8\u0cc1\u0c97\u0cc0\u0ca4\u0cb0\u0ca4\u0cc7 \u0964\n\u0c95\u0ccd\u0cb5\u0ca3\u0cbf\u0ca4\u0cbe\u0cb8\u0cc1\u0caa\u0cc2\u0cb0\u0cb5\u0cbf\u0c9a\u0cbf\u0ca4\u0ccd\u0cb0\u0c95\u0c99\u0ccd\u0c95\u0ca3\u0c95\u0cc2\u0c9c\u0cbf\u0ca4\u0ca8\u0cc2\u0caa\u0cc1\u0cb0\u0ca8\u0cbe\u0ca6\u0cb0\u0ca4\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0cef \u0965", "malayalam": "\u0d38\u0d41\u0d30\u0d32\u0d32\u0d28\u0d3e\u0d24\u0d24\u0d25\u0d47\u0d2f\u0d3f\u0d24\u0d25\u0d47\u0d2f\u0d3f\u0d24\u0d25\u0d3e\u0d2d\u0d3f\u0d28\u0d2f\u0d4b\u0d24\u0d4d\u0d24\u0d30\u0d28\u0d43\u0d24\u0d4d\u0d2f\u0d30\u0d24\u0d47\n\u0d39\u0d3e\u0d38\u0d35\u0d3f\u0d32\u0d3e\u0d38\u0d38\u0d2e\u0d3e\u0d15\u0d41\u0d32\u0d2e\u0d3e\u0d28\u0d38\u0d2e\u0d19\u0d4d\u0d17\u0d32\u0d17\u0d3e\u0d28\u0d38\u0d41\u0d17\u0d40\u0d24\u0d30\u0d24\u0d47 \u0964\n\u0d15\u0d4d\u0d35\u0d23\u0d3f\u0d24\u0d3e\u0d38\u0d41\u0d2a\u0d42\u0d30\u0d35\u0d3f\u0d1a\u0d3f\u0d24\u0d4d\u0d30\u0d15\u0d19\u0d4d\u0d15\u0d23\u0d15\u0d42\u0d1c\u0d3f\u0d24\u0d28\u0d42\u0d2a\u0d41\u0d30\u0d28\u0d3e\u0d26\u0d30\u0d24\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d6f \u0965", "iast": "suralalan\u0101tatatheyitatheyitath\u0101bhinayottaran\u1e5btyarate\nh\u0101savil\u0101sasam\u0101kulam\u0101nasama\u1e45galag\u0101nasug\u012btarate |\nkva\u1e47it\u0101sup\u016bravicitraka\u1e45ka\u1e47ak\u016bjitan\u016bpuran\u0101darate\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 9 ||"},
        draftTranslation: "Rejoicing in the dramatic rhythmic dancing of celestial maidens to rhythmic beats, delighting in auspicious songs of victory, adorned with chiming bangles and tinkling anklets! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 10,
        devanagariText: "\u0905\u092f\u093f \u0938\u0941\u092e\u0928\u0903\u0938\u0941\u092e\u0928\u0903\u0938\u0941\u092e\u0928\u0903\u0938\u0941\u092e\u0928\u0903\u0938\u0941\u092e\u0928\u094b\u0939\u0930\u0915\u093e\u0928\u094d\u0924\u093f\u092f\u0941\u0924\u0947\n\u0936\u094d\u0930\u093f\u0924\u0930\u091c\u0928\u0940\u0930\u091c\u0928\u0940\u0930\u091c\u0928\u0940\u0930\u091c\u0928\u0940\u0930\u091c\u0928\u0940\u0915\u0930\u0935\u0915\u094d\u0924\u094d\u0930\u0935\u0943\u0924\u0947 \u0964\n\u0938\u0941\u0928\u092f\u0928\u0935\u093f\u092d\u094d\u0930\u092e\u0930\u092d\u094d\u0930\u092e\u0930\u092d\u094d\u0930\u092e\u0930\u092d\u094d\u0930\u092e\u0930\u092d\u094d\u0930\u092e\u0930\u093e\u0927\u093f\u092a\u0924\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0967\u0966 \u0965",
        iastText: "ayi sumana\u1e25sumana\u1e25sumana\u1e25sumana\u1e25suman\u014dharak\u0101ntiyut\u0113\n\u015britarajan\u012brajan\u012brajan\u012brajan\u012brajan\u012bkaravakrav\u1e5bt\u0113 \u0964\nsunayanavibhramarabhramarabhramarabhramarabhramar\u0101dhipat\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 10 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c05\u0c2f\u0c3f \u0c38\u0c41\u0c2e\u0c28\u0c03\u0c38\u0c41\u0c2e\u0c28\u0c03\u0c38\u0c41\u0c2e\u0c28\u0c03\u0c38\u0c41\u0c2e\u0c28\u0c03\u0c38\u0c41\u0c2e\u0c28\u0c4b\u0c39\u0c30\u0c15\u0c3e\u0c28\u0c4d\u0c24\u0c3f\u0c2f\u0c41\u0c24\u0c47\n\u0c36\u0c4d\u0c30\u0c3f\u0c24\u0c30\u0c1c\u0c28\u0c40\u0c30\u0c1c\u0c28\u0c40\u0c30\u0c1c\u0c28\u0c40\u0c30\u0c1c\u0c28\u0c40\u0c30\u0c1c\u0c28\u0c40\u0c15\u0c30\u0c35\u0c15\u0c4d\u0c24\u0c4d\u0c30\u0c35\u0c43\u0c24\u0c47 \u0964\n\u0c38\u0c41\u0c28\u0c2f\u0c28\u0c35\u0c3f\u0c2d\u0c4d\u0c30\u0c2e\u0c30\u0c2d\u0c4d\u0c30\u0c2e\u0c30\u0c2d\u0c4d\u0c30\u0c2e\u0c30\u0c2d\u0c4d\u0c30\u0c2e\u0c30\u0c2d\u0c4d\u0c30\u0c2e\u0c30\u0c3e\u0c27\u0c3f\u0c2a\u0c24\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c67\u0c66 \u0965", "tamil": "\u0b85\u0baf\u0bbf \u0bb8\u0bc1\u0bae\u0ba8\u0b83\u0bb8\u0bc1\u0bae\u0ba8\u0b83\u0bb8\u0bc1\u0bae\u0ba8\u0b83\u0bb8\u0bc1\u0bae\u0ba8\u0b83\u0bb8\u0bc1\u0bae\u0ba8\u0bcb\u0bb9\u0bb0\u0b95\u0bbe\u0ba8\u0bcd\u0ba4\u0bbf\u0baf\u0bc1\u0ba4\u0bc7\n\u0bb6\u0bcd\u0bb0\u0bbf\u0ba4\u0bb0\u0b9c\u0ba8\u0bc0\u0bb0\u0b9c\u0ba8\u0bc0\u0bb0\u0b9c\u0ba8\u0bc0\u0bb0\u0b9c\u0ba8\u0bc0\u0bb0\u0b9c\u0ba8\u0bc0\u0b95\u0bb0\u0bb5\u0b95\u0bcd\u0ba4\u0bcd\u0bb0\u0bb5\u0bcd\u0bb0\u0bc1'\u0ba4\u0bc7 \u0964\n\u0bb8\u0bc1\u0ba8\u0baf\u0ba8\u0bb5\u0bbf\u0baa\u0bcd\u0bb0\u0bae\u0bb0\u0baa\u0bcd\u0bb0\u0bae\u0bb0\u0baa\u0bcd\u0bb0\u0bae\u0bb0\u0baa\u0bcd\u0bb0\u0bae\u0bb0\u0baa\u0bcd\u0bb0\u0bae\u0bb0\u0bbe\u0ba4\u0bbf\u0baa\u0ba4\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be7\u0be6 \u0965", "kannada": "\u0c85\u0caf\u0cbf \u0cb8\u0cc1\u0cae\u0ca8\u0c83\u0cb8\u0cc1\u0cae\u0ca8\u0c83\u0cb8\u0cc1\u0cae\u0ca8\u0c83\u0cb8\u0cc1\u0cae\u0ca8\u0c83\u0cb8\u0cc1\u0cae\u0ca8\u0ccb\u0cb9\u0cb0\u0c95\u0cbe\u0ca8\u0ccd\u0ca4\u0cbf\u0caf\u0cc1\u0ca4\u0cc7\n\u0cb6\u0ccd\u0cb0\u0cbf\u0ca4\u0cb0\u0c9c\u0ca8\u0cc0\u0cb0\u0c9c\u0ca8\u0cc0\u0cb0\u0c9c\u0ca8\u0cc0\u0cb0\u0c9c\u0ca8\u0cc0\u0cb0\u0c9c\u0ca8\u0cc0\u0c95\u0cb0\u0cb5\u0c95\u0ccd\u0ca4\u0ccd\u0cb0\u0cb5\u0cc3\u0ca4\u0cc7 \u0964\n\u0cb8\u0cc1\u0ca8\u0caf\u0ca8\u0cb5\u0cbf\u0cad\u0ccd\u0cb0\u0cae\u0cb0\u0cad\u0ccd\u0cb0\u0cae\u0cb0\u0cad\u0ccd\u0cb0\u0cae\u0cb0\u0cad\u0ccd\u0cb0\u0cae\u0cb0\u0cad\u0ccd\u0cb0\u0cae\u0cb0\u0cbe\u0ca7\u0cbf\u0caa\u0ca4\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce7\u0ce6 \u0965", "malayalam": "\u0d05\u0d2f\u0d3f \u0d38\u0d41\u0d2e\u0d28\u0d03\u0d38\u0d41\u0d2e\u0d28\u0d03\u0d38\u0d41\u0d2e\u0d28\u0d03\u0d38\u0d41\u0d2e\u0d28\u0d03\u0d38\u0d41\u0d2e\u0d28\u0d4b\u0d39\u0d30\u0d15\u0d3e\u0d28\u0d4d\u0d24\u0d3f\u0d2f\u0d41\u0d24\u0d47\n\u0d36\u0d4d\u0d30\u0d3f\u0d24\u0d30\u0d1c\u0d28\u0d40\u0d30\u0d1c\u0d28\u0d40\u0d30\u0d1c\u0d28\u0d40\u0d30\u0d1c\u0d28\u0d40\u0d30\u0d1c\u0d28\u0d40\u0d15\u0d30\u0d35\u0d15\u0d4d\u0d24\u0d4d\u0d30\u0d35\u0d43\u0d24\u0d47 \u0964\n\u0d38\u0d41\u0d28\u0d2f\u0d28\u0d35\u0d3f\u0d2d\u0d4d\u0d30\u0d2e\u0d30\u0d2d\u0d4d\u0d30\u0d2e\u0d30\u0d2d\u0d4d\u0d30\u0d2e\u0d30\u0d2d\u0d4d\u0d30\u0d2e\u0d30\u0d2d\u0d4d\u0d30\u0d2e\u0d30\u0d3e\u0d27\u0d3f\u0d2a\u0d24\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d67\u0d66 \u0965", "iast": "ayi sumana\u1e25sumana\u1e25sumana\u1e25sumana\u1e25sumanoharak\u0101ntiyute\n\u015britarajan\u012brajan\u012brajan\u012brajan\u012brajan\u012bkaravaktrav\u1e5bte |\nsunayanavibhramarabhramarabhramarabhramarabhramar\u0101dhipate\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 10 ||"},
        draftTranslation: "Endowed with mesmerizing grace resembling the sweetest blossoms, face glowing like the tranquil moon, eyes fluttering with charming glances like black honeybees circling a lotus! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 11,
        devanagariText: "\u0938\u0939\u093f\u0924\u092e\u0939\u093e\u0939\u0935\u092e\u0932\u094d\u0932\u092e\u0924\u0932\u094d\u0932\u093f\u0915\u092e\u0932\u094d\u0932\u093f\u0924\u0930\u0932\u094d\u0932\u0915\u092d\u0932\u094d\u0932\u0930\u0924\u0947\n\u0935\u093f\u0930\u091a\u093f\u0924\u0935\u0932\u094d\u0932\u093f\u0915\u092a\u0932\u094d\u0932\u093f\u0915\u092e\u0932\u094d\u0932\u093f\u0915\u091d\u093f\u0932\u094d\u0932\u093f\u0915\u092d\u093f\u0932\u094d\u0932\u093f\u0915\u0935\u0930\u094d\u0917\u0935\u0943\u0924\u0947 \u0964\n\u0936\u093f\u0924\u0915\u0943\u0924\u092b\u0941\u0932\u094d\u0932\u0938\u092e\u0941\u0932\u094d\u0932\u0938\u093f\u0924\u093e\u0930\u0941\u0923\u0924\u0932\u094d\u0932\u091c\u092a\u0932\u094d\u0932\u0935\u092a\u093e\u0926\u092f\u0941\u0917\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0967\u0967 \u0965",
        iastText: "sahitamah\u0101havamallamatallikamallitarallakabhallar\u0113\nviracitavallikapallikamallikajhillikabhillikavargav\u1e5bt\u0113 \u0964\n\u015bitak\u1e5btaphullasamullasit\u0101ru\u1e47atallajapallavap\u0101dayug\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 11 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c38\u0c39\u0c3f\u0c24\u0c2e\u0c39\u0c3e\u0c39\u0c35\u0c2e\u0c32\u0c4d\u0c32\u0c2e\u0c24\u0c32\u0c4d\u0c32\u0c3f\u0c15\u0c2e\u0c32\u0c4d\u0c32\u0c3f\u0c24\u0c30\u0c32\u0c4d\u0c32\u0c15\u0c2d\u0c32\u0c4d\u0c32\u0c30\u0c24\u0c47\n\u0c35\u0c3f\u0c30\u0c1a\u0c3f\u0c24\u0c35\u0c32\u0c4d\u0c32\u0c3f\u0c15\u0c2a\u0c32\u0c4d\u0c32\u0c3f\u0c15\u0c2e\u0c32\u0c4d\u0c32\u0c3f\u0c15\u0c1d\u0c3f\u0c32\u0c4d\u0c32\u0c3f\u0c15\u0c2d\u0c3f\u0c32\u0c4d\u0c32\u0c3f\u0c15\u0c35\u0c30\u0c4d\u0c17\u0c35\u0c43\u0c24\u0c47 \u0964\n\u0c36\u0c3f\u0c24\u0c15\u0c43\u0c24\u0c2b\u0c41\u0c32\u0c4d\u0c32\u0c38\u0c2e\u0c41\u0c32\u0c4d\u0c32\u0c38\u0c3f\u0c24\u0c3e\u0c30\u0c41\u0c23\u0c24\u0c32\u0c4d\u0c32\u0c1c\u0c2a\u0c32\u0c4d\u0c32\u0c35\u0c2a\u0c3e\u0c26\u0c2f\u0c41\u0c17\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c67\u0c67 \u0965", "tamil": "\u0bb8\u0bb9\u0bbf\u0ba4\u0bae\u0bb9\u0bbe\u0bb9\u0bb5\u0bae\u0bb2\u0bcd\u0bb2\u0bae\u0ba4\u0bb2\u0bcd\u0bb2\u0bbf\u0b95\u0bae\u0bb2\u0bcd\u0bb2\u0bbf\u0ba4\u0bb0\u0bb2\u0bcd\u0bb2\u0b95\u0baa\u0bb2\u0bcd\u0bb2\u0bb0\u0ba4\u0bc7\n\u0bb5\u0bbf\u0bb0\u0b9a\u0bbf\u0ba4\u0bb5\u0bb2\u0bcd\u0bb2\u0bbf\u0b95\u0baa\u0bb2\u0bcd\u0bb2\u0bbf\u0b95\u0bae\u0bb2\u0bcd\u0bb2\u0bbf\u0b95\u0b9a\u0bbf\u0bb2\u0bcd\u0bb2\u0bbf\u0b95\u0baa\u0bbf\u0bb2\u0bcd\u0bb2\u0bbf\u0b95\u0bb5\u0bb0\u0bcd\u0b95\u0bb5\u0bcd\u0bb0\u0bc1'\u0ba4\u0bc7 \u0964\n\u0bb6\u0bbf\u0ba4\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0baa\u0bc1\u0bb2\u0bcd\u0bb2\u0bb8\u0bae\u0bc1\u0bb2\u0bcd\u0bb2\u0bb8\u0bbf\u0ba4\u0bbe\u0bb0\u0bc1\u0ba3\u0ba4\u0bb2\u0bcd\u0bb2\u0b9c\u0baa\u0bb2\u0bcd\u0bb2\u0bb5\u0baa\u0bbe\u0ba4\u0baf\u0bc1\u0b95\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be7\u0be7 \u0965", "kannada": "\u0cb8\u0cb9\u0cbf\u0ca4\u0cae\u0cb9\u0cbe\u0cb9\u0cb5\u0cae\u0cb2\u0ccd\u0cb2\u0cae\u0ca4\u0cb2\u0ccd\u0cb2\u0cbf\u0c95\u0cae\u0cb2\u0ccd\u0cb2\u0cbf\u0ca4\u0cb0\u0cb2\u0ccd\u0cb2\u0c95\u0cad\u0cb2\u0ccd\u0cb2\u0cb0\u0ca4\u0cc7\n\u0cb5\u0cbf\u0cb0\u0c9a\u0cbf\u0ca4\u0cb5\u0cb2\u0ccd\u0cb2\u0cbf\u0c95\u0caa\u0cb2\u0ccd\u0cb2\u0cbf\u0c95\u0cae\u0cb2\u0ccd\u0cb2\u0cbf\u0c95\u0c9d\u0cbf\u0cb2\u0ccd\u0cb2\u0cbf\u0c95\u0cad\u0cbf\u0cb2\u0ccd\u0cb2\u0cbf\u0c95\u0cb5\u0cb0\u0ccd\u0c97\u0cb5\u0cc3\u0ca4\u0cc7 \u0964\n\u0cb6\u0cbf\u0ca4\u0c95\u0cc3\u0ca4\u0cab\u0cc1\u0cb2\u0ccd\u0cb2\u0cb8\u0cae\u0cc1\u0cb2\u0ccd\u0cb2\u0cb8\u0cbf\u0ca4\u0cbe\u0cb0\u0cc1\u0ca3\u0ca4\u0cb2\u0ccd\u0cb2\u0c9c\u0caa\u0cb2\u0ccd\u0cb2\u0cb5\u0caa\u0cbe\u0ca6\u0caf\u0cc1\u0c97\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce7\u0ce7 \u0965", "malayalam": "\u0d38\u0d39\u0d3f\u0d24\u0d2e\u0d39\u0d3e\u0d39\u0d35\u0d2e\u0d32\u0d4d\u0d32\u0d2e\u0d24\u0d32\u0d4d\u0d32\u0d3f\u0d15\u0d2e\u0d32\u0d4d\u0d32\u0d3f\u0d24\u0d30\u0d32\u0d4d\u0d32\u0d15\u0d2d\u0d32\u0d4d\u0d32\u0d30\u0d24\u0d47\n\u0d35\u0d3f\u0d30\u0d1a\u0d3f\u0d24\u0d35\u0d32\u0d4d\u0d32\u0d3f\u0d15\u0d2a\u0d32\u0d4d\u0d32\u0d3f\u0d15\u0d2e\u0d32\u0d4d\u0d32\u0d3f\u0d15\u0d1d\u0d3f\u0d32\u0d4d\u0d32\u0d3f\u0d15\u0d2d\u0d3f\u0d32\u0d4d\u0d32\u0d3f\u0d15\u0d35\u0d30\u0d4d\u0d17\u0d35\u0d43\u0d24\u0d47 \u0964\n\u0d36\u0d3f\u0d24\u0d15\u0d43\u0d24\u0d2b\u0d41\u0d32\u0d4d\u0d32\u0d38\u0d2e\u0d41\u0d32\u0d4d\u0d32\u0d38\u0d3f\u0d24\u0d3e\u0d30\u0d41\u0d23\u0d24\u0d32\u0d4d\u0d32\u0d1c\u0d2a\u0d32\u0d4d\u0d32\u0d35\u0d2a\u0d3e\u0d26\u0d2f\u0d41\u0d17\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d67\u0d67 \u0965", "iast": "sahitamah\u0101havamallamatallikamallitarallakabhallarate\nviracitavallikapallikamallikajhillikabhillikavargav\u1e5bte |\n\u015bitak\u1e5btaphullasamullasit\u0101ru\u1e47atallajapallavap\u0101dayuge\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 11 ||"},
        draftTranslation: "Wielding spears and arrows against the formidable champion wrestlers of the demon army, worshipped by simple forest tribes, whose lotus feet glow rosy-red like freshly sprouted tender leaves! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 12,
        devanagariText: "\u0905\u0935\u093f\u0930\u0932\u0917\u0923\u094d\u0921\u0917\u0932\u0928\u094d\u092e\u0926\u092e\u0947\u0926\u0941\u0930\u092e\u0924\u094d\u0924\u092e\u0924\u094d\u0924\u0919\u094d\u0917\u091c\u0930\u093e\u091c\u092a\u0924\u0947\n\u0924\u094d\u0930\u093f\u092d\u0941\u0935\u0928\u092d\u0942\u0937\u0923\u092d\u0942\u0924\u0915\u0932\u093e\u0928\u093f\u0927\u093f\u0930\u0942\u092a\u092a\u092f\u094b\u0928\u093f\u0927\u093f\u0930\u093e\u091c\u0938\u0941\u0924\u0947 \u0964\n\u0905\u092f\u093f \u0938\u0941\u0926\u0924\u0940\u091c\u0928\u0932\u093e\u0932\u0938\u092e\u093e\u0928\u0938\u092e\u094b\u0939\u0928\u092e\u0928\u094d\u092e\u0925\u0930\u093e\u091c\u0938\u0941\u0924\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0967\u0968 \u0965",
        iastText: "aviralaga\u1e47\u1e0dagalanmadam\u0113duramattamatta\u1e45gajar\u0101japat\u0113\ntribhuvanabh\u016b\u1e63a\u1e47abh\u016btakal\u0101nidhir\u016bpapay\u014dnidhir\u0101jasut\u0113 \u0964\nayi sudat\u012bjanal\u0101lasam\u0101nasam\u014dhanamanmathar\u0101jasut\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 12 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c05\u0c35\u0c3f\u0c30\u0c32\u0c17\u0c23\u0c4d\u0c21\u0c17\u0c32\u0c28\u0c4d\u0c2e\u0c26\u0c2e\u0c47\u0c26\u0c41\u0c30\u0c2e\u0c24\u0c4d\u0c24\u0c2e\u0c24\u0c4d\u0c24\u0c19\u0c4d\u0c17\u0c1c\u0c30\u0c3e\u0c1c\u0c2a\u0c24\u0c47\n\u0c24\u0c4d\u0c30\u0c3f\u0c2d\u0c41\u0c35\u0c28\u0c2d\u0c42\u0c37\u0c23\u0c2d\u0c42\u0c24\u0c15\u0c32\u0c3e\u0c28\u0c3f\u0c27\u0c3f\u0c30\u0c42\u0c2a\u0c2a\u0c2f\u0c4b\u0c28\u0c3f\u0c27\u0c3f\u0c30\u0c3e\u0c1c\u0c38\u0c41\u0c24\u0c47 \u0964\n\u0c05\u0c2f\u0c3f \u0c38\u0c41\u0c26\u0c24\u0c40\u0c1c\u0c28\u0c32\u0c3e\u0c32\u0c38\u0c2e\u0c3e\u0c28\u0c38\u0c2e\u0c4b\u0c39\u0c28\u0c2e\u0c28\u0c4d\u0c2e\u0c25\u0c30\u0c3e\u0c1c\u0c38\u0c41\u0c24\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c67\u0c68 \u0965", "tamil": "\u0b85\u0bb5\u0bbf\u0bb0\u0bb2\u0b95\u0ba3\u0bcd\u0b9f\u0b95\u0bb2\u0ba8\u0bcd\u0bae\u0ba4\u0bae\u0bc7\u0ba4\u0bc1\u0bb0\u0bae\u0ba4\u0bcd\u0ba4\u0bae\u0ba4\u0bcd\u0ba4\u0b99\u0bcd\u0b95\u0b9c\u0bb0\u0bbe\u0b9c\u0baa\u0ba4\u0bc7\n\u0ba4\u0bcd\u0bb0\u0bbf\u0baa\u0bc1\u0bb5\u0ba8\u0baa\u0bc2\u0bb7\u0ba3\u0baa\u0bc2\u0ba4\u0b95\u0bb2\u0bbe\u0ba8\u0bbf\u0ba4\u0bbf\u0bb0\u0bc2\u0baa\u0baa\u0baf\u0bcb\u0ba8\u0bbf\u0ba4\u0bbf\u0bb0\u0bbe\u0b9c\u0bb8\u0bc1\u0ba4\u0bc7 \u0964\n\u0b85\u0baf\u0bbf \u0bb8\u0bc1\u0ba4\u0ba4\u0bc0\u0b9c\u0ba8\u0bb2\u0bbe\u0bb2\u0bb8\u0bae\u0bbe\u0ba8\u0bb8\u0bae\u0bcb\u0bb9\u0ba8\u0bae\u0ba8\u0bcd\u0bae\u0ba4\u0bb0\u0bbe\u0b9c\u0bb8\u0bc1\u0ba4\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be7\u0be8 \u0965", "kannada": "\u0c85\u0cb5\u0cbf\u0cb0\u0cb2\u0c97\u0ca3\u0ccd\u0ca1\u0c97\u0cb2\u0ca8\u0ccd\u0cae\u0ca6\u0cae\u0cc7\u0ca6\u0cc1\u0cb0\u0cae\u0ca4\u0ccd\u0ca4\u0cae\u0ca4\u0ccd\u0ca4\u0c99\u0ccd\u0c97\u0c9c\u0cb0\u0cbe\u0c9c\u0caa\u0ca4\u0cc7\n\u0ca4\u0ccd\u0cb0\u0cbf\u0cad\u0cc1\u0cb5\u0ca8\u0cad\u0cc2\u0cb7\u0ca3\u0cad\u0cc2\u0ca4\u0c95\u0cb2\u0cbe\u0ca8\u0cbf\u0ca7\u0cbf\u0cb0\u0cc2\u0caa\u0caa\u0caf\u0ccb\u0ca8\u0cbf\u0ca7\u0cbf\u0cb0\u0cbe\u0c9c\u0cb8\u0cc1\u0ca4\u0cc7 \u0964\n\u0c85\u0caf\u0cbf \u0cb8\u0cc1\u0ca6\u0ca4\u0cc0\u0c9c\u0ca8\u0cb2\u0cbe\u0cb2\u0cb8\u0cae\u0cbe\u0ca8\u0cb8\u0cae\u0ccb\u0cb9\u0ca8\u0cae\u0ca8\u0ccd\u0cae\u0ca5\u0cb0\u0cbe\u0c9c\u0cb8\u0cc1\u0ca4\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce7\u0ce8 \u0965", "malayalam": "\u0d05\u0d35\u0d3f\u0d30\u0d32\u0d17\u0d23\u0d4d\u0d21\u0d17\u0d32\u0d28\u0d4d\u0d2e\u0d26\u0d2e\u0d47\u0d26\u0d41\u0d30\u0d2e\u0d24\u0d4d\u0d24\u0d2e\u0d24\u0d4d\u0d24\u0d19\u0d4d\u0d17\u0d1c\u0d30\u0d3e\u0d1c\u0d2a\u0d24\u0d47\n\u0d24\u0d4d\u0d30\u0d3f\u0d2d\u0d41\u0d35\u0d28\u0d2d\u0d42\u0d37\u0d23\u0d2d\u0d42\u0d24\u0d15\u0d32\u0d3e\u0d28\u0d3f\u0d27\u0d3f\u0d30\u0d42\u0d2a\u0d2a\u0d2f\u0d4b\u0d28\u0d3f\u0d27\u0d3f\u0d30\u0d3e\u0d1c\u0d38\u0d41\u0d24\u0d47 \u0964\n\u0d05\u0d2f\u0d3f \u0d38\u0d41\u0d26\u0d24\u0d40\u0d1c\u0d28\u0d32\u0d3e\u0d32\u0d38\u0d2e\u0d3e\u0d28\u0d38\u0d2e\u0d4b\u0d39\u0d28\u0d2e\u0d28\u0d4d\u0d2e\u0d25\u0d30\u0d3e\u0d1c\u0d38\u0d41\u0d24\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d67\u0d68 \u0965", "iast": "aviralaga\u1e47\u1e0dagalanmadameduramattamatta\u1e45gajar\u0101japate\ntribhuvanabh\u016b\u1e63a\u1e47abh\u016btakal\u0101nidhir\u016bpapayonidhir\u0101jasute |\nayi sudat\u012bjanal\u0101lasam\u0101nasamohanamanmathar\u0101jasute\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 12 ||"},
        draftTranslation: "Subduing raging war-elephants intoxicated with rut, daughter of the King of the Ocean, ornament of the three worlds, captivating the hearts of the noble and wise! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 13,
        devanagariText: "\u0915\u092e\u0932\u0926\u0932\u093e\u092e\u0932\u0915\u094b\u092e\u0932\u0917\u093e\u0928\u0915\u0932\u093e\u092e\u0932\u093f\u0915\u093e\u092e\u0932\u092d\u093e\u0932\u0932\u0924\u0947\n\u0938\u0915\u0932\u0935\u093f\u0932\u093e\u0938\u092e\u0939\u093e\u0928\u093f\u0927\u093f\u0936\u0948\u0932\u0938\u0941\u0924\u093e\u0935\u0930\u091a\u093e\u0930\u0941\u0915\u091f\u093e\u0915\u094d\u0937\u0928\u0941\u0924\u0947 \u0964\n\u092d\u094d\u0930\u092e\u0930\u0917\u0923\u0948\u0930\u092d\u093f\u0928\u0928\u094d\u0926\u093f\u0924\u091a\u0928\u094d\u0926\u0928\u0938\u094c\u0930\u092d\u0938\u094c\u0930\u092d\u092e\u0928\u094d\u0926\u0917\u0924\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0967\u0969 \u0965",
        iastText: "kamaladal\u0101malak\u014dmalag\u0101nakal\u0101malik\u0101malabh\u0101lalat\u0113\nsakalavil\u0101samah\u0101nidhi\u015bailasut\u0101varac\u0101ruka\u1e6d\u0101k\u1e63anut\u0113 \u0964\nbhramaraga\u1e47airabhinanditacandanasaurabhasaurabhamandagat\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 13 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c15\u0c2e\u0c32\u0c26\u0c32\u0c3e\u0c2e\u0c32\u0c15\u0c4b\u0c2e\u0c32\u0c17\u0c3e\u0c28\u0c15\u0c32\u0c3e\u0c2e\u0c32\u0c3f\u0c15\u0c3e\u0c2e\u0c32\u0c2d\u0c3e\u0c32\u0c32\u0c24\u0c47\n\u0c38\u0c15\u0c32\u0c35\u0c3f\u0c32\u0c3e\u0c38\u0c2e\u0c39\u0c3e\u0c28\u0c3f\u0c27\u0c3f\u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c3e\u0c35\u0c30\u0c1a\u0c3e\u0c30\u0c41\u0c15\u0c1f\u0c3e\u0c15\u0c4d\u0c37\u0c28\u0c41\u0c24\u0c47 \u0964\n\u0c2d\u0c4d\u0c30\u0c2e\u0c30\u0c17\u0c23\u0c48\u0c30\u0c2d\u0c3f\u0c28\u0c28\u0c4d\u0c26\u0c3f\u0c24\u0c1a\u0c28\u0c4d\u0c26\u0c28\u0c38\u0c4c\u0c30\u0c2d\u0c38\u0c4c\u0c30\u0c2d\u0c2e\u0c28\u0c4d\u0c26\u0c17\u0c24\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c67\u0c69 \u0965", "tamil": "\u0b95\u0bae\u0bb2\u0ba4\u0bb2\u0bbe\u0bae\u0bb2\u0b95\u0bcb\u0bae\u0bb2\u0b95\u0bbe\u0ba8\u0b95\u0bb2\u0bbe\u0bae\u0bb2\u0bbf\u0b95\u0bbe\u0bae\u0bb2\u0baa\u0bbe\u0bb2\u0bb2\u0ba4\u0bc7\n\u0bb8\u0b95\u0bb2\u0bb5\u0bbf\u0bb2\u0bbe\u0bb8\u0bae\u0bb9\u0bbe\u0ba8\u0bbf\u0ba4\u0bbf\u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bbe\u0bb5\u0bb0\u0b9a\u0bbe\u0bb0\u0bc1\u0b95\u0b9f\u0bbe\u0b95\u0bcd\u0bb7\u0ba8\u0bc1\u0ba4\u0bc7 \u0964\n\u0baa\u0bcd\u0bb0\u0bae\u0bb0\u0b95\u0ba3\u0bc8\u0bb0\u0baa\u0bbf\u0ba8\u0ba8\u0bcd\u0ba4\u0bbf\u0ba4\u0b9a\u0ba8\u0bcd\u0ba4\u0ba8\u0bb8\u0bcc\u0bb0\u0baa\u0bb8\u0bcc\u0bb0\u0baa\u0bae\u0ba8\u0bcd\u0ba4\u0b95\u0ba4\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be7\u0be9 \u0965", "kannada": "\u0c95\u0cae\u0cb2\u0ca6\u0cb2\u0cbe\u0cae\u0cb2\u0c95\u0ccb\u0cae\u0cb2\u0c97\u0cbe\u0ca8\u0c95\u0cb2\u0cbe\u0cae\u0cb2\u0cbf\u0c95\u0cbe\u0cae\u0cb2\u0cad\u0cbe\u0cb2\u0cb2\u0ca4\u0cc7\n\u0cb8\u0c95\u0cb2\u0cb5\u0cbf\u0cb2\u0cbe\u0cb8\u0cae\u0cb9\u0cbe\u0ca8\u0cbf\u0ca7\u0cbf\u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cbe\u0cb5\u0cb0\u0c9a\u0cbe\u0cb0\u0cc1\u0c95\u0c9f\u0cbe\u0c95\u0ccd\u0cb7\u0ca8\u0cc1\u0ca4\u0cc7 \u0964\n\u0cad\u0ccd\u0cb0\u0cae\u0cb0\u0c97\u0ca3\u0cc8\u0cb0\u0cad\u0cbf\u0ca8\u0ca8\u0ccd\u0ca6\u0cbf\u0ca4\u0c9a\u0ca8\u0ccd\u0ca6\u0ca8\u0cb8\u0ccc\u0cb0\u0cad\u0cb8\u0ccc\u0cb0\u0cad\u0cae\u0ca8\u0ccd\u0ca6\u0c97\u0ca4\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce7\u0ce9 \u0965", "malayalam": "\u0d15\u0d2e\u0d32\u0d26\u0d32\u0d3e\u0d2e\u0d32\u0d15\u0d4b\u0d2e\u0d32\u0d17\u0d3e\u0d28\u0d15\u0d32\u0d3e\u0d2e\u0d32\u0d3f\u0d15\u0d3e\u0d2e\u0d32\u0d2d\u0d3e\u0d32\u0d32\u0d24\u0d47\n\u0d38\u0d15\u0d32\u0d35\u0d3f\u0d32\u0d3e\u0d38\u0d2e\u0d39\u0d3e\u0d28\u0d3f\u0d27\u0d3f\u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d3e\u0d35\u0d30\u0d1a\u0d3e\u0d30\u0d41\u0d15\u0d1f\u0d3e\u0d15\u0d4d\u0d37\u0d28\u0d41\u0d24\u0d47 \u0964\n\u0d2d\u0d4d\u0d30\u0d2e\u0d30\u0d17\u0d23\u0d48\u0d30\u0d2d\u0d3f\u0d28\u0d28\u0d4d\u0d26\u0d3f\u0d24\u0d1a\u0d28\u0d4d\u0d26\u0d28\u0d38\u0d4c\u0d30\u0d2d\u0d38\u0d4c\u0d30\u0d2d\u0d2e\u0d28\u0d4d\u0d26\u0d17\u0d24\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d67\u0d69 \u0965", "iast": "kamaladal\u0101malakomalag\u0101nakal\u0101malik\u0101malabh\u0101lalate\nsakalavil\u0101samah\u0101nidhi\u015bailasut\u0101varac\u0101ruka\u1e6d\u0101k\u1e63anute |\nbhramaraga\u1e47airabhinanditacandanasaurabhasaurabhamandagate\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 13 ||"},
        draftTranslation: "Forehead radiant and smooth like a lotus petal, ocean of all grace, whose graceful sidelong glances bestow boons, moving with majestic slow steps fragrant with sandalwood adored by bees! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 14,
        devanagariText: "\u0915\u0930\u092e\u0941\u0930\u0932\u0940\u0930\u0935\u0915\u0942\u091c\u093f\u0924\u0915\u0942\u091c\u093f\u0924\u0915\u094b\u0915\u093f\u0932\u092e\u091e\u094d\u091c\u0941\u0932\u092e\u091e\u094d\u091c\u0941\u092e\u0924\u0947\n\u092e\u093f\u0932\u093f\u0924\u092a\u0941\u0932\u093f\u0928\u094d\u0926\u092e\u0928\u094b\u0939\u0930\u0917\u0941\u091e\u094d\u091c\u093f\u0924\u0930\u091e\u094d\u091c\u093f\u0924\u0936\u0948\u0932\u0928\u093f\u0915\u0941\u091e\u094d\u091c\u0917\u0924\u0947 \u0964\n\u0928\u093f\u091c\u0917\u0941\u0923\u092d\u0942\u0924\u092a\u0935\u093f\u0924\u094d\u0930\u093f\u0924\u0935\u093f\u0936\u094d\u0935\u092e\u0928\u094b\u0939\u0930\u0928\u0928\u094d\u0926\u0928\u0915\u093e\u0928\u0928\u092d\u093e\u0915\u094d\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0967\u096a \u0965",
        iastText: "karamural\u012bravak\u016bjitak\u016bjitak\u014dkilama\u00f1julama\u00f1jumat\u0113\nmilitapulindaman\u014dharagu\u00f1jitara\u00f1jita\u015bailaniku\u00f1jagat\u0113 \u0964\nnijagu\u1e47abh\u016btapavitritavi\u015bvaman\u014dharanandanak\u0101nanabh\u0101k\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 14 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c15\u0c30\u0c2e\u0c41\u0c30\u0c32\u0c40\u0c30\u0c35\u0c15\u0c42\u0c1c\u0c3f\u0c24\u0c15\u0c42\u0c1c\u0c3f\u0c24\u0c15\u0c4b\u0c15\u0c3f\u0c32\u0c2e\u0c1e\u0c4d\u0c1c\u0c41\u0c32\u0c2e\u0c1e\u0c4d\u0c1c\u0c41\u0c2e\u0c24\u0c47\n\u0c2e\u0c3f\u0c32\u0c3f\u0c24\u0c2a\u0c41\u0c32\u0c3f\u0c28\u0c4d\u0c26\u0c2e\u0c28\u0c4b\u0c39\u0c30\u0c17\u0c41\u0c1e\u0c4d\u0c1c\u0c3f\u0c24\u0c30\u0c1e\u0c4d\u0c1c\u0c3f\u0c24\u0c36\u0c48\u0c32\u0c28\u0c3f\u0c15\u0c41\u0c1e\u0c4d\u0c1c\u0c17\u0c24\u0c47 \u0964\n\u0c28\u0c3f\u0c1c\u0c17\u0c41\u0c23\u0c2d\u0c42\u0c24\u0c2a\u0c35\u0c3f\u0c24\u0c4d\u0c30\u0c3f\u0c24\u0c35\u0c3f\u0c36\u0c4d\u0c35\u0c2e\u0c28\u0c4b\u0c39\u0c30\u0c28\u0c28\u0c4d\u0c26\u0c28\u0c15\u0c3e\u0c28\u0c28\u0c2d\u0c3e\u0c15\u0c4d\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c67\u0c6a \u0965", "tamil": "\u0b95\u0bb0\u0bae\u0bc1\u0bb0\u0bb2\u0bc0\u0bb0\u0bb5\u0b95\u0bc2\u0b9c\u0bbf\u0ba4\u0b95\u0bc2\u0b9c\u0bbf\u0ba4\u0b95\u0bcb\u0b95\u0bbf\u0bb2\u0bae\u0b9e\u0bcd\u0b9c\u0bc1\u0bb2\u0bae\u0b9e\u0bcd\u0b9c\u0bc1\u0bae\u0ba4\u0bc7\n\u0bae\u0bbf\u0bb2\u0bbf\u0ba4\u0baa\u0bc1\u0bb2\u0bbf\u0ba8\u0bcd\u0ba4\u0bae\u0ba8\u0bcb\u0bb9\u0bb0\u0b95\u0bc1\u0b9e\u0bcd\u0b9c\u0bbf\u0ba4\u0bb0\u0b9e\u0bcd\u0b9c\u0bbf\u0ba4\u0bb6\u0bc8\u0bb2\u0ba8\u0bbf\u0b95\u0bc1\u0b9e\u0bcd\u0b9c\u0b95\u0ba4\u0bc7 \u0964\n\u0ba8\u0bbf\u0b9c\u0b95\u0bc1\u0ba3\u0baa\u0bc2\u0ba4\u0baa\u0bb5\u0bbf\u0ba4\u0bcd\u0bb0\u0bbf\u0ba4\u0bb5\u0bbf\u0bb6\u0bcd\u0bb5\u0bae\u0ba8\u0bcb\u0bb9\u0bb0\u0ba8\u0ba8\u0bcd\u0ba4\u0ba8\u0b95\u0bbe\u0ba8\u0ba8\u0baa\u0bbe\u0b95\u0bcd\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be7\u0bea \u0965", "kannada": "\u0c95\u0cb0\u0cae\u0cc1\u0cb0\u0cb2\u0cc0\u0cb0\u0cb5\u0c95\u0cc2\u0c9c\u0cbf\u0ca4\u0c95\u0cc2\u0c9c\u0cbf\u0ca4\u0c95\u0ccb\u0c95\u0cbf\u0cb2\u0cae\u0c9e\u0ccd\u0c9c\u0cc1\u0cb2\u0cae\u0c9e\u0ccd\u0c9c\u0cc1\u0cae\u0ca4\u0cc7\n\u0cae\u0cbf\u0cb2\u0cbf\u0ca4\u0caa\u0cc1\u0cb2\u0cbf\u0ca8\u0ccd\u0ca6\u0cae\u0ca8\u0ccb\u0cb9\u0cb0\u0c97\u0cc1\u0c9e\u0ccd\u0c9c\u0cbf\u0ca4\u0cb0\u0c9e\u0ccd\u0c9c\u0cbf\u0ca4\u0cb6\u0cc8\u0cb2\u0ca8\u0cbf\u0c95\u0cc1\u0c9e\u0ccd\u0c9c\u0c97\u0ca4\u0cc7 \u0964\n\u0ca8\u0cbf\u0c9c\u0c97\u0cc1\u0ca3\u0cad\u0cc2\u0ca4\u0caa\u0cb5\u0cbf\u0ca4\u0ccd\u0cb0\u0cbf\u0ca4\u0cb5\u0cbf\u0cb6\u0ccd\u0cb5\u0cae\u0ca8\u0ccb\u0cb9\u0cb0\u0ca8\u0ca8\u0ccd\u0ca6\u0ca8\u0c95\u0cbe\u0ca8\u0ca8\u0cad\u0cbe\u0c95\u0ccd\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce7\u0cea \u0965", "malayalam": "\u0d15\u0d30\u0d2e\u0d41\u0d30\u0d32\u0d40\u0d30\u0d35\u0d15\u0d42\u0d1c\u0d3f\u0d24\u0d15\u0d42\u0d1c\u0d3f\u0d24\u0d15\u0d4b\u0d15\u0d3f\u0d32\u0d2e\u0d1e\u0d4d\u0d1c\u0d41\u0d32\u0d2e\u0d1e\u0d4d\u0d1c\u0d41\u0d2e\u0d24\u0d47\n\u0d2e\u0d3f\u0d32\u0d3f\u0d24\u0d2a\u0d41\u0d32\u0d3f\u0d28\u0d4d\u0d26\u0d2e\u0d28\u0d4b\u0d39\u0d30\u0d17\u0d41\u0d1e\u0d4d\u0d1c\u0d3f\u0d24\u0d30\u0d1e\u0d4d\u0d1c\u0d3f\u0d24\u0d36\u0d48\u0d32\u0d28\u0d3f\u0d15\u0d41\u0d1e\u0d4d\u0d1c\u0d17\u0d24\u0d47 \u0964\n\u0d28\u0d3f\u0d1c\u0d17\u0d41\u0d23\u0d2d\u0d42\u0d24\u0d2a\u0d35\u0d3f\u0d24\u0d4d\u0d30\u0d3f\u0d24\u0d35\u0d3f\u0d36\u0d4d\u0d35\u0d2e\u0d28\u0d4b\u0d39\u0d30\u0d28\u0d28\u0d4d\u0d26\u0d28\u0d15\u0d3e\u0d28\u0d28\u0d2d\u0d3e\u0d15\u0d4d\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d67\u0d6a \u0965", "iast": "karamural\u012bravak\u016bjitak\u016bjitakokilama\u00f1julama\u00f1jumate\nmilitapulindamanoharagu\u00f1jitara\u00f1jita\u015bailaniku\u00f1jagate |\nnijagu\u1e47abh\u016btapavitritavi\u015bvamanoharanandanak\u0101nanabh\u0101k\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 14 ||"},
        draftTranslation: "Mind attuned to the sweet notes of the flute and the song of the cuckoo, gracing mountain bowers resonant with honeyed hums, purifying all worlds by Your virtues! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 15,
        devanagariText: "\u0915\u091f\u093f\u0924\u091f\u092a\u0940\u0924\u0926\u0941\u0915\u0942\u0932\u0935\u093f\u091a\u093f\u0924\u094d\u0930\u092e\u092f\u0942\u0916\u0924\u093f\u0930\u0938\u094d\u0915\u0943\u0924\u091a\u0928\u094d\u0926\u094d\u0930\u0930\u0941\u091a\u0947\n\u092a\u094d\u0930\u0923\u0924\u0938\u0941\u0930\u093e\u0938\u0941\u0930\u092e\u094c\u0932\u093f\u0935\u093f\u0930\u091e\u094d\u091c\u093f\u0924\u0930\u0924\u094d\u0928\u0915\u0926\u092e\u094d\u092c\u0915\u0930\u093e\u091c\u093f\u0928\u0941\u0924\u0947 \u0964\n\u0909\u0926\u093f\u0924\u092e\u0939\u093e\u0930\u0941\u0923\u092e\u0923\u094d\u0921\u0932\u0928\u093f\u0930\u094d\u092e\u0932\u0915\u093e\u0928\u094d\u0924\u093f\u0935\u093f\u0932\u093e\u0938\u0935\u093f\u0926\u0940\u092a\u094d\u0924\u0924\u0932\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0967\u096b \u0965",
        iastText: "ka\u1e6dita\u1e6dap\u012btaduk\u016blavicitramay\u016bkhatirask\u1e5btacandraruc\u0113\npra\u1e47atasur\u0101suramaulivira\u00f1jitaratnakadambakar\u0101jinut\u0113 \u0964\nuditamah\u0101ru\u1e47ama\u1e47\u1e0dalanirmalak\u0101ntivil\u0101savid\u012bptatal\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 15 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c15\u0c1f\u0c3f\u0c24\u0c1f\u0c2a\u0c40\u0c24\u0c26\u0c41\u0c15\u0c42\u0c32\u0c35\u0c3f\u0c1a\u0c3f\u0c24\u0c4d\u0c30\u0c2e\u0c2f\u0c42\u0c16\u0c24\u0c3f\u0c30\u0c38\u0c4d\u0c15\u0c43\u0c24\u0c1a\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c30\u0c41\u0c1a\u0c47\n\u0c2a\u0c4d\u0c30\u0c23\u0c24\u0c38\u0c41\u0c30\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c4c\u0c32\u0c3f\u0c35\u0c3f\u0c30\u0c1e\u0c4d\u0c1c\u0c3f\u0c24\u0c30\u0c24\u0c4d\u0c28\u0c15\u0c26\u0c2e\u0c4d\u0c2c\u0c15\u0c30\u0c3e\u0c1c\u0c3f\u0c28\u0c41\u0c24\u0c47 \u0964\n\u0c09\u0c26\u0c3f\u0c24\u0c2e\u0c39\u0c3e\u0c30\u0c41\u0c23\u0c2e\u0c23\u0c4d\u0c21\u0c32\u0c28\u0c3f\u0c30\u0c4d\u0c2e\u0c32\u0c15\u0c3e\u0c28\u0c4d\u0c24\u0c3f\u0c35\u0c3f\u0c32\u0c3e\u0c38\u0c35\u0c3f\u0c26\u0c40\u0c2a\u0c4d\u0c24\u0c24\u0c32\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c67\u0c6b \u0965", "tamil": "\u0b95\u0b9f\u0bbf\u0ba4\u0b9f\u0baa\u0bc0\u0ba4\u0ba4\u0bc1\u0b95\u0bc2\u0bb2\u0bb5\u0bbf\u0b9a\u0bbf\u0ba4\u0bcd\u0bb0\u0bae\u0baf\u0bc2\u0b95\u0ba4\u0bbf\u0bb0\u0bb8\u0bcd\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0b9a\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bb0\u0bc1\u0b9a\u0bc7\n\u0baa\u0bcd\u0bb0\u0ba3\u0ba4\u0bb8\u0bc1\u0bb0\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bcc\u0bb2\u0bbf\u0bb5\u0bbf\u0bb0\u0b9e\u0bcd\u0b9c\u0bbf\u0ba4\u0bb0\u0ba4\u0bcd\u0ba8\u0b95\u0ba4\u0bae\u0bcd\u0baa\u0b95\u0bb0\u0bbe\u0b9c\u0bbf\u0ba8\u0bc1\u0ba4\u0bc7 \u0964\n\u0b89\u0ba4\u0bbf\u0ba4\u0bae\u0bb9\u0bbe\u0bb0\u0bc1\u0ba3\u0bae\u0ba3\u0bcd\u0b9f\u0bb2\u0ba8\u0bbf\u0bb0\u0bcd\u0bae\u0bb2\u0b95\u0bbe\u0ba8\u0bcd\u0ba4\u0bbf\u0bb5\u0bbf\u0bb2\u0bbe\u0bb8\u0bb5\u0bbf\u0ba4\u0bc0\u0baa\u0bcd\u0ba4\u0ba4\u0bb2\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be7\u0beb \u0965", "kannada": "\u0c95\u0c9f\u0cbf\u0ca4\u0c9f\u0caa\u0cc0\u0ca4\u0ca6\u0cc1\u0c95\u0cc2\u0cb2\u0cb5\u0cbf\u0c9a\u0cbf\u0ca4\u0ccd\u0cb0\u0cae\u0caf\u0cc2\u0c96\u0ca4\u0cbf\u0cb0\u0cb8\u0ccd\u0c95\u0cc3\u0ca4\u0c9a\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0cb0\u0cc1\u0c9a\u0cc7\n\u0caa\u0ccd\u0cb0\u0ca3\u0ca4\u0cb8\u0cc1\u0cb0\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0ccc\u0cb2\u0cbf\u0cb5\u0cbf\u0cb0\u0c9e\u0ccd\u0c9c\u0cbf\u0ca4\u0cb0\u0ca4\u0ccd\u0ca8\u0c95\u0ca6\u0cae\u0ccd\u0cac\u0c95\u0cb0\u0cbe\u0c9c\u0cbf\u0ca8\u0cc1\u0ca4\u0cc7 \u0964\n\u0c89\u0ca6\u0cbf\u0ca4\u0cae\u0cb9\u0cbe\u0cb0\u0cc1\u0ca3\u0cae\u0ca3\u0ccd\u0ca1\u0cb2\u0ca8\u0cbf\u0cb0\u0ccd\u0cae\u0cb2\u0c95\u0cbe\u0ca8\u0ccd\u0ca4\u0cbf\u0cb5\u0cbf\u0cb2\u0cbe\u0cb8\u0cb5\u0cbf\u0ca6\u0cc0\u0caa\u0ccd\u0ca4\u0ca4\u0cb2\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce7\u0ceb \u0965", "malayalam": "\u0d15\u0d1f\u0d3f\u0d24\u0d1f\u0d2a\u0d40\u0d24\u0d26\u0d41\u0d15\u0d42\u0d32\u0d35\u0d3f\u0d1a\u0d3f\u0d24\u0d4d\u0d30\u0d2e\u0d2f\u0d42\u0d16\u0d24\u0d3f\u0d30\u0d38\u0d4d\u0d15\u0d43\u0d24\u0d1a\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d30\u0d41\u0d1a\u0d47\n\u0d2a\u0d4d\u0d30\u0d23\u0d24\u0d38\u0d41\u0d30\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d4c\u0d32\u0d3f\u0d35\u0d3f\u0d30\u0d1e\u0d4d\u0d1c\u0d3f\u0d24\u0d30\u0d24\u0d4d\u0d28\u0d15\u0d26\u0d2e\u0d4d\u0d2c\u0d15\u0d30\u0d3e\u0d1c\u0d3f\u0d28\u0d41\u0d24\u0d47 \u0964\n\u0d09\u0d26\u0d3f\u0d24\u0d2e\u0d39\u0d3e\u0d30\u0d41\u0d23\u0d2e\u0d23\u0d4d\u0d21\u0d32\u0d28\u0d3f\u0d30\u0d4d\u0d2e\u0d32\u0d15\u0d3e\u0d28\u0d4d\u0d24\u0d3f\u0d35\u0d3f\u0d32\u0d3e\u0d38\u0d35\u0d3f\u0d26\u0d40\u0d2a\u0d4d\u0d24\u0d24\u0d32\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d67\u0d6b \u0965", "iast": "ka\u1e6dita\u1e6dap\u012btaduk\u016blavicitramay\u016bkhatirask\u1e5btacandraruce\npra\u1e47atasur\u0101suramaulivira\u00f1jitaratnakadambakar\u0101jinute |\nuditamah\u0101ru\u1e47ama\u1e47\u1e0dalanirmalak\u0101ntivil\u0101savid\u012bptatale\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 15 ||"},
        draftTranslation: "Adorned around the waist with golden-yellow silk outshining the moon, whose feet are bathed in the multicolored gem-light of bowing gods and demons, shining like the newly risen sun! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 16,
        devanagariText: "\u0938\u0941\u0930\u0928\u0930\u0935\u0928\u094d\u0926\u093f\u0924\u092a\u093e\u0926\u0938\u0930\u094b\u0930\u0941\u0939\u092e\u0941\u0926\u094d\u0930\u093f\u0924\u0938\u0930\u094d\u0935\u0936\u0941\u092d\u092a\u094d\u0930\u092a\u0924\u0947\n\u0915\u0941\u092e\u0941\u0926\u0935\u093f\u0915\u093e\u0938\u0938\u0941\u0939\u093e\u0938\u0935\u093f\u0932\u093e\u0938\u0938\u0941\u0936\u094b\u092d\u093f\u0924\u0926\u093f\u0935\u094d\u092f\u092e\u0941\u0916\u093e\u092e\u094d\u092c\u0941\u0930\u0941\u0939\u0947 \u0964\n\u0936\u093f\u0936\u093f\u0930\u0936\u093f\u0932\u093e\u0924\u0932\u0935\u093e\u0938\u093f\u0924\u092a\u0941\u0937\u094d\u092a\u092a\u0930\u093e\u0917\u0938\u0941\u0917\u0928\u094d\u0927\u093f\u0924\u091a\u0928\u094d\u0926\u094d\u0930\u0938\u0941\u0924\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0967\u096c \u0965",
        iastText: "suranaravanditap\u0101dasar\u014druhamudritasarva\u015bubhaprapat\u0113\nkumudavik\u0101sasuh\u0101savil\u0101sasu\u015b\u014dbhitadivyamukh\u0101mburuh\u0113 \u0964\n\u015bi\u015bira\u015bil\u0101talav\u0101sitapu\u1e63papar\u0101gasugandhitacandrasut\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 16 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c38\u0c41\u0c30\u0c28\u0c30\u0c35\u0c28\u0c4d\u0c26\u0c3f\u0c24\u0c2a\u0c3e\u0c26\u0c38\u0c30\u0c4b\u0c30\u0c41\u0c39\u0c2e\u0c41\u0c26\u0c4d\u0c30\u0c3f\u0c24\u0c38\u0c30\u0c4d\u0c35\u0c36\u0c41\u0c2d\u0c2a\u0c4d\u0c30\u0c2a\u0c24\u0c47\n\u0c15\u0c41\u0c2e\u0c41\u0c26\u0c35\u0c3f\u0c15\u0c3e\u0c38\u0c38\u0c41\u0c39\u0c3e\u0c38\u0c35\u0c3f\u0c32\u0c3e\u0c38\u0c38\u0c41\u0c36\u0c4b\u0c2d\u0c3f\u0c24\u0c26\u0c3f\u0c35\u0c4d\u0c2f\u0c2e\u0c41\u0c16\u0c3e\u0c2e\u0c4d\u0c2c\u0c41\u0c30\u0c41\u0c39\u0c47 \u0964\n\u0c36\u0c3f\u0c36\u0c3f\u0c30\u0c36\u0c3f\u0c32\u0c3e\u0c24\u0c32\u0c35\u0c3e\u0c38\u0c3f\u0c24\u0c2a\u0c41\u0c37\u0c4d\u0c2a\u0c2a\u0c30\u0c3e\u0c17\u0c38\u0c41\u0c17\u0c28\u0c4d\u0c27\u0c3f\u0c24\u0c1a\u0c28\u0c4d\u0c26\u0c4d\u0c30\u0c38\u0c41\u0c24\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c67\u0c6c \u0965", "tamil": "\u0bb8\u0bc1\u0bb0\u0ba8\u0bb0\u0bb5\u0ba8\u0bcd\u0ba4\u0bbf\u0ba4\u0baa\u0bbe\u0ba4\u0bb8\u0bb0\u0bcb\u0bb0\u0bc1\u0bb9\u0bae\u0bc1\u0ba4\u0bcd\u0bb0\u0bbf\u0ba4\u0bb8\u0bb0\u0bcd\u0bb5\u0bb6\u0bc1\u0baa\u0baa\u0bcd\u0bb0\u0baa\u0ba4\u0bc7\n\u0b95\u0bc1\u0bae\u0bc1\u0ba4\u0bb5\u0bbf\u0b95\u0bbe\u0bb8\u0bb8\u0bc1\u0bb9\u0bbe\u0bb8\u0bb5\u0bbf\u0bb2\u0bbe\u0bb8\u0bb8\u0bc1\u0bb6\u0bcb\u0baa\u0bbf\u0ba4\u0ba4\u0bbf\u0bb5\u0bcd\u0baf\u0bae\u0bc1\u0b95\u0bbe\u0bae\u0bcd\u0baa\u0bc1\u0bb0\u0bc1\u0bb9\u0bc7 \u0964\n\u0bb6\u0bbf\u0bb6\u0bbf\u0bb0\u0bb6\u0bbf\u0bb2\u0bbe\u0ba4\u0bb2\u0bb5\u0bbe\u0bb8\u0bbf\u0ba4\u0baa\u0bc1\u0bb7\u0bcd\u0baa\u0baa\u0bb0\u0bbe\u0b95\u0bb8\u0bc1\u0b95\u0ba8\u0bcd\u0ba4\u0bbf\u0ba4\u0b9a\u0ba8\u0bcd\u0ba4\u0bcd\u0bb0\u0bb8\u0bc1\u0ba4\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be7\u0bec \u0965", "kannada": "\u0cb8\u0cc1\u0cb0\u0ca8\u0cb0\u0cb5\u0ca8\u0ccd\u0ca6\u0cbf\u0ca4\u0caa\u0cbe\u0ca6\u0cb8\u0cb0\u0ccb\u0cb0\u0cc1\u0cb9\u0cae\u0cc1\u0ca6\u0ccd\u0cb0\u0cbf\u0ca4\u0cb8\u0cb0\u0ccd\u0cb5\u0cb6\u0cc1\u0cad\u0caa\u0ccd\u0cb0\u0caa\u0ca4\u0cc7\n\u0c95\u0cc1\u0cae\u0cc1\u0ca6\u0cb5\u0cbf\u0c95\u0cbe\u0cb8\u0cb8\u0cc1\u0cb9\u0cbe\u0cb8\u0cb5\u0cbf\u0cb2\u0cbe\u0cb8\u0cb8\u0cc1\u0cb6\u0ccb\u0cad\u0cbf\u0ca4\u0ca6\u0cbf\u0cb5\u0ccd\u0caf\u0cae\u0cc1\u0c96\u0cbe\u0cae\u0ccd\u0cac\u0cc1\u0cb0\u0cc1\u0cb9\u0cc7 \u0964\n\u0cb6\u0cbf\u0cb6\u0cbf\u0cb0\u0cb6\u0cbf\u0cb2\u0cbe\u0ca4\u0cb2\u0cb5\u0cbe\u0cb8\u0cbf\u0ca4\u0caa\u0cc1\u0cb7\u0ccd\u0caa\u0caa\u0cb0\u0cbe\u0c97\u0cb8\u0cc1\u0c97\u0ca8\u0ccd\u0ca7\u0cbf\u0ca4\u0c9a\u0ca8\u0ccd\u0ca6\u0ccd\u0cb0\u0cb8\u0cc1\u0ca4\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce7\u0cec \u0965", "malayalam": "\u0d38\u0d41\u0d30\u0d28\u0d30\u0d35\u0d28\u0d4d\u0d26\u0d3f\u0d24\u0d2a\u0d3e\u0d26\u0d38\u0d30\u0d4b\u0d30\u0d41\u0d39\u0d2e\u0d41\u0d26\u0d4d\u0d30\u0d3f\u0d24\u0d38\u0d30\u0d4d\u0d35\u0d36\u0d41\u0d2d\u0d2a\u0d4d\u0d30\u0d2a\u0d24\u0d47\n\u0d15\u0d41\u0d2e\u0d41\u0d26\u0d35\u0d3f\u0d15\u0d3e\u0d38\u0d38\u0d41\u0d39\u0d3e\u0d38\u0d35\u0d3f\u0d32\u0d3e\u0d38\u0d38\u0d41\u0d36\u0d4b\u0d2d\u0d3f\u0d24\u0d26\u0d3f\u0d35\u0d4d\u0d2f\u0d2e\u0d41\u0d16\u0d3e\u0d2e\u0d4d\u0d2c\u0d41\u0d30\u0d41\u0d39\u0d47 \u0964\n\u0d36\u0d3f\u0d36\u0d3f\u0d30\u0d36\u0d3f\u0d32\u0d3e\u0d24\u0d32\u0d35\u0d3e\u0d38\u0d3f\u0d24\u0d2a\u0d41\u0d37\u0d4d\u0d2a\u0d2a\u0d30\u0d3e\u0d17\u0d38\u0d41\u0d17\u0d28\u0d4d\u0d27\u0d3f\u0d24\u0d1a\u0d28\u0d4d\u0d26\u0d4d\u0d30\u0d38\u0d41\u0d24\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d67\u0d6c \u0965", "iast": "suranaravanditap\u0101dasaroruhamudritasarva\u015bubhaprapate\nkumudavik\u0101sasuh\u0101savil\u0101sasu\u015bobhitadivyamukh\u0101mburuhe |\n\u015bi\u015bira\u015bil\u0101talav\u0101sitapu\u1e63papar\u0101gasugandhitacandrasute\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 16 ||"},
        draftTranslation: "Whose lotus feet, worshipped by gods and humans, impress auspiciousness upon all creation, whose face blossoms with a smile like night-blooming water lilies, fragrant with mountain wildflowers! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 17,
        devanagariText: "\u0905\u092f\u093f \u092e\u092f\u093f \u0926\u0940\u0928\u0926\u092f\u093e\u0932\u0941\u0926\u092f\u093e\u0928\u093f\u0915\u0941\u0930\u0941\u092e\u094d\u092c\u0915\u092e\u0947\u0926\u0941\u0930\u0928\u0947\u0924\u094d\u0930\u0930\u0941\u091a\u0947\n\u0928\u093f\u091c\u092a\u0926\u0915\u091e\u094d\u091c\u0938\u092e\u093e\u0936\u094d\u0930\u093f\u0924\u0926\u0940\u0928\u0938\u0941\u092d\u0915\u094d\u0924\u091c\u0928\u093e\u0930\u094d\u0924\u093f\u0939\u0930\u092a\u094d\u0930\u092d\u0935\u0947 \u0964\n\u0915\u0941\u0930\u0941 \u0926\u092f\u092f\u093e \u092e\u092f\u093f \u0926\u093e\u0938\u092e\u092e\u0928\u094d\u0926\u092e\u092a\u093e\u0930\u092d\u0935\u093e\u0930\u094d\u0923\u0935\u0924\u093e\u0930\u0923\u0924\u0903\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0967\u096d \u0965",
        iastText: "ayi mayi d\u012bnaday\u0101luday\u0101nikurumbakam\u0113duran\u0113traruc\u0113\nnijapadaka\u00f1jasam\u0101\u015britad\u012bnasubaktajan\u0101rtiharaprabhav\u0113 \u0964\nkuru dayay\u0101 mayi d\u0101samamandamaip\u0101rabhav\u0101r\u1e47avat\u0101ra\u1e47ata\u1e25\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 17 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c05\u0c2f\u0c3f \u0c2e\u0c2f\u0c3f \u0c26\u0c40\u0c28\u0c26\u0c2f\u0c3e\u0c32\u0c41\u0c26\u0c2f\u0c3e\u0c28\u0c3f\u0c15\u0c41\u0c30\u0c41\u0c2e\u0c4d\u0c2c\u0c15\u0c2e\u0c47\u0c26\u0c41\u0c30\u0c28\u0c47\u0c24\u0c4d\u0c30\u0c30\u0c41\u0c1a\u0c47\n\u0c28\u0c3f\u0c1c\u0c2a\u0c26\u0c15\u0c1e\u0c4d\u0c1c\u0c38\u0c2e\u0c3e\u0c36\u0c4d\u0c30\u0c3f\u0c24\u0c26\u0c40\u0c28\u0c38\u0c41\u0c2d\u0c15\u0c4d\u0c24\u0c1c\u0c28\u0c3e\u0c30\u0c4d\u0c24\u0c3f\u0c39\u0c30\u0c2a\u0c4d\u0c30\u0c2d\u0c35\u0c47 \u0964\n\u0c15\u0c41\u0c30\u0c41 \u0c26\u0c2f\u0c2f\u0c3e \u0c2e\u0c2f\u0c3f \u0c26\u0c3e\u0c38\u0c2e\u0c2e\u0c28\u0c4d\u0c26\u0c2e\u0c2a\u0c3e\u0c30\u0c2d\u0c35\u0c3e\u0c30\u0c4d\u0c23\u0c35\u0c24\u0c3e\u0c30\u0c23\u0c24\u0c03\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c67\u0c6d \u0965", "tamil": "\u0b85\u0baf\u0bbf \u0bae\u0baf\u0bbf \u0ba4\u0bc0\u0ba8\u0ba4\u0baf\u0bbe\u0bb2\u0bc1\u0ba4\u0baf\u0bbe\u0ba8\u0bbf\u0b95\u0bc1\u0bb0\u0bc1\u0bae\u0bcd\u0baa\u0b95\u0bae\u0bc7\u0ba4\u0bc1\u0bb0\u0ba8\u0bc7\u0ba4\u0bcd\u0bb0\u0bb0\u0bc1\u0b9a\u0bc7\n\u0ba8\u0bbf\u0b9c\u0baa\u0ba4\u0b95\u0b9e\u0bcd\u0b9c\u0bb8\u0bae\u0bbe\u0bb6\u0bcd\u0bb0\u0bbf\u0ba4\u0ba4\u0bc0\u0ba8\u0bb8\u0bc1\u0baa\u0b95\u0bcd\u0ba4\u0b9c\u0ba8\u0bbe\u0bb0\u0bcd\u0ba4\u0bbf\u0bb9\u0bb0\u0baa\u0bcd\u0bb0\u0baa\u0bb5\u0bc7 \u0964\n\u0b95\u0bc1\u0bb0\u0bc1 \u0ba4\u0baf\u0baf\u0bbe \u0bae\u0baf\u0bbf \u0ba4\u0bbe\u0bb8\u0bae\u0bae\u0ba8\u0bcd\u0ba4\u0bae\u0baa\u0bbe\u0bb0\u0baa\u0bb5\u0bbe\u0bb0\u0bcd\u0ba3\u0bb5\u0ba4\u0bbe\u0bb0\u0ba3\u0ba4\u0b83\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be7\u0bed \u0965", "kannada": "\u0c85\u0caf\u0cbf \u0cae\u0caf\u0cbf \u0ca6\u0cc0\u0ca8\u0ca6\u0caf\u0cbe\u0cb2\u0cc1\u0ca6\u0caf\u0cbe\u0ca8\u0cbf\u0c95\u0cc1\u0cb0\u0cc1\u0cae\u0ccd\u0cac\u0c95\u0cae\u0cc7\u0ca6\u0cc1\u0cb0\u0ca8\u0cc7\u0ca4\u0ccd\u0cb0\u0cb0\u0cc1\u0c9a\u0cc7\n\u0ca8\u0cbf\u0c9c\u0caa\u0ca6\u0c95\u0c9e\u0ccd\u0c9c\u0cb8\u0cae\u0cbe\u0cb6\u0ccd\u0cb0\u0cbf\u0ca4\u0ca6\u0cc0\u0ca8\u0cb8\u0cc1\u0cad\u0c95\u0ccd\u0ca4\u0c9c\u0ca8\u0cbe\u0cb0\u0ccd\u0ca4\u0cbf\u0cb9\u0cb0\u0caa\u0ccd\u0cb0\u0cad\u0cb5\u0cc7 \u0964\n\u0c95\u0cc1\u0cb0\u0cc1 \u0ca6\u0caf\u0caf\u0cbe \u0cae\u0caf\u0cbf \u0ca6\u0cbe\u0cb8\u0cae\u0cae\u0ca8\u0ccd\u0ca6\u0cae\u0caa\u0cbe\u0cb0\u0cad\u0cb5\u0cbe\u0cb0\u0ccd\u0ca3\u0cb5\u0ca4\u0cbe\u0cb0\u0ca3\u0ca4\u0c83\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce7\u0ced \u0965", "malayalam": "\u0d05\u0d2f\u0d3f \u0d2e\u0d2f\u0d3f \u0d26\u0d40\u0d28\u0d26\u0d2f\u0d3e\u0d32\u0d41\u0d26\u0d2f\u0d3e\u0d28\u0d3f\u0d15\u0d41\u0d30\u0d41\u0d2e\u0d4d\u0d2c\u0d15\u0d2e\u0d47\u0d26\u0d41\u0d30\u0d28\u0d47\u0d24\u0d4d\u0d30\u0d30\u0d41\u0d1a\u0d47\n\u0d28\u0d3f\u0d1c\u0d2a\u0d26\u0d15\u0d1e\u0d4d\u0d1c\u0d38\u0d2e\u0d3e\u0d36\u0d4d\u0d30\u0d3f\u0d24\u0d26\u0d40\u0d28\u0d38\u0d41\u0d2d\u0d15\u0d4d\u0d24\u0d1c\u0d28\u0d3e\u0d30\u0d4d\u0d24\u0d3f\u0d39\u0d30\u0d2a\u0d4d\u0d30\u0d2d\u0d35\u0d47 \u0964\n\u0d15\u0d41\u0d30\u0d41 \u0d26\u0d2f\u0d2f\u0d3e \u0d2e\u0d2f\u0d3f \u0d26\u0d3e\u0d38\u0d2e\u0d2e\u0d28\u0d4d\u0d26\u0d2e\u0d2a\u0d3e\u0d30\u0d2d\u0d35\u0d3e\u0d30\u0d4d\u0d23\u0d35\u0d24\u0d3e\u0d30\u0d23\u0d24\u0d03\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d67\u0d6d \u0965", "iast": "ayi mayi d\u012bnaday\u0101luday\u0101nikurumbakameduranetraruce\nnijapadaka\u00f1jasam\u0101\u015britad\u012bnasubhaktajan\u0101rtiharaprabhave |\nkuru dayay\u0101 mayi d\u0101samamandamap\u0101rabhav\u0101r\u1e47avat\u0101ra\u1e47ata\u1e25\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 17 ||"},
        draftTranslation: "O Merciful Mother! Cast Your gaze overflowing with kindness upon me, Your humble servant, dispelling all suffering and ferrying me safely across the fathomless ocean of worldly existence! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 18,
        devanagariText: "\u092a\u0926\u0915\u092e\u0932\u0902 \u0915\u0930\u0941\u0923\u093e\u0928\u093f\u0932\u092f\u0947 \u0935\u0930\u093f\u0935\u0938\u094d\u092f\u0924\u093f \u092f\u094b\u093d\u0928\u0941\u0926\u093f\u0928\u0902 \u0938 \u0936\u093f\u0935\u0947\n\u0938 \u0915\u0925\u0902 \u0928 \u092d\u0935\u0947\u0924\u094d\u0938 \u0915\u0925\u0902 \u0928 \u092d\u0935\u0947\u0924\u094d\u0924\u0935 \u092d\u093e\u0935\u0928\u092f\u093e \u0936\u0941\u091a\u093f\u092e\u093e\u0928\u091c\u0928\u0903 \u0964\n\u0924\u0935 \u0935\u093f\u092e\u0932\u0947\u0928\u094d\u0926\u0941\u0915\u0941\u0932\u0902 \u0935\u0926\u0928\u0902 \u0935\u093f\u091a\u093f\u0928\u094d\u0924\u092f\u0924\u094b \u0939\u0943\u0926\u092f\u0947 \u0928\u0928\u0941 \u0915\u093f\u092e\u094d\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0967\u096e \u0965",
        iastText: "padakamala\u1e41 karu\u1e47\u0101nilay\u0113 varivasyati y\u014d'nudina\u1e41 sa \u015biv\u0113\nsa katha\u1e41 na bhav\u0113tsa katha\u1e41 na bhav\u0113ttava bh\u0101vanay\u0101 \u015bucim\u0101najana\u1e25 \u0964\ntava vimal\u0113ndukula\u1e41 vadana\u1e41 vicintayat\u014d h\u1e5bday\u0113 nanu kim\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 18 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c2a\u0c26\u0c15\u0c2e\u0c32\u0c02 \u0c15\u0c30\u0c41\u0c23\u0c3e\u0c28\u0c3f\u0c32\u0c2f\u0c47 \u0c35\u0c30\u0c3f\u0c35\u0c38\u0c4d\u0c2f\u0c24\u0c3f \u0c2f\u0c4b\u0c3d\u0c28\u0c41\u0c26\u0c3f\u0c28\u0c02 \u0c38 \u0c36\u0c3f\u0c35\u0c47\n\u0c38 \u0c15\u0c25\u0c02 \u0c28 \u0c2d\u0c35\u0c47\u0c24\u0c4d\u0c38 \u0c15\u0c25\u0c02 \u0c28 \u0c2d\u0c35\u0c47\u0c24\u0c4d\u0c24\u0c35 \u0c2d\u0c3e\u0c35\u0c28\u0c2f\u0c3e \u0c36\u0c41\u0c1a\u0c3f\u0c2e\u0c3e\u0c28\u0c1c\u0c28\u0c03 \u0964\n\u0c24\u0c35 \u0c35\u0c3f\u0c2e\u0c32\u0c47\u0c28\u0c4d\u0c26\u0c41\u0c15\u0c41\u0c32\u0c02 \u0c35\u0c26\u0c28\u0c02 \u0c35\u0c3f\u0c1a\u0c3f\u0c28\u0c4d\u0c24\u0c2f\u0c24\u0c4b \u0c39\u0c43\u0c26\u0c2f\u0c47 \u0c28\u0c28\u0c41 \u0c15\u0c3f\u0c2e\u0c4d\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c67\u0c6e \u0965", "tamil": "\u0baa\u0ba4\u0b95\u0bae\u0bb2\u0bae\u0bcd \u0b95\u0bb0\u0bc1\u0ba3\u0bbe\u0ba8\u0bbf\u0bb2\u0baf\u0bc7 \u0bb5\u0bb0\u0bbf\u0bb5\u0bb8\u0bcd\u0baf\u0ba4\u0bbf \u0baf\u0bcb\u093d\u0ba8\u0bc1\u0ba4\u0bbf\u0ba8\u0bae\u0bcd \u0bb8 \u0bb6\u0bbf\u0bb5\u0bc7\n\u0bb8 \u0b95\u0ba4\u0bae\u0bcd \u0ba8 \u0baa\u0bb5\u0bc7\u0ba4\u0bcd\u0bb8 \u0b95\u0ba4\u0bae\u0bcd \u0ba8 \u0baa\u0bb5\u0bc7\u0ba4\u0bcd\u0ba4\u0bb5 \u0baa\u0bbe\u0bb5\u0ba8\u0baf\u0bbe \u0bb6\u0bc1\u0b9a\u0bbf\u0bae\u0bbe\u0ba8\u0b9c\u0ba8\u0b83 \u0964\n\u0ba4\u0bb5 \u0bb5\u0bbf\u0bae\u0bb2\u0bc7\u0ba8\u0bcd\u0ba4\u0bc1\u0b95\u0bc1\u0bb2\u0bae\u0bcd \u0bb5\u0ba4\u0ba8\u0bae\u0bcd \u0bb5\u0bbf\u0b9a\u0bbf\u0ba8\u0bcd\u0ba4\u0baf\u0ba4\u0bcb \u0bb9\u0bcd\u0bb0\u0bc1'\u0ba4\u0baf\u0bc7 \u0ba8\u0ba8\u0bc1 \u0b95\u0bbf\u0bae\u0bcd\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be7\u0bee \u0965", "kannada": "\u0caa\u0ca6\u0c95\u0cae\u0cb2\u0c82 \u0c95\u0cb0\u0cc1\u0ca3\u0cbe\u0ca8\u0cbf\u0cb2\u0caf\u0cc7 \u0cb5\u0cb0\u0cbf\u0cb5\u0cb8\u0ccd\u0caf\u0ca4\u0cbf \u0caf\u0ccb\u0cbd\u0ca8\u0cc1\u0ca6\u0cbf\u0ca8\u0c82 \u0cb8 \u0cb6\u0cbf\u0cb5\u0cc7\n\u0cb8 \u0c95\u0ca5\u0c82 \u0ca8 \u0cad\u0cb5\u0cc7\u0ca4\u0ccd\u0cb8 \u0c95\u0ca5\u0c82 \u0ca8 \u0cad\u0cb5\u0cc7\u0ca4\u0ccd\u0ca4\u0cb5 \u0cad\u0cbe\u0cb5\u0ca8\u0caf\u0cbe \u0cb6\u0cc1\u0c9a\u0cbf\u0cae\u0cbe\u0ca8\u0c9c\u0ca8\u0c83 \u0964\n\u0ca4\u0cb5 \u0cb5\u0cbf\u0cae\u0cb2\u0cc7\u0ca8\u0ccd\u0ca6\u0cc1\u0c95\u0cc1\u0cb2\u0c82 \u0cb5\u0ca6\u0ca8\u0c82 \u0cb5\u0cbf\u0c9a\u0cbf\u0ca8\u0ccd\u0ca4\u0caf\u0ca4\u0ccb \u0cb9\u0cc3\u0ca6\u0caf\u0cc7 \u0ca8\u0ca8\u0cc1 \u0c95\u0cbf\u0cae\u0ccd\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce7\u0cee \u0965", "malayalam": "\u0d2a\u0d26\u0d15\u0d2e\u0d32\u0d02 \u0d15\u0d30\u0d41\u0d23\u0d3e\u0d28\u0d3f\u0d32\u0d2f\u0d47 \u0d35\u0d30\u0d3f\u0d35\u0d38\u0d4d\u0d2f\u0d24\u0d3f \u0d2f\u0d4b\u0d3d\u0d28\u0d41\u0d26\u0d3f\u0d28\u0d02 \u0d38 \u0d36\u0d3f\u0d35\u0d47\n\u0d38 \u0d15\u0d25\u0d02 \u0d28 \u0d2d\u0d35\u0d47\u0d24\u0d4d\u0d38 \u0d15\u0d25\u0d02 \u0d28 \u0d2d\u0d35\u0d47\u0d24\u0d4d\u0d24\u0d35 \u0d2d\u0d3e\u0d35\u0d28\u0d2f\u0d3e \u0d36\u0d41\u0d1a\u0d3f\u0d2e\u0d3e\u0d28\u0d1c\u0d28\u0d03 \u0964\n\u0d24\u0d35 \u0d35\u0d3f\u0d2e\u0d32\u0d47\u0d28\u0d4d\u0d26\u0d41\u0d15\u0d41\u0d32\u0d02 \u0d35\u0d26\u0d28\u0d02 \u0d35\u0d3f\u0d1a\u0d3f\u0d28\u0d4d\u0d24\u0d2f\u0d24\u0d4b \u0d39\u0d43\u0d26\u0d2f\u0d47 \u0d28\u0d28\u0d41 \u0d15\u0d3f\u0d2e\u0d4d\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d67\u0d6e \u0965", "iast": "padakamala\u1e43 karu\u1e47\u0101nilaye varivasyati yo'nudina\u1e43 sa \u015bive\nsa katha\u1e43 na bhavetsa katha\u1e43 na bhavettava bh\u0101vanay\u0101 \u015bucim\u0101najana\u1e25 |\ntava vimalendukula\u1e43 vadana\u1e43 vicintayato h\u1e5bdaye nanu kim\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 18 ||"},
        draftTranslation: "Whoever daily serves Your lotus feet, O abode of compassion, O Auspicious Shivaa \u2014 how could that person not become purified and exalted through Your contemplation? Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 19,
        devanagariText: "\u0938\u094d\u0924\u0941\u0924\u093f\u092d\u093f\u0930\u092e\u0928\u094d\u0926\u092e\u0941\u0926\u093e\u0930\u0917\u0941\u0923\u093e\u092d\u093f\u0930\u0941\u0926\u0940\u0930\u093f\u0924\u0926\u093f\u0935\u094d\u092f\u0917\u0941\u0923\u093e\u092e\u094d\u092c\u0941\u0928\u093f\u0927\u0947\n\u092d\u091c\u0924\u093f \u092f\u0924\u094b \u0926\u092f\u092f\u093e \u0938 \u0928\u0930\u0903 \u0938\u092e\u0935\u093e\u092a\u094d\u0928\u0941\u0924 \u090f\u0935 \u092a\u0930\u093e\u0902 \u092e\u0941\u0926\u093f\u0924\u092e\u094d \u0964\n\u091c\u0928\u0928\u093f \u0924\u0935\u0948\u0935 \u092a\u0926\u093e\u092c\u094d\u091c\u092a\u0930\u093e\u0917\u0938\u0941\u0917\u0928\u094d\u0927\u093f\u0928\u093f\u0935\u0947\u0936\u093f\u0924\u092e\u093e\u0928\u0938\u0924\u094b\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0967\u096f \u0965",
        iastText: "stutibhiramandamad\u0101ragu\u1e47\u0101bhirud\u012britadivyagu\u1e47\u0101mbunidh\u0113\nbhajati yat\u014d dayay\u0101 sa nara\u1e25 samav\u0101pnuta \u0113va par\u0101\u1e41 muditam \u0964\njanani tavaiva pad\u0101bjapar\u0101gasugandhiniv\u0113\u015bitam\u0101nasat\u014d\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 19 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c38\u0c4d\u0c24\u0c41\u0c24\u0c3f\u0c2d\u0c3f\u0c30\u0c2e\u0c28\u0c4d\u0c26\u0c2e\u0c41\u0c26\u0c3e\u0c30\u0c17\u0c41\u0c23\u0c3e\u0c2d\u0c3f\u0c30\u0c41\u0c26\u0c40\u0c30\u0c3f\u0c24\u0c26\u0c3f\u0c35\u0c4d\u0c2f\u0c17\u0c41\u0c23\u0c3e\u0c2e\u0c4d\u0c2c\u0c41\u0c28\u0c3f\u0c27\u0c47\n\u0c2d\u0c1c\u0c24\u0c3f \u0c2f\u0c24\u0c4b \u0c26\u0c2f\u0c2f\u0c3e \u0c38 \u0c28\u0c30\u0c03 \u0c38\u0c2e\u0c35\u0c3e\u0c2a\u0c4d\u0c28\u0c41\u0c24 \u0c0f\u0c35 \u0c2a\u0c30\u0c3e\u0c02 \u0c2e\u0c41\u0c26\u0c3f\u0c24\u0c2e\u0c4d \u0964\n\u0c1c\u0c28\u0c28\u0c3f \u0c24\u0c35\u0c48\u0c35 \u0c2a\u0c26\u0c3e\u0c2c\u0c4d\u0c1c\u0c2a\u0c30\u0c3e\u0c17\u0c38\u0c41\u0c17\u0c28\u0c4d\u0c27\u0c3f\u0c28\u0c3f\u0c35\u0c47\u0c36\u0c3f\u0c24\u0c2e\u0c3e\u0c28\u0c38\u0c24\u0c4b\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c67\u0c6f \u0965", "tamil": "\u0bb8\u0bcd\u0ba4\u0bc1\u0ba4\u0bbf\u0baa\u0bbf\u0bb0\u0bae\u0ba8\u0bcd\u0ba4\u0bae\u0bc1\u0ba4\u0bbe\u0bb0\u0b95\u0bc1\u0ba3\u0bbe\u0baa\u0bbf\u0bb0\u0bc1\u0ba4\u0bc0\u0bb0\u0bbf\u0ba4\u0ba4\u0bbf\u0bb5\u0bcd\u0baf\u0b95\u0bc1\u0ba3\u0bbe\u0bae\u0bcd\u0baa\u0bc1\u0ba8\u0bbf\u0ba4\u0bc7\n\u0baa\u0b9c\u0ba4\u0bbf \u0baf\u0ba4\u0bcb \u0ba4\u0baf\u0baf\u0bbe \u0bb8 \u0ba8\u0bb0\u0b83 \u0bb8\u0bae\u0bb5\u0bbe\u0baa\u0bcd\u0ba8\u0bc1\u0ba4 \u0b8f\u0bb5 \u0baa\u0bb0\u0bbe\u0bae\u0bcd \u0bae\u0bc1\u0ba4\u0bbf\u0ba4\u0bae\u0bcd \u0964\n\u0b9c\u0ba8\u0ba8\u0bbf \u0ba4\u0bb5\u0bc8\u0bb5 \u0baa\u0ba4\u0bbe\u0baa\u0bcd\u0b9c\u0baa\u0bb0\u0bbe\u0b95\u0bb8\u0bc1\u0b95\u0ba8\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf\u0bb5\u0bc7\u0bb6\u0bbf\u0ba4\u0bae\u0bbe\u0ba8\u0bb8\u0ba4\u0bcb\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be7\u0bef \u0965", "kannada": "\u0cb8\u0ccd\u0ca4\u0cc1\u0ca4\u0cbf\u0cad\u0cbf\u0cb0\u0cae\u0ca8\u0ccd\u0ca6\u0cae\u0cc1\u0ca6\u0cbe\u0cb0\u0c97\u0cc1\u0ca3\u0cbe\u0cad\u0cbf\u0cb0\u0cc1\u0ca6\u0cc0\u0cb0\u0cbf\u0ca4\u0ca6\u0cbf\u0cb5\u0ccd\u0caf\u0c97\u0cc1\u0ca3\u0cbe\u0cae\u0ccd\u0cac\u0cc1\u0ca8\u0cbf\u0ca7\u0cc7\n\u0cad\u0c9c\u0ca4\u0cbf \u0caf\u0ca4\u0ccb \u0ca6\u0caf\u0caf\u0cbe \u0cb8 \u0ca8\u0cb0\u0c83 \u0cb8\u0cae\u0cb5\u0cbe\u0caa\u0ccd\u0ca8\u0cc1\u0ca4 \u0c8f\u0cb5 \u0caa\u0cb0\u0cbe\u0c82 \u0cae\u0cc1\u0ca6\u0cbf\u0ca4\u0cae\u0ccd \u0964\n\u0c9c\u0ca8\u0ca8\u0cbf \u0ca4\u0cb5\u0cc8\u0cb5 \u0caa\u0ca6\u0cbe\u0cac\u0ccd\u0c9c\u0caa\u0cb0\u0cbe\u0c97\u0cb8\u0cc1\u0c97\u0ca8\u0ccd\u0ca7\u0cbf\u0ca8\u0cbf\u0cb5\u0cc7\u0cb6\u0cbf\u0ca4\u0cae\u0cbe\u0ca8\u0cb8\u0ca4\u0ccb\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce7\u0cef \u0965", "malayalam": "\u0d38\u0d4d\u0d24\u0d41\u0d24\u0d3f\u0d2d\u0d3f\u0d30\u0d2e\u0d28\u0d4d\u0d26\u0d2e\u0d41\u0d26\u0d3e\u0d30\u0d17\u0d41\u0d23\u0d3e\u0d2d\u0d3f\u0d30\u0d41\u0d26\u0d40\u0d30\u0d3f\u0d24\u0d26\u0d3f\u0d35\u0d4d\u0d2f\u0d17\u0d41\u0d23\u0d3e\u0d2e\u0d4d\u0d2c\u0d41\u0d28\u0d3f\u0d27\u0d47\n\u0d2d\u0d1c\u0d24\u0d3f \u0d2f\u0d24\u0d4b \u0d26\u0d2f\u0d2f\u0d3e \u0d38 \u0d28\u0d30\u0d03 \u0d38\u0d2e\u0d35\u0d3e\u0d2a\u0d4d\u0d28\u0d41\u0d24 \u0d0f\u0d35 \u0d2a\u0d30\u0d3e\u0d02 \u0d2e\u0d41\u0d26\u0d3f\u0d24\u0d2e\u0d4d \u0964\n\u0d1c\u0d28\u0d28\u0d3f \u0d24\u0d35\u0d48\u0d35 \u0d2a\u0d26\u0d3e\u0d2c\u0d4d\u0d1c\u0d2a\u0d30\u0d3e\u0d17\u0d38\u0d41\u0d17\u0d28\u0d4d\u0d27\u0d3f\u0d28\u0d3f\u0d35\u0d47\u0d36\u0d3f\u0d24\u0d2e\u0d3e\u0d28\u0d38\u0d24\u0d4b\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d67\u0d6f \u0965", "iast": "stutibhiramandamud\u0101ragu\u1e47\u0101bhirud\u012britadivyagu\u1e47\u0101mbunidhe\nbhajati yato dayay\u0101 sa nara\u1e25 samav\u0101pnuta eva par\u0101\u1e43 muditam |\njanani tavaiva pad\u0101bjapar\u0101gasugandhinive\u015bitam\u0101nasato\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 19 ||"},
        draftTranslation: "Whoever praises Your divine virtues through these exalted hymns, anchoring their mind upon the fragrant dust of Your lotus feet, attains supreme bliss and liberation! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 20,
        devanagariText: "\u0915\u0928\u0915\u092a\u094d\u0930\u092d\u093e\u0935\u0930\u0928\u093f\u0930\u094d\u092e\u0932\u0915\u093e\u0928\u094d\u0924\u093f\u0935\u093f\u0930\u093e\u091c\u093f\u0924\u0926\u093f\u0935\u094d\u092f\u0936\u0930\u0940\u0930\u0927\u0930\u0947\n\u0915\u092e\u0932\u093e\u0938\u0928\u0935\u093f\u0937\u094d\u0923\u0941\u092e\u0939\u0947\u0936\u0938\u0941\u0930\u0947\u0936\u094d\u0935\u0930\u0935\u0928\u094d\u0926\u093f\u0924\u092a\u093e\u0926\u092f\u0941\u0917\u0947 \u0964\n\u092a\u0930\u092e\u0936\u0941\u092d\u092a\u094d\u0930\u0926\u091a\u093f\u0924\u094d\u0924\u0935\u093f\u092d\u093e\u0935\u0928\u0924\u093e\u0930\u0915\u092a\u0941\u0923\u094d\u092f\u0915\u0943\u0924\u0947 \u0938\u0941\u0916\u0926\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0968\u0966 \u0965",
        iastText: "kanakaprabh\u0101varanirmalak\u0101ntivir\u0101jitadivya\u015bar\u012bradhar\u0113\nkamal\u0101sanavi\u1e63\u1e47umah\u0113\u015basur\u0113\u015bvaravanditap\u0101dayug\u0113 \u0964\nparama\u015bubhapadacittavibh\u0101vanat\u0101rakapu\u1e47yak\u1e5bt\u0113 sukhad\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 20 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c15\u0c28\u0c15\u0c2a\u0c4d\u0c30\u0c2d\u0c3e\u0c35\u0c30\u0c28\u0c3f\u0c30\u0c4d\u0c2e\u0c32\u0c15\u0c3e\u0c28\u0c4d\u0c24\u0c3f\u0c35\u0c3f\u0c30\u0c3e\u0c1c\u0c3f\u0c24\u0c26\u0c3f\u0c35\u0c4d\u0c2f\u0c36\u0c30\u0c40\u0c30\u0c27\u0c30\u0c47\n\u0c15\u0c2e\u0c32\u0c3e\u0c38\u0c28\u0c35\u0c3f\u0c37\u0c4d\u0c23\u0c41\u0c2e\u0c39\u0c47\u0c36\u0c38\u0c41\u0c30\u0c47\u0c36\u0c4d\u0c35\u0c30\u0c35\u0c28\u0c4d\u0c26\u0c3f\u0c24\u0c2a\u0c3e\u0c26\u0c2f\u0c41\u0c17\u0c47 \u0964\n\u0c2a\u0c30\u0c2e\u0c36\u0c41\u0c2d\u0c2a\u0c4d\u0c30\u0c26\u0c1a\u0c3f\u0c24\u0c4d\u0c24\u0c35\u0c3f\u0c2d\u0c3e\u0c35\u0c28\u0c24\u0c3e\u0c30\u0c15\u0c2a\u0c41\u0c23\u0c4d\u0c2f\u0c15\u0c43\u0c24\u0c47 \u0c38\u0c41\u0c16\u0c26\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c68\u0c66 \u0965", "tamil": "\u0b95\u0ba8\u0b95\u0baa\u0bcd\u0bb0\u0baa\u0bbe\u0bb5\u0bb0\u0ba8\u0bbf\u0bb0\u0bcd\u0bae\u0bb2\u0b95\u0bbe\u0ba8\u0bcd\u0ba4\u0bbf\u0bb5\u0bbf\u0bb0\u0bbe\u0b9c\u0bbf\u0ba4\u0ba4\u0bbf\u0bb5\u0bcd\u0baf\u0bb6\u0bb0\u0bc0\u0bb0\u0ba4\u0bb0\u0bc7\n\u0b95\u0bae\u0bb2\u0bbe\u0bb8\u0ba8\u0bb5\u0bbf\u0bb7\u0bcd\u0ba3\u0bc1\u0bae\u0bb9\u0bc7\u0bb6\u0bb8\u0bc1\u0bb0\u0bc7\u0bb6\u0bcd\u0bb5\u0bb0\u0bb5\u0ba8\u0bcd\u0ba4\u0bbf\u0ba4\u0baa\u0bbe\u0ba4\u0baf\u0bc1\u0b95\u0bc7 \u0964\n\u0baa\u0bb0\u0bae\u0bb6\u0bc1\u0baa\u0baa\u0bcd\u0bb0\u0ba4\u0b9a\u0bbf\u0ba4\u0bcd\u0ba4\u0bb5\u0bbf\u0baa\u0bbe\u0bb5\u0ba8\u0ba4\u0bbe\u0bb0\u0b95\u0baa\u0bc1\u0ba3\u0bcd\u0baf\u0b95\u0bcd\u0bb0\u0bc1'\u0ba4\u0bc7 \u0bb8\u0bc1\u0b95\u0ba4\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be8\u0be6 \u0965", "kannada": "\u0c95\u0ca8\u0c95\u0caa\u0ccd\u0cb0\u0cad\u0cbe\u0cb5\u0cb0\u0ca8\u0cbf\u0cb0\u0ccd\u0cae\u0cb2\u0c95\u0cbe\u0ca8\u0ccd\u0ca4\u0cbf\u0cb5\u0cbf\u0cb0\u0cbe\u0c9c\u0cbf\u0ca4\u0ca6\u0cbf\u0cb5\u0ccd\u0caf\u0cb6\u0cb0\u0cc0\u0cb0\u0ca7\u0cb0\u0cc7\n\u0c95\u0cae\u0cb2\u0cbe\u0cb8\u0ca8\u0cb5\u0cbf\u0cb7\u0ccd\u0ca3\u0cc1\u0cae\u0cb9\u0cc7\u0cb6\u0cb8\u0cc1\u0cb0\u0cc7\u0cb6\u0ccd\u0cb5\u0cb0\u0cb5\u0ca8\u0ccd\u0ca6\u0cbf\u0ca4\u0caa\u0cbe\u0ca6\u0caf\u0cc1\u0c97\u0cc7 \u0964\n\u0caa\u0cb0\u0cae\u0cb6\u0cc1\u0cad\u0caa\u0ccd\u0cb0\u0ca6\u0c9a\u0cbf\u0ca4\u0ccd\u0ca4\u0cb5\u0cbf\u0cad\u0cbe\u0cb5\u0ca8\u0ca4\u0cbe\u0cb0\u0c95\u0caa\u0cc1\u0ca3\u0ccd\u0caf\u0c95\u0cc3\u0ca4\u0cc7 \u0cb8\u0cc1\u0c96\u0ca6\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce8\u0ce6 \u0965", "malayalam": "\u0d15\u0d28\u0d15\u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d35\u0d30\u0d28\u0d3f\u0d30\u0d4d\u0d2e\u0d32\u0d15\u0d3e\u0d28\u0d4d\u0d24\u0d3f\u0d35\u0d3f\u0d30\u0d3e\u0d1c\u0d3f\u0d24\u0d26\u0d3f\u0d35\u0d4d\u0d2f\u0d36\u0d30\u0d40\u0d30\u0d27\u0d30\u0d47\n\u0d15\u0d2e\u0d32\u0d3e\u0d38\u0d28\u0d35\u0d3f\u0d37\u0d4d\u0d23\u0d41\u0d2e\u0d39\u0d47\u0d36\u0d38\u0d41\u0d30\u0d47\u0d36\u0d4d\u0d35\u0d30\u0d35\u0d28\u0d4d\u0d26\u0d3f\u0d24\u0d2a\u0d3e\u0d26\u0d2f\u0d41\u0d17\u0d47 \u0964\n\u0d2a\u0d30\u0d2e\u0d36\u0d41\u0d2d\u0d2a\u0d4d\u0d30\u0d26\u0d1a\u0d3f\u0d24\u0d4d\u0d24\u0d35\u0d3f\u0d2d\u0d3e\u0d35\u0d28\u0d24\u0d3e\u0d30\u0d15\u0d2a\u0d41\u0d23\u0d4d\u0d2f\u0d15\u0d43\u0d24\u0d47 \u0d38\u0d41\u0d16\u0d26\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d68\u0d66 \u0965", "iast": "kanakaprabh\u0101varanirmalak\u0101ntivir\u0101jitadivya\u015bar\u012bradhare\nkamal\u0101sanavi\u1e63\u1e47umahe\u015basure\u015bvaravanditap\u0101dayuge |\nparama\u015bubhapradacittavibh\u0101vanat\u0101rakapu\u1e47yak\u1e5bte sukhade\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 20 ||"},
        draftTranslation: "Dazzling with a golden aura of transcendental beauty, whose feet are revered by Brahma, Vishnu, Shiva, and Indra, granting highest peace, salvation, and joy to pure hearts! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
      Verse(
        verseNumber: 21,
        devanagariText: "\u0915\u0928\u0915\u0932\u094d\u0938\u0924\u094d\u0915\u0932\u0938\u093f\u0928\u094d\u0927\u0941\u091c\u0932\u0948\u0930\u0928\u0941\u0937\u093f\u091e\u094d\u091a\u093f\u0928\u0941 \u0924\u0947 \u0917\u0941\u0923\u0930\u0919\u094d\u0917\u092d\u0941\u0935\u092e\u094d\n\u092d\u091c\u0924\u093f \u0938 \u0915\u093f\u0902 \u0928 \u0936\u091a\u0940\u0915\u0941\u091a\u0915\u0941\u092e\u094d\u092d\u0924\u091f\u0940\u092a\u0930\u093f\u0930\u092e\u094d\u092d\u0938\u0941\u0916\u093e\u0928\u0941\u0930\u0924\u092e\u094d \u0964\n\u0924\u0935 \u091a\u0930\u0923\u0902 \u0936\u0930\u0923\u0902 \u0915\u0930\u0935\u093e\u0923\u093f \u0928\u0924\u093e\u092e\u0930\u0935\u093e\u0923\u093f \u0928\u093f\u0935\u093e\u0938\u093f \u0936\u093f\u0935\u0947\n\u091c\u092f \u091c\u092f \u0939\u0947 \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930\u092e\u0930\u094d\u0926\u093f\u0928\u093f \u0930\u092e\u094d\u092f\u0915\u092a\u0930\u094d\u0926\u093f\u0928\u093f \u0936\u0948\u0932\u0938\u0941\u0924\u0947 \u0965 \u0968\u0967 \u0965",
        iastText: "kanakalsatkala sindhujalairanu\u1e63i\u00f1cinu t\u0113 gu\u1e47ara\u1e45gabhuvam\nbhajati sa ki\u1e41 na \u015bac\u012bkucakumbhata\u1e6d\u012bparirambhasukh\u0101nuratam \u0964\ntava cara\u1e47a\u1e41 \u015bara\u1e47a\u1e41 karav\u0101\u1e47i nat\u0101marav\u0101\u1e47i niv\u0101si \u015biv\u0113\njaya jaya h\u0113 mahi\u1e63\u0101suramardini ramyakapardini \u015bailasut\u0113 \u0965 21 \u0965",
        meter: "Dandaka-Rhythmic",
        transliterations: {"telugu": "\u0c15\u0c28\u0c15\u0c32\u0c4d\u0c38\u0c24\u0c4d\u0c15\u0c32\u0c38\u0c3f\u0c28\u0c4d\u0c27\u0c41\u0c1c\u0c32\u0c48\u0c30\u0c28\u0c41\u0c37\u0c3f\u0c1e\u0c4d\u0c1a\u0c3f\u0c28\u0c41 \u0c24\u0c47 \u0c17\u0c41\u0c23\u0c30\u0c19\u0c4d\u0c17\u0c2d\u0c41\u0c35\u0c2e\u0c4d\n\u0c2d\u0c1c\u0c24\u0c3f \u0c38 \u0c15\u0c3f\u0c02 \u0c28 \u0c36\u0c1a\u0c40\u0c15\u0c41\u0c1a\u0c15\u0c41\u0c2e\u0c4d\u0c2d\u0c24\u0c1f\u0c40\u0c2a\u0c30\u0c3f\u0c30\u0c2e\u0c4d\u0c2d\u0c38\u0c41\u0c16\u0c3e\u0c28\u0c41\u0c30\u0c24\u0c2e\u0c4d \u0964\n\u0c24\u0c35 \u0c1a\u0c30\u0c23\u0c02 \u0c36\u0c30\u0c23\u0c02 \u0c15\u0c30\u0c35\u0c3e\u0c23\u0c3f \u0c28\u0c24\u0c3e\u0c2e\u0c30\u0c35\u0c3e\u0c23\u0c3f \u0c28\u0c3f\u0c35\u0c3e\u0c38\u0c3f \u0c36\u0c3f\u0c35\u0c47\n\u0c1c\u0c2f \u0c1c\u0c2f \u0c39\u0c47 \u0c2e\u0c39\u0c3f\u0c37\u0c3e\u0c38\u0c41\u0c30\u0c2e\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c30\u0c2e\u0c4d\u0c2f\u0c15\u0c2a\u0c30\u0c4d\u0c26\u0c3f\u0c28\u0c3f \u0c36\u0c48\u0c32\u0c38\u0c41\u0c24\u0c47 \u0965 \u0c68\u0c67 \u0965", "tamil": "\u0b95\u0ba8\u0b95\u0bb2\u0bcd\u0bb8\u0ba4\u0bcd\u0b95\u0bb2\u0bb8\u0bbf\u0ba8\u0bcd\u0ba4\u0bc1\u0b9c\u0bb2\u0bc8\u0bb0\u0ba8\u0bc1\u0bb7\u0bbf\u0b9e\u0bcd\u0b9a\u0bbf\u0ba8\u0bc1 \u0ba4\u0bc7 \u0b95\u0bc1\u0ba3\u0bb0\u0b99\u0bcd\u0b95\u0baa\u0bc1\u0bb5\u0bae\u0bcd\n\u0baa\u0b9c\u0ba4\u0bbf \u0bb8 \u0b95\u0bbf\u0bae\u0bcd \u0ba8 \u0bb6\u0b9a\u0bc0\u0b95\u0bc1\u0b9a\u0b95\u0bc1\u0bae\u0bcd\u0baa\u0ba4\u0b9f\u0bc0\u0baa\u0bb0\u0bbf\u0bb0\u0bae\u0bcd\u0baa\u0bb8\u0bc1\u0b95\u0bbe\u0ba8\u0bc1\u0bb0\u0ba4\u0bae\u0bcd \u0964\n\u0ba4\u0bb5 \u0b9a\u0bb0\u0ba3\u0bae\u0bcd \u0bb6\u0bb0\u0ba3\u0bae\u0bcd \u0b95\u0bb0\u0bb5\u0bbe\u0ba3\u0bbf \u0ba8\u0ba4\u0bbe\u0bae\u0bb0\u0bb5\u0bbe\u0ba3\u0bbf \u0ba8\u0bbf\u0bb5\u0bbe\u0bb8\u0bbf \u0bb6\u0bbf\u0bb5\u0bc7\n\u0b9c\u0baf \u0b9c\u0baf \u0bb9\u0bc7 \u0bae\u0bb9\u0bbf\u0bb7\u0bbe\u0bb8\u0bc1\u0bb0\u0bae\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb0\u0bae\u0bcd\u0baf\u0b95\u0baa\u0bb0\u0bcd\u0ba4\u0bbf\u0ba8\u0bbf \u0bb6\u0bc8\u0bb2\u0bb8\u0bc1\u0ba4\u0bc7 \u0965 \u0be8\u0be7 \u0965", "kannada": "\u0c95\u0ca8\u0c95\u0cb2\u0ccd\u0cb8\u0ca4\u0ccd\u0c95\u0cb2\u0cb8\u0cbf\u0ca8\u0ccd\u0ca7\u0cc1\u0c9c\u0cb2\u0cc8\u0cb0\u0ca8\u0cc1\u0cb7\u0cbf\u0c9e\u0ccd\u0c9a\u0cbf\u0ca8\u0cc1 \u0ca4\u0cc7 \u0c97\u0cc1\u0ca3\u0cb0\u0c99\u0ccd\u0c97\u0cad\u0cc1\u0cb5\u0cae\u0ccd\n\u0cad\u0c9c\u0ca4\u0cbf \u0cb8 \u0c95\u0cbf\u0c82 \u0ca8 \u0cb6\u0c9a\u0cc0\u0c95\u0cc1\u0c9a\u0c95\u0cc1\u0cae\u0ccd\u0cad\u0ca4\u0c9f\u0cc0\u0caa\u0cb0\u0cbf\u0cb0\u0cae\u0ccd\u0cad\u0cb8\u0cc1\u0c96\u0cbe\u0ca8\u0cc1\u0cb0\u0ca4\u0cae\u0ccd \u0964\n\u0ca4\u0cb5 \u0c9a\u0cb0\u0ca3\u0c82 \u0cb6\u0cb0\u0ca3\u0c82 \u0c95\u0cb0\u0cb5\u0cbe\u0ca3\u0cbf \u0ca8\u0ca4\u0cbe\u0cae\u0cb0\u0cb5\u0cbe\u0ca3\u0cbf \u0ca8\u0cbf\u0cb5\u0cbe\u0cb8\u0cbf \u0cb6\u0cbf\u0cb5\u0cc7\n\u0c9c\u0caf \u0c9c\u0caf \u0cb9\u0cc7 \u0cae\u0cb9\u0cbf\u0cb7\u0cbe\u0cb8\u0cc1\u0cb0\u0cae\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb0\u0cae\u0ccd\u0caf\u0c95\u0caa\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cbf \u0cb6\u0cc8\u0cb2\u0cb8\u0cc1\u0ca4\u0cc7 \u0965 \u0ce8\u0ce7 \u0965", "malayalam": "\u0d15\u0d28\u0d15\u0d32\u0d4d\u0d38\u0d24\u0d4d\u0d15\u0d32\u0d38\u0d3f\u0d28\u0d4d\u0d27\u0d41\u0d1c\u0d32\u0d48\u0d30\u0d28\u0d41\u0d37\u0d3f\u0d1e\u0d4d\u0d1a\u0d3f\u0d28\u0d41 \u0d24\u0d47 \u0d17\u0d41\u0d23\u0d30\u0d19\u0d4d\u0d17\u0d2d\u0d41\u0d35\u0d2e\u0d4d\n\u0d2d\u0d1c\u0d24\u0d3f \u0d38 \u0d15\u0d3f\u0d02 \u0d28 \u0d36\u0d1a\u0d40\u0d15\u0d41\u0d1a\u0d15\u0d41\u0d2e\u0d4d\u0d2d\u0d24\u0d1f\u0d40\u0d2a\u0d30\u0d3f\u0d30\u0d2e\u0d4d\u0d2d\u0d38\u0d41\u0d16\u0d3e\u0d28\u0d41\u0d30\u0d24\u0d2e\u0d4d \u0964\n\u0d24\u0d35 \u0d1a\u0d30\u0d23\u0d02 \u0d36\u0d30\u0d23\u0d02 \u0d15\u0d30\u0d35\u0d3e\u0d23\u0d3f \u0d28\u0d24\u0d3e\u0d2e\u0d30\u0d35\u0d3e\u0d23\u0d3f \u0d28\u0d3f\u0d35\u0d3e\u0d38\u0d3f \u0d36\u0d3f\u0d35\u0d47\n\u0d1c\u0d2f \u0d1c\u0d2f \u0d39\u0d47 \u0d2e\u0d39\u0d3f\u0d37\u0d3e\u0d38\u0d41\u0d30\u0d2e\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d30\u0d2e\u0d4d\u0d2f\u0d15\u0d2a\u0d30\u0d4d\u0d26\u0d3f\u0d28\u0d3f \u0d36\u0d48\u0d32\u0d38\u0d41\u0d24\u0d47 \u0965 \u0d68\u0d67 \u0965", "iast": "kanakalsatkalasindhujalairanu\u1e63i\u00f1cinu te gu\u1e47ara\u1e45gabhuvam\nbhajati sa ki\u1e43 na \u015bac\u012bkucakumbhata\u1e6d\u012bparirambhasukh\u0101nuratam |\ntava cara\u1e47a\u1e43 \u015bara\u1e47a\u1e43 karav\u0101\u1e47i nat\u0101marav\u0101\u1e47i niv\u0101si \u015bive\njaya jaya he mahi\u1e63\u0101suramardini ramyakapardini \u015bailasute || 21 ||"},
        draftTranslation: "Whoever bathes Your sanctum with golden waters and worships You with pure devotion attains all celestial glory and divine peace. O Auspicious Mother, refuge of the gods, I surrender unto Your sacred lotus feet! Victory to You, O Slayer of Mahishasura!",
        translationStatus: "DRAFT",
        isApproved: false,
      ),
    ],
  ),
