    verses: [
      Verse(
        verseNumber: 1,
        devanagariText: "\u0924\u0924\u094b \u092f\u0941\u0926\u094d\u0927\u092a\u0930\u093f\u0936\u094d\u0930\u093e\u0928\u094d\u0924\u0902 \u0938\u092e\u0930\u0947 \u091a\u093f\u0928\u094d\u0924\u092f\u093e \u0938\u094d\u0925\u093f\u0924\u092e\u094d \u0965 \u0967 \u0965",
        iastText: "tato yuddhapari\u015br\u0101nta\u1e43 samare cintay\u0101 sthitam || 1 ||",
        meter: "",
        transliterations: {"telugu": "\u0c24\u0c24\u0c4b \u0c2f\u0c41\u0c26\u0c4d\u0c27\u0c2a\u0c30\u0c3f\u0c36\u0c4d\u0c30\u0c3e\u0c28\u0c4d\u0c24\u0c02 \u0c38\u0c2e\u0c30\u0c47 \u0c1a\u0c3f\u0c28\u0c4d\u0c24\u0c2f\u0c3e \u0c38\u0c4d\u0c25\u0c3f\u0c24\u0c2e\u0c4d \u0965 \u0c67 \u0965", "tamil": "\u0ba4\u0ba4\u0bcb \u0baf\u0bc1\u0ba4\u0bcd\u0ba4\u0baa\u0bb0\u0bbf\u0bb6\u0bcd\u0bb0\u0bbe\u0ba8\u0bcd\u0ba4\u0bae\u0bcd \u0bb8\u0bae\u0bb0\u0bc7 \u0b9a\u0bbf\u0ba8\u0bcd\u0ba4\u0baf\u0bbe \u0bb8\u0bcd\u0ba4\u0bbf\u0ba4\u0bae\u0bcd \u0965 \u0be7 \u0965", "kannada": "\u0ca4\u0ca4\u0ccb \u0caf\u0cc1\u0ca6\u0ccd\u0ca7\u0caa\u0cb0\u0cbf\u0cb6\u0ccd\u0cb0\u0cbe\u0ca8\u0ccd\u0ca4\u0c82 \u0cb8\u0cae\u0cb0\u0cc7 \u0c9a\u0cbf\u0ca8\u0ccd\u0ca4\u0caf\u0cbe \u0cb8\u0ccd\u0ca5\u0cbf\u0ca4\u0cae\u0ccd \u0965 \u0ce7 \u0965", "malayalam": "\u0d24\u0d24\u0d4b \u0d2f\u0d41\u0d26\u0d4d\u0d27\u0d2a\u0d30\u0d3f\u0d36\u0d4d\u0d30\u0d3e\u0d28\u0d4d\u0d24\u0d02 \u0d38\u0d2e\u0d30\u0d47 \u0d1a\u0d3f\u0d28\u0d4d\u0d24\u0d2f\u0d3e \u0d38\u0d4d\u0d25\u0d3f\u0d24\u0d2e\u0d4d \u0965 \u0d67 \u0965"},
        draftTranslation: null,
        translationStatus: "IN_PROGRESS",
        isApproved: false,
      ),
      Verse(
        verseNumber: 2,
        devanagariText: "\u0906\u0926\u093f\u0924\u094d\u092f\u0902 \u0938\u0930\u094d\u0935\u092d\u0942\u0924\u093e\u0928\u093e\u0902 \u0928\u092e\u0938\u094d\u0915\u0941\u0930\u0941 \u0926\u093f\u0935\u093e\u0915\u0930\u092e\u094d \u0965 \u0968 \u0965",
        iastText: "\u0101ditya\u1e43 sarvabh\u016bt\u0101n\u0101\u1e43 namaskuru div\u0101karam || 2 ||",
        meter: "",
        transliterations: {"telugu": "\u0c06\u0c26\u0c3f\u0c24\u0c4d\u0c2f\u0c02 \u0c38\u0c30\u0c4d\u0c35\u0c2d\u0c42\u0c24\u0c3e\u0c28\u0c3e\u0c02 \u0c28\u0c2e\u0c38\u0c4d\u0c15\u0c41\u0c30\u0c41 \u0c26\u0c3f\u0c35\u0c3e\u0c15\u0c30\u0c2e\u0c4d \u0965 \u0c68 \u0965", "tamil": "\u0b86\u0ba4\u0bbf\u0ba4\u0bcd\u0baf\u0bae\u0bcd \u0bb8\u0bb0\u0bcd\u0bb5\u0baa\u0bc2\u0ba4\u0bbe\u0ba8\u0bbe\u0bae\u0bcd \u0ba8\u0bae\u0bb8\u0bcd\u0b95\u0bc1\u0bb0\u0bc1 \u0ba4\u0bbf\u0bb5\u0bbe\u0b95\u0bb0\u0bae\u0bcd \u0965 \u0be8 \u0965", "kannada": "\u0c86\u0ca6\u0cbf\u0ca4\u0ccd\u0caf\u0c82 \u0cb8\u0cb0\u0ccd\u0cb5\u0cad\u0cc2\u0ca4\u0cbe\u0ca8\u0cbe\u0c82 \u0ca8\u0cae\u0cb8\u0ccd\u0c95\u0cc1\u0cb0\u0cc1 \u0ca6\u0cbf\u0cb5\u0cbe\u0c95\u0cb0\u0cae\u0ccd \u0965 \u0ce8 \u0965", "malayalam": "\u0d06\u0d26\u0d3f\u0d24\u0d4d\u0d2f\u0d02 \u0d38\u0d30\u0d4d\u0d35\u0d2d\u0d42\u0d24\u0d3e\u0d28\u0d3e\u0d02 \u0d28\u0d2e\u0d38\u0d4d\u0d15\u0d41\u0d30\u0d41 \u0d26\u0d3f\u0d35\u0d3e\u0d15\u0d30\u0d2e\u0d4d \u0965 \u0d68 \u0965"},
